create or replace materialized view FLASH_SUMMARY_COMP_TIME_INTERVAL(
	TIME_INTERVAL,
	BUSINESS_DATE,
	CALENDAR_DT,
	FISCAL_YEAR_START_DT,
	FISCAL_QUARTER_START_DT,
	FISCAL_PERIOD_START_DT,
	FISCAL_WEEK_START_DT
) as

SELECT 
'CY' AS TIME_INTERVAL, 
CALENDAR_DT AS BUSINESS_DATE,
CALENDAR_DT,
FISCAL_YEAR_START_DT,
FISCAL_QUARTER_START_DT,
FISCAL_PERIOD_START_DT,
FISCAL_WEEK_START_DT
FROM IDS_DEV.INT_REF.COMP_CALENDAR

UNION ALL

SELECT 
'FISC1Y' AS TIME_INTERVAL,
CALENDAR_DT AS BUSINESS_DATE, 
FISCAL_1YR_COMP_DT AS CALENDAR_DT,
FISCAL_1YR_COMP_YEAR_DT AS FISCAL_YEAR_START_DT,
FISCAL_1YR_COMP_QUARTER_DT AS FISCAL_QUARTER_START_DT,
FISCAL_1YR_COMP_PERIOD_DT AS FISCAL_PERIOD_START_DT,
FISCAL_1YR_COMP_WEEK_DT AS FISCAL_WEEK_START_DT
FROM IDS_DEV.INT_REF.COMP_CALENDAR

UNION ALL

SELECT 
'CAL1Y' AS TIME_INTERVAL, 
CALENDAR_DT AS BUSINESS_DATE,
CALENDAR_1YR_COMP_DT AS CALENDAR_DT,
CALENDAR_1YR_COMP_YEAR_DT AS FISCAL_YEAR_START_DT,
CALENDAR_1YR_COMP_QUARTER_DT AS FISCAL_QUARTER_START_DT,
CALENDAR_1YR_COMP_PERIOD_DT AS FISCAL_PERIOD_START_DT,
CALENDAR_1YR_COMP_WEEK_DT AS FISCAL_WEEK_START_DT
FROM IDS_DEV.INT_REF.COMP_CALENDAR


UNION ALL

SELECT 
'CAL2Y' AS TIME_INTERVAL, 
CALENDAR_DT AS BUSINESS_DATE,
CALENDAR_2YR_COMP_DT AS CALENDAR_DT,
CALENDAR_2YR_COMP_YEAR_DT AS FISCAL_YEAR_START_DT,
CALENDAR_2YR_COMP_QUARTER_DT AS FISCAL_QUARTER_START_DT,
CALENDAR_2YR_COMP_PERIOD_DT AS FISCAL_PERIOD_START_DT,
CALENDAR_2YR_COMP_WEEK_DT AS FISCAL_WEEK_START_DT
FROM IDS_DEV.INT_REF.COMP_CALENDAR


UNION ALL

SELECT 
'CAL3Y' AS TIME_INTERVAL, 
CALENDAR_DT AS BUSINESS_DATE,
CALENDAR_3YR_COMP_DT AS CALENDAR_DT,
CALENDAR_3YR_COMP_YEAR_DT AS FISCAL_YEAR_START_DT,
CALENDAR_3YR_COMP_QUARTER_DT AS FISCAL_QUARTER_START_DT,
CALENDAR_3YR_COMP_PERIOD_DT AS FISCAL_PERIOD_START_DT,
CALENDAR_3YR_COMP_WEEK_DT AS FISCAL_WEEK_START_DT
FROM IDS_DEV.INT_REF.COMP_CALENDAR

;
create TABLE IF NOT EXISTS FLYWAY_SCHEMA_HISTORY (
	INSTALLED_RANK NUMBER(38,0) NOT NULL,
	VERSION VARCHAR(50),
	DESCRIPTION VARCHAR(200),
	TYPE VARCHAR(20) NOT NULL,
	SCRIPT VARCHAR(1000) NOT NULL,
	CHECKSUM NUMBER(38,0),
	INSTALLED_BY VARCHAR(100) NOT NULL,
	INSTALLED_ON TIMESTAMP_LTZ(9) NOT NULL DEFAULT CURRENT_TIMESTAMP(),
	EXECUTION_TIME NUMBER(38,0) NOT NULL,
	SUCCESS BOOLEAN NOT NULL,
	primary key (INSTALLED_RANK)
);
create view IF NOT EXISTS DAILY_DAY_PART_FLASH_SALES_FACT_BV(
	STORE_ID COMMENT 'Number that uniquely identifies the Store',
	BUSINESS_DT COMMENT 'Date of the Flash Sales',
	BRAND_DAY_PART_NM COMMENT 'This is the Name of the Date Part',
	BRAND_ID COMMENT 'Brand for the Order\n',
	CHANNEL_ID COMMENT 'This is a unique Channel Identifier',
	FULFILLMENT_CHANNEL_NM,
	IRB_DAY_PART_NM COMMENT 'The Inspire Brands Daypart',
	CLOSED_TM COMMENT 'time the ticket was closed',
	TRX_CNT COMMENT 'Records whether order has been voided or not. (previously called GrossQuantity)',
	NET_SALES_AMT COMMENT 'Net Amount for the sales',
	LOAD_TYP COMMENT 'Indicates whether data is part of a large historical data pull or was added from a smaller data pull (daily, weekly etc.)',
	SOURCE_SYSTEM_NM COMMENT 'The POS System used to load the transaction  information',
	LOAD_ID COMMENT 'Indicates whether data is part of a large historical data pull or was added from a smaller data pull (daily, weekly etc.) \n',
	LOAD_DTTM COMMENT 'The Date/Datetime the Record was Inserted',
	UPDATE_ID COMMENT 'This is the User Identifier of the Person or Process that Updated the Table',
	UPDATE_DTTM COMMENT 'The Date/Datetime the Record was Inserted'
) as 
SELECT FACT.STORE_ID,FACT.BUSINESS_DT,FACT.BRAND_DAY_PART_NM,FACT.BRAND_ID,FACT.CHANNEL_ID,FACT.IRB_DAY_PART_NM,FACT.CLOSED_TM,CD.FULFILLMENTCHANNELNAME,FACT.TRX_CNT,FACT.NET_SALES_AMT,FACT.LOAD_TYP,FACT.SOURCE_SYSTEM_NM,FACT.LOAD_ID,FACT.LOAD_DTTM,FACT.UPDATE_ID,FACT.UPDATE_DTTM
FROM IDS_DEV.DATASTORE.DAILY_DAY_PART_FLASH_SALES_FACT  FACT LEFT JOIN POLARIS_DEV.SADM.CHANNEL_DIM CD ON  FACT.CHANNEL_ID = CD.CHANNELID;
create view IF NOT EXISTS LOYALTY_ORDER_FACT_V(
	TRANSACTION_ID COMMENT 'Unique ID for loyalty transaction',
	CUSTOMER_KEY COMMENT 'This is a sorrogate key for the Customer Dimension',
	STORE_KEY,
	BUSINESS_DATE_KEY,
	EMPLOYEE_KEY,
	ORDER_ID COMMENT 'OrderID uniquely defines each order for each brand',
	EMPLOYEE_ID COMMENT 'ID of the employee who is serving a customer or who took the order',
	MEMBER_ID COMMENT 'A unique ID that is internally generated any time a customer joins the loyalty program/system.',
	STORE_ID COMMENT 'Store Number that uniquely identifies the store ( from FRM)',
	BRAND_ID COMMENT 'Brand associated with the transaction ',
	BUSINESS_DT COMMENT 'The Date of the Transaction',
	EMPLOYEE_NM COMMENT 'Name of the staff Member serving the customer',
	CHECK_NBR COMMENT 'This is an incremental number that starts at one each business day to record customer order. Number restarts from one each day.',
	MEMBER_CARD_NBR COMMENT 'A loyalty number that is used to link a transaction to a customer’s loyalty profile',
	DOLLAR_NET_VALUE_AMT COMMENT 'Net Amount in dollar paid by the customer',
	ELIGIBLE_REVENUE_AMT COMMENT 'Amount that is eligible for loyalty rewards. There could be certain items within a transaction that don’t qualify for loyalty rewards.\n\n',
	ATTACHMENT_METHOD_TYP COMMENT 'Channel through which loyalty rewards were linked to a profile. Ex: At store, POS or through customer service for missing transaction.',
	TRANSACTION_STATUS_TYP COMMENT 'Transaction status, if the transaction is pending or closed',
	MEMBER_PHONE_NBR COMMENT 'Phone number of the member collected during transaction',
	REASON_CD COMMENT 'Reason why certain items disqualified from earning loyalty rewards.',
	MIN_DAY_PART_ID COMMENT 'Breakfast, Lunch, Dinner are different Dayparts for restaurants. If an item is part of multiple dayparts, then the earliest daypart is considered for this field',
	MAX_DAY_PART_ID COMMENT 'Breakfast ,Lunch, Dinner are different Dayparts for restaurants. If an item is part of multiple dayparts, then the latest daypart is considered for this field',
	SUSPENDED_TRANSACTION_ID COMMENT 'A ID generated when a Loyalty transaction is suspended.\n\nMostly valid for BWWs',
	SUSPENDED_TRANSACTION_STATUS_IND COMMENT 'The Status to indicate if the suspension is active or not.\n\nMostly valid for BWWs',
	SOURCE_SYSTEM_NM COMMENT 'The POS System used to load the transaction  information\n',
	LOAD_TYP COMMENT 'Indicates whether data is part of a large historical data pull or was added from a smaller data pull (daily, weekly etc.) \n',
	LOAD_ID COMMENT ' Indicates whether data is part of a large historical data pull or was added from a smaller data pull (daily, weekly etc.) \n',
	LOAD_DTTM COMMENT '\nThe Date/Datetime the Record was Inserted',
	UPDATE_ID COMMENT 'This is the User Identifier of the Person or Process that Updated the Table',
	UPDATE_DTTM COMMENT 'The Date/Datetime the Record was Updated'
) as 
SELECT LOYALTY_ORDER_FACT.TRANSACTION_ID,LOYALTY_ORDER_FACT.CUSTOMER_KEY,LOYALTY_ORDER_FACT.STORE_KEY,LOYALTY_ORDER_FACT.BUSINESS_DATE_KEY,LOYALTY_ORDER_FACT.EMPLOYEE_KEY,LOYALTY_ORDER_FACT.ORDER_ID,LOYALTY_ORDER_FACT.EMPLOYEE_ID,LOYALTY_ORDER_FACT.MEMBER_ID,LOYALTY_ORDER_FACT.STORE_ID,LOYALTY_ORDER_FACT.BRAND_ID,LOYALTY_ORDER_FACT.BUSINESS_DT,LOYALTY_ORDER_FACT.EMPLOYEE_NM,LOYALTY_ORDER_FACT.CHECK_NBR,LOYALTY_ORDER_FACT.MEMBER_CARD_NBR,LOYALTY_ORDER_FACT.DOLLAR_NET_VALUE_AMT,LOYALTY_ORDER_FACT.ELIGIBLE_REVENUE_AMT,LOYALTY_ORDER_FACT.ATTACHMENT_METHOD_TYP,LOYALTY_ORDER_FACT.TRANSACTION_STATUS_TYP,LOYALTY_ORDER_FACT.MEMBER_PHONE_NBR,LOYALTY_ORDER_FACT.REASON_CD,LOYALTY_ORDER_FACT.MIN_DAY_PART_ID,LOYALTY_ORDER_FACT.MAX_DAY_PART_ID,LOYALTY_ORDER_FACT.SUSPENDED_TRANSACTION_ID,LOYALTY_ORDER_FACT.SUSPENDED_TRANSACTION_STATUS_IND,LOYALTY_ORDER_FACT.SOURCE_SYSTEM_NM,LOYALTY_ORDER_FACT.LOAD_TYP,LOYALTY_ORDER_FACT.LOAD_ID,LOYALTY_ORDER_FACT.LOAD_DTTM,LOYALTY_ORDER_FACT.UPDATE_ID,LOYALTY_ORDER_FACT.UPDATE_DTTM
FROM IDS_DEV.DATASTORE.LOYALTY_ORDER_FACT ;
