create view IF NOT EXISTS ORDERED_ITEMS_BY_CUSTOMER_VAPP(
	CUSTOMER,
	DATE_UTC,
	DATE_LOCAL,
	STORE_ID,
	BRAND,
	IDP_ORDER_ID,
	PRODUCT_ID,
	PRODUCT_CATEGORY,
	PRODUCT_NAME,
	COUNT
) as (
    WITH RECURSIVE PRODUCT_QUANTITY AS (
        SELECT
            DIGITAL_ORDER_ID,
            BRAND_ID,
            BUSINESS_DT,
            LINE_ITEM_ID AS ITEM_ID,
            LINE_ITEM_PRODUCT_CATEGORY_NM AS PRODUCT_CATEGORY,
            LINE_ITEM_DESC AS PRODUCT_DESCRIPTION,
            LINE_ITEM_QTY AS QTY
        FROM
            IDS_DEV.TXN.DIGITAL_ORDER_LINE
        UNION ALL
        SELECT
            C.DIGITAL_ORDER_ID AS DIGITAL_ORDER_ID,
            C.BRAND_ID AS BRAND_ID,
            C.BUSINESS_DT AS BUSINESS_DT,
            C.CHILD_ITEM_ID AS ITEM_ID,
            C.CHILD_ITEM_PRODUCT_CATEGORY_NM AS PRODUCT_CATEGORY,
            C.CHILD_ITEM_DESC AS PRODUCT_DESCRIPTION,
            (L.QTY * C.CHILD_ITEM_QTY) AS QTY
        FROM
            IDS_DEV.TXN.DIGITAL_ORDER_LINE_CHILD AS C
            JOIN PRODUCT_QUANTITY AS L
                ON L.DIGITAL_ORDER_ID = C.DIGITAL_ORDER_ID
                AND L.ITEM_ID = C.CHILD_PARENT_ITEM_ID
                AND L.BUSINESS_DT = C.BUSINESS_DT
                AND L.BRAND_ID = C.BRAND_ID
    )
    SELECT
        COALESCE(D.CUST_EMAIL, D.CUST_PHONE_NBR) AS CUSTOMER,
        D.BUSINESS_DTTM AS DATE_UTC,
        ITPRCS_DEV.CSO.CONVERT_TIMESTAMP_FROM_UTC_TO_TIMEZONE(D.BUSINESS_DTTM, ANY_VALUE(S.TIMEZONE)) AS DATE_LOCAL,
        LPAD(ANY_VALUE(D.LOC_ID),5,0) AS STORE_ID,
        P.BRAND_ID AS BRAND,
        P.DIGITAL_ORDER_ID AS IDP_ORDER_ID,
        P.ITEM_ID AS PRODUCT_ID,
        ANY_VALUE(P.PRODUCT_CATEGORY) AS PRODUCT_CATEGORY,
        ANY_VALUE(P.PRODUCT_DESCRIPTION) AS PRODUCT_NAME,
        SUM(P.QTY) AS COUNT
    FROM
        PRODUCT_QUANTITY AS P
        JOIN IDS_DEV.TXN.DIGITAL_ORDER AS D
            ON P.DIGITAL_ORDER_ID = D.DIGITAL_ORDER_ID
            AND P.BRAND_ID = D.BRAND_ID
            AND P.BUSINESS_DT = D.BUSINESS_DT
        LEFT JOIN POLARIS_DEV.SHDM.STORE_SCD_DIM AS S
            ON D.LOC_ID::INTEGER = S.STORE_ID::INTEGER
            AND D.BRAND_ID = S.BRAND_ID
            AND P.BUSINESS_DT BETWEEN S.EFFECTIVE_BEGIN_DATE
            AND S.EFFECTIVE_END_DATE
    WHERE
        PRODUCT_CATEGORY LIKE ANY ('Shake', 'Softdrink', 'Kid%Drink', 'Meal', 'Kid%Meal', 'Side', 'Sandwich', 'Wrap', 'Wings', 'Tenders')
    GROUP BY
        P.DIGITAL_ORDER_ID,
        P.ITEM_ID,
        D.BUSINESS_DTTM,
        P.BRAND_ID,
        CUSTOMER
    ORDER BY
        DATE_UTC ASC,
        PRODUCT_CATEGORY
);
create view IF NOT EXISTS ORDER_CHANNEL_V(
	CHANNEL_ID,
	ORDER_CHANNEL_NM,
	FULFILLMENT_CHANNEL_NM,
	ORDER_CHANNEL_HIERARCHY_LEVEL3_NM,
	ORDER_CHANNEL_HIERARCHY_LEVEL2_NM,
	ORDER_CHANNEL_HIERARCHY_LEVEL1_NM,
	FULFILLMENT_CHANNEL_HIERARCHY_L3_NM,
	FULFILLMENT_CHANNEL_HIERARCHY_L2_NM,
	FULFILLMENT_CHANNEL_HIERARCHY_L1_NM,
	SOURCE_SYSTEM_NM,
	HIERARCHY_SOURCE_SYSTEM_NM,
	BRAND_ID,
	CDM_LOAD_DT,
	CDM_UPDATE_DT
) as 
SELECT CHANNEL_DIM.CHANNELID,CHANNEL_DIM.ORDERCHANNELNAME,CHANNEL_DIM.FULFILLMENTCHANNELNAME,CHANNEL_DIM.ORDERCHANNELHIERARCHYNAME_L3,CHANNEL_DIM.ORDERCHANNELHIERARCHYNAME_L2,CHANNEL_DIM.ORDERCHANNELHIERARCHYNAME_L1,CHANNEL_DIM.FULFILLMENTCHANNELHIERARCHYNAME_L3,CHANNEL_DIM.FULFILLMENTCHANNELHIERARCHYNAME_L2,CHANNEL_DIM.FULFILLMENTCHANNELHIERARCHYNAME_L1,CHANNEL_DIM.SOURCE,CHANNEL_DIM.HIERARCHYSOURCE,CHANNEL_DIM.BRANDID,CHANNEL_DIM.CDMLOADDATE,CHANNEL_DIM.CDMUPDATEDATE
FROM POLARIS_DEV.SADM.CHANNEL_DIM;
create view IF NOT EXISTS ORDER_COMBOS_QUANTITY_VAPP(
	CUSTOMER,
	DATE_UTC,
	DATE_LOCAL,
	STORE_ID,
	BRAND,
	IDP_ORDER_ID,
	PRODUCT_ID,
	PRODUCT_CATEGORY,
	PRODUCT_NAME,
	COUNT
) as(
    WITH RECURSIVE PRODUCT_QUANTITY AS (
        SELECT
            DIGITAL_ORDER_ID,
            BRAND_ID,
            BUSINESS_DT,
            LINE_ITEM_ID AS ITEM_ID,
            LINE_ITEM_PRODUCT_CATEGORY_NM AS PRODUCT_CATEGORY,
            LINE_ITEM_DESC AS PRODUCT_DESCRIPTION,
            LINE_ITEM_QTY AS QTY
        FROM
            IDS_DEV.TXN.DIGITAL_ORDER_LINE
        UNION ALL
        SELECT
            C.DIGITAL_ORDER_ID AS DIGITAL_ORDER_ID,
            C.BRAND_ID AS BRAND_ID,
            C.BUSINESS_DT AS BUSINESS_DT,
            C.CHILD_ITEM_ID AS ITEM_ID,
            C.CHILD_ITEM_PRODUCT_CATEGORY_NM AS PRODUCT_CATEGORY,
            C.CHILD_ITEM_DESC AS PRODUCT_DESCRIPTION,
            (L.QTY * C.CHILD_ITEM_QTY) AS QTY
        FROM
            IDS_DEV.TXN.DIGITAL_ORDER_LINE_CHILD C
            JOIN PRODUCT_QUANTITY L ON L.DIGITAL_ORDER_ID = C.DIGITAL_ORDER_ID
            AND L.ITEM_ID = C.CHILD_PARENT_ITEM_ID
            AND L.BUSINESS_DT = C.BUSINESS_DT
            AND L.BRAND_ID = C.BRAND_ID
    )
    SELECT
        COALESCE(D.CUST_EMAIL, D.CUST_PHONE_NBR) AS CUSTOMER,
        D.BUSINESS_DTTM AS DATE_UTC,
        ITPRCS_DEV.CSO.CONVERT_TIMESTAMP_FROM_UTC_TO_TIMEZONE(D.BUSINESS_DTTM, ANY_VALUE(S.TIMEZONE)) AS DATE_LOCAL,
        LPAD(ANY_VALUE(D.LOC_ID),5,0) AS STORE_ID,
        P.BRAND_ID AS BRAND,
        P.DIGITAL_ORDER_ID AS IDP_ORDER_ID,
        P.ITEM_ID AS PRODUCT_ID,
        ANY_VALUE(P.PRODUCT_CATEGORY) AS PRODUCT_CATEGORY,
        ANY_VALUE(P.PRODUCT_DESCRIPTION) AS PRODUCT_NAME,
        SUM(P.QTY) AS COUNT
    FROM
        PRODUCT_QUANTITY AS P
        JOIN IDS_DEV.TXN.DIGITAL_ORDER AS D ON P.DIGITAL_ORDER_ID = D.DIGITAL_ORDER_ID
        AND P.BRAND_ID = D.BRAND_ID
        AND P.BUSINESS_DT = D.BUSINESS_DT
        LEFT JOIN POLARIS_DEV.SHDM.STORE_SCD_DIM S ON D.LOC_ID::INTEGER = S.STORE_ID::INTEGER
        AND D.BRAND_ID = S.BRAND_ID
        AND P.BUSINESS_DT BETWEEN S.EFFECTIVE_BEGIN_DATE
        AND S.EFFECTIVE_END_DATE
    WHERE
        PRODUCT_CATEGORY = 'Meal'
    GROUP BY
        P.DIGITAL_ORDER_ID,
        P.ITEM_ID,
        D.BUSINESS_DTTM,
        P.BRAND_ID,
        CUSTOMER
);
