	OFFER_MISC10,
	PRODUCT_MISC1,
	PRODUCT_MISC2,
	PRODUCT_MISC3,
	PRODUCT_MISC4,
	PRODUCT_MISC5,
	PRODUCT_MISC6,
	PRODUCT_MISC7,
	PRODUCT_MISC8,
	PRODUCT_MISC9,
	PRODUCT_MISC10,
	OFFER_HIERARCHY_ID
) as
SELECT 
    ORDER_ID ORDER_ID,
    ORDER_LINE_ID ORDERLINE_ID,
   -- TO_CHAR(BUSINESS_DT,'YYYY-MM-DD') as ORDER_DT,
   -- TO_CHAR(TO_DATE(BUSINESS_DT,'YYYYMMDD'),'YYYY-MM-DD')  as ORDER_DT,
	 TO_CHAR( TO_DATE(BUSINESS_DT,'YYYYMMDD'),'YYYY-MM-DD') as ORDER_DT,
     BUSINESS_DT AS ORDER_DT_KEY,
    TIME_KEY ORDER_TM,
    ol.STORE_ID STORE_ID,
    st.DMA_CODE DMA_CD,
    st.DMA_NAME DMA_NM,
    ol.CHANNEL_ID CHANNEL_ID,
    ch.ORDERCHANNELNAME ORDER_CHANNEL_NM,
    ORDERCHANNELHIERARCHYNAME_L3 LEVEL3_ORDER_CHANNEL_HIERARCHY_NM,
    ORDERCHANNELHIERARCHYNAME_L2 LEVEL2_ORDER_CHANNEL_HIERARCHY_NM,
    ORDERCHANNELHIERARCHYNAME_L1 LEVEL1_ORDER_CHANNEL_HIERARCHY_NM,
    ch.FULFILLMENTCHANNELNAME FULFILLMENT_CHANNEL_NM ,
    FULFILLMENTCHANNELHIERARCHYNAME_L3 LEVEL3_FULFILLMENT_CHANNEL_HIERARCHY_NM,
    FULFILLMENTCHANNELHIERARCHYNAME_L2 LEVEL2_FULFILLMENT_CHANNEL_HIERARCHY_NM,
    FULFILLMENTCHANNELHIERARCHYNAME_L1 LEVEL1_FULFILLMENT_CHANNEL_HIERARCHY_NM,
    EMPLOYEE_ID EMPLOYEE_ID,
    MANAGER_ID MANAGER_ID,
    REGISTER_ID REGISTER_ID,
    TAX_ID TAX_ID,
    CASE WHEN MODIFIER_IND = 'Y' THEN 'True'
         WHEN MODIFIER_IND = 'N' THEN 'False' END AS MODIFIER_IND,
    TAX_EXEMPT_ID TAXEXEMPT_ID,
    SEAT_NBR SEAT_NBR,
    ol.MDM_ITEM_ID MDM_ITEM_ID,
    mc.SOURCESYSTEMID SOURCE_SYSTEM_ID,
    mc.ITEMNAME ITEM_NM,
    mc.MDMITEMTYPE MDM_ITEM_TYP,
    mc.MDMPRODUCTID MDM_PRODUCT_ID,
    mc.PRODUCTNAME PRODUCT_NM,
    mc.PRODUCTDESC PRODUCT_DESC,
    mc.PRODUCTSTATUS PRODUCT_STATUS_CD,
    mc.TECHNICALSIZE TECHNICAL_SIZE_NBR,
    mc.UNITOFMEASURE UNIT_OF_MEASURE_VAL,
    mc.NONUSASPECIALTY NON_USA_SPECIALTY_IND,
    mc.VEHICLE VEHICLE_NBR,
    mc.ISHOTPRODUCT HOT_PRODUCT_IND,
    mc.ISBREAKFASTPRODUCT BREAKFAST_PRODUCT_IND,
    mc.PRODUCTBRAND PRODUCT_BRAND_NM,
    mc.MENUTYPE MENU_TYP,
    mc.MENUSECTION MENU_SECTION_TYP,
    mc.GBBMEASURE GBB_MEASURE_VAL,
    mc.ISCOLDSPACEREQUIRED COLD_SPACE_REQUIRED_IND,
    mc.ISFRYERREQUIRED FRYER_REQUIRED_IND,
    mc.PRODUCTHIERARCHYNODE PRODUCT_HIERARCHY_ID,
    mc.L5PRODUCTHIERARCHY LEVEL5_PRODUCT_HIERARCHY_NM,
    mc.L4PRODUCTHIERARCHY LEVEL4_PRODUCT_HIERARCHY_NM,
    mc.L3PRODUCTHIERARCHY LEVEL3_PRODUCT_HIERARCHY_NM,
    mc.L2PRODUCTHIERARCHY LEVEL2_PRODUCT_HIERARCHY_NM,
    mc.L1PRODUCTHIERARCHY LEVEL1_PRODUCT_HIERARCHY_NM,
    mc.MDMOFFERID MDM_OFFER_ID,
    mc.OFFERNAME OFFER_NM,
    mc.OFFERDESC OFFER_DESC,
    mc.OFFERCATEGORY OFFER_CAT,
    mc.OFFERTYPE OFFER_TYP,
    mc.L5OFFERHIERARCHY LEVEL5_OFFER_HIERARCHY_NM,
    mc.L4OFFERHIERARCHY LEVEL4_OFFER_HIERARCHY_NM,
    mc.L3OFFERHIERARCHY LEVEL3_OFFER_HIERARCHY_NM,
    mc.L2OFFERHIERARCHY LEVEL2_OFFER_HIERARCHY_NM,
    mc.L1OFFERHIERARCHY LEVEL1_OFFER_HIERARCHY_NM,
    ol.MDM_PARENT_ITEM_ID MDM_PARENT_ITEM_ID,
    mp.SOURCESYSTEMID PARENT_SOURCE_SYSTEM_ID,
    mp.ITEMNAME PARENT_ITEM_NM,
    mp.MDMITEMTYPE MDM_PARENT_ITEM_TYP,
    SOURCE_GROSS_QTY,
    SOURCE_GROSS_AMT,
    DISCOUNT_CD,
	DISCOUNT_NM,
	--SOURCE_DISCOUNT_AMT,
	SOURCE_DISCOUNT_TYP,
    SOURCE_DISCOUNT_AMT,
	SOURCE_NET_AMT,
    DERIVED_GROSS_QTY DERIVED_GROSS_QTY,
    PRICE_AMT RETAIL_PRICE_AMT,
    --DISCOUNTPRICE DISCOUNT_PRICE_AMT,
    DERIVED_GROSS_AMT DERIVED_GROSS_AMT,
    DERIVED_NET_AMT DERIVED_NET_AMT,
    DERIVED_DISCOUNT_AMT,
    TAX_AMT TAX_AMT,
    --INCLUSIVETAX INCLUSIVE_TAX_AMT,
    CASE WHEN CLEARED_IND = 'Y' THEN 'True'
 	     WHEN CLEARED_IND = 'N' THEN 'False' END AS CLEARED_IND,
    CASE WHEN DELETED_IND = 'Y' THEN 'True' 
	     WHEN DELETED_IND = 'N' THEN 'False' END AS DELETED_IND,
    CASE WHEN VOID_IND = 'Y' THEN 'True'
     	 WHEN VOID_IND = 'N' THEN 'False' END AS VOIDED_IND,
    INVENTORY_IND INVENTORY_IND,
    ol.ALTERNATE1_ORDER_ID,
    ol.SOURCE_SYSTEM_NM SOURCE_NM,
    ol.BRAND_ID BRAND_ID,
    ol.Load_ID LOAD_DT,
    ol.LOAD_DTTM LAST_UPDATED_DTTM,
    MO.MISC1 OFFER_MISC1,
    MO.MISC2 OFFER_MISC2,
    MO.MISC3 OFFER_MISC3,
    MO.MISC4 OFFER_MISC4,
    MO.MISC5 OFFER_MISC5,
    MO.MISC6 OFFER_MISC6,
    MO.MISC7 OFFER_MISC7,
    MO.MISC8 OFFER_MISC8,
    MO.MISC9 OFFER_MISC9,
    MO.MISC10 OFFER_MISC10,
	MPR.MISC1 PRODUCT_MISC1,
	MPR.MISC2 PRODUCT_MISC2,
	MPR.MISC3 PRODUCT_MISC3,
	MPR.MISC4 PRODUCT_MISC4,
	MPR.MISC5 PRODUCT_MISC5,
	MPR.MISC6 PRODUCT_MISC6,
	MPR.MISC7 PRODUCT_MISC7,
	MPR.MISC8 PRODUCT_MISC8,
	MPR.MISC9 PRODUCT_MISC9,
	MPR.MISC10 PRODUCT_MISC10,
    MO.OFFERHIERARCHYID OFFER_HIERARCHY_ID
 FROM
    IDS_DEV.TXN_BV.ORDER_LINE_BV ol
    LEFT JOIN POLARIS_DEV.SHDM.STORE_DIM st ON ol.STORE_ID = st.STORE_ID AND st.BRAND_ID = ol.BRAND_ID
    LEFT JOIN POLARIS_DEV.SADM.CHANNEL_DIM ch ON ol.CHANNEL_ID = ch.CHANNELID
    LEFT JOIN POLARIS_DEV.SADM.MENU_DIM mc ON ol.MDM_Item_Id = mc.MDMItemId
    LEFT JOIN POLARIS_DEV.SADM.MENU_DIM mp ON ol.MDM_Parent_Item_Id = mp.MDMItemId
	LEFT JOIN IDS_DEV.MENU_BV.MENU_OFFER_PLR_BV MO ON MO.MDMOFFERID = ol.MDM_ITEM_ID
	LEFT JOIN IDS_DEV.MENU_BV.MENU_PRODUCT_PLR_BV MPR ON MPR.MDMPRODUCTID = ol.MDM_ITEM_ID;
create view IF NOT EXISTS ORDER_DRINKS_QUANTITY_VAPP(
	CUSTOMER,
	DATE_UTC,
	DATE_LOCAL,
	STORE_ID,
	BRAND,
	IDP_ORDER_ID,
	PRODUCT_ID,
	PRODUCT_CATEGORY,
	PRODUCT_NAME,
	COUNT
) as (
    WITH RECURSIVE PRODUCT_QUANTITY AS (
        SELECT
            DIGITAL_ORDER_ID,
            BRAND_ID,
            BUSINESS_DT,
            LINE_ITEM_ID AS ITEM_ID,
            LINE_ITEM_PRODUCT_CATEGORY_NM AS PRODUCT_CATEGORY,
            LINE_ITEM_DESC AS PRODUCT_DESCRIPTION,
            LINE_ITEM_QTY AS QTY
        FROM
            IDS_DEV.TXN.DIGITAL_ORDER_LINE
        UNION ALL
        SELECT
            C.DIGITAL_ORDER_ID AS DIGITAL_ORDER_ID,
            C.BRAND_ID AS BRAND_ID,
            C.BUSINESS_DT AS BUSINESS_DT,
            C.CHILD_ITEM_ID AS ITEM_ID,
            C.CHILD_ITEM_PRODUCT_CATEGORY_NM AS PRODUCT_CATEGORY,
            C.CHILD_ITEM_DESC AS PRODUCT_DESCRIPTION,
            (L.QTY * C.CHILD_ITEM_QTY) AS QTY
        FROM
            IDS_DEV.TXN.DIGITAL_ORDER_LINE_CHILD AS C
            JOIN PRODUCT_QUANTITY AS L
                ON L.DIGITAL_ORDER_ID = C.DIGITAL_ORDER_ID
                AND L.ITEM_ID = C.CHILD_PARENT_ITEM_ID
                AND L.BUSINESS_DT = C.BUSINESS_DT
                AND L.BRAND_ID = C.BRAND_ID
    )
    SELECT
        COALESCE(D.CUST_EMAIL, D.CUST_PHONE_NBR) AS CUSTOMER,
        D.BUSINESS_DTTM AS DATE_UTC,
        ITPRCS_DEV.CSO.CONVERT_TIMESTAMP_FROM_UTC_TO_TIMEZONE(D.BUSINESS_DTTM, ANY_VALUE(S.TIMEZONE)) AS DATE_LOCAL,
        LPAD(ANY_VALUE(D.LOC_ID),5,0) AS STORE_ID,
        P.BRAND_ID AS BRAND,
        P.DIGITAL_ORDER_ID AS IDP_ORDER_ID,
        P.ITEM_ID AS PRODUCT_ID,
        ANY_VALUE(P.PRODUCT_CATEGORY) AS PRODUCT_CATEGORY,
        ANY_VALUE(P.PRODUCT_DESCRIPTION) AS PRODUCT_NAME,
        SUM(P.QTY) AS COUNT
    FROM
        PRODUCT_QUANTITY AS P
        JOIN IDS_DEV.TXN.DIGITAL_ORDER AS D
            ON P.DIGITAL_ORDER_ID = D.DIGITAL_ORDER_ID
            AND P.BRAND_ID = D.BRAND_ID
            AND P.BUSINESS_DT = D.BUSINESS_DT
        LEFT JOIN POLARIS_DEV.SHDM.STORE_SCD_DIM AS S
            ON D.LOC_ID::INTEGER = S.STORE_ID::INTEGER
            AND D.BRAND_ID = S.BRAND_ID
            AND P.BUSINESS_DT BETWEEN S.EFFECTIVE_BEGIN_DATE
            AND S.EFFECTIVE_END_DATE
    WHERE
        PRODUCT_CATEGORY LIKE ANY ('Shake', 'Softdrink', 'Kid%Drink')
    GROUP BY
        P.DIGITAL_ORDER_ID,
        P.ITEM_ID,
        D.BUSINESS_DTTM,
        P.BRAND_ID,
        CUSTOMER
);
create view IF NOT EXISTS ORDER_ENTREES_QUANTITY_VAPP(
	CUSTOMER,
	DATE_UTC,
	DATE_LOCAL,
	STORE_ID,
	BRAND,
	IDP_ORDER_ID,
	PRODUCT_ID,
	PRODUCT_CATEGORY,
	PRODUCT_NAME,
	COUNT
) as (
    WITH RECURSIVE PRODUCT_QUANTITY AS (
        SELECT 
            DIGITAL_ORDER_ID,
            BRAND_ID,
            BUSINESS_DT,
            LINE_ITEM_ID AS ITEM_ID,
            LINE_ITEM_PRODUCT_CATEGORY_NM AS PRODUCT_CATEGORY,
            LINE_ITEM_DESC AS PRODUCT_DESCRIPTION,
            LINE_ITEM_QTY AS QTY
        FROM IDS_DEV.TXN."DIGITAL_ORDER_LINE"
    
        UNION ALL
    
        SELECT 
            C.DIGITAL_ORDER_ID AS DIGITAL_ORDER_ID,
            C.BRAND_ID AS BRAND_ID,
            C.BUSINESS_DT AS BUSINESS_DT,
            C.CHILD_ITEM_ID AS ITEM_ID,
            C.CHILD_ITEM_PRODUCT_CATEGORY_NM AS PRODUCT_CATEGORY,
            C.CHILD_ITEM_DESC AS PRODUCT_DESCRIPTION,
            (L.QTY * C.CHILD_ITEM_QTY) AS QTY
        FROM IDS_DEV.TXN."DIGITAL_ORDER_LINE_CHILD" C
        JOIN PRODUCT_QUANTITY L 
            ON L.DIGITAL_ORDER_ID = C.DIGITAL_ORDER_ID 
                AND L.ITEM_ID = C.CHILD_PARENT_ITEM_ID
                AND L.BUSINESS_DT = C.BUSINESS_DT
                AND L.BRAND_ID = C.BRAND_ID
    )
    SELECT
        COALESCE(D.CUST_EMAIL, D.CUST_PHONE_NBR) AS CUSTOMER,
        D.BUSINESS_DTTM AS DATE_UTC,
        ITPRCS_DEV.CSO.CONVERT_TIMESTAMP_FROM_UTC_TO_TIMEZONE(BUSINESS_DTTM, ANY_VALUE(S.TIMEZONE)) AS DATE_LOCAL,
        LPAD(ANY_VALUE(D.LOC_ID), 5, '0') AS STORE_ID,
        P.BRAND_ID AS BRAND,
        P.DIGITAL_ORDER_ID AS IDP_ORDER_ID,
        P.ITEM_ID AS PRODUCT_ID,
        ANY_VALUE(P.PRODUCT_CATEGORY) AS PRODUCT_CATEGORY, 
        ANY_VALUE(P.PRODUCT_DESCRIPTION) AS PRODUCT_NAME,
        SUM(P.QTY) AS COUNT
    FROM PRODUCT_QUANTITY AS P
    JOIN IDS_DEV.TXN."DIGITAL_ORDER" AS D
        ON P.DIGITAL_ORDER_ID = D.DIGITAL_ORDER_ID
        AND P.BRAND_ID = D.BRAND_ID
        AND P.BUSINESS_DT = D.BUSINESS_DT
    LEFT JOIN POLARIS_DEV.SHDM."STORE_SCD_DIM" S
        ON D.LOC_ID::INTEGER = S.STORE_ID::INTEGER
        AND D.BRAND_ID = S.BRAND_ID
        AND P.BUSINESS_DT BETWEEN S.EFFECTIVE_BEGIN_DATE AND S.EFFECTIVE_END_DATE
    WHERE PRODUCT_CATEGORY IN ('Sandwich', 'Wrap', 'Wings', 'Tenders')
    GROUP BY P.DIGITAL_ORDER_ID, P.ITEM_ID, D.BUSINESS_DTTM, P.BRAND_ID, CUSTOMER
);
