FROM IDS_DEV.DATASTORE.ORDER_LINE_FACT ;
create view IF NOT EXISTS ORDER_PAYMENT_V(
	PAYMENT_ID COMMENT 'This column creates a unique payment record',
	ORDER_ID COMMENT 'OrderID associates each unique paymentID record with the order that it paid for',
	EMPLOYEE_ID COMMENT 'The ID of Employee taking the customer’s order',
	PAYMENT_TYP COMMENT 'Card issuer, exactly as reported by the source system. May be full name e.g. “Visa” or abbreviation e.g. “VS”',
	BRAND_ID COMMENT 'Brand for the Order',
	STORE_ID COMMENT 'Unique identifier for the store where the purchase was made',
	BUSINESS_DT COMMENT 'BusinessDate is the date when the order was taken. The exception is for 24-hour stores that may define the beginning of a new “business day” as being at 2:00AM. So an order at 1:30AM on 11/11/20 would be counted towards the sales of BusinessDate 11/10/20.\n\n',
	VOID_IND COMMENT 'Indicates whether the order was cancelled \n',
	INSPIRE_ID COMMENT 'Masked card number used to pay for order. Concatenates first six card digits, six “x”''s, last four card digits, and cardholder name.',
	ACCOUNT_NM COMMENT 'Cardholder’s name',
	CARD_TYP COMMENT 'Specifies whether payment was by credit card, cash, debit card, Sonic gift card, EBT card or delivery service (e.g. Door Dash, GrubHub etc.). Card Issuer (e.g. Visa, Mastercard etc.) is not specified.',
	CARD_ISSUER_NM COMMENT 'Name of card issuer or delivery service.',
	PAYMENT_FIRST6_NBR COMMENT 'First six digits of the payment card for the order.',
	PAYMENT_LAST4_NBR COMMENT 'Last four digits of the payment card for the order.',
	PAYMENT_AUTH_CD COMMENT 'This is the 6-character authorization code provided by the card issuer',
	EXPIRATION_DT COMMENT 'Expiration date of the payment card used to purchase the order.',
	PAYMENT_AMT COMMENT 'Payment Amount reported by the credit card processor. Includes tip and delivery charge.',
	AMT COMMENT 'Payment Amount as reported by the Point Of Sale system. Includes everything but the tip (Includes delivery charge)',
	TRANSACTION_TM COMMENT 'Time when the card transaction was made.',
	LOAD_TYP COMMENT 'Indicates whether data is part of a large historical data pull or was added from a smaller data pull (daily, weekly etc.) \n',
	SOURCE_SYSTEM_NM COMMENT 'The POS System used to load the transaction  information\n',
	LOAD_ID COMMENT ' Indicates whether data is part of a large historical data pull or was added from a smaller data pull (daily, weekly etc.) \n',
	LOAD_DTTM COMMENT '\nThe Date/Datetime the Record was Inserted',
	UPDATE_ID COMMENT 'This is the User Identifier of the Person or Process that Updated the Table',
	UPDATE_DTTM COMMENT 'The Date/Datetime the Record was Updated'
) as 
SELECT ORDER_PAYMENT_FACT.PAYMENT_ID,ORDER_PAYMENT_FACT.ORDER_ID,ORDER_PAYMENT_FACT.EMPLOYEE_ID,ORDER_PAYMENT_FACT.PAYMENT_TYP,ORDER_PAYMENT_FACT.BRAND_ID,ORDER_PAYMENT_FACT.STORE_ID,ORDER_PAYMENT_FACT.BUSINESS_DT,ORDER_PAYMENT_FACT.VOID_IND,ORDER_PAYMENT_FACT.INSPIRE_ID,ORDER_PAYMENT_FACT.ACCOUNT_NM,ORDER_PAYMENT_FACT.CARD_TYP,ORDER_PAYMENT_FACT.CARD_ISSUER_NM,ORDER_PAYMENT_FACT.PAYMENT_FIRST6_NBR,ORDER_PAYMENT_FACT.PAYMENT_LAST4_NBR,ORDER_PAYMENT_FACT.PAYMENT_AUTH_CD,ORDER_PAYMENT_FACT.EXPIRATION_DT,ORDER_PAYMENT_FACT.PAYMENT_AMT,ORDER_PAYMENT_FACT.AMT,ORDER_PAYMENT_FACT.TRANSACTION_TM,ORDER_PAYMENT_FACT.LOAD_TYP,ORDER_PAYMENT_FACT.SOURCE_SYSTEM_NM,ORDER_PAYMENT_FACT.LOAD_ID,ORDER_PAYMENT_FACT.LOAD_DTTM,ORDER_PAYMENT_FACT.UPDATE_ID,ORDER_PAYMENT_FACT.UPDATE_DTTM
FROM IDS_DEV.DATASTORE.ORDER_PAYMENT_FACT ;
create view IF NOT EXISTS ORDER_SIDES_QUANTITY_VAPP(
	CUSTOMER,
	DATE_UTC,
	DATE_LOCAL,
	STORE_ID,
	BRAND,
	IDP_ORDER_ID,
	PRODUCT_ID,
	PRODUCT_CATEGORY,
	PRODUCT_NAME,
	COUNT
) as (
    WITH RECURSIVE PRODUCT_QUANTITY AS (
        SELECT
            DIGITAL_ORDER_ID,
            BRAND_ID,
            BUSINESS_DT,
            LINE_ITEM_ID AS ITEM_ID,
            LINE_ITEM_PRODUCT_CATEGORY_NM AS PRODUCT_CATEGORY,
            LINE_ITEM_DESC AS PRODUCT_DESCRIPTION,
            LINE_ITEM_QTY AS QTY
        FROM
            IDS_DEV.TXN.DIGITAL_ORDER_LINE
        UNION ALL
        SELECT
            C.DIGITAL_ORDER_ID AS DIGITAL_ORDER_ID,
            C.BRAND_ID AS BRAND_ID,
            C.BUSINESS_DT AS BUSINESS_DT,
            C.CHILD_ITEM_ID AS ITEM_ID,
            C.CHILD_ITEM_PRODUCT_CATEGORY_NM AS PRODUCT_CATEGORY,
            C.CHILD_ITEM_DESC AS PRODUCT_DESCRIPTION,
            (L.QTY * C.CHILD_ITEM_QTY) AS QTY
        FROM
            IDS_DEV.TXN.DIGITAL_ORDER_LINE_CHILD C
            JOIN PRODUCT_QUANTITY L ON L.DIGITAL_ORDER_ID = C.DIGITAL_ORDER_ID
            AND L.ITEM_ID = C.CHILD_PARENT_ITEM_ID
            AND L.BUSINESS_DT = C.BUSINESS_DT
            AND L.BRAND_ID = C.BRAND_ID
    )
    SELECT
        COALESCE(D.CUST_EMAIL, D.CUST_PHONE_NBR) AS CUSTOMER,
        D.BUSINESS_DTTM AS DATE_UTC,
        ITPRCS_DEV.CSO.CONVERT_TIMESTAMP_FROM_UTC_TO_TIMEZONE(D.BUSINESS_DTTM, ANY_VALUE(S.TIMEZONE)) AS DATE_LOCAL,
        LPAD(ANY_VALUE(D.LOC_ID),5,0) AS STORE_ID,
        P.BRAND_ID AS BRAND,
        P.DIGITAL_ORDER_ID AS IDP_ORDER_ID,
        P.ITEM_ID AS PRODUCT_ID,
        ANY_VALUE(P.PRODUCT_CATEGORY) AS PRODUCT_CATEGORY,
        ANY_VALUE(P.PRODUCT_DESCRIPTION) AS PRODUCT_NAME,
        SUM(P.QTY) AS COUNT
    FROM
        PRODUCT_QUANTITY AS P
        JOIN IDS_DEV.TXN.DIGITAL_ORDER AS D ON P.DIGITAL_ORDER_ID = D.DIGITAL_ORDER_ID
        AND P.BRAND_ID = D.BRAND_ID
        AND P.BUSINESS_DT = D.BUSINESS_DT
        LEFT JOIN POLARIS_DEV.SHDM.STORE_SCD_DIM S ON D.LOC_ID::INTEGER = S.STORE_ID::INTEGER
        AND D.BRAND_ID = S.BRAND_ID
        AND P.BUSINESS_DT BETWEEN S.EFFECTIVE_BEGIN_DATE
        AND S.EFFECTIVE_END_DATE
    WHERE
        PRODUCT_CATEGORY = 'Side'
    GROUP BY
        P.DIGITAL_ORDER_ID,
        P.ITEM_ID,
        D.BUSINESS_DTTM,
        P.BRAND_ID,
        CUSTOMER
);
create view IF NOT EXISTS ORDER_V(
	ORDER_ID,
	EMPLOYEE_ID,
	BUSINESS_DT,
	STORE_ID,
	CHECK_NBR,
	OPENED_TM,
