	SOURCE_NET_AMT,
	SURCHARGE_AMT,
	TAX_AMT,
	SOURCE_PAYMENT_AMT,
	GRATUITY_AMT,
	CUSTOMER_NM,
	CUSTOMER_ID,
	LOYALTY_NBR,
	FIRST_SEND_TM,
	CLOSED_IND,
	FUTURE_ORDER_IND,
	VOID_IND,
	REFUND_IND,
	TAX_EXEMPT_IND,
	GUEST_CNT,
	BRAND_ID,
