	LOAD_TYP,
	DERIVED_GROSS_AMT,
	DERIVED_DISCOUNT_AMT,
	DERIVED_NET_AMT,
	MISC_CHARGE_AMT,
	CHANNEL_ID,
	ALTERNATE1_ORDER_ID,
	LOAD_ID,
	LOAD_DTTM,
	UPDATE_ID,
	UPDATE_DTTM,
	DERIVED_PAYMENT_AMT
) as 
SELECT ORDER_FACT.ORDER_ID,ORDER_FACT.EMPLOYEE_ID,ORDER_FACT.BUSINESS_DT,ORDER_FACT.STORE_ID,ORDER_FACT.CHECK_NBR,ORDER_FACT.OPENED_TM,ORDER_FACT.CLOSED_TM,ORDER_FACT.ORDER_NM,ORDER_FACT.ITEM_CNT,ORDER_FACT.TRANSACTION_CNT,ORDER_FACT.SOURCE_GROSS_AMT,ORDER_FACT.SOURCE_DISCOUNT_AMT,ORDER_FACT.SOURCE_NET_AMT,ORDER_FACT.SURCHARGE_AMT,ORDER_FACT.TAX_AMT,ORDER_FACT.SOURCE_PAYMENT_AMT,ORDER_FACT.GRATUITY_AMT,ORDER_FACT.CUSTOMER_NM,ORDER_FACT.CUSTOMER_ID,ORDER_FACT.LOYALTY_NBR,ORDER_FACT.FIRST_SEND_TM,ORDER_FACT.CLOSED_IND,ORDER_FACT.FUTURE_ORDER_IND,ORDER_FACT.VOID_IND,ORDER_FACT.REFUND_IND,ORDER_FACT.TAX_EXEMPT_IND,ORDER_FACT.GUEST_CNT,ORDER_FACT.BRAND_ID,ORDER_FACT.SOURCE_SYSTEM_NM,ORDER_FACT.TIME_KEY,ORDER_FACT.LOAD_TYP,ORDER_FACT.DERIVED_GROSS_AMT,ORDER_FACT.DERIVED_DISCOUNT_AMT,ORDER_FACT.DERIVED_NET_AMT,ORDER_FACT.MISC_CHARGE_AMT,ORDER_FACT.CHANNEL_ID,ORDER_FACT.ALTERNATE1_ORDER_ID,ORDER_FACT.LOAD_ID,ORDER_FACT.LOAD_DTTM,ORDER_FACT.UPDATE_ID,ORDER_FACT.UPDATE_DTTM,ORDER_FACT.DERIVED_PAYMENT_AMT
FROM IDS_DEV.DATASTORE.ORDER_FACT ;
create view IF NOT EXISTS PERIOD_FLASH_COMPARABLE_SALES(
	BRAND,
	FISCAL_YEAR_NBR,
	FISCAL_QUARTER_NBR,
	FISCAL_PERIOD_NBR,
	STORE_NBR,
	STORE_STATUS_TYPE,
	CURRENT_OWNER,
	SALES_TIME_OWNER_NAME,
	ORDER_CHANNEL_TYPE,
	NET_SALES_AMOUNT,
	COMPARABLE_SALES_THIS_YEAR_CURRENT_YEAR_NBR,
	COMPARABLE_SALES_LAST_YEAR_CURRENT_YEAR_NBR,
	COMPARABLE_SALES_THIS_YEAR_PREVIOUS_YEAR_NBR,
	COMPARABLE_SALES_LAST_YEAR_PREVIOUS_YEAR_NBR,
	COMPARABLE_SALES_THIS_YEAR_PREVIOUS_PREVIOUS_YEAR_NBR,
	COMPARABLE_SALES_LAST_YEAR_PREVIOUS_PREVIOUS_YEAR_NBR,
	COMPARABLE_TRANSACTION_THIS_YEAR_CURRENT_YEAR_NBR,
	COMPARABLE_TRANSACTION_LAST_YEAR_CURRENT_YEAR_NBR,
	COMPARABLE_TRANSACTION_THIS_YEAR_PREVIOUS_YEAR_NBR,
	COMPARABLE_TRANSACTION_LAST_YEAR_PREVIOUS_YEAR_NBR,
	COMPARABLE_TRANSACTION_THIS_YEAR_PREVIOUS_PREVIOUS_YEAR_NBR,
	COMPARABLE_TRANSACTION_LAST_YEAR_PREVIOUS_PREVIOUS_YEAR_NBR
) as
SELECT
    CASE WHEN UPPER(SALES.BRAND_ID) IN ('ARG','ARBYS') THEN 'ARB'
       WHEN UPPER(SALES.BRAND_ID) IN ('BWW') THEN 'BWW'
       WHEN UPPER(SALES.BRAND_ID) IN ('SDI','SONIC') THEN 'SON'
       WHEN UPPER(SALES.BRAND_ID) IN ('JJ') THEN 'JJ'
       WHEN UPPER(SALES.BRAND_ID) IN ('DNKN') THEN 'DUN'
       WHEN UPPER(SALES.BRAND_ID) IN ('BSKN') THEN 'BR'
       WHEN UPPER(SALES.BRAND_ID) IN ('RTO') THEN 'RT'
       ELSE 'UNKNOWN'
    END as BRAND,
    SALES.FISCAL_YEAR_NBR,
    SALES.FISCAL_QUARTER_NBR,
    SALES.FISCAL_PERIOD_NBR,
    SALES.STORE_NBR,
    re.STORE_STATUS_TYP as STORE_STATUS_TYPE,
    re.FRANCHISEE_NM as CURRENT_OWNER,
    SALES.SALES_TIME_OWNER_NAME,
    SALES.ORDER_CHANNEL_TYPE,
    SALES.NET_SALES_AMOUNT,
    SALES.COMPARABLE_SALES_THIS_YEAR_CURRENT_YEAR_NBR,
    SALES.COMPARABLE_SALES_LAST_YEAR_CURRENT_YEAR_NBR,
    SALES.COMPARABLE_SALES_THIS_YEAR_PREVIOUS_YEAR_NBR,
    SALES.COMPARABLE_SALES_LAST_YEAR_PREVIOUS_YEAR_NBR,
    SALES.COMPARABLE_SALES_THIS_YEAR_PREVIOUS_PREVIOUS_YEAR_NBR,
    SALES.COMPARABLE_SALES_LAST_YEAR_PREVIOUS_PREVIOUS_YEAR_NBR,
    SALES.COMPARABLE_TRANSACTION_THIS_YEAR_CURRENT_YEAR_NBR,
    SALES.COMPARABLE_TRANSACTION_LAST_YEAR_CURRENT_YEAR_NBR,
    SALES.COMPARABLE_TRANSACTION_THIS_YEAR_PREVIOUS_YEAR_NBR,
    SALES.COMPARABLE_TRANSACTION_LAST_YEAR_PREVIOUS_YEAR_NBR,
    SALES.COMPARABLE_TRANSACTION_THIS_YEAR_PREVIOUS_PREVIOUS_YEAR_NBR,
    SALES.COMPARABLE_TRANSACTION_LAST_YEAR_PREVIOUS_PREVIOUS_YEAR_NBR



FROM IDS_DEV.TXN.PERIOD_FLASH_COMPARABLE_SALES SALES
left join IDM_DEV.COREDIM.RESTAURANT_SCD_DIM re
    on SALES.brand_id = re.brand_id
    and SALES.store_nbr = re.store_id
    and re.current_ind = TRUE;
create view IF NOT EXISTS SALES_DAY_V(
	STORE_ID,
	BRAND_ID,
	TRANSACTION_CNT,
	BUSINESS_DT,
	NET_SALES_AMT,
	LOAD_TYP,
	SOURCE_SYSTEM_NM,
	LOAD_ID,
	LOAD_DTTM,
	UPDATE_ID,
	UPDATE_DTTM
) as 
SELECT DAILY_FLASH_SALES_FACT.STORE_ID,DAILY_FLASH_SALES_FACT.BRAND_ID,DAILY_FLASH_SALES_FACT.TRANSACTION_CNT,DAILY_FLASH_SALES_FACT.BUSINESS_DT,DAILY_FLASH_SALES_FACT.NET_SALES_AMT,DAILY_FLASH_SALES_FACT.LOAD_TYP,DAILY_FLASH_SALES_FACT.SOURCE_SYSTEM_NM,DAILY_FLASH_SALES_FACT.LOAD_ID,DAILY_FLASH_SALES_FACT.LOAD_DTTM,DAILY_FLASH_SALES_FACT.UPDATE_ID,DAILY_FLASH_SALES_FACT.UPDATE_DTTM
FROM IDS_DEV.DATASTORE.DAILY_FLASH_SALES_FACT ;
create view IF NOT EXISTS SALES_WEEK_V(
	BRAND_ID,
	WEEK_START_DT,
	STORE_ID,
	DMA_CD,
	DMA_NM,
	SALES_AMT,
	TRANSACTION_CNT
) as
with cte_week
as
(select date_key, Fiscal_Week_Start_Date,Fiscal_Week_End_Date  From polaris.shdm.dim_Date_arbys
group by date_key, Fiscal_Year, Fiscal_Week_Start_Date,Fiscal_Week_End_Date)
select ord.brandid brand_id, wk.Fiscal_Week_Start_Date Week_Start_Dt,  ord.storeid Store_Id, st.dma_code dma_cd, st.dma_name dma_nm, sum(netamount) Sales_Amt, count(orderid) Transaction_Cnt from "POLARIS_TEST"."SADM"."ORDER_FACT" ord
left join polaris.shdm.store_dim st on ord.storeid = st.store_id and ord.brandid = st.brand_id
left join cte_week wk on replace(ord.businessdate,'-') = wk.date_key
group by ord.brandid, ord.storeid, wk.Fiscal_Week_Start_Date, st.dma_code, st.dma_name;
create view IF NOT EXISTS STORE_COUNT_V(
	BRAND_ID,
	OWNERSHIP_TYP,
	BUSINESS_DT,
	CNT_ACTIVE,
	CNT_SALES,
	STORE_PERC,
	THRESHOLD_FLG
) as
WITH DT AS (
    -- get last 10 days
    SELECT LEVEL, BUSINESS_DT - LEVEL as BUSINESS_DT 
    FROM (select date(TO_TIMESTAMP_NTZ(CONVERT_TIMEZONE('EST', current_timestamp))) BUSINESS_DT ) DUAL 
    CONNECT BY prior LEVEL < 10
)
,ST AS ( 
    -- count the number of corporate and franchised stores
    SELECT 
        lower(BRAND_ID) as BRAND_ID, OWNERSHIP_TYP, dt.BUSINESS_DT,
        COUNT(DISTINCT STORE_ID) OVER (PARTITION BY BRAND_ID, OWNERSHIP_TYP, dt.BUSINESS_DT) as active_stores
    FROM 
        IDH_QA.SHARED.STORE_SCD_PROD_V ssv
        INNER JOIN DT ON dt.BUSINESS_DT BETWEEN ssv.EFFECTIVE_BEGIN_DT AND ssv.EFFECTIVE_END_DT
    WHERE 
        OWNERSHIP_TYP in ('Company Owned', 'Franchised')
        and ssv.OPEN_DT is not null 
        AND (ssv.CLOSURE_DT IS NULL or ssv.CLOSURE_DT > DT.BUSINESS_DT)
        and COUNTRY_NM in ('US', 'USA')
        and ((TEMP_CLOSED_DT is null and REOPEN_DT is NULL) or reopen_DT < dt.BUSINESS_DT)
)
, DSF AS (
    -- get the total number of stores who have sales in business_dt
    SELECT distinct
        lower(a.BRAND_ID) as BRAND_ID, OWNERSHIP_TYP, dt.BUSINESS_DT, 
        COUNT(DISTINCT a.STORE_ID) OVER (PARTITION BY a.BRAND_ID, OWNERSHIP_TYP, dt.BUSINESS_DT) AS active_store_sales
    FROM
        DT
        INNER JOIN IDS_DEV.DATASTORE.DAILY_FLASH_SALES_FACT a on a.business_dt = dt.business_dt
        LEFT OUTER JOIN IDH_QA.SHARED.STORE_SCD_PROD_V b 
            on a.BUSINESS_DT BETWEEN b.EFFECTIVE_BEGIN_DT AND b.EFFECTIVE_END_DT
            and a.store_id = b.store_id
            and a.brand_id = b.brand_id
            and b.OWNERSHIP_TYP in ('Company Owned', 'Franchised')
            and b.COUNTRY_NM in ('US', 'USA')
    WHERE 
        nvl(a.NET_SALES_AMT, 0) > 0

)
, F AS (
    SELECT DISTINCT
        st.BRAND_ID, 
        st.OWNERSHIP_TYP, 
        st.BUSINESS_DT, 
        nvl(active_stores, 0) as active_stores, 
        nvl(active_store_sales, 0) as active_sales_stores, 
        ROUND(nvl(active_store_sales, 0) / nvl(active_stores, 0) *100, 0) AS STORE_COUNT,
    CASE
        WHEN st.BRAND_ID = 'arbys' and st.OWNERSHIP_TYP = 'Company Owned' and ROUND((active_store_sales/active_stores)*100,0) >= 95 THEN 'Y'
        WHEN st.BRAND_ID IN ('jj', 'bww', 'sonic') and ROUND((active_store_sales/active_stores)*100,0) >= 90 THEN 'Y'
        WHEN st.BRAND_ID IN ('dnkn', 'bskn') and st.OWNERSHIP_TYP = 'Franchised' and ROUND((active_store_sales/active_stores)*100,0) >= 90 THEN 'Y'
        ELSE 'N'
    END AS THRESHOLD_FLG
FROM 
    st
    LEFT OUTER JOIN DSF 
        on dsf.brand_id = st.brand_id
        and dsf.business_dt = st.business_dt 
        and dsf.OWNERSHIP_TYP = st.OWNERSHIP_TYP
)
, A AS (
    SELECT
        brand_id,
        business_dt,
        min(THRESHOLD_FLG) as THRESHOLD_FLG
    FROM f
    WHERE brand_id IN ('jj', 'bww', 'sonic')
    GROUP BY 
    brand_id,
    business_dt
)
    SELECT 
        f.BRAND_ID,
        f.OWNERSHIP_TYP,
        f.BUSINESS_DT,
        f.active_stores,
        f.active_sales_stores,
        f.STORE_COUNT,
        case when f.BRAND_ID IN ('jj', 'bww', 'sonic') THEN a.THRESHOLD_FLG ELSE f.THRESHOLD_FLG END as THRESHOLD_FLG
    FROM f
    LEFT OUTER JOIN a
    ON f.brand_id = a.brand_id
    AND f.business_dt = a.business_dt
    order by f.brand_id, f.business_dt desc, f.OWNERSHIP_TYP;
CREATE FUNCTION IF NOT EXISTS DAILY_DAY_PART_FLASH_SALES_V("DATE_FROM" DATE, "DATE_TO" DATE)
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BUSINESS_DT" DATE, "FISCAL_YEAR_NBR" NUMBER(38,0), "FISCAL_QUARTER_NBR" NUMBER(38,0), "FISCAL_PERIOD_NBR" NUMBER(38,0), "FISCAL_WEEK_NBR" NUMBER(38,0), "CALENDAR_DAY_NM" VARCHAR(16777216), "NET_SALES" NUMBER(38,2), "TRANS_CNT" NUMBER(38,0), "DMA_NAME" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "ADDRESS_1" VARCHAR(16777216), "ADDRESS_2" VARCHAR(16777216), "CITY" VARCHAR(16777216), "ZIP_CD" VARCHAR(16777216), "OPEN_15P_FLAG" BOOLEAN, "OPEN_AFTER_HONEYMOON_FLAG" BOOLEAN)
LANGUAGE SQL
AS '

with a as
(  
 select
 DATE_FROM,
 DATE_TO
),
DT as (
SELECT
DT.CALENDAR_DT,
DT.FISCAL_YEAR_NBR,
DT.FISCAL_QUARTER_NBR,
DT.FISCAL_PERIOD_NBR,
DT.FISCAL_WEEK_NBR,
DT.CALENDAR_DAY_NM  
FROM a
INNER join
IDH_DEV.SHARED.DATE_DIM_V DT
on DT.CALENDAR_DT BETWEEN A.DATE_FROM AND A.DATE_TO
),
ST as (
SELECT
DT.CALENDAR_DT,
DT.FISCAL_YEAR_NBR,
DT.FISCAL_QUARTER_NBR,
DT.FISCAL_PERIOD_NBR,
DT.FISCAL_WEEK_NBR,
DT.CALENDAR_DAY_NM,  
ST.STORE_ID,
ST.BRAND_ID,
st.DMA_NM,
st.DMA_CD,
st.OWNERSHIP_TYP,
st.STATE_NM,
st.COUNTRY_NM,
st.ADDRESS_1_TXT,
st.ADDRESS_2_TXT,
st.CITY_NM,
st.ZIP_CD,
ST.OPEN_DT
FROM DT
INNER JOIN IDH_DEV.SHARED.STORE_SCD_V ST  
ON DT.CALENDAR_DT >= ST.OPEN_DT
AND IFNULL(st.COUNTRY_NM, '''') in (''US'', ''USA'')
AND ST.CURRENT_IND = 1
)
SELECT
      ST.BRAND_ID
    , ST.STORE_ID
    , ST.CALENDAR_DT
    , ST.FISCAL_YEAR_NBR
    , ST.FISCAL_QUARTER_NBR
    , ST.FISCAL_PERIOD_NBR
    , ST.FISCAL_WEEK_NBR
    , ST.CALENDAR_DAY_NM
    , sum(nvl(dfsf.NET_SALES_AMT, 0)) AS Net_Sales  /*ODI - 2289*/
    , iff(sum(nvl(dfsf.NET_SALES_AMT, 0)) = 0, 0, sum(nvl(dfsf.TRX_CNT, 0))) AS Trans_Cnt  /*ODI - 2289*/
    , IFNULL(st.DMA_NM, ''UNKNOWN'') AS DMA_NAME
    , IFNULL(st.DMA_CD, ''UNKNOWN'') AS DMA_CODE
    , IFNULL(st.OWNERSHIP_TYP, ''UNKNOWN'') AS OWNERSHIP_TYP
    , IFNULL(st.STATE_NM, ''UNKNOWN'') AS STATE
    , IFNULL(st.COUNTRY_NM, ''UNKNOWN'') AS COUNTRY
    , IFNULL(st.ADDRESS_1_TXT, ''UNKNOWN'') AS ADDRESS_1
    , IFNULL(st.ADDRESS_2_TXT, ''UNKNOWN'') AS ADDRESS_2  
    , IFNULL(st.CITY_NM, ''UNKNOWN'') AS CITY
    , IFNULL(st.ZIP_CD, ''UNKNOWN'') AS ZIP_CD
    , nvl(ST.OPEN_DT, opendt.calendar_dt) <= opendt.calendar_dt as OPEN_15P_FLAG -- ODI-53
    , nvl(ST.OPEN_DT, opendthoney.calendar_dt) <= opendthoney.calendar_dt as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
FROM ST
INNER JOIN 
    IDH_DEV.SHARED.DATE_DIM_V as opendt
    on opendt.calendar_dt = opendt.FISCAL_PERIOD_START_DT
    INNER JOIN IDH_DEV.SHARED.DATE_DIM_V as busdt
    on busdt.calendar_dt = ST.CALENDAR_DT
    and
        iff (opendt.FISCAL_PERIOD_START_DT = opendt.CALENDAR_DT
            , iff((opendt.FISCAL_PERIOD_NBR+15)%12 = 0, 12, (opendt.FISCAL_PERIOD_NBR+15)%12)
            , iff((opendt.FISCAL_PERIOD_NBR+16)%12 = 0, 12, (opendt.FISCAL_PERIOD_NBR+16)%12)
        ) = busdt.FISCAL_PERIOD_NBR
    and iff (opendt.FISCAL_PERIOD_START_DT = opendt.CALENDAR_DT
            , opendt.FISCAL_YEAR_NBR + trunc((opendt.FISCAL_PERIOD_NBR+14)/12)
            , opendt.FISCAL_YEAR_NBR + trunc((opendt.FISCAL_PERIOD_NBR+15)/12)
        ) = busdt.FISCAL_YEAR_NBR  
    INNER JOIN IDH_DEV.SHARED.DATE_DIM_V as opendthoney --ODI-199
    on
        iff ((opendthoney.FISCAL_PERIOD_NBR +
                iff(opendthoney.FISCAL_PERIOD_START_DT = opendthoney.CALENDAR_DT, 3, 4)
        ) % 12 = 0, 12, (opendthoney.FISCAL_PERIOD_NBR +
                iff(opendthoney.FISCAL_PERIOD_START_DT = opendthoney.CALENDAR_DT, 3, 4)
        ) % 12
        ) = busdt.FISCAL_PERIOD_NBR
    and 
        opendthoney.FISCAL_YEAR_NBR + trunc(
            (opendthoney.FISCAL_PERIOD_NBR +
                    iff(opendthoney.FISCAL_PERIOD_START_DT = opendthoney.CALENDAR_DT, 2, 3)
            ) / 12
        ) = busdt.FISCAL_YEAR_NBR
    and opendthoney.calendar_dt = opendthoney.FISCAL_PERIOD_START_DT
LEFT OUTER JOIN  IDS_DEV.DATASTORE.DAILY_DAY_PART_FLASH_SALES_FACT dfsf
ON  ST.STORE_ID = DFSF.STORE_ID
and ST.brand_id = DFSF.brand_id
AND ST.CALENDAR_DT = DFSF.BUSINESS_DT
GROUP BY
      ST.BRAND_ID
    , ST.STORE_ID
    , ST.CALENDAR_DT
    , ST.FISCAL_YEAR_NBR
    , ST.FISCAL_QUARTER_NBR
    , ST.FISCAL_PERIOD_NBR
    , ST.FISCAL_WEEK_NBR
    , ST.CALENDAR_DAY_NM
    , st.DMA_NM
    , st.DMA_CD
    , st.OWNERSHIP_TYP
    , st.STATE_NM
    , st.COUNTRY_NM
    , st.ADDRESS_1_TXT
    , st.ADDRESS_2_TXT
    , st.CITY_NM
    , st.ZIP_CD
    , ST.OPEN_DT
    , opendt.calendar_dt
    , opendthoney.calendar_dt
';
CREATE FUNCTION IF NOT EXISTS DAILY_FLASH_SALES_V("BUSINESS_DATE" DATE)
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BUSINESS_DT" DATE, "NET_SALES" NUMBER(38,2), "TRANS_CNT" NUMBER(38,0), "COMP_SALES" NUMBER(38,2), "COMP_TRANS" NUMBER(38,0), "DMA_NAME" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "OWNERSHIP_TYPE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "OPEN_DATE" DATE, "CLOSURE_DATE" DATE, "TEMP_CLOSED_DATE" DATE, "REOPEN_DATE" DATE)
LANGUAGE SQL
AS '


with a as 
(  
 select BUSINESS_DATE
),
DT as (
SELECT 
DT.DATE_KEY,
DT.CALENDAR_DT
FROM a
INNER join 
IDH_DEV.SHARED.DATE_DIM_V BDT
on BDT.CALENDAR_DT = a.business_date
LEFT OUTER JOIN IDH_DEV.SHARED.DATE_DIM_V DT
on DT.CALENDAR_DT between least(BDT.FISCAL_YEAR_START_DT, BUSINESS_DATE - 9) AND BUSINESS_DATE
AND DT.DATE_KEY >= 20160101
),
ST as (
SELECT 
DT.DATE_KEY,
DT.CALENDAR_DT,
ST.STORE_ID,
ST.BRAND_ID,
st.DMA_NM,
st.DMA_CD,
st.OWNERSHIP_TYP,
st.STATE_NM,
st.COUNTRY_NM,
st.OPEN_DT,
st.CLOSURE_DT
FROM DT
INNER JOIN IDH_DEV.SHARED.STORE_SCD_V ST   
ON DT.CALENDAR_DT >= ST.OPEN_DT
AND IFNULL(st.COUNTRY_NM, '''') in (''US'', ''USA'')
AND ST.CURRENT_IND = 1
)

SELECT
      ST.BRAND_ID
    , ST.STORE_ID
    , ST.CALENDAR_DT
    , nvl(dfsf.NET_SALES_AMT, 0) AS Net_Sales  /*ODI - 2289*/
    , iff(nvl(dfsf.NET_SALES_AMT, 0) = 0, 0, nvl(dfsf.TRANSACTION_CNT, 0)) AS Trans_Cnt  /*ODI - 2289*/
    , NVL(dfsf.NET_SALES_AMT,0) AS Comp_Sales  /*ODI - 2289*/
    , iff(nvl(dfsf.NET_SALES_AMT, 0) = 0, 0, dfsf.TRANSACTION_CNT) AS Comp_Trans /*ODI - 2289*/
    , IFNULL(st.DMA_NM, ''UNKNOWN'') AS DMA_NAME
    , IFNULL(st.DMA_CD, ''UNKNOWN'') AS DMA_CODE
    , IFNULL(st.OWNERSHIP_TYP, ''UNKNOWN'') AS OWNERSHIP_TYPE
    , IFNULL(st.STATE_NM, ''UNKNOWN'') AS STATE
    , IFNULL(st.COUNTRY_NM, ''UNKNOWN'') AS COUNTRY
    , st.OPEN_DT
    , st.CLOSURE_DT
    , st_cl.TEMP_CLOSED_DT
    , st_cl.REOPEN_DT
FROM ST
LEFT OUTER JOIN  IDS_DEV.DATASTORE.DAILY_FLASH_SALES_FACT dfsf
ON  ST.STORE_ID = DFSF.STORE_ID 
and ST.brand_id = DFSF.brand_id 
AND ST.DATE_KEY = DFSF.BUSINESS_DATE_KEY
LEFT OUTER JOIN  IDH_DEV.SHARED.STORE_SCD_V ST_CL
ON st.BRAND_ID = st_cl.BRAND_ID 
AND st.STORE_ID = st_cl.STORE_ID
AND st_cl.TEMP_CLOSED_DT IS NOT NULL
AND ST.CALENDAR_DT between st_cl.TEMP_CLOSED_DT and st_cl.REOPEN_DT

';
CREATE FUNCTION IF NOT EXISTS DAILY_FLASH_SALES_V("BUSINESS_DATE" DATE, "TIME_INTERVAL" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BUSINESS_DT" DATE, "FISCAL_WEEK_NBR" NUMBER(38,0), "NET_SALES" NUMBER(38,2), "TRANS_CNT" NUMBER(38,0), "COMP_SALES" NUMBER(38,2), "COMP_TRANS" NUMBER(38,0), "DMA_NAME" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "OWNERSHIP_TYPE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "OPEN_DATE" DATE, "CLOSURE_DATE" DATE, "TEMP_CLOSED_DATE" DATE, "REOPEN_DATE" DATE)
LANGUAGE SQL
AS '


WITH 
DT AS (
SELECT
DT.CALENDAR_DT,
DT.BUSINESS_DT,
DT.FISCAL_WEEK_NBR
FROM
IDS_DEV.INT_REF.COMP_DATES BDT
INNER JOIN IDS_DEV.INT_REF.COMP_CALENDAR C
ON C.CALENDAR_DT = BDT.BUSINESS_DT
INNER JOIN IDS_DEV.INT_REF.COMP_DATES DT
ON DT.TIME_INTERVAL = BDT.TIME_INTERVAL
AND BDT.BUSINESS_DT >= DT.BUSINESS_DT
AND DT.CALENDAR_DT BETWEEN least(BDT.FISCAL_YEAR_START_DT, BDT.CALENDAR_DT - iff(TIME_INTERVAL = ''CY'', 9, 16)) AND BDT.CALENDAR_DT  
WHERE BDT.BUSINESS_DT = BUSINESS_DATE
AND BDT.TIME_INTERVAL = TIME_INTERVAL
qualify row_number() over (partition by DT.CALENDAR_DT order by DT.BUSINESS_DT desc) = 1
),

ST AS (
SELECT 
DT.CALENDAR_DT,
DT.FISCAL_WEEK_NBR,
ST.STORE_ID,
ST.BRAND_ID,
ST_SCD.DMA_NM,
ST_SCD.DMA_CD,
ST_SCD.OWNERSHIP_TYP,
st.STATE_NM,
st.COUNTRY_NM,
st.OPEN_DT,
ST_SCD.CLOSURE_DT
FROM DT
INNER JOIN IDH_DEV.SHARED.STORE_SCD_V ST
ON ST.CURRENT_IND = 1
AND IFNULL(st.COUNTRY_NM, '''') IN (''US'', ''USA'')
AND (CASE WHEN lower(ST.BRAND_ID) IN (''arbys'',''arg'')
AND lower(ST.OWNERSHIP_TYP) =''franchised''
THEN 0 ELSE 1 END) = 1
LEFT JOIN IDH_DEV.SHARED.STORE_SCD_V ST_SCD
ON DT.CALENDAR_DT BETWEEN ST_SCD.EFFECTIVE_BEGIN_DT AND ST_SCD.EFFECTIVE_END_DT
AND ST_SCD.STORE_ID = ST.STORE_ID
AND ST_SCD.BRAND_ID = ST.BRAND_ID
AND IFNULL(ST_SCD.COUNTRY_NM, '''') IN (''US'', ''USA'')
AND (CASE WHEN lower(ST_SCD.BRAND_ID) IN (''arbys'',''arg'')
AND lower(ST_SCD.OWNERSHIP_TYP) =''franchised''
THEN 0 ELSE 1 END) = 1
LEFT JOIN IDH_DEV.SHARED.STORE_SCD_V PST
ON ST.STORE_ID = PST.STORE_ID
AND ST.BRAND_ID = PST.BRAND_ID
AND DT.BUSINESS_DT BETWEEN PST.EFFECTIVE_BEGIN_DT AND PST.EFFECTIVE_END_DT
AND IFNULL(PST.COUNTRY_NM, '''') IN (''US'', ''USA'')
AND (CASE WHEN lower(PST.BRAND_ID) IN (''arbys'',''arg'')
AND lower(PST.OWNERSHIP_TYP) =''franchised''
THEN 0 ELSE 1 END) = 1
INNER JOIN (
        select BDT.FISCAL_YEAR_START_DT
        from IDS_DEV.INT_REF.COMP_DATES BDT
        where BDT.TIME_INTERVAL = ''CAL3Y''
        and BDT.BUSINESS_DT = BUSINESS_DATE
    ) as c3y_dt
ON coalesce(ST_SCD.CLOSURE_DT, ST.CLOSURE_DT, c3y_dt.FISCAL_YEAR_START_DT) >= c3y_dt.FISCAL_YEAR_START_DT
)

SELECT
      ST.BRAND_ID
    , ST.STORE_ID
    , ST.CALENDAR_DT
    , ST.FISCAL_WEEK_NBR
    , nvl(dfsf.NET_SALES_AMT, 0) AS Net_Sales  /*ODI - 2289*/
    , iff(nvl(dfsf.NET_SALES_AMT, 0) = 0, 0, nvl(dfsf.TRANSACTION_CNT, 0)) AS Trans_Cnt  /*ODI - 2289*/
    , NVL(dfsf.NET_SALES_AMT,0) AS Comp_Sales  /*ODI - 2289*/
    , iff(nvl(dfsf.NET_SALES_AMT, 0) = 0, 0, dfsf.TRANSACTION_CNT) AS Comp_Trans /*ODI - 2289*/
    , IFNULL(st.DMA_NM, ''UNKNOWN'') AS DMA_NAME
    , IFNULL(st.DMA_CD, ''UNKNOWN'') AS DMA_CODE
    , IFNULL(st.OWNERSHIP_TYP, ''UNKNOWN'') AS OWNERSHIP_TYPE
    , IFNULL(st.STATE_NM, ''UNKNOWN'') AS STATE
    , IFNULL(st.COUNTRY_NM, ''UNKNOWN'') AS COUNTRY
    , st.OPEN_DT
    , st.CLOSURE_DT
    , st_cl.TEMP_CLOSED_DT
    , st_cl.REOPEN_DT
FROM ST
LEFT OUTER JOIN  IDS_DEV.DATASTORE.DAILY_FLASH_SALES_FACT dfsf
ON  ST.STORE_ID = DFSF.STORE_ID 
and ST.brand_id = DFSF.brand_id 
AND ST.CALENDAR_DT = DFSF.BUSINESS_DT
LEFT OUTER JOIN  IDH_DEV.SHARED.STORE_SCD_V ST_CL
ON st.BRAND_ID = st_cl.BRAND_ID 
AND st.STORE_ID = st_cl.STORE_ID
AND st_cl.TEMP_CLOSED_DT IS NOT NULL
AND ST.CALENDAR_DT BETWEEN st_cl.TEMP_CLOSED_DT AND st_cl.REOPEN_DT

';
CREATE FUNCTION IF NOT EXISTS DAILY_FLASH_SALES_V("BUSINESS_DATE" DATE, "TIME_INTERVAL" VARCHAR(16777216), "BRAND" VARCHAR(16777216), "THRESHOLD_FLG" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BUSINESS_DT" DATE, "FISCAL_WEEK_NBR" NUMBER(38,0), "NET_SALES" NUMBER(38,2), "TRANS_CNT" NUMBER(38,0), "COMP_SALES" NUMBER(38,2), "COMP_TRANS" NUMBER(38,0), "DMA_NAME" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "OWNERSHIP_TYPE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "OPEN_DATE" DATE, "CLOSURE_DATE" DATE, "TEMP_CLOSED_DATE" DATE, "REOPEN_DATE" DATE, "THRESHOLD_FLAG" BOOLEAN)
LANGUAGE SQL
AS '


WITH 
DT AS (
SELECT
DT.CALENDAR_DT,
DT.BUSINESS_DT,
DT.FISCAL_WEEK_NBR
FROM
IDS_DEV.INT_REF.COMP_DATES BDT
INNER JOIN IDS_DEV.INT_REF.COMP_CALENDAR C
ON C.CALENDAR_DT = BDT.BUSINESS_DT
INNER JOIN IDS_DEV.INT_REF.COMP_DATES DT
ON DT.TIME_INTERVAL = BDT.TIME_INTERVAL
AND BDT.BUSINESS_DT >= DT.BUSINESS_DT
AND DT.CALENDAR_DT BETWEEN least(BDT.FISCAL_YEAR_START_DT, BDT.CALENDAR_DT - iff(TIME_INTERVAL = ''CY'', 9, 16)) AND BDT.CALENDAR_DT  
WHERE BDT.BUSINESS_DT = BUSINESS_DATE
AND BDT.TIME_INTERVAL = TIME_INTERVAL
qualify row_number() over (partition by DT.CALENDAR_DT order by DT.BUSINESS_DT desc) = 1
),

ST AS (
SELECT 
DT.CALENDAR_DT,
DT.FISCAL_WEEK_NBR,
ST.STORE_ID,
ST.BRAND_ID,
ST_SCD.DMA_NM,
ST_SCD.DMA_CD,
ST_SCD.OWNERSHIP_TYP,
st.STATE_NM,
st.COUNTRY_NM,
st.OPEN_DT,
ST_SCD.CLOSURE_DT,
SC.THRESHOLD_FLG = ''Y'' as THRESHOLD_FLG
FROM DT
INNER JOIN IDH_QA.SHARED.STORE_SCD_PROD_V ST
ON ST.CURRENT_IND = 1
AND IFNULL(st.COUNTRY_NM, '''') IN (''US'', ''USA'')
AND (CASE WHEN lower(ST.BRAND_ID) IN (''arbys'',''arg'')
AND lower(ST.OWNERSHIP_TYP) =''franchised''
THEN 0 ELSE 1 END) = 1
AND (CASE WHEN UPPER(ST.BRAND_ID) IN (''ARG'',''ARBYS'') THEN ''ARB''
       WHEN UPPER(ST.BRAND_ID) IN (''BWW'') THEN ''BWW''
       WHEN UPPER(ST.BRAND_ID) IN (''SDI'',''SONIC'') THEN ''SON''
       WHEN UPPER(ST.BRAND_ID) IN (''JJ'') THEN ''JJ''
       WHEN UPPER(ST.BRAND_ID) IN (''DNKN'') THEN ''DUN''
       WHEN UPPER(ST.BRAND_ID) IN (''BSKN'') THEN ''BR''
       WHEN UPPER(ST.BRAND_ID) IN (''RTO'') THEN ''RT''
       ELSE ''UNKNOWN''
       END = BRAND
    OR UPPER(BRAND) IN (''ALL'', ''*''))
LEFT JOIN IDH_QA.SHARED.STORE_SCD_PROD_V ST_SCD
ON DT.CALENDAR_DT BETWEEN ST_SCD.EFFECTIVE_BEGIN_DT AND ST_SCD.EFFECTIVE_END_DT
AND ST_SCD.STORE_ID = ST.STORE_ID
AND ST_SCD.BRAND_ID = ST.BRAND_ID
AND IFNULL(ST_SCD.COUNTRY_NM, '''') IN (''US'', ''USA'')
AND (CASE WHEN lower(ST_SCD.BRAND_ID) IN (''arbys'',''arg'')
AND lower(ST_SCD.OWNERSHIP_TYP) =''franchised''
THEN 0 ELSE 1 END) = 1
LEFT JOIN STORE_COUNT_V as SC
    on
       -- BUSINESS_DATE - 9 >= DT.CALENDAR_DT AND
        DT.CALENDAR_DT = SC.BUSINESS_DT
        AND SC.BRAND_ID = ST.BRAND_ID
        AND lower(ST_SCD.OWNERSHIP_TYP) = lower(SC.OWNERSHIP_TYP)
       -- AND SC.THRESHOLD_FLG = ''Y''
LEFT JOIN IDH_QA.SHARED.STORE_SCD_PROD_V PST
ON ST.STORE_ID = PST.STORE_ID
AND ST.BRAND_ID = PST.BRAND_ID
AND DT.BUSINESS_DT BETWEEN PST.EFFECTIVE_BEGIN_DT AND PST.EFFECTIVE_END_DT
AND IFNULL(PST.COUNTRY_NM, '''') IN (''US'', ''USA'')
AND (CASE WHEN lower(PST.BRAND_ID) IN (''arbys'',''arg'')
AND lower(PST.OWNERSHIP_TYP) =''franchised''
THEN 0 ELSE 1 END) = 1
INNER JOIN (
        select BDT.FISCAL_YEAR_START_DT
        from IDS_DEV.INT_REF.COMP_DATES BDT
        where BDT.TIME_INTERVAL = ''CAL3Y''
        and BDT.BUSINESS_DT = BUSINESS_DATE
    ) as c3y_dt
ON coalesce(ST_SCD.CLOSURE_DT, ST.CLOSURE_DT, c3y_dt.FISCAL_YEAR_START_DT) >= c3y_dt.FISCAL_YEAR_START_DT
)
,RESULT as (
SELECT
      ST.BRAND_ID
    , ST.STORE_ID
    , ST.CALENDAR_DT
    , ST.FISCAL_WEEK_NBR
    , nvl(dfsf.NET_SALES_AMT,0) AS Net_Sales  /*ODI - 2289*/
    , nvl(dfsf.TRANSACTION_CNT,0) AS Trans_Cnt  /*ODI - 2289*/
    , nvl(dfsf.NET_SALES_AMT,0) AS Comp_Sales  /*ODI - 2289*/
    , nvl(dfsf.TRANSACTION_CNT,0) AS Comp_Trans /*ODI - 2289*/
    , IFNULL(st.DMA_NM, ''UNKNOWN'') AS DMA_NAME
    , IFNULL(st.DMA_CD, ''UNKNOWN'') AS DMA_CODE
    , IFNULL(st.OWNERSHIP_TYP, ''UNKNOWN'') AS OWNERSHIP_TYPE
    , IFNULL(st.STATE_NM, ''UNKNOWN'') AS STATE
    , IFNULL(st.COUNTRY_NM, ''UNKNOWN'') AS COUNTRY
    , st.OPEN_DT
    , st.CLOSURE_DT
    , st_cl.TEMP_CLOSED_DT
    , st_cl.REOPEN_DT
    , (NOT THRESHOLD_FLG
    OR ST.THRESHOLD_FLG AND upper(THRESHOLD_FLG) IN (''Y'', ''YES'')
    OR ST.CALENDAR_DT < CURRENT_DATE - 10) as THRESHOLD_FLAG
FROM ST
LEFT OUTER JOIN  IDS_DEV.DATASTORE.DAILY_FLASH_SALES_FACT dfsf
ON  ST.STORE_ID = DFSF.STORE_ID 
and ST.brand_id = DFSF.brand_id 
AND ST.CALENDAR_DT = DFSF.BUSINESS_DT
AND (NOT THRESHOLD_FLG
    OR ST.THRESHOLD_FLG AND upper(THRESHOLD_FLG) IN (''Y'', ''YES'')
    OR ST.CALENDAR_DT < CURRENT_DATE - 10)
LEFT OUTER JOIN  IDH_QA.SHARED.STORE_SCD_PROD_V ST_CL
ON st.BRAND_ID = st_cl.BRAND_ID 
AND st.STORE_ID = st_cl.STORE_ID
AND st_cl.TEMP_CLOSED_DT IS NOT NULL
AND ST.CALENDAR_DT BETWEEN st_cl.TEMP_CLOSED_DT AND st_cl.REOPEN_DT
)
SELECT 
BRAND_ID,
STORE_ID,
CALENDAR_DT,
FISCAL_WEEK_NBR,
iff(THRESHOLD_FLAG = FALSE, NULL, Net_Sales) as Net_Sales,
iff(THRESHOLD_FLAG = FALSE, NULL, Trans_Cnt) as Trans_Cnt,
iff(THRESHOLD_FLAG = FALSE, NULL, Comp_Sales) as Comp_Sales,
iff(THRESHOLD_FLAG = FALSE, NULL, Comp_Trans) as Comp_Trans,
DMA_NAME,
DMA_CODE,
OWNERSHIP_TYPE,
STATE,
COUNTRY,
OPEN_DT,
CLOSURE_DT,
TEMP_CLOSED_DT,
REOPEN_DT,
THRESHOLD_FLAG
FROM 
RESULT 
';
