FROM ST
LEFT OUTER JOIN  IDS_DEV.DATASTORE.DAILY_FLASH_SALES_FACT_DEBUG dfsf
ON  ST.STORE_ID = DFSF.STORE_ID 
and ST.brand_id = DFSF.brand_id 
AND ST.CALENDAR_DT = DFSF.BUSINESS_DT
AND (NOT THRESHOLD_FLG
    OR ST.THRESHOLD_FLG AND upper(THRESHOLD_FLG) IN (''Y'', ''YES'')
    OR ST.CALENDAR_DT < BUSINESS_DATE - 9)
LEFT OUTER JOIN  IDH_DEV.SHARED.STORE_SCD_V ST_CL
ON st.BRAND_ID = st_cl.BRAND_ID 
AND st.STORE_ID = st_cl.STORE_ID
AND st_cl.TEMP_CLOSED_DT IS NOT NULL
AND ST.CALENDAR_DT BETWEEN st_cl.TEMP_CLOSED_DT AND st_cl.REOPEN_DT
)
SELECT 
BRAND_ID,
STORE_ID,
CALENDAR_DT,
FISCAL_WEEK_NBR,
iff(THRESHOLD_FLAG = FALSE, NULL, Net_Sales) as Net_Sales,
iff(THRESHOLD_FLAG = FALSE, NULL, Trans_Cnt) as Trans_Cnt,
iff(THRESHOLD_FLAG = FALSE, NULL, Comp_Sales) as Comp_Sales,
iff(THRESHOLD_FLAG = FALSE, NULL, Comp_Trans) as Comp_Trans,
DMA_NAME,
DMA_CODE,
OWNERSHIP_TYPE,
STATE,
COUNTRY,
OPEN_DT,
CLOSURE_DT,
TEMP_CLOSED_DT,
REOPEN_DT,
THRESHOLD_FLAG
FROM 
RESULT 

';
CREATE FUNCTION IF NOT EXISTS DAILY_FLASH_SALES_V_TEST("BUSINESS_DATE" DATE, "TIME_INTERVAL" VARCHAR(16777216), "BRAND" VARCHAR(16777216), "TRESHOLD" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BUSINESS_DT" DATE, "FISCAL_WEEK_NBR" NUMBER(38,0), "NET_SALES" NUMBER(38,2), "TRANS_CNT" NUMBER(38,0), "COMP_SALES" NUMBER(38,2), "COMP_TRANS" NUMBER(38,0), "DMA_NAME" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "OWNERSHIP_TYPE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "OPEN_DATE" DATE, "CLOSURE_DATE" DATE, "TEMP_CLOSED_DATE" DATE, "REOPEN_DATE" DATE)
LANGUAGE SQL
AS '


WITH 
TH AS (
SELECT 
sc.BUSINESS_DT,
CASE 
WHEN BRAND = ''ALL''
THEN sc.BRAND_ID
WHEN BRAND = ''ARB''
THEN ''arbys''
WHEN BRAND = ''SON''
THEN ''sonic''
WHEN BRAND = ''DUN''
THEN ''dnkn''
WHEN BRAND = ''BR''
THEN ''bskn''
WHEN BRAND = ''RT''
THEN ''rto''
ELSE BRAND
END AS BRAND_ID,
CASE 
WHEN TRESHOLD = ''N'' THEN ''N''
WHEN TRESHOLD = ''Y'' THEN ''Y''
ELSE sc.TRESHOLD_FLG END AS TRESHOLD_FLG
FROM STORE_COUNT_V sc
),

DT AS (
SELECT
DT.CALENDAR_DT,
DT.BUSINESS_DT,
DT.FISCAL_WEEK_NBR
FROM
IDS_DEV.INT_REF.COMP_DATES BDT
INNER JOIN IDS_DEV.INT_REF.COMP_CALENDAR C
ON C.CALENDAR_DT = BDT.BUSINESS_DT
INNER JOIN IDS_DEV.INT_REF.COMP_DATES DT
ON DT.TIME_INTERVAL = BDT.TIME_INTERVAL
AND BDT.BUSINESS_DT >= DT.BUSINESS_DT
AND DT.CALENDAR_DT BETWEEN least(BDT.FISCAL_YEAR_START_DT, BDT.CALENDAR_DT - iff(TIME_INTERVAL = ''CY'', 9, 16)) AND BDT.CALENDAR_DT  
WHERE BDT.BUSINESS_DT = BUSINESS_DATE
AND BDT.TIME_INTERVAL = TIME_INTERVAL
AND DT.BUSINESS_DT >= C.FISCAL_YEAR_START_DT
),

ST AS (
SELECT 
DT.CALENDAR_DT,
DT.FISCAL_WEEK_NBR,
ST.STORE_ID,
ST.BRAND_ID,
st.DMA_NM,
st.DMA_CD,
st.OWNERSHIP_TYP,
st.STATE_NM,
st.COUNTRY_NM,
st.OPEN_DT,
st.CLOSURE_DT
FROM DT
INNER JOIN IDH_DEV.SHARED.STORE_SCD_V ST   
ON DT.CALENDAR_DT BETWEEN ST.EFFECTIVE_BEGIN_DT AND ST.EFFECTIVE_END_DT
AND IFNULL(st.COUNTRY_NM, '''') IN (''US'', ''USA'')
AND (CASE WHEN lower(ST.BRAND_ID) IN (''arbys'',''arg'')
AND lower(ST.OWNERSHIP_TYP) =''franchised''
THEN 0 ELSE 1 END) = 1
INNER JOIN IDH_DEV.SHARED.STORE_SCD_V PST   
ON ST.STORE_ID = PST.STORE_ID
AND ST.BRAND_ID = PST.BRAND_ID
AND DT.BUSINESS_DT BETWEEN PST.EFFECTIVE_BEGIN_DT AND PST.EFFECTIVE_END_DT  
AND IFNULL(PST.COUNTRY_NM, '''') IN (''US'', ''USA'')
AND (CASE WHEN lower(PST.BRAND_ID) IN (''arbys'',''arg'')
AND lower(PST.OWNERSHIP_TYP) =''franchised''
THEN 0 ELSE 1 END) = 1
INNER JOIN (
        select BDT.FISCAL_YEAR_START_DT
        from IDS_DEV.INT_REF.COMP_DATES BDT
        where BDT.TIME_INTERVAL = ''CAL3Y''
        and BDT.BUSINESS_DT = BUSINESS_DATE
    ) as c3y_dt
ON nvl(ST.CLOSURE_DT, c3y_dt.FISCAL_YEAR_START_DT) >= c3y_dt.FISCAL_YEAR_START_DT
)

SELECT
      ST.BRAND_ID
    , ST.STORE_ID
    , ST.CALENDAR_DT
    , ST.FISCAL_WEEK_NBR
    , CASE WHEN TH.TRESHOLD_FLG =''N''
      THEN 0
      ELSE nvl(dfsf.NET_SALES_AMT, 0) END AS Net_Sales  /*ODI - 2289*/
    , CASE WHEN TH.TRESHOLD_FLG =''N''
      THEN 0
      ELSE iff(nvl(dfsf.NET_SALES_AMT, 0) = 0, 0, nvl(dfsf.TRANSACTION_CNT, 0)) END AS Trans_Cnt  /*ODI - 2289*/
    , CASE WHEN TH.TRESHOLD_FLG =''N''
      THEN 0
      ELSE NVL(dfsf.NET_SALES_AMT,0) END AS Comp_Sales  /*ODI - 2289*/
    , CASE WHEN TH.TRESHOLD_FLG =''N''
      THEN 0
      ELSE iff(nvl(dfsf.NET_SALES_AMT, 0) = 0, 0, dfsf.TRANSACTION_CNT) END AS Comp_Trans /*ODI - 2289*/
    , IFNULL(st.DMA_NM, ''UNKNOWN'') AS DMA_NAME
    , IFNULL(st.DMA_CD, ''UNKNOWN'') AS DMA_CODE
    , IFNULL(st.OWNERSHIP_TYP, ''UNKNOWN'') AS OWNERSHIP_TYPE
    , IFNULL(st.STATE_NM, ''UNKNOWN'') AS STATE
    , IFNULL(st.COUNTRY_NM, ''UNKNOWN'') AS COUNTRY
    , st.OPEN_DT
    , st.CLOSURE_DT
    , st_cl.TEMP_CLOSED_DT
    , st_cl.REOPEN_DT
FROM ST
INNER JOIN TH
ON LOWER(TH.BRAND_ID) = LOWER(ST.brand_id)
AND TH.BUSINESS_DT = ST.CALENDAR_DT
LEFT OUTER JOIN  IDS_DEV.DATASTORE.DAILY_FLASH_SALES_FACT dfsf
ON  ST.STORE_ID = DFSF.STORE_ID 
and ST.brand_id = DFSF.brand_id 
AND ST.CALENDAR_DT = DFSF.BUSINESS_DT
LEFT OUTER JOIN  IDH_DEV.SHARED.STORE_SCD_V ST_CL
ON st.BRAND_ID = st_cl.BRAND_ID 
AND st.STORE_ID = st_cl.STORE_ID
AND st_cl.TEMP_CLOSED_DT IS NOT NULL
AND ST.CALENDAR_DT BETWEEN st_cl.TEMP_CLOSED_DT AND st_cl.REOPEN_DT

';
CREATE FUNCTION IF NOT EXISTS DAILY_FLASH_SALES_V_WITHOUT_THRESHOLD("BUSINESS_DATE" DATE, "TIME_INTERVAL" VARCHAR(16777216), "BRAND" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BUSINESS_DT" DATE, "FISCAL_WEEK_NBR" NUMBER(38,0), "NET_SALES" NUMBER(38,2), "TRANS_CNT" NUMBER(38,0), "COMP_SALES" NUMBER(38,2), "COMP_TRANS" NUMBER(38,0), "DMA_NAME" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "OWNERSHIP_TYPE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "OPEN_DATE" DATE, "CLOSURE_DATE" DATE, "TEMP_CLOSED_DATE" DATE, "REOPEN_DATE" DATE, "THRESHOLD_FLAG" BOOLEAN)
LANGUAGE SQL
AS '


WITH 
DT AS (
SELECT
DT.CALENDAR_DT,
DT.BUSINESS_DT,
DT.FISCAL_WEEK_NBR
FROM
IDS_DEV.INT_REF.COMP_DATES BDT
INNER JOIN IDS_DEV.INT_REF.COMP_CALENDAR C
ON C.CALENDAR_DT = BDT.BUSINESS_DT
INNER JOIN IDS_DEV.INT_REF.COMP_DATES DT
ON DT.TIME_INTERVAL = BDT.TIME_INTERVAL
AND BDT.BUSINESS_DT >= DT.BUSINESS_DT
AND DT.CALENDAR_DT BETWEEN least(BDT.FISCAL_YEAR_START_DT, BDT.CALENDAR_DT - iff(TIME_INTERVAL = ''CY'', 9, 16)) AND BDT.CALENDAR_DT  
WHERE BDT.BUSINESS_DT = BUSINESS_DATE
AND BDT.TIME_INTERVAL = TIME_INTERVAL
qualify row_number() over (partition by DT.CALENDAR_DT order by DT.BUSINESS_DT desc) = 1
),

ST AS (
SELECT 
DT.CALENDAR_DT,
DT.FISCAL_WEEK_NBR,
ST.STORE_ID,
ST.BRAND_ID,
ST_SCD.DMA_NM,
ST_SCD.DMA_CD,
ST_SCD.OWNERSHIP_TYP,
st.STATE_NM,
st.COUNTRY_NM,
st.OPEN_DT,
ST_SCD.CLOSURE_DT
FROM DT
INNER JOIN IDH_DEV.SHARED.STORE_SCD_V ST
ON ST.CURRENT_IND = 1
AND IFNULL(st.COUNTRY_NM, '''') IN (''US'', ''USA'')
AND (CASE WHEN lower(ST.BRAND_ID) IN (''arbys'',''arg'')
AND lower(ST.OWNERSHIP_TYP) =''franchised''
THEN 0 ELSE 1 END) = 1
AND (CASE WHEN UPPER(ST.BRAND_ID) IN (''ARG'',''ARBYS'') THEN ''ARB''
       WHEN UPPER(ST.BRAND_ID) IN (''BWW'') THEN ''BWW''
       WHEN UPPER(ST.BRAND_ID) IN (''SDI'',''SONIC'') THEN ''SON''
       WHEN UPPER(ST.BRAND_ID) IN (''JJ'') THEN ''JJ''
       WHEN UPPER(ST.BRAND_ID) IN (''DNKN'') THEN ''DUN''
       WHEN UPPER(ST.BRAND_ID) IN (''BSKN'') THEN ''BR''
       WHEN UPPER(ST.BRAND_ID) IN (''RTO'') THEN ''RT''
       ELSE ''UNKNOWN''
       END = BRAND
    OR UPPER(BRAND) IN (''ALL'', ''*''))
LEFT JOIN IDH_DEV.SHARED.STORE_SCD_V ST_SCD
ON DT.CALENDAR_DT BETWEEN ST_SCD.EFFECTIVE_BEGIN_DT AND ST_SCD.EFFECTIVE_END_DT
AND ST_SCD.STORE_ID = ST.STORE_ID
AND ST_SCD.BRAND_ID = ST.BRAND_ID
AND IFNULL(ST_SCD.COUNTRY_NM, '''') IN (''US'', ''USA'')
AND (CASE WHEN lower(ST_SCD.BRAND_ID) IN (''arbys'',''arg'')
AND lower(ST_SCD.OWNERSHIP_TYP) =''franchised''
THEN 0 ELSE 1 END) = 1
LEFT JOIN IDH_DEV.SHARED.STORE_SCD_V PST
ON ST.STORE_ID = PST.STORE_ID
AND ST.BRAND_ID = PST.BRAND_ID
AND DT.BUSINESS_DT BETWEEN PST.EFFECTIVE_BEGIN_DT AND PST.EFFECTIVE_END_DT
AND IFNULL(PST.COUNTRY_NM, '''') IN (''US'', ''USA'')
AND (CASE WHEN lower(PST.BRAND_ID) IN (''arbys'',''arg'')
AND lower(PST.OWNERSHIP_TYP) =''franchised''
THEN 0 ELSE 1 END) = 1
INNER JOIN (
        select BDT.FISCAL_YEAR_START_DT
        from IDS_DEV.INT_REF.COMP_DATES BDT
        where BDT.TIME_INTERVAL = ''CAL3Y''
        and BDT.BUSINESS_DT = BUSINESS_DATE
    ) as c3y_dt
ON coalesce(ST_SCD.CLOSURE_DT, ST.CLOSURE_DT, c3y_dt.FISCAL_YEAR_START_DT) >= c3y_dt.FISCAL_YEAR_START_DT
)

SELECT
      ST.BRAND_ID
    , ST.STORE_ID
    , ST.CALENDAR_DT
    , ST.FISCAL_WEEK_NBR
    , nvl(dfsf.NET_SALES_AMT, 0) AS Net_Sales  /*ODI - 2289*/
    , iff(nvl(dfsf.NET_SALES_AMT, 0) = 0, 0, nvl(dfsf.TRANSACTION_CNT, 0)) AS Trans_Cnt  /*ODI - 2289*/
    , NVL(dfsf.NET_SALES_AMT,0) AS Comp_Sales  /*ODI - 2289*/
    , iff(nvl(dfsf.NET_SALES_AMT, 0) = 0, 0, dfsf.TRANSACTION_CNT) AS Comp_Trans /*ODI - 2289*/
    , IFNULL(st.DMA_NM, ''UNKNOWN'') AS DMA_NAME
    , IFNULL(st.DMA_CD, ''UNKNOWN'') AS DMA_CODE
    , IFNULL(st.OWNERSHIP_TYP, ''UNKNOWN'') AS OWNERSHIP_TYPE
    , IFNULL(st.STATE_NM, ''UNKNOWN'') AS STATE
    , IFNULL(st.COUNTRY_NM, ''UNKNOWN'') AS COUNTRY
    , st.OPEN_DT
    , st.CLOSURE_DT
    , st_cl.TEMP_CLOSED_DT
    , st_cl.REOPEN_DT
    , NULL
FROM ST
LEFT OUTER JOIN  IDS_DEV.DATASTORE.DAILY_FLASH_SALES_FACT dfsf
ON  ST.STORE_ID = DFSF.STORE_ID 
and ST.brand_id = DFSF.brand_id 
AND ST.CALENDAR_DT = DFSF.BUSINESS_DT
LEFT OUTER JOIN  IDH_DEV.SHARED.STORE_SCD_V ST_CL
ON st.BRAND_ID = st_cl.BRAND_ID 
AND st.STORE_ID = st_cl.STORE_ID
AND st_cl.TEMP_CLOSED_DT IS NOT NULL
AND ST.CALENDAR_DT BETWEEN st_cl.TEMP_CLOSED_DT AND st_cl.REOPEN_DT

';
CREATE FUNCTION IF NOT EXISTS DAYPART_FLASH_INIT("DATE_FROM" DATE, "DATE_TO" DATE, "AGG_LEVEL" VARCHAR(16777216), "TIME_INTERVAL" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BRAND_DAY_PART_NM" VARCHAR(16777216), "IRB_DAY_PART_NM" VARCHAR(16777216), "CLOSED_HR" TIME(9), "BUSINESS_DT" DATE, "FISCAL_WEEK_START_DT" DATE, "FISCAL_YEAR_NBR" NUMBER(38,0), "FISCAL_QUARTER_NBR" NUMBER(38,0), "FISCAL_PERIOD_NBR" NUMBER(38,0), "FISCAL_WEEK_NBR" NUMBER(38,0), "CALENDAR_DAY_NM" VARCHAR(16777216), "HOLIDAY_IND" NUMBER(38,0), "HOLIDAY_NM" VARCHAR(16777216), "NET_SALES" NUMBER(38,2), "TRANS_CNT" NUMBER(38,0), "DMA_NAME" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "ADDRESS_1" VARCHAR(16777216), "ADDRESS_2" VARCHAR(16777216), "CITY" VARCHAR(16777216), "ZIP_CD" VARCHAR(16777216), "WEEKDAY_OFFSET" ARRAY, "WEEK_TRANS_CNTS" ARRAY, "WEEK_NET_SALES" ARRAY, "CHANNEL_ID" VARCHAR(16777216), "OPEN_15P_FLAG" BOOLEAN, "OPEN_AFTER_HONEYMOON_FLAG" BOOLEAN, "IS_XMAS_THANKSGIVING" BOOLEAN, "STORE_CNT" NUMBER(38,0), "COMP_STORE_CNT" NUMBER(38,0), "ADD_NULL_WEEK" BOOLEAN)
LANGUAGE SQL
AS '

    SELECT * FROM table(DAYPART_FLASH_INIT(DATE_FROM, DATE_TO, AGG_LEVEL, TIME_INTERVAL, ''ALL''))

';
CREATE FUNCTION IF NOT EXISTS DAYPART_FLASH_INIT("DATE_FROM" DATE, "DATE_TO" DATE, "AGG_LEVEL" VARCHAR(16777216), "TIME_INTERVAL" VARCHAR(16777216), "BRAND_INPUT" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BRAND_DAY_PART_NM" VARCHAR(16777216), "IRB_DAY_PART_NM" VARCHAR(16777216), "CLOSED_HR" TIME(9), "BUSINESS_DT" DATE, "FISCAL_WEEK_START_DT" DATE, "FISCAL_YEAR_NBR" NUMBER(38,0), "FISCAL_QUARTER_NBR" NUMBER(38,0), "FISCAL_PERIOD_NBR" NUMBER(38,0), "FISCAL_WEEK_NBR" NUMBER(38,0), "CALENDAR_DAY_NM" VARCHAR(16777216), "HOLIDAY_IND" NUMBER(38,0), "HOLIDAY_NM" VARCHAR(16777216), "NET_SALES" NUMBER(38,2), "TRANS_CNT" NUMBER(38,0), "DMA_NAME" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "ADDRESS_1" VARCHAR(16777216), "ADDRESS_2" VARCHAR(16777216), "CITY" VARCHAR(16777216), "ZIP_CD" VARCHAR(16777216), "WEEKDAY_OFFSET" ARRAY, "WEEK_TRANS_CNTS" ARRAY, "WEEK_NET_SALES" ARRAY, "CHANNEL_ID" VARCHAR(16777216), "OPEN_15P_FLAG" BOOLEAN, "OPEN_AFTER_HONEYMOON_FLAG" BOOLEAN, "IS_XMAS_THANKSGIVING" BOOLEAN, "STORE_CNT" NUMBER(38,0), "COMP_STORE_CNT" NUMBER(38,0), "ADD_NULL_WEEK" BOOLEAN)
LANGUAGE SQL
AS '

with a as
(  
    select
    DATE_FROM,
    DATE_TO,
    AGG_LEVEL,
    TIME_INTERVAL,
    CALENDAR_DT,
    MAX_OPEN_DT,
    MAX_HONEY_DT
    FROM table(FLASH_SUMMARY_COMP_HONEYMOON(DATE_FROM, DATE_TO, TIME_INTERVAL)) as honeymoon
), CLOSED_HOURS as
(
    SELECT CLOSED_HR AS CLOSED_HOUR
    FROM    
    IDS_DEV.INT_REF.CLOSED_HOUR
    WHERE AGG_LEVEL IN (''DAY_PART'', ''WEEK_CHANNEL'')
          AND TIME_INTERVAL = ''CY''
), chs as (
    SELECT DISTINCT CHANNEL_ID, STORE_ID, BRAND_ID
    FROM IDS_DEV.DATASTORE.DAILY_DAY_PART_FLASH_SALES_FACT as dfsf
    WHERE AGG_LEVEL IN (''WEEK_CHANNEL'', ''DAY_CHANNEL'') 
    AND TIME_INTERVAL = ''CY''
    AND (CASE WHEN UPPER(dfsf.BRAND_ID) IN (''ARG'',''ARBYS'') THEN ''ARB''
       WHEN UPPER(dfsf.BRAND_ID) IN (''BWW'') THEN ''BWW''
       WHEN UPPER(dfsf.BRAND_ID) IN (''SDI'',''SONIC'') THEN ''SON''
       WHEN UPPER(dfsf.BRAND_ID) IN (''JJ'') THEN ''JJ''
       WHEN UPPER(dfsf.BRAND_ID) IN (''DNKN'') THEN ''DUN''
       WHEN UPPER(dfsf.BRAND_ID) IN (''BSKN'') THEN ''BR''
       WHEN UPPER(dfsf.BRAND_ID) IN (''RTO'') THEN ''RT''
       ELSE ''UNKNOWN''
       END = BRAND_INPUT
    OR UPPER(BRAND_INPUT) IN (''ALL'', ''*''))
),
DT as (
SELECT
DT.CALENDAR_DT,
DT.DATE_KEY,
DT.FISCAL_YEAR_NBR,
DT.FISCAL_QUARTER_NBR,
DT.FISCAL_PERIOD_NBR,
DT.FISCAL_WEEK_NBR,
DT.CALENDAR_DAY_NM,
DT.FISCAL_WEEK_START_DT,
MAX_OPEN_DT,
MAX_HONEY_DT
FROM a
INNER join
IDH_DEV.SHARED.DATE_DIM_V DT
on DT.CALENDAR_DT = a.CALENDAR_DT
),
OT as (
SELECT 
BRAND_ID,
STORE_ID,
OWNERSHIP_TYP,
ST.DMA_NM,
ST.DMA_CD,
FISCAL_WEEK_START_DT
FROM DT
INNER JOIN IDH_DEV.SHARED.STORE_SCD_V ST  
ON DT.CALENDAR_DT BETWEEN ST.EFFECTIVE_BEGIN_DT AND ST.EFFECTIVE_END_DT
AND IFNULL(st.COUNTRY_NM, '''') in (''US'', ''USA'')
    AND (CASE WHEN UPPER(ST.BRAND_ID) IN (''ARG'',''ARBYS'') THEN ''ARB''
       WHEN UPPER(ST.BRAND_ID) IN (''BWW'') THEN ''BWW''
       WHEN UPPER(ST.BRAND_ID) IN (''SDI'',''SONIC'') THEN ''SON''
       WHEN UPPER(ST.BRAND_ID) IN (''JJ'') THEN ''JJ''
       WHEN UPPER(ST.BRAND_ID) IN (''DNKN'') THEN ''DUN''
       WHEN UPPER(ST.BRAND_ID) IN (''BSKN'') THEN ''BR''
       WHEN UPPER(ST.BRAND_ID) IN (''RTO'') THEN ''RT''
       ELSE ''UNKNOWN''
       END = BRAND_INPUT
    OR UPPER(BRAND_INPUT) IN (''ALL'', ''*''))
QUALIFY ROW_NUMBER() OVER (PARTITION BY STORE_ID, BRAND_ID, FISCAL_WEEK_START_DT ORDER BY CALENDAR_DT DESC) = 1
),
ST as (
SELECT
distinct
DT.CALENDAR_DT,
DT.FISCAL_YEAR_NBR,
DT.FISCAL_QUARTER_NBR,
DT.FISCAL_PERIOD_NBR,
DT.FISCAL_WEEK_NBR,
DT.CALENDAR_DAY_NM,
DT.FISCAL_WEEK_START_DT,
DT.DATE_KEY,
ST.STORE_ID,
ST.BRAND_ID,
CASE WHEN AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'')
THEN ot.DMA_NM ELSE STDAY.DMA_NM END AS DMA_NM,
CASE WHEN AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'')
THEN ot.DMA_CD ELSE STDAY.DMA_CD END AS DMA_CD,
CASE WHEN AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'')
THEN ot.OWNERSHIP_TYP
ELSE STDAY.OWNERSHIP_TYP END AS OWNERSHIP_TYP,
st.STATE_NM,
st.COUNTRY_NM,
st.ADDRESS_1_TXT,
st.ADDRESS_2_TXT,
st.CITY_NM,
st.ZIP_CD,
nvl(ST.OPEN_DT, DT.MAX_OPEN_DT) <= DT.MAX_OPEN_DT as OPEN_15P_FLAG, -- ODI-53
nvl(ST.OPEN_DT, DT.MAX_HONEY_DT) <= DT.MAX_HONEY_DT as OPEN_AFTER_HONEYMOON_FLAG, -- ODI-199
CLOSED_HOURS.CLOSED_HOUR,
chs.CHANNEL_ID,
iff(nvl(hol.HOLIDAY_IND, false), 1, 0) as HOLIDAY_IND,
nvl(hol.HOLIDAY_LIST_NM, '''') as HOLIDAY_NM,
nvl(
        (ARRAY_CONTAINS(cast(''THANKSGIVING DAY'' as variant), split(hol.HOLIDAY_LIST_NM, '', ''))
         OR ARRAY_CONTAINS(cast(''CHRISTMAS DAY'' as variant), split(hol.HOLIDAY_LIST_NM, '', '')))
        , FALSE) as IS_XMAS_THANKSGIVING
FROM DT
INNER JOIN IDH_DEV.SHARED.STORE_SCD_V ST  
ON CURRENT_IND = 1
AND IFNULL(st.COUNTRY_NM, '''') in (''US'', ''USA'')
LEFT JOIN OT
ON OT.BRAND_ID = ST.BRAND_ID
AND OT.STORE_ID = ST.STORE_ID
AND OT.FISCAL_WEEK_START_DT = DT.FISCAL_WEEK_START_DT
LEFT JOIN IDH_DEV.SHARED.STORE_SCD_V STDAY  
ON DT.CALENDAR_DT BETWEEN STDAY.EFFECTIVE_BEGIN_DT AND STDAY.EFFECTIVE_END_DT
AND STDAY.BRAND_ID = ST.BRAND_ID
AND STDAY.STORE_ID = ST.STORE_ID
AND IFNULL(STDAY.COUNTRY_NM, '''') in (''US'', ''USA'')
INNER JOIN (
        select BDT.FISCAL_YEAR_START_DT
        from IDS_DEV.INT_REF.COMP_DATES BDT
        where BDT.TIME_INTERVAL = ''CAL3Y''
        and BDT.BUSINESS_DT = DATE_FROM
    ) as c3y_dt
ON nvl(ST.CLOSURE_DT, c3y_dt.FISCAL_YEAR_START_DT) >= c3y_dt.FISCAL_YEAR_START_DT
INNER JOIN (select distinct STORE_ID, BRAND_ID from IDS_DEV.DATASTORE.DAILY_DAY_PART_FLASH_SALES_FACT as f
        where CASE WHEN UPPER(f.BRAND_ID) IN (''ARG'',''ARBYS'') THEN ''ARB''
            WHEN UPPER(f.BRAND_ID) IN (''BWW'') THEN ''BWW''
            WHEN UPPER(f.BRAND_ID) IN (''SDI'',''SONIC'') THEN ''SON''
            WHEN UPPER(f.BRAND_ID) IN (''JJ'') THEN ''JJ''
            WHEN UPPER(f.BRAND_ID) IN (''DNKN'') THEN ''DUN''
            WHEN UPPER(f.BRAND_ID) IN (''BSKN'') THEN ''BR''
            WHEN UPPER(f.BRAND_ID) IN (''RTO'') THEN ''RT''
            ELSE ''UNKNOWN''
            END = BRAND_INPUT
        OR UPPER(BRAND_INPUT) IN (''ALL'', ''*'')
    ) as dpsf
on ST.store_ID = dpsf.STORE_ID
and ST.BRAND_ID = dpsf.BRAND_ID
LEFT JOIN CLOSED_HOURS
ON  1 = 1
LEFT JOIN chs
ON  chs.STORE_ID = ST.STORE_ID
AND chs.BRAND_ID = ST.BRAND_ID
LEFT JOIN IDH_DEV.SHARED.HOLIDAY_LIST_V as hol
ON DT.DATE_KEY = hol.DATE_KEY
),
FINAL AS (
SELECT
    ST.BRAND_ID
    , ST.STORE_ID
    , dpsf.BRAND_DAY_PART_NM as BRAND_DAY_PART_NM
    , dpsf.IRB_DAY_PART_NM as IRB_DAY_PART_NM
    , CASE
        WHEN AGG_LEVEL in (''DAY_PART'', ''WEEK_CHANNEL'') AND TIME_INTERVAL = ''CY'' THEN ST.CLOSED_HOUR
        WHEN AGG_LEVEL in (''DAY_PART'', ''WEEK_CHANNEL'') AND TIME_INTERVAL <> ''CY'' THEN dpsf.CLOSED_HR
    ELSE null
    END AS CLOSED_HR
    , CASE
        WHEN AGG_LEVEL in (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') THEN ST.CALENDAR_DT
    ELSE null
    END AS BUSINESS_DT
    , CASE
        WHEN AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'') THEN ST.FISCAL_WEEK_START_DT
    ELSE null
    END AS FISCAL_WEEK_START_DT
    , ST.FISCAL_YEAR_NBR as FISCAL_YEAR_NBR
    , ST.FISCAL_QUARTER_NBR as FISCAL_QUARTER_NBR
    , ST.FISCAL_PERIOD_NBR as FISCAL_PERIOD_NBR
    , ST.FISCAL_WEEK_NBR as FISCAL_WEEK_NBR
    , ST.CALENDAR_DAY_NM as CALENDAR_DAY_NM
    , CASE WHEN AGG_LEVEL in (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') THEN ST.HOLIDAY_IND ELSE NULL END AS HOLIDAY_IND
    , CASE WHEN AGG_LEVEL in (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') THEN ST.HOLIDAY_NM ELSE NULL END AS HOLIDAY_NM
    , sum(nvl(dpsf.NET_SALES_AMT, 0)) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,
        CASE WHEN AGG_LEVEL IN (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') 
        THEN ST.CALENDAR_DT
        WHEN AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'') THEN ST.FISCAL_WEEK_START_DT
        ELSE null END,
        CASE
        WHEN AGG_LEVEL IN (''DAY_PART'', ''WEEK_CHANNEL'') AND TIME_INTERVAL = ''CY'' THEN ST.CLOSED_HOUR
        WHEN AGG_LEVEL IN (''DAY_PART'', ''WEEK_CHANNEL'') AND TIME_INTERVAL <> ''CY'' THEN dpsf.CLOSED_HR
        ELSE null END,
        CASE
        WHEN AGG_LEVEL IN (''WEEK_CHANNEL'', ''DAY_CHANNEL'') AND TIME_INTERVAL = ''CY'' THEN ST.CHANNEL_ID
        WHEN AGG_LEVEL IN (''WEEK_CHANNEL'', ''DAY_CHANNEL'') AND TIME_INTERVAL <> ''CY'' THEN dpsf.CHANNEL_ID
        ELSE null END) as Net_Sales
    , sum(iff(nvl(dpsf.NET_SALES_AMT,0) = 0,0, nvl(dpsf.TRX_CNT,0))) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,
        CASE WHEN AGG_LEVEL IN (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') 
        THEN ST.CALENDAR_DT
        WHEN AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'') THEN ST.FISCAL_WEEK_START_DT
        ELSE null END,
        CASE
        WHEN AGG_LEVEL IN (''DAY_PART'', ''WEEK_CHANNEL'') AND TIME_INTERVAL = ''CY'' THEN ST.CLOSED_HOUR
        WHEN AGG_LEVEL IN (''DAY_PART'', ''WEEK_CHANNEL'') AND TIME_INTERVAL <> ''CY'' THEN dpsf.CLOSED_HR
        ELSE null END,
        CASE
        WHEN AGG_LEVEL IN (''WEEK_CHANNEL'', ''DAY_CHANNEL'') AND TIME_INTERVAL = ''CY'' THEN ST.CHANNEL_ID
        WHEN AGG_LEVEL IN (''WEEK_CHANNEL'', ''DAY_CHANNEL'') AND TIME_INTERVAL <> ''CY'' THEN dpsf.CHANNEL_ID
        ELSE null END ) as Trans_Cnt
    , IFNULL(st.DMA_NM, ''UNKNOWN'') AS DMA_NAME
    , IFNULL(st.DMA_CD, ''UNKNOWN'') AS DMA_CODE
    , IFNULL(st.OWNERSHIP_TYP, ''UNKNOWN'') AS OWNERSHIP_TYP
    , IFNULL(st.STATE_NM, ''UNKNOWN'') AS STATE
    , IFNULL(st.COUNTRY_NM, ''UNKNOWN'') AS COUNTRY
    , IFNULL(st.ADDRESS_1_TXT, ''UNKNOWN'') AS ADDRESS_1
    , IFNULL(st.ADDRESS_2_TXT, ''UNKNOWN'') AS ADDRESS_2  
    , IFNULL(st.CITY_NM, ''UNKNOWN'') AS CITY
    , IFNULL(st.ZIP_CD, ''UNKNOWN'') AS ZIP_CD
    , CASE
        WHEN AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'') 
        THEN ARRAY_AGG(ST.CALENDAR_DT - ST.FISCAL_WEEK_START_DT) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,ST.FISCAL_WEEK_START_DT)
    ELSE null
    END AS WEEKDAY_OFFSET --ODI-2977
    , CASE
        WHEN AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'') 
        THEN ARRAY_AGG(dpsf.TRX_CNT) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,ST.FISCAL_WEEK_START_DT)
    ELSE null
    END AS WEEK_TRANS_CNTS --ODI-2977
    , CASE
        WHEN AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'') 
        THEN ARRAY_AGG(dpsf.NET_SALES_AMT) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,ST.FISCAL_WEEK_START_DT)
    ELSE null
    END AS WEEK_NET_SALES --ODI-2977
    , CASE
        WHEN AGG_LEVEL IN (''WEEK_CHANNEL'', ''DAY_CHANNEL'') AND TIME_INTERVAL = ''CY'' THEN ST.CHANNEL_ID
        WHEN AGG_LEVEL IN (''WEEK_CHANNEL'', ''DAY_CHANNEL'') AND TIME_INTERVAL <> ''CY'' THEN dpsf.CHANNEL_ID
    ELSE null
    END AS CHANNEL_ID
    , ST.OPEN_15P_FLAG as OPEN_15P_FLAG1
    , ST.OPEN_AFTER_HONEYMOON_FLAG as OPEN_AFTER_HONEYMOON_FLAG1
    , MAX(ST.IS_XMAS_THANKSGIVING) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,
        CASE WHEN AGG_LEVEL IN (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') 
        THEN ST.CALENDAR_DT
        WHEN AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'') THEN ST.FISCAL_WEEK_START_DT
        ELSE null END) AS IS_XMAS_THANKSGIVING1
    , CASE
        WHEN sum(nvl(dpsf.NET_SALES_AMT, 0)) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,
        CASE WHEN AGG_LEVEL IN (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') 
        THEN ST.CALENDAR_DT
        WHEN AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'') THEN ST.FISCAL_WEEK_START_DT
        ELSE null
        END ) = 0
        THEN 0 ELSE 1 END as STORE_CNT
    , CASE
        WHEN sum(nvl(dpsf.NET_SALES_AMT, 0)) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,
        CASE WHEN AGG_LEVEL IN (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') 
        THEN ST.CALENDAR_DT
        WHEN AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'') THEN ST.FISCAL_WEEK_START_DT
        ELSE null
        END ) = 0 and AGG_LEVEL IN (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') AND not IS_XMAS_THANKSGIVING1 THEN 0 
        
        WHEN sum(nvl(dpsf.NET_SALES_AMT, 0)) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,
        CASE WHEN AGG_LEVEL IN (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') 
        THEN ST.CALENDAR_DT
        WHEN AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'') THEN ST.FISCAL_WEEK_START_DT
        ELSE null
        END ) = 0 and AGG_LEVEL IN (''WEEK'', ''WEEK_CHANNEL'') THEN 0
            
        WHEN TIME_INTERVAL = ''CY'' AND (NOT OPEN_AFTER_HONEYMOON_FLAG1 OR NOT OPEN_15P_FLAG1)
        THEN 0
        WHEN TIME_INTERVAL <> ''CY'' AND NOT OPEN_AFTER_HONEYMOON_FLAG1
        THEN 0
        ELSE 1
    END                                     as COMP_STORE_CNT
    , AGG_LEVEL = ''WEEK_CHANNEL'' AND TIME_INTERVAL = ''CY''
        AND sum(1) over (PARTITION BY ST.BRAND_ID, ST.STORE_ID,
                    CASE
                        WHEN AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'') THEN ST.FISCAL_WEEK_START_DT
                    ELSE null
                    END)
            
                * CASE WHEN dpsf.CHANNEL_ID is null
                        THEN -1 ELSE 1 END
                = -1
                                            as ADD_NULL_WEEK
FROM
    (select distinct AGG_LEVEL from a) as agg
    , IDS_DEV.DATASTORE.DAILY_DAY_PART_FLASH_SALES_FACT as dpsf
RIGHT JOIN ST
ON  ST.STORE_ID = dpsf.STORE_ID
and ST.brand_id = dpsf.brand_id
AND ST.CALENDAR_DT = dpsf.BUSINESS_DT
AND CASE
        WHEN AGG_LEVEL in (''DAY_PART'', ''WEEK_CHANNEL'') AND TIME_INTERVAL = ''CY''
        THEN nvl(dpsf.CLOSED_HR, ST.CLOSED_HOUR) = ST.CLOSED_HOUR
        WHEN AGG_LEVEL in (''DAY_PART'', ''WEEK_CHANNEL'') AND TIME_INTERVAL <> ''CY''
        THEN dpsf.CLOSED_HR is not null
    ELSE true END
AND CASE
        WHEN AGG_LEVEL IN (''WEEK_CHANNEL'', ''DAY_CHANNEL'') AND TIME_INTERVAL = ''CY''
        THEN nvl(dpsf.CHANNEL_ID, ST.CHANNEL_ID) = ST.CHANNEL_ID
        WHEN AGG_LEVEL IN (''WEEK_CHANNEL'', ''DAY_CHANNEL'') AND TIME_INTERVAL <> ''CY''
        THEN dpsf.CHANNEL_ID is not null
    ELSE true END
WHERE AGG_LEVEL = ''DAY_PART'' AND (TIME_INTERVAL = ''CY'' AND nvl(dpsf.CLOSED_HR, ST.CLOSED_HOUR) = ST.CLOSED_HOUR
                                                         OR TIME_INTERVAL <> ''CY'' AND dpsf.CLOSED_HR is not null)
    OR AGG_LEVEL IN (''WEEK_CHANNEL'', ''DAY_CHANNEL'') 
    OR AGG_LEVEL IN (''DAY'', ''WEEK'')
)
SELECT * FROM FINAL
QUALIFY ROW_NUMBER() OVER (PARTITION BY STORE_ID, BRAND_ID, CASE WHEN AGG_LEVEL IN (''WEEK_CHANNEL'',''WEEK'') THEN FISCAL_WEEK_START_DT ELSE BUSINESS_DT END, CHANNEL_ID, CLOSED_HR ORDER BY CASE WHEN AGG_LEVEL IN (''WEEK_CHANNEL'',''WEEK'') THEN FISCAL_WEEK_START_DT ELSE BUSINESS_DT END ) = 1

';
CREATE FUNCTION IF NOT EXISTS DAYPART_FLASH_SUMMARY("FROM_DATE" DATE, "TO_DATE" DATE, "AGG_LEVEL" VARCHAR(16777216))
RETURNS TABLE ("AGG_LEVEL" VARCHAR(16777216), "BUSINESS_DATE" DATE, "WEEK_START_DT" DATE, "WEEK_END_DT" DATE, "BRAND_DAYPART" VARCHAR(16777216), "IRB_DAYPART" VARCHAR(16777216), "CLOSED_HOUR" TIME(9), "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "DMA_NAME" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "ADDRESS_1" VARCHAR(16777216), "ADDRESS_2" VARCHAR(16777216), "CITY" VARCHAR(16777216), "ZIP_CODE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "CHANNEL_ID" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "DAY_OF_WEEK" VARCHAR(16777216), "HOLIDAY_IND_CY" NUMBER(38,0), "HOLIDAY_NM_CY" VARCHAR(16777216), "NET_SALES_CY" NUMBER(38,2), "TRANS_CY" NUMBER(38,0), "AVG_CHECK_CY" NUMBER(38,2), "STORE_CNT_CY" NUMBER(38,0), "COMP_SALES_CY" NUMBER(38,2), "COMP_TRANS_CY" NUMBER(38,0), "COMP_AVG_CHECK_CY" NUMBER(38,2), "COMP_STORE_CNT_CY" NUMBER(38,0), "FISC_DATE_LY" DATE, "FISC_WEEK_START_DT_LY" DATE, "FISC_WEEK_END_DT_LY" DATE, "FISC_HOLIDAY_IND_LY" NUMBER(38,0), "FISC_HOLIDAY_NM_LY" VARCHAR(16777216), "FISC_NET_SALES_LY" NUMBER(38,2), "FISC_TRANS_LY" NUMBER(38,0), "FISC_AVG_CHECK_LY" NUMBER(38,2), "FISC_STORE_CNT_LY" NUMBER(38,0), "FISC_COMP_SALES_LY" NUMBER(38,2), "FISC_COMP_TRANS_LY" NUMBER(38,0), "FISC_COMP_AVG_CHECK_LY" NUMBER(38,2), "FISC_COMP_STORE_CNT_LY" NUMBER(38,0), "CAL_COMP_DATE_LY" DATE, "CAL_WEEK_START_DT_LY" DATE, "CAL_WEEK_END_DT_LY" DATE, "CAL_HOLIDAY_IND_LY" NUMBER(38,0), "CAL_HOLIDAY_NM_LY" VARCHAR(16777216), "CAL_NET_SALES_LY" NUMBER(38,2), "CAL_TRANS_LY" NUMBER(38,0), "CAL_AVG_CHECK_LY" NUMBER(38,2), "CAL_STORE_CNT_LY" NUMBER(38,0), "CAL_COMP_SALES_LY" NUMBER(38,2), "CAL_COMP_TRANS_LY" NUMBER(38,0), "CAL_COMP_AVG_CHECK_LY" NUMBER(38,2), "CAL_COMP_STORE_CNT_LY" NUMBER(38,0), "CAL_COMP_DATE_2Y" DATE, "CAL_WEEK_START_DT_2Y" DATE, "CAL_WEEK_END_DT_2Y" DATE, "CAL_HOLIDAY_IND_2Y" NUMBER(38,0), "CAL_HOLIDAY_NM_2Y" VARCHAR(16777216), "CAL_NET_SALES_2Y" NUMBER(38,2), "CAL_TRANS_2Y" NUMBER(38,0), "CAL_AVG_CHECK_2Y" NUMBER(38,2), "CAL_STORE_CNT_2Y" NUMBER(38,0), "CAL_COMP_SALES_2Y" NUMBER(38,2), "CAL_COMP_TRANS_2Y" NUMBER(38,0), "CAL_COMP_AVG_CHECK_2Y" NUMBER(38,2), "CAL_COMP_STORE_CNT_2Y" NUMBER(38,0), "CAL_COMP_DATE_3Y" DATE, "CAL_WEEK_START_DT_3Y" DATE, "CAL_WEEK_END_DT_3Y" DATE, "CAL_HOLIDAY_IND_3Y" NUMBER(38,0), "CAL_HOLIDAY_NM_3Y" VARCHAR(16777216), "CAL_NET_SALES_3Y" NUMBER(38,2), "CAL_TRANS_3Y" NUMBER(38,0), "CAL_AVG_CHECK_3Y" NUMBER(38,2), "CAL_STORE_CNT_3Y" NUMBER(38,0), "CAL_COMP_SALES_3Y" NUMBER(38,2), "CAL_COMP_TRANS_3Y" NUMBER(38,0), "CAL_COMP_AVG_CHECK_3Y" NUMBER(38,2), "CAL_COMP_STORE_CNT_3Y" NUMBER(38,0))
LANGUAGE SQL
AS '

SELECT * FROM table(DAYPART_FLASH_SUMMARY(FROM_DATE, TO_DATE, AGG_LEVEL, ''ALL''))

';
CREATE FUNCTION IF NOT EXISTS DAYPART_FLASH_SUMMARY("FROM_DATE" DATE, "TO_DATE" DATE, "AGG_LEVEL" VARCHAR(16777216), "BRAND_INPUT" VARCHAR(16777216))
RETURNS TABLE ("AGG_LEVEL" VARCHAR(16777216), "BUSINESS_DATE" DATE, "WEEK_START_DT" DATE, "WEEK_END_DT" DATE, "BRAND_DAYPART" VARCHAR(16777216), "IRB_DAYPART" VARCHAR(16777216), "CLOSED_HOUR" TIME(9), "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "DMA_NAME" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "ADDRESS_1" VARCHAR(16777216), "ADDRESS_2" VARCHAR(16777216), "CITY" VARCHAR(16777216), "ZIP_CODE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "CHANNEL_ID" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "DAY_OF_WEEK" VARCHAR(16777216), "HOLIDAY_IND_CY" NUMBER(38,0), "HOLIDAY_NM_CY" VARCHAR(16777216), "NET_SALES_CY" NUMBER(38,2), "TRANS_CY" NUMBER(38,0), "AVG_CHECK_CY" NUMBER(38,2), "STORE_CNT_CY" NUMBER(38,0), "COMP_SALES_CY" NUMBER(38,2), "COMP_TRANS_CY" NUMBER(38,0), "COMP_AVG_CHECK_CY" NUMBER(38,2), "COMP_STORE_CNT_CY" NUMBER(38,0), "FISC_DATE_LY" DATE, "FISC_WEEK_START_DT_LY" DATE, "FISC_WEEK_END_DT_LY" DATE, "FISC_HOLIDAY_IND_LY" NUMBER(38,0), "FISC_HOLIDAY_NM_LY" VARCHAR(16777216), "FISC_NET_SALES_LY" NUMBER(38,2), "FISC_TRANS_LY" NUMBER(38,0), "FISC_AVG_CHECK_LY" NUMBER(38,2), "FISC_STORE_CNT_LY" NUMBER(38,0), "FISC_COMP_SALES_LY" NUMBER(38,2), "FISC_COMP_TRANS_LY" NUMBER(38,0), "FISC_COMP_AVG_CHECK_LY" NUMBER(38,2), "FISC_COMP_STORE_CNT_LY" NUMBER(38,0), "CAL_COMP_DATE_LY" DATE, "CAL_WEEK_START_DT_LY" DATE, "CAL_WEEK_END_DT_LY" DATE, "CAL_HOLIDAY_IND_LY" NUMBER(38,0), "CAL_HOLIDAY_NM_LY" VARCHAR(16777216), "CAL_NET_SALES_LY" NUMBER(38,2), "CAL_TRANS_LY" NUMBER(38,0), "CAL_AVG_CHECK_LY" NUMBER(38,2), "CAL_STORE_CNT_LY" NUMBER(38,0), "CAL_COMP_SALES_LY" NUMBER(38,2), "CAL_COMP_TRANS_LY" NUMBER(38,0), "CAL_COMP_AVG_CHECK_LY" NUMBER(38,2), "CAL_COMP_STORE_CNT_LY" NUMBER(38,0), "CAL_COMP_DATE_2Y" DATE, "CAL_WEEK_START_DT_2Y" DATE, "CAL_WEEK_END_DT_2Y" DATE, "CAL_HOLIDAY_IND_2Y" NUMBER(38,0), "CAL_HOLIDAY_NM_2Y" VARCHAR(16777216), "CAL_NET_SALES_2Y" NUMBER(38,2), "CAL_TRANS_2Y" NUMBER(38,0), "CAL_AVG_CHECK_2Y" NUMBER(38,2), "CAL_STORE_CNT_2Y" NUMBER(38,0), "CAL_COMP_SALES_2Y" NUMBER(38,2), "CAL_COMP_TRANS_2Y" NUMBER(38,0), "CAL_COMP_AVG_CHECK_2Y" NUMBER(38,2), "CAL_COMP_STORE_CNT_2Y" NUMBER(38,0), "CAL_COMP_DATE_3Y" DATE, "CAL_WEEK_START_DT_3Y" DATE, "CAL_WEEK_END_DT_3Y" DATE, "CAL_HOLIDAY_IND_3Y" NUMBER(38,0), "CAL_HOLIDAY_NM_3Y" VARCHAR(16777216), "CAL_NET_SALES_3Y" NUMBER(38,2), "CAL_TRANS_3Y" NUMBER(38,0), "CAL_AVG_CHECK_3Y" NUMBER(38,2), "CAL_STORE_CNT_3Y" NUMBER(38,0), "CAL_COMP_SALES_3Y" NUMBER(38,2), "CAL_COMP_TRANS_3Y" NUMBER(38,0), "CAL_COMP_AVG_CHECK_3Y" NUMBER(38,2), "CAL_COMP_STORE_CNT_3Y" NUMBER(38,0))
LANGUAGE SQL
AS '

SELECT 
    AGG_LEVEL                                       as AGG_LEVEL
    , dt.CALENDAR_DT                                as BUSINESS_DATE
    , dt.FISCAL_WEEK_START_DT                       as WEEK_START_DT
    , dt.FISCAL_WEEK_START_DT + 6                   as WEEK_END_DT
    , iff(AGG_LEVEL in (''DAY'', ''WEEK'', ''DAY_CHANNEL''), NULL, coalesce(cy.BRAND_DAY_PART_NM, fly.BRAND_DAY_PART_NM, cly.BRAND_DAY_PART_NM, c2y.BRAND_DAY_PART_NM, c3y.BRAND_DAY_PART_NM))
                                                    as BRAND_DAY_PART_NM
    , iff(AGG_LEVEL in (''DAY'', ''WEEK'', ''DAY_CHANNEL''), NULL, coalesce(cy.IRB_DAY_PART_NM, fly.IRB_DAY_PART_NM, cly.IRB_DAY_PART_NM, c2y.IRB_DAY_PART_NM, c3y.IRB_DAY_PART_NM))
                                                    as IRB_DAY_PART_NM
    , iff(AGG_LEVEL in (''DAY'', ''WEEK'', ''DAY_CHANNEL''), NULL, coalesce(cy.CLOSED_HR, fly.CLOSED_HR, cly.CLOSED_HR, c2y.CLOSED_HR, c3y.CLOSED_HR))
                                                    as CLOSED_HR
    , CASE WHEN UPPER(coalesce(cy.BRAND_ID, fly.BRAND_ID, cly.BRAND_ID, c2y.BRAND_ID, c3y.BRAND_ID)) IN (''ARG'',''ARBYS'') THEN ''ARB''
       WHEN UPPER(coalesce(cy.BRAND_ID, fly.BRAND_ID, cly.BRAND_ID, c2y.BRAND_ID, c3y.BRAND_ID)) IN (''BWW'') THEN ''BWW''
       WHEN UPPER(coalesce(cy.BRAND_ID, fly.BRAND_ID, cly.BRAND_ID, c2y.BRAND_ID, c3y.BRAND_ID)) IN (''SDI'',''SONIC'') THEN ''SON''
       WHEN UPPER(coalesce(cy.BRAND_ID, fly.BRAND_ID, cly.BRAND_ID, c2y.BRAND_ID, c3y.BRAND_ID)) IN (''JJ'') THEN ''JJ''
       WHEN UPPER(coalesce(cy.BRAND_ID, fly.BRAND_ID, cly.BRAND_ID, c2y.BRAND_ID, c3y.BRAND_ID)) IN (''DNKN'') THEN ''DUN''
       WHEN UPPER(coalesce(cy.BRAND_ID, fly.BRAND_ID, cly.BRAND_ID, c2y.BRAND_ID, c3y.BRAND_ID)) IN (''BSKN'') THEN ''BR''
       WHEN UPPER(coalesce(cy.BRAND_ID, fly.BRAND_ID, cly.BRAND_ID, c2y.BRAND_ID, c3y.BRAND_ID)) IN (''RTO'') THEN ''RT''
       ELSE ''UNKNOWN''
       END                                          as BRAND
    , coalesce(cy.STORE_ID, fly.STORE_ID, cly.STORE_ID, c2y.STORE_ID, c3y.STORE_ID)
                                                    as STORE_NBR
    , coalesce(cy.DMA_CODE, fly.DMA_CODE, cly.DMA_CODE, c2y.DMA_CODE, c3y.DMA_CODE, '''')
                                                    as DMA_CODE
    , coalesce(cy.DMA_NAME, fly.DMA_NAME, cly.DMA_NAME, c2y.DMA_NAME, c3y.DMA_NAME, '''')
                                                    as DMA_NAME
    , nvl(lv.LEVEL1_NM, '''')                         as L1Name
    , nvl(lv.LEVEL2_NM, '''')                         as L2Name
    , nvl(lv.LEVEL3_NM, '''')                         as L3Name
    , nvl(lv.LEVEL4_NM, '''')                         as L4Name
    , nvl(lv.LEVEL5_NM, '''')                         as L5Name
    , coalesce(cy.OWNERSHIP_TYP, fly.OWNERSHIP_TYP, cly.OWNERSHIP_TYP, c2y.OWNERSHIP_TYP, c3y.OWNERSHIP_TYP, '''')
                                                    as OWNERSHIP_TYP
    , coalesce(cy.ADDRESS_1, fly.ADDRESS_1, cly.ADDRESS_1, c2y.ADDRESS_1, c3y.ADDRESS_1, '''')
                                                    as ADDRESS_1
    , coalesce(cy.ADDRESS_2, fly.ADDRESS_2, cly.ADDRESS_2, c2y.ADDRESS_2, c3y.ADDRESS_2, '''')
                                                    as ADDRESS_2
    , coalesce(cy.CITY, fly.CITY, cly.CITY, c2y.CITY, c3y.CITY, '''')
                                                    as CITY
    , coalesce(cy.ZIP_CD, fly.ZIP_CD, cly.ZIP_CD, c2y.ZIP_CD, c3y.ZIP_CD, '''')
                                                    as ZIP_CODE
    , coalesce(cy.STATE, fly.STATE, cly.STATE, c2y.STATE, c3y.STATE, '''')
                                                    as STATE
    , coalesce(cy.COUNTRY, fly.COUNTRY, cly.COUNTRY, c2y.COUNTRY, c3y.COUNTRY, '''')
                                                    as COUNTRY
    , coalesce(cy.CHANNEL_ID, fly.CHANNEL_ID, cly.CHANNEL_ID, c2y.CHANNEL_ID, c3y.CHANNEL_ID)
                                                    as CHANNEL_ID

    --current year
    , coalesce(cy.FISCAL_YEAR_NBR, fly.FISCAL_YEAR_NBR + 1, cly.FISCAL_YEAR_NBR + 1, c2y.FISCAL_YEAR_NBR + 2, c3y.FISCAL_YEAR_NBR + 3)
                                                    as FISC_YEAR_NBR
    , coalesce(cy.FISCAL_QUARTER_NBR, fly.FISCAL_QUARTER_NBR, cly.FISCAL_QUARTER_NBR, c2y.FISCAL_QUARTER_NBR, c3y.FISCAL_QUARTER_NBR)
                                                    as FISC_QUARTER_NBR
    , coalesce(cy.FISCAL_PERIOD_NBR, fly.FISCAL_PERIOD_NBR, cly.FISCAL_PERIOD_NBR, c2y.FISCAL_PERIOD_NBR, c3y.FISCAL_PERIOD_NBR)
                                                    as FISCAL_PERIOD_NBR
    , coalesce(cy.FISCAL_WEEK_NBR, fly.FISCAL_WEEK_NBR, cly.FISCAL_WEEK_NBR, c2y.FISCAL_WEEK_NBR, c3y.FISCAL_WEEK_NBR)
                                                    as FISCAL_WEEK_NBR
    , coalesce(cy.CALENDAR_DAY_NM, fly.CALENDAR_DAY_NM, cly.CALENDAR_DAY_NM, c2y.CALENDAR_DAY_NM, c3y.CALENDAR_DAY_NM)
                                                    as DAY_OF_WEEK
    , nvl(cy.HOLIDAY_IND, iff(nvl(hol_cy.HOLIDAY_IND, false), 1, 0))                        as HOLIDAY_IND_CY
    , coalesce(hol_cy.HOLIDAY_LIST_NM, cy.HOLIDAY_NM, '''')                        as HOLIDAY_NM_CY
    , cy.NET_SALES                                  as NET_SALES_CY
    , cy.TRANS_CNT                                      as TRANS_CY
    , iff(cy.TRANS_CNT > 0, cy.NET_SALES/cy.TRANS_CNT, 0)   as AVG_CHECK_CY
    , cy.STORE_CNT                                  as STORE_CNT_CY
    , iff(cy.COMP_STORE_CNT = 1, cy.NET_SALES, 0)   as COMP_SALES_CY
    , iff(cy.COMP_STORE_CNT = 1, cy.TRANS_CNT, 0)   as COMP_TRANS_CY
    , iff(cy.COMP_STORE_CNT = 1 AND COMP_TRANS_CY > 0
        , COMP_SALES_CY/COMP_TRANS_CY, 0)           as COMP_AVG_CHECK_CY
    , iff(STORE_CNT_CY = 0, 0, cy.COMP_STORE_CNT)   as COMP_STORE_CNT_CY

    --fiscal last year
    , dt.FISCAL_1YR_COMP_DT                         as FISC_DATE_LY
    , dt.FISCAL_1YR_COMP_WEEK_DT                    as FISC_WEEK_START_DT_LY
    , dt.FISCAL_1YR_COMP_WEEK_DT + 6                as FISC_WEEK_END_DT_LY
    , nvl(fly.HOLIDAY_IND, iff(nvl(hol_fly.HOLIDAY_IND, false), 1, 0))                       as FISC_HOLIDAY_IND_LY
    , coalesce(hol_fly.HOLIDAY_LIST_NM, fly.HOLIDAY_NM, '''')                       as FISC_HOLIDAY_NM_LY
    , nvl(fly.NET_SALES, 0)                         as FISC_NET_SALES_LY
    , nvl(fly.TRANS_CNT, 0)                         as FISC_TRANS_LY
    , iff(fly.TRANS_CNT > 0, fly.NET_SALES/fly.TRANS_CNT, 0)
                                                    as FISC_AVG_CHECK_LY
    , fly.STORE_CNT                                 as FISC_STORE_CNT_LY
    , CASE
        WHEN --ODI-2977
            AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'')
            AND TO_DATE > CURRENT_DATE
            AND NOT nvl(cy.IS_XMAS_THANKSGIVING, false)
            AND ARRAY_INTERSECTION(cy.WEEKDAY_OFFSET, fly.WEEKDAY_OFFSET) IS NOT NULL
            AND fly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
        THEN
            fly.NET_SALES - EXCLUDE_FROM_ARRAY(fly.WEEK_NET_SALES, cy.WEEK_NET_SALES, cy.WEEKDAY_OFFSET, fly.WEEKDAY_OFFSET)
        ELSE        
            iff(fly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
            , fly.NET_SALES, 0)
        END                                         as FISC_COMP_SALES_LY
    , CASE
        WHEN --ODI-2977
            AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'')
            AND TO_DATE > CURRENT_DATE
            AND NOT nvl(cy.IS_XMAS_THANKSGIVING, false)
            AND ARRAY_INTERSECTION(cy.WEEKDAY_OFFSET, fly.WEEKDAY_OFFSET) IS NOT NULL
            AND fly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
        THEN
            fly.TRANS_CNT - EXCLUDE_FROM_ARRAY(fly.WEEK_TRANS_CNTS, cy.WEEK_TRANS_CNTS, cy.WEEKDAY_OFFSET, fly.WEEKDAY_OFFSET)
        ELSE        
            iff(fly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
            , fly.TRANS_CNT, 0)
        END                                         as FISC_COMP_TRANS_LY
    , iff(fly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1 AND FISC_COMP_TRANS_LY > 0
        , FISC_COMP_SALES_LY/FISC_COMP_TRANS_LY, 0)               as FISC_COMP_AVG_CHECK_LY
    , iff(cy.COMP_STORE_CNT = 1 and FISC_STORE_CNT_LY = 1
        , fly.COMP_STORE_CNT, 0)                    as FISC_COMP_STORE_CNT_LY

    --calendar last year
    , dt.CALENDAR_1YR_COMP_DT                       as CAL_COMP_DATE_LY
    , dt.CALENDAR_1YR_COMP_WEEK_DT                  as CAL_WEEK_START_DT_LY
    , dt.CALENDAR_1YR_COMP_WEEK_DT + 6              as CAL_WEEK_END_DT_LY
    , nvl(cly.HOLIDAY_IND, iff(nvl(hol_cly.HOLIDAY_IND, false), 1, 0))                       as CAL_HOLIDAY_IND_LY
    , coalesce(hol_cly.HOLIDAY_LIST_NM, cly.HOLIDAY_NM, '''')                       as CAL_HOLIDAY_NM_LY
    , nvl(cly.NET_SALES, 0)                         as CAL_NET_SALES_LY
    , nvl(cly.TRANS_CNT, 0)                         as CAL_TRANS_LY
    , iff(cly.TRANS_CNT > 0, cly.NET_SALES/cly.TRANS_CNT, 0)
                                                    as CAL_AVG_CHECK_LY
    , cly.STORE_CNT                                 as CAL_STORE_CNT_LY
    , CASE
        WHEN --ODI-2977
            AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'')
            AND TO_DATE > CURRENT_DATE
            AND NOT nvl(cy.IS_XMAS_THANKSGIVING, false)
            AND ARRAY_INTERSECTION(cy.WEEKDAY_OFFSET, cly.WEEKDAY_OFFSET) IS NOT NULL
            AND cly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
        THEN
            cly.NET_SALES - EXCLUDE_FROM_ARRAY(cly.WEEK_NET_SALES, cy.WEEK_NET_SALES, cy.WEEKDAY_OFFSET, cly.WEEKDAY_OFFSET)
        ELSE        
            iff(cly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
            , cly.NET_SALES, 0)
        END                                         as CAL_COMP_SALES_LY
    , CASE
        WHEN --ODI-2977
            AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'')
            AND TO_DATE > CURRENT_DATE
            AND NOT nvl(cy.IS_XMAS_THANKSGIVING, false)
            AND ARRAY_INTERSECTION(cy.WEEKDAY_OFFSET, cly.WEEKDAY_OFFSET) IS NOT NULL
            AND cly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
        THEN
            cly.TRANS_CNT - EXCLUDE_FROM_ARRAY(cly.WEEK_TRANS_CNTS, cy.WEEK_TRANS_CNTS, cy.WEEKDAY_OFFSET, cly.WEEKDAY_OFFSET)
        ELSE        
            iff(cly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
            , cly.TRANS_CNT, 0)
        END                                         as CAL_COMP_TRANS_LY
    , iff(cly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1 AND CAL_COMP_TRANS_LY > 0
        , CAL_COMP_SALES_LY/CAL_COMP_TRANS_LY, 0)   as CAL_COMP_AVG_CHECK_LY
    , iff(cy.COMP_STORE_CNT = 1 and CAL_STORE_CNT_LY = 1
        , cly.COMP_STORE_CNT, 0)                    as CAL_COMP_STORE_CNT_LY

    --calendar 2 years
    , dt.CALENDAR_2YR_COMP_DT                       as CAL_COMP_DATE_2Y
    , dt.CALENDAR_2YR_COMP_WEEK_DT                  as CAL_WEEK_START_DT_2Y
    , dt.CALENDAR_2YR_COMP_WEEK_DT + 6              as CAL_WEEK_END_DT_2Y
    , nvl(c2y.HOLIDAY_IND, iff(nvl(hol_c2y.HOLIDAY_IND, false), 1, 0))                       as CAL_HOLIDAY_IND_2Y
    , coalesce(hol_c2y.HOLIDAY_LIST_NM, c2y.HOLIDAY_NM, '''')                       as CAL_HOLIDAY_NM_2Y
    , nvl(c2y.NET_SALES, 0)                         as CAL_NET_SALES_DAY_2Y
    , nvl(c2y.TRANS_CNT, 0)                         as CAL_TRANS_2Y
    , iff(c2y.TRANS_CNT > 0, c2y.NET_SALES/c2y.TRANS_CNT, 0)
                                                    as CAL_AVG_CHECK_2Y
    , c2y.STORE_CNT                                 as CAL_STORE_CNT_2Y
    , CASE
        WHEN --ODI-2977
            AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'')
            AND TO_DATE > CURRENT_DATE
            AND NOT nvl(cy.IS_XMAS_THANKSGIVING, false)
            AND ARRAY_INTERSECTION(cy.WEEKDAY_OFFSET, c2y.WEEKDAY_OFFSET) IS NOT NULL
            AND c2y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
        THEN
            c2y.NET_SALES - EXCLUDE_FROM_ARRAY(c2y.WEEK_NET_SALES, cy.WEEK_NET_SALES, cy.WEEKDAY_OFFSET, c2y.WEEKDAY_OFFSET)
        ELSE        
            iff(c2y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
        , c2y.NET_SALES, 0)
        END                                         as CAL_COMP_SALES_2Y
    , CASE
        WHEN --ODI-2977
            AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'')
            AND TO_DATE > CURRENT_DATE
            AND NOT nvl(cy.IS_XMAS_THANKSGIVING, false)
            AND ARRAY_INTERSECTION(cy.WEEKDAY_OFFSET, c2y.WEEKDAY_OFFSET) IS NOT NULL
            AND c2y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
        THEN
            c2y.TRANS_CNT - EXCLUDE_FROM_ARRAY(c2y.WEEK_TRANS_CNTS, cy.WEEK_TRANS_CNTS, cy.WEEKDAY_OFFSET, c2y.WEEKDAY_OFFSET)
        ELSE        
            iff(c2y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
            , c2y.TRANS_CNT, 0)
        END                                         as CAL_COMP_TRANS_2Y
    , iff(c2y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1 AND CAL_COMP_TRANS_2Y > 0
        , CAL_COMP_SALES_2Y/CAL_COMP_TRANS_2Y, 0)   as CAL_COMP_AVG_CHECK_2Y
    , iff(cy.COMP_STORE_CNT = 1 and CAL_STORE_CNT_2Y = 1
        , c2y.COMP_STORE_CNT, 0)                    as CAL_COMP_STORE_CNT_2Y

    --calendar 3 years
    , dt.CALENDAR_3YR_COMP_DT                       as CAL_COMP_DATE_3Y
    , dt.CALENDAR_3YR_COMP_WEEK_DT                  as CAL_WEEK_START_DT_3Y
    , dt.CALENDAR_3YR_COMP_WEEK_DT + 6              as CAL_WEEK_END_DT_3Y
    , nvl(c3y.HOLIDAY_IND, iff(nvl(hol_c3y.HOLIDAY_IND, false), 1, 0))                       as CAL_HOLIDAY_IND_3Y
    , coalesce(hol_c3y.HOLIDAY_LIST_NM, c3y.HOLIDAY_NM, '''')                       as CAL_HOLIDAY_NM_3Y
    , nvl(c3y.NET_SALES, 0)                         as CAL_NET_SALES_DAY_3Y
    , nvl(c3y.TRANS_CNT, 0)                         as CAL_TRANS_3Y
    , iff(c3y.TRANS_CNT > 0, c3y.NET_SALES/c3y.TRANS_CNT, 0)
                                                    as CAL_AVG_CHECK_3Y
    , c3y.STORE_CNT                                 as CAL_STORE_CNT_3Y
    , CASE
        WHEN --ODI-2977
            AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'')
            AND TO_DATE > CURRENT_DATE
            AND NOT nvl(cy.IS_XMAS_THANKSGIVING, false)
            AND ARRAY_INTERSECTION(cy.WEEKDAY_OFFSET, c3y.WEEKDAY_OFFSET) IS NOT NULL
            AND c3y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
        THEN
            c3y.NET_SALES - EXCLUDE_FROM_ARRAY(c3y.WEEK_NET_SALES, cy.WEEK_NET_SALES, cy.WEEKDAY_OFFSET, c3y.WEEKDAY_OFFSET)
        ELSE        
            iff(c3y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
            , c3y.NET_SALES, 0)
        END                                         as CAL_COMP_SALES_3Y
    , CASE
        WHEN --ODI-2977
            AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'')
            AND TO_DATE > CURRENT_DATE
            AND NOT nvl(cy.IS_XMAS_THANKSGIVING, false)
            AND ARRAY_INTERSECTION(cy.WEEKDAY_OFFSET, c3y.WEEKDAY_OFFSET) IS NOT NULL
            AND c3y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
        THEN
            c3y.TRANS_CNT - EXCLUDE_FROM_ARRAY(c3y.WEEK_TRANS_CNTS, cy.WEEK_TRANS_CNTS, cy.WEEKDAY_OFFSET, c3y.WEEKDAY_OFFSET)
        ELSE        
            iff(c3y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
            , c3y.TRANS_CNT, 0)
        END                                         as CAL_COMP_TRANS_3Y
    , iff(c3y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1 AND CAL_COMP_TRANS_3Y > 0
        , CAL_COMP_SALES_3Y/CAL_COMP_TRANS_3Y, 0)   as CAL_COMP_AVG_CHECK_3Y
    , iff(cy.COMP_STORE_CNT = 1 and CAL_STORE_CNT_3Y = 1
        , c3y.COMP_STORE_CNT, 0)                    as CAL_COMP_STORE_CNT_3Y
FROM IDS_DEV.INT_REF.COMP_CALENDAR dt
INNER JOIN table(DAYPART_FLASH_INIT(FROM_DATE, TO_DATE, AGG_LEVEL, ''CY'', BRAND_INPUT)) as cy
    on dt.CALENDAR_DT = 
                CASE WHEN AGG_LEVEL IN (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') THEN cy.business_dt
                ELSE cy.FISCAL_WEEK_START_DT END
LEFT JOIN table(DAYPART_FLASH_INIT(FROM_DATE, TO_DATE, AGG_LEVEL, ''FISC1Y'', BRAND_INPUT)) as fly
    on fly.BRAND_ID = cy.BRAND_ID
    and fly.STORE_ID = cy.STORE_ID
    and CASE WHEN AGG_LEVEL IN (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') THEN dt.FISCAL_1YR_COMP_DT
        ELSE dt.FISCAL_1YR_COMP_WEEK_DT END =
                CASE WHEN AGG_LEVEL IN (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') THEN fly.business_dt
                ELSE fly.FISCAL_WEEK_START_DT END
    and CASE WHEN AGG_LEVEL in (''DAY_PART'', ''WEEK_CHANNEL'') THEN
                    fly.CLOSED_HR = cy.CLOSED_HR
                ELSE true END
    and CASE WHEN AGG_LEVEL IN (''WEEK_CHANNEL'', ''DAY_CHANNEL'') THEN fly.CHANNEL_ID = cy.CHANNEL_ID ELSE TRUE END
LEFT JOIN table(DAYPART_FLASH_INIT(FROM_DATE, TO_DATE, AGG_LEVEL, ''CAL1Y'', BRAND_INPUT)) as cly
    on cly.BRAND_ID = cy.BRAND_ID
    and cly.STORE_ID = cy.STORE_ID
    and CASE WHEN AGG_LEVEL IN (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') THEN dt.CALENDAR_1YR_COMP_DT
        ELSE dt.CALENDAR_1YR_COMP_WEEK_DT END =
                CASE WHEN AGG_LEVEL IN (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') THEN cly.business_dt
                ELSE cly.FISCAL_WEEK_START_DT END
    and CASE WHEN AGG_LEVEL in (''DAY_PART'', ''WEEK_CHANNEL'') THEN
                    cly.CLOSED_HR = cy.CLOSED_HR
                ELSE true END
    and CASE WHEN AGG_LEVEL IN (''WEEK_CHANNEL'', ''DAY_CHANNEL'') THEN cly.CHANNEL_ID = cy.CHANNEL_ID ELSE TRUE END
LEFT JOIN table(DAYPART_FLASH_INIT(FROM_DATE, TO_DATE, AGG_LEVEL, ''CAL2Y'', BRAND_INPUT)) as c2y
    on c2y.BRAND_ID = cy.BRAND_ID
    and c2y.STORE_ID = cy.STORE_ID
    and CASE WHEN AGG_LEVEL IN (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') THEN dt.CALENDAR_2YR_COMP_DT
        ELSE dt.CALENDAR_2YR_COMP_WEEK_DT END =
                CASE WHEN AGG_LEVEL IN (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') THEN c2y.business_dt
                ELSE c2y.FISCAL_WEEK_START_DT END
    and CASE WHEN AGG_LEVEL in (''DAY_PART'', ''WEEK_CHANNEL'') THEN
                    c2y.CLOSED_HR = cy.CLOSED_HR
                ELSE true END
    and CASE WHEN AGG_LEVEL IN (''WEEK_CHANNEL'', ''DAY_CHANNEL'') THEN c2y.CHANNEL_ID = cy.CHANNEL_ID ELSE TRUE END
LEFT JOIN table(DAYPART_FLASH_INIT(FROM_DATE, TO_DATE, AGG_LEVEL, ''CAL3Y'', BRAND_INPUT)) as c3y
    on c3y.BRAND_ID = cy.BRAND_ID
    and c3y.STORE_ID = cy.STORE_ID
    and CASE WHEN AGG_LEVEL IN (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') THEN dt.CALENDAR_3YR_COMP_DT
        ELSE dt.CALENDAR_3YR_COMP_WEEK_DT END =
                CASE WHEN AGG_LEVEL IN (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') THEN c3y.business_dt
                ElSE c3y.FISCAL_WEEK_START_DT END
    and CASE WHEN AGG_LEVEL in (''DAY_PART'', ''WEEK_CHANNEL'') THEN
                    c3y.CLOSED_HR = cy.CLOSED_HR
                ELSE true END
    and CASE WHEN AGG_LEVEL IN (''WEEK_CHANNEL'', ''DAY_CHANNEL'') THEN c3y.CHANNEL_ID = cy.CHANNEL_ID ELSE TRUE END
LEFT JOIN IDH_DEV.OPERATION.LOCATION_HIERARCHY_V lv 
    on lv.LOCATION_ID = coalesce(cy.STORE_ID, fly.STORE_ID, cly.STORE_ID, c2y.STORE_ID, c3y.STORE_ID)
    and lv.brand_id = coalesce(cy.BRAND_ID, fly.BRAND_ID, cly.BRAND_ID, c2y.BRAND_ID, c3y.BRAND_ID)
LEFT JOIN IDH_DEV.SHARED.HOLIDAY_LIST_V as hol_cy
    ON AGG_LEVEL IN (''DAY_PART'', ''DAY_CHANNEL'')
    AND hol_cy.DATE_KEY = replace(dt.CALENDAR_DT, ''-'', '''')
LEFT JOIN IDH_DEV.SHARED.HOLIDAY_LIST_V as hol_fly
    ON AGG_LEVEL IN (''DAY_PART'', ''DAY_CHANNEL'')
    AND hol_fly.DATE_KEY = replace(dt.FISCAL_1YR_COMP_DT, ''-'', '''')
LEFT JOIN IDH_DEV.SHARED.HOLIDAY_LIST_V as hol_cly
    ON AGG_LEVEL IN (''DAY_PART'', ''DAY_CHANNEL'')
    AND hol_cly.DATE_KEY = replace(dt.CALENDAR_1YR_COMP_DT, ''-'', '''')
LEFT JOIN IDH_DEV.SHARED.HOLIDAY_LIST_V as hol_c2y
    ON AGG_LEVEL IN (''DAY_PART'', ''DAY_CHANNEL'')
    AND hol_c2y.DATE_KEY = replace(dt.CALENDAR_2YR_COMP_DT, ''-'', '''')
LEFT JOIN IDH_DEV.SHARED.HOLIDAY_LIST_V as hol_c3y
    ON AGG_LEVEL IN (''DAY_PART'', ''DAY_CHANNEL'')
    AND hol_c3y.DATE_KEY = replace(dt.CALENDAR_3YR_COMP_DT, ''-'', '''')
where CASE WHEN AGG_LEVEL = ''WEEK_CHANNEL''
                    THEN cy.CHANNEL_ID  is not null
                    OR cy.BRAND_DAY_PART_NM is not null
                    OR cy.ADD_NULL_WEEK
             WHEN AGG_LEVEL = ''DAY_CHANNEL''  
                THEN cy.CHANNEL_ID = coalesce(fly.CHANNEL_ID, cly.CHANNEL_ID, c2y.CHANNEL_ID, c3y.CHANNEL_ID) OR cy.BRAND_DAY_PART_NM is not null
        WHEN AGG_LEVEL = ''DAY_PART'' THEN cy.CLOSED_HR = coalesce(fly.CLOSED_HR, cly.CLOSED_HR, c2y.CLOSED_HR, c3y.CLOSED_HR) OR cy.BRAND_DAY_PART_NM is not null
        ELSE true END
    and (
        dt.CALENDAR_DT = 
                    CASE WHEN AGG_LEVEL IN (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') THEN cy.business_dt
                    ELSE cy.FISCAL_WEEK_START_DT END
        or CASE WHEN AGG_LEVEL IN (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') THEN dt.FISCAL_1YR_COMP_DT
        ELSE dt.FISCAL_1YR_COMP_WEEK_DT END =
                CASE WHEN AGG_LEVEL IN (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') THEN fly.business_dt
                ELSE fly.FISCAL_WEEK_START_DT END
        or CASE WHEN AGG_LEVEL IN (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') THEN dt.CALENDAR_1YR_COMP_DT
        ELSE dt.CALENDAR_1YR_COMP_WEEK_DT END =
                CASE WHEN AGG_LEVEL IN (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') THEN cly.business_dt
                ELSE cly.FISCAL_WEEK_START_DT END
        or CASE WHEN AGG_LEVEL IN (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') THEN dt.CALENDAR_2YR_COMP_DT
        ELSE dt.CALENDAR_2YR_COMP_WEEK_DT END =
                CASE WHEN AGG_LEVEL IN (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') THEN c2y.business_dt
                ELSE c2y.FISCAL_WEEK_START_DT END
        or CASE WHEN AGG_LEVEL IN (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') THEN dt.CALENDAR_3YR_COMP_DT
        ELSE dt.CALENDAR_3YR_COMP_WEEK_DT END =
                CASE WHEN AGG_LEVEL IN (''DAY'', ''DAY_PART'', ''DAY_CHANNEL'') THEN c3y.business_dt
                ElSE c3y.FISCAL_WEEK_START_DT END
    )
';
CREATE FUNCTION IF NOT EXISTS EXCLUDE_FROM_ARRAY("FULL_ARRAY" ARRAY, "FULL_ARRAY_CY" ARRAY, "CY_OFFSET" ARRAY, "LY_OFFSET" ARRAY)
RETURNS NUMBER(38,2)
LANGUAGE SQL
AS '

select cast(
    iff(
      full_array_cy[ARRAY_POSITION(
            ARRAY_INTERSECTION(cy_offset, ly_offset)[0], cy_offset
        )] = 0
      , 
      full_array[ARRAY_POSITION(
            ARRAY_INTERSECTION(cy_offset, ly_offset)[0], ly_offset
        )]
      , 0
    )
    + iff(ARRAY_SIZE(ARRAY_INTERSECTION(cy_offset, ly_offset)) > 1
          AND full_array_cy[ARRAY_POSITION(
                ARRAY_INTERSECTION(cy_offset, ly_offset)[1], cy_offset
            )] = 0
          , full_array[ARRAY_POSITION(
                  ARRAY_INTERSECTION(cy_offset, ly_offset)[1], ly_offset
              )]
          , 0
         )
    + iff(ARRAY_SIZE(ARRAY_INTERSECTION(cy_offset, ly_offset)) > 2
          AND full_array_cy[ARRAY_POSITION(
                ARRAY_INTERSECTION(cy_offset, ly_offset)[2], cy_offset
            )] = 0
          , full_array[ARRAY_POSITION(
                  ARRAY_INTERSECTION(cy_offset, ly_offset)[2], ly_offset
              )]
          , 0
         )
    + iff(ARRAY_SIZE(ARRAY_INTERSECTION(cy_offset, ly_offset)) > 3
          AND full_array_cy[ARRAY_POSITION(
                ARRAY_INTERSECTION(cy_offset, ly_offset)[3], cy_offset
            )] = 0
          , full_array[ARRAY_POSITION(
                  ARRAY_INTERSECTION(cy_offset, ly_offset)[3], ly_offset
              )]
          , 0
         )
    + iff(ARRAY_SIZE(ARRAY_INTERSECTION(cy_offset, ly_offset)) > 4
          AND full_array_cy[ARRAY_POSITION(
                ARRAY_INTERSECTION(cy_offset, ly_offset)[4], cy_offset
            )] = 0
          , full_array[ARRAY_POSITION(
                  ARRAY_INTERSECTION(cy_offset, ly_offset)[4], ly_offset
              )]
          , 0
         )
    + iff(ARRAY_SIZE(ARRAY_INTERSECTION(cy_offset, ly_offset)) > 5
          AND full_array_cy[ARRAY_POSITION(
                ARRAY_INTERSECTION(cy_offset, ly_offset)[5], cy_offset
            )] = 0
          , full_array[ARRAY_POSITION(
                  ARRAY_INTERSECTION(cy_offset, ly_offset)[5], ly_offset
              )]
          , 0
         )
         + iff(ARRAY_SIZE(ARRAY_INTERSECTION(cy_offset, ly_offset)) > 6
          AND full_array_cy[ARRAY_POSITION(
                ARRAY_INTERSECTION(cy_offset, ly_offset)[6], cy_offset
            )] = 0
          , full_array[ARRAY_POSITION(
                  ARRAY_INTERSECTION(cy_offset, ly_offset)[6], ly_offset
              )]
          , 0
         )
as number (38, 2))

';
CREATE FUNCTION IF NOT EXISTS EXCLUDE_FROM_ARRAY_WITHOUT_THRESHOLD("FULL_ARRAY" ARRAY, "FULL_ARRAY_CY" ARRAY, "CY_OFFSET" ARRAY, "LY_OFFSET" ARRAY)
RETURNS NUMBER(38,2)
LANGUAGE SQL
AS '

select cast(
    iff(
      full_array_cy[ARRAY_POSITION(
            ARRAY_INTERSECTION(cy_offset, ly_offset)[0], cy_offset
        )] = 0
      , 
      full_array[ARRAY_POSITION(
            ARRAY_INTERSECTION(cy_offset, ly_offset)[0], ly_offset
        )]
      , 0
    )
    + iff(ARRAY_SIZE(ARRAY_INTERSECTION(cy_offset, ly_offset)) > 1
          AND full_array_cy[ARRAY_POSITION(
                ARRAY_INTERSECTION(cy_offset, ly_offset)[1], cy_offset
            )] = 0
          , full_array[ARRAY_POSITION(
                  ARRAY_INTERSECTION(cy_offset, ly_offset)[1], ly_offset
              )]
          , 0
         )
    + iff(ARRAY_SIZE(ARRAY_INTERSECTION(cy_offset, ly_offset)) > 2
          AND full_array_cy[ARRAY_POSITION(
                ARRAY_INTERSECTION(cy_offset, ly_offset)[2], cy_offset
            )] = 0
          , full_array[ARRAY_POSITION(
                  ARRAY_INTERSECTION(cy_offset, ly_offset)[2], ly_offset
              )]
          , 0
         )
    + iff(ARRAY_SIZE(ARRAY_INTERSECTION(cy_offset, ly_offset)) > 3
          AND full_array_cy[ARRAY_POSITION(
                ARRAY_INTERSECTION(cy_offset, ly_offset)[3], cy_offset
            )] = 0
          , full_array[ARRAY_POSITION(
                  ARRAY_INTERSECTION(cy_offset, ly_offset)[3], ly_offset
              )]
          , 0
         )
    + iff(ARRAY_SIZE(ARRAY_INTERSECTION(cy_offset, ly_offset)) > 4
          AND full_array_cy[ARRAY_POSITION(
                ARRAY_INTERSECTION(cy_offset, ly_offset)[4], cy_offset
            )] = 0
          , full_array[ARRAY_POSITION(
                  ARRAY_INTERSECTION(cy_offset, ly_offset)[4], ly_offset
              )]
          , 0
         )
    + iff(ARRAY_SIZE(ARRAY_INTERSECTION(cy_offset, ly_offset)) > 5
          AND full_array_cy[ARRAY_POSITION(
                ARRAY_INTERSECTION(cy_offset, ly_offset)[5], cy_offset
            )] = 0
          , full_array[ARRAY_POSITION(
                  ARRAY_INTERSECTION(cy_offset, ly_offset)[5], ly_offset
              )]
          , 0
         )
as number (38, 2))

';
CREATE FUNCTION IF NOT EXISTS FCN_RETURN_BRAND_ID("BUSINESSDATE" DATE, "STOREID" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216))
LANGUAGE SQL
AS 'SELECT
    st.BRAND_ID
FROM
    IDH_QA.SHARED.STORE_V st
WHERE
    st.BRAND_ID IN (''bskn'', ''dnkn'') 
AND st.STORE_ID IN (STORE_ID)
AND BusinessDate <= IFNULL(st.CLOSURE_DT, TO_DATE(''9999-12-31''))
AND st.STORE_ID = StoreId
QUALIFY
    ROW_NUMBER() OVER(ORDER BY st.BRAND_ID DESC) = 1';
CREATE FUNCTION IF NOT EXISTS FISC_DAILY_PRODUCT_SALES()
RETURNS TABLE ("FISC_DATE_LY" DATE, "BRAND" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "MDM_PRODUCT_ID" NUMBER(38,0), "CHECK_SALES_LY" NUMBER(38,0), "CHECK_CNT_LY" NUMBER(38,0), "REST_SALES_LY" NUMBER(38,2), "REST_TRANS_LY" NUMBER(38,0))
LANGUAGE SQL
AS 'WITH src AS
(
    SELECT
        od.ORDER_ID
      , od.ORDERLINE_ID
      , od.ORDER_DT
      , od.ORDER_TM
      , od.STORE_ID
      , od.DMA_CD
      , od.DMA_NM
      , od.CHANNEL_ID
      , od.ORDER_CHANNEL_NM
      , od.LEVEL3_ORDER_CHANNEL_HIERARCHY_NM
      , od.LEVEL2_ORDER_CHANNEL_HIERARCHY_NM
      , od.LEVEL1_ORDER_CHANNEL_HIERARCHY_NM
      , od.FULFILLMENT_CHANNEL_NM
      , od.LEVEL3_FULFILLMENT_CHANNEL_HIERARCHY_NM
      , od.LEVEL2_FULFILLMENT_CHANNEL_HIERARCHY_NM
      , od.LEVEL1_FULFILLMENT_CHANNEL_HIERARCHY_NM
      , od.EMPLOYEE_ID
      , od.MANAGER_ID
      , od.REGISTER_ID
      , od.TAX_ID
      , od.MODIFIER_IND
      , od.TAXEXEMPT_ID
      , od.SEAT_NBR
      , od.MDM_ITEM_ID
      , od.SOURCE_SYSTEM_ID
      , od.ITEM_NM
      , od.MDM_ITEM_TYP
      , od.MDM_PRODUCT_ID
      , od.PRODUCT_NM
      , od.PRODUCT_DESC
      , od.PRODUCT_STATUS_CD
      , od.TECHNICAL_SIZE_NBR
      , od.UNIT_OF_MEASURE_VAL
      , od.NON_USA_SPECIALTY_IND
      , od.VEHICLE_NBR
      , od.HOT_PRODUCT_IND
      , od.BREAKFAST_PRODUCT_IND
      , od.PRODUCT_BRAND_NM
      , od.MENU_TYP
      , od.MENU_SECTION_TYP
      , od.GBB_MEASURE_VAL
      , od.COLD_SPACE_REQUIRED_IND
      , od.FRYER_REQUIRED_IND
      , od.PRODUCT_HIERARCHY_ID
      , od.LEVEL5_PRODUCT_HIERARCHY_NM
      , od.LEVEL4_PRODUCT_HIERARCHY_NM
      , od.LEVEL3_PRODUCT_HIERARCHY_NM
      , od.LEVEL2_PRODUCT_HIERARCHY_NM
      , od.LEVEL1_PRODUCT_HIERARCHY_NM
      , od.MDM_OFFER_ID
      , od.OFFER_NM
      , od.OFFER_DESC
      , od.OFFER_CAT
      , od.OFFER_TYP
      , od.LEVEL5_OFFER_HIERARCHY_NM
      , od.LEVEL4_OFFER_HIERARCHY_NM
      , od.LEVEL3_OFFER_HIERARCHY_NM
      , od.LEVEL2_OFFER_HIERARCHY_NM
      , od.LEVEL1_OFFER_HIERARCHY_NM
      , IFNULL(od.MDM_PARENT_ITEM_ID, 0) AS PARENT_PRODUCT_ID
      , od.PARENT_SOURCE_SYSTEM_ID
      , od.PARENT_ITEM_NM
      , od.MDM_PARENT_ITEM_TYP
      , od.SOURCE_GROSS_QTY
      , od.SOURCE_GROSS_AMT
      , od.DISCOUNT_CD
      , od.DISCOUNT_NM
      , od.SOURCE_DISCOUNT_TYP
      , od.SOURCE_DISCOUNT_AMT
      , od.SOURCE_NET_AMT
      , od.DERIVED_GROSS_QTY
      , od.RETAIL_PRICE_AMT
      , od.DERIVED_GROSS_AMT
      , od.DERIVED_NET_AMT
      , od.DERIVED_DISCOUNT_AMT
      , od.TAX_AMT
      , od.CLEARED_IND
      , od.DELETED_IND
      , od.VOIDED_IND
      , od.INVENTORY_IND
      , od.ALTERNATE1_ORDER_ID
      , od.SOURCE_NM
      , od.BRAND_ID
      , od.LOAD_DT
      , od.LAST_UPDATED_DTTM
      , od.OFFER_MISC1
      , od.OFFER_MISC2
      , od.OFFER_MISC3
      , od.OFFER_MISC4
      , od.OFFER_MISC5
      , od.OFFER_MISC6
      , od.OFFER_MISC7
      , od.OFFER_MISC8
      , od.OFFER_MISC9
      , od.OFFER_MISC10
      , od.PRODUCT_MISC1
      , od.PRODUCT_MISC2
      , od.PRODUCT_MISC3
      , od.PRODUCT_MISC4
      , od.PRODUCT_MISC5
      , od.PRODUCT_MISC6
      , od.PRODUCT_MISC7
      , od.PRODUCT_MISC8
      , od.PRODUCT_MISC9
      , od.PRODUCT_MISC10
      , od.OFFER_HIERARCHY_ID
      , ROW_NUMBER() OVER (PARTITION BY ORDER_ID, ORDERLINE_ID, STORE_ID, ORDER_DT ORDER BY ORDER_ID, ORDERLINE_ID, STORE_ID, ORDER_DT, LAST_UPDATED_DTTM DESC) as Rn
    FROM
        ORDER_DETAIL_V od
    WHERE
        IFNULL((CASE WHEN UPPER(CAST(VOIDED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(VOIDED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND IFNULL((CASE WHEN UPPER(CAST(CLEARED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(CLEARED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND IFNULL((CASE WHEN UPPER(CAST(DELETED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(DELETED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND MDM_PRODUCT_ID IS NOT NULL
    --AND od.STORE_ID = PRM_STORE_ID
    AND od.ORDER_DT = ''2018-02-06''
    /*AND od.MDM_PRODUCT_ID = PRM_MDM_PRODUCT_ID*/
    /*AND (CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
           WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
           WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
           WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
           WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
           WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
           WHEN od.BRAND_ID = ''rto'' THEN ''RT''
           ELSE ''UNKNOWN'' END) = PRM_BRAND*/
)
, src_prel AS
(
    SELECT
      ORDER_ID
      , ORDER_DT AS BUSINESS_DT
      , CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
           WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
           WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
           WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
           WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
           WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
           WHEN od.BRAND_ID = ''rto'' THEN ''RT''
           ELSE ''UNKNOWN'' END AS BRAND
      , od.STORE_ID
      , IFNULL(od.MDM_PRODUCT_ID, 0) AS MDM_PRODUCT_ID
      , DERIVED_GROSS_QTY
      , DERIVED_NET_AMT
      , dd.FISCAL_COMPARABLE_DT AS FISC_DATE_LY
    FROM
        src od
    INNER JOIN
        IDH_DEV.SHARED.DATE_DIM_V dd
    ON  dd.CALENDAR_DT = od.ORDER_DT
    LEFT OUTER JOIN
        IDH_DEV.SHARED.HOLIDAY_LIST_V hl
    ON  hl.DATE_KEY = dd.DATE_KEY
    LEFT OUTER JOIN
        IDH_DEV.SHARED.HOLIDAY_LIST_V hlf
    ON  TO_DATE(CAST(hlf.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = dd.FISCAL_COMPARABLE_DT
    LEFT OUTER JOIN
      IDH_DEV.SHARED.HOLIDAY_LIST_V hl_cal
    ON  TO_DATE(CAST(hl_cal.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = dd.CALENDAR_COMPARABLE_DT
    LEFT OUTER JOIN
        IDH_DEV.SHARED.STORE_SCD_V st
    ON  od.STORE_ID = st.STORE_ID
    AND od.BRAND_ID = st.BRAND_ID
    AND od.ORDER_DT BETWEEN st.EFFECTIVE_BEGIN_DT AND st.EFFECTIVE_END_DT
    LEFT OUTER JOIN 
        IDH_DEV.OPERATION.LOCATION_HIERARCHY_V lv
    ON  lv.LOCATION_ID = st.STORE_ID
    AND lv.BRAND_ID = st.BRAND_ID
    WHERE
        od.Rn = 1
)
, src_prel_dist AS
(
    SELECT
      ORDER_ID
      , BUSINESS_DT
      , BRAND
      , STORE_ID
      , MDM_PRODUCT_ID
      , FISC_DATE_LY
      , SUM(IFNULL(DERIVED_GROSS_QTY, 0.00)) AS DERIVED_GROSS_QTY
      , SUM(IFNULL(DERIVED_NET_AMT, 0.00)) AS DERIVED_NET_AMT
    FROM
        src_prel
    GROUP BY
      ORDER_ID
      , BUSINESS_DT
      , BRAND
      , STORE_ID
      , MDM_PRODUCT_ID
      , FISC_DATE_LY
      
)
, src_prel_dist_fin AS
(
    SELECT 
      ORDER_ID
      , BUSINESS_DT
      , BRAND
      , STORE_ID
      , MDM_PRODUCT_ID

      , SUM(DERIVED_NET_AMT) OVER (PARTITION BY BUSINESS_DT, STORE_ID, FISC_DATE_LY, BRAND) AS CHECK_SALES_CY
      , COUNT(DISTINCT ORDER_ID) OVER (PARTITION BY BUSINESS_DT, STORE_ID, FISC_DATE_LY, BRAND) AS CHECK_CNT_CY
      , SUM(DERIVED_NET_AMT) OVER (PARTITION BY STORE_ID, FISC_DATE_LY, BRAND) AS REST_SALES_CY
      , COUNT(DISTINCT ORDER_ID) OVER (PARTITION BY STORE_ID, FISC_DATE_LY, BRAND) AS REST_TRANS_CY
    FROM 
      src_prel_dist
)

SELECT
    BUSINESS_DT AS FISC_DATE_LY
    , BRAND
    , STORE_ID
    , MDM_PRODUCT_ID
    
    , SUM(CHECK_SALES_CY) AS CHECK_SALES_CY
    , SUM(CHECK_CNT_CY) AS CHECK_CNT_CY
    , MAX(REST_SALES_CY) AS REST_SALES_CY
    , MAX(REST_TRANS_CY) AS REST_TRANS_CY
FROM
    src_prel_dist_fin
--WHERE
--    BUSINESS_DT = PRM_ORDER_DT
GROUP BY
    BUSINESS_DT
    , BRAND
    , STORE_ID
    , MDM_PRODUCT_ID
--ORDER BY
--    MDM_PRODUCT_ID
';
CREATE FUNCTION IF NOT EXISTS FISC_DAILY_PRODUCT_SALES("PRM_FROMDATE" DATE, "PRM_TODATE" DATE)
RETURNS TABLE ("FISC_DATE_LY" DATE, "BRAND" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "MDM_PRODUCT_ID" NUMBER(38,0), "CHECK_SALES_LY" NUMBER(38,0), "CHECK_CNT_LY" NUMBER(38,0), "REST_SALES_LY" NUMBER(38,2), "REST_TRANS_LY" NUMBER(38,0))
LANGUAGE SQL
AS 'WITH src AS
(
    SELECT
        od.ORDER_ID
      , od.ORDERLINE_ID
      , od.ORDER_DT
      , od.ORDER_TM
      , od.STORE_ID
      , od.DMA_CD
      , od.DMA_NM
      , od.CHANNEL_ID
      , od.ORDER_CHANNEL_NM
      , od.LEVEL3_ORDER_CHANNEL_HIERARCHY_NM
      , od.LEVEL2_ORDER_CHANNEL_HIERARCHY_NM
      , od.LEVEL1_ORDER_CHANNEL_HIERARCHY_NM
      , od.FULFILLMENT_CHANNEL_NM
      , od.LEVEL3_FULFILLMENT_CHANNEL_HIERARCHY_NM
      , od.LEVEL2_FULFILLMENT_CHANNEL_HIERARCHY_NM
      , od.LEVEL1_FULFILLMENT_CHANNEL_HIERARCHY_NM
      , od.EMPLOYEE_ID
      , od.MANAGER_ID
      , od.REGISTER_ID
      , od.TAX_ID
      , od.MODIFIER_IND
      , od.TAXEXEMPT_ID
      , od.SEAT_NBR
      , od.MDM_ITEM_ID
      , od.SOURCE_SYSTEM_ID
      , od.ITEM_NM
      , od.MDM_ITEM_TYP
      , od.MDM_PRODUCT_ID
      , od.PRODUCT_NM
      , od.PRODUCT_DESC
      , od.PRODUCT_STATUS_CD
      , od.TECHNICAL_SIZE_NBR
      , od.UNIT_OF_MEASURE_VAL
      , od.NON_USA_SPECIALTY_IND
      , od.VEHICLE_NBR
      , od.HOT_PRODUCT_IND
      , od.BREAKFAST_PRODUCT_IND
      , od.PRODUCT_BRAND_NM
      , od.MENU_TYP
      , od.MENU_SECTION_TYP
      , od.GBB_MEASURE_VAL
      , od.COLD_SPACE_REQUIRED_IND
      , od.FRYER_REQUIRED_IND
      , od.PRODUCT_HIERARCHY_ID
      , od.LEVEL5_PRODUCT_HIERARCHY_NM
      , od.LEVEL4_PRODUCT_HIERARCHY_NM
      , od.LEVEL3_PRODUCT_HIERARCHY_NM
      , od.LEVEL2_PRODUCT_HIERARCHY_NM
      , od.LEVEL1_PRODUCT_HIERARCHY_NM
      , od.MDM_OFFER_ID
      , od.OFFER_NM
      , od.OFFER_DESC
      , od.OFFER_CAT
      , od.OFFER_TYP
      , od.LEVEL5_OFFER_HIERARCHY_NM
      , od.LEVEL4_OFFER_HIERARCHY_NM
      , od.LEVEL3_OFFER_HIERARCHY_NM
      , od.LEVEL2_OFFER_HIERARCHY_NM
      , od.LEVEL1_OFFER_HIERARCHY_NM
      , IFNULL(od.MDM_PARENT_ITEM_ID, 0) AS PARENT_PRODUCT_ID
      , od.PARENT_SOURCE_SYSTEM_ID
      , od.PARENT_ITEM_NM
      , od.MDM_PARENT_ITEM_TYP
      , od.SOURCE_GROSS_QTY
      , od.SOURCE_GROSS_AMT
      , od.DISCOUNT_CD
      , od.DISCOUNT_NM
      , od.SOURCE_DISCOUNT_TYP
      , od.SOURCE_DISCOUNT_AMT
      , od.SOURCE_NET_AMT
      , od.DERIVED_GROSS_QTY
      , od.RETAIL_PRICE_AMT
      , od.DERIVED_GROSS_AMT
      , od.DERIVED_NET_AMT
      , od.DERIVED_DISCOUNT_AMT
      , od.TAX_AMT
      , od.CLEARED_IND
      , od.DELETED_IND
      , od.VOIDED_IND
      , od.INVENTORY_IND
      , od.ALTERNATE1_ORDER_ID
      , od.SOURCE_NM
      , od.BRAND_ID
      , od.LOAD_DT
      , od.LAST_UPDATED_DTTM
      , od.OFFER_MISC1
      , od.OFFER_MISC2
      , od.OFFER_MISC3
      , od.OFFER_MISC4
      , od.OFFER_MISC5
      , od.OFFER_MISC6
      , od.OFFER_MISC7
      , od.OFFER_MISC8
      , od.OFFER_MISC9
      , od.OFFER_MISC10
      , od.PRODUCT_MISC1
      , od.PRODUCT_MISC2
      , od.PRODUCT_MISC3
      , od.PRODUCT_MISC4
      , od.PRODUCT_MISC5
      , od.PRODUCT_MISC6
      , od.PRODUCT_MISC7
      , od.PRODUCT_MISC8
      , od.PRODUCT_MISC9
      , od.PRODUCT_MISC10
      , od.OFFER_HIERARCHY_ID
      , ROW_NUMBER() OVER (PARTITION BY ORDER_ID, ORDERLINE_ID, STORE_ID, ORDER_DT ORDER BY ORDER_ID, ORDERLINE_ID, STORE_ID, ORDER_DT, LAST_UPDATED_DTTM DESC) as Rn
    FROM
        ORDER_DETAIL_V od
    WHERE
        IFNULL((CASE WHEN UPPER(CAST(VOIDED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(VOIDED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND IFNULL((CASE WHEN UPPER(CAST(CLEARED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(CLEARED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND IFNULL((CASE WHEN UPPER(CAST(DELETED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(DELETED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND MDM_PRODUCT_ID IS NOT NULL
    
)
, src_prel AS
(
    SELECT
      ORDER_ID
      , ORDER_DT AS BUSINESS_DT
      , CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
           WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
           WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
           WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
           WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
           WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
           WHEN od.BRAND_ID = ''rto'' THEN ''RT''
           ELSE ''UNKNOWN'' END AS BRAND
      , od.STORE_ID
      , IFNULL(od.MDM_PRODUCT_ID, 0) AS MDM_PRODUCT_ID
      , DERIVED_GROSS_QTY
      , DERIVED_NET_AMT
      , dd.FISCAL_COMPARABLE_DT AS FISC_DATE_LY
    FROM
        src od
    INNER JOIN
        IDH_DEV.SHARED.DATE_DIM_V dd
    ON  dd.CALENDAR_DT = od.ORDER_DT
    LEFT OUTER JOIN
        IDH_DEV.SHARED.HOLIDAY_LIST_V hl
    ON  hl.DATE_KEY = dd.DATE_KEY
    LEFT OUTER JOIN
        IDH_DEV.SHARED.HOLIDAY_LIST_V hlf
    ON  TO_DATE(CAST(hlf.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = dd.FISCAL_COMPARABLE_DT
    LEFT OUTER JOIN
      IDH_DEV.SHARED.HOLIDAY_LIST_V hl_cal
    ON  TO_DATE(CAST(hl_cal.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = dd.CALENDAR_COMPARABLE_DT
    LEFT OUTER JOIN
        IDH_DEV.SHARED.STORE_SCD_V st
    ON  od.STORE_ID = st.STORE_ID
    AND od.BRAND_ID = st.BRAND_ID
    AND od.ORDER_DT BETWEEN st.EFFECTIVE_BEGIN_DT AND st.EFFECTIVE_END_DT
    LEFT OUTER JOIN 
        IDH_DEV.OPERATION.LOCATION_HIERARCHY_V lv
    ON  lv.LOCATION_ID = st.STORE_ID
    AND lv.BRAND_ID = st.BRAND_ID
    WHERE
        od.Rn = 1
    AND dd.FISCAL_COMPARABLE_DT BETWEEN PRM_FROMDATE AND PRM_TODATE
    AND od.STORE_ID = ''06997''
    AND od.MDM_PRODUCT_ID = ''30018''
)
, src_prel_dist AS
(
    SELECT
      ORDER_ID
      , BUSINESS_DT
      , BRAND
      , STORE_ID
      , MDM_PRODUCT_ID
      , FISC_DATE_LY
      , SUM(IFNULL(DERIVED_GROSS_QTY, 0.00)) AS DERIVED_GROSS_QTY
      , SUM(IFNULL(DERIVED_NET_AMT, 0.00)) AS DERIVED_NET_AMT
    FROM
        src_prel
    GROUP BY
      ORDER_ID
      , BUSINESS_DT
      , BRAND
      , STORE_ID
      , MDM_PRODUCT_ID
      , FISC_DATE_LY
      
)
, src_prel_dist_fin AS
(
    SELECT 
      ORDER_ID
      , BUSINESS_DT
      , BRAND
      , STORE_ID
      , MDM_PRODUCT_ID

      , SUM(DERIVED_NET_AMT) OVER (PARTITION BY BUSINESS_DT, STORE_ID, FISC_DATE_LY, BRAND) AS CHECK_SALES_CY
      , COUNT(DISTINCT ORDER_ID) OVER (PARTITION BY BUSINESS_DT, STORE_ID, FISC_DATE_LY, BRAND) AS CHECK_CNT_CY
      , SUM(DERIVED_NET_AMT) OVER (PARTITION BY STORE_ID, FISC_DATE_LY, BRAND) AS REST_SALES_CY
      , COUNT(DISTINCT ORDER_ID) OVER (PARTITION BY STORE_ID, FISC_DATE_LY, BRAND) AS REST_TRANS_CY
    FROM 
      src_prel_dist
)

SELECT
    BUSINESS_DT AS FISC_DATE_LY
    , BRAND
    , STORE_ID
    , MDM_PRODUCT_ID
    
    , SUM(CHECK_SALES_CY) AS CHECK_SALES_CY
    , SUM(CHECK_CNT_CY) AS CHECK_CNT_CY
    , MAX(REST_SALES_CY) AS REST_SALES_CY
    , MAX(REST_TRANS_CY) AS REST_TRANS_CY
FROM
    src_prel_dist_fin
GROUP BY
    BUSINESS_DT
    , BRAND
    , STORE_ID
    , MDM_PRODUCT_ID
--ORDER BY
--    MDM_PRODUCT_ID
';
CREATE FUNCTION IF NOT EXISTS FISC_DAILY_PRODUCT_SALES("PRM_ORDER_DT" DATE)
RETURNS TABLE ("FISC_DATE_LY" DATE, "BRAND" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "MDM_PRODUCT_ID" NUMBER(38,0), "CHECK_SALES_LY" NUMBER(38,0), "CHECK_CNT_LY" NUMBER(38,0), "REST_SALES_LY" NUMBER(38,2), "REST_TRANS_LY" NUMBER(38,0))
LANGUAGE SQL
AS 'WITH src AS
(
    SELECT
        od.ORDER_ID
      , od.ORDERLINE_ID
      , od.ORDER_DT
      , od.ORDER_TM
      , od.STORE_ID
      , od.DMA_CD
      , od.DMA_NM
      , od.CHANNEL_ID
      , od.ORDER_CHANNEL_NM
      , od.LEVEL3_ORDER_CHANNEL_HIERARCHY_NM
      , od.LEVEL2_ORDER_CHANNEL_HIERARCHY_NM
      , od.LEVEL1_ORDER_CHANNEL_HIERARCHY_NM
      , od.FULFILLMENT_CHANNEL_NM
      , od.LEVEL3_FULFILLMENT_CHANNEL_HIERARCHY_NM
      , od.LEVEL2_FULFILLMENT_CHANNEL_HIERARCHY_NM
      , od.LEVEL1_FULFILLMENT_CHANNEL_HIERARCHY_NM
      , od.EMPLOYEE_ID
      , od.MANAGER_ID
      , od.REGISTER_ID
      , od.TAX_ID
      , od.MODIFIER_IND
      , od.TAXEXEMPT_ID
      , od.SEAT_NBR
      , od.MDM_ITEM_ID
      , od.SOURCE_SYSTEM_ID
      , od.ITEM_NM
      , od.MDM_ITEM_TYP
      , od.MDM_PRODUCT_ID
      , od.PRODUCT_NM
      , od.PRODUCT_DESC
      , od.PRODUCT_STATUS_CD
      , od.TECHNICAL_SIZE_NBR
      , od.UNIT_OF_MEASURE_VAL
      , od.NON_USA_SPECIALTY_IND
      , od.VEHICLE_NBR
      , od.HOT_PRODUCT_IND
      , od.BREAKFAST_PRODUCT_IND
      , od.PRODUCT_BRAND_NM
      , od.MENU_TYP
      , od.MENU_SECTION_TYP
      , od.GBB_MEASURE_VAL
      , od.COLD_SPACE_REQUIRED_IND
      , od.FRYER_REQUIRED_IND
      , od.PRODUCT_HIERARCHY_ID
      , od.LEVEL5_PRODUCT_HIERARCHY_NM
      , od.LEVEL4_PRODUCT_HIERARCHY_NM
      , od.LEVEL3_PRODUCT_HIERARCHY_NM
      , od.LEVEL2_PRODUCT_HIERARCHY_NM
      , od.LEVEL1_PRODUCT_HIERARCHY_NM
      , od.MDM_OFFER_ID
      , od.OFFER_NM
      , od.OFFER_DESC
      , od.OFFER_CAT
      , od.OFFER_TYP
      , od.LEVEL5_OFFER_HIERARCHY_NM
      , od.LEVEL4_OFFER_HIERARCHY_NM
      , od.LEVEL3_OFFER_HIERARCHY_NM
      , od.LEVEL2_OFFER_HIERARCHY_NM
      , od.LEVEL1_OFFER_HIERARCHY_NM
      , IFNULL(od.MDM_PARENT_ITEM_ID, 0) AS PARENT_PRODUCT_ID
      , od.PARENT_SOURCE_SYSTEM_ID
      , od.PARENT_ITEM_NM
      , od.MDM_PARENT_ITEM_TYP
      , od.SOURCE_GROSS_QTY
      , od.SOURCE_GROSS_AMT
      , od.DISCOUNT_CD
      , od.DISCOUNT_NM
      , od.SOURCE_DISCOUNT_TYP
      , od.SOURCE_DISCOUNT_AMT
      , od.SOURCE_NET_AMT
      , od.DERIVED_GROSS_QTY
      , od.RETAIL_PRICE_AMT
      , od.DERIVED_GROSS_AMT
      , od.DERIVED_NET_AMT
      , od.DERIVED_DISCOUNT_AMT
      , od.TAX_AMT
      , od.CLEARED_IND
      , od.DELETED_IND
      , od.VOIDED_IND
      , od.INVENTORY_IND
      , od.ALTERNATE1_ORDER_ID
      , od.SOURCE_NM
      , od.BRAND_ID
      , od.LOAD_DT
      , od.LAST_UPDATED_DTTM
      , od.OFFER_MISC1
      , od.OFFER_MISC2
      , od.OFFER_MISC3
      , od.OFFER_MISC4
      , od.OFFER_MISC5
      , od.OFFER_MISC6
      , od.OFFER_MISC7
      , od.OFFER_MISC8
      , od.OFFER_MISC9
      , od.OFFER_MISC10
      , od.PRODUCT_MISC1
      , od.PRODUCT_MISC2
      , od.PRODUCT_MISC3
      , od.PRODUCT_MISC4
      , od.PRODUCT_MISC5
      , od.PRODUCT_MISC6
      , od.PRODUCT_MISC7
      , od.PRODUCT_MISC8
      , od.PRODUCT_MISC9
      , od.PRODUCT_MISC10
      , od.OFFER_HIERARCHY_ID
      , ROW_NUMBER() OVER (PARTITION BY ORDER_ID, ORDERLINE_ID, STORE_ID, ORDER_DT ORDER BY ORDER_ID, ORDERLINE_ID, STORE_ID, ORDER_DT, LAST_UPDATED_DTTM DESC) as Rn
    FROM
        ORDER_DETAIL_V od
    WHERE
        IFNULL((CASE WHEN UPPER(CAST(VOIDED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(VOIDED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND IFNULL((CASE WHEN UPPER(CAST(CLEARED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(CLEARED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND IFNULL((CASE WHEN UPPER(CAST(DELETED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(DELETED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND MDM_PRODUCT_ID IS NOT NULL
    --AND od.STORE_ID = PRM_STORE_ID
    AND od.ORDER_DT = PRM_ORDER_DT
    /*AND od.MDM_PRODUCT_ID = PRM_MDM_PRODUCT_ID*/
    /*AND (CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
           WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
           WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
           WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
           WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
           WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
           WHEN od.BRAND_ID = ''rto'' THEN ''RT''
           ELSE ''UNKNOWN'' END) = PRM_BRAND*/
)
, src_prel AS
(
    SELECT
      ORDER_ID
      , ORDER_DT AS BUSINESS_DT
      , CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
           WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
           WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
           WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
           WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
           WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
           WHEN od.BRAND_ID = ''rto'' THEN ''RT''
           ELSE ''UNKNOWN'' END AS BRAND
      , od.STORE_ID
      , IFNULL(od.MDM_PRODUCT_ID, 0) AS MDM_PRODUCT_ID
      , DERIVED_GROSS_QTY
      , DERIVED_NET_AMT
      , dd.FISCAL_COMPARABLE_DT AS FISC_DATE_LY
    FROM
        src od
    INNER JOIN
        IDH_DEV.SHARED.DATE_DIM_V dd
    ON  dd.CALENDAR_DT = od.ORDER_DT
    LEFT OUTER JOIN
        IDH_DEV.SHARED.HOLIDAY_LIST_V hl
    ON  hl.DATE_KEY = dd.DATE_KEY
    LEFT OUTER JOIN
        IDH_DEV.SHARED.HOLIDAY_LIST_V hlf
    ON  TO_DATE(CAST(hlf.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = dd.FISCAL_COMPARABLE_DT
    LEFT OUTER JOIN
      IDH_DEV.SHARED.HOLIDAY_LIST_V hl_cal
    ON  TO_DATE(CAST(hl_cal.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = dd.CALENDAR_COMPARABLE_DT
    LEFT OUTER JOIN
        IDH_DEV.SHARED.STORE_SCD_V st
    ON  od.STORE_ID = st.STORE_ID
    AND od.BRAND_ID = st.BRAND_ID
    AND od.ORDER_DT BETWEEN st.EFFECTIVE_BEGIN_DT AND st.EFFECTIVE_END_DT
    LEFT OUTER JOIN 
        IDH_DEV.OPERATION.LOCATION_HIERARCHY_V lv
    ON  lv.LOCATION_ID = st.STORE_ID
    AND lv.BRAND_ID = st.BRAND_ID
    WHERE
        od.Rn = 1
)
, src_prel_dist AS
(
    SELECT
      ORDER_ID
      , BUSINESS_DT
      , BRAND
      , STORE_ID
      , MDM_PRODUCT_ID
      , FISC_DATE_LY
      , SUM(IFNULL(DERIVED_GROSS_QTY, 0.00)) AS DERIVED_GROSS_QTY
      , SUM(IFNULL(DERIVED_NET_AMT, 0.00)) AS DERIVED_NET_AMT
    FROM
        src_prel
    GROUP BY
      ORDER_ID
      , BUSINESS_DT
      , BRAND
      , STORE_ID
      , MDM_PRODUCT_ID
      , FISC_DATE_LY
      
)
, src_prel_dist_fin AS
(
    SELECT 
      ORDER_ID
      , BUSINESS_DT
      , BRAND
      , STORE_ID
      , MDM_PRODUCT_ID

      , SUM(DERIVED_NET_AMT) OVER (PARTITION BY BUSINESS_DT, STORE_ID, FISC_DATE_LY, BRAND) AS CHECK_SALES_CY
      , COUNT(DISTINCT ORDER_ID) OVER (PARTITION BY BUSINESS_DT, STORE_ID, FISC_DATE_LY, BRAND) AS CHECK_CNT_CY
      , SUM(DERIVED_NET_AMT) OVER (PARTITION BY STORE_ID, FISC_DATE_LY, BRAND) AS REST_SALES_CY
      , COUNT(DISTINCT ORDER_ID) OVER (PARTITION BY STORE_ID, FISC_DATE_LY, BRAND) AS REST_TRANS_CY
    FROM 
      src_prel_dist
)

SELECT
    BUSINESS_DT AS FISC_DATE_LY
    , BRAND
    , STORE_ID
    , MDM_PRODUCT_ID
    
    , SUM(CHECK_SALES_CY) AS CHECK_SALES_CY
    , SUM(CHECK_CNT_CY) AS CHECK_CNT_CY
    , MAX(REST_SALES_CY) AS REST_SALES_CY
    , MAX(REST_TRANS_CY) AS REST_TRANS_CY
FROM
    src_prel_dist_fin
WHERE
    BUSINESS_DT = PRM_ORDER_DT
GROUP BY
    BUSINESS_DT
    , BRAND
    , STORE_ID
    , MDM_PRODUCT_ID
--ORDER BY
--    MDM_PRODUCT_ID
';
CREATE FUNCTION IF NOT EXISTS FISC_DAILY_PRODUCT_SALES("PRM_ORDER_DT" DATE, "PRM_MDM_PRODUCT_ID" NUMBER(38,0), "PRM_BRAND" VARCHAR(16777216))
RETURNS TABLE ("FISC_DATE_LY" DATE, "BRAND" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "MDM_PRODUCT_ID" NUMBER(38,0), "CHECK_SALES_CY" NUMBER(38,0), "CHECK_CNT_CY" NUMBER(38,0), "REST_SALES_CY" NUMBER(38,2), "REST_TRANS_CY" NUMBER(38,0))
LANGUAGE SQL
AS 'WITH src AS
(
    SELECT
        od.ORDER_ID
      , od.ORDERLINE_ID
      , od.ORDER_DT
      , od.ORDER_TM
      , od.STORE_ID
      , od.DMA_CD
      , od.DMA_NM
      , od.CHANNEL_ID
      , od.ORDER_CHANNEL_NM
      , od.LEVEL3_ORDER_CHANNEL_HIERARCHY_NM
      , od.LEVEL2_ORDER_CHANNEL_HIERARCHY_NM
      , od.LEVEL1_ORDER_CHANNEL_HIERARCHY_NM
      , od.FULFILLMENT_CHANNEL_NM
      , od.LEVEL3_FULFILLMENT_CHANNEL_HIERARCHY_NM
      , od.LEVEL2_FULFILLMENT_CHANNEL_HIERARCHY_NM
      , od.LEVEL1_FULFILLMENT_CHANNEL_HIERARCHY_NM
      , od.EMPLOYEE_ID
      , od.MANAGER_ID
      , od.REGISTER_ID
      , od.TAX_ID
      , od.MODIFIER_IND
      , od.TAXEXEMPT_ID
      , od.SEAT_NBR
      , od.MDM_ITEM_ID
      , od.SOURCE_SYSTEM_ID
      , od.ITEM_NM
      , od.MDM_ITEM_TYP
      , od.MDM_PRODUCT_ID
      , od.PRODUCT_NM
      , od.PRODUCT_DESC
      , od.PRODUCT_STATUS_CD
      , od.TECHNICAL_SIZE_NBR
      , od.UNIT_OF_MEASURE_VAL
      , od.NON_USA_SPECIALTY_IND
      , od.VEHICLE_NBR
      , od.HOT_PRODUCT_IND
      , od.BREAKFAST_PRODUCT_IND
      , od.PRODUCT_BRAND_NM
      , od.MENU_TYP
      , od.MENU_SECTION_TYP
      , od.GBB_MEASURE_VAL
      , od.COLD_SPACE_REQUIRED_IND
      , od.FRYER_REQUIRED_IND
      , od.PRODUCT_HIERARCHY_ID
      , od.LEVEL5_PRODUCT_HIERARCHY_NM
      , od.LEVEL4_PRODUCT_HIERARCHY_NM
      , od.LEVEL3_PRODUCT_HIERARCHY_NM
      , od.LEVEL2_PRODUCT_HIERARCHY_NM
      , od.LEVEL1_PRODUCT_HIERARCHY_NM
      , od.MDM_OFFER_ID
      , od.OFFER_NM
      , od.OFFER_DESC
      , od.OFFER_CAT
      , od.OFFER_TYP
      , od.LEVEL5_OFFER_HIERARCHY_NM
      , od.LEVEL4_OFFER_HIERARCHY_NM
      , od.LEVEL3_OFFER_HIERARCHY_NM
      , od.LEVEL2_OFFER_HIERARCHY_NM
      , od.LEVEL1_OFFER_HIERARCHY_NM
      , IFNULL(od.MDM_PARENT_ITEM_ID, 0) AS PARENT_PRODUCT_ID
      , od.PARENT_SOURCE_SYSTEM_ID
      , od.PARENT_ITEM_NM
      , od.MDM_PARENT_ITEM_TYP
      , od.SOURCE_GROSS_QTY
      , od.SOURCE_GROSS_AMT
      , od.DISCOUNT_CD
      , od.DISCOUNT_NM
      , od.SOURCE_DISCOUNT_TYP
      , od.SOURCE_DISCOUNT_AMT
      , od.SOURCE_NET_AMT
      , od.DERIVED_GROSS_QTY
      , od.RETAIL_PRICE_AMT
      , od.DERIVED_GROSS_AMT
      , od.DERIVED_NET_AMT
      , od.DERIVED_DISCOUNT_AMT
      , od.TAX_AMT
      , od.CLEARED_IND
      , od.DELETED_IND
      , od.VOIDED_IND
      , od.INVENTORY_IND
      , od.ALTERNATE1_ORDER_ID
      , od.SOURCE_NM
      , od.BRAND_ID
      , od.LOAD_DT
      , od.LAST_UPDATED_DTTM
      , od.OFFER_MISC1
      , od.OFFER_MISC2
      , od.OFFER_MISC3
      , od.OFFER_MISC4
      , od.OFFER_MISC5
      , od.OFFER_MISC6
      , od.OFFER_MISC7
      , od.OFFER_MISC8
      , od.OFFER_MISC9
      , od.OFFER_MISC10
      , od.PRODUCT_MISC1
      , od.PRODUCT_MISC2
      , od.PRODUCT_MISC3
      , od.PRODUCT_MISC4
      , od.PRODUCT_MISC5
      , od.PRODUCT_MISC6
      , od.PRODUCT_MISC7
      , od.PRODUCT_MISC8
      , od.PRODUCT_MISC9
      , od.PRODUCT_MISC10
      , od.OFFER_HIERARCHY_ID
      , ROW_NUMBER() OVER (PARTITION BY ORDER_ID, ORDERLINE_ID, STORE_ID, ORDER_DT ORDER BY ORDER_ID, ORDERLINE_ID, STORE_ID, ORDER_DT, LAST_UPDATED_DTTM DESC) as Rn
    FROM
        ORDER_DETAIL_V od
    WHERE
        IFNULL((CASE WHEN UPPER(CAST(VOIDED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(VOIDED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND IFNULL((CASE WHEN UPPER(CAST(CLEARED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(CLEARED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND IFNULL((CASE WHEN UPPER(CAST(DELETED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(DELETED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND MDM_PRODUCT_ID IS NOT NULL
    --AND od.STORE_ID = PRM_STORE_ID
    AND od.ORDER_DT = PRM_ORDER_DT
    AND od.MDM_PRODUCT_ID = PRM_MDM_PRODUCT_ID
    AND (CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
           WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
           WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
           WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
           WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
           WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
           WHEN od.BRAND_ID = ''rto'' THEN ''RT''
           ELSE ''UNKNOWN'' END) = PRM_BRAND
)
, src_prel AS
(
    SELECT
      ORDER_ID
      , ORDER_DT AS BUSINESS_DT
      , CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
           WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
           WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
           WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
           WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
           WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
           WHEN od.BRAND_ID = ''rto'' THEN ''RT''
           ELSE ''UNKNOWN'' END AS BRAND
      , od.STORE_ID
      , IFNULL(od.MDM_PRODUCT_ID, 0) AS MDM_PRODUCT_ID
      , DERIVED_GROSS_QTY
      , DERIVED_NET_AMT
      , dd.FISCAL_COMPARABLE_DT AS FISC_DATE_LY
    FROM
        src od
    INNER JOIN
        IDH_DEV.SHARED.DATE_DIM_V dd
    ON  dd.CALENDAR_DT = od.ORDER_DT
    LEFT OUTER JOIN
        IDH_DEV.SHARED.HOLIDAY_LIST_V hl
    ON  hl.DATE_KEY = dd.DATE_KEY
    LEFT OUTER JOIN
        IDH_DEV.SHARED.HOLIDAY_LIST_V hlf
    ON  TO_DATE(CAST(hlf.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = dd.FISCAL_COMPARABLE_DT
    LEFT OUTER JOIN
      IDH_DEV.SHARED.HOLIDAY_LIST_V hl_cal
    ON  TO_DATE(CAST(hl_cal.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = dd.CALENDAR_COMPARABLE_DT
    LEFT OUTER JOIN
        IDH_DEV.SHARED.STORE_SCD_V st
    ON  od.STORE_ID = st.STORE_ID
    AND od.BRAND_ID = st.BRAND_ID
    AND od.ORDER_DT BETWEEN st.EFFECTIVE_BEGIN_DT AND st.EFFECTIVE_END_DT
    LEFT OUTER JOIN 
        IDH_DEV.OPERATION.LOCATION_HIERARCHY_V lv
    ON  lv.LOCATION_ID = st.STORE_ID
    AND lv.BRAND_ID = st.BRAND_ID
    WHERE
        od.Rn = 1
)
, src_prel_dist AS
(
    SELECT
      ORDER_ID
      , BUSINESS_DT
      , BRAND
      , STORE_ID
      , MDM_PRODUCT_ID
      , FISC_DATE_LY
      , SUM(IFNULL(DERIVED_GROSS_QTY, 0.00)) AS DERIVED_GROSS_QTY
      , SUM(IFNULL(DERIVED_NET_AMT, 0.00)) AS DERIVED_NET_AMT
    FROM
        src_prel
    GROUP BY
      ORDER_ID
      , BUSINESS_DT
      , BRAND
      , STORE_ID
      , MDM_PRODUCT_ID
      , FISC_DATE_LY
      
)
, src_prel_dist_fin AS
(
    SELECT 
      ORDER_ID
      , BUSINESS_DT
      , BRAND
      , STORE_ID
      , MDM_PRODUCT_ID

      , SUM(DERIVED_NET_AMT) OVER (PARTITION BY BUSINESS_DT, STORE_ID, FISC_DATE_LY, BRAND) AS CHECK_SALES_CY
      , COUNT(DISTINCT ORDER_ID) OVER (PARTITION BY BUSINESS_DT, STORE_ID, FISC_DATE_LY, BRAND) AS CHECK_CNT_CY
      , SUM(DERIVED_NET_AMT) OVER (PARTITION BY STORE_ID, FISC_DATE_LY, BRAND) AS REST_SALES_CY
      , COUNT(DISTINCT ORDER_ID) OVER (PARTITION BY STORE_ID, FISC_DATE_LY, BRAND) AS REST_TRANS_CY
    FROM 
      src_prel_dist
)

SELECT
    BUSINESS_DT AS FISC_DATE_LY
    , BRAND
    , STORE_ID
    , MDM_PRODUCT_ID
    
    , SUM(CHECK_SALES_CY) AS CHECK_SALES_CY
    , SUM(CHECK_CNT_CY) AS CHECK_CNT_CY
    , MAX(REST_SALES_CY) AS REST_SALES_CY
    , MAX(REST_TRANS_CY) AS REST_TRANS_CY
FROM
    src_prel_dist_fin
GROUP BY
    BUSINESS_DT
    , BRAND
    , STORE_ID
    , MDM_PRODUCT_ID
--ORDER BY
--    MDM_PRODUCT_ID
';
