      , od.OFFER_HIERARCHY_ID
      , ROW_NUMBER() OVER (PARTITION BY ORDER_ID, ORDERLINE_ID, STORE_ID, ORDER_DT ORDER BY ORDER_ID, ORDERLINE_ID, STORE_ID, ORDER_DT, LAST_UPDATED_DTTM DESC) as Rn
    FROM
