    WHERE
        IFNULL((CASE WHEN UPPER(CAST(VOIDED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(VOIDED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND IFNULL((CASE WHEN UPPER(CAST(CLEARED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(CLEARED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND IFNULL((CASE WHEN UPPER(CAST(DELETED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(DELETED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND MDM_PRODUCT_ID IS NOT NULL
    AND od.STORE_ID = PRM_STORE_ID
    AND od.ORDER_DT = PRM_ORDER_DT
    AND od.MDM_PRODUCT_ID = PRM_MDM_PRODUCT_ID
    AND (CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
           WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
           WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
           WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
           WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
           WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
           WHEN od.BRAND_ID = ''rto'' THEN ''RT''
           ELSE ''UNKNOWN'' END) = PRM_BRAND
)
, src_prel AS
(
    SELECT
      ORDER_ID
      , ORDER_DT AS BUSINESS_DT
      , CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
           WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
           WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
           WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
           WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
           WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
           WHEN od.BRAND_ID = ''rto'' THEN ''RT''
           ELSE ''UNKNOWN'' END AS BRAND
      , od.STORE_ID
      , IFNULL(od.MDM_PRODUCT_ID, 0) AS MDM_PRODUCT_ID
      , DERIVED_GROSS_QTY
      , DERIVED_NET_AMT
      , dd.FISCAL_COMPARABLE_DT AS FISC_DATE_LY
    FROM
        src od
    INNER JOIN
        IDH_DEV.SHARED.DATE_DIM_V dd
    ON  dd.CALENDAR_DT = od.ORDER_DT
    LEFT OUTER JOIN
        IDH_DEV.SHARED.HOLIDAY_LIST_V hl
    ON  hl.DATE_KEY = dd.DATE_KEY
    LEFT OUTER JOIN
        IDH_DEV.SHARED.HOLIDAY_LIST_V hlf
    ON  TO_DATE(CAST(hlf.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = dd.FISCAL_COMPARABLE_DT
    LEFT OUTER JOIN
      IDH_DEV.SHARED.HOLIDAY_LIST_V hl_cal
    ON  TO_DATE(CAST(hl_cal.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = dd.CALENDAR_COMPARABLE_DT
    LEFT OUTER JOIN
        IDH_DEV.SHARED.STORE_SCD_V st
    ON  od.STORE_ID = st.STORE_ID
    AND od.BRAND_ID = st.BRAND_ID
    AND od.ORDER_DT BETWEEN st.EFFECTIVE_BEGIN_DT AND st.EFFECTIVE_END_DT
    LEFT OUTER JOIN 
        IDH_DEV.OPERATION.LOCATION_HIERARCHY_V lv
    ON  lv.LOCATION_ID = st.STORE_ID
    AND lv.BRAND_ID = st.BRAND_ID
    WHERE
        od.Rn = 1
)
, src_prel_dist AS
(
    SELECT
      ORDER_ID
      , BUSINESS_DT
      , BRAND
      , STORE_ID
      , MDM_PRODUCT_ID
      , FISC_DATE_LY
      , SUM(IFNULL(DERIVED_GROSS_QTY, 0.00)) AS DERIVED_GROSS_QTY
      , SUM(IFNULL(DERIVED_NET_AMT, 0.00)) AS DERIVED_NET_AMT
    FROM
        src_prel
    GROUP BY
      ORDER_ID
      , BUSINESS_DT
      , BRAND
      , STORE_ID
      , MDM_PRODUCT_ID
      , FISC_DATE_LY
      
)
, src_prel_dist_fin AS
(
    SELECT 
      ORDER_ID
      , BUSINESS_DT
      , BRAND
      , STORE_ID
      , MDM_PRODUCT_ID

      , SUM(DERIVED_NET_AMT) OVER (PARTITION BY BUSINESS_DT, STORE_ID, FISC_DATE_LY, BRAND) AS CHECK_SALES_CY
      , COUNT(DISTINCT ORDER_ID) OVER (PARTITION BY BUSINESS_DT, STORE_ID, FISC_DATE_LY, BRAND) AS CHECK_CNT_CY
      , SUM(DERIVED_NET_AMT) OVER (PARTITION BY STORE_ID, FISC_DATE_LY, BRAND) AS REST_SALES_CY
      , COUNT(DISTINCT ORDER_ID) OVER (PARTITION BY STORE_ID, FISC_DATE_LY, BRAND) AS REST_TRANS_CY
    FROM 
      src_prel_dist
)

SELECT
    BUSINESS_DT AS FISC_DATE_LY
    , BRAND
    , STORE_ID
    , MDM_PRODUCT_ID
    
    , SUM(CHECK_SALES_CY) AS CHECK_SALES_CY
    , SUM(CHECK_CNT_CY) AS CHECK_CNT_CY
    , MAX(REST_SALES_CY) AS REST_SALES_CY
    , MAX(REST_TRANS_CY) AS REST_TRANS_CY
FROM
    src_prel_dist_fin
GROUP BY
    BUSINESS_DT
    , BRAND
    , STORE_ID
    , MDM_PRODUCT_ID
--ORDER BY
--    MDM_PRODUCT_ID
';
CREATE FUNCTION IF NOT EXISTS FISC_DAILY_PRODUCT_SALES("STORE_ID" VARCHAR(16777216), "ORDER_DT" DATE, "MDM_PRODUCT_ID" VARCHAR(16777216), "BRAND" VARCHAR(16777216))
RETURNS TABLE ("FISC_DATE_LY" DATE, "BRAND" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "MDM_PRODUCT_ID" VARCHAR(16777216), "CHECK_SALES_CY" NUMBER(38,0), "CHECK_CNT_CY" NUMBER(38,0), "REST_SALES_CY" NUMBER(38,2), "REST_TRANS_CY" NUMBER(38,0))
LANGUAGE SQL
AS '


WITH src AS
(
    SELECT
        od.ORDER_ID
      , od.ORDERLINE_ID
      , od.ORDER_DT
      , od.ORDER_TM
      , od.STORE_ID
      , od.DMA_CD
      , od.DMA_NM
      , od.CHANNEL_ID
      , od.ORDER_CHANNEL_NM
      , od.LEVEL3_ORDER_CHANNEL_HIERARCHY_NM
      , od.LEVEL2_ORDER_CHANNEL_HIERARCHY_NM
      , od.LEVEL1_ORDER_CHANNEL_HIERARCHY_NM
      , od.FULFILLMENT_CHANNEL_NM
      , od.LEVEL3_FULFILLMENT_CHANNEL_HIERARCHY_NM
      , od.LEVEL2_FULFILLMENT_CHANNEL_HIERARCHY_NM
      , od.LEVEL1_FULFILLMENT_CHANNEL_HIERARCHY_NM
      , od.EMPLOYEE_ID
      , od.MANAGER_ID
      , od.REGISTER_ID
      , od.TAX_ID
      , od.MODIFIER_IND
      , od.TAXEXEMPT_ID
      , od.SEAT_NBR
      , od.MDM_ITEM_ID
      , od.SOURCE_SYSTEM_ID
      , od.ITEM_NM
      , od.MDM_ITEM_TYP
      , od.MDM_PRODUCT_ID
      , od.PRODUCT_NM
      , od.PRODUCT_DESC
      , od.PRODUCT_STATUS_CD
      , od.TECHNICAL_SIZE_NBR
      , od.UNIT_OF_MEASURE_VAL
      , od.NON_USA_SPECIALTY_IND
      , od.VEHICLE_NBR
      , od.HOT_PRODUCT_IND
      , od.BREAKFAST_PRODUCT_IND
      , od.PRODUCT_BRAND_NM
      , od.MENU_TYP
      , od.MENU_SECTION_TYP
      , od.GBB_MEASURE_VAL
      , od.COLD_SPACE_REQUIRED_IND
      , od.FRYER_REQUIRED_IND
      , od.PRODUCT_HIERARCHY_ID
      , od.LEVEL5_PRODUCT_HIERARCHY_NM
      , od.LEVEL4_PRODUCT_HIERARCHY_NM
      , od.LEVEL3_PRODUCT_HIERARCHY_NM
      , od.LEVEL2_PRODUCT_HIERARCHY_NM
      , od.LEVEL1_PRODUCT_HIERARCHY_NM
      , od.MDM_OFFER_ID
      , od.OFFER_NM
      , od.OFFER_DESC
      , od.OFFER_CAT
      , od.OFFER_TYP
      , od.LEVEL5_OFFER_HIERARCHY_NM
      , od.LEVEL4_OFFER_HIERARCHY_NM
      , od.LEVEL3_OFFER_HIERARCHY_NM
      , od.LEVEL2_OFFER_HIERARCHY_NM
      , od.LEVEL1_OFFER_HIERARCHY_NM
      , IFNULL(od.MDM_PARENT_ITEM_ID, 0) AS PARENT_PRODUCT_ID
      , od.PARENT_SOURCE_SYSTEM_ID
      , od.PARENT_ITEM_NM
      , od.MDM_PARENT_ITEM_TYP
      , od.SOURCE_GROSS_QTY
      , od.SOURCE_GROSS_AMT
      , od.DISCOUNT_CD
      , od.DISCOUNT_NM
      , od.SOURCE_DISCOUNT_TYP
      , od.SOURCE_DISCOUNT_AMT
      , od.SOURCE_NET_AMT
      , od.DERIVED_GROSS_QTY
      , od.RETAIL_PRICE_AMT
      , od.DERIVED_GROSS_AMT
      , od.DERIVED_NET_AMT
      , od.DERIVED_DISCOUNT_AMT
      , od.TAX_AMT
      , od.CLEARED_IND
      , od.DELETED_IND
      , od.VOIDED_IND
      , od.INVENTORY_IND
      , od.ALTERNATE1_ORDER_ID
      , od.SOURCE_NM
      , od.BRAND_ID
      , od.LOAD_DT
      , od.LAST_UPDATED_DTTM
      , od.OFFER_MISC1
      , od.OFFER_MISC2
      , od.OFFER_MISC3
      , od.OFFER_MISC4
      , od.OFFER_MISC5
      , od.OFFER_MISC6
      , od.OFFER_MISC7
      , od.OFFER_MISC8
      , od.OFFER_MISC9
      , od.OFFER_MISC10
      , od.PRODUCT_MISC1
      , od.PRODUCT_MISC2
      , od.PRODUCT_MISC3
      , od.PRODUCT_MISC4
      , od.PRODUCT_MISC5
      , od.PRODUCT_MISC6
      , od.PRODUCT_MISC7
      , od.PRODUCT_MISC8
      , od.PRODUCT_MISC9
      , od.PRODUCT_MISC10
      , od.OFFER_HIERARCHY_ID
      , ROW_NUMBER() OVER (PARTITION BY ORDER_ID, ORDERLINE_ID, STORE_ID, ORDER_DT ORDER BY ORDER_ID, ORDERLINE_ID, STORE_ID, ORDER_DT, LAST_UPDATED_DTTM DESC) as Rn
    FROM
        ORDER_DETAIL_V od
    WHERE
        IFNULL((CASE WHEN UPPER(CAST(VOIDED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(VOIDED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND IFNULL((CASE WHEN UPPER(CAST(CLEARED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(CLEARED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND IFNULL((CASE WHEN UPPER(CAST(DELETED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(DELETED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND MDM_PRODUCT_ID IS NOT NULL
    AND od.STORE_ID = ''06941''
    AND od.ORDER_DT = ''2018-02-06''
    AND od.MDM_PRODUCT_ID = ''30000''
    AND (CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
           WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
           WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
           WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
           WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
           WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
           WHEN od.BRAND_ID = ''rto'' THEN ''RT''
           ELSE ''UNKNOWN'' END) = ''ARB''
)
, src_prel AS
(
    SELECT
      ORDER_ID
      , ORDER_DT AS BUSINESS_DT
      , CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
           WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
           WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
           WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
           WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
           WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
           WHEN od.BRAND_ID = ''rto'' THEN ''RT''
           ELSE ''UNKNOWN'' END AS BRAND
      , od.STORE_ID
      , IFNULL(od.MDM_PRODUCT_ID, 0) AS MDM_PRODUCT_ID
      , DERIVED_GROSS_QTY
      , DERIVED_NET_AMT
      , dd.FISCAL_COMPARABLE_DT AS FISC_DATE_LY
    FROM
        src od
    INNER JOIN
        IDH_DEV.SHARED.DATE_DIM_V dd
    ON  dd.CALENDAR_DT = od.ORDER_DT
    LEFT OUTER JOIN
        IDH_DEV.SHARED.HOLIDAY_LIST_V hl
    ON  hl.DATE_KEY = dd.DATE_KEY
    LEFT OUTER JOIN
        IDH_DEV.SHARED.HOLIDAY_LIST_V hlf
    ON  TO_DATE(CAST(hlf.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = dd.FISCAL_COMPARABLE_DT
    LEFT OUTER JOIN
      IDH_DEV.SHARED.HOLIDAY_LIST_V hl_cal
    ON  TO_DATE(CAST(hl_cal.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = dd.CALENDAR_COMPARABLE_DT
    LEFT OUTER JOIN
        IDH_DEV.SHARED.STORE_SCD_V st
    ON  od.STORE_ID = st.STORE_ID
    AND od.BRAND_ID = st.BRAND_ID
    AND od.ORDER_DT BETWEEN st.EFFECTIVE_BEGIN_DT AND st.EFFECTIVE_END_DT
    LEFT OUTER JOIN 
        IDH_DEV.OPERATION.LOCATION_HIERARCHY_V lv
    ON  lv.LOCATION_ID = st.STORE_ID
    AND lv.BRAND_ID = st.BRAND_ID
    WHERE
        od.Rn = 1
)
, src_prel_dist AS
(
    SELECT
      ORDER_ID
      , BUSINESS_DT
      , BRAND
      , STORE_ID
      , MDM_PRODUCT_ID
      , FISC_DATE_LY
      , SUM(IFNULL(DERIVED_GROSS_QTY, 0.00)) AS DERIVED_GROSS_QTY
      , SUM(IFNULL(DERIVED_NET_AMT, 0.00)) AS DERIVED_NET_AMT
    FROM
        src_prel
    GROUP BY
      ORDER_ID
      , BUSINESS_DT
      , BRAND
      , STORE_ID
      , MDM_PRODUCT_ID
      , FISC_DATE_LY
      
)
, src_prel_dist_fin AS
(
    SELECT 
      ORDER_ID
      , BUSINESS_DT
      , BRAND
      , STORE_ID
      , MDM_PRODUCT_ID

      , SUM(DERIVED_NET_AMT) OVER (PARTITION BY BUSINESS_DT, STORE_ID, FISC_DATE_LY, BRAND) AS CHECK_SALES_CY
      , COUNT(DISTINCT ORDER_ID) OVER (PARTITION BY BUSINESS_DT, STORE_ID, FISC_DATE_LY, BRAND) AS CHECK_CNT_CY
      , SUM(DERIVED_NET_AMT) OVER (PARTITION BY STORE_ID, FISC_DATE_LY, BRAND) AS REST_SALES_CY
      , COUNT(DISTINCT ORDER_ID) OVER (PARTITION BY STORE_ID, FISC_DATE_LY, BRAND) AS REST_TRANS_CY
    FROM 
      src_prel_dist
)

SELECT
    BUSINESS_DT AS FISC_DATE_LY
    , BRAND
    , STORE_ID
    , MDM_PRODUCT_ID
    
    , SUM(CHECK_SALES_CY) AS CHECK_SALES_CY
    , SUM(CHECK_CNT_CY) AS CHECK_CNT_CY
    , MAX(REST_SALES_CY) AS REST_SALES_CY
    , MAX(REST_TRANS_CY) AS REST_TRANS_CY
FROM
    src_prel_dist_fin
GROUP BY
    BUSINESS_DT
    , BRAND
    , STORE_ID
    , MDM_PRODUCT_ID
ORDER BY
    MDM_PRODUCT_ID
    
';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_DAY("BUSINESS_DATE" DATE, "TIME_INTERVAL" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BUSINESS_DT" DATE, "TRANS_CNT" NUMBER(38,0), "NET_SALES" NUMBER(38,2), "COMP_TRANS" NUMBER(38,0), "COMP_SALES" NUMBER(38,2), "AGG_START_DT" DATE, "AGG_LEVEL" VARCHAR(16777216), "DMA_NAME" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "OWNERSHIP_TYPE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "OPEN_15P_FLAG" BOOLEAN, "CLOSED_BEFORE_PERIOD_END_FLAG" BOOLEAN, "OPEN_AFTER_HONEYMOON_FLAG" BOOLEAN, "WEEKDAY_OFFSET" ARRAY, "WEEK_TRANS_CNTS" ARRAY, "WEEK_NET_SALES" ARRAY, "IS_XMAS_THANKSGIVING" BOOLEAN, "DAY_OF_WEEK" VARCHAR(10), "END_DT" DATE, "THRESHOLD_FLAG" BOOLEAN)
LANGUAGE SQL
AS '

WITH COMP_DATE AS 
(
 SELECT  
       calendar_dt -- comparison date
    ,  MAX_OPEN_DT -- ODI-53 maximum open date for which the store will be comp when reporting at BUSINESS_DATE
    ,  MAX_HONEY_DT -- ODI-199 maximum open date for which the store will be out of honeymoon period (3 full fiscal periods) at BUSINESS_DATE
FROM TABLE(FLASH_SUMMARY_COMP_HONEYMOON((SELECT MAX(A.CALENDAR_DT) 
FROM IDS_DEV.INT_REF.COMP_DATES A
WHERE A.BUSINESS_DT BETWEEN BUSINESS_DATE - iff(TIME_INTERVAL = ''CY'', 9, 16) AND BUSINESS_DATE
AND A.TIME_INTERVAL = TIME_INTERVAL),''CY'')) 
),

SLS AS (
    select * from IDS_DEV.DATASTORE.DAILY_FLASH_SALES_STG as STG where SESSION_NO = CURRENT_SESSION() and STG.TIME_INTERVAL = TIME_INTERVAL
)
SELECT 
      SLS.BRAND_ID
    , STORE_ID
    , SLS.BUSINESS_DT
    , SUM(Trans_Cnt) as Trans_Cnt
    , SUM(Net_Sales) as Net_Sales
    , SUM(Trans_Cnt) as Comp_Trans
    , SUM(Net_Sales) as Comp_Sales
    , SLS.BUSINESS_DT as AGG_START_DT
    , ''DAY'' AS AGG_LEVEL
    , DMA_NAME 
    , DMA_CODE
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , MAX(nvl(OPEN_DATE, MAX_OPEN_DT)) <= MAX(MAX_OPEN_DT) as OPEN_15P_FLAG -- ODI-53
    , NULL as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , MAX(nvl(SLS.OPEN_DATE, COMP_DATE.MAX_HONEY_DT)) <= MAX(COMP_DATE.MAX_HONEY_DT) as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , NULL as WEEKDAY_OFFSET --ODI-2977
    , NULL as WEEK_TRANS_CNTS --ODI-2977
    , NULL as WEEK_NET_SALES --ODI-2977
    , max(hol.date_key is not null) as IS_XMAS_THANKSGIVING --ODI-3039
    , max(DT.CALENDAR_DAY_NM) as DAY_OF_WEEK --ODI-3551
    , SLS.BUSINESS_DT as END_DT
    , SLS.THRESHOLD_FLAG
FROM 
    SLS
INNER JOIN 
    COMP_DATE 
ON  SLS.BUSINESS_DT BETWEEN COMP_DATE.CALENDAR_DT - iff(TIME_INTERVAL = ''CY'', 9, 16) AND COMP_DATE.CALENDAR_DT
INNER JOIN
    IDS_DEV.INT_REF.COMP_DATES DT
ON  SLS.BUSINESS_DT = DT.CALENDAR_DT
AND DT.TIME_INTERVAL =''CY''
LEFT JOIN
    IDH_DEV.SHARED.HOLIDAY_DIM_V as hol
ON  SLS.BUSINESS_DT = TO_DATE(cast(hol.DATE_KEY as string), ''YYYYMMDD'')
AND hol.HOLIDAY_NM IN (''THANKSGIVING DAY'',''CHRISTMAS DAY'')
GROUP BY    
      SLS.BRAND_ID
    , STORE_ID
    , SLS.BUSINESS_DT
    , ''DAY'' 
    , DMA_NAME 
    , DMA_CODE
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , COMP_DATE.CALENDAR_DT
    , SLS.THRESHOLD_FLAG

';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_DAY("BUSINESS_DATE" DATE, "TIME_INTERVAL" VARCHAR(16777216), "REPORT_BRAND" VARCHAR(16777216), "THRESHOLD_FLAG" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BUSINESS_DT" DATE, "TRANS_CNT" NUMBER(38,0), "NET_SALES" NUMBER(38,2), "COMP_TRANS" NUMBER(38,0), "COMP_SALES" NUMBER(38,2), "AGG_START_DT" DATE, "AGG_LEVEL" VARCHAR(16777216), "DMA_NAME" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "OWNERSHIP_TYPE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "OPEN_15P_FLAG" BOOLEAN, "CLOSED_BEFORE_PERIOD_END_FLAG" BOOLEAN, "OPEN_AFTER_HONEYMOON_FLAG" BOOLEAN, "WEEKDAY_OFFSET" ARRAY, "WEEK_TRANS_CNTS" ARRAY, "WEEK_NET_SALES" ARRAY, "IS_XMAS_THANKSGIVING" BOOLEAN, "DAY_OF_WEEK" VARCHAR(10), "END_DT" DATE)
LANGUAGE SQL
AS '

WITH COMP_DATE AS 
(
 SELECT  
       calendar_dt -- comparison date
    ,  MAX_OPEN_DT -- ODI-53 maximum open date for which the store will be comp when reporting at BUSINESS_DATE
    ,  MAX_HONEY_DT -- ODI-199 maximum open date for which the store will be out of honeymoon period (3 full fiscal periods) at BUSINESS_DATE
FROM TABLE(FLASH_SUMMARY_COMP_HONEYMOON((SELECT MAX(A.CALENDAR_DT) 
FROM IDS_DEV.INT_REF.COMP_DATES A
WHERE A.BUSINESS_DT BETWEEN BUSINESS_DATE - iff(TIME_INTERVAL = ''CY'', 9, 16) AND BUSINESS_DATE
AND A.TIME_INTERVAL = TIME_INTERVAL),''CY'')) 
),

SLS AS (
    select * from table(DAILY_FLASH_SALES_V(BUSINESS_DATE, TIME_INTERVAL))
)
SELECT 
      SLS.BRAND_ID
    , STORE_ID
    , SLS.BUSINESS_DT
    , SUM(Trans_Cnt) as Trans_Cnt
    , SUM(Net_Sales) as Net_Sales
    , SUM(Trans_Cnt) as Comp_Trans
    , SUM(Net_Sales) as Comp_Sales
    , SLS.BUSINESS_DT as AGG_START_DT
    , ''DAY'' AS AGG_LEVEL
    , DMA_NAME 
    , DMA_CODE
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , MAX(nvl(OPEN_DATE, MAX_OPEN_DT)) <= MAX(MAX_OPEN_DT) as OPEN_15P_FLAG -- ODI-53
    , NULL as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , MAX(nvl(SLS.OPEN_DATE, COMP_DATE.MAX_HONEY_DT)) <= MAX(COMP_DATE.MAX_HONEY_DT) as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , NULL as WEEKDAY_OFFSET --ODI-2977
    , NULL as WEEK_TRANS_CNTS --ODI-2977
    , NULL as WEEK_NET_SALES --ODI-2977
    , max(hol.date_key is not null) as IS_XMAS_THANKSGIVING --ODI-3039
    , max(DT.CALENDAR_DAY_NM) as DAY_OF_WEEK --ODI-3551
    , SLS.BUSINESS_DT as END_DT
FROM 
    SLS
INNER JOIN 
    COMP_DATE 
ON  SLS.BUSINESS_DT BETWEEN COMP_DATE.CALENDAR_DT - iff(TIME_INTERVAL = ''CY'', 9, 16) AND COMP_DATE.CALENDAR_DT
INNER JOIN
    IDS_DEV.INT_REF.COMP_DATES DT
ON  SLS.BUSINESS_DT = DT.CALENDAR_DT
AND DT.TIME_INTERVAL =''CY''
LEFT JOIN
    IDH_DEV.SHARED.HOLIDAY_DIM_V as hol
ON  SLS.BUSINESS_DT = TO_DATE(cast(hol.DATE_KEY as string), ''YYYYMMDD'')
AND hol.HOLIDAY_NM IN (''THANKSGIVING DAY'',''CHRISTMAS DAY'')
GROUP BY    
      SLS.BRAND_ID
    , STORE_ID
    , SLS.BUSINESS_DT
    , ''DAY'' 
    , DMA_NAME 
    , DMA_CODE
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , COMP_DATE.CALENDAR_DT

';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_DAYS_IN_WEEKS("BUSINESS_DATE" DATE)
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "THRESHOLD_FLAG" BOOLEAN, "FISCAL_WEEK_START_DT" DATE, "FISCAL_PERIOD_START_DT" DATE, "FISCAL_QUARTER_START_DT" DATE, "FISCAL_YEAR_START_DT" DATE, "FISCAL_1YR_COMP_WEEK_DT" DATE, "FISCAL_1YR_COMP_PERIOD_DT" DATE, "FISCAL_1YR_COMP_QUARTER_DT" DATE, "FISCAL_1YR_COMP_YEAR_DT" DATE, "FISC_1Y_SALES" NUMBER(38,2), "FISC_1Y_TRANS" NUMBER(38,0), "CALENDAR_1YR_COMP_WEEK_DT" DATE, "CALENDAR_1YR_COMP_PERIOD_DT" DATE, "CALENDAR_1YR_COMP_QUARTER_DT" DATE, "CALENDAR_1YR_COMP_YEAR_DT" DATE, "CAL_1Y_SALES" NUMBER(38,2), "CAL_1Y_TRANS" NUMBER(38,0), "CALENDAR_2YR_COMP_WEEK_DT" DATE, "CALENDAR_2YR_COMP_PERIOD_DT" DATE, "CALENDAR_2YR_COMP_QUARTER_DT" DATE, "CALENDAR_2YR_COMP_YEAR_DT" DATE, "CAL_2Y_SALES" NUMBER(38,2), "CAL_2Y_TRANS" NUMBER(38,0), "CALENDAR_3YR_COMP_WEEK_DT" DATE, "CALENDAR_3YR_COMP_PERIOD_DT" DATE, "CALENDAR_3YR_COMP_QUARTER_DT" DATE, "CALENDAR_3YR_COMP_YEAR_DT" DATE, "CAL_3Y_SALES" NUMBER(38,2), "CAL_3Y_TRANS" NUMBER(38,0))
LANGUAGE SQL
AS '

    select CY.BRAND_ID, CY.STORE_ID, CY.THRESHOLD_FLAG, CY.FISCAL_WEEK_START_DT, CY.FISCAL_PERIOD_START_DT, CY.FISCAL_QUARTER_START_DT, CY.FISCAL_YEAR_START_DT,
    FISC1Y.FISCAL_WEEK_START_DT, FISC1Y.FISCAL_PERIOD_START_DT, FISC1Y.FISCAL_QUARTER_START_DT, FISC1Y.FISCAL_YEAR_START_DT,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, FISC1Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(FISC1Y.WEEK_NET_SALES, CY.WEEK_NET_SALES, CY.WEEKDAY_OFFSET, FISC1Y.WEEKDAY_OFFSET) END as Fisc1y_Sales,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, FISC1Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(FISC1Y.WEEK_TRANS_CNTS, CY.WEEK_TRANS_CNTS, CY.WEEKDAY_OFFSET, FISC1Y.WEEKDAY_OFFSET) END as Fisc1y_Trans,
    CAL1Y.FISCAL_WEEK_START_DT, CAL1Y.FISCAL_PERIOD_START_DT, CAL1Y.FISCAL_QUARTER_START_DT, CAL1Y.FISCAL_YEAR_START_DT,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, CAL1Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(CAL1Y.WEEK_NET_SALES, CY.WEEK_NET_SALES, CY.WEEKDAY_OFFSET, CAL1Y.WEEKDAY_OFFSET) END as Cal1y_Sales,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, CAL1Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(CAL1Y.WEEK_TRANS_CNTS, CY.WEEK_TRANS_CNTS, CY.WEEKDAY_OFFSET, CAL1Y.WEEKDAY_OFFSET) END as Cal1y_Trans,
    CAL2Y.FISCAL_WEEK_START_DT, CAL2Y.FISCAL_PERIOD_START_DT, CAL2Y.FISCAL_QUARTER_START_DT, CAL2Y.FISCAL_YEAR_START_DT,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, CAL2Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(CAL2Y.WEEK_NET_SALES, CY.WEEK_NET_SALES, CY.WEEKDAY_OFFSET, CAL2Y.WEEKDAY_OFFSET) END as Cal2y_Sales,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, CAL2Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(CAL2Y.WEEK_TRANS_CNTS, CY.WEEK_TRANS_CNTS, CY.WEEKDAY_OFFSET, CAL2Y.WEEKDAY_OFFSET) END as Cal2y_Trans,
    CAL3Y.FISCAL_WEEK_START_DT, CAL3Y.FISCAL_PERIOD_START_DT, CAL3Y.FISCAL_QUARTER_START_DT, CAL3Y.FISCAL_YEAR_START_DT,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, CAL3Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(CAL3Y.WEEK_NET_SALES, CY.WEEK_NET_SALES, CY.WEEKDAY_OFFSET, CAL3Y.WEEKDAY_OFFSET) END as Cal3y_Sales,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, CAL3Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(CAL3Y.WEEK_TRANS_CNTS, CY.WEEK_TRANS_CNTS, CY.WEEKDAY_OFFSET, CAL3Y.WEEKDAY_OFFSET) END as Cal3y_Trans
    from 
    table(FLASH_SUMMARY_COMP_PAST_DAYS(BUSINESS_DATE, ''CY'')) CY
    LEFT OUTER JOIN table(FLASH_SUMMARY_COMP_PAST_DAYS(BUSINESS_DATE, ''FISC1Y'')) FISC1Y
    ON CY.BRAND_ID = FISC1Y.BRAND_ID
    AND CY.STORE_ID = FISC1Y.STORE_ID
    AND CY.FISCAL_WEEK_NBR = FISC1Y.FISCAL_WEEK_NBR
    LEFT OUTER JOIN table(FLASH_SUMMARY_COMP_PAST_DAYS(BUSINESS_DATE, ''CAL1Y'')) CAL1Y
    ON CY.BRAND_ID = CAL1Y.BRAND_ID
    AND CY.STORE_ID = CAL1Y.STORE_ID
    AND CY.FISCAL_WEEK_NBR = CAL1Y.FISCAL_WEEK_NBR
    LEFT OUTER JOIN table(FLASH_SUMMARY_COMP_PAST_DAYS(BUSINESS_DATE, ''CAL2Y'')) CAL2Y
    ON CY.BRAND_ID = CAL2Y.BRAND_ID
    AND CY.STORE_ID = CAL2Y.STORE_ID
    AND CY.FISCAL_WEEK_NBR = CAL2Y.FISCAL_WEEK_NBR
    LEFT OUTER JOIN table(FLASH_SUMMARY_COMP_PAST_DAYS(BUSINESS_DATE, ''CAL3Y'')) CAL3Y
    ON CY.BRAND_ID = CAL3Y.BRAND_ID
    AND CY.STORE_ID = CAL3Y.STORE_ID
    AND CY.FISCAL_WEEK_NBR = CAL3Y.FISCAL_WEEK_NBR
where NOT CY.THRESHOLD_FLAG 

';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_DAY_F("BUSINESS_DATE" DATE, "TIME_INTERVAL" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BUSINESS_DT" DATE, "TRANS_CNT" NUMBER(38,0), "NET_SALES" NUMBER(38,2), "COMP_TRANS" NUMBER(38,0), "COMP_SALES" NUMBER(38,2), "AGG_START_DT" DATE, "AGG_LEVEL" VARCHAR(16777216), "DMA_NAME" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "OWNERSHIP_TYPE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "OPEN_15P_FLAG" BOOLEAN, "CLOSED_BEFORE_PERIOD_END_FLAG" BOOLEAN, "OPEN_AFTER_HONEYMOON_FLAG" BOOLEAN, "WEEKDAY_OFFSET" ARRAY, "WEEK_TRANS_CNTS" ARRAY, "WEEK_NET_SALES" ARRAY, "IS_XMAS_THANKSGIVING" BOOLEAN, "DAY_OF_WEEK" VARCHAR(10), "END_DT" DATE)
LANGUAGE SQL
AS '

WITH COMP_DATE AS 
(
 SELECT  
       calendar_dt -- comparison date
    ,  MAX_OPEN_DT -- ODI-53 maximum open date for which the store will be comp when reporting at BUSINESS_DATE
    ,  MAX_HONEY_DT -- ODI-199 maximum open date for which the store will be out of honeymoon period (3 full fiscal periods) at BUSINESS_DATE
FROM TABLE(FLASH_SUMMARY_COMP_HONEYMOON((SELECT MAX(A.CALENDAR_DT) 
FROM IDS_DEV.INT_REF.COMP_DATES A
WHERE A.BUSINESS_DT BETWEEN BUSINESS_DATE - iff(TIME_INTERVAL = ''CY'', 9, 16) AND BUSINESS_DATE
AND A.TIME_INTERVAL = TIME_INTERVAL),''CY'')) 
),

SLS AS (
    select * from table(DAILY_FLASH_SALES_V_F(BUSINESS_DATE, TIME_INTERVAL))
)
SELECT 
      SLS.BRAND_ID
    , STORE_ID
    , SLS.BUSINESS_DT
    , SUM(Trans_Cnt) as Trans_Cnt
    , SUM(Net_Sales) as Net_Sales
    , SUM(Trans_Cnt) as Comp_Trans
    , SUM(Net_Sales) as Comp_Sales
    , SLS.BUSINESS_DT as AGG_START_DT
    , ''DAY'' AS AGG_LEVEL
    , DMA_NAME 
    , DMA_CODE
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , MAX(nvl(OPEN_DATE, MAX_OPEN_DT)) <= MAX(MAX_OPEN_DT) as OPEN_15P_FLAG -- ODI-53
    , NULL as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , MAX(nvl(SLS.OPEN_DATE, COMP_DATE.MAX_HONEY_DT)) <= MAX(COMP_DATE.MAX_HONEY_DT) as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , NULL as WEEKDAY_OFFSET --ODI-2977
    , NULL as WEEK_TRANS_CNTS --ODI-2977
    , NULL as WEEK_NET_SALES --ODI-2977
    , max(hol.date_key is not null) as IS_XMAS_THANKSGIVING --ODI-3039
    , max(DT.CALENDAR_DAY_NM) as DAY_OF_WEEK --ODI-3551
    , SLS.BUSINESS_DT as END_DT
FROM 
    SLS
INNER JOIN 
    COMP_DATE 
ON  SLS.BUSINESS_DT BETWEEN COMP_DATE.CALENDAR_DT - iff(TIME_INTERVAL = ''CY'', 9, 16) AND COMP_DATE.CALENDAR_DT
INNER JOIN
    IDS_DEV.INT_REF.COMP_DATES DT
ON  SLS.BUSINESS_DT = DT.CALENDAR_DT
AND DT.TIME_INTERVAL =''CY''
LEFT JOIN
    IDH_DEV.SHARED.HOLIDAY_DIM_V as hol
ON  SLS.BUSINESS_DT = TO_DATE(cast(hol.DATE_KEY as string), ''YYYYMMDD'')
AND hol.HOLIDAY_NM IN (''THANKSGIVING DAY'',''CHRISTMAS DAY'')
GROUP BY    
      SLS.BRAND_ID
    , STORE_ID
    , SLS.BUSINESS_DT
    , ''DAY'' 
    , DMA_NAME 
    , DMA_CODE
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , COMP_DATE.CALENDAR_DT

';
