SELECT
    calendar_dt
    , MAX_OPEN_DT
    , MAX_HONEY_DT
FROM TABLE (FLASH_SUMMARY_COMP_HONEYMOON_without_threshold(BUSINESS_DATE, BUSINESS_DATE, TIME_INTERVAL))
';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_HONEYMOON_WITHOUT_THRESHOLD("DATE_FROM" DATE, "DATE_TO" DATE, "TIME_INTERVAL" VARCHAR(16777216))
RETURNS TABLE ("CALENDAR_DT" DATE, "MAX_OPEN_DT" DATE, "MAX_HONEY_DT" DATE)
LANGUAGE SQL
AS '

WITH COMP_DATES AS 
(
SELECT DISTINCT DT.CALENDAR_DT
FROM
IDS_DEV.INT_REF.COMP_DATES DT
WHERE DT.BUSINESS_DT BETWEEN DATE_FROM and DATE_TO
AND DT.TIME_INTERVAL = TIME_INTERVAL
)

    SELECT  
      busdt.calendar_dt AS calendar_dt -- comparison date
    , opendt.calendar_dt as MAX_OPEN_DT -- ODI-53 maximum open date for which the store will be comp when reporting at BUSINESS_DATE
    , opendthoney.calendar_dt as MAX_HONEY_DT -- ODI-199 maximum open date for which the store will be out of honeymoon period (3 full fiscal periods) at BUSINESS_DATE
FROM IDH_DEV.SHARED.DATE_DIM_V as opendt
INNER JOIN IDH_DEV.SHARED.DATE_DIM_V as busdt
on
    iff (opendt.FISCAL_PERIOD_START_DT = opendt.CALENDAR_DT
        , iff((opendt.FISCAL_PERIOD_NBR+15)%12 = 0, 12, (opendt.FISCAL_PERIOD_NBR+15)%12)
        , iff((opendt.FISCAL_PERIOD_NBR+16)%12 = 0, 12, (opendt.FISCAL_PERIOD_NBR+16)%12)
    ) = busdt.FISCAL_PERIOD_NBR
and iff (opendt.FISCAL_PERIOD_START_DT = opendt.CALENDAR_DT
        , opendt.FISCAL_YEAR_NBR + trunc((opendt.FISCAL_PERIOD_NBR+14)/12)
        , opendt.FISCAL_YEAR_NBR + trunc((opendt.FISCAL_PERIOD_NBR+15)/12)
    ) = busdt.FISCAL_YEAR_NBR  
INNER JOIN IDH_DEV.SHARED.DATE_DIM_V as opendthoney --ODI-199
on
    iff ((opendthoney.FISCAL_PERIOD_NBR +
            iff(opendthoney.FISCAL_PERIOD_START_DT = opendthoney.CALENDAR_DT, 3, 4)
    ) % 12 = 0, 12, (opendthoney.FISCAL_PERIOD_NBR +
              iff(opendthoney.FISCAL_PERIOD_START_DT = opendthoney.CALENDAR_DT, 3, 4)
      ) % 12
    ) = busdt.FISCAL_PERIOD_NBR
and 
    opendthoney.FISCAL_YEAR_NBR + trunc(
        (opendthoney.FISCAL_PERIOD_NBR +
                iff(opendthoney.FISCAL_PERIOD_START_DT = opendthoney.CALENDAR_DT, 2, 3)
        ) / 12
    ) = busdt.FISCAL_YEAR_NBR
INNER JOIN  COMP_DATES
ON busdt.calendar_dt = COMP_DATES.CALENDAR_DT   
where opendt.calendar_dt = opendt.FISCAL_PERIOD_START_DT
and opendthoney.calendar_dt = opendthoney.FISCAL_PERIOD_START_DT

';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_NULL_PERIODS("BUSINESS_DATE" DATE)
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BUSINESS_DT" DATE, "FISCAL_YEAR_START_DT" DATE, "PERIOD_ARRAY" ARRAY, "ARRAY_SALES" ARRAY, "ARRAY_TRANS" ARRAY)
LANGUAGE SQL
AS '

WITH PAST AS (
SELECT store_id, brand_id,business_dt,FISCAL_YEAR_START_DT,
 fiscal_period_nbr , Net_Sales, Trans_Cnt
FROM table(FLASH_SUMMARY_COMP_PAST_PERIODS(BUSINESS_DATE))
WHERE NET_SALES IS NOT NULL
AND comp_sales IS NULL
AND business_dt = BUSINESS_DATE
),
PTD AS (
    SELECT store_id, brand_id,calendar_dt,FISCAL_YEAR_START_DT,
fiscal_period_nbr , Net_Sales, Trans_Cnt
FROM table(FLASH_SUMMARY_COMP_PTD(BUSINESS_DATE))
WHERE NET_SALES IS NOT NULL
AND comp_sales IS NULL
AND calendar_dt = BUSINESS_DATE
)
SELECT NVL(PTD.brand_id,PAST.brand_id), NVL(PTD.store_id,PAST.store_id) ,NVL(PTD.calendar_dt,PAST.business_dt),NVL(PAST.FISCAL_YEAR_START_DT,PTD.FISCAL_YEAR_START_DT),
ARRAY_CAT(ARRAY_AGG(PAST.fiscal_period_nbr),ARRAY_AGG(distinct PTD.fiscal_period_nbr)) AS ARRAY_PERIODS,
ARRAY_CAT(ARRAY_AGG(PAST.Net_Sales),ARRAY_AGG(distinct PTD.Net_Sales)) AS ARRAY_SALES,
ARRAY_CAT(ARRAY_AGG(PAST.Trans_Cnt),ARRAY_AGG(distinct PTD.Trans_Cnt)) AS ARRAY_TRANS
FROM PTD FULL OUTER JOIN PAST
ON PAST.STORE_ID = PTD.STORE_ID
AND PAST.BRAND_ID = PTD.BRAND_ID
AND PAST.BUSINESS_DT = PTD.calendar_dt
group by PTD.store_id, PTD.brand_id,PTD.calendar_dt,PAST.store_id,PAST.brand_id,PAST.business_dt, PAST.FISCAL_YEAR_START_DT, PTD.FISCAL_YEAR_START_DT
ORDER BY NVL(PTD.store_id,PAST.store_id)

';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_PAST_DAYS("BUSINESS_DATE" DATE, "TIME_INTERVAL" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BUSINESS_DT" DATE, "FISCAL_WEEK_START_DT" DATE, "FISCAL_WEEK_NBR" NUMBER(38,0), "FISCAL_PERIOD_START_DT" DATE, "FISCAL_YEAR_START_DT" DATE, "FISCAL_QUARTER_START_DT" DATE, "THRESHOLD_FLAG" BOOLEAN, "WEEKDAY_OFFSET" ARRAY, "WEEK_TRANS_CNTS" ARRAY, "WEEK_NET_SALES" ARRAY)
LANGUAGE SQL
AS '

SELECT  
      SLS.BRAND_ID
    , SLS.STORE_ID
    , BDT.CALENDAR_DT
    , DT.FISCAL_WEEK_START_DT 
    , DT.FISCAL_WEEK_NBR
    , DT.FISCAL_PERIOD_START_DT 
    , DT.FISCAL_YEAR_START_DT
    , DT.FISCAL_QUARTER_START_DT
    , SLS.THRESHOLD_FLAG
    , ARRAY_AGG(SLS.BUSINESS_DT - DT.FISCAL_WEEK_START_DT) AS WEEKDAY_OFFSET
    , ARRAY_AGG(NVL(Trans_Cnt,0)) as WEEK_TRANS_CNTS 
    , ARRAY_AGG(NVL(Net_Sales,0)) as WEEK_NET_SALES

FROM  
IDS_DEV.INT_REF.COMP_DATES BDT
INNER JOIN 
    IDS_DEV.INT_REF.COMP_DATES DT
ON  DT.CALENDAR_DT  <=  BDT.CALENDAR_DT
AND DT.BUSINESS_DT  <= BDT.BUSINESS_DT
AND DT.TIME_INTERVAL = BDT.TIME_INTERVAL
AND DT.FISCAL_WEEK_NBR != 53
AND DT.FISCAL_YEAR_START_DT = BDT.FISCAL_YEAR_START_DT
INNER JOIN IDS_DEV.DATASTORE.DAILY_FLASH_SALES_STG SLS
ON SLS.BUSINESS_DT = DT.CALENDAR_DT
AND SLS.SESSION_NO = CURRENT_SESSION()
AND SLS.TIME_INTERVAL = TIME_INTERVAL
where BDT.BUSINESS_DT = BUSINESS_DATE
AND BDT.TIME_INTERVAL = TIME_INTERVAL
GROUP BY        
      SLS.BRAND_ID
    , SLS.STORE_ID
    , BDT.CALENDAR_DT
    , DT.FISCAL_WEEK_START_DT 
    , DT.FISCAL_WEEK_NBR
    , DT.FISCAL_PERIOD_START_DT
    , DT.FISCAL_PERIOD_END_DT
    , DT.FISCAL_YEAR_START_DT
    , DT.FISCAL_QUARTER_START_DT
    , SLS.THRESHOLD_FLAG

    ';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_PAST_DAYS_F("BUSINESS_DATE" DATE, "TIME_INTERVAL" VARCHAR(16777216), "BRAND" VARCHAR(16777216), "THRESHOLD_FLG" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BUSINESS_DT" DATE, "FISCAL_WEEK_START_DT" DATE, "FISCAL_WEEK_NBR" NUMBER(38,0), "FISCAL_PERIOD_START_DT" DATE, "FISCAL_YEAR_START_DT" DATE, "FISCAL_QUARTER_START_DT" DATE, "THRESHOLD_FLAG" BOOLEAN, "WEEKDAY_OFFSET" ARRAY, "WEEK_TRANS_CNTS" ARRAY, "WEEK_NET_SALES" ARRAY)
LANGUAGE SQL
AS '

SELECT  
      SLS.BRAND_ID
    , SLS.STORE_ID
    , BDT.CALENDAR_DT
    , DT.FISCAL_WEEK_START_DT 
    , DT.FISCAL_WEEK_NBR
    , DT.FISCAL_PERIOD_START_DT 
    , DT.FISCAL_YEAR_START_DT
    , DT.FISCAL_QUARTER_START_DT
    , SLS.THRESHOLD_FLAG
    , ARRAY_AGG(SLS.BUSINESS_DT - DT.FISCAL_WEEK_START_DT) AS WEEKDAY_OFFSET
    , ARRAY_AGG(NVL(Trans_Cnt,0)) as WEEK_TRANS_CNTS 
    , ARRAY_AGG(NVL(Net_Sales,0)) as WEEK_NET_SALES

FROM  
IDS_DEV.INT_REF.COMP_DATES BDT
INNER JOIN 
    IDS_DEV.INT_REF.COMP_DATES DT
ON  DT.CALENDAR_DT  <=  BDT.CALENDAR_DT
AND DT.BUSINESS_DT  <= BDT.BUSINESS_DT
AND DT.TIME_INTERVAL = BDT.TIME_INTERVAL
AND DT.FISCAL_WEEK_NBR != 53
AND DT.FISCAL_YEAR_START_DT = BDT.FISCAL_YEAR_START_DT
INNER JOIN table(DAILY_FLASH_SALES_V_F(BUSINESS_DATE, TIME_INTERVAL, BRAND, THRESHOLD_FLG)) SLS
ON SLS.BUSINESS_DT = DT.CALENDAR_DT
where BDT.BUSINESS_DT = BUSINESS_DATE
AND BDT.TIME_INTERVAL = TIME_INTERVAL
GROUP BY        
      SLS.BRAND_ID
    , SLS.STORE_ID
    , BDT.CALENDAR_DT
    , DT.FISCAL_WEEK_START_DT 
    , DT.FISCAL_WEEK_NBR
    , DT.FISCAL_PERIOD_START_DT
    , DT.FISCAL_PERIOD_END_DT
    , DT.FISCAL_YEAR_START_DT
    , DT.FISCAL_QUARTER_START_DT
    , SLS.THRESHOLD_FLAG

    ';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_PAST_PERIODS("BUSINESS_DATE" DATE, "TIME_INTERVAL" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BUSINESS_DT" DATE, "TRANS_CNT" NUMBER(38,0), "NET_SALES" NUMBER(38,2), "COMP_TRANS" NUMBER(38,0), "COMP_SALES" NUMBER(38,2), "AGG_START_DT" DATE, "FISCAL_PERIOD_NBR" NUMBER(38,0), "FISCAL_YEAR_START_DT" DATE, "FISCAL_QUARTER_START_DT" DATE, "CLOSED_BEFORE_PERIOD_END_FLAG" BOOLEAN, "TEMP_CLOSED_FLAG" BOOLEAN)
LANGUAGE SQL
AS '

WITH COMP_DATE AS 
(
    SELECT  
       s.calendar_dt -- comparison date
    ,  MAX_OPEN_DT -- ODI-53 maximum open date for which the store will be comp when reporting at BUSINESS_DATE
    ,  MAX_HONEY_DT -- ODI-199 maximum open date for which the store will be out of honeymoon period (3 full fiscal periods) at BUSINESS_DATE
FROM TABLE(FLASH_SUMMARY_COMP_HONEYMOON(BUSINESS_DATE,TIME_INTERVAL)) as s

)

SELECT  --ODI-2123
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT
    , SUM(SLS.Trans_Cnt) as Trans_Cnt
    , SUM(SLS.Net_Sales) as Net_Sales
    , SUM(CASE WHEN SLS.FISCAL_WEEK_NBR = 53 
      THEN 0 ELSE SLS.Trans_Cnt END) as Comp_Trans
    , SUM(CASE WHEN SLS.FISCAL_WEEK_NBR = 53 
      THEN 0 ELSE SLS.Net_Sales END) as Comp_Sales
    , DT.FISCAL_PERIOD_START_DT AGG_START_DT
    , DT.FISCAL_PERIOD_NBR
    , DT.FISCAL_YEAR_START_DT
    , DT.FISCAL_QUARTER_START_DT
    , MAX(NVL(SLS.CLOSURE_DATE, DT.FISCAL_PERIOD_END_DT)) < MAX(DT.FISCAL_PERIOD_END_DT) --ODI-55
        and MAX(NVL(SLS.CLOSURE_DATE, DT.FISCAL_PERIOD_END_DT)) <= COMP_DATE.CALENDAR_DT as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-3733
    ,(least(nvl(max(REOPEN_DATE),DT.FISCAL_PERIOD_END_DT), DT.FISCAL_PERIOD_END_DT, COMP_DATE.CALENDAR_DT)
            - greatest(nvl(max(TEMP_CLOSED_DATE),DT.FISCAL_PERIOD_START_DT), DT.FISCAL_PERIOD_START_DT) >= 7 
        and max(TEMP_CLOSED_DATE) is not null) as TEMP_CLOSED_FLAG
FROM 
    IDS_DEV.INT_REF.DAILY_FLASH_SALES_TEMP SLS
INNER JOIN 
    COMP_DATE
ON SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN 
    IDS_DEV.INT_REF.COMP_DATES DT
ON  SLS.BUSINESS_DT = DT.CALENDAR_DT
AND DT.TIME_INTERVAL = TIME_INTERVAL
AND SLS.TIME_INTERVAL = TIME_INTERVAL
GROUP BY    
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT
    , DT.FISCAL_PERIOD_START_DT
    , DT.FISCAL_PERIOD_END_DT
    , DT.FISCAL_PERIOD_NBR
    , DT.FISCAL_YEAR_START_DT
    , DT.FISCAL_QUARTER_START_DT

    ';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_PAST_PERIODS_F("BUSINESS_DATE" DATE, "TIME_INTERVAL" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BUSINESS_DT" DATE, "TRANS_CNT" NUMBER(38,0), "NET_SALES" NUMBER(38,2), "COMP_TRANS" NUMBER(38,0), "COMP_SALES" NUMBER(38,2), "AGG_START_DT" DATE, "FISCAL_PERIOD_NBR" NUMBER(38,0), "FISCAL_YEAR_START_DT" DATE, "FISCAL_QUARTER_START_DT" DATE, "CLOSED_BEFORE_PERIOD_END_FLAG" BOOLEAN, "TEMP_CLOSED_FLAG" BOOLEAN)
LANGUAGE SQL
AS '

WITH COMP_DATE AS 
(
    SELECT  
       s.calendar_dt -- comparison date
    ,  MAX_OPEN_DT -- ODI-53 maximum open date for which the store will be comp when reporting at BUSINESS_DATE
    ,  MAX_HONEY_DT -- ODI-199 maximum open date for which the store will be out of honeymoon period (3 full fiscal periods) at BUSINESS_DATE
FROM TABLE(FLASH_SUMMARY_COMP_HONEYMOON(BUSINESS_DATE,TIME_INTERVAL)) as s

)

SELECT  --ODI-2123
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT
    , SUM(SLS.Trans_Cnt) as Trans_Cnt
    , SUM(SLS.Net_Sales) as Net_Sales
    , SUM(CASE WHEN SLS.FISCAL_WEEK_NBR = 53 
      THEN 0 ELSE SLS.Trans_Cnt END) as Comp_Trans
    , SUM(CASE WHEN SLS.FISCAL_WEEK_NBR = 53 
      THEN 0 ELSE SLS.Net_Sales END) as Comp_Sales
    , DT.FISCAL_PERIOD_START_DT AGG_START_DT
    , DT.FISCAL_PERIOD_NBR
    , DT.FISCAL_YEAR_START_DT
    , DT.FISCAL_QUARTER_START_DT
    , MAX(NVL(SLS.CLOSURE_DATE, DT.FISCAL_PERIOD_END_DT)) < MAX(DT.FISCAL_PERIOD_END_DT) --ODI-55
        and MAX(NVL(SLS.CLOSURE_DATE, DT.FISCAL_PERIOD_END_DT)) <= COMP_DATE.CALENDAR_DT as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-3733
    ,(least(nvl(max(REOPEN_DATE),DT.FISCAL_PERIOD_END_DT), DT.FISCAL_PERIOD_END_DT, COMP_DATE.CALENDAR_DT)
            - greatest(nvl(max(TEMP_CLOSED_DATE),DT.FISCAL_PERIOD_START_DT), DT.FISCAL_PERIOD_START_DT) >= 7 
        and max(TEMP_CLOSED_DATE) is not null) as TEMP_CLOSED_FLAG
FROM 
    table(DAILY_FLASH_SALES_V_F(BUSINESS_DATE,TIME_INTERVAL)) SLS
INNER JOIN 
    COMP_DATE
ON SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN 
    IDS_DEV.INT_REF.COMP_DATES DT
ON  SLS.BUSINESS_DT = DT.CALENDAR_DT
AND DT.TIME_INTERVAL = TIME_INTERVAL
GROUP BY    
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT
    , DT.FISCAL_PERIOD_START_DT
    , DT.FISCAL_PERIOD_END_DT
    , DT.FISCAL_PERIOD_NBR
    , DT.FISCAL_YEAR_START_DT
    , DT.FISCAL_QUARTER_START_DT

    ';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_PAST_WEEKS("BUSINESS_DATE" DATE, "TIME_INTERVAL" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BUSINESS_DT" DATE, "TRANS_CNT" NUMBER(38,0), "NET_SALES" NUMBER(38,2), "COMP_TRANS" NUMBER(38,0), "COMP_SALES" NUMBER(38,2), "AGG_START_DT" DATE, "FISCAL_WEEK_NBR" NUMBER(38,0), "FISCAL_PERIOD_START_DT" DATE, "FISCAL_YEAR_START_DT" DATE, "FISCAL_QUARTER_START_DT" DATE, "CLOSED_BEFORE_PERIOD_END_FLAG" BOOLEAN, "TEMP_CLOSED_FLAG" BOOLEAN)
LANGUAGE SQL
AS '

WITH TEMP_CLOSED AS (
SELECT
BRAND_ID,
STORE_ID, 
BUSINESS_DT,
FISCAL_PERIOD_START_DT,
FISCAL_QUARTER_START_DT,
FISCAL_YEAR_START_DT,
CLOSED_BEFORE_PERIOD_END_FLAG,
TEMP_CLOSED_FLAG
FROM 
table(FLASH_SUMMARY_COMP_PERIODS_TEMP_CLOSED(BUSINESS_DATE,TIME_INTERVAL))
)

SELECT  
      SLS.BRAND_ID
    , SLS.STORE_ID
    , BDT.CALENDAR_DT
    , SUM(nvl(SLS.Trans_Cnt,0)) as Trans_Cnt
    , SUM(nvl(SLS.Net_Sales,0)) as Net_Sales
    , SUM(CASE WHEN SLS.FISCAL_WEEK_NBR = 53
      THEN 0 ELSE nvl(SLS.Trans_Cnt,0) END) as Comp_Trans
    , SUM(CASE WHEN SLS.FISCAL_WEEK_NBR = 53
      THEN 0 ELSE nvl(SLS.Net_Sales,0) END) as Comp_Sales
    , DT.FISCAL_WEEK_START_DT 
    , DT.FISCAL_WEEK_NBR
    , DT.FISCAL_PERIOD_START_DT 
    , DT.FISCAL_YEAR_START_DT
    , DT.FISCAL_QUARTER_START_DT
    , T.CLOSED_BEFORE_PERIOD_END_FLAG 
    , T.TEMP_CLOSED_FLAG
FROM  
IDS_DEV.INT_REF.COMP_DATES BDT
INNER JOIN 
    IDS_DEV.INT_REF.COMP_DATES DT
ON  DT.CALENDAR_DT  <=  BDT.CALENDAR_DT
AND DT.BUSINESS_DT  <= BDT.BUSINESS_DT
AND DT.TIME_INTERVAL = BDT.TIME_INTERVAL
AND DT.FISCAL_YEAR_START_DT = BDT.FISCAL_YEAR_START_DT
INNER JOIN IDS_DEV.DATASTORE.DAILY_FLASH_SALES_STG SLS
ON SLS.BUSINESS_DT = DT.CALENDAR_DT
AND SLS.SESSION_NO = CURRENT_SESSION()
AND SLS.TIME_INTERVAL = TIME_INTERVAL
LEFT OUTER JOIN TEMP_CLOSED T
ON SLS.BRAND_ID = T.BRAND_ID
AND SLS.STORE_ID = T.STORE_ID
AND DT.FISCAL_PERIOD_START_DT = T.FISCAL_PERIOD_START_DT
where BDT.BUSINESS_DT = BUSINESS_DATE
AND BDT.TIME_INTERVAL = TIME_INTERVAL
GROUP BY        
      SLS.BRAND_ID
    , SLS.STORE_ID
    , BDT.CALENDAR_DT
    , DT.FISCAL_WEEK_START_DT 
    , DT.FISCAL_WEEK_NBR
    , DT.FISCAL_PERIOD_START_DT
    , DT.FISCAL_PERIOD_END_DT
    , DT.FISCAL_YEAR_START_DT
    , DT.FISCAL_QUARTER_START_DT
    , T.CLOSED_BEFORE_PERIOD_END_FLAG 
    , T.TEMP_CLOSED_FLAG

';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_PAST_WEEKS("BUSINESS_DATE" DATE, "TIME_INTERVAL" VARCHAR(16777216), "REPORT_BRAND" VARCHAR(16777216), "THRESHOLD_FLAG" VARCHAR(16777216))
