    , DT.FISCAL_PERIOD_START_DT
    , DT.FISCAL_PERIOD_END_DT
    , DT.FISCAL_YEAR_START_DT
    , DT.FISCAL_QUARTER_START_DT
    , T.CLOSED_BEFORE_PERIOD_END_FLAG 
    , T.TEMP_CLOSED_FLAG

';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_PAST_WEEKS_F("BUSINESS_DATE" DATE, "TIME_INTERVAL" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BUSINESS_DT" DATE, "TRANS_CNT" NUMBER(38,0), "NET_SALES" NUMBER(38,2), "COMP_TRANS" NUMBER(38,0), "COMP_SALES" NUMBER(38,2), "AGG_START_DT" DATE, "FISCAL_WEEK_NBR" NUMBER(38,0), "FISCAL_PERIOD_START_DT" DATE, "FISCAL_YEAR_START_DT" DATE, "FISCAL_QUARTER_START_DT" DATE, "CLOSED_BEFORE_PERIOD_END_FLAG" BOOLEAN, "TEMP_CLOSED_FLAG" BOOLEAN)
LANGUAGE SQL
