CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_PERIODS_TEMP_CLOSED("BUSINESS_DATE" DATE, "TIME_INTERVAL" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BUSINESS_DT" DATE, "FISCAL_PERIOD_START_DT" DATE, "FISCAL_YEAR_START_DT" DATE, "FISCAL_QUARTER_START_DT" DATE, "CLOSED_BEFORE_PERIOD_END_FLAG" BOOLEAN, "TEMP_CLOSED_FLAG" BOOLEAN)
LANGUAGE SQL
AS '

SELECT  
      SLS.BRAND_ID
    , SLS.STORE_ID
    , BDT.CALENDAR_DT
    , DT.FISCAL_PERIOD_START_DT 
    , DT.FISCAL_YEAR_START_DT
    , DT.FISCAL_QUARTER_START_DT
    , MAX(NVL(SLS.CLOSURE_DATE, DT.FISCAL_PERIOD_END_DT)) < MAX(DT.FISCAL_PERIOD_END_DT) --ODI-55
        and MAX(NVL(SLS.CLOSURE_DATE, DT.FISCAL_PERIOD_END_DT)) <= BDT.CALENDAR_DT as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-3733
    , (least(nvl(max(REOPEN_DATE -1),DT.FISCAL_PERIOD_END_DT), DT.FISCAL_PERIOD_END_DT, BDT.CALENDAR_DT)
            - greatest(nvl(max(TEMP_CLOSED_DATE),DT.FISCAL_PERIOD_START_DT), DT.FISCAL_PERIOD_START_DT) >= 6 
        and max(TEMP_CLOSED_DATE) is not null) as TEMP_CLOSED_FLAG
FROM  
IDS_DEV.INT_REF.COMP_DATES BDT
INNER JOIN 
    IDS_DEV.INT_REF.COMP_DATES DT
ON  DT.CALENDAR_DT  <=  BDT.CALENDAR_DT
AND DT.BUSINESS_DT  <= BDT.BUSINESS_DT
AND DT.TIME_INTERVAL = BDT.TIME_INTERVAL
AND DT.FISCAL_YEAR_START_DT = BDT.FISCAL_YEAR_START_DT
INNER JOIN IDS_DEV.DATASTORE.DAILY_FLASH_SALES_STG SLS
ON SLS.BUSINESS_DT = DT.CALENDAR_DT
AND SLS.SESSION_NO = CURRENT_SESSION()
AND SLS.TIME_INTERVAL = TIME_INTERVAL
where BDT.BUSINESS_DT = BUSINESS_DATE
AND BDT.TIME_INTERVAL = TIME_INTERVAL
GROUP BY        
      SLS.BRAND_ID
    , SLS.STORE_ID
    , BDT.CALENDAR_DT
    , DT.FISCAL_PERIOD_START_DT
    , DT.FISCAL_PERIOD_END_DT
    , DT.FISCAL_YEAR_START_DT
    , DT.FISCAL_QUARTER_START_DT

';
