CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_PTD("BUSINESS_DATE" DATE, "TIME_INTERVAL" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "CALENDAR_DT" DATE, "TRANS_CNT" NUMBER(38,0), "NET_SALES" NUMBER(38,2), "COMP_TRANS" NUMBER(38,0), "COMP_SALES" NUMBER(38,2), "AGG_START_DT" DATE, "AGG_LEVEL" VARCHAR(16777216), "DMA_NAME" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "OPEN_15P_FLAG" BOOLEAN, "CLOSED_BEFORE_PERIOD_END_FLAG" BOOLEAN, "OPEN_AFTER_HONEYMOON_FLAG" BOOLEAN, "WEEKDAY_OFFSET" ARRAY, "WEEK_TRANS_CNTS" ARRAY, "WEEK_NET_SALES" ARRAY, "FISCAL_PERIOD_NBR" NUMBER(38,0), "FISCAL_YEAR_START_DT" DATE, "END_DT" DATE, "TEMP_CLOSED_FLAG" BOOLEAN)
LANGUAGE SQL
AS '

WITH COMP_DATE AS 
(
    SELECT  
       s.calendar_dt -- comparison date
    ,  MAX_OPEN_DT -- ODI-53 maximum open date for which the store will be comp when reporting at BUSINESS_DATE
    ,  MAX_HONEY_DT -- ODI-199 maximum open date for which the store will be out of honeymoon period (3 full fiscal periods) at BUSINESS_DATE
FROM TABLE(FLASH_SUMMARY_COMP_HONEYMOON(BUSINESS_DATE,TIME_INTERVAL)) as s

)

SELECT  --ODI-2123
      SLS.BRAND_ID
    , STORE_ID
    , COMP_DATE.CALENDAR_DT 
    , SUM(nvl(SLS.Trans_Cnt,0)) as Trans_Cnt
    , SUM(nvl(SLS.Net_Sales,0)) as Net_Sales
    , SUM(CASE WHEN SLS.FISCAL_WEEK_NBR = 53 
      THEN 0 ELSE nvl(SLS.Trans_Cnt,0) END) as Comp_Trans
    , SUM(CASE WHEN SLS.FISCAL_WEEK_NBR = 53 
      THEN 0 ELSE nvl(SLS.Net_Sales,0) END) as Comp_Sales
    , DT.FISCAL_PERIOD_START_DT AGG_START_DT
    , ''PTD'' AS Agg_Level
    , DMA_NAME 
    , DMA_CODE
    , STATE
    , COUNTRY
    , MAX(nvl(OPEN_DATE, MAX_OPEN_DT)) <= MAX(MAX_OPEN_DT) as OPEN_15P_FLAG -- ODI-53
    , MAX(NVL(SLS.CLOSURE_DATE, DT.FISCAL_PERIOD_END_DT)) < MAX(DT.FISCAL_PERIOD_END_DT) --ODI-55
        and MAX(NVL(SLS.CLOSURE_DATE, DT.FISCAL_PERIOD_END_DT)) <= COMP_DATE.CALENDAR_DT as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-3733
    , MAX(nvl(SLS.OPEN_DATE, COMP_DATE.MAX_HONEY_DT)) <= MAX(COMP_DATE.MAX_HONEY_DT) as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , NULL as WEEKDAY_OFFSET --ODI-2977
    , NULL as WEEK_TRANS_CNTS --ODI-2977
    , NULL as WEEK_NET_SALES --ODI-2977
    , DT.FISCAL_PERIOD_NBR
    , DT.FISCAL_YEAR_START_DT
    , max(DT.FISCAL_PERIOD_END_DT) as END_DT
    , (least(nvl(max(REOPEN_DATE -1),DT.FISCAL_PERIOD_END_DT), DT.FISCAL_PERIOD_END_DT, COMP_DATE.CALENDAR_DT)
       - greatest(nvl(max(TEMP_CLOSED_DATE),DT.FISCAL_PERIOD_START_DT), DT.FISCAL_PERIOD_START_DT) >= 6 
        and max(TEMP_CLOSED_DATE) is not null) AS TEMP_CLOSED_FLAG
FROM 
    IDS_DEV.DATASTORE.DAILY_FLASH_SALES_STG SLS
INNER JOIN 
    COMP_DATE
ON SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN 
    IDS_DEV.INT_REF.COMP_DATES DT
ON COMP_DATE.CALENDAR_DT = DT.CALENDAR_DT
AND DT.BUSINESS_DT = BUSINESS_DATE
AND DT.TIME_INTERVAL = TIME_INTERVAL
WHERE SLS.SESSION_NO = CURRENT_SESSION()
AND SLS.TIME_INTERVAL = TIME_INTERVAL
AND SLS.BUSINESS_DT >= DT.FISCAL_PERIOD_START_DT
AND SLS.BUSINESS_DT <= 
                        iff(TIME_INTERVAL <> ''CY''
                            , least(COMP_DATE.CALENDAR_DT, DT.FISCAL_PERIOD_END_DT)
                            , COMP_DATE.CALENDAR_DT
                        )
GROUP BY    
      SLS.BRAND_ID
    , STORE_ID
    , COMP_DATE.CALENDAR_DT
    , ''PTD'' 
    , DMA_NAME 
    , DMA_CODE
    , STATE
    , COUNTRY
    , DT.FISCAL_PERIOD_START_DT
    , DT.FISCAL_PERIOD_END_DT
    , DT.FISCAL_WEEK_NBR
    , DT.FISCAL_PERIOD_NBR
    , DT.FISCAL_YEAR_START_DT

    ';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_PTD("BUSINESS_DATE" DATE, "TIME_INTERVAL" VARCHAR(16777216), "REPORT_BRAND" VARCHAR(16777216), "THRESHOLD_FLAG" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "CALENDAR_DT" DATE, "TRANS_CNT" NUMBER(38,0), "NET_SALES" NUMBER(38,2), "COMP_TRANS" NUMBER(38,0), "COMP_SALES" NUMBER(38,2), "AGG_START_DT" DATE, "AGG_LEVEL" VARCHAR(16777216), "DMA_NAME" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "OPEN_15P_FLAG" BOOLEAN, "CLOSED_BEFORE_PERIOD_END_FLAG" BOOLEAN, "OPEN_AFTER_HONEYMOON_FLAG" BOOLEAN, "WEEKDAY_OFFSET" ARRAY, "WEEK_TRANS_CNTS" ARRAY, "WEEK_NET_SALES" ARRAY, "FISCAL_PERIOD_NBR" NUMBER(38,0), "FISCAL_YEAR_START_DT" DATE, "END_DT" DATE, "TEMP_CLOSED_FLAG" BOOLEAN)
LANGUAGE SQL
AS '

WITH COMP_DATE AS 
(
    SELECT  
       s.calendar_dt -- comparison date
    ,  MAX_OPEN_DT -- ODI-53 maximum open date for which the store will be comp when reporting at BUSINESS_DATE
    ,  MAX_HONEY_DT -- ODI-199 maximum open date for which the store will be out of honeymoon period (3 full fiscal periods) at BUSINESS_DATE
FROM TABLE(FLASH_SUMMARY_COMP_HONEYMOON(BUSINESS_DATE,TIME_INTERVAL)) as s

)

SELECT  --ODI-2123
      SLS.BRAND_ID
    , STORE_ID
    , COMP_DATE.CALENDAR_DT 
    , SUM(SLS.Trans_Cnt) as Trans_Cnt
    , SUM(SLS.Net_Sales) as Net_Sales
    , SUM(CASE WHEN SLS.FISCAL_WEEK_NBR = 53 
      THEN 0 ELSE SLS.Trans_Cnt END) as Comp_Trans
    , SUM(CASE WHEN SLS.FISCAL_WEEK_NBR = 53 
      THEN 0 ELSE SLS.Net_Sales END) as Comp_Sales
    , DT.FISCAL_PERIOD_START_DT AGG_START_DT
    , ''PTD'' AS Agg_Level
    , DMA_NAME 
    , DMA_CODE
    , STATE
    , COUNTRY
    , MAX(nvl(OPEN_DATE, MAX_OPEN_DT)) <= MAX(MAX_OPEN_DT) as OPEN_15P_FLAG -- ODI-53
    , MAX(NVL(SLS.CLOSURE_DATE, DT.FISCAL_PERIOD_END_DT)) < MAX(DT.FISCAL_PERIOD_END_DT) --ODI-55
        and MAX(NVL(SLS.CLOSURE_DATE, DT.FISCAL_PERIOD_END_DT)) <= COMP_DATE.CALENDAR_DT as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-3733
    , MAX(nvl(SLS.OPEN_DATE, COMP_DATE.MAX_HONEY_DT)) <= MAX(COMP_DATE.MAX_HONEY_DT) as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , NULL as WEEKDAY_OFFSET --ODI-2977
    , NULL as WEEK_TRANS_CNTS --ODI-2977
    , NULL as WEEK_NET_SALES --ODI-2977
    , DT.FISCAL_PERIOD_NBR
    , DT.FISCAL_YEAR_START_DT
    , max(DT.FISCAL_PERIOD_END_DT) as END_DT
    , (least(nvl(max(REOPEN_DATE -1),DT.FISCAL_PERIOD_END_DT), DT.FISCAL_PERIOD_END_DT, COMP_DATE.CALENDAR_DT)
       - greatest(nvl(max(TEMP_CLOSED_DATE),DT.FISCAL_PERIOD_START_DT), DT.FISCAL_PERIOD_START_DT) >= 6 
        and max(TEMP_CLOSED_DATE) is not null) AS TEMP_CLOSED_FLAG
FROM 
    table(DAILY_FLASH_SALES_V(BUSINESS_DATE,TIME_INTERVAL, REPORT_BRAND, THRESHOLD_FLAG)) SLS
INNER JOIN 
    COMP_DATE
ON SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN 
    IDS_DEV.INT_REF.COMP_DATES DT
ON COMP_DATE.CALENDAR_DT = DT.CALENDAR_DT
AND DT.BUSINESS_DT = BUSINESS_DATE
AND DT.TIME_INTERVAL = TIME_INTERVAL
WHERE SLS.BUSINESS_DT >= DT.FISCAL_PERIOD_START_DT
AND SLS.BUSINESS_DT <= 
                        iff(TIME_INTERVAL <> ''CY''
                            , least(COMP_DATE.CALENDAR_DT, DT.FISCAL_PERIOD_END_DT)
                            , COMP_DATE.CALENDAR_DT
                        )
GROUP BY    
      SLS.BRAND_ID
    , STORE_ID
    , COMP_DATE.CALENDAR_DT
    , ''PTD'' 
    , DMA_NAME 
    , DMA_CODE
    , STATE
    , COUNTRY
    , DT.FISCAL_PERIOD_START_DT
    , DT.FISCAL_PERIOD_END_DT
    , DT.FISCAL_WEEK_NBR
    , DT.FISCAL_PERIOD_NBR
    , DT.FISCAL_YEAR_START_DT

    ';
