CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_TIME_INTERVAL("BUSINESS_DATE" DATE, "TIME_INTERVAL" VARCHAR(16777216))
RETURNS TABLE ("BUSINESS_DT" DATE, "FISCAL_YEAR_START_DT" DATE, "FISCAL_QUARTER_START_DT" DATE, "FISCAL_PERIOD_START_DT" DATE, "FISCAL_WEEK_START_DT" DATE)
LANGUAGE SQL
AS '
SELECT 
CASE 
WHEN TIME_INTERVAL = ''CY''
THEN CALENDAR_DT
WHEN TIME_INTERVAL = ''FISC1Y''
THEN FISCAL_1YR_COMP_DT
WHEN TIME_INTERVAL = ''CAL1Y''
THEN CALENDAR_1YR_COMP_DT
WHEN TIME_INTERVAL = ''CAL2Y''
THEN CALENDAR_2YR_COMP_DT
WHEN TIME_INTERVAL = ''CAL3Y''
THEN CALENDAR_3YR_COMP_DT
END AS BUSINESS_DT,
CASE 
WHEN TIME_INTERVAL = ''CY''
THEN FISCAL_YEAR_START_DT
WHEN TIME_INTERVAL = ''FISC1Y''
THEN FISCAL_1YR_COMP_YEAR_DT
WHEN TIME_INTERVAL = ''CAL1Y''
THEN CALENDAR_1YR_COMP_YEAR_DT
WHEN TIME_INTERVAL = ''CAL2Y''
THEN CALENDAR_2YR_COMP_YEAR_DT
WHEN TIME_INTERVAL = ''CAL3Y''
THEN CALENDAR_3YR_COMP_YEAR_DT
END AS FISCAL_YEAR_START_DT,
CASE 
WHEN TIME_INTERVAL = ''CY''
THEN FISCAL_QUARTER_START_DT
WHEN TIME_INTERVAL = ''FISC1Y''
THEN FISCAL_1YR_COMP_QUARTER_DT
WHEN TIME_INTERVAL = ''CAL1Y''
THEN CALENDAR_1YR_COMP_QUARTER_DT
WHEN TIME_INTERVAL = ''CAL2Y''
THEN CALENDAR_2YR_COMP_QUARTER_DT
WHEN TIME_INTERVAL = ''CAL3Y''
THEN CALENDAR_3YR_COMP_QUARTER_DT
END AS FISCAL_QUARTER_START_DT,
CASE 
WHEN TIME_INTERVAL = ''CY''
THEN FISCAL_PERIOD_START_DT
WHEN TIME_INTERVAL = ''FISC1Y''
THEN FISCAL_1YR_COMP_PERIOD_DT
WHEN TIME_INTERVAL = ''CAL1Y''
THEN CALENDAR_1YR_COMP_PERIOD_DT
WHEN TIME_INTERVAL = ''CAL2Y''
THEN CALENDAR_2YR_COMP_PERIOD_DT
WHEN TIME_INTERVAL = ''CAL3Y''
THEN CALENDAR_3YR_COMP_PERIOD_DT
END AS FISCAL_PERIOD_START_DT,
CASE 
WHEN TIME_INTERVAL = ''CY''
THEN FISCAL_WEEK_START_DT
WHEN TIME_INTERVAL = ''FISC1Y''
THEN FISCAL_1YR_COMP_WEEK_DT
WHEN TIME_INTERVAL = ''CAL1Y''
THEN CALENDAR_1YR_COMP_WEEK_DT
WHEN TIME_INTERVAL = ''CAL2Y''
THEN CALENDAR_2YR_COMP_WEEK_DT
WHEN TIME_INTERVAL = ''CAL3Y''
THEN CALENDAR_3YR_COMP_WEEK_DT
END AS FISCAL_WEEK_START_DT
FROM IDS_DEV.INT_REF.COMP_CALENDAR
WHERE CALENDAR_DT =  BUSINESS_DATE

';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_WEEKS_IN_PERIODS("BUSINESS_DATE" DATE)
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "FISCAL_PERIOD_START_DT" DATE, "FISCAL_1YR_COMP_PERIOD_DT" DATE, "CALENDAR_1YR_COMP_PERIOD_DT" DATE, "CALENDAR_2YR_COMP_PERIOD_DT" DATE, "CALENDAR_3YR_COMP_PERIOD_DT" DATE, "FISC_1Y_SALES" NUMBER(38,2), "FISC_1Y_TRANS" NUMBER(38,0), "CAL_1Y_SALES" NUMBER(38,2), "CAL_1Y_TRANS" NUMBER(38,0), "CAL_2Y_SALES" NUMBER(38,2), "CAL_2Y_TRANS" NUMBER(38,0), "CAL_3Y_SALES" NUMBER(38,2), "CAL_3Y_TRANS" NUMBER(38,0))
LANGUAGE SQL
AS '

WITH CY_DT AS (
select CALENDAR_DT, 
FISCAL_PERIOD_START_DT,
FISCAL_WEEK_START_DT,
FISCAL_1YR_COMP_WEEK_DT,   
CALENDAR_1YR_COMP_WEEK_DT,
CALENDAR_2YR_COMP_WEEK_DT,
CALENDAR_3YR_COMP_WEEK_DT 
from IDS_DEV.INT_REF.COMP_CALENDAR 
where CALENDAR_DT = BUSINESS_DATE
),
DT AS (
SELECT DISTINCT
DT.FISCAL_PERIOD_START_DT,
DT.FISCAL_WEEK_START_DT,
DT.FISCAL_1YR_COMP_PERIOD_DT, 
DT.FISCAL_1YR_COMP_WEEK_DT,
DT.CALENDAR_1YR_COMP_PERIOD_DT,
DT.CALENDAR_1YR_COMP_WEEK_DT,
DT.CALENDAR_2YR_COMP_PERIOD_DT,
DT.CALENDAR_2YR_COMP_WEEK_DT,
DT.CALENDAR_3YR_COMP_PERIOD_DT,
DT.CALENDAR_3YR_COMP_WEEK_DT
FROM
IDS_DEV.INT_REF.COMP_CALENDAR DT
INNER JOIN CY_DT
ON DT.FISCAL_PERIOD_START_DT = CY_DT.FISCAL_PERIOD_START_DT
AND DT.FISCAL_WEEK_START_DT <= CY_DT.FISCAL_WEEK_START_DT
AND DT.FISCAL_1YR_COMP_WEEK_DT <= CY_DT.FISCAL_1YR_COMP_WEEK_DT
AND DT.CALENDAR_1YR_COMP_WEEK_DT <= CY_DT.CALENDAR_1YR_COMP_WEEK_DT
AND DT.CALENDAR_2YR_COMP_WEEK_DT <= CY_DT.CALENDAR_2YR_COMP_WEEK_DT
AND DT.CALENDAR_3YR_COMP_WEEK_DT <= CY_DT.CALENDAR_3YR_COMP_WEEK_DT
)

    SELECT 
    CR.BRAND_ID,
    CR.STORE_ID,
    DT.FISCAL_PERIOD_START_DT,
    DT.FISCAL_1YR_COMP_PERIOD_DT,
    DT.CALENDAR_1YR_COMP_PERIOD_DT,
    DT.CALENDAR_2YR_COMP_PERIOD_DT,
    DT.CALENDAR_3YR_COMP_PERIOD_DT,
    SUM(NVL(CASE WHEN CR.NET_SALES IS NOT NULL AND CR.comp_sales = 0 THEN FISC_1Y.COMP_SALES 
         ELSE DW.FISC_1Y_SALES END,0)) AS FISC_1Y_SALES,
    SUM(NVL(CASE WHEN CR.NET_SALES IS NOT NULL AND CR.comp_sales = 0 THEN FISC_1Y.COMP_TRANS
         ELSE DW.FISC_1Y_TRANS END,0)) AS FISC_1Y_TRANS,
    SUM(NVL(CASE WHEN CR.NET_SALES IS NOT NULL AND CR.comp_sales = 0 THEN CAL_1Y.COMP_SALES 
         ELSE DW.CAL_1Y_SALES END,0)) AS CAL_1Y_SALES,
    SUM(NVL(CASE WHEN CR.NET_SALES IS NOT NULL AND CR.comp_sales = 0 THEN CAL_1Y.COMP_TRANS
         ELSE DW.CAL_1Y_TRANS END,0)) AS CAL_1Y_TRANS,
    SUM(NVL(CASE WHEN CR.NET_SALES IS NOT NULL AND CR.comp_sales = 0 THEN CAL_2Y.COMP_SALES 
         ELSE DW.CAL_2Y_SALES END,0)) AS CAL_2Y_SALES,
    SUM(NVL(CASE WHEN CR.NET_SALES IS NOT NULL AND CR.comp_sales = 0 THEN CAL_2Y.COMP_TRANS
         ELSE DW.CAL_2Y_TRANS END,0)) AS CAL_2Y_TRANS,   
    SUM(NVL(CASE WHEN CR.NET_SALES IS NOT NULL AND CR.comp_sales = 0 THEN CAL_3Y.COMP_SALES 
         ELSE DW.CAL_3Y_SALES END,0)) AS CAL_3Y_SALES,
    SUM(NVL(CASE WHEN CR.NET_SALES IS NOT NULL AND CR.comp_sales = 0 THEN CAL_3Y.COMP_TRANS
         ELSE DW.CAL_3Y_TRANS END,0)) AS CAL_3Y_TRANS
    FROM  DT
    INNER JOIN table(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''CY'')) CR
    ON DT.FISCAL_WEEK_START_DT = CR.AGG_START_DT
    AND CR.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN TABLE(FLASH_SUMMARY_COMP_WEEKS_TRESHOLD(BUSINESS_DATE)) DW
    ON CR.STORE_ID = DW.STORE_ID 
    AND CR.BRAND_ID = DW.BRAND_ID
    AND DT.FISCAL_WEEK_START_DT = DW.FISCAL_WEEK_START_DT
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''FISC1Y''))  FISC_1Y                                   
    ON CR.STORE_ID = FISC_1Y.STORE_ID 
    AND CR.BRAND_ID = FISC_1Y.BRAND_ID
    AND DT.FISCAL_1YR_COMP_WEEK_DT = FISC_1Y.AGG_START_DT
    AND DT.FISCAL_1YR_COMP_PERIOD_DT = FISC_1Y.FISCAL_PERIOD_START_DT
    AND FISC_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''CAL1Y''))  CAL_1Y
     ON CR.STORE_ID = CAL_1Y.STORE_ID 
     AND CR.BRAND_ID = CAL_1Y.BRAND_ID
     AND DT.CALENDAR_1YR_COMP_WEEK_DT = CAL_1Y.AGG_START_DT
     AND DT.CALENDAR_1YR_COMP_PERIOD_DT = CAL_1Y.FISCAL_PERIOD_START_DT
     AND CAL_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''CAL2Y''))  CAL_2Y
     ON CR.STORE_ID = CAL_2Y.STORE_ID 
     AND CR.BRAND_ID = CAL_2Y.BRAND_ID
     AND DT.CALENDAR_2YR_COMP_WEEK_DT = CAL_2Y.AGG_START_DT
     AND DT.CALENDAR_2YR_COMP_PERIOD_DT = CAL_2Y.FISCAL_PERIOD_START_DT
     AND CAL_2Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''CAL3Y''))  CAL_3Y
     ON CR.STORE_ID = CAL_3Y.STORE_ID 
     AND CR.BRAND_ID = CAL_3Y.BRAND_ID
     AND DT.CALENDAR_3YR_COMP_WEEK_DT = CAL_3Y.AGG_START_DT
     AND DT.CALENDAR_3YR_COMP_PERIOD_DT = CAL_3Y.FISCAL_PERIOD_START_DT
     AND CAL_3Y.FISCAL_WEEK_NBR !=53
     WHERE 
     (CR.NET_SALES IS NOT NULL
     AND CR.comp_sales = 0)
     OR DW.STORE_ID IS NOT NULL
GROUP BY 
CR.BRAND_ID,
CR.STORE_ID,
DT.FISCAL_PERIOD_START_DT,
DT.FISCAL_1YR_COMP_PERIOD_DT,
DT.CALENDAR_1YR_COMP_PERIOD_DT,
DT.CALENDAR_2YR_COMP_PERIOD_DT,
DT.CALENDAR_3YR_COMP_PERIOD_DT
';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_WEEKS_IN_PERIODS("BUSINESS_DATE" DATE, "REPORT_BRAND" VARCHAR(16777216), "THRESHOLD_FLAG" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "FISCAL_PERIOD_START_DT" DATE, "FISCAL_1YR_COMP_PERIOD_DT" DATE, "CALENDAR_1YR_COMP_PERIOD_DT" DATE, "CALENDAR_2YR_COMP_PERIOD_DT" DATE, "CALENDAR_3YR_COMP_PERIOD_DT" DATE, "FISC_1Y_SALES" NUMBER(38,2), "FISC_1Y_TRANS" NUMBER(38,0), "CAL_1Y_SALES" NUMBER(38,2), "CAL_1Y_TRANS" NUMBER(38,0), "CAL_2Y_SALES" NUMBER(38,2), "CAL_2Y_TRANS" NUMBER(38,0), "CAL_3Y_SALES" NUMBER(38,2), "CAL_3Y_TRANS" NUMBER(38,0))
LANGUAGE SQL
AS '

WITH CY_DT AS (
select CALENDAR_DT, 
FISCAL_PERIOD_START_DT,
FISCAL_WEEK_START_DT,
FISCAL_1YR_COMP_WEEK_DT,   
CALENDAR_1YR_COMP_WEEK_DT,
CALENDAR_2YR_COMP_WEEK_DT,
CALENDAR_3YR_COMP_WEEK_DT 
from IDS_DEV.INT_REF.COMP_CALENDAR 
where CALENDAR_DT = BUSINESS_DATE
),
LY_DT AS (
SELECT DISTINCT
DT.FISCAL_PERIOD_START_DT,
DT.FISCAL_WEEK_START_DT,
DT.FISCAL_1YR_COMP_PERIOD_DT, 
DT.FISCAL_1YR_COMP_WEEK_DT,
DT.CALENDAR_1YR_COMP_PERIOD_DT,
DT.CALENDAR_1YR_COMP_WEEK_DT,
DT.CALENDAR_2YR_COMP_PERIOD_DT,
DT.CALENDAR_2YR_COMP_WEEK_DT,
DT.CALENDAR_3YR_COMP_PERIOD_DT,
DT.CALENDAR_3YR_COMP_WEEK_DT
FROM
IDS_DEV.INT_REF.COMP_CALENDAR DT
INNER JOIN CY_DT
ON DT.FISCAL_PERIOD_START_DT = CY_DT.FISCAL_PERIOD_START_DT
AND DT.FISCAL_WEEK_START_DT <= CY_DT.FISCAL_WEEK_START_DT
AND DT.FISCAL_1YR_COMP_WEEK_DT <= CY_DT.FISCAL_1YR_COMP_WEEK_DT
AND DT.CALENDAR_1YR_COMP_WEEK_DT <= CY_DT.CALENDAR_1YR_COMP_WEEK_DT
AND DT.CALENDAR_2YR_COMP_WEEK_DT <= CY_DT.CALENDAR_2YR_COMP_WEEK_DT
AND DT.CALENDAR_3YR_COMP_WEEK_DT <= CY_DT.CALENDAR_3YR_COMP_WEEK_DT
),
DT AS (
SELECT 
FISCAL_PERIOD_START_DT,
FISCAL_WEEK_START_DT,
FISCAL_1YR_COMP_PERIOD_DT, 
FISCAL_1YR_COMP_WEEK_DT,
CALENDAR_1YR_COMP_PERIOD_DT,
CALENDAR_1YR_COMP_WEEK_DT,
CALENDAR_2YR_COMP_PERIOD_DT,
CALENDAR_2YR_COMP_WEEK_DT,
CALENDAR_3YR_COMP_PERIOD_DT,
CALENDAR_3YR_COMP_WEEK_DT,
ROW_NUMBER() OVER (PARTITION BY FISCAL_1YR_COMP_WEEK_DT
                   ORDER BY FISCAL_WEEK_START_DT, FISCAL_1YR_COMP_WEEK_DT ,CALENDAR_1YR_COMP_WEEK_DT ,CALENDAR_2YR_COMP_WEEK_DT ,CALENDAR_3YR_COMP_WEEK_DT) AS ROW_NUM             
from LY_DT
QUALIFY ROW_NUM = 1)

    SELECT 
    CR.BRAND_ID,
    CR.STORE_ID,
    DT.FISCAL_PERIOD_START_DT,
    DT.FISCAL_1YR_COMP_PERIOD_DT,
    DT.CALENDAR_1YR_COMP_PERIOD_DT,
    DT.CALENDAR_2YR_COMP_PERIOD_DT,
    DT.CALENDAR_3YR_COMP_PERIOD_DT,
    SUM(NVL(FISC_1Y.COMP_SALES,0)) AS FISC_1Y_SALES,
    SUM(NVL(FISC_1Y.COMP_TRANS,0)) AS FISC_1Y_TRANS,
    SUM(NVL(CAL_1Y.COMP_SALES,0)) AS CAL_1Y_SALES,
    SUM(NVL(CAL_1Y.COMP_TRANS,0)) AS CAL_1Y_TRANS,
    SUM(NVL(CAL_2Y.COMP_SALES,0)) AS CAL_2Y_SALES,
    SUM(NVL(CAL_2Y.COMP_TRANS,0)) AS CAL_2Y_TRANS,
    SUM(NVL(CAL_3Y.COMP_SALES,0)) AS CAL_3Y_SALES,
    SUM(NVL(CAL_3Y.COMP_TRANS,0)) AS CAL_3Y_TRANS 
    FROM  table(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''CY'', REPORT_BRAND, THRESHOLD_FLAG)) CR
    INNER JOIN DT
    ON DT.FISCAL_WEEK_START_DT = CR.AGG_START_DT
    AND CR.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''FISC1Y'', REPORT_BRAND, THRESHOLD_FLAG))  FISC_1Y                                   
    ON CR.STORE_ID = FISC_1Y.STORE_ID 
    AND CR.BRAND_ID = FISC_1Y.BRAND_ID
    AND DT.FISCAL_1YR_COMP_WEEK_DT = FISC_1Y.AGG_START_DT
    AND DT.FISCAL_1YR_COMP_PERIOD_DT = FISC_1Y.FISCAL_PERIOD_START_DT
    AND FISC_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''CAL1Y'', REPORT_BRAND, THRESHOLD_FLAG))  CAL_1Y
     ON CR.STORE_ID = CAL_1Y.STORE_ID 
     AND CR.BRAND_ID = CAL_1Y.BRAND_ID
     AND DT.CALENDAR_1YR_COMP_WEEK_DT = CAL_1Y.AGG_START_DT
     AND DT.CALENDAR_1YR_COMP_PERIOD_DT = CAL_1Y.FISCAL_PERIOD_START_DT
     AND CAL_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''CAL2Y'', REPORT_BRAND, THRESHOLD_FLAG))  CAL_2Y
     ON CR.STORE_ID = CAL_2Y.STORE_ID 
     AND CR.BRAND_ID = CAL_2Y.BRAND_ID
     AND DT.CALENDAR_2YR_COMP_WEEK_DT = CAL_2Y.AGG_START_DT
     AND DT.CALENDAR_2YR_COMP_PERIOD_DT = CAL_2Y.FISCAL_PERIOD_START_DT
     AND CAL_2Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''CAL3Y'', REPORT_BRAND, THRESHOLD_FLAG))  CAL_3Y
     ON CR.STORE_ID = CAL_3Y.STORE_ID 
     AND CR.BRAND_ID = CAL_3Y.BRAND_ID
     AND DT.CALENDAR_3YR_COMP_WEEK_DT = CAL_3Y.AGG_START_DT
     AND DT.CALENDAR_3YR_COMP_PERIOD_DT = CAL_3Y.FISCAL_PERIOD_START_DT
     AND CAL_3Y.FISCAL_WEEK_NBR !=53
WHERE CR.NET_SALES IS NOT NULL
AND CR.comp_sales = 0
GROUP BY 
CR.BRAND_ID,
CR.STORE_ID,
DT.FISCAL_PERIOD_START_DT,
DT.FISCAL_1YR_COMP_PERIOD_DT,
DT.CALENDAR_1YR_COMP_PERIOD_DT,
DT.CALENDAR_2YR_COMP_PERIOD_DT,
DT.CALENDAR_3YR_COMP_PERIOD_DT
';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_WEEKS_IN_PERIODS_F("BUSINESS_DATE" DATE)
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "FISCAL_PERIOD_START_DT" DATE, "FISCAL_1YR_COMP_PERIOD_DT" DATE, "CALENDAR_1YR_COMP_PERIOD_DT" DATE, "CALENDAR_2YR_COMP_PERIOD_DT" DATE, "CALENDAR_3YR_COMP_PERIOD_DT" DATE, "FISC_1Y_SALES" NUMBER(38,2), "FISC_1Y_TRANS" NUMBER(38,0), "CAL_1Y_SALES" NUMBER(38,2), "CAL_1Y_TRANS" NUMBER(38,0), "CAL_2Y_SALES" NUMBER(38,2), "CAL_2Y_TRANS" NUMBER(38,0), "CAL_3Y_SALES" NUMBER(38,2), "CAL_3Y_TRANS" NUMBER(38,0))
LANGUAGE SQL
AS '

WITH CY_DT AS (
select CALENDAR_DT, 
FISCAL_PERIOD_START_DT,
FISCAL_WEEK_START_DT,
FISCAL_1YR_COMP_WEEK_DT,   
CALENDAR_1YR_COMP_WEEK_DT,
CALENDAR_2YR_COMP_WEEK_DT,
CALENDAR_3YR_COMP_WEEK_DT 
from IDS_DEV.INT_REF.COMP_CALENDAR 
where CALENDAR_DT = BUSINESS_DATE
),
LY_DT AS (
SELECT DISTINCT
DT.FISCAL_PERIOD_START_DT,
DT.FISCAL_WEEK_START_DT,
DT.FISCAL_1YR_COMP_PERIOD_DT, 
DT.FISCAL_1YR_COMP_WEEK_DT,
DT.CALENDAR_1YR_COMP_PERIOD_DT,
DT.CALENDAR_1YR_COMP_WEEK_DT,
DT.CALENDAR_2YR_COMP_PERIOD_DT,
DT.CALENDAR_2YR_COMP_WEEK_DT,
DT.CALENDAR_3YR_COMP_PERIOD_DT,
DT.CALENDAR_3YR_COMP_WEEK_DT
FROM
IDS_DEV.INT_REF.COMP_CALENDAR DT
INNER JOIN CY_DT
ON DT.FISCAL_PERIOD_START_DT = CY_DT.FISCAL_PERIOD_START_DT
AND DT.FISCAL_WEEK_START_DT <= CY_DT.FISCAL_WEEK_START_DT
AND DT.FISCAL_1YR_COMP_WEEK_DT <= CY_DT.FISCAL_1YR_COMP_WEEK_DT
AND DT.CALENDAR_1YR_COMP_WEEK_DT <= CY_DT.CALENDAR_1YR_COMP_WEEK_DT
AND DT.CALENDAR_2YR_COMP_WEEK_DT <= CY_DT.CALENDAR_2YR_COMP_WEEK_DT
AND DT.CALENDAR_3YR_COMP_WEEK_DT <= CY_DT.CALENDAR_3YR_COMP_WEEK_DT
),
DT AS (
SELECT 
FISCAL_PERIOD_START_DT,
FISCAL_WEEK_START_DT,
FISCAL_1YR_COMP_PERIOD_DT, 
FISCAL_1YR_COMP_WEEK_DT,
CALENDAR_1YR_COMP_PERIOD_DT,
CALENDAR_1YR_COMP_WEEK_DT,
CALENDAR_2YR_COMP_PERIOD_DT,
CALENDAR_2YR_COMP_WEEK_DT,
CALENDAR_3YR_COMP_PERIOD_DT,
CALENDAR_3YR_COMP_WEEK_DT,
ROW_NUMBER() OVER (PARTITION BY FISCAL_1YR_COMP_WEEK_DT
                   ORDER BY FISCAL_WEEK_START_DT, FISCAL_1YR_COMP_WEEK_DT ,CALENDAR_1YR_COMP_WEEK_DT ,CALENDAR_2YR_COMP_WEEK_DT ,CALENDAR_3YR_COMP_WEEK_DT) AS ROW_NUM             
from LY_DT
QUALIFY ROW_NUM = 1)

    SELECT 
    CR.BRAND_ID,
    CR.STORE_ID,
    DT.FISCAL_PERIOD_START_DT,
    DT.FISCAL_1YR_COMP_PERIOD_DT,
    DT.CALENDAR_1YR_COMP_PERIOD_DT,
    DT.CALENDAR_2YR_COMP_PERIOD_DT,
    DT.CALENDAR_3YR_COMP_PERIOD_DT,
    SUM(NVL(FISC_1Y.COMP_SALES,0)) AS FISC_1Y_SALES,
    SUM(NVL(FISC_1Y.COMP_TRANS,0)) AS FISC_1Y_TRANS,
    SUM(NVL(CAL_1Y.COMP_SALES,0)) AS CAL_1Y_SALES,
    SUM(NVL(CAL_1Y.COMP_TRANS,0)) AS CAL_1Y_TRANS,
    SUM(NVL(CAL_2Y.COMP_SALES,0)) AS CAL_2Y_SALES,
    SUM(NVL(CAL_2Y.COMP_TRANS,0)) AS CAL_2Y_TRANS,
    SUM(NVL(CAL_3Y.COMP_SALES,0)) AS CAL_3Y_SALES,
    SUM(NVL(CAL_3Y.COMP_TRANS,0)) AS CAL_3Y_TRANS 
    FROM  table(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''CY'')) CR
    INNER JOIN DT
    ON DT.FISCAL_WEEK_START_DT = CR.AGG_START_DT
    AND CR.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''FISC1Y''))  FISC_1Y                                   
    ON CR.STORE_ID = FISC_1Y.STORE_ID 
    AND CR.BRAND_ID = FISC_1Y.BRAND_ID
    AND DT.FISCAL_1YR_COMP_WEEK_DT = FISC_1Y.AGG_START_DT
    AND DT.FISCAL_1YR_COMP_PERIOD_DT = FISC_1Y.FISCAL_PERIOD_START_DT
    AND FISC_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''CAL1Y''))  CAL_1Y
     ON CR.STORE_ID = CAL_1Y.STORE_ID 
     AND CR.BRAND_ID = CAL_1Y.BRAND_ID
     AND DT.CALENDAR_1YR_COMP_WEEK_DT = CAL_1Y.AGG_START_DT
     AND DT.CALENDAR_1YR_COMP_PERIOD_DT = CAL_1Y.FISCAL_PERIOD_START_DT
     AND CAL_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''CAL2Y''))  CAL_2Y
     ON CR.STORE_ID = CAL_2Y.STORE_ID 
     AND CR.BRAND_ID = CAL_2Y.BRAND_ID
     AND DT.CALENDAR_2YR_COMP_WEEK_DT = CAL_2Y.AGG_START_DT
     AND DT.CALENDAR_2YR_COMP_PERIOD_DT = CAL_2Y.FISCAL_PERIOD_START_DT
     AND CAL_2Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''CAL3Y''))  CAL_3Y
     ON CR.STORE_ID = CAL_3Y.STORE_ID 
     AND CR.BRAND_ID = CAL_3Y.BRAND_ID
     AND DT.CALENDAR_3YR_COMP_WEEK_DT = CAL_3Y.AGG_START_DT
     AND DT.CALENDAR_3YR_COMP_PERIOD_DT = CAL_3Y.FISCAL_PERIOD_START_DT
     AND CAL_3Y.FISCAL_WEEK_NBR !=53
WHERE CR.NET_SALES IS NOT NULL
AND CR.comp_sales = 0
GROUP BY 
CR.BRAND_ID,
CR.STORE_ID,
DT.FISCAL_PERIOD_START_DT,
DT.FISCAL_1YR_COMP_PERIOD_DT,
DT.CALENDAR_1YR_COMP_PERIOD_DT,
DT.CALENDAR_2YR_COMP_PERIOD_DT,
DT.CALENDAR_3YR_COMP_PERIOD_DT
';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_WEEKS_IN_PERIODS_F("BUSINESS_DATE" DATE, "BRAND" VARCHAR(16777216), "THRESHOLD_FLG" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "FISCAL_PERIOD_START_DT" DATE, "FISCAL_1YR_COMP_PERIOD_DT" DATE, "CALENDAR_1YR_COMP_PERIOD_DT" DATE, "CALENDAR_2YR_COMP_PERIOD_DT" DATE, "CALENDAR_3YR_COMP_PERIOD_DT" DATE, "FISC_1Y_SALES" NUMBER(38,2), "FISC_1Y_TRANS" NUMBER(38,0), "CAL_1Y_SALES" NUMBER(38,2), "CAL_1Y_TRANS" NUMBER(38,0), "CAL_2Y_SALES" NUMBER(38,2), "CAL_2Y_TRANS" NUMBER(38,0), "CAL_3Y_SALES" NUMBER(38,2), "CAL_3Y_TRANS" NUMBER(38,0))
LANGUAGE SQL
AS '

WITH CY_DT AS (
select CALENDAR_DT, 
FISCAL_PERIOD_START_DT,
FISCAL_WEEK_START_DT,
FISCAL_1YR_COMP_WEEK_DT,   
CALENDAR_1YR_COMP_WEEK_DT,
CALENDAR_2YR_COMP_WEEK_DT,
CALENDAR_3YR_COMP_WEEK_DT 
from IDS_DEV.INT_REF.COMP_CALENDAR 
where CALENDAR_DT = BUSINESS_DATE
),
DT AS (
SELECT DISTINCT
DT.FISCAL_PERIOD_START_DT,
DT.FISCAL_WEEK_START_DT,
DT.FISCAL_1YR_COMP_PERIOD_DT, 
DT.FISCAL_1YR_COMP_WEEK_DT,
DT.CALENDAR_1YR_COMP_PERIOD_DT,
DT.CALENDAR_1YR_COMP_WEEK_DT,
DT.CALENDAR_2YR_COMP_PERIOD_DT,
DT.CALENDAR_2YR_COMP_WEEK_DT,
DT.CALENDAR_3YR_COMP_PERIOD_DT,
DT.CALENDAR_3YR_COMP_WEEK_DT
FROM
IDS_DEV.INT_REF.COMP_CALENDAR DT
INNER JOIN CY_DT
ON DT.FISCAL_PERIOD_START_DT = CY_DT.FISCAL_PERIOD_START_DT
AND DT.FISCAL_WEEK_START_DT <= CY_DT.FISCAL_WEEK_START_DT
AND DT.FISCAL_1YR_COMP_WEEK_DT <= CY_DT.FISCAL_1YR_COMP_WEEK_DT
AND DT.CALENDAR_1YR_COMP_WEEK_DT <= CY_DT.CALENDAR_1YR_COMP_WEEK_DT
AND DT.CALENDAR_2YR_COMP_WEEK_DT <= CY_DT.CALENDAR_2YR_COMP_WEEK_DT
AND DT.CALENDAR_3YR_COMP_WEEK_DT <= CY_DT.CALENDAR_3YR_COMP_WEEK_DT
)

    SELECT 
    CR.BRAND_ID,
    CR.STORE_ID,
    DT.FISCAL_PERIOD_START_DT,
    DT.FISCAL_1YR_COMP_PERIOD_DT,
    DT.CALENDAR_1YR_COMP_PERIOD_DT,
    DT.CALENDAR_2YR_COMP_PERIOD_DT,
    DT.CALENDAR_3YR_COMP_PERIOD_DT,
    SUM(NVL(CASE WHEN CR.NET_SALES IS NOT NULL AND CR.comp_sales = 0 THEN FISC_1Y.COMP_SALES 
         ELSE DW.FISC_1Y_SALES END,0)) AS FISC_1Y_SALES,
    SUM(NVL(CASE WHEN CR.NET_SALES IS NOT NULL AND CR.comp_sales = 0 THEN FISC_1Y.COMP_TRANS
         ELSE DW.FISC_1Y_TRANS END,0)) AS FISC_1Y_TRANS,
    SUM(NVL(CASE WHEN CR.NET_SALES IS NOT NULL AND CR.comp_sales = 0 THEN CAL_1Y.COMP_SALES 
         ELSE DW.CAL_1Y_SALES END,0)) AS CAL_1Y_SALES,
    SUM(NVL(CASE WHEN CR.NET_SALES IS NOT NULL AND CR.comp_sales = 0 THEN CAL_1Y.COMP_TRANS
         ELSE DW.CAL_1Y_TRANS END,0)) AS CAL_1Y_TRANS,
    SUM(NVL(CASE WHEN CR.NET_SALES IS NOT NULL AND CR.comp_sales = 0 THEN CAL_2Y.COMP_SALES 
         ELSE DW.CAL_2Y_SALES END,0)) AS CAL_2Y_SALES,
    SUM(NVL(CASE WHEN CR.NET_SALES IS NOT NULL AND CR.comp_sales = 0 THEN CAL_2Y.COMP_TRANS
         ELSE DW.CAL_2Y_TRANS END,0)) AS CAL_2Y_TRANS,   
    SUM(NVL(CASE WHEN CR.NET_SALES IS NOT NULL AND CR.comp_sales = 0 THEN CAL_3Y.COMP_SALES 
         ELSE DW.CAL_3Y_SALES END,0)) AS CAL_3Y_SALES,
    SUM(NVL(CASE WHEN CR.NET_SALES IS NOT NULL AND CR.comp_sales = 0 THEN CAL_3Y.COMP_TRANS
         ELSE DW.CAL_3Y_TRANS END,0)) AS CAL_3Y_TRANS
    FROM  DT
    INNER JOIN table(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''CY'', BRAND, THRESHOLD_FLG)) CR
    ON DT.FISCAL_WEEK_START_DT = CR.AGG_START_DT
    AND CR.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN TABLE(FLASH_SUMMARY_COMP_WEEKS_TRESHOLD_F(BUSINESS_DATE, BRAND, THRESHOLD_FLG)) DW
    ON CR.STORE_ID = DW.STORE_ID 
    AND CR.BRAND_ID = DW.BRAND_ID
    AND DT.FISCAL_WEEK_START_DT = DW.FISCAL_WEEK_START_DT
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''FISC1Y'', BRAND, THRESHOLD_FLG))  FISC_1Y                                   
    ON CR.STORE_ID = FISC_1Y.STORE_ID 
    AND CR.BRAND_ID = FISC_1Y.BRAND_ID
    AND DT.FISCAL_1YR_COMP_WEEK_DT = FISC_1Y.AGG_START_DT
    AND DT.FISCAL_1YR_COMP_PERIOD_DT = FISC_1Y.FISCAL_PERIOD_START_DT
    AND FISC_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''CAL1Y'', BRAND, THRESHOLD_FLG))  CAL_1Y
     ON CR.STORE_ID = CAL_1Y.STORE_ID 
     AND CR.BRAND_ID = CAL_1Y.BRAND_ID
     AND DT.CALENDAR_1YR_COMP_WEEK_DT = CAL_1Y.AGG_START_DT
     AND DT.CALENDAR_1YR_COMP_PERIOD_DT = CAL_1Y.FISCAL_PERIOD_START_DT
     AND CAL_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''CAL2Y'', BRAND, THRESHOLD_FLG))  CAL_2Y
     ON CR.STORE_ID = CAL_2Y.STORE_ID 
     AND CR.BRAND_ID = CAL_2Y.BRAND_ID
     AND DT.CALENDAR_2YR_COMP_WEEK_DT = CAL_2Y.AGG_START_DT
     AND DT.CALENDAR_2YR_COMP_PERIOD_DT = CAL_2Y.FISCAL_PERIOD_START_DT
     AND CAL_2Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''CAL3Y'', BRAND, THRESHOLD_FLG))  CAL_3Y
     ON CR.STORE_ID = CAL_3Y.STORE_ID 
     AND CR.BRAND_ID = CAL_3Y.BRAND_ID
     AND DT.CALENDAR_3YR_COMP_WEEK_DT = CAL_3Y.AGG_START_DT
     AND DT.CALENDAR_3YR_COMP_PERIOD_DT = CAL_3Y.FISCAL_PERIOD_START_DT
     AND CAL_3Y.FISCAL_WEEK_NBR !=53
WHERE 
     (CR.NET_SALES IS NOT NULL
     AND CR.comp_sales = 0)
     OR DW.STORE_ID IS NOT NULL
GROUP BY 
CR.BRAND_ID,
CR.STORE_ID,
DT.FISCAL_PERIOD_START_DT,
DT.FISCAL_1YR_COMP_PERIOD_DT,
DT.CALENDAR_1YR_COMP_PERIOD_DT,
DT.CALENDAR_2YR_COMP_PERIOD_DT,
DT.CALENDAR_3YR_COMP_PERIOD_DT
';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_WEEKS_IN_PERIODS_WITHOUT_THRESHOLD("BUSINESS_DATE" DATE)
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "FISCAL_PERIOD_START_DT" DATE, "FISCAL_1YR_COMP_PERIOD_DT" DATE, "CALENDAR_1YR_COMP_PERIOD_DT" DATE, "CALENDAR_2YR_COMP_PERIOD_DT" DATE, "CALENDAR_3YR_COMP_PERIOD_DT" DATE, "FISC_1Y_SALES" NUMBER(38,2), "FISC_1Y_TRANS" NUMBER(38,0), "CAL_1Y_SALES" NUMBER(38,2), "CAL_1Y_TRANS" NUMBER(38,0), "CAL_2Y_SALES" NUMBER(38,2), "CAL_2Y_TRANS" NUMBER(38,0), "CAL_3Y_SALES" NUMBER(38,2), "CAL_3Y_TRANS" NUMBER(38,0))
LANGUAGE SQL
AS '

WITH CY_DT AS (
select CALENDAR_DT, 
FISCAL_PERIOD_START_DT,
FISCAL_WEEK_START_DT,
FISCAL_1YR_COMP_WEEK_DT,   
CALENDAR_1YR_COMP_WEEK_DT,
CALENDAR_2YR_COMP_WEEK_DT,
CALENDAR_3YR_COMP_WEEK_DT 
from IDS_DEV.INT_REF.COMP_CALENDAR 
where CALENDAR_DT = BUSINESS_DATE
),
LY_DT AS (
SELECT DISTINCT
DT.FISCAL_PERIOD_START_DT,
DT.FISCAL_WEEK_START_DT,
DT.FISCAL_1YR_COMP_PERIOD_DT, 
DT.FISCAL_1YR_COMP_WEEK_DT,
DT.CALENDAR_1YR_COMP_PERIOD_DT,
DT.CALENDAR_1YR_COMP_WEEK_DT,
DT.CALENDAR_2YR_COMP_PERIOD_DT,
DT.CALENDAR_2YR_COMP_WEEK_DT,
DT.CALENDAR_3YR_COMP_PERIOD_DT,
DT.CALENDAR_3YR_COMP_WEEK_DT
FROM
IDS_DEV.INT_REF.COMP_CALENDAR DT
INNER JOIN CY_DT
ON DT.FISCAL_PERIOD_START_DT = CY_DT.FISCAL_PERIOD_START_DT
AND DT.FISCAL_WEEK_START_DT <= CY_DT.FISCAL_WEEK_START_DT
AND DT.FISCAL_1YR_COMP_WEEK_DT <= CY_DT.FISCAL_1YR_COMP_WEEK_DT
AND DT.CALENDAR_1YR_COMP_WEEK_DT <= CY_DT.CALENDAR_1YR_COMP_WEEK_DT
AND DT.CALENDAR_2YR_COMP_WEEK_DT <= CY_DT.CALENDAR_2YR_COMP_WEEK_DT
AND DT.CALENDAR_3YR_COMP_WEEK_DT <= CY_DT.CALENDAR_3YR_COMP_WEEK_DT
),
DT AS (
SELECT 
FISCAL_PERIOD_START_DT,
FISCAL_WEEK_START_DT,
FISCAL_1YR_COMP_PERIOD_DT, 
FISCAL_1YR_COMP_WEEK_DT,
CALENDAR_1YR_COMP_PERIOD_DT,
CALENDAR_1YR_COMP_WEEK_DT,
CALENDAR_2YR_COMP_PERIOD_DT,
CALENDAR_2YR_COMP_WEEK_DT,
CALENDAR_3YR_COMP_PERIOD_DT,
CALENDAR_3YR_COMP_WEEK_DT,
ROW_NUMBER() OVER (PARTITION BY FISCAL_1YR_COMP_WEEK_DT
                   ORDER BY FISCAL_WEEK_START_DT, FISCAL_1YR_COMP_WEEK_DT ,CALENDAR_1YR_COMP_WEEK_DT ,CALENDAR_2YR_COMP_WEEK_DT ,CALENDAR_3YR_COMP_WEEK_DT) AS ROW_NUM             
from LY_DT
QUALIFY ROW_NUM = 1)

    SELECT 
    CR.BRAND_ID,
    CR.STORE_ID,
    DT.FISCAL_PERIOD_START_DT,
    DT.FISCAL_1YR_COMP_PERIOD_DT,
    DT.CALENDAR_1YR_COMP_PERIOD_DT,
    DT.CALENDAR_2YR_COMP_PERIOD_DT,
    DT.CALENDAR_3YR_COMP_PERIOD_DT,
    SUM(NVL(FISC_1Y.COMP_SALES,0)) AS FISC_1Y_SALES,
    SUM(NVL(FISC_1Y.COMP_TRANS,0)) AS FISC_1Y_TRANS,
    SUM(NVL(CAL_1Y.COMP_SALES,0)) AS CAL_1Y_SALES,
    SUM(NVL(CAL_1Y.COMP_TRANS,0)) AS CAL_1Y_TRANS,
    SUM(NVL(CAL_2Y.COMP_SALES,0)) AS CAL_2Y_SALES,
    SUM(NVL(CAL_2Y.COMP_TRANS,0)) AS CAL_2Y_TRANS,
    SUM(NVL(CAL_3Y.COMP_SALES,0)) AS CAL_3Y_SALES,
    SUM(NVL(CAL_3Y.COMP_TRANS,0)) AS CAL_3Y_TRANS 
    FROM  table(FLASH_SUMMARY_COMP_PAST_WEEKS_without_threshold(BUSINESS_DATE,''CY'')) CR
    INNER JOIN DT
    ON DT.FISCAL_WEEK_START_DT = CR.AGG_START_DT
    AND CR.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_without_threshold(BUSINESS_DATE,''FISC1Y''))  FISC_1Y                                   
    ON CR.STORE_ID = FISC_1Y.STORE_ID 
    AND CR.BRAND_ID = FISC_1Y.BRAND_ID
    AND DT.FISCAL_1YR_COMP_WEEK_DT = FISC_1Y.AGG_START_DT
    AND DT.FISCAL_1YR_COMP_PERIOD_DT = FISC_1Y.FISCAL_PERIOD_START_DT
    AND FISC_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_without_threshold(BUSINESS_DATE,''CAL1Y''))  CAL_1Y
     ON CR.STORE_ID = CAL_1Y.STORE_ID 
     AND CR.BRAND_ID = CAL_1Y.BRAND_ID
     AND DT.CALENDAR_1YR_COMP_WEEK_DT = CAL_1Y.AGG_START_DT
     AND DT.CALENDAR_1YR_COMP_PERIOD_DT = CAL_1Y.FISCAL_PERIOD_START_DT
     AND CAL_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_without_threshold(BUSINESS_DATE,''CAL2Y''))  CAL_2Y
     ON CR.STORE_ID = CAL_2Y.STORE_ID 
     AND CR.BRAND_ID = CAL_2Y.BRAND_ID
     AND DT.CALENDAR_2YR_COMP_WEEK_DT = CAL_2Y.AGG_START_DT
     AND DT.CALENDAR_2YR_COMP_PERIOD_DT = CAL_2Y.FISCAL_PERIOD_START_DT
     AND CAL_2Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_without_threshold(BUSINESS_DATE,''CAL3Y''))  CAL_3Y
     ON CR.STORE_ID = CAL_3Y.STORE_ID 
     AND CR.BRAND_ID = CAL_3Y.BRAND_ID
     AND DT.CALENDAR_3YR_COMP_WEEK_DT = CAL_3Y.AGG_START_DT
     AND DT.CALENDAR_3YR_COMP_PERIOD_DT = CAL_3Y.FISCAL_PERIOD_START_DT
     AND CAL_3Y.FISCAL_WEEK_NBR !=53
WHERE CR.NET_SALES IS NOT NULL
AND CR.comp_sales = 0
GROUP BY 
CR.BRAND_ID,
CR.STORE_ID,
DT.FISCAL_PERIOD_START_DT,
DT.FISCAL_1YR_COMP_PERIOD_DT,
DT.CALENDAR_1YR_COMP_PERIOD_DT,
DT.CALENDAR_2YR_COMP_PERIOD_DT,
DT.CALENDAR_3YR_COMP_PERIOD_DT
';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_WEEKS_IN_QUARTERS("BUSINESS_DATE" DATE)
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "FISCAL_QUARTER_START_DT" DATE, "FISCAL_1YR_COMP_QUARTER_DT" DATE, "CALENDAR_1YR_COMP_QUARTER_DT" DATE, "CALENDAR_2YR_COMP_QUARTER_DT" DATE, "CALENDAR_3YR_COMP_QUARTER_DT" DATE, "FISC_1Y_SALES" NUMBER(38,2), "FISC_1Y_TRANS" NUMBER(38,0), "CAL_1Y_SALES" NUMBER(38,2), "CAL_1Y_TRANS" NUMBER(38,0), "CAL_2Y_SALES" NUMBER(38,2), "CAL_2Y_TRANS" NUMBER(38,0), "CAL_3Y_SALES" NUMBER(38,2), "CAL_3Y_TRANS" NUMBER(38,0))
LANGUAGE SQL
AS '

WITH CY_DT AS (
select CALENDAR_DT, 
FISCAL_QUARTER_START_DT,
FISCAL_WEEK_START_DT,
FISCAL_1YR_COMP_WEEK_DT,   
CALENDAR_1YR_COMP_WEEK_DT,
CALENDAR_2YR_COMP_WEEK_DT,
CALENDAR_3YR_COMP_WEEK_DT 
from IDS_DEV.INT_REF.COMP_CALENDAR 
where CALENDAR_DT = BUSINESS_DATE
),
DT AS (
SELECT DISTINCT
DT.FISCAL_QUARTER_START_DT,
DT.FISCAL_WEEK_START_DT,
DT.FISCAL_1YR_COMP_QUARTER_DT, 
DT.FISCAL_1YR_COMP_WEEK_DT,
DT.CALENDAR_1YR_COMP_QUARTER_DT,
DT.CALENDAR_1YR_COMP_WEEK_DT,
DT.CALENDAR_2YR_COMP_QUARTER_DT,
DT.CALENDAR_2YR_COMP_WEEK_DT,
DT.CALENDAR_3YR_COMP_QUARTER_DT,
DT.CALENDAR_3YR_COMP_WEEK_DT
FROM
IDS_DEV.INT_REF.COMP_CALENDAR DT
INNER JOIN CY_DT
ON DT.FISCAL_QUARTER_START_DT = CY_DT.FISCAL_QUARTER_START_DT
AND DT.FISCAL_WEEK_START_DT <= CY_DT.FISCAL_WEEK_START_DT
AND DT.FISCAL_1YR_COMP_WEEK_DT <= CY_DT.FISCAL_1YR_COMP_WEEK_DT
AND DT.CALENDAR_1YR_COMP_WEEK_DT <= CY_DT.CALENDAR_1YR_COMP_WEEK_DT
AND DT.CALENDAR_2YR_COMP_WEEK_DT <= CY_DT.CALENDAR_2YR_COMP_WEEK_DT
AND DT.CALENDAR_3YR_COMP_WEEK_DT <= CY_DT.CALENDAR_3YR_COMP_WEEK_DT
),
MAIN AS (
    SELECT 
    CR.BRAND_ID,
    CR.STORE_ID,
    DT.FISCAL_WEEK_START_DT,
    DT.FISCAL_QUARTER_START_DT,
    DT.FISCAL_1YR_COMP_QUARTER_DT,
    DT.CALENDAR_1YR_COMP_QUARTER_DT,
    DT.CALENDAR_2YR_COMP_QUARTER_DT,
    DT.CALENDAR_3YR_COMP_QUARTER_DT,
    CASE WHEN (CR.NET_SALES IS NOT NULL AND (CR.comp_sales = 0
    OR CR.CLOSED_BEFORE_PERIOD_END_FLAG
    OR CR.TEMP_CLOSED_FLAG)) THEN TRUE 
    WHEN  DW.STORE_ID IS NOT NULL THEN FALSE 
    ELSE NULL END AS CR_FLG,
    CASE WHEN CR_FLG THEN NVL(FISC_1Y.COMP_SALES,0) ELSE DW.FISC_1Y_SALES END AS FISC_1Y_SALES,
    CASE WHEN CR_FLG THEN NVL(FISC_1Y.COMP_TRANS,0) ELSE DW.FISC_1Y_TRANS END AS FISC_1Y_TRANS,
    CASE WHEN CR_FLG THEN NVL(CAL_1Y.COMP_SALES,0) ELSE DW.CAL_1Y_SALES END AS CAL_1Y_SALES,
    CASE WHEN CR_FLG THEN NVL(CAL_1Y.COMP_TRANS,0) ELSE DW.CAL_1Y_TRANS END AS CAL_1Y_TRANS,
    CASE WHEN CR_FLG THEN NVL(CAL_2Y.COMP_SALES,0) ELSE DW.CAL_2Y_SALES END AS CAL_2Y_SALES,
    CASE WHEN CR_FLG THEN NVL(CAL_2Y.COMP_TRANS,0) ELSE DW.CAL_2Y_TRANS END AS CAL_2Y_TRANS,
    CASE WHEN CR_FLG THEN NVL(CAL_3Y.COMP_SALES,0) ELSE DW.CAL_3Y_SALES END AS CAL_3Y_SALES,
    CASE WHEN CR_FLG THEN NVL(CAL_3Y.COMP_TRANS,0) ELSE DW.CAL_3Y_TRANS END AS CAL_3Y_TRANS
    FROM  DT
    INNER JOIN table(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''CY'')) CR
    ON DT.FISCAL_WEEK_START_DT = CR.AGG_START_DT
    AND CR.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN TABLE(FLASH_SUMMARY_COMP_WEEKS_TRESHOLD(BUSINESS_DATE)) DW
    ON CR.STORE_ID = DW.STORE_ID 
    AND CR.BRAND_ID = DW.BRAND_ID
    AND CR.AGG_START_DT = DW.FISCAL_WEEK_START_DT
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''FISC1Y''))  FISC_1Y                                    
    ON CR.STORE_ID = FISC_1Y.STORE_ID 
    AND CR.BRAND_ID = FISC_1Y.BRAND_ID
    AND DT.FISCAL_1YR_COMP_WEEK_DT = FISC_1Y.AGG_START_DT
    AND DT.FISCAL_1YR_COMP_QUARTER_DT = FISC_1Y.FISCAL_QUARTER_START_DT
    AND FISC_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''CAL1Y''))  CAL_1Y
     ON CR.STORE_ID = CAL_1Y.STORE_ID 
     AND CR.BRAND_ID = CAL_1Y.BRAND_ID
     AND DT.CALENDAR_1YR_COMP_WEEK_DT = CAL_1Y.AGG_START_DT
     AND DT.CALENDAR_1YR_COMP_QUARTER_DT = CAL_1Y.FISCAL_QUARTER_START_DT
     AND CAL_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''CAL2Y''))  CAL_2Y
     ON CR.STORE_ID = CAL_2Y.STORE_ID 
     AND CR.BRAND_ID = CAL_2Y.BRAND_ID
     AND DT.CALENDAR_2YR_COMP_WEEK_DT = CAL_2Y.AGG_START_DT
     AND DT.CALENDAR_2YR_COMP_QUARTER_DT = CAL_2Y.FISCAL_QUARTER_START_DT
     AND CAL_2Y.FISCAL_WEEK_NBR !=53
         LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''CAL3Y''))  CAL_3Y
     ON CR.STORE_ID = CAL_3Y.STORE_ID 
     AND CR.BRAND_ID = CAL_3Y.BRAND_ID
     AND DT.CALENDAR_3YR_COMP_WEEK_DT = CAL_3Y.AGG_START_DT
     AND DT.CALENDAR_3YR_COMP_QUARTER_DT = CAL_3Y.FISCAL_QUARTER_START_DT
     AND CAL_3Y.FISCAL_WEEK_NBR !=53
WHERE (CR.NET_SALES IS NOT NULL
AND (CR.comp_sales = 0
OR CR.CLOSED_BEFORE_PERIOD_END_FLAG
OR CR.TEMP_CLOSED_FLAG))
OR DW.STORE_ID IS NOT NULL)

SELECT 
BRAND_ID,
STORE_ID,
FISCAL_QUARTER_START_DT,
FISCAL_1YR_COMP_QUARTER_DT,
CALENDAR_1YR_COMP_QUARTER_DT,
CALENDAR_2YR_COMP_QUARTER_DT,
CALENDAR_3YR_COMP_QUARTER_DT,
SUM(FISC_1Y_SALES),
SUM(FISC_1Y_TRANS),
SUM(CAL_1Y_SALES),
SUM(CAL_1Y_TRANS),
SUM(CAL_2Y_SALES),
SUM(CAL_2Y_TRANS),
SUM(CAL_3Y_SALES),
SUM(CAL_3Y_TRANS)
FROM MAIN
GROUP BY 
BRAND_ID,
STORE_ID,
FISCAL_QUARTER_START_DT,
FISCAL_1YR_COMP_QUARTER_DT,
CALENDAR_1YR_COMP_QUARTER_DT,
CALENDAR_2YR_COMP_QUARTER_DT,
CALENDAR_3YR_COMP_QUARTER_DT

';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_WEEKS_IN_QUARTERS("BUSINESS_DATE" DATE, "REPORT_BRAND" VARCHAR(16777216), "THRESHOLD_FLAG" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "FISCAL_QUARTER_START_DT" DATE, "FISCAL_1YR_COMP_QUARTER_DT" DATE, "CALENDAR_1YR_COMP_QUARTER_DT" DATE, "CALENDAR_2YR_COMP_QUARTER_DT" DATE, "CALENDAR_3YR_COMP_QUARTER_DT" DATE, "FISC_1Y_SALES" NUMBER(38,2), "FISC_1Y_TRANS" NUMBER(38,0), "CAL_1Y_SALES" NUMBER(38,2), "CAL_1Y_TRANS" NUMBER(38,0), "CAL_2Y_SALES" NUMBER(38,2), "CAL_2Y_TRANS" NUMBER(38,0), "CAL_3Y_SALES" NUMBER(38,2), "CAL_3Y_TRANS" NUMBER(38,0))
LANGUAGE SQL
AS '

WITH CY_DT AS (
select CALENDAR_DT, 
FISCAL_QUARTER_START_DT,
FISCAL_WEEK_START_DT,
FISCAL_1YR_COMP_WEEK_DT,   
CALENDAR_1YR_COMP_WEEK_DT,
CALENDAR_2YR_COMP_WEEK_DT,
CALENDAR_3YR_COMP_WEEK_DT 
from IDS_DEV.INT_REF.COMP_CALENDAR 
where CALENDAR_DT = BUSINESS_DATE
),
LY_DT AS (
SELECT DISTINCT
DT.FISCAL_QUARTER_START_DT,
DT.FISCAL_WEEK_START_DT,
DT.FISCAL_1YR_COMP_QUARTER_DT, 
DT.FISCAL_1YR_COMP_WEEK_DT,
DT.CALENDAR_1YR_COMP_QUARTER_DT,
DT.CALENDAR_1YR_COMP_WEEK_DT,
DT.CALENDAR_2YR_COMP_QUARTER_DT,
DT.CALENDAR_2YR_COMP_WEEK_DT,
DT.CALENDAR_3YR_COMP_QUARTER_DT,
DT.CALENDAR_3YR_COMP_WEEK_DT
FROM
IDS_DEV.INT_REF.COMP_CALENDAR DT
INNER JOIN CY_DT
ON DT.FISCAL_QUARTER_START_DT = CY_DT.FISCAL_QUARTER_START_DT
AND DT.FISCAL_WEEK_START_DT <= CY_DT.FISCAL_WEEK_START_DT
AND DT.FISCAL_1YR_COMP_WEEK_DT <= CY_DT.FISCAL_1YR_COMP_WEEK_DT
AND DT.CALENDAR_1YR_COMP_WEEK_DT <= CY_DT.CALENDAR_1YR_COMP_WEEK_DT
AND DT.CALENDAR_2YR_COMP_WEEK_DT <= CY_DT.CALENDAR_2YR_COMP_WEEK_DT
AND DT.CALENDAR_3YR_COMP_WEEK_DT <= CY_DT.CALENDAR_3YR_COMP_WEEK_DT
),
DT AS (
SELECT 
FISCAL_QUARTER_START_DT,
FISCAL_WEEK_START_DT,
FISCAL_1YR_COMP_QUARTER_DT, 
FISCAL_1YR_COMP_WEEK_DT,
CALENDAR_1YR_COMP_QUARTER_DT,
CALENDAR_1YR_COMP_WEEK_DT,
CALENDAR_2YR_COMP_QUARTER_DT,
CALENDAR_2YR_COMP_WEEK_DT,
CALENDAR_3YR_COMP_QUARTER_DT,
CALENDAR_3YR_COMP_WEEK_DT,
ROW_NUMBER() OVER (PARTITION BY FISCAL_1YR_COMP_WEEK_DT
                   ORDER BY FISCAL_WEEK_START_DT, FISCAL_1YR_COMP_WEEK_DT ,CALENDAR_1YR_COMP_WEEK_DT ,CALENDAR_2YR_COMP_WEEK_DT ,CALENDAR_3YR_COMP_WEEK_DT) AS ROW_NUM             
from LY_DT
QUALIFY ROW_NUM = 1),
MAIN AS (
    SELECT 
    CR.BRAND_ID,
    CR.STORE_ID,
    DT.FISCAL_QUARTER_START_DT,
    DT.FISCAL_1YR_COMP_QUARTER_DT,
    DT.CALENDAR_1YR_COMP_QUARTER_DT,
    DT.CALENDAR_2YR_COMP_QUARTER_DT,
    DT.CALENDAR_3YR_COMP_QUARTER_DT,
    SUM(NVL(FISC_1Y.COMP_SALES,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT, DT.FISCAL_1YR_COMP_QUARTER_DT) AS FISC_1Y_SALES,
    SUM(NVL(FISC_1Y.COMP_TRANS,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT, DT.FISCAL_1YR_COMP_QUARTER_DT) AS FISC_1Y_TRANS,
    SUM(NVL(CAL_1Y.COMP_SALES,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT, DT.CALENDAR_1YR_COMP_QUARTER_DT) AS CAL_1Y_SALES,
    SUM(NVL(CAL_1Y.COMP_TRANS,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT, DT.CALENDAR_1YR_COMP_QUARTER_DT) AS CAL_1Y_TRANS,
    SUM(NVL(CAL_2Y.COMP_SALES,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT, DT.CALENDAR_2YR_COMP_QUARTER_DT) AS CAL_2Y_SALES,
    SUM(NVL(CAL_2Y.COMP_TRANS,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT, DT.CALENDAR_2YR_COMP_QUARTER_DT) AS CAL_2Y_TRANS,
    SUM(NVL(CAL_3Y.COMP_SALES,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT, DT.CALENDAR_3YR_COMP_QUARTER_DT) AS CAL_3Y_SALES,
    SUM(NVL(CAL_3Y.COMP_TRANS,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT, DT.CALENDAR_3YR_COMP_QUARTER_DT) AS CAL_3Y_TRANS,
    ROW_NUMBER() OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT,DT.FISCAL_1YR_COMP_QUARTER_DT,DT.CALENDAR_1YR_COMP_QUARTER_DT,DT.CALENDAR_2YR_COMP_QUARTER_DT,DT.CALENDAR_3YR_COMP_QUARTER_DT
                   ORDER BY DT.FISCAL_QUARTER_START_DT, DT.FISCAL_1YR_COMP_QUARTER_DT ,DT.CALENDAR_1YR_COMP_QUARTER_DT ,DT.CALENDAR_2YR_COMP_QUARTER_DT ,DT.CALENDAR_3YR_COMP_QUARTER_DT) AS ROW_NUM  
    FROM  table(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''CY'', REPORT_BRAND, THRESHOLD_FLAG)) CR
    INNER JOIN DT
    ON DT.FISCAL_WEEK_START_DT = CR.AGG_START_DT
    AND CR.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''FISC1Y'', REPORT_BRAND, THRESHOLD_FLAG))  FISC_1Y
                                          
    ON CR.STORE_ID = FISC_1Y.STORE_ID 
    AND CR.BRAND_ID = FISC_1Y.BRAND_ID
    AND DT.FISCAL_1YR_COMP_WEEK_DT = FISC_1Y.AGG_START_DT
    AND DT.FISCAL_1YR_COMP_QUARTER_DT = FISC_1Y.FISCAL_QUARTER_START_DT
    AND FISC_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''CAL1Y'', REPORT_BRAND, THRESHOLD_FLAG))  CAL_1Y
     ON CR.STORE_ID = CAL_1Y.STORE_ID 
     AND CR.BRAND_ID = CAL_1Y.BRAND_ID
     AND DT.CALENDAR_1YR_COMP_WEEK_DT = CAL_1Y.AGG_START_DT
     AND DT.CALENDAR_1YR_COMP_QUARTER_DT = CAL_1Y.FISCAL_QUARTER_START_DT
     AND CAL_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''CAL2Y'', REPORT_BRAND, THRESHOLD_FLAG))  CAL_2Y
     ON CR.STORE_ID = CAL_2Y.STORE_ID 
     AND CR.BRAND_ID = CAL_2Y.BRAND_ID
     AND DT.CALENDAR_2YR_COMP_WEEK_DT = CAL_2Y.AGG_START_DT
     AND DT.CALENDAR_2YR_COMP_QUARTER_DT = CAL_2Y.FISCAL_QUARTER_START_DT
     AND CAL_2Y.FISCAL_WEEK_NBR !=53
         LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''CAL3Y'', REPORT_BRAND, THRESHOLD_FLAG))  CAL_3Y
     ON CR.STORE_ID = CAL_3Y.STORE_ID 
     AND CR.BRAND_ID = CAL_3Y.BRAND_ID
     AND DT.CALENDAR_3YR_COMP_WEEK_DT = CAL_3Y.AGG_START_DT
     AND DT.CALENDAR_3YR_COMP_QUARTER_DT = CAL_3Y.FISCAL_QUARTER_START_DT
     AND CAL_3Y.FISCAL_WEEK_NBR !=53
WHERE CR.NET_SALES IS NOT NULL
AND (CR.comp_sales = 0
OR CR.CLOSED_BEFORE_PERIOD_END_FLAG
OR CR.TEMP_CLOSED_FLAG))

SELECT 
BRAND_ID,
STORE_ID,
FISCAL_QUARTER_START_DT,
FISCAL_1YR_COMP_QUARTER_DT,
CALENDAR_1YR_COMP_QUARTER_DT,
CALENDAR_2YR_COMP_QUARTER_DT,
CALENDAR_3YR_COMP_QUARTER_DT,
FISC_1Y_SALES,
FISC_1Y_TRANS,
CAL_1Y_SALES,
CAL_1Y_TRANS,
CAL_2Y_SALES,
CAL_2Y_TRANS,
CAL_3Y_SALES,
CAL_3Y_TRANS
FROM MAIN
WHERE ROW_NUM = 1
';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_WEEKS_IN_QUARTERS_F("BUSINESS_DATE" DATE)
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "FISCAL_QUARTER_START_DT" DATE, "FISCAL_1YR_COMP_QUARTER_DT" DATE, "CALENDAR_1YR_COMP_QUARTER_DT" DATE, "CALENDAR_2YR_COMP_QUARTER_DT" DATE, "CALENDAR_3YR_COMP_QUARTER_DT" DATE, "FISC_1Y_SALES" NUMBER(38,2), "FISC_1Y_TRANS" NUMBER(38,0), "CAL_1Y_SALES" NUMBER(38,2), "CAL_1Y_TRANS" NUMBER(38,0), "CAL_2Y_SALES" NUMBER(38,2), "CAL_2Y_TRANS" NUMBER(38,0), "CAL_3Y_SALES" NUMBER(38,2), "CAL_3Y_TRANS" NUMBER(38,0))
LANGUAGE SQL
AS '

WITH CY_DT AS (
select CALENDAR_DT, 
FISCAL_QUARTER_START_DT,
FISCAL_WEEK_START_DT,
FISCAL_1YR_COMP_WEEK_DT,   
CALENDAR_1YR_COMP_WEEK_DT,
CALENDAR_2YR_COMP_WEEK_DT,
CALENDAR_3YR_COMP_WEEK_DT 
from IDS_DEV.INT_REF.COMP_CALENDAR 
where CALENDAR_DT = BUSINESS_DATE
),
LY_DT AS (
SELECT DISTINCT
DT.FISCAL_QUARTER_START_DT,
DT.FISCAL_WEEK_START_DT,
DT.FISCAL_1YR_COMP_QUARTER_DT, 
DT.FISCAL_1YR_COMP_WEEK_DT,
DT.CALENDAR_1YR_COMP_QUARTER_DT,
DT.CALENDAR_1YR_COMP_WEEK_DT,
DT.CALENDAR_2YR_COMP_QUARTER_DT,
DT.CALENDAR_2YR_COMP_WEEK_DT,
DT.CALENDAR_3YR_COMP_QUARTER_DT,
DT.CALENDAR_3YR_COMP_WEEK_DT
FROM
IDS_DEV.INT_REF.COMP_CALENDAR DT
INNER JOIN CY_DT
ON DT.FISCAL_QUARTER_START_DT = CY_DT.FISCAL_QUARTER_START_DT
AND DT.FISCAL_WEEK_START_DT <= CY_DT.FISCAL_WEEK_START_DT
AND DT.FISCAL_1YR_COMP_WEEK_DT <= CY_DT.FISCAL_1YR_COMP_WEEK_DT
AND DT.CALENDAR_1YR_COMP_WEEK_DT <= CY_DT.CALENDAR_1YR_COMP_WEEK_DT
AND DT.CALENDAR_2YR_COMP_WEEK_DT <= CY_DT.CALENDAR_2YR_COMP_WEEK_DT
AND DT.CALENDAR_3YR_COMP_WEEK_DT <= CY_DT.CALENDAR_3YR_COMP_WEEK_DT
),
DT AS (
SELECT 
FISCAL_QUARTER_START_DT,
FISCAL_WEEK_START_DT,
FISCAL_1YR_COMP_QUARTER_DT, 
FISCAL_1YR_COMP_WEEK_DT,
CALENDAR_1YR_COMP_QUARTER_DT,
CALENDAR_1YR_COMP_WEEK_DT,
CALENDAR_2YR_COMP_QUARTER_DT,
CALENDAR_2YR_COMP_WEEK_DT,
CALENDAR_3YR_COMP_QUARTER_DT,
CALENDAR_3YR_COMP_WEEK_DT,
ROW_NUMBER() OVER (PARTITION BY FISCAL_1YR_COMP_WEEK_DT
                   ORDER BY FISCAL_WEEK_START_DT, FISCAL_1YR_COMP_WEEK_DT ,CALENDAR_1YR_COMP_WEEK_DT ,CALENDAR_2YR_COMP_WEEK_DT ,CALENDAR_3YR_COMP_WEEK_DT) AS ROW_NUM             
from LY_DT
QUALIFY ROW_NUM = 1),
MAIN AS (
    SELECT 
    CR.BRAND_ID,
    CR.STORE_ID,
    DT.FISCAL_QUARTER_START_DT,
    DT.FISCAL_1YR_COMP_QUARTER_DT,
    DT.CALENDAR_1YR_COMP_QUARTER_DT,
    DT.CALENDAR_2YR_COMP_QUARTER_DT,
    DT.CALENDAR_3YR_COMP_QUARTER_DT,
    SUM(NVL(FISC_1Y.COMP_SALES,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT, DT.FISCAL_1YR_COMP_QUARTER_DT) AS FISC_1Y_SALES,
    SUM(NVL(FISC_1Y.COMP_TRANS,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT, DT.FISCAL_1YR_COMP_QUARTER_DT) AS FISC_1Y_TRANS,
    SUM(NVL(CAL_1Y.COMP_SALES,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT, DT.CALENDAR_1YR_COMP_QUARTER_DT) AS CAL_1Y_SALES,
    SUM(NVL(CAL_1Y.COMP_TRANS,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT, DT.CALENDAR_1YR_COMP_QUARTER_DT) AS CAL_1Y_TRANS,
    SUM(NVL(CAL_2Y.COMP_SALES,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT, DT.CALENDAR_2YR_COMP_QUARTER_DT) AS CAL_2Y_SALES,
    SUM(NVL(CAL_2Y.COMP_TRANS,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT, DT.CALENDAR_2YR_COMP_QUARTER_DT) AS CAL_2Y_TRANS,
    SUM(NVL(CAL_3Y.COMP_SALES,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT, DT.CALENDAR_3YR_COMP_QUARTER_DT) AS CAL_3Y_SALES,
    SUM(NVL(CAL_3Y.COMP_TRANS,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT, DT.CALENDAR_3YR_COMP_QUARTER_DT) AS CAL_3Y_TRANS,
    ROW_NUMBER() OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT,DT.FISCAL_1YR_COMP_QUARTER_DT,DT.CALENDAR_1YR_COMP_QUARTER_DT,DT.CALENDAR_2YR_COMP_QUARTER_DT,DT.CALENDAR_3YR_COMP_QUARTER_DT
                   ORDER BY DT.FISCAL_QUARTER_START_DT, DT.FISCAL_1YR_COMP_QUARTER_DT ,DT.CALENDAR_1YR_COMP_QUARTER_DT ,DT.CALENDAR_2YR_COMP_QUARTER_DT ,DT.CALENDAR_3YR_COMP_QUARTER_DT) AS ROW_NUM  
    FROM  table(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''CY'')) CR
    INNER JOIN DT
    ON DT.FISCAL_WEEK_START_DT = CR.AGG_START_DT
    AND CR.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''FISC1Y''))  FISC_1Y
                                          
    ON CR.STORE_ID = FISC_1Y.STORE_ID 
    AND CR.BRAND_ID = FISC_1Y.BRAND_ID
    AND DT.FISCAL_1YR_COMP_WEEK_DT = FISC_1Y.AGG_START_DT
    AND DT.FISCAL_1YR_COMP_QUARTER_DT = FISC_1Y.FISCAL_QUARTER_START_DT
    AND FISC_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''CAL1Y''))  CAL_1Y
     ON CR.STORE_ID = CAL_1Y.STORE_ID 
     AND CR.BRAND_ID = CAL_1Y.BRAND_ID
     AND DT.CALENDAR_1YR_COMP_WEEK_DT = CAL_1Y.AGG_START_DT
     AND DT.CALENDAR_1YR_COMP_QUARTER_DT = CAL_1Y.FISCAL_QUARTER_START_DT
     AND CAL_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''CAL2Y''))  CAL_2Y
     ON CR.STORE_ID = CAL_2Y.STORE_ID 
     AND CR.BRAND_ID = CAL_2Y.BRAND_ID
     AND DT.CALENDAR_2YR_COMP_WEEK_DT = CAL_2Y.AGG_START_DT
     AND DT.CALENDAR_2YR_COMP_QUARTER_DT = CAL_2Y.FISCAL_QUARTER_START_DT
     AND CAL_2Y.FISCAL_WEEK_NBR !=53
         LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''CAL3Y''))  CAL_3Y
     ON CR.STORE_ID = CAL_3Y.STORE_ID 
     AND CR.BRAND_ID = CAL_3Y.BRAND_ID
     AND DT.CALENDAR_3YR_COMP_WEEK_DT = CAL_3Y.AGG_START_DT
     AND DT.CALENDAR_3YR_COMP_QUARTER_DT = CAL_3Y.FISCAL_QUARTER_START_DT
     AND CAL_3Y.FISCAL_WEEK_NBR !=53
WHERE CR.NET_SALES IS NOT NULL
AND (CR.comp_sales = 0
OR CR.CLOSED_BEFORE_PERIOD_END_FLAG
OR CR.TEMP_CLOSED_FLAG))

SELECT 
BRAND_ID,
STORE_ID,
FISCAL_QUARTER_START_DT,
FISCAL_1YR_COMP_QUARTER_DT,
CALENDAR_1YR_COMP_QUARTER_DT,
CALENDAR_2YR_COMP_QUARTER_DT,
CALENDAR_3YR_COMP_QUARTER_DT,
FISC_1Y_SALES,
FISC_1Y_TRANS,
CAL_1Y_SALES,
CAL_1Y_TRANS,
CAL_2Y_SALES,
CAL_2Y_TRANS,
CAL_3Y_SALES,
CAL_3Y_TRANS
FROM MAIN
WHERE ROW_NUM = 1
';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_WEEKS_IN_QUARTERS_F("BUSINESS_DATE" DATE, "BRAND" VARCHAR(16777216), "THRESHOLD_FLG" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "FISCAL_QUARTER_START_DT" DATE, "FISCAL_1YR_COMP_QUARTER_DT" DATE, "CALENDAR_1YR_COMP_QUARTER_DT" DATE, "CALENDAR_2YR_COMP_QUARTER_DT" DATE, "CALENDAR_3YR_COMP_QUARTER_DT" DATE, "FISC_1Y_SALES" NUMBER(38,2), "FISC_1Y_TRANS" NUMBER(38,0), "CAL_1Y_SALES" NUMBER(38,2), "CAL_1Y_TRANS" NUMBER(38,0), "CAL_2Y_SALES" NUMBER(38,2), "CAL_2Y_TRANS" NUMBER(38,0), "CAL_3Y_SALES" NUMBER(38,2), "CAL_3Y_TRANS" NUMBER(38,0))
LANGUAGE SQL
AS '

WITH CY_DT AS (
select CALENDAR_DT, 
FISCAL_QUARTER_START_DT,
FISCAL_WEEK_START_DT,
FISCAL_1YR_COMP_WEEK_DT,   
CALENDAR_1YR_COMP_WEEK_DT,
CALENDAR_2YR_COMP_WEEK_DT,
CALENDAR_3YR_COMP_WEEK_DT 
from IDS_DEV.INT_REF.COMP_CALENDAR 
where CALENDAR_DT = BUSINESS_DATE
),
DT AS (
SELECT DISTINCT
DT.FISCAL_QUARTER_START_DT,
DT.FISCAL_WEEK_START_DT,
DT.FISCAL_1YR_COMP_QUARTER_DT, 
DT.FISCAL_1YR_COMP_WEEK_DT,
DT.CALENDAR_1YR_COMP_QUARTER_DT,
DT.CALENDAR_1YR_COMP_WEEK_DT,
DT.CALENDAR_2YR_COMP_QUARTER_DT,
DT.CALENDAR_2YR_COMP_WEEK_DT,
DT.CALENDAR_3YR_COMP_QUARTER_DT,
DT.CALENDAR_3YR_COMP_WEEK_DT
FROM
IDS_DEV.INT_REF.COMP_CALENDAR DT
INNER JOIN CY_DT
ON DT.FISCAL_QUARTER_START_DT = CY_DT.FISCAL_QUARTER_START_DT
AND DT.FISCAL_WEEK_START_DT <= CY_DT.FISCAL_WEEK_START_DT
AND DT.FISCAL_1YR_COMP_WEEK_DT <= CY_DT.FISCAL_1YR_COMP_WEEK_DT
AND DT.CALENDAR_1YR_COMP_WEEK_DT <= CY_DT.CALENDAR_1YR_COMP_WEEK_DT
AND DT.CALENDAR_2YR_COMP_WEEK_DT <= CY_DT.CALENDAR_2YR_COMP_WEEK_DT
AND DT.CALENDAR_3YR_COMP_WEEK_DT <= CY_DT.CALENDAR_3YR_COMP_WEEK_DT
),
MAIN AS (
    SELECT 
    CR.BRAND_ID,
    CR.STORE_ID,
    DT.FISCAL_WEEK_START_DT,
    DT.FISCAL_QUARTER_START_DT,
    DT.FISCAL_1YR_COMP_QUARTER_DT,
    DT.CALENDAR_1YR_COMP_QUARTER_DT,
    DT.CALENDAR_2YR_COMP_QUARTER_DT,
    DT.CALENDAR_3YR_COMP_QUARTER_DT,
    CASE WHEN (CR.NET_SALES IS NOT NULL AND (CR.comp_sales = 0
    OR CR.CLOSED_BEFORE_PERIOD_END_FLAG
    OR CR.TEMP_CLOSED_FLAG)) THEN TRUE 
    WHEN  DW.STORE_ID IS NOT NULL THEN FALSE 
    ELSE NULL END AS CR_FLG,
    CASE WHEN CR_FLG THEN NVL(FISC_1Y.COMP_SALES,0) ELSE DW.FISC_1Y_SALES END AS FISC_1Y_SALES,
    CASE WHEN CR_FLG THEN NVL(FISC_1Y.COMP_TRANS,0) ELSE DW.FISC_1Y_TRANS END AS FISC_1Y_TRANS,
    CASE WHEN CR_FLG THEN NVL(CAL_1Y.COMP_SALES,0) ELSE DW.CAL_1Y_SALES END AS CAL_1Y_SALES,
    CASE WHEN CR_FLG THEN NVL(CAL_1Y.COMP_TRANS,0) ELSE DW.CAL_1Y_TRANS END AS CAL_1Y_TRANS,
    CASE WHEN CR_FLG THEN NVL(CAL_2Y.COMP_SALES,0) ELSE DW.CAL_2Y_SALES END AS CAL_2Y_SALES,
    CASE WHEN CR_FLG THEN NVL(CAL_2Y.COMP_TRANS,0) ELSE DW.CAL_2Y_TRANS END AS CAL_2Y_TRANS,
    CASE WHEN CR_FLG THEN NVL(CAL_3Y.COMP_SALES,0) ELSE DW.CAL_3Y_SALES END AS CAL_3Y_SALES,
    CASE WHEN CR_FLG THEN NVL(CAL_3Y.COMP_TRANS,0) ELSE DW.CAL_3Y_TRANS END AS CAL_3Y_TRANS
    FROM DT
    INNER JOIN table(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''CY'', BRAND, THRESHOLD_FLG)) CR
    ON DT.FISCAL_WEEK_START_DT = CR.AGG_START_DT
    AND CR.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN TABLE(FLASH_SUMMARY_COMP_WEEKS_TRESHOLD_F(BUSINESS_DATE, BRAND, THRESHOLD_FLG)) DW
    ON CR.STORE_ID = DW.STORE_ID 
    AND CR.BRAND_ID = DW.BRAND_ID
    AND CR.AGG_START_DT = DW.FISCAL_WEEK_START_DT
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''FISC1Y'', BRAND, THRESHOLD_FLG))  FISC_1Y
                                          
    ON CR.STORE_ID = FISC_1Y.STORE_ID 
    AND CR.BRAND_ID = FISC_1Y.BRAND_ID
    AND DT.FISCAL_1YR_COMP_WEEK_DT = FISC_1Y.AGG_START_DT
    AND DT.FISCAL_1YR_COMP_QUARTER_DT = FISC_1Y.FISCAL_QUARTER_START_DT
    AND FISC_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''CAL1Y'', BRAND, THRESHOLD_FLG))  CAL_1Y
     ON CR.STORE_ID = CAL_1Y.STORE_ID 
     AND CR.BRAND_ID = CAL_1Y.BRAND_ID
     AND DT.CALENDAR_1YR_COMP_WEEK_DT = CAL_1Y.AGG_START_DT
     AND DT.CALENDAR_1YR_COMP_QUARTER_DT = CAL_1Y.FISCAL_QUARTER_START_DT
     AND CAL_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''CAL2Y'', BRAND, THRESHOLD_FLG))  CAL_2Y
     ON CR.STORE_ID = CAL_2Y.STORE_ID 
     AND CR.BRAND_ID = CAL_2Y.BRAND_ID
     AND DT.CALENDAR_2YR_COMP_WEEK_DT = CAL_2Y.AGG_START_DT
     AND DT.CALENDAR_2YR_COMP_QUARTER_DT = CAL_2Y.FISCAL_QUARTER_START_DT
     AND CAL_2Y.FISCAL_WEEK_NBR !=53
         LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''CAL3Y'', BRAND, THRESHOLD_FLG))  CAL_3Y
     ON CR.STORE_ID = CAL_3Y.STORE_ID 
     AND CR.BRAND_ID = CAL_3Y.BRAND_ID
     AND DT.CALENDAR_3YR_COMP_WEEK_DT = CAL_3Y.AGG_START_DT
     AND DT.CALENDAR_3YR_COMP_QUARTER_DT = CAL_3Y.FISCAL_QUARTER_START_DT
     AND CAL_3Y.FISCAL_WEEK_NBR !=53
WHERE (CR.NET_SALES IS NOT NULL
AND (CR.comp_sales = 0
OR CR.CLOSED_BEFORE_PERIOD_END_FLAG
OR CR.TEMP_CLOSED_FLAG))
OR DW.STORE_ID IS NOT NULL)

SELECT 
BRAND_ID,
STORE_ID,
FISCAL_QUARTER_START_DT,
FISCAL_1YR_COMP_QUARTER_DT,
CALENDAR_1YR_COMP_QUARTER_DT,
CALENDAR_2YR_COMP_QUARTER_DT,
CALENDAR_3YR_COMP_QUARTER_DT,
SUM(FISC_1Y_SALES),
SUM(FISC_1Y_TRANS),
SUM(CAL_1Y_SALES),
SUM(CAL_1Y_TRANS),
SUM(CAL_2Y_SALES),
SUM(CAL_2Y_TRANS),
SUM(CAL_3Y_SALES),
SUM(CAL_3Y_TRANS)
FROM MAIN
GROUP BY 
BRAND_ID,
STORE_ID,
FISCAL_QUARTER_START_DT,
FISCAL_1YR_COMP_QUARTER_DT,
CALENDAR_1YR_COMP_QUARTER_DT,
CALENDAR_2YR_COMP_QUARTER_DT,
CALENDAR_3YR_COMP_QUARTER_DT
';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_WEEKS_IN_QUARTERS_WITHOUT_THRESHOLD("BUSINESS_DATE" DATE)
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "FISCAL_QUARTER_START_DT" DATE, "FISCAL_1YR_COMP_QUARTER_DT" DATE, "CALENDAR_1YR_COMP_QUARTER_DT" DATE, "CALENDAR_2YR_COMP_QUARTER_DT" DATE, "CALENDAR_3YR_COMP_QUARTER_DT" DATE, "FISC_1Y_SALES" NUMBER(38,2), "FISC_1Y_TRANS" NUMBER(38,0), "CAL_1Y_SALES" NUMBER(38,2), "CAL_1Y_TRANS" NUMBER(38,0), "CAL_2Y_SALES" NUMBER(38,2), "CAL_2Y_TRANS" NUMBER(38,0), "CAL_3Y_SALES" NUMBER(38,2), "CAL_3Y_TRANS" NUMBER(38,0))
LANGUAGE SQL
AS '

WITH CY_DT AS (
select CALENDAR_DT, 
FISCAL_QUARTER_START_DT,
FISCAL_WEEK_START_DT,
FISCAL_1YR_COMP_WEEK_DT,   
CALENDAR_1YR_COMP_WEEK_DT,
CALENDAR_2YR_COMP_WEEK_DT,
CALENDAR_3YR_COMP_WEEK_DT 
from IDS_DEV.INT_REF.COMP_CALENDAR 
where CALENDAR_DT = BUSINESS_DATE
),
LY_DT AS (
SELECT DISTINCT
DT.FISCAL_QUARTER_START_DT,
DT.FISCAL_WEEK_START_DT,
DT.FISCAL_1YR_COMP_QUARTER_DT, 
DT.FISCAL_1YR_COMP_WEEK_DT,
DT.CALENDAR_1YR_COMP_QUARTER_DT,
DT.CALENDAR_1YR_COMP_WEEK_DT,
DT.CALENDAR_2YR_COMP_QUARTER_DT,
DT.CALENDAR_2YR_COMP_WEEK_DT,
DT.CALENDAR_3YR_COMP_QUARTER_DT,
DT.CALENDAR_3YR_COMP_WEEK_DT
FROM
IDS_DEV.INT_REF.COMP_CALENDAR DT
INNER JOIN CY_DT
ON DT.FISCAL_QUARTER_START_DT = CY_DT.FISCAL_QUARTER_START_DT
AND DT.FISCAL_WEEK_START_DT <= CY_DT.FISCAL_WEEK_START_DT
AND DT.FISCAL_1YR_COMP_WEEK_DT <= CY_DT.FISCAL_1YR_COMP_WEEK_DT
AND DT.CALENDAR_1YR_COMP_WEEK_DT <= CY_DT.CALENDAR_1YR_COMP_WEEK_DT
AND DT.CALENDAR_2YR_COMP_WEEK_DT <= CY_DT.CALENDAR_2YR_COMP_WEEK_DT
AND DT.CALENDAR_3YR_COMP_WEEK_DT <= CY_DT.CALENDAR_3YR_COMP_WEEK_DT
),
DT AS (
SELECT 
FISCAL_QUARTER_START_DT,
FISCAL_WEEK_START_DT,
FISCAL_1YR_COMP_QUARTER_DT, 
FISCAL_1YR_COMP_WEEK_DT,
CALENDAR_1YR_COMP_QUARTER_DT,
CALENDAR_1YR_COMP_WEEK_DT,
CALENDAR_2YR_COMP_QUARTER_DT,
CALENDAR_2YR_COMP_WEEK_DT,
CALENDAR_3YR_COMP_QUARTER_DT,
CALENDAR_3YR_COMP_WEEK_DT,
ROW_NUMBER() OVER (PARTITION BY FISCAL_1YR_COMP_WEEK_DT
                   ORDER BY FISCAL_WEEK_START_DT, FISCAL_1YR_COMP_WEEK_DT ,CALENDAR_1YR_COMP_WEEK_DT ,CALENDAR_2YR_COMP_WEEK_DT ,CALENDAR_3YR_COMP_WEEK_DT) AS ROW_NUM             
from LY_DT
QUALIFY ROW_NUM = 1),
MAIN AS (
    SELECT 
    CR.BRAND_ID,
    CR.STORE_ID,
    DT.FISCAL_QUARTER_START_DT,
    DT.FISCAL_1YR_COMP_QUARTER_DT,
    DT.CALENDAR_1YR_COMP_QUARTER_DT,
    DT.CALENDAR_2YR_COMP_QUARTER_DT,
    DT.CALENDAR_3YR_COMP_QUARTER_DT,
    SUM(NVL(FISC_1Y.COMP_SALES,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT, DT.FISCAL_1YR_COMP_QUARTER_DT) AS FISC_1Y_SALES,
    SUM(NVL(FISC_1Y.COMP_TRANS,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT, DT.FISCAL_1YR_COMP_QUARTER_DT) AS FISC_1Y_TRANS,
    SUM(NVL(CAL_1Y.COMP_SALES,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT, DT.CALENDAR_1YR_COMP_QUARTER_DT) AS CAL_1Y_SALES,
    SUM(NVL(CAL_1Y.COMP_TRANS,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT, DT.CALENDAR_1YR_COMP_QUARTER_DT) AS CAL_1Y_TRANS,
    SUM(NVL(CAL_2Y.COMP_SALES,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT, DT.CALENDAR_2YR_COMP_QUARTER_DT) AS CAL_2Y_SALES,
    SUM(NVL(CAL_2Y.COMP_TRANS,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT, DT.CALENDAR_2YR_COMP_QUARTER_DT) AS CAL_2Y_TRANS,
    SUM(NVL(CAL_3Y.COMP_SALES,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT, DT.CALENDAR_3YR_COMP_QUARTER_DT) AS CAL_3Y_SALES,
    SUM(NVL(CAL_3Y.COMP_TRANS,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT, DT.CALENDAR_3YR_COMP_QUARTER_DT) AS CAL_3Y_TRANS,
    ROW_NUMBER() OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_QUARTER_START_DT,DT.FISCAL_1YR_COMP_QUARTER_DT,DT.CALENDAR_1YR_COMP_QUARTER_DT,DT.CALENDAR_2YR_COMP_QUARTER_DT,DT.CALENDAR_3YR_COMP_QUARTER_DT
                   ORDER BY DT.FISCAL_QUARTER_START_DT, DT.FISCAL_1YR_COMP_QUARTER_DT ,DT.CALENDAR_1YR_COMP_QUARTER_DT ,DT.CALENDAR_2YR_COMP_QUARTER_DT ,DT.CALENDAR_3YR_COMP_QUARTER_DT) AS ROW_NUM  
    FROM  table(FLASH_SUMMARY_COMP_PAST_WEEKS_without_threshold(BUSINESS_DATE,''CY'')) CR
    INNER JOIN DT
    ON DT.FISCAL_WEEK_START_DT = CR.AGG_START_DT
    AND CR.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_without_threshold(BUSINESS_DATE,''FISC1Y''))  FISC_1Y
                                          
    ON CR.STORE_ID = FISC_1Y.STORE_ID 
    AND CR.BRAND_ID = FISC_1Y.BRAND_ID
    AND DT.FISCAL_1YR_COMP_WEEK_DT = FISC_1Y.AGG_START_DT
    AND DT.FISCAL_1YR_COMP_QUARTER_DT = FISC_1Y.FISCAL_QUARTER_START_DT
    AND FISC_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_without_threshold(BUSINESS_DATE,''CAL1Y''))  CAL_1Y
     ON CR.STORE_ID = CAL_1Y.STORE_ID 
     AND CR.BRAND_ID = CAL_1Y.BRAND_ID
     AND DT.CALENDAR_1YR_COMP_WEEK_DT = CAL_1Y.AGG_START_DT
     AND DT.CALENDAR_1YR_COMP_QUARTER_DT = CAL_1Y.FISCAL_QUARTER_START_DT
     AND CAL_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_without_threshold(BUSINESS_DATE,''CAL2Y''))  CAL_2Y
     ON CR.STORE_ID = CAL_2Y.STORE_ID 
     AND CR.BRAND_ID = CAL_2Y.BRAND_ID
     AND DT.CALENDAR_2YR_COMP_WEEK_DT = CAL_2Y.AGG_START_DT
     AND DT.CALENDAR_2YR_COMP_QUARTER_DT = CAL_2Y.FISCAL_QUARTER_START_DT
     AND CAL_2Y.FISCAL_WEEK_NBR !=53
         LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_without_threshold(BUSINESS_DATE,''CAL3Y''))  CAL_3Y
     ON CR.STORE_ID = CAL_3Y.STORE_ID 
     AND CR.BRAND_ID = CAL_3Y.BRAND_ID
     AND DT.CALENDAR_3YR_COMP_WEEK_DT = CAL_3Y.AGG_START_DT
     AND DT.CALENDAR_3YR_COMP_QUARTER_DT = CAL_3Y.FISCAL_QUARTER_START_DT
     AND CAL_3Y.FISCAL_WEEK_NBR !=53
WHERE CR.NET_SALES IS NOT NULL
AND (CR.comp_sales = 0
OR CR.CLOSED_BEFORE_PERIOD_END_FLAG
OR CR.TEMP_CLOSED_FLAG))

SELECT 
BRAND_ID,
STORE_ID,
FISCAL_QUARTER_START_DT,
FISCAL_1YR_COMP_QUARTER_DT,
CALENDAR_1YR_COMP_QUARTER_DT,
CALENDAR_2YR_COMP_QUARTER_DT,
CALENDAR_3YR_COMP_QUARTER_DT,
FISC_1Y_SALES,
FISC_1Y_TRANS,
CAL_1Y_SALES,
CAL_1Y_TRANS,
CAL_2Y_SALES,
CAL_2Y_TRANS,
CAL_3Y_SALES,
CAL_3Y_TRANS
FROM MAIN
WHERE ROW_NUM = 1
';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_WEEKS_IN_YEARS("BUSINESS_DATE" DATE)
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "FISCAL_YEAR_START_DT" DATE, "FISCAL_1YR_COMP_YEAR_DT" DATE, "CALENDAR_1YR_COMP_YEAR_DT" DATE, "CALENDAR_2YR_COMP_YEAR_DT" DATE, "CALENDAR_3YR_COMP_YEAR_DT" DATE, "FISC_1Y_SALES" NUMBER(38,2), "FISC_1Y_TRANS" NUMBER(38,0), "CAL_1Y_SALES" NUMBER(38,2), "CAL_1Y_TRANS" NUMBER(38,0), "CAL_2Y_SALES" NUMBER(38,2), "CAL_2Y_TRANS" NUMBER(38,0), "CAL_3Y_SALES" NUMBER(38,2), "CAL_3Y_TRANS" NUMBER(38,0))
LANGUAGE SQL
AS '

WITH CY_DT AS (
select CALENDAR_DT, 
FISCAL_YEAR_START_DT,
FISCAL_WEEK_START_DT,
FISCAL_1YR_COMP_WEEK_DT,   
CALENDAR_1YR_COMP_WEEK_DT,
CALENDAR_2YR_COMP_WEEK_DT,
CALENDAR_3YR_COMP_WEEK_DT 
from IDS_DEV.INT_REF.COMP_CALENDAR 
where CALENDAR_DT = BUSINESS_DATE
),
DT AS (
SELECT DISTINCT
DT.FISCAL_YEAR_START_DT,
DT.FISCAL_WEEK_START_DT,
DT.FISCAL_1YR_COMP_YEAR_DT, 
DT.FISCAL_1YR_COMP_WEEK_DT,
DT.CALENDAR_1YR_COMP_YEAR_DT,
DT.CALENDAR_1YR_COMP_WEEK_DT,
DT.CALENDAR_2YR_COMP_YEAR_DT,
DT.CALENDAR_2YR_COMP_WEEK_DT,
DT.CALENDAR_3YR_COMP_YEAR_DT,
DT.CALENDAR_3YR_COMP_WEEK_DT
FROM
IDS_DEV.INT_REF.COMP_CALENDAR DT
INNER JOIN CY_DT
ON DT.FISCAL_YEAR_START_DT = CY_DT.FISCAL_YEAR_START_DT
AND DT.FISCAL_WEEK_START_DT <= CY_DT.FISCAL_WEEK_START_DT
AND DT.FISCAL_1YR_COMP_WEEK_DT <= CY_DT.FISCAL_1YR_COMP_WEEK_DT
AND DT.CALENDAR_1YR_COMP_WEEK_DT <= CY_DT.CALENDAR_1YR_COMP_WEEK_DT
AND DT.CALENDAR_2YR_COMP_WEEK_DT <= CY_DT.CALENDAR_2YR_COMP_WEEK_DT
AND DT.CALENDAR_3YR_COMP_WEEK_DT <= CY_DT.CALENDAR_3YR_COMP_WEEK_DT
),
MAIN AS (
    SELECT 
    CR.BRAND_ID,
    CR.STORE_ID,
    DT.FISCAL_YEAR_START_DT,
    DT.FISCAL_1YR_COMP_YEAR_DT,
    DT.CALENDAR_1YR_COMP_YEAR_DT,
    DT.CALENDAR_2YR_COMP_YEAR_DT,
    DT.CALENDAR_3YR_COMP_YEAR_DT,
    CASE WHEN (CR.NET_SALES IS NOT NULL AND (CR.comp_sales = 0
    OR CR.CLOSED_BEFORE_PERIOD_END_FLAG
    OR CR.TEMP_CLOSED_FLAG)) THEN TRUE 
    WHEN  DW.STORE_ID IS NOT NULL THEN FALSE 
    ELSE NULL END AS CR_FLG,
    CASE WHEN CR_FLG THEN NVL(FISC_1Y.COMP_SALES,0) ELSE DW.FISC_1Y_SALES END AS FISC_1Y_SALES,
    CASE WHEN CR_FLG THEN NVL(FISC_1Y.COMP_TRANS,0) ELSE DW.FISC_1Y_TRANS END AS FISC_1Y_TRANS,
    CASE WHEN CR_FLG THEN NVL(CAL_1Y.COMP_SALES,0) ELSE DW.CAL_1Y_SALES END AS CAL_1Y_SALES,
    CASE WHEN CR_FLG THEN NVL(CAL_1Y.COMP_TRANS,0) ELSE DW.CAL_1Y_TRANS END AS CAL_1Y_TRANS,
    CASE WHEN CR_FLG THEN NVL(CAL_2Y.COMP_SALES,0) ELSE DW.CAL_2Y_SALES END AS CAL_2Y_SALES,
    CASE WHEN CR_FLG THEN NVL(CAL_2Y.COMP_TRANS,0) ELSE DW.CAL_2Y_TRANS END AS CAL_2Y_TRANS,
    CASE WHEN CR_FLG THEN NVL(CAL_3Y.COMP_SALES,0) ELSE DW.CAL_3Y_SALES END AS CAL_3Y_SALES,
    CASE WHEN CR_FLG THEN NVL(CAL_3Y.COMP_TRANS,0) ELSE DW.CAL_3Y_TRANS END AS CAL_3Y_TRANS
    FROM  DT
    INNER JOIN table(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''CY'')) CR
    ON DT.FISCAL_WEEK_START_DT = CR.AGG_START_DT
    AND CR.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN TABLE(FLASH_SUMMARY_COMP_WEEKS_TRESHOLD(BUSINESS_DATE)) DW
    ON CR.STORE_ID = DW.STORE_ID 
    AND CR.BRAND_ID = DW.BRAND_ID
    AND CR.AGG_START_DT = DW.FISCAL_WEEK_START_DT
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''FISC1Y''))  FISC_1Y                                   
    ON CR.STORE_ID = FISC_1Y.STORE_ID 
    AND CR.BRAND_ID = FISC_1Y.BRAND_ID
    AND DT.FISCAL_1YR_COMP_WEEK_DT = FISC_1Y.AGG_START_DT
    AND DT.FISCAL_1YR_COMP_YEAR_DT = FISC_1Y.FISCAL_YEAR_START_DT
    AND FISC_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''CAL1Y''))  CAL_1Y
     ON CR.STORE_ID = CAL_1Y.STORE_ID 
     AND CR.BRAND_ID = CAL_1Y.BRAND_ID
     AND DT.CALENDAR_1YR_COMP_WEEK_DT = CAL_1Y.AGG_START_DT
     AND DT.CALENDAR_1YR_COMP_YEAR_DT = CAL_1Y.FISCAL_YEAR_START_DT
     AND CAL_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''CAL2Y''))  CAL_2Y
     ON CR.STORE_ID = CAL_2Y.STORE_ID 
     AND CR.BRAND_ID = CAL_2Y.BRAND_ID
     AND DT.CALENDAR_2YR_COMP_WEEK_DT = CAL_2Y.AGG_START_DT
     AND DT.CALENDAR_2YR_COMP_YEAR_DT = CAL_2Y.FISCAL_YEAR_START_DT
     AND CAL_2Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''CAL3Y''))  CAL_3Y
     ON CR.STORE_ID = CAL_3Y.STORE_ID 
     AND CR.BRAND_ID = CAL_3Y.BRAND_ID
     AND DT.CALENDAR_3YR_COMP_WEEK_DT = CAL_3Y.AGG_START_DT
     AND DT.CALENDAR_3YR_COMP_YEAR_DT = CAL_3Y.FISCAL_YEAR_START_DT
     AND CAL_3Y.FISCAL_WEEK_NBR !=53
WHERE (CR.NET_SALES IS NOT NULL
AND (CR.comp_sales = 0
OR CR.CLOSED_BEFORE_PERIOD_END_FLAG
OR CR.TEMP_CLOSED_FLAG))
OR DW.STORE_ID IS NOT NULL)

SELECT 
BRAND_ID,
STORE_ID,
FISCAL_YEAR_START_DT,
FISCAL_1YR_COMP_YEAR_DT,
CALENDAR_1YR_COMP_YEAR_DT,
CALENDAR_2YR_COMP_YEAR_DT,
CALENDAR_3YR_COMP_YEAR_DT,
SUM(FISC_1Y_SALES),
SUM(FISC_1Y_TRANS),
SUM(CAL_1Y_SALES),
SUM(CAL_1Y_TRANS),
SUM(CAL_2Y_SALES),
SUM(CAL_2Y_TRANS),
SUM(CAL_3Y_SALES),
SUM(CAL_3Y_TRANS)
FROM MAIN
GROUP BY 
BRAND_ID,
STORE_ID,
FISCAL_YEAR_START_DT,
FISCAL_1YR_COMP_YEAR_DT,
CALENDAR_1YR_COMP_YEAR_DT,
CALENDAR_2YR_COMP_YEAR_DT,
CALENDAR_3YR_COMP_YEAR_DT
';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_WEEKS_IN_YEARS("BUSINESS_DATE" DATE, "REPORT_BRAND" VARCHAR(16777216), "THRESHOLD_FLAG" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "FISCAL_YEAR_START_DT" DATE, "FISCAL_1YR_COMP_YEAR_DT" DATE, "CALENDAR_1YR_COMP_YEAR_DT" DATE, "CALENDAR_2YR_COMP_YEAR_DT" DATE, "CALENDAR_3YR_COMP_YEAR_DT" DATE, "FISC_1Y_SALES" NUMBER(38,2), "FISC_1Y_TRANS" NUMBER(38,0), "CAL_1Y_SALES" NUMBER(38,2), "CAL_1Y_TRANS" NUMBER(38,0), "CAL_2Y_SALES" NUMBER(38,2), "CAL_2Y_TRANS" NUMBER(38,0), "CAL_3Y_SALES" NUMBER(38,2), "CAL_3Y_TRANS" NUMBER(38,0))
LANGUAGE SQL
AS '

WITH CY_DT AS (
select CALENDAR_DT, 
FISCAL_YEAR_START_DT,
FISCAL_WEEK_START_DT,
FISCAL_1YR_COMP_WEEK_DT,   
CALENDAR_1YR_COMP_WEEK_DT,
CALENDAR_2YR_COMP_WEEK_DT,
CALENDAR_3YR_COMP_WEEK_DT 
from IDS_DEV.INT_REF.COMP_CALENDAR 
where CALENDAR_DT = BUSINESS_DATE
),
LY_DT AS (
SELECT DISTINCT
DT.FISCAL_YEAR_START_DT,
DT.FISCAL_WEEK_START_DT,
DT.FISCAL_1YR_COMP_YEAR_DT, 
DT.FISCAL_1YR_COMP_WEEK_DT,
DT.CALENDAR_1YR_COMP_YEAR_DT,
DT.CALENDAR_1YR_COMP_WEEK_DT,
DT.CALENDAR_2YR_COMP_YEAR_DT,
DT.CALENDAR_2YR_COMP_WEEK_DT,
DT.CALENDAR_3YR_COMP_YEAR_DT,
DT.CALENDAR_3YR_COMP_WEEK_DT
FROM
IDS_DEV.INT_REF.COMP_CALENDAR DT
INNER JOIN CY_DT
ON DT.FISCAL_YEAR_START_DT = CY_DT.FISCAL_YEAR_START_DT
AND DT.FISCAL_WEEK_START_DT <= CY_DT.FISCAL_WEEK_START_DT
AND DT.FISCAL_1YR_COMP_WEEK_DT <= CY_DT.FISCAL_1YR_COMP_WEEK_DT
AND DT.CALENDAR_1YR_COMP_WEEK_DT <= CY_DT.CALENDAR_1YR_COMP_WEEK_DT
AND DT.CALENDAR_2YR_COMP_WEEK_DT <= CY_DT.CALENDAR_2YR_COMP_WEEK_DT
AND DT.CALENDAR_3YR_COMP_WEEK_DT <= CY_DT.CALENDAR_3YR_COMP_WEEK_DT
),
DT AS (
SELECT 
FISCAL_YEAR_START_DT,
FISCAL_WEEK_START_DT,
FISCAL_1YR_COMP_YEAR_DT, 
FISCAL_1YR_COMP_WEEK_DT,
CALENDAR_1YR_COMP_YEAR_DT,
CALENDAR_1YR_COMP_WEEK_DT,
CALENDAR_2YR_COMP_YEAR_DT,
CALENDAR_2YR_COMP_WEEK_DT,
CALENDAR_3YR_COMP_YEAR_DT,
CALENDAR_3YR_COMP_WEEK_DT,
ROW_NUMBER() OVER (PARTITION BY FISCAL_1YR_COMP_WEEK_DT
                   ORDER BY FISCAL_WEEK_START_DT, FISCAL_1YR_COMP_WEEK_DT ,CALENDAR_1YR_COMP_WEEK_DT ,CALENDAR_2YR_COMP_WEEK_DT ,CALENDAR_3YR_COMP_WEEK_DT) AS ROW_NUM             
from LY_DT
QUALIFY ROW_NUM = 1),
MAIN AS (
    SELECT 
    CR.BRAND_ID,
    CR.STORE_ID,
    DT.FISCAL_YEAR_START_DT,
    DT.FISCAL_1YR_COMP_YEAR_DT,
    DT.CALENDAR_1YR_COMP_YEAR_DT,
    DT.CALENDAR_2YR_COMP_YEAR_DT,
    DT.CALENDAR_3YR_COMP_YEAR_DT,
    SUM(NVL(FISC_1Y.COMP_SALES,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT, DT.FISCAL_1YR_COMP_YEAR_DT) AS FISC_1Y_SALES,
    SUM(NVL(FISC_1Y.COMP_TRANS,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT, DT.FISCAL_1YR_COMP_YEAR_DT) AS FISC_1Y_TRANS,
    SUM(NVL(CAL_1Y.COMP_SALES,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT, DT.CALENDAR_1YR_COMP_YEAR_DT) AS CAL_1Y_SALES,
    SUM(NVL(CAL_1Y.COMP_TRANS,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT, DT.CALENDAR_1YR_COMP_YEAR_DT) AS CAL_1Y_TRANS,
    SUM(NVL(CAL_2Y.COMP_SALES,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT, DT.CALENDAR_2YR_COMP_YEAR_DT) AS CAL_2Y_SALES,
    SUM(NVL(CAL_2Y.COMP_TRANS,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT, DT.CALENDAR_2YR_COMP_YEAR_DT) AS CAL_2Y_TRANS,
    SUM(NVL(CAL_3Y.COMP_SALES,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT, DT.CALENDAR_3YR_COMP_YEAR_DT) AS CAL_3Y_SALES,
    SUM(NVL(CAL_3Y.COMP_TRANS,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT, DT.CALENDAR_3YR_COMP_YEAR_DT) AS CAL_3Y_TRANS,
    ROW_NUMBER() OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT,DT.FISCAL_1YR_COMP_YEAR_DT,DT.CALENDAR_1YR_COMP_YEAR_DT,DT.CALENDAR_2YR_COMP_YEAR_DT,DT.CALENDAR_3YR_COMP_YEAR_DT
                   ORDER BY DT.FISCAL_YEAR_START_DT, DT.FISCAL_1YR_COMP_YEAR_DT ,DT.CALENDAR_1YR_COMP_YEAR_DT ,DT.CALENDAR_2YR_COMP_YEAR_DT ,DT.CALENDAR_3YR_COMP_YEAR_DT) AS ROW_NUM 
    FROM  table(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''CY'', REPORT_BRAND, THRESHOLD_FLAG)) CR
    INNER JOIN IDS_DEV.INT_REF.COMP_CALENDAR dt
    ON dt.CALENDAR_DT = CR.AGG_START_DT
    AND CR.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''FISC1Y'', REPORT_BRAND, THRESHOLD_FLAG))  FISC_1Y
                                          
    ON CR.STORE_ID = FISC_1Y.STORE_ID 
    AND CR.BRAND_ID = FISC_1Y.BRAND_ID
    AND DT.FISCAL_1YR_COMP_WEEK_DT = FISC_1Y.AGG_START_DT
    AND DT.FISCAL_1YR_COMP_YEAR_DT = FISC_1Y.FISCAL_YEAR_START_DT
    AND FISC_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''CAL1Y'', REPORT_BRAND, THRESHOLD_FLAG))  CAL_1Y
     ON CR.STORE_ID = CAL_1Y.STORE_ID 
     AND CR.BRAND_ID = CAL_1Y.BRAND_ID
     AND DT.CALENDAR_1YR_COMP_WEEK_DT = CAL_1Y.AGG_START_DT
     AND DT.CALENDAR_1YR_COMP_YEAR_DT = CAL_1Y.FISCAL_YEAR_START_DT
     AND CAL_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''CAL2Y'', REPORT_BRAND, THRESHOLD_FLAG))  CAL_2Y
     ON CR.STORE_ID = CAL_2Y.STORE_ID 
     AND CR.BRAND_ID = CAL_2Y.BRAND_ID
     AND DT.CALENDAR_2YR_COMP_WEEK_DT = CAL_2Y.AGG_START_DT
     AND DT.CALENDAR_2YR_COMP_YEAR_DT = CAL_2Y.FISCAL_YEAR_START_DT
     AND CAL_2Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,''CAL3Y'', REPORT_BRAND, THRESHOLD_FLAG))  CAL_3Y
     ON CR.STORE_ID = CAL_3Y.STORE_ID 
     AND CR.BRAND_ID = CAL_3Y.BRAND_ID
     AND DT.CALENDAR_3YR_COMP_WEEK_DT = CAL_3Y.AGG_START_DT
     AND DT.CALENDAR_3YR_COMP_YEAR_DT = CAL_3Y.FISCAL_YEAR_START_DT
     AND CAL_3Y.FISCAL_WEEK_NBR !=53
WHERE CR.NET_SALES IS NOT NULL
AND (CR.comp_sales = 0
OR CR.CLOSED_BEFORE_PERIOD_END_FLAG
OR CR.TEMP_CLOSED_FLAG))

SELECT 
BRAND_ID,
STORE_ID,
FISCAL_YEAR_START_DT,
FISCAL_1YR_COMP_YEAR_DT,
CALENDAR_1YR_COMP_YEAR_DT,
CALENDAR_2YR_COMP_YEAR_DT,
CALENDAR_3YR_COMP_YEAR_DT,
FISC_1Y_SALES,
FISC_1Y_TRANS,
CAL_1Y_SALES,
CAL_1Y_TRANS,
CAL_2Y_SALES,
CAL_2Y_TRANS,
CAL_3Y_SALES,
CAL_3Y_TRANS
FROM MAIN
WHERE ROW_NUM = 1

';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_WEEKS_IN_YEARS_F("BUSINESS_DATE" DATE)
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "FISCAL_YEAR_START_DT" DATE, "FISCAL_1YR_COMP_YEAR_DT" DATE, "CALENDAR_1YR_COMP_YEAR_DT" DATE, "CALENDAR_2YR_COMP_YEAR_DT" DATE, "CALENDAR_3YR_COMP_YEAR_DT" DATE, "FISC_1Y_SALES" NUMBER(38,2), "FISC_1Y_TRANS" NUMBER(38,0), "CAL_1Y_SALES" NUMBER(38,2), "CAL_1Y_TRANS" NUMBER(38,0), "CAL_2Y_SALES" NUMBER(38,2), "CAL_2Y_TRANS" NUMBER(38,0), "CAL_3Y_SALES" NUMBER(38,2), "CAL_3Y_TRANS" NUMBER(38,0))
LANGUAGE SQL
AS '

WITH CY_DT AS (
select CALENDAR_DT, 
FISCAL_YEAR_START_DT,
FISCAL_WEEK_START_DT,
FISCAL_1YR_COMP_WEEK_DT,   
CALENDAR_1YR_COMP_WEEK_DT,
CALENDAR_2YR_COMP_WEEK_DT,
CALENDAR_3YR_COMP_WEEK_DT 
from IDS_DEV.INT_REF.COMP_CALENDAR 
where CALENDAR_DT = BUSINESS_DATE
),
LY_DT AS (
SELECT DISTINCT
DT.FISCAL_YEAR_START_DT,
DT.FISCAL_WEEK_START_DT,
DT.FISCAL_1YR_COMP_YEAR_DT, 
DT.FISCAL_1YR_COMP_WEEK_DT,
DT.CALENDAR_1YR_COMP_YEAR_DT,
DT.CALENDAR_1YR_COMP_WEEK_DT,
DT.CALENDAR_2YR_COMP_YEAR_DT,
DT.CALENDAR_2YR_COMP_WEEK_DT,
DT.CALENDAR_3YR_COMP_YEAR_DT,
DT.CALENDAR_3YR_COMP_WEEK_DT
FROM
IDS_DEV.INT_REF.COMP_CALENDAR DT
INNER JOIN CY_DT
ON DT.FISCAL_YEAR_START_DT = CY_DT.FISCAL_YEAR_START_DT
AND DT.FISCAL_WEEK_START_DT <= CY_DT.FISCAL_WEEK_START_DT
AND DT.FISCAL_1YR_COMP_WEEK_DT <= CY_DT.FISCAL_1YR_COMP_WEEK_DT
AND DT.CALENDAR_1YR_COMP_WEEK_DT <= CY_DT.CALENDAR_1YR_COMP_WEEK_DT
AND DT.CALENDAR_2YR_COMP_WEEK_DT <= CY_DT.CALENDAR_2YR_COMP_WEEK_DT
AND DT.CALENDAR_3YR_COMP_WEEK_DT <= CY_DT.CALENDAR_3YR_COMP_WEEK_DT
),
DT AS (
SELECT 
FISCAL_YEAR_START_DT,
FISCAL_WEEK_START_DT,
FISCAL_1YR_COMP_YEAR_DT, 
FISCAL_1YR_COMP_WEEK_DT,
CALENDAR_1YR_COMP_YEAR_DT,
CALENDAR_1YR_COMP_WEEK_DT,
CALENDAR_2YR_COMP_YEAR_DT,
CALENDAR_2YR_COMP_WEEK_DT,
CALENDAR_3YR_COMP_YEAR_DT,
CALENDAR_3YR_COMP_WEEK_DT,
ROW_NUMBER() OVER (PARTITION BY FISCAL_1YR_COMP_WEEK_DT
                   ORDER BY FISCAL_WEEK_START_DT, FISCAL_1YR_COMP_WEEK_DT ,CALENDAR_1YR_COMP_WEEK_DT ,CALENDAR_2YR_COMP_WEEK_DT ,CALENDAR_3YR_COMP_WEEK_DT) AS ROW_NUM             
from LY_DT
QUALIFY ROW_NUM = 1),
MAIN AS (
    SELECT 
    CR.BRAND_ID,
    CR.STORE_ID,
    DT.FISCAL_YEAR_START_DT,
    DT.FISCAL_1YR_COMP_YEAR_DT,
    DT.CALENDAR_1YR_COMP_YEAR_DT,
    DT.CALENDAR_2YR_COMP_YEAR_DT,
    DT.CALENDAR_3YR_COMP_YEAR_DT,
    SUM(NVL(FISC_1Y.COMP_SALES,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT, DT.FISCAL_1YR_COMP_YEAR_DT) AS FISC_1Y_SALES,
    SUM(NVL(FISC_1Y.COMP_TRANS,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT, DT.FISCAL_1YR_COMP_YEAR_DT) AS FISC_1Y_TRANS,
    SUM(NVL(CAL_1Y.COMP_SALES,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT, DT.CALENDAR_1YR_COMP_YEAR_DT) AS CAL_1Y_SALES,
    SUM(NVL(CAL_1Y.COMP_TRANS,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT, DT.CALENDAR_1YR_COMP_YEAR_DT) AS CAL_1Y_TRANS,
    SUM(NVL(CAL_2Y.COMP_SALES,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT, DT.CALENDAR_2YR_COMP_YEAR_DT) AS CAL_2Y_SALES,
    SUM(NVL(CAL_2Y.COMP_TRANS,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT, DT.CALENDAR_2YR_COMP_YEAR_DT) AS CAL_2Y_TRANS,
    SUM(NVL(CAL_3Y.COMP_SALES,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT, DT.CALENDAR_3YR_COMP_YEAR_DT) AS CAL_3Y_SALES,
    SUM(NVL(CAL_3Y.COMP_TRANS,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT, DT.CALENDAR_3YR_COMP_YEAR_DT) AS CAL_3Y_TRANS,
    ROW_NUMBER() OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT,DT.FISCAL_1YR_COMP_YEAR_DT,DT.CALENDAR_1YR_COMP_YEAR_DT,DT.CALENDAR_2YR_COMP_YEAR_DT,DT.CALENDAR_3YR_COMP_YEAR_DT
                   ORDER BY DT.FISCAL_YEAR_START_DT, DT.FISCAL_1YR_COMP_YEAR_DT ,DT.CALENDAR_1YR_COMP_YEAR_DT ,DT.CALENDAR_2YR_COMP_YEAR_DT ,DT.CALENDAR_3YR_COMP_YEAR_DT) AS ROW_NUM 
    FROM  table(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''CY'')) CR
    INNER JOIN IDS_DEV.INT_REF.COMP_CALENDAR dt
    ON dt.CALENDAR_DT = CR.AGG_START_DT
    AND CR.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''FISC1Y''))  FISC_1Y
                                          
    ON CR.STORE_ID = FISC_1Y.STORE_ID 
    AND CR.BRAND_ID = FISC_1Y.BRAND_ID
    AND DT.FISCAL_1YR_COMP_WEEK_DT = FISC_1Y.AGG_START_DT
    AND DT.FISCAL_1YR_COMP_YEAR_DT = FISC_1Y.FISCAL_YEAR_START_DT
    AND FISC_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''CAL1Y''))  CAL_1Y
     ON CR.STORE_ID = CAL_1Y.STORE_ID 
     AND CR.BRAND_ID = CAL_1Y.BRAND_ID
     AND DT.CALENDAR_1YR_COMP_WEEK_DT = CAL_1Y.AGG_START_DT
     AND DT.CALENDAR_1YR_COMP_YEAR_DT = CAL_1Y.FISCAL_YEAR_START_DT
     AND CAL_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''CAL2Y''))  CAL_2Y
     ON CR.STORE_ID = CAL_2Y.STORE_ID 
     AND CR.BRAND_ID = CAL_2Y.BRAND_ID
     AND DT.CALENDAR_2YR_COMP_WEEK_DT = CAL_2Y.AGG_START_DT
     AND DT.CALENDAR_2YR_COMP_YEAR_DT = CAL_2Y.FISCAL_YEAR_START_DT
     AND CAL_2Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''CAL3Y''))  CAL_3Y
     ON CR.STORE_ID = CAL_3Y.STORE_ID 
     AND CR.BRAND_ID = CAL_3Y.BRAND_ID
     AND DT.CALENDAR_3YR_COMP_WEEK_DT = CAL_3Y.AGG_START_DT
     AND DT.CALENDAR_3YR_COMP_YEAR_DT = CAL_3Y.FISCAL_YEAR_START_DT
     AND CAL_3Y.FISCAL_WEEK_NBR !=53
WHERE CR.NET_SALES IS NOT NULL
AND (CR.comp_sales = 0
OR CR.CLOSED_BEFORE_PERIOD_END_FLAG
OR CR.TEMP_CLOSED_FLAG))

SELECT 
BRAND_ID,
STORE_ID,
FISCAL_YEAR_START_DT,
FISCAL_1YR_COMP_YEAR_DT,
CALENDAR_1YR_COMP_YEAR_DT,
CALENDAR_2YR_COMP_YEAR_DT,
CALENDAR_3YR_COMP_YEAR_DT,
FISC_1Y_SALES,
FISC_1Y_TRANS,
CAL_1Y_SALES,
CAL_1Y_TRANS,
CAL_2Y_SALES,
CAL_2Y_TRANS,
CAL_3Y_SALES,
CAL_3Y_TRANS
FROM MAIN
WHERE ROW_NUM = 1

';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_WEEKS_IN_YEARS_F("BUSINESS_DATE" DATE, "BRAND" VARCHAR(16777216), "THRESHOLD_FLG" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "FISCAL_YEAR_START_DT" DATE, "FISCAL_1YR_COMP_YEAR_DT" DATE, "CALENDAR_1YR_COMP_YEAR_DT" DATE, "CALENDAR_2YR_COMP_YEAR_DT" DATE, "CALENDAR_3YR_COMP_YEAR_DT" DATE, "FISC_1Y_SALES" NUMBER(38,2), "FISC_1Y_TRANS" NUMBER(38,0), "CAL_1Y_SALES" NUMBER(38,2), "CAL_1Y_TRANS" NUMBER(38,0), "CAL_2Y_SALES" NUMBER(38,2), "CAL_2Y_TRANS" NUMBER(38,0), "CAL_3Y_SALES" NUMBER(38,2), "CAL_3Y_TRANS" NUMBER(38,0))
LANGUAGE SQL
AS '

WITH CY_DT AS (
select CALENDAR_DT, 
FISCAL_YEAR_START_DT,
FISCAL_WEEK_START_DT,
FISCAL_1YR_COMP_WEEK_DT,   
CALENDAR_1YR_COMP_WEEK_DT,
CALENDAR_2YR_COMP_WEEK_DT,
CALENDAR_3YR_COMP_WEEK_DT 
from IDS_DEV.INT_REF.COMP_CALENDAR 
where CALENDAR_DT = BUSINESS_DATE
),
DT AS (
SELECT DISTINCT
DT.FISCAL_YEAR_START_DT,
DT.FISCAL_WEEK_START_DT,
DT.FISCAL_1YR_COMP_YEAR_DT, 
DT.FISCAL_1YR_COMP_WEEK_DT,
DT.CALENDAR_1YR_COMP_YEAR_DT,
DT.CALENDAR_1YR_COMP_WEEK_DT,
DT.CALENDAR_2YR_COMP_YEAR_DT,
DT.CALENDAR_2YR_COMP_WEEK_DT,
DT.CALENDAR_3YR_COMP_YEAR_DT,
DT.CALENDAR_3YR_COMP_WEEK_DT
FROM
IDS_DEV.INT_REF.COMP_CALENDAR DT
INNER JOIN CY_DT
ON DT.FISCAL_YEAR_START_DT = CY_DT.FISCAL_YEAR_START_DT
AND DT.FISCAL_WEEK_START_DT <= CY_DT.FISCAL_WEEK_START_DT
AND DT.FISCAL_1YR_COMP_WEEK_DT <= CY_DT.FISCAL_1YR_COMP_WEEK_DT
AND DT.CALENDAR_1YR_COMP_WEEK_DT <= CY_DT.CALENDAR_1YR_COMP_WEEK_DT
AND DT.CALENDAR_2YR_COMP_WEEK_DT <= CY_DT.CALENDAR_2YR_COMP_WEEK_DT
AND DT.CALENDAR_3YR_COMP_WEEK_DT <= CY_DT.CALENDAR_3YR_COMP_WEEK_DT
),
MAIN AS (
    SELECT 
    CR.BRAND_ID,
    CR.STORE_ID,
    DT.FISCAL_YEAR_START_DT,
    DT.FISCAL_1YR_COMP_YEAR_DT,
    DT.CALENDAR_1YR_COMP_YEAR_DT,
    DT.CALENDAR_2YR_COMP_YEAR_DT,
    DT.CALENDAR_3YR_COMP_YEAR_DT,
    CASE WHEN (CR.NET_SALES IS NOT NULL AND (CR.comp_sales = 0
    OR CR.CLOSED_BEFORE_PERIOD_END_FLAG
    OR CR.TEMP_CLOSED_FLAG)) THEN TRUE 
    WHEN  DW.STORE_ID IS NOT NULL THEN FALSE 
    ELSE NULL END AS CR_FLG,
    CASE WHEN CR_FLG THEN NVL(FISC_1Y.COMP_SALES,0) ELSE DW.FISC_1Y_SALES END AS FISC_1Y_SALES,
    CASE WHEN CR_FLG THEN NVL(FISC_1Y.COMP_TRANS,0) ELSE DW.FISC_1Y_TRANS END AS FISC_1Y_TRANS,
    CASE WHEN CR_FLG THEN NVL(CAL_1Y.COMP_SALES,0) ELSE DW.CAL_1Y_SALES END AS CAL_1Y_SALES,
    CASE WHEN CR_FLG THEN NVL(CAL_1Y.COMP_TRANS,0) ELSE DW.CAL_1Y_TRANS END AS CAL_1Y_TRANS,
    CASE WHEN CR_FLG THEN NVL(CAL_2Y.COMP_SALES,0) ELSE DW.CAL_2Y_SALES END AS CAL_2Y_SALES,
    CASE WHEN CR_FLG THEN NVL(CAL_2Y.COMP_TRANS,0) ELSE DW.CAL_2Y_TRANS END AS CAL_2Y_TRANS,
    CASE WHEN CR_FLG THEN NVL(CAL_3Y.COMP_SALES,0) ELSE DW.CAL_3Y_SALES END AS CAL_3Y_SALES,
    CASE WHEN CR_FLG THEN NVL(CAL_3Y.COMP_TRANS,0) ELSE DW.CAL_3Y_TRANS END AS CAL_3Y_TRANS
    FROM DT
    INNER JOIN table(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''CY'', BRAND, THRESHOLD_FLG)) CR
    ON dt.FISCAL_WEEK_START_DT = CR.AGG_START_DT
    AND CR.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN TABLE(FLASH_SUMMARY_COMP_WEEKS_TRESHOLD_F(BUSINESS_DATE, BRAND, THRESHOLD_FLG)) DW
    ON CR.STORE_ID = DW.STORE_ID 
    AND CR.BRAND_ID = DW.BRAND_ID
    AND CR.AGG_START_DT = DW.FISCAL_WEEK_START_DT
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''FISC1Y'', BRAND, THRESHOLD_FLG))  FISC_1Y
                                          
    ON CR.STORE_ID = FISC_1Y.STORE_ID 
    AND CR.BRAND_ID = FISC_1Y.BRAND_ID
    AND DT.FISCAL_1YR_COMP_WEEK_DT = FISC_1Y.AGG_START_DT
    AND DT.FISCAL_1YR_COMP_YEAR_DT = FISC_1Y.FISCAL_YEAR_START_DT
    AND FISC_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''CAL1Y'', BRAND, THRESHOLD_FLG))  CAL_1Y
     ON CR.STORE_ID = CAL_1Y.STORE_ID 
     AND CR.BRAND_ID = CAL_1Y.BRAND_ID
     AND DT.CALENDAR_1YR_COMP_WEEK_DT = CAL_1Y.AGG_START_DT
     AND DT.CALENDAR_1YR_COMP_YEAR_DT = CAL_1Y.FISCAL_YEAR_START_DT
     AND CAL_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''CAL2Y'', BRAND, THRESHOLD_FLG))  CAL_2Y
     ON CR.STORE_ID = CAL_2Y.STORE_ID 
     AND CR.BRAND_ID = CAL_2Y.BRAND_ID
     AND DT.CALENDAR_2YR_COMP_WEEK_DT = CAL_2Y.AGG_START_DT
     AND DT.CALENDAR_2YR_COMP_YEAR_DT = CAL_2Y.FISCAL_YEAR_START_DT
     AND CAL_2Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,''CAL3Y'', BRAND, THRESHOLD_FLG))  CAL_3Y
     ON CR.STORE_ID = CAL_3Y.STORE_ID 
     AND CR.BRAND_ID = CAL_3Y.BRAND_ID
     AND DT.CALENDAR_3YR_COMP_WEEK_DT = CAL_3Y.AGG_START_DT
     AND DT.CALENDAR_3YR_COMP_YEAR_DT = CAL_3Y.FISCAL_YEAR_START_DT
     AND CAL_3Y.FISCAL_WEEK_NBR !=53
WHERE (CR.NET_SALES IS NOT NULL
AND (CR.comp_sales = 0
OR CR.CLOSED_BEFORE_PERIOD_END_FLAG
OR CR.TEMP_CLOSED_FLAG))
OR DW.STORE_ID IS NOT NULL)

SELECT 
BRAND_ID,
STORE_ID,
FISCAL_YEAR_START_DT,
FISCAL_1YR_COMP_YEAR_DT,
CALENDAR_1YR_COMP_YEAR_DT,
CALENDAR_2YR_COMP_YEAR_DT,
CALENDAR_3YR_COMP_YEAR_DT,
SUM(FISC_1Y_SALES),
SUM(FISC_1Y_TRANS),
SUM(CAL_1Y_SALES),
SUM(CAL_1Y_TRANS),
SUM(CAL_2Y_SALES),
SUM(CAL_2Y_TRANS),
SUM(CAL_3Y_SALES),
SUM(CAL_3Y_TRANS)
FROM MAIN
GROUP BY 
BRAND_ID,
STORE_ID,
FISCAL_YEAR_START_DT,
FISCAL_1YR_COMP_YEAR_DT,
CALENDAR_1YR_COMP_YEAR_DT,
CALENDAR_2YR_COMP_YEAR_DT,
CALENDAR_3YR_COMP_YEAR_DT
';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_WEEKS_IN_YEARS_WITHOUT_THRESHOLD("BUSINESS_DATE" DATE)
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "FISCAL_YEAR_START_DT" DATE, "FISCAL_1YR_COMP_YEAR_DT" DATE, "CALENDAR_1YR_COMP_YEAR_DT" DATE, "CALENDAR_2YR_COMP_YEAR_DT" DATE, "CALENDAR_3YR_COMP_YEAR_DT" DATE, "FISC_1Y_SALES" NUMBER(38,2), "FISC_1Y_TRANS" NUMBER(38,0), "CAL_1Y_SALES" NUMBER(38,2), "CAL_1Y_TRANS" NUMBER(38,0), "CAL_2Y_SALES" NUMBER(38,2), "CAL_2Y_TRANS" NUMBER(38,0), "CAL_3Y_SALES" NUMBER(38,2), "CAL_3Y_TRANS" NUMBER(38,0))
LANGUAGE SQL
AS '

WITH CY_DT AS (
select CALENDAR_DT, 
FISCAL_YEAR_START_DT,
FISCAL_WEEK_START_DT,
FISCAL_1YR_COMP_WEEK_DT,   
CALENDAR_1YR_COMP_WEEK_DT,
CALENDAR_2YR_COMP_WEEK_DT,
CALENDAR_3YR_COMP_WEEK_DT 
from IDS_DEV.INT_REF.COMP_CALENDAR 
where CALENDAR_DT = BUSINESS_DATE
),
LY_DT AS (
SELECT DISTINCT
DT.FISCAL_YEAR_START_DT,
DT.FISCAL_WEEK_START_DT,
DT.FISCAL_1YR_COMP_YEAR_DT, 
DT.FISCAL_1YR_COMP_WEEK_DT,
DT.CALENDAR_1YR_COMP_YEAR_DT,
DT.CALENDAR_1YR_COMP_WEEK_DT,
DT.CALENDAR_2YR_COMP_YEAR_DT,
DT.CALENDAR_2YR_COMP_WEEK_DT,
DT.CALENDAR_3YR_COMP_YEAR_DT,
DT.CALENDAR_3YR_COMP_WEEK_DT
FROM
IDS_DEV.INT_REF.COMP_CALENDAR DT
INNER JOIN CY_DT
ON DT.FISCAL_YEAR_START_DT = CY_DT.FISCAL_YEAR_START_DT
AND DT.FISCAL_WEEK_START_DT <= CY_DT.FISCAL_WEEK_START_DT
AND DT.FISCAL_1YR_COMP_WEEK_DT <= CY_DT.FISCAL_1YR_COMP_WEEK_DT
AND DT.CALENDAR_1YR_COMP_WEEK_DT <= CY_DT.CALENDAR_1YR_COMP_WEEK_DT
AND DT.CALENDAR_2YR_COMP_WEEK_DT <= CY_DT.CALENDAR_2YR_COMP_WEEK_DT
AND DT.CALENDAR_3YR_COMP_WEEK_DT <= CY_DT.CALENDAR_3YR_COMP_WEEK_DT
),
DT AS (
SELECT 
FISCAL_YEAR_START_DT,
FISCAL_WEEK_START_DT,
FISCAL_1YR_COMP_YEAR_DT, 
FISCAL_1YR_COMP_WEEK_DT,
CALENDAR_1YR_COMP_YEAR_DT,
CALENDAR_1YR_COMP_WEEK_DT,
CALENDAR_2YR_COMP_YEAR_DT,
CALENDAR_2YR_COMP_WEEK_DT,
CALENDAR_3YR_COMP_YEAR_DT,
CALENDAR_3YR_COMP_WEEK_DT,
ROW_NUMBER() OVER (PARTITION BY FISCAL_1YR_COMP_WEEK_DT
                   ORDER BY FISCAL_WEEK_START_DT, FISCAL_1YR_COMP_WEEK_DT ,CALENDAR_1YR_COMP_WEEK_DT ,CALENDAR_2YR_COMP_WEEK_DT ,CALENDAR_3YR_COMP_WEEK_DT) AS ROW_NUM             
from LY_DT
QUALIFY ROW_NUM = 1),
MAIN AS (
    SELECT 
    CR.BRAND_ID,
    CR.STORE_ID,
    DT.FISCAL_YEAR_START_DT,
    DT.FISCAL_1YR_COMP_YEAR_DT,
    DT.CALENDAR_1YR_COMP_YEAR_DT,
    DT.CALENDAR_2YR_COMP_YEAR_DT,
    DT.CALENDAR_3YR_COMP_YEAR_DT,
    SUM(NVL(FISC_1Y.COMP_SALES,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT, DT.FISCAL_1YR_COMP_YEAR_DT) AS FISC_1Y_SALES,
    SUM(NVL(FISC_1Y.COMP_TRANS,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT, DT.FISCAL_1YR_COMP_YEAR_DT) AS FISC_1Y_TRANS,
    SUM(NVL(CAL_1Y.COMP_SALES,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT, DT.CALENDAR_1YR_COMP_YEAR_DT) AS CAL_1Y_SALES,
    SUM(NVL(CAL_1Y.COMP_TRANS,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT, DT.CALENDAR_1YR_COMP_YEAR_DT) AS CAL_1Y_TRANS,
    SUM(NVL(CAL_2Y.COMP_SALES,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT, DT.CALENDAR_2YR_COMP_YEAR_DT) AS CAL_2Y_SALES,
    SUM(NVL(CAL_2Y.COMP_TRANS,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT, DT.CALENDAR_2YR_COMP_YEAR_DT) AS CAL_2Y_TRANS,
    SUM(NVL(CAL_3Y.COMP_SALES,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT, DT.CALENDAR_3YR_COMP_YEAR_DT) AS CAL_3Y_SALES,
    SUM(NVL(CAL_3Y.COMP_TRANS,0)) OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT, DT.CALENDAR_3YR_COMP_YEAR_DT) AS CAL_3Y_TRANS,
    ROW_NUMBER() OVER (PARTITION BY CR.BRAND_ID, CR.STORE_ID, DT.FISCAL_YEAR_START_DT,DT.FISCAL_1YR_COMP_YEAR_DT,DT.CALENDAR_1YR_COMP_YEAR_DT,DT.CALENDAR_2YR_COMP_YEAR_DT,DT.CALENDAR_3YR_COMP_YEAR_DT
                   ORDER BY DT.FISCAL_YEAR_START_DT, DT.FISCAL_1YR_COMP_YEAR_DT ,DT.CALENDAR_1YR_COMP_YEAR_DT ,DT.CALENDAR_2YR_COMP_YEAR_DT ,DT.CALENDAR_3YR_COMP_YEAR_DT) AS ROW_NUM 
    FROM  table(FLASH_SUMMARY_COMP_PAST_WEEKS_without_threshold(BUSINESS_DATE,''CY'')) CR
    INNER JOIN IDS_DEV.INT_REF.COMP_CALENDAR dt
    ON dt.CALENDAR_DT = CR.AGG_START_DT
    AND CR.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_without_threshold(BUSINESS_DATE,''FISC1Y''))  FISC_1Y
                                          
    ON CR.STORE_ID = FISC_1Y.STORE_ID 
    AND CR.BRAND_ID = FISC_1Y.BRAND_ID
    AND DT.FISCAL_1YR_COMP_WEEK_DT = FISC_1Y.AGG_START_DT
    AND DT.FISCAL_1YR_COMP_YEAR_DT = FISC_1Y.FISCAL_YEAR_START_DT
    AND FISC_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_without_threshold(BUSINESS_DATE,''CAL1Y''))  CAL_1Y
     ON CR.STORE_ID = CAL_1Y.STORE_ID 
     AND CR.BRAND_ID = CAL_1Y.BRAND_ID
     AND DT.CALENDAR_1YR_COMP_WEEK_DT = CAL_1Y.AGG_START_DT
     AND DT.CALENDAR_1YR_COMP_YEAR_DT = CAL_1Y.FISCAL_YEAR_START_DT
     AND CAL_1Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_without_threshold(BUSINESS_DATE,''CAL2Y''))  CAL_2Y
     ON CR.STORE_ID = CAL_2Y.STORE_ID 
     AND CR.BRAND_ID = CAL_2Y.BRAND_ID
     AND DT.CALENDAR_2YR_COMP_WEEK_DT = CAL_2Y.AGG_START_DT
     AND DT.CALENDAR_2YR_COMP_YEAR_DT = CAL_2Y.FISCAL_YEAR_START_DT
     AND CAL_2Y.FISCAL_WEEK_NBR !=53
    LEFT OUTER JOIN 
   TABLE(FLASH_SUMMARY_COMP_PAST_WEEKS_without_threshold(BUSINESS_DATE,''CAL3Y''))  CAL_3Y
     ON CR.STORE_ID = CAL_3Y.STORE_ID 
     AND CR.BRAND_ID = CAL_3Y.BRAND_ID
     AND DT.CALENDAR_3YR_COMP_WEEK_DT = CAL_3Y.AGG_START_DT
     AND DT.CALENDAR_3YR_COMP_YEAR_DT = CAL_3Y.FISCAL_YEAR_START_DT
     AND CAL_3Y.FISCAL_WEEK_NBR !=53
WHERE CR.NET_SALES IS NOT NULL
AND (CR.comp_sales = 0
OR CR.CLOSED_BEFORE_PERIOD_END_FLAG
OR CR.TEMP_CLOSED_FLAG))

SELECT 
BRAND_ID,
STORE_ID,
FISCAL_YEAR_START_DT,
FISCAL_1YR_COMP_YEAR_DT,
CALENDAR_1YR_COMP_YEAR_DT,
CALENDAR_2YR_COMP_YEAR_DT,
CALENDAR_3YR_COMP_YEAR_DT,
FISC_1Y_SALES,
FISC_1Y_TRANS,
CAL_1Y_SALES,
CAL_1Y_TRANS,
CAL_2Y_SALES,
CAL_2Y_TRANS,
CAL_3Y_SALES,
CAL_3Y_TRANS
FROM MAIN
WHERE ROW_NUM = 1

';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_WEEKS_TRESHOLD("BUSINESS_DATE" DATE)
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "THRESHOLD_FLAG" BOOLEAN, "FISCAL_WEEK_START_DT" DATE, "FISCAL_PERIOD_START_DT" DATE, "FISCAL_QUARTER_START_DT" DATE, "FISCAL_YEAR_START_DT" DATE, "FISCAL_1YR_COMP_WEEK_DT" DATE, "FISCAL_1YR_COMP_PERIOD_DT" DATE, "FISCAL_1YR_COMP_QUARTER_DT" DATE, "FISCAL_1YR_COMP_YEAR_DT" DATE, "FISC_1Y_SALES" NUMBER(38,2), "FISC_1Y_TRANS" NUMBER(38,0), "CALENDAR_1YR_COMP_WEEK_DT" DATE, "CALENDAR_1YR_COMP_PERIOD_DT" DATE, "CALENDAR_1YR_COMP_QUARTER_DT" DATE, "CALENDAR_1YR_COMP_YEAR_DT" DATE, "CAL_1Y_SALES" NUMBER(38,2), "CAL_1Y_TRANS" NUMBER(38,0), "CALENDAR_2YR_COMP_WEEK_DT" DATE, "CALENDAR_2YR_COMP_PERIOD_DT" DATE, "CALENDAR_2YR_COMP_QUARTER_DT" DATE, "CALENDAR_2YR_COMP_YEAR_DT" DATE, "CAL_2Y_SALES" NUMBER(38,2), "CAL_2Y_TRANS" NUMBER(38,0), "CALENDAR_3YR_COMP_WEEK_DT" DATE, "CALENDAR_3YR_COMP_PERIOD_DT" DATE, "CALENDAR_3YR_COMP_QUARTER_DT" DATE, "CALENDAR_3YR_COMP_YEAR_DT" DATE, "CAL_3Y_SALES" NUMBER(38,2), "CAL_3Y_TRANS" NUMBER(38,0))
LANGUAGE SQL
AS '

    WITH CY_DT AS (
    SELECT CALENDAR_DT, 
    FISCAL_YEAR_START_DT,
    FISCAL_WEEK_START_DT,
    FISCAL_1YR_COMP_WEEK_DT,   
    CALENDAR_1YR_COMP_WEEK_DT,
    CALENDAR_2YR_COMP_WEEK_DT,
    CALENDAR_3YR_COMP_WEEK_DT 
    FROM IDS_DEV.INT_REF.COMP_CALENDAR 
    WHERE CALENDAR_DT = BUSINESS_DATE
    ),
    DT AS (
    SELECT DISTINCT
    DT.FISCAL_WEEK_START_DT,
    DT.FISCAL_1YR_COMP_WEEK_DT,
    DT.CALENDAR_1YR_COMP_WEEK_DT,
    DT.CALENDAR_2YR_COMP_WEEK_DT,
    DT.CALENDAR_3YR_COMP_WEEK_DT
    FROM
    IDS_DEV.INT_REF.COMP_CALENDAR DT
    INNER JOIN CY_DT
    ON DT.FISCAL_YEAR_START_DT = CY_DT.FISCAL_YEAR_START_DT
    AND DT.FISCAL_WEEK_START_DT <= CY_DT.FISCAL_WEEK_START_DT
    AND DT.FISCAL_1YR_COMP_WEEK_DT <= CY_DT.FISCAL_1YR_COMP_WEEK_DT
    AND DT.CALENDAR_1YR_COMP_WEEK_DT <= CY_DT.CALENDAR_1YR_COMP_WEEK_DT
    AND DT.CALENDAR_2YR_COMP_WEEK_DT <= CY_DT.CALENDAR_2YR_COMP_WEEK_DT
    AND DT.CALENDAR_3YR_COMP_WEEK_DT <= CY_DT.CALENDAR_3YR_COMP_WEEK_DT
    )
    SELECT CY.BRAND_ID, CY.STORE_ID, CY.THRESHOLD_FLAG, CY.FISCAL_WEEK_START_DT, CY.FISCAL_PERIOD_START_DT, CY.FISCAL_QUARTER_START_DT, CY.FISCAL_YEAR_START_DT,
    FISC1Y.FISCAL_WEEK_START_DT, FISC1Y.FISCAL_PERIOD_START_DT, FISC1Y.FISCAL_QUARTER_START_DT, FISC1Y.FISCAL_YEAR_START_DT,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, FISC1Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(FISC1Y.WEEK_NET_SALES, CY.WEEK_NET_SALES, CY.WEEKDAY_OFFSET, FISC1Y.WEEKDAY_OFFSET) END as Fisc1y_Sales,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, FISC1Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(FISC1Y.WEEK_TRANS_CNTS, CY.WEEK_TRANS_CNTS, CY.WEEKDAY_OFFSET, FISC1Y.WEEKDAY_OFFSET) END as Fisc1y_Trans,
    CAL1Y.FISCAL_WEEK_START_DT, CAL1Y.FISCAL_PERIOD_START_DT, CAL1Y.FISCAL_QUARTER_START_DT, CAL1Y.FISCAL_YEAR_START_DT,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, CAL1Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(CAL1Y.WEEK_NET_SALES, CY.WEEK_NET_SALES, CY.WEEKDAY_OFFSET, CAL1Y.WEEKDAY_OFFSET) END as Cal1y_Sales,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, CAL1Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(CAL1Y.WEEK_TRANS_CNTS, CY.WEEK_TRANS_CNTS, CY.WEEKDAY_OFFSET, CAL1Y.WEEKDAY_OFFSET) END as Cal1y_Trans,
    CAL2Y.FISCAL_WEEK_START_DT, CAL2Y.FISCAL_PERIOD_START_DT, CAL2Y.FISCAL_QUARTER_START_DT, CAL2Y.FISCAL_YEAR_START_DT,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, CAL2Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(CAL2Y.WEEK_NET_SALES, CY.WEEK_NET_SALES, CY.WEEKDAY_OFFSET, CAL2Y.WEEKDAY_OFFSET) END as Cal2y_Sales,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, CAL2Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(CAL2Y.WEEK_TRANS_CNTS, CY.WEEK_TRANS_CNTS, CY.WEEKDAY_OFFSET, CAL2Y.WEEKDAY_OFFSET) END as Cal2y_Trans,
    CAL3Y.FISCAL_WEEK_START_DT, CAL3Y.FISCAL_PERIOD_START_DT, CAL3Y.FISCAL_QUARTER_START_DT, CAL3Y.FISCAL_YEAR_START_DT,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, CAL3Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(CAL3Y.WEEK_NET_SALES, CY.WEEK_NET_SALES, CY.WEEKDAY_OFFSET, CAL3Y.WEEKDAY_OFFSET) END as Cal3y_Sales,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, CAL3Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(CAL3Y.WEEK_TRANS_CNTS, CY.WEEK_TRANS_CNTS, CY.WEEKDAY_OFFSET, CAL3Y.WEEKDAY_OFFSET) END as Cal3y_Trans
    FROM DT
    INNER JOIN table(FLASH_SUMMARY_COMP_PAST_DAYS(BUSINESS_DATE, ''CY'')) CY
    ON DT.FISCAL_WEEK_START_DT = CY.FISCAL_WEEK_START_DT
    LEFT OUTER JOIN table(FLASH_SUMMARY_COMP_PAST_DAYS(BUSINESS_DATE, ''FISC1Y'')) FISC1Y
    ON CY.BRAND_ID = FISC1Y.BRAND_ID
    AND CY.STORE_ID = FISC1Y.STORE_ID
    AND DT.FISCAL_1YR_COMP_WEEK_DT = FISC1Y.FISCAL_WEEK_START_DT
    LEFT OUTER JOIN table(FLASH_SUMMARY_COMP_PAST_DAYS(BUSINESS_DATE, ''CAL1Y'')) CAL1Y
    ON CY.BRAND_ID = CAL1Y.BRAND_ID
    AND CY.STORE_ID = CAL1Y.STORE_ID
    AND DT.CALENDAR_1YR_COMP_WEEK_DT = CAL1Y.FISCAL_WEEK_START_DT
    LEFT OUTER JOIN table(FLASH_SUMMARY_COMP_PAST_DAYS(BUSINESS_DATE, ''CAL2Y'')) CAL2Y
    ON CY.BRAND_ID = CAL2Y.BRAND_ID
    AND CY.STORE_ID = CAL2Y.STORE_ID
    AND DT.CALENDAR_2YR_COMP_WEEK_DT = CAL2Y.FISCAL_WEEK_START_DT
    LEFT OUTER JOIN table(FLASH_SUMMARY_COMP_PAST_DAYS(BUSINESS_DATE, ''CAL3Y'')) CAL3Y
    ON CY.BRAND_ID = CAL3Y.BRAND_ID
    AND CY.STORE_ID = CAL3Y.STORE_ID
    AND DT.CALENDAR_3YR_COMP_WEEK_DT = CAL3Y.FISCAL_WEEK_START_DT
    WHERE NOT CY.THRESHOLD_FLAG 

';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_WEEKS_TRESHOLD("BUSINESS_DATE" DATE, "BRAND" VARCHAR(16777216), "THRESHOLD_FLG" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "THRESHOLD_FLAG" BOOLEAN, "FISCAL_WEEK_START_DT" DATE, "FISCAL_PERIOD_START_DT" DATE, "FISCAL_QUARTER_START_DT" DATE, "FISCAL_YEAR_START_DT" DATE, "FISCAL_1YR_COMP_WEEK_DT" DATE, "FISCAL_1YR_COMP_PERIOD_DT" DATE, "FISCAL_1YR_COMP_QUARTER_DT" DATE, "FISCAL_1YR_COMP_YEAR_DT" DATE, "FISC_1Y_SALES" NUMBER(38,2), "FISC_1Y_TRANS" NUMBER(38,0), "CALENDAR_1YR_COMP_WEEK_DT" DATE, "CALENDAR_1YR_COMP_PERIOD_DT" DATE, "CALENDAR_1YR_COMP_QUARTER_DT" DATE, "CALENDAR_1YR_COMP_YEAR_DT" DATE, "CAL_1Y_SALES" NUMBER(38,2), "CAL_1Y_TRANS" NUMBER(38,0), "CALENDAR_2YR_COMP_WEEK_DT" DATE, "CALENDAR_2YR_COMP_PERIOD_DT" DATE, "CALENDAR_2YR_COMP_QUARTER_DT" DATE, "CALENDAR_2YR_COMP_YEAR_DT" DATE, "CAL_2Y_SALES" NUMBER(38,2), "CAL_2Y_TRANS" NUMBER(38,0), "CALENDAR_3YR_COMP_WEEK_DT" DATE, "CALENDAR_3YR_COMP_PERIOD_DT" DATE, "CALENDAR_3YR_COMP_QUARTER_DT" DATE, "CALENDAR_3YR_COMP_YEAR_DT" DATE, "CAL_3Y_SALES" NUMBER(38,2), "CAL_3Y_TRANS" NUMBER(38,0))
LANGUAGE SQL
AS '

    SELECT CY.BRAND_ID, CY.STORE_ID, CY.THRESHOLD_FLAG, CY.FISCAL_WEEK_START_DT, CY.FISCAL_PERIOD_START_DT, CY.FISCAL_QUARTER_START_DT, CY.FISCAL_YEAR_START_DT,
    FISC1Y.FISCAL_WEEK_START_DT, FISC1Y.FISCAL_PERIOD_START_DT, FISC1Y.FISCAL_QUARTER_START_DT, FISC1Y.FISCAL_YEAR_START_DT,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, FISC1Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(FISC1Y.WEEK_NET_SALES, CY.WEEK_NET_SALES, CY.WEEKDAY_OFFSET, FISC1Y.WEEKDAY_OFFSET) END as Fisc1y_Sales,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, FISC1Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(FISC1Y.WEEK_TRANS_CNTS, CY.WEEK_TRANS_CNTS, CY.WEEKDAY_OFFSET, FISC1Y.WEEKDAY_OFFSET) END as Fisc1y_Trans,
    CAL1Y.FISCAL_WEEK_START_DT, CAL1Y.FISCAL_PERIOD_START_DT, CAL1Y.FISCAL_QUARTER_START_DT, CAL1Y.FISCAL_YEAR_START_DT,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, CAL1Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(CAL1Y.WEEK_NET_SALES, CY.WEEK_NET_SALES, CY.WEEKDAY_OFFSET, CAL1Y.WEEKDAY_OFFSET) END as Cal1y_Sales,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, CAL1Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(CAL1Y.WEEK_TRANS_CNTS, CY.WEEK_TRANS_CNTS, CY.WEEKDAY_OFFSET, CAL1Y.WEEKDAY_OFFSET) END as Cal1y_Trans,
    CAL2Y.FISCAL_WEEK_START_DT, CAL2Y.FISCAL_PERIOD_START_DT, CAL2Y.FISCAL_QUARTER_START_DT, CAL2Y.FISCAL_YEAR_START_DT,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, CAL2Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(CAL2Y.WEEK_NET_SALES, CY.WEEK_NET_SALES, CY.WEEKDAY_OFFSET, CAL2Y.WEEKDAY_OFFSET) END as Cal2y_Sales,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, CAL2Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(CAL2Y.WEEK_TRANS_CNTS, CY.WEEK_TRANS_CNTS, CY.WEEKDAY_OFFSET, CAL2Y.WEEKDAY_OFFSET) END as Cal2y_Trans,
    CAL3Y.FISCAL_WEEK_START_DT, CAL3Y.FISCAL_PERIOD_START_DT, CAL3Y.FISCAL_QUARTER_START_DT, CAL3Y.FISCAL_YEAR_START_DT,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, CAL3Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(CAL3Y.WEEK_NET_SALES, CY.WEEK_NET_SALES, CY.WEEKDAY_OFFSET, CAL3Y.WEEKDAY_OFFSET) END as Cal3y_Sales,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, CAL3Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(CAL3Y.WEEK_TRANS_CNTS, CY.WEEK_TRANS_CNTS, CY.WEEKDAY_OFFSET, CAL3Y.WEEKDAY_OFFSET) END as Cal3y_Trans
    from 
    table(FLASH_SUMMARY_COMP_PAST_DAYS_F(BUSINESS_DATE, ''CY'', BRAND, THRESHOLD_FLG)) CY
    LEFT OUTER JOIN table(FLASH_SUMMARY_COMP_PAST_DAYS_F(BUSINESS_DATE, ''FISC1Y'', BRAND, THRESHOLD_FLG)) FISC1Y
    ON CY.BRAND_ID = FISC1Y.BRAND_ID
    AND CY.STORE_ID = FISC1Y.STORE_ID
    AND CY.FISCAL_WEEK_NBR = FISC1Y.FISCAL_WEEK_NBR
    LEFT OUTER JOIN table(FLASH_SUMMARY_COMP_PAST_DAYS_F(BUSINESS_DATE, ''CAL1Y'', BRAND, THRESHOLD_FLG)) CAL1Y
    ON CY.BRAND_ID = CAL1Y.BRAND_ID
    AND CY.STORE_ID = CAL1Y.STORE_ID
    AND CY.FISCAL_WEEK_NBR = CAL1Y.FISCAL_WEEK_NBR
    LEFT OUTER JOIN table(FLASH_SUMMARY_COMP_PAST_DAYS_F(BUSINESS_DATE, ''CAL2Y'', BRAND, THRESHOLD_FLG)) CAL2Y
    ON CY.BRAND_ID = CAL2Y.BRAND_ID
    AND CY.STORE_ID = CAL2Y.STORE_ID
    AND CY.FISCAL_WEEK_NBR = CAL2Y.FISCAL_WEEK_NBR
    LEFT OUTER JOIN table(FLASH_SUMMARY_COMP_PAST_DAYS_F(BUSINESS_DATE, ''CAL3Y'', BRAND, THRESHOLD_FLG)) CAL3Y
    ON CY.BRAND_ID = CAL3Y.BRAND_ID
    AND CY.STORE_ID = CAL3Y.STORE_ID
    AND CY.FISCAL_WEEK_NBR = CAL3Y.FISCAL_WEEK_NBR
    WHERE NOT CY.THRESHOLD_FLAG 

';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_COMP_WEEKS_TRESHOLD_F("BUSINESS_DATE" DATE, "BRAND" VARCHAR(16777216), "THRESHOLD_FLG" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "THRESHOLD_FLAG" BOOLEAN, "FISCAL_WEEK_START_DT" DATE, "FISCAL_PERIOD_START_DT" DATE, "FISCAL_QUARTER_START_DT" DATE, "FISCAL_YEAR_START_DT" DATE, "FISCAL_1YR_COMP_WEEK_DT" DATE, "FISCAL_1YR_COMP_PERIOD_DT" DATE, "FISCAL_1YR_COMP_QUARTER_DT" DATE, "FISCAL_1YR_COMP_YEAR_DT" DATE, "FISC_1Y_SALES" NUMBER(38,2), "FISC_1Y_TRANS" NUMBER(38,0), "CALENDAR_1YR_COMP_WEEK_DT" DATE, "CALENDAR_1YR_COMP_PERIOD_DT" DATE, "CALENDAR_1YR_COMP_QUARTER_DT" DATE, "CALENDAR_1YR_COMP_YEAR_DT" DATE, "CAL_1Y_SALES" NUMBER(38,2), "CAL_1Y_TRANS" NUMBER(38,0), "CALENDAR_2YR_COMP_WEEK_DT" DATE, "CALENDAR_2YR_COMP_PERIOD_DT" DATE, "CALENDAR_2YR_COMP_QUARTER_DT" DATE, "CALENDAR_2YR_COMP_YEAR_DT" DATE, "CAL_2Y_SALES" NUMBER(38,2), "CAL_2Y_TRANS" NUMBER(38,0), "CALENDAR_3YR_COMP_WEEK_DT" DATE, "CALENDAR_3YR_COMP_PERIOD_DT" DATE, "CALENDAR_3YR_COMP_QUARTER_DT" DATE, "CALENDAR_3YR_COMP_YEAR_DT" DATE, "CAL_3Y_SALES" NUMBER(38,2), "CAL_3Y_TRANS" NUMBER(38,0))
LANGUAGE SQL
AS '

    SELECT CY.BRAND_ID, CY.STORE_ID, CY.THRESHOLD_FLAG, CY.FISCAL_WEEK_START_DT, CY.FISCAL_PERIOD_START_DT, CY.FISCAL_QUARTER_START_DT, CY.FISCAL_YEAR_START_DT,
    FISC1Y.FISCAL_WEEK_START_DT, FISC1Y.FISCAL_PERIOD_START_DT, FISC1Y.FISCAL_QUARTER_START_DT, FISC1Y.FISCAL_YEAR_START_DT,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, FISC1Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(FISC1Y.WEEK_NET_SALES, CY.WEEK_NET_SALES, CY.WEEKDAY_OFFSET, FISC1Y.WEEKDAY_OFFSET) END as Fisc1y_Sales,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, FISC1Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(FISC1Y.WEEK_TRANS_CNTS, CY.WEEK_TRANS_CNTS, CY.WEEKDAY_OFFSET, FISC1Y.WEEKDAY_OFFSET) END as Fisc1y_Trans,
    CAL1Y.FISCAL_WEEK_START_DT, CAL1Y.FISCAL_PERIOD_START_DT, CAL1Y.FISCAL_QUARTER_START_DT, CAL1Y.FISCAL_YEAR_START_DT,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, CAL1Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(CAL1Y.WEEK_NET_SALES, CY.WEEK_NET_SALES, CY.WEEKDAY_OFFSET, CAL1Y.WEEKDAY_OFFSET) END as Cal1y_Sales,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, CAL1Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(CAL1Y.WEEK_TRANS_CNTS, CY.WEEK_TRANS_CNTS, CY.WEEKDAY_OFFSET, CAL1Y.WEEKDAY_OFFSET) END as Cal1y_Trans,
    CAL2Y.FISCAL_WEEK_START_DT, CAL2Y.FISCAL_PERIOD_START_DT, CAL2Y.FISCAL_QUARTER_START_DT, CAL2Y.FISCAL_YEAR_START_DT,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, CAL2Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(CAL2Y.WEEK_NET_SALES, CY.WEEK_NET_SALES, CY.WEEKDAY_OFFSET, CAL2Y.WEEKDAY_OFFSET) END as Cal2y_Sales,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, CAL2Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(CAL2Y.WEEK_TRANS_CNTS, CY.WEEK_TRANS_CNTS, CY.WEEKDAY_OFFSET, CAL2Y.WEEKDAY_OFFSET) END as Cal2y_Trans,
    CAL3Y.FISCAL_WEEK_START_DT, CAL3Y.FISCAL_PERIOD_START_DT, CAL3Y.FISCAL_QUARTER_START_DT, CAL3Y.FISCAL_YEAR_START_DT,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, CAL3Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(CAL3Y.WEEK_NET_SALES, CY.WEEK_NET_SALES, CY.WEEKDAY_OFFSET, CAL3Y.WEEKDAY_OFFSET) END as Cal3y_Sales,
    CASE WHEN ARRAY_INTERSECTION(CY.WEEKDAY_OFFSET, CAL3Y.WEEKDAY_OFFSET) IS NOT NULL
    THEN 
    EXCLUDE_FROM_ARRAY(CAL3Y.WEEK_TRANS_CNTS, CY.WEEK_TRANS_CNTS, CY.WEEKDAY_OFFSET, CAL3Y.WEEKDAY_OFFSET) END as Cal3y_Trans
    from 
    table(FLASH_SUMMARY_COMP_PAST_DAYS_F(BUSINESS_DATE, ''CY'', BRAND, THRESHOLD_FLG)) CY
    LEFT OUTER JOIN table(FLASH_SUMMARY_COMP_PAST_DAYS_F(BUSINESS_DATE, ''FISC1Y'', BRAND, THRESHOLD_FLG)) FISC1Y
    ON CY.BRAND_ID = FISC1Y.BRAND_ID
    AND CY.STORE_ID = FISC1Y.STORE_ID
    AND CY.FISCAL_WEEK_NBR = FISC1Y.FISCAL_WEEK_NBR
    LEFT OUTER JOIN table(FLASH_SUMMARY_COMP_PAST_DAYS_F(BUSINESS_DATE, ''CAL1Y'', BRAND, THRESHOLD_FLG)) CAL1Y
    ON CY.BRAND_ID = CAL1Y.BRAND_ID
    AND CY.STORE_ID = CAL1Y.STORE_ID
    AND CY.FISCAL_WEEK_NBR = CAL1Y.FISCAL_WEEK_NBR
    LEFT OUTER JOIN table(FLASH_SUMMARY_COMP_PAST_DAYS_F(BUSINESS_DATE, ''CAL2Y'', BRAND, THRESHOLD_FLG)) CAL2Y
    ON CY.BRAND_ID = CAL2Y.BRAND_ID
    AND CY.STORE_ID = CAL2Y.STORE_ID
    AND CY.FISCAL_WEEK_NBR = CAL2Y.FISCAL_WEEK_NBR
    LEFT OUTER JOIN table(FLASH_SUMMARY_COMP_PAST_DAYS_F(BUSINESS_DATE, ''CAL3Y'', BRAND, THRESHOLD_FLG)) CAL3Y
    ON CY.BRAND_ID = CAL3Y.BRAND_ID
    AND CY.STORE_ID = CAL3Y.STORE_ID
    AND CY.FISCAL_WEEK_NBR = CAL3Y.FISCAL_WEEK_NBR
    WHERE NOT CY.THRESHOLD_FLAG 

';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_NO_COMP_CALENDAR("BUSINESS_DATE" DATE)
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BUSINESS_DT" DATE, "CY_NET_TRANS_CNT_DAY" NUMBER(38,0), "CY_NET_SALES_DAY" NUMBER(38,0), "CY_COMP_TRANS_CNT_DAY" NUMBER(38,0), "CY_CAL_COMP_SALES_DAY" NUMBER(38,0), "AGG_START_DT" DATE, "AGG_LEVEL" VARCHAR(16777216), "CY_COMP_ELIGIBLE_DAY" VARCHAR(16777216), "DMA_NAME" VARCHAR(16777216), "OWNERSHIP_TYPE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216))
LANGUAGE SQL
AS '

WITH COMP_DATE AS 
(
SELECT  
    BUSINESS_DATE AS calendar_dt  -- comparison date
FROM 
    dual
)
--CDTD AS   --ODI-2289 + ODI-906
 
SELECT 
    BRAND_ID
    , STORE_ID
    , BUSINESS_DT
    , SUM(CY_Net_Trans_Cnt_Day)
    , SUM(CY_Net_Sales_Day)
    , SUM(CY_Net_Trans_Cnt_Day) as CY_Comp_Trans_Cnt_Day
    , SUM(CY_Net_Sales_Day) as CY_Cal_Comp_Sales_Day
    , BUSINESS_DT as AGG_START_DT
    , ''DY'' AS AGG_LEVEL
    , CY_Comp_Eligible_Day
    , DMA_NAME 
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , L1Name
    , L2Name
    , L3Name
    , L4Name
    , L5Name
FROM 
    DAILY_FLASH_SALES_V
INNER JOIN 
    COMP_DATE 
ON  DAILY_FLASH_SALES_V.BUSINESS_DT BETWEEN COMP_DATE.CALENDAR_DT -9 AND COMP_DATE.CALENDAR_DT
GROUP BY    
      BRAND_ID
    , STORE_ID
    , BUSINESS_DT
    , ''DY'' 
    , CY_Comp_Eligible_Day
    , DMA_NAME 
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , COMP_DATE.CALENDAR_DT
    , L1Name
    , L2Name
    , L3Name
    , L4Name
    , L5Name

UNION 

--ODI-2233

SELECT 
      SLS.BRAND_ID
    , STORE_ID
    , COMP_DATE.CALENDAR_DT 
    , SUM(CY_Net_Trans_Cnt_Day)
    , SUM(CY_Net_Sales_Day)
    , SUM(CY_Net_Trans_Cnt_Day) as CY_Comp_Trans_Cnt_Day
    , SUM(CY_Net_Sales_Day) as CY_Cal_Comp_Sales_Day
    , CALENDAR_YEAR_START_DT AGG_START_DT
    , ''YTD'' AS Agg_Level
    , CY_Comp_Eligible_Day
    , DMA_NAME 
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , L1Name
    , L2Name
    , L3Name
    , L4Name
    , L5Name
FROM 
    DAILY_FLASH_SALES_V SLS
INNER JOIN 
    COMP_DATE
ON  SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN 
    IDS_DEV.DATASTORE.DATE_DIM DT
ON  COMP_DATE.CALENDAR_DT = DT.CALENDAR_DT
WHERE 
    SLS.BUSINESS_DT >= DT.CALENDAR_YEAR_START_DT
GROUP BY    
      SLS.BRAND_ID
    , STORE_ID
    , COMP_DATE.CALENDAR_DT
    , ''YTD'' 
    , CY_Comp_Eligible_Day
    , DMA_NAME 
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , CALENDAR_YEAR_START_DT
    , L1Name
    , L2Name
    , L3Name
    , L4Name
    , L5Name

UNION 

--ODI-2178

SELECT    
    SLS.BRAND_ID
    , STORE_ID
    , COMP_DATE.CALENDAR_DT 
    , SUM(CY_Net_Trans_Cnt_Day)
    , SUM(CY_Net_Sales_Day)
    , SUM(CY_Net_Trans_Cnt_Day) as CY_Comp_Trans_Cnt_Day
    , SUM(CY_Net_Sales_Day) as CY_Cal_Comp_Sales_Day
    , CALENDAR_QUARTER_START_DT AGG_START_DT
    , ''QTD'' AS Agg_Level
    , CY_Comp_Eligible_Day
    , DMA_NAME 
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , L1Name
    , L2Name
    , L3Name
    , L4Name
    , L5Name
FROM 
    DAILY_FLASH_SALES_V SLS
INNER JOIN 
    COMP_DATE
ON  SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN 
    IDS_DEV.DATASTORE.DATE_DIM DT
ON  COMP_DATE.CALENDAR_DT = DT.CALENDAR_DT
WHERE 
    SLS.BUSINESS_DT >= DT.CALENDAR_QUARTER_START_DT
GROUP BY    
      SLS.BRAND_ID
    , STORE_ID
    , COMP_DATE.CALENDAR_DT
    , ''QTD'' 
    , CY_Comp_Eligible_Day
    , DMA_NAME 
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , CALENDAR_QUARTER_START_DT
    , L1Name
    , L2Name
    , L3Name
    , L4Name
    , L5Name


UNION

SELECT  --ODI-2675 
    SLS.BRAND_ID
    , STORE_ID
    , COMP_DATE.CALENDAR_DT 
    , SUM(CY_Net_Trans_Cnt_Day)
    , SUM(CY_Net_Sales_Day)
    , SUM(CY_Net_Trans_Cnt_Day) as CY_Comp_Trans_Cnt_Day
    , SUM(CY_Net_Sales_Day) as CY_Cal_Comp_Sales_Day
    , CALENDAR_MONTH_START_DT AGG_START_DT
    , ''PTD'' AS Agg_Level
    , CY_Comp_Eligible_Day
    , DMA_NAME 
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , L1Name
    , L2Name
    , L3Name
    , L4Name
    , L5Name
FROM 
    DAILY_FLASH_SALES_V SLS
INNER JOIN 
    COMP_DATE
ON SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN 
    IDS_DEV.DATASTORE.DATE_DIM DT
ON COMP_DATE.CALENDAR_DT = DT.CALENDAR_DT
WHERE SLS.BUSINESS_DT >= DT.CALENDAR_MONTH_START_DT
GROUP BY    
      SLS.BRAND_ID
    , STORE_ID
    , COMP_DATE.CALENDAR_DT
    , ''PTD'' 
    , CY_Comp_Eligible_Day
    , DMA_NAME 
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , CALENDAR_MONTH_START_DT
    , L1Name
    , L2Name
    , L3Name
    , L4Name
    , L5Name


UNION
   
SELECT   --ODI-2078 
   SLS.BRAND_ID
    , STORE_ID
    , COMP_DATE.CALENDAR_DT 
    , SUM(CY_Net_Trans_Cnt_Day)
    , SUM(CY_Net_Sales_Day)
    , SUM(CY_Net_Trans_Cnt_Day) as CY_Comp_Trans_Cnt_Day
    , SUM(CY_Net_Sales_Day) as CY_Cal_Comp_Sales_Day
    , CALENDAR_WEEK_START_DT AGG_START_DT
    , ''WTD'' AS Agg_Level
    , CY_Comp_Eligible_Day
    , DMA_NAME 
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , L1Name
    , L2Name
    , L3Name
    , L4Name
    , L5Name
FROM 
    DAILY_FLASH_SALES_V SLS
INNER JOIN 
    COMP_DATE
ON SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN 
    IDS_DEV.DATASTORE.DATE_DIM DT
ON  COMP_DATE.CALENDAR_DT = DT.CALENDAR_DT
WHERE 
    SLS.BUSINESS_DT >= DT.CALENDAR_WEEK_START_DT
GROUP BY    
      SLS.BRAND_ID
    , STORE_ID
    , COMP_DATE.CALENDAR_DT
    , ''WTD'' 
    , CY_Comp_Eligible_Day
    , DMA_NAME 
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , CALENDAR_WEEK_START_DT
    , L1Name
    , L2Name
    , L3Name
    , L4Name
    , L5Name

';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_NO_COMP_FISCAL("BUSINESS_DATE" DATE, "TIME_INTERVAL" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BUSINESS_DT" DATE, "TRANS_CNT" NUMBER(38,0), "NET_SALES" NUMBER(38,2), "COMP_TRANS" NUMBER(38,0), "COMP_SALES" NUMBER(38,2), "AGG_START_DT" DATE, "AGG_LEVEL" VARCHAR(16777216), "DMA_NAME" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "OWNERSHIP_TYPE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "OPEN_15P_FLAG" BOOLEAN, "CLOSED_BEFORE_PERIOD_END_FLAG" BOOLEAN, "OPEN_AFTER_HONEYMOON_FLAG" BOOLEAN, "WEEKDAY_OFFSET" ARRAY, "WEEK_TRANS_CNTS" ARRAY, "WEEK_NET_SALES" ARRAY, "WEEK_TRESHOLD" ARRAY, "IS_XMAS_THANKSGIVING" BOOLEAN, "DAY_OF_WEEK" VARCHAR(10), "END_DT" DATE, "TEMP_CLOSED_FLAG" BOOLEAN, "THRESHOLD_FLAG" BOOLEAN)
LANGUAGE SQL
AS '

WITH COMP_DATE AS 
(
 SELECT  
       s.calendar_dt -- comparison date
    ,  MAX_OPEN_DT -- ODI-53 maximum open date for which the store will be comp when reporting at BUSINESS_DATE
    ,  MAX_HONEY_DT -- ODI-199 maximum open date for which the store will be out of honeymoon period (3 full fiscal periods) at BUSINESS_DATE
FROM TABLE(FLASH_SUMMARY_COMP_HONEYMOON(BUSINESS_DATE,TIME_INTERVAL)) as s
),

SLS AS (
    select * from IDS_DEV.DATASTORE.DAILY_FLASH_SALES_STG as STG where SESSION_NO = CURRENT_SESSION() and STG.TIME_INTERVAL = TIME_INTERVAL
),
OT AS (
    SELECT 
      BRAND_ID
    , STORE_ID
    , OWNERSHIP_TYPE
    , DMA_CODE
    , DMA_NAME
    FROM IDS_DEV.DATASTORE.DAILY_FLASH_SALES_STG as STG
    WHERE SESSION_NO = CURRENT_SESSION() and STG.TIME_INTERVAL = TIME_INTERVAL
    QUALIFY ROW_NUMBER() OVER (PARTITION BY STORE_ID, BRAND_ID ORDER BY BUSINESS_DT DESC) = 1
),

QTD AS (
SELECT   --ODI-2392 
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT 
    , SUM(nvl(Trans_Cnt,0)) as Trans_Cnt
    , SUM(nvl(Net_Sales,0)) as Net_Sales
    , SUM(CASE WHEN 
        SLS.FISCAL_WEEK_NBR = 53 
        THEN 0 ELSE 
        nvl(Trans_Cnt,0) END) as Comp_Trans
    , SUM(CASE WHEN 
        SLS.FISCAL_WEEK_NBR = 53 
        THEN 0 ELSE 
        nvl(Net_Sales,0) END) as Comp_Sales
    , BDT.FISCAL_QUARTER_START_DT AGG_START_DT
    , ''QTD'' AS Agg_Level
    , OT.DMA_NAME 
    , OT.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , MAX(nvl(OPEN_DATE, MAX_OPEN_DT)) <= MAX(MAX_OPEN_DT) as OPEN_15P_FLAG -- ODI-53
    , NULL as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , MAX(nvl(SLS.OPEN_DATE, COMP_DATE.MAX_HONEY_DT)) <= MAX(COMP_DATE.MAX_HONEY_DT) as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , max(BDT.FISCAL_QUARTER_END_DT) as END_DT
FROM 
    SLS
INNER JOIN 
    OT
ON OT.BRAND_ID = SLS.BRAND_ID
AND OT.STORE_ID = SLS.STORE_ID
INNER JOIN 
    COMP_DATE
ON  SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN IDS_DEV.INT_REF.COMP_DATES BDT
ON BDT.CALENDAR_DT = COMP_DATE.CALENDAR_DT 
AND BDT.TIME_INTERVAL = TIME_INTERVAL
AND BDT.BUSINESS_DT = BUSINESS_DATE
WHERE 
    SLS.BUSINESS_DT >= BDT.FISCAL_QUARTER_START_DT
AND SLS.BUSINESS_DT <= 
                        iff(TIME_INTERVAL <> ''CY''
                            , least(COMP_DATE.CALENDAR_DT, BDT.FISCAL_QUARTER_END_DT)
                            , COMP_DATE.CALENDAR_DT
                        )
GROUP BY    
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT
    , ''QTD'' 
    , OT.DMA_NAME 
    , OT.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , BDT.FISCAL_QUARTER_START_DT
    , BDT.FISCAL_WEEK_NBR
),

YTD AS (
SELECT --ODI-2480
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT 
    , SUM(nvl(Trans_Cnt,0)) AS Trans_Cnt
    , SUM(nvl(Net_Sales,0)) AS Net_Sales
    , SUM(CASE WHEN 
        SLS.FISCAL_WEEK_NBR = 53 
        THEN 0 ELSE 
        nvl(Trans_Cnt,0) END) as Comp_Trans
    , SUM(CASE WHEN 
        SLS.FISCAL_WEEK_NBR = 53 
        THEN 0 ELSE 
        nvl(Net_Sales,0) END) as Comp_Sales
    , BDT.FISCAL_YEAR_START_DT AGG_START_DT
    , ''YTD'' AS Agg_Level
    , OT.DMA_NAME 
    , OT.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , MAX(nvl(OPEN_DATE, MAX_OPEN_DT)) <= MAX(MAX_OPEN_DT) as OPEN_15P_FLAG -- ODI-53
    , NULL as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , MAX(nvl(SLS.OPEN_DATE, COMP_DATE.MAX_HONEY_DT)) <= MAX(COMP_DATE.MAX_HONEY_DT) as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , max(BDT.FISCAL_YEAR_END_DT) as END_DT
FROM 
    SLS
INNER JOIN 
    OT
ON OT.BRAND_ID = SLS.BRAND_ID
AND OT.STORE_ID = SLS.STORE_ID
INNER JOIN 
    COMP_DATE
ON  SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN IDS_DEV.INT_REF.COMP_DATES BDT
ON BDT.CALENDAR_DT = COMP_DATE.CALENDAR_DT 
AND BDT.TIME_INTERVAL = TIME_INTERVAL
AND BDT.BUSINESS_DT = BUSINESS_DATE
WHERE 
    SLS.BUSINESS_DT >= BDT.FISCAL_YEAR_START_DT
AND SLS.BUSINESS_DT <=
                        iff(TIME_INTERVAL <> ''CY''
                            , least(COMP_DATE.CALENDAR_DT, BDT.FISCAL_QUARTER_END_DT)
                            , COMP_DATE.CALENDAR_DT
                        )
GROUP BY    
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT
    , ''YTD'' 
    , OT.DMA_NAME 
    , OT.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , BDT.FISCAL_YEAR_START_DT
    , BDT.FISCAL_WEEK_NBR
)
--CDTD AS   --ODI-2289 + ODI-906

SELECT 
      BRAND_ID
    , STORE_ID
    , BUSINESS_DT
    , Trans_Cnt
    , Net_Sales
    , Comp_Trans
    , Comp_Sales
    , AGG_START_DT
    , AGG_LEVEL
    , DMA_NAME 
    , DMA_CODE
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , OPEN_15P_FLAG -- ODI-53
    , CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , WEEKDAY_OFFSET --ODI-2977
    , WEEK_TRANS_CNTS --ODI-2977
    , WEEK_NET_SALES --ODI-2977
    , NULL as WEEK_TRESHOLD
    , IS_XMAS_THANKSGIVING --ODI-3039
    , DAY_OF_WEEK --ODI-3551
    , END_DT
    , NULL AS TEMP_CLOSED_FLAG
    , THRESHOLD_FLAG
FROM 
    table(FLASH_SUMMARY_COMP_DAY(BUSINESS_DATE,TIME_INTERVAL))

UNION ALL



SELECT  --ODI-2123
      YTD.BRAND_ID
    , YTD.STORE_ID
    , YTD.CALENDAR_DT 
    , YTD.Trans_Cnt
    , YTD.Net_Sales
    , YTD.Comp_Trans  
      - SUM(CASE WHEN PTD_ALL.Comp_Sales IS NULL 
      OR PTD_ALL.Comp_Sales = 0
      OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG 
      OR PTD_ALL.TEMP_CLOSED_FLAG
      THEN nvl(PTD_ALL.Comp_Trans, 0) ELSE 0 END) AS Comp_Trans
    , YTD.Comp_Sales
      - SUM(CASE WHEN PTD_ALL.Comp_Sales IS NULL 
      OR PTD_ALL.Comp_Sales = 0
      OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG 
      OR PTD_ALL.TEMP_CLOSED_FLAG
      THEN nvl(PTD_ALL.Comp_Sales, 0) ELSE 0 END) AS Comp_Sales
    , YTD.AGG_START_DT
    , YTD.Agg_Level
    , YTD.DMA_NAME 
    , YTD.DMA_CODE
    , YTD.OWNERSHIP_TYPE
    , YTD.STATE
    , YTD.COUNTRY
    , YTD.OPEN_15P_FLAG -- ODI-53
    , YTD.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , YTD.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , NULL as WEEKDAY_OFFSET --ODI-2977
    , NULL as WEEK_TRANS_CNTS --ODI-2977
    , NULL as WEEK_NET_SALES --ODI-2977
    , NULL as WEEK_TRESHOLD
    , NULL as IS_XMAS_THANKSGIVING --ODI-3039
    , NULL as DAY_OF_WEEK --ODI-3551
    , max(YTD.END_DT) as END_DT
    , NULL AS TEMP_CLOSED_FLAG
    , TRUE as THRESHOLD_FLAG
FROM YTD
LEFT JOIN table(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,TIME_INTERVAL)) PTD_ALL
ON YTD.BRAND_ID  = PTD_ALL.BRAND_ID
AND YTD.STORE_ID = PTD_ALL.STORE_ID
AND YTD.CALENDAR_DT = PTD_ALL.BUSINESS_DT
AND YTD.AGG_START_DT <= PTD_ALL.FISCAL_PERIOD_START_DT
AND PTD_ALL.NET_SALES IS NOT NULL
AND (PTD_ALL.COMP_SALES IS NULL or PTD_ALL.COMP_SALES = 0
OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG
OR TEMP_CLOSED_FLAG)
GROUP BY 
      YTD.BRAND_ID
    , YTD.STORE_ID
    , YTD.CALENDAR_DT 
    , YTD.Trans_Cnt
    , YTD.Net_Sales
    , YTD.AGG_START_DT
    , YTD.Agg_Level
    , YTD.DMA_NAME 
    , YTD.DMA_CODE
    , YTD.OWNERSHIP_TYPE
    , YTD.STATE
    , YTD.COUNTRY
    , YTD.OPEN_15P_FLAG -- ODI-53
    , YTD.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , YTD.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , YTD.Comp_Trans
    , YTD.Comp_Sales

UNION ALL


SELECT  --ODI-2123
      QTD.BRAND_ID
    , QTD.STORE_ID
    , QTD.CALENDAR_DT 
    , QTD.Trans_Cnt
    , QTD.Net_Sales
    , QTD.Comp_Trans 
      - SUM(CASE WHEN PTD_ALL.Comp_Sales IS NULL 
      OR PTD_ALL.Comp_Sales = 0
      OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG 
      OR PTD_ALL.TEMP_CLOSED_FLAG
      THEN nvl(PTD_ALL.Comp_Trans, 0) ELSE 0 END) AS Comp_Trans
    , QTD.Comp_Sales 
      - SUM(CASE WHEN PTD_ALL.Comp_Sales IS NULL 
      OR PTD_ALL.Comp_Sales = 0
      OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG 
      OR PTD_ALL.TEMP_CLOSED_FLAG
      THEN nvl(PTD_ALL.Comp_Sales, 0) ELSE 0 END) AS Comp_Sales
    , QTD.AGG_START_DT
    , QTD.Agg_Level
    , QTD.DMA_NAME 
    , QTD.DMA_CODE
    , QTD.OWNERSHIP_TYPE
    , QTD.STATE
    , QTD.COUNTRY
    , QTD.OPEN_15P_FLAG -- ODI-53
    , QTD.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , QTD.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , NULL as WEEKDAY_OFFSET --ODI-2977
    , NULL as WEEK_TRANS_CNTS --ODI-2977
    , NULL as WEEK_NET_SALES --ODI-2977
    , NULL as WEEK_TRESHOLD
    , NULL as IS_XMAS_THANKSGIVING --ODI-3039
    , NULL as DAY_OF_WEEK --ODI-3551
    , max(QTD.END_DT) as END_DT
    , NULL AS TEMP_CLOSED_FLAG
    , TRUE as THRESHOLD_FLAG
FROM QTD
LEFT JOIN table(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,TIME_INTERVAL)) PTD_ALL
ON QTD.BRAND_ID  = PTD_ALL.BRAND_ID
AND QTD.STORE_ID = PTD_ALL.STORE_ID
AND QTD.CALENDAR_DT = PTD_ALL.BUSINESS_DT
AND QTD.AGG_START_DT <= PTD_ALL.FISCAL_PERIOD_START_DT
AND PTD_ALL.NET_SALES IS NOT NULL
AND (PTD_ALL.COMP_SALES IS NULL or PTD_ALL.COMP_SALES = 0
OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG
OR TEMP_CLOSED_FLAG)
GROUP BY 
      QTD.BRAND_ID
    , QTD.STORE_ID
    , QTD.CALENDAR_DT 
    , QTD.Trans_Cnt
    , QTD.Net_Sales
    , QTD.AGG_START_DT
    , QTD.Agg_Level
    , QTD.DMA_NAME 
    , QTD.DMA_CODE
    , QTD.OWNERSHIP_TYPE
    , QTD.STATE
    , QTD.COUNTRY
    , QTD.OPEN_15P_FLAG -- ODI-53
    , QTD.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , QTD.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , QTD.Comp_Trans
    , QTD.Comp_Sales


UNION ALL

SELECT  --ODI-2123
      PTD.BRAND_ID
    , PTD.STORE_ID
    , CALENDAR_DT 
    , Trans_Cnt
    , Net_Sales
    , CASE WHEN CLOSED_BEFORE_PERIOD_END_FLAG
      OR TEMP_CLOSED_FLAG 
      THEN 0 ELSE Comp_Trans END AS Comp_Trans
    , CASE WHEN CLOSED_BEFORE_PERIOD_END_FLAG
      OR TEMP_CLOSED_FLAG
      THEN 0 ELSE Comp_Sales END AS Comp_Sales
    , AGG_START_DT
    , Agg_Level
    , OT.DMA_NAME 
    , OT.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , OPEN_15P_FLAG -- ODI-53
    , CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , NULL as WEEKDAY_OFFSET --ODI-2977
    , NULL as WEEK_TRANS_CNTS --ODI-2977
    , NULL as WEEK_NET_SALES --ODI-2977
    , NULL as WEEK_TRESHOLD
    , NULL as IS_XMAS_THANKSGIVING --ODI-3039
    , NULL as DAY_OF_WEEK --ODI-3551
    , END_DT
    , TEMP_CLOSED_FLAG
    , TRUE as THRESHOLD_FLAG
FROM TABLE(FLASH_SUMMARY_COMP_PTD(BUSINESS_DATE,TIME_INTERVAL)) PTD
INNER JOIN 
    OT
ON OT.BRAND_ID = PTD.BRAND_ID
AND OT.STORE_ID = PTD.STORE_ID


UNION ALL
   
SELECT   --ODI-2403 
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT 
    , SUM(nvl(Trans_Cnt,0)) 
    , SUM(nvl(Net_Sales,0))
    , SUM(Trans_Cnt) as Comp_Trans
    , SUM(Net_Sales) as Comp_Sales
    , BDT.FISCAL_WEEK_START_DT AGG_START_DT
    , ''WTD'' AS Agg_Level
    , OT.DMA_NAME 
    , OT.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , MAX(nvl(OPEN_DATE, MAX_OPEN_DT)) <= MAX(MAX_OPEN_DT) as OPEN_15P_FLAG -- ODI-53
    , NULL as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , MAX(nvl(SLS.OPEN_DATE, COMP_DATE.MAX_HONEY_DT)) <= MAX(COMP_DATE.MAX_HONEY_DT) as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , ARRAY_AGG(SLS.BUSINESS_DT - BDT.FISCAL_WEEK_START_DT) as WEEKDAY_OFFSET --ODI-2977
    , ARRAY_AGG(nvl(Trans_Cnt,0)) as WEEK_TRANS_CNTS --ODI-2977
    , ARRAY_AGG(nvl(Net_Sales,0)) as WEEK_NET_SALES --ODI-2977
    , ARRAY_AGG(THRESHOLD_FLAG) as WEEK_TRESHOLD
    , max(hol.date_key is not null) as IS_XMAS_THANKSGIVING --ODI-3039
    , NULL as DAY_OF_WEEK --ODI-3551
    , max(BDT.FISCAL_WEEK_END_DT) as END_DT
    , NULL AS TEMP_CLOSED_FLAG
    , TRUE as THRESHOLD_FLAG
FROM 
    SLS
INNER JOIN 
    OT
ON OT.BRAND_ID = SLS.BRAND_ID
AND OT.STORE_ID = SLS.STORE_ID
INNER JOIN 
    COMP_DATE
ON SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN IDS_DEV.INT_REF.COMP_DATES BDT
ON BDT.CALENDAR_DT = COMP_DATE.CALENDAR_DT 
AND BDT.TIME_INTERVAL = TIME_INTERVAL
AND BDT.BUSINESS_DT = BUSINESS_DATE
LEFT JOIN
    IDH_DEV.SHARED.HOLIDAY_DIM_V as hol
ON  SLS.BUSINESS_DT = TO_DATE(cast(hol.DATE_KEY as string), ''YYYYMMDD'')
AND hol.HOLIDAY_NM IN (''THANKSGIVING DAY'',''CHRISTMAS DAY'')
WHERE 
    SLS.BUSINESS_DT >= BDT.FISCAL_WEEK_START_DT
GROUP BY    
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT
    , ''WTD'' 
    , OT.DMA_NAME 
    , OT.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , BDT.FISCAL_WEEK_START_DT
    , BDT.FISCAL_WEEK_NBR

';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_NO_COMP_FISCAL("BUSINESS_DATE" DATE, "TIME_INTERVAL" VARCHAR(16777216), "REPORT_BRAND" VARCHAR(16777216), "THRESHOLD_FLAG" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BUSINESS_DT" DATE, "TRANS_CNT" NUMBER(38,0), "NET_SALES" NUMBER(38,2), "COMP_TRANS" NUMBER(38,0), "COMP_SALES" NUMBER(38,2), "AGG_START_DT" DATE, "AGG_LEVEL" VARCHAR(16777216), "DMA_NAME" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "OWNERSHIP_TYPE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "OPEN_15P_FLAG" BOOLEAN, "CLOSED_BEFORE_PERIOD_END_FLAG" BOOLEAN, "OPEN_AFTER_HONEYMOON_FLAG" BOOLEAN, "WEEKDAY_OFFSET" ARRAY, "WEEK_TRANS_CNTS" ARRAY, "WEEK_NET_SALES" ARRAY, "IS_XMAS_THANKSGIVING" BOOLEAN, "DAY_OF_WEEK" VARCHAR(10), "END_DT" DATE, "TEMP_CLOSED_FLAG" BOOLEAN)
LANGUAGE SQL
AS '

WITH COMP_DATE AS 
(
 SELECT  
       s.calendar_dt -- comparison date
    ,  MAX_OPEN_DT -- ODI-53 maximum open date for which the store will be comp when reporting at BUSINESS_DATE
    ,  MAX_HONEY_DT -- ODI-199 maximum open date for which the store will be out of honeymoon period (3 full fiscal periods) at BUSINESS_DATE
FROM TABLE(FLASH_SUMMARY_COMP_HONEYMOON(BUSINESS_DATE,TIME_INTERVAL)) as s
),

SLS AS (
    select * from table(DAILY_FLASH_SALES_V(BUSINESS_DATE,TIME_INTERVAL, REPORT_BRAND, THRESHOLD_FLAG))
),
OT AS (
    SELECT 
      BRAND_ID
    , STORE_ID
    , OWNERSHIP_TYPE
    FROM table(DAILY_FLASH_SALES_V(BUSINESS_DATE,TIME_INTERVAL, REPORT_BRAND, THRESHOLD_FLAG))
    QUALIFY ROW_NUMBER() OVER (PARTITION BY STORE_ID, BRAND_ID ORDER BY BUSINESS_DT DESC) = 1
),

QTD AS (
SELECT   --ODI-2392 
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT 
    , SUM(Trans_Cnt) as Trans_Cnt
    , SUM(Net_Sales) as Net_Sales
    , SUM(CASE WHEN 
        SLS.FISCAL_WEEK_NBR = 53 
        THEN 0 ELSE 
        Trans_Cnt END) as Comp_Trans
    , SUM(CASE WHEN 
        SLS.FISCAL_WEEK_NBR = 53 
        THEN 0 ELSE 
        Net_Sales END) as Comp_Sales
    , BDT.FISCAL_QUARTER_START_DT AGG_START_DT
    , ''QTD'' AS Agg_Level
    , SLS.DMA_NAME 
    , SLS.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , MAX(nvl(OPEN_DATE, MAX_OPEN_DT)) <= MAX(MAX_OPEN_DT) as OPEN_15P_FLAG -- ODI-53
    , NULL as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , MAX(nvl(SLS.OPEN_DATE, COMP_DATE.MAX_HONEY_DT)) <= MAX(COMP_DATE.MAX_HONEY_DT) as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , max(BDT.FISCAL_QUARTER_END_DT) as END_DT
FROM 
    SLS
INNER JOIN 
    OT
ON OT.BRAND_ID = SLS.BRAND_ID
AND OT.STORE_ID = SLS.STORE_ID
INNER JOIN 
    COMP_DATE
ON  SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN IDS_DEV.INT_REF.COMP_DATES BDT
ON BDT.CALENDAR_DT = COMP_DATE.CALENDAR_DT 
AND BDT.TIME_INTERVAL = TIME_INTERVAL
AND BDT.BUSINESS_DT = BUSINESS_DATE
WHERE 
    SLS.BUSINESS_DT >= BDT.FISCAL_QUARTER_START_DT
AND SLS.BUSINESS_DT <= 
                        iff(TIME_INTERVAL <> ''CY''
                            , least(COMP_DATE.CALENDAR_DT, BDT.FISCAL_QUARTER_END_DT)
                            , COMP_DATE.CALENDAR_DT
                        )
GROUP BY    
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT
    , ''QTD'' 
    , SLS.DMA_NAME 
    , SLS.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , BDT.FISCAL_QUARTER_START_DT
    , BDT.FISCAL_WEEK_NBR
),

YTD AS (
SELECT --ODI-2480
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT 
    , SUM(Trans_Cnt) AS Trans_Cnt
    , SUM(Net_Sales) AS Net_Sales
    , SUM(CASE WHEN 
        SLS.FISCAL_WEEK_NBR = 53 
        THEN 0 ELSE 
        Trans_Cnt END) as Comp_Trans
    , SUM(CASE WHEN 
        SLS.FISCAL_WEEK_NBR = 53 
        THEN 0 ELSE 
        Net_Sales END) as Comp_Sales
    , BDT.FISCAL_YEAR_START_DT AGG_START_DT
    , ''YTD'' AS Agg_Level
    , SLS.DMA_NAME 
    , SLS.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , MAX(nvl(OPEN_DATE, MAX_OPEN_DT)) <= MAX(MAX_OPEN_DT) as OPEN_15P_FLAG -- ODI-53
    , NULL as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , MAX(nvl(SLS.OPEN_DATE, COMP_DATE.MAX_HONEY_DT)) <= MAX(COMP_DATE.MAX_HONEY_DT) as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , max(BDT.FISCAL_YEAR_END_DT) as END_DT
FROM 
    SLS
INNER JOIN 
    OT
ON OT.BRAND_ID = SLS.BRAND_ID
AND OT.STORE_ID = SLS.STORE_ID
INNER JOIN 
    COMP_DATE
ON  SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN IDS_DEV.INT_REF.COMP_DATES BDT
ON BDT.CALENDAR_DT = COMP_DATE.CALENDAR_DT 
AND BDT.TIME_INTERVAL = TIME_INTERVAL
AND BDT.BUSINESS_DT = BUSINESS_DATE
WHERE 
    SLS.BUSINESS_DT >= BDT.FISCAL_YEAR_START_DT
AND SLS.BUSINESS_DT <=
                        iff(TIME_INTERVAL <> ''CY''
                            , least(COMP_DATE.CALENDAR_DT, BDT.FISCAL_QUARTER_END_DT)
                            , COMP_DATE.CALENDAR_DT
                        )
GROUP BY    
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT
    , ''YTD'' 
    , SLS.DMA_NAME 
    , SLS.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , BDT.FISCAL_YEAR_START_DT
    , BDT.FISCAL_WEEK_NBR
)
--CDTD AS   --ODI-2289 + ODI-906

SELECT 
      BRAND_ID
    , STORE_ID
    , BUSINESS_DT
    , Trans_Cnt
    , Net_Sales
    , Comp_Trans
    , Comp_Sales
    , AGG_START_DT
    , AGG_LEVEL
    , DMA_NAME 
    , DMA_CODE
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , OPEN_15P_FLAG -- ODI-53
    , CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , WEEKDAY_OFFSET --ODI-2977
    , WEEK_TRANS_CNTS --ODI-2977
    , WEEK_NET_SALES --ODI-2977
    , IS_XMAS_THANKSGIVING --ODI-3039
    , DAY_OF_WEEK --ODI-3551
    , END_DT
    , NULL AS TEMP_CLOSED_FLAG
FROM 
    table(FLASH_SUMMARY_COMP_DAY(BUSINESS_DATE,TIME_INTERVAL, REPORT_BRAND, THRESHOLD_FLAG))

UNION ALL



SELECT  --ODI-2123
      YTD.BRAND_ID
    , YTD.STORE_ID
    , YTD.CALENDAR_DT 
    , YTD.Trans_Cnt
    , YTD.Net_Sales
    , YTD.Comp_Trans  
      - SUM(CASE WHEN PTD_ALL.Comp_Sales IS NULL 
      OR PTD_ALL.Comp_Sales = 0
      OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG 
      OR PTD_ALL.TEMP_CLOSED_FLAG
      THEN nvl(PTD_ALL.Comp_Trans, 0) ELSE 0 END) AS Comp_Trans
    , YTD.Comp_Sales
      - SUM(CASE WHEN PTD_ALL.Comp_Sales IS NULL 
      OR PTD_ALL.Comp_Sales = 0
      OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG 
      OR PTD_ALL.TEMP_CLOSED_FLAG
      THEN nvl(PTD_ALL.Comp_Sales, 0) ELSE 0 END) AS Comp_Sales
    , YTD.AGG_START_DT
    , YTD.Agg_Level
    , YTD.DMA_NAME 
    , YTD.DMA_CODE
    , YTD.OWNERSHIP_TYPE
    , YTD.STATE
    , YTD.COUNTRY
    , YTD.OPEN_15P_FLAG -- ODI-53
    , YTD.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , YTD.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , NULL as WEEKDAY_OFFSET --ODI-2977
    , NULL as WEEK_TRANS_CNTS --ODI-2977
    , NULL as WEEK_NET_SALES --ODI-2977
    , NULL as IS_XMAS_THANKSGIVING --ODI-3039
    , NULL as DAY_OF_WEEK --ODI-3551
    , max(YTD.END_DT) as END_DT
    , NULL AS TEMP_CLOSED_FLAG
FROM YTD
LEFT JOIN table(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,TIME_INTERVAL, REPORT_BRAND, THRESHOLD_FLAG)) PTD_ALL
ON YTD.BRAND_ID  = PTD_ALL.BRAND_ID
AND YTD.STORE_ID = PTD_ALL.STORE_ID
AND YTD.CALENDAR_DT = PTD_ALL.BUSINESS_DT
AND YTD.AGG_START_DT <= PTD_ALL.FISCAL_PERIOD_START_DT
AND PTD_ALL.NET_SALES IS NOT NULL
AND (PTD_ALL.COMP_SALES IS NULL or PTD_ALL.COMP_SALES = 0
OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG
OR TEMP_CLOSED_FLAG)
GROUP BY 
      YTD.BRAND_ID
    , YTD.STORE_ID
    , YTD.CALENDAR_DT 
    , YTD.Trans_Cnt
    , YTD.Net_Sales
    , YTD.AGG_START_DT
    , YTD.Agg_Level
    , YTD.DMA_NAME 
    , YTD.DMA_CODE
    , YTD.OWNERSHIP_TYPE
    , YTD.STATE
    , YTD.COUNTRY
    , YTD.OPEN_15P_FLAG -- ODI-53
    , YTD.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , YTD.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , YTD.Comp_Trans
    , YTD.Comp_Sales

UNION ALL


SELECT  --ODI-2123
      QTD.BRAND_ID
    , QTD.STORE_ID
    , QTD.CALENDAR_DT 
    , QTD.Trans_Cnt
    , QTD.Net_Sales
    , QTD.Comp_Trans 
      - SUM(CASE WHEN PTD_ALL.Comp_Sales IS NULL 
      OR PTD_ALL.Comp_Sales = 0
      OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG 
      OR PTD_ALL.TEMP_CLOSED_FLAG
      THEN nvl(PTD_ALL.Comp_Trans, 0) ELSE 0 END) AS Comp_Trans
    , QTD.Comp_Sales 
      - SUM(CASE WHEN PTD_ALL.Comp_Sales IS NULL 
      OR PTD_ALL.Comp_Sales = 0
      OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG 
      OR PTD_ALL.TEMP_CLOSED_FLAG
      THEN nvl(PTD_ALL.Comp_Sales, 0) ELSE 0 END) AS Comp_Sales
    , QTD.AGG_START_DT
    , QTD.Agg_Level
    , QTD.DMA_NAME 
    , QTD.DMA_CODE
    , QTD.OWNERSHIP_TYPE
    , QTD.STATE
    , QTD.COUNTRY
    , QTD.OPEN_15P_FLAG -- ODI-53
    , QTD.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , QTD.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , NULL as WEEKDAY_OFFSET --ODI-2977
    , NULL as WEEK_TRANS_CNTS --ODI-2977
    , NULL as WEEK_NET_SALES --ODI-2977
    , NULL as IS_XMAS_THANKSGIVING --ODI-3039
    , NULL as DAY_OF_WEEK --ODI-3551
    , max(QTD.END_DT) as END_DT
    , NULL AS TEMP_CLOSED_FLAG
FROM QTD
LEFT JOIN table(FLASH_SUMMARY_COMP_PAST_WEEKS(BUSINESS_DATE,TIME_INTERVAL, REPORT_BRAND, THRESHOLD_FLAG)) PTD_ALL
ON QTD.BRAND_ID  = PTD_ALL.BRAND_ID
AND QTD.STORE_ID = PTD_ALL.STORE_ID
AND QTD.CALENDAR_DT = PTD_ALL.BUSINESS_DT
AND QTD.AGG_START_DT <= PTD_ALL.FISCAL_PERIOD_START_DT
AND PTD_ALL.NET_SALES IS NOT NULL
AND (PTD_ALL.COMP_SALES IS NULL or PTD_ALL.COMP_SALES = 0
OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG
OR TEMP_CLOSED_FLAG)
GROUP BY 
      QTD.BRAND_ID
    , QTD.STORE_ID
    , QTD.CALENDAR_DT 
    , QTD.Trans_Cnt
    , QTD.Net_Sales
    , QTD.AGG_START_DT
    , QTD.Agg_Level
    , QTD.DMA_NAME 
    , QTD.DMA_CODE
    , QTD.OWNERSHIP_TYPE
    , QTD.STATE
    , QTD.COUNTRY
    , QTD.OPEN_15P_FLAG -- ODI-53
    , QTD.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , QTD.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , QTD.Comp_Trans
    , QTD.Comp_Sales


UNION ALL

SELECT  --ODI-2123
      PTD.BRAND_ID
    , PTD.STORE_ID
    , CALENDAR_DT 
    , Trans_Cnt
    , Net_Sales
    , CASE WHEN CLOSED_BEFORE_PERIOD_END_FLAG
      OR TEMP_CLOSED_FLAG 
      THEN 0 ELSE Comp_Trans END AS Comp_Trans
    , CASE WHEN CLOSED_BEFORE_PERIOD_END_FLAG
      OR TEMP_CLOSED_FLAG
      THEN 0 ELSE Comp_Sales END AS Comp_Sales
    , AGG_START_DT
    , Agg_Level
    , DMA_NAME 
    , DMA_CODE
    , OT.OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , OPEN_15P_FLAG -- ODI-53
    , CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , NULL as WEEKDAY_OFFSET --ODI-2977
    , NULL as WEEK_TRANS_CNTS --ODI-2977
    , NULL as WEEK_NET_SALES --ODI-2977
    , NULL as IS_XMAS_THANKSGIVING --ODI-3039
    , NULL as DAY_OF_WEEK --ODI-3551
    , END_DT
    , TEMP_CLOSED_FLAG
FROM TABLE(FLASH_SUMMARY_COMP_PTD(BUSINESS_DATE,TIME_INTERVAL, REPORT_BRAND, THRESHOLD_FLAG)) PTD
INNER JOIN 
    OT
ON OT.BRAND_ID = PTD.BRAND_ID
AND OT.STORE_ID = PTD.STORE_ID


UNION ALL
   
SELECT   --ODI-2403 
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT 
    , SUM(Trans_Cnt)
    , SUM(Net_Sales)
    , SUM(Trans_Cnt) as Comp_Trans
    , SUM(Net_Sales) as Comp_Sales
    , BDT.FISCAL_WEEK_START_DT AGG_START_DT
    , ''WTD'' AS Agg_Level
    , SLS.DMA_NAME 
    , SLS.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , MAX(nvl(OPEN_DATE, MAX_OPEN_DT)) <= MAX(MAX_OPEN_DT) as OPEN_15P_FLAG -- ODI-53
    , NULL as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , MAX(nvl(SLS.OPEN_DATE, COMP_DATE.MAX_HONEY_DT)) <= MAX(COMP_DATE.MAX_HONEY_DT) as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , ARRAY_AGG(SLS.BUSINESS_DT - BDT.FISCAL_WEEK_START_DT) as WEEKDAY_OFFSET --ODI-2977
    , ARRAY_AGG(Trans_Cnt) as WEEK_TRANS_CNTS --ODI-2977
    , ARRAY_AGG(Net_Sales) as WEEK_NET_SALES --ODI-2977
    , max(hol.date_key is not null) as IS_XMAS_THANKSGIVING --ODI-3039
    , NULL as DAY_OF_WEEK --ODI-3551
    , max(BDT.FISCAL_WEEK_END_DT) as END_DT
    , NULL AS TEMP_CLOSED_FLAG
FROM 
    SLS
INNER JOIN 
    OT
ON OT.BRAND_ID = SLS.BRAND_ID
AND OT.STORE_ID = SLS.STORE_ID
INNER JOIN 
    COMP_DATE
ON SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN IDS_DEV.INT_REF.COMP_DATES BDT
ON BDT.CALENDAR_DT = COMP_DATE.CALENDAR_DT 
AND BDT.TIME_INTERVAL = TIME_INTERVAL
AND BDT.BUSINESS_DT = BUSINESS_DATE
LEFT JOIN
    IDH_DEV.SHARED.HOLIDAY_DIM_V as hol
ON  SLS.BUSINESS_DT = TO_DATE(cast(hol.DATE_KEY as string), ''YYYYMMDD'')
AND hol.HOLIDAY_NM IN (''THANKSGIVING DAY'',''CHRISTMAS DAY'')
WHERE 
    SLS.BUSINESS_DT >= BDT.FISCAL_WEEK_START_DT
GROUP BY    
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT
    , ''WTD'' 
    , SLS.DMA_NAME 
    , SLS.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , BDT.FISCAL_WEEK_START_DT
    , BDT.FISCAL_WEEK_NBR

';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_NO_COMP_FISCAL_DEV_AG("BUSINESS_DATE" DATE, "CURRENT_YEAR_BUSINESS_DATE" DATE)
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BUSINESS_DT" DATE, "TRANS_CNT" NUMBER(38,0), "NET_SALES" NUMBER(38,2), "COMP_TRANS" NUMBER(38,0), "COMP_SALES" NUMBER(38,2), "AGG_START_DT" DATE, "AGG_LEVEL" VARCHAR(16777216), "CY_COMP_ELIGIBLE_DAY" VARCHAR(16777216), "DMA_NAME" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "OWNERSHIP_TYPE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OPEN_15P_FLAG" BOOLEAN, "CLOSED_BEFORE_PERIOD_END_FLAG" BOOLEAN, "OPEN_AFTER_HONEYMOON_FLAG" BOOLEAN, "WEEKDAY_OFFSET" ARRAY, "WEEK_TRANS_CNTS" ARRAY, "WEEK_NET_SALES" ARRAY, "IS_XMAS_THANKSGIVING" BOOLEAN)
LANGUAGE SQL
AS '

WITH COMP_DATE AS 
(
 SELECT  
       s.calendar_dt -- comparison date
    ,  agg_start_p.FISCAL_QUARTER_START_DT as PRIOR_FISCAL_QUARTER_START_DT
    ,  agg_start_p.FISCAL_YEAR_START_DT as PRIOR_FISCAL_YEAR_START_DT
    ,  MAX_OPEN_DT -- ODI-53 maximum open date for which the store will be comp when reporting at BUSINESS_DATE
    ,  MAX_HONEY_DT -- ODI-199 maximum open date for which the store will be out of honeymoon period (3 full fiscal periods) at BUSINESS_DATE
FROM TABLE(FLASH_SUMMARY_COMP_HONEYMOON(BUSINESS_DATE)) as s
LEFT JOIN IDS_DEV.DATASTORE.DATE_DIM as cy
  on cy.FISCAL_WEEK_NBR = 53
  and CURRENT_YEAR_BUSINESS_DATE <> BUSINESS_DATE
  and CURRENT_YEAR_BUSINESS_DATE = cy.CALENDAR_DT
LEFT JOIN IDS_DEV.DATASTORE.DATE_DIM as py
  on cy.FISCAL_WEEK_NBR = 53
  and CURRENT_YEAR_BUSINESS_DATE <> BUSINESS_DATE
  and BUSINESS_DATE = py.CALENDAR_DT
LEFT JOIN IDS_DEV.DATASTORE.DATE_DIM as agg_start_p
  on cy.FISCAL_WEEK_NBR = 53
  and CURRENT_YEAR_BUSINESS_DATE <> BUSINESS_DATE
  and agg_start_p.FISCAL_YEAR_NBR = py.FISCAL_YEAR_NBR-1
  and agg_start_p.FISCAL_PERIOD_NBR = 12
  and agg_start_p.CALENDAR_DT = agg_start_p.FISCAL_PERIOD_START_DT
),

SLS AS (
    select * from table(DAILY_FLASH_SALES_V(BUSINESS_DATE, CURRENT_YEAR_BUSINESS_DATE))
),

QTD AS (
SELECT   --ODI-2392 
    SLS.BRAND_ID
    , STORE_ID
    , COMP_DATE.CALENDAR_DT 
    , SUM(Trans_Cnt) as Trans_Cnt
    , SUM(Net_Sales) as Net_Sales
    , SUM(CASE WHEN 
        salesday.FISCAL_WEEK_NBR = 53 
        THEN 0 ELSE 
        Trans_Cnt END) as Comp_Trans
    , SUM(CASE WHEN 
        salesday.FISCAL_WEEK_NBR = 53 
        THEN 0 ELSE 
        Net_Sales END) as Comp_Sales
    , nvl(COMP_DATE.PRIOR_FISCAL_QUARTER_START_DT, DT.FISCAL_QUARTER_START_DT) AGG_START_DT
    , ''QTD'' AS Agg_Level
    , CY_Comp_Eligible_Day
    , DMA_NAME 
    , DMA_CODE
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , L1Name
    , L2Name
    , L3Name
    , L4Name
    , L5Name
    , MAX(nvl(OPEN_DATE, MAX_OPEN_DT)) <= MAX(MAX_OPEN_DT) as OPEN_15P_FLAG -- ODI-53
    , NULL as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , MAX(nvl(SLS.OPEN_DATE, COMP_DATE.MAX_HONEY_DT)) <= MAX(COMP_DATE.MAX_HONEY_DT) as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
FROM 
    SLS
INNER JOIN 
    COMP_DATE
ON  SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN 
    IDS_DEV.DATASTORE.DATE_DIM DT
ON  COMP_DATE.CALENDAR_DT = DT.CALENDAR_DT
INNER JOIN 
    IDS_DEV.DATASTORE.DATE_DIM salesday
ON SLS.BUSINESS_DT = salesday.CALENDAR_DT
WHERE 
    SLS.BUSINESS_DT >= nvl(COMP_DATE.PRIOR_FISCAL_QUARTER_START_DT, DT.FISCAL_QUARTER_START_DT)
GROUP BY    
      SLS.BRAND_ID
    , STORE_ID
    , COMP_DATE.CALENDAR_DT
    , ''QTD'' 
    , CY_Comp_Eligible_Day
    , DMA_NAME 
    , DMA_CODE
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , nvl(COMP_DATE.PRIOR_FISCAL_QUARTER_START_DT, DT.FISCAL_QUARTER_START_DT)
    , L1Name
    , L2Name
    , L3Name
    , L4Name
    , L5Name
    , DT.FISCAL_WEEK_NBR
),

YTD AS (
SELECT --ODI-2480
      SLS.BRAND_ID
    , STORE_ID
    , COMP_DATE.CALENDAR_DT 
    , SUM(Trans_Cnt) AS Trans_Cnt
    , SUM(Net_Sales) AS Net_Sales
    , SUM(CASE WHEN 
        salesday.FISCAL_WEEK_NBR = 53 
        THEN 0 ELSE 
        Trans_Cnt END) as Comp_Trans
    , SUM(CASE WHEN 
        salesday.FISCAL_WEEK_NBR = 53 
        THEN 0 ELSE 
        Net_Sales END) as Comp_Sales
    , nvl(COMP_DATE.PRIOR_FISCAL_YEAR_START_DT, DT.FISCAL_YEAR_START_DT) AGG_START_DT
    , ''YTD'' AS Agg_Level
    , CY_Comp_Eligible_Day
    , DMA_NAME 
    , DMA_CODE
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , L1Name
    , L2Name
    , L3Name
    , L4Name
    , L5Name
    , MAX(nvl(OPEN_DATE, MAX_OPEN_DT)) <= MAX(MAX_OPEN_DT) as OPEN_15P_FLAG -- ODI-53
    , NULL as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , MAX(nvl(SLS.OPEN_DATE, COMP_DATE.MAX_HONEY_DT)) <= MAX(COMP_DATE.MAX_HONEY_DT) as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
FROM 
    SLS
INNER JOIN 
    COMP_DATE
ON  SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN 
    IDS_DEV.DATASTORE.DATE_DIM DT
ON  COMP_DATE.CALENDAR_DT = DT.CALENDAR_DT
INNER JOIN 
    IDS_DEV.DATASTORE.DATE_DIM salesday
ON SLS.BUSINESS_DT = salesday.CALENDAR_DT
WHERE 
    SLS.BUSINESS_DT >= nvl(COMP_DATE.PRIOR_FISCAL_YEAR_START_DT, DT.FISCAL_YEAR_START_DT)
GROUP BY    
      SLS.BRAND_ID
    , STORE_ID
    , COMP_DATE.CALENDAR_DT
    , ''YTD'' 
    , CY_Comp_Eligible_Day
    , DMA_NAME 
    , DMA_CODE
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , nvl(COMP_DATE.PRIOR_FISCAL_YEAR_START_DT, DT.FISCAL_YEAR_START_DT)
    , L1Name
    , L2Name
    , L3Name
    , L4Name
    , L5Name
    , DT.FISCAL_WEEK_NBR
)
--CDTD AS   --ODI-2289 + ODI-906

SELECT 
    BRAND_ID
    , STORE_ID
    , BUSINESS_DT
    , SUM(Trans_Cnt) as Trans_Cnt
    , SUM(Net_Sales) as Net_Sales
    , SUM(Trans_Cnt) as Comp_Trans
    , SUM(Net_Sales) as Comp_Sales
    , BUSINESS_DT as AGG_START_DT
    , ''DY'' AS AGG_LEVEL
    , CY_Comp_Eligible_Day
    , DMA_NAME 
    , DMA_CODE
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , L1Name
    , L2Name
    , L3Name
    , L4Name
    , L5Name
    , MAX(nvl(OPEN_DATE, MAX_OPEN_DT)) <= MAX(MAX_OPEN_DT) as OPEN_15P_FLAG -- ODI-53
    , NULL as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , MAX(nvl(SLS.OPEN_DATE, COMP_DATE.MAX_HONEY_DT)) <= MAX(COMP_DATE.MAX_HONEY_DT) as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , NULL as WEEKDAY_OFFSET --ODI-2977
    , NULL as WEEK_TRANS_CNTS --ODI-2977
    , NULL as WEEK_NET_SALES --ODI-2977
    , max(hol.date_key is not null) as IS_XMAS_THANKSGIVING --ODI-3039
FROM 
    SLS
INNER JOIN 
    COMP_DATE 
ON  SLS.BUSINESS_DT BETWEEN COMP_DATE.CALENDAR_DT -9 AND COMP_DATE.CALENDAR_DT
LEFT JOIN
    IDH_DEV.SHARED.HOLIDAY_NAMES_DIM_V as hol
ON  SLS.BUSINESS_DT = TO_DATE(cast(hol.DATE_KEY as string), ''YYYYMMDD'')
AND hol.HOLIDAY_LIST_NM IN (''THANKSGIVING DAY'',''CHRISTMAS DAY'')
GROUP BY    
      BRAND_ID
    , STORE_ID
    , BUSINESS_DT
    , ''DY'' 
    , CY_Comp_Eligible_Day
    , DMA_NAME 
    , DMA_CODE
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , COMP_DATE.CALENDAR_DT
    , L1Name
    , L2Name
    , L3Name
    , L4Name
    , L5Name

UNION 



SELECT  --ODI-2123
      YTD.BRAND_ID
    , YTD.STORE_ID
    , YTD.CALENDAR_DT 
    , YTD.Trans_Cnt
    , YTD.Net_Sales
    , YTD.Comp_Trans  
      - SUM(CASE WHEN PTD_ALL.Comp_Sales IS NULL THEN 
      nvl(PTD_ALL.Trans_Cnt, 0) ELSE 0 END) AS Comp_Trans
    , YTD.Comp_Sales
      - SUM(CASE WHEN PTD_ALL.Comp_Sales IS NULL THEN
      nvl(PTD_ALL.Net_Sales, 0) ELSE 0 END) AS Comp_Sales
    , YTD.AGG_START_DT
    , YTD.Agg_Level
    , YTD.CY_Comp_Eligible_Day
    , YTD.DMA_NAME 
    , YTD.DMA_CODE
    , YTD.OWNERSHIP_TYPE
    , YTD.STATE
    , YTD.COUNTRY
    , YTD.L1Name
    , YTD.L2Name
    , YTD.L3Name
    , YTD.L4Name
    , YTD.L5Name
    , YTD.OPEN_15P_FLAG -- ODI-53
    , YTD.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , YTD.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , NULL as WEEKDAY_OFFSET --ODI-2977
    , NULL as WEEK_TRANS_CNTS --ODI-2977
    , NULL as WEEK_NET_SALES --ODI-2977
    , NULL as IS_XMAS_THANKSGIVING --ODI-3039
FROM YTD
LEFT JOIN table(FLASH_SUMMARY_COMP_PAST_PERIODS(BUSINESS_DATE, CURRENT_YEAR_BUSINESS_DATE)) PTD_ALL
ON YTD.BRAND_ID  = PTD_ALL.BRAND_ID
AND YTD.STORE_ID = PTD_ALL.STORE_ID
AND YTD.CALENDAR_DT = PTD_ALL.BUSINESS_DT
AND YTD.AGG_START_DT <= PTD_ALL.AGG_START_DT
AND PTD_ALL.COMP_SALES IS NULL
AND PTD_ALL.NET_SALES IS NOT NULL
GROUP BY 
      YTD.BRAND_ID
    , YTD.STORE_ID
    , YTD.CALENDAR_DT 
    , YTD.Trans_Cnt
    , YTD.Net_Sales
    , YTD.AGG_START_DT
    , YTD.Agg_Level
    , YTD.CY_Comp_Eligible_Day
    , YTD.DMA_NAME 
    , YTD.DMA_CODE
    , YTD.OWNERSHIP_TYPE
    , YTD.STATE
    , YTD.COUNTRY
    , YTD.L1Name
    , YTD.L2Name
    , YTD.L3Name
    , YTD.L4Name
    , YTD.L5Name
    , YTD.OPEN_15P_FLAG -- ODI-53
    , YTD.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , YTD.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , PTD_ALL.Comp_Trans
    , PTD_ALL.Comp_Sales
    , YTD.Comp_Trans
    , YTD.Comp_Sales

UNION 


SELECT  --ODI-2123
      QTD.BRAND_ID
    , QTD.STORE_ID
    , QTD.CALENDAR_DT 
    , QTD.Trans_Cnt
    , QTD.Net_Sales
    , QTD.Comp_Trans 
      - SUM(CASE WHEN PTD_ALL.Comp_Sales IS NULL THEN 
      nvl(PTD_ALL.Trans_Cnt, 0) ELSE 0 END) AS Comp_Trans
    , QTD.Comp_Sales 
      - SUM(CASE WHEN PTD_ALL.Comp_Sales IS NULL THEN 
      nvl(PTD_ALL.Net_Sales, 0) ELSE 0 END) AS Comp_Sales
    , QTD.AGG_START_DT
    , QTD.Agg_Level
    , QTD.CY_Comp_Eligible_Day
    , QTD.DMA_NAME 
    , QTD.DMA_CODE
    , QTD.OWNERSHIP_TYPE
    , QTD.STATE
    , QTD.COUNTRY
    , QTD.L1Name
    , QTD.L2Name
    , QTD.L3Name
    , QTD.L4Name
    , QTD.L5Name
    , QTD.OPEN_15P_FLAG -- ODI-53
    , QTD.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , QTD.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , NULL as WEEKDAY_OFFSET --ODI-2977
    , NULL as WEEK_TRANS_CNTS --ODI-2977
    , NULL as WEEK_NET_SALES --ODI-2977
    , NULL as IS_XMAS_THANKSGIVING --ODI-3039
FROM QTD
LEFT JOIN table(FLASH_SUMMARY_COMP_PAST_PERIODS(BUSINESS_DATE, CURRENT_YEAR_BUSINESS_DATE)) PTD_ALL
ON QTD.BRAND_ID  = PTD_ALL.BRAND_ID
AND QTD.STORE_ID = PTD_ALL.STORE_ID
AND QTD.CALENDAR_DT = PTD_ALL.BUSINESS_DT
AND QTD.AGG_START_DT <= PTD_ALL.AGG_START_DT
AND PTD_ALL.COMP_SALES IS NULL
AND PTD_ALL.NET_SALES IS NOT NULL
GROUP BY 
      QTD.BRAND_ID
    , QTD.STORE_ID
    , QTD.CALENDAR_DT 
    , QTD.Trans_Cnt
    , QTD.Net_Sales
    , QTD.AGG_START_DT
    , QTD.Agg_Level
    , QTD.CY_Comp_Eligible_Day
    , QTD.DMA_NAME 
    , QTD.DMA_CODE
    , QTD.OWNERSHIP_TYPE
    , QTD.STATE
    , QTD.COUNTRY
    , QTD.L1Name
    , QTD.L2Name
    , QTD.L3Name
    , QTD.L4Name
    , QTD.L5Name
    , QTD.OPEN_15P_FLAG -- ODI-53
    , QTD.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , QTD.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , PTD_ALL.Comp_Trans
    , PTD_ALL.Comp_Sales
    , QTD.Comp_Trans
    , QTD.Comp_Sales


UNION

SELECT  --ODI-2123
      BRAND_ID
    , STORE_ID
    , CALENDAR_DT 
    , Trans_Cnt
    , Net_Sales
    , Comp_Trans
    , Comp_Sales
    , AGG_START_DT
    , Agg_Level
    , CY_Comp_Eligible_Day
    , DMA_NAME 
    , DMA_CODE
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , L1Name
    , L2Name
    , L3Name
    , L4Name
    , L5Name
    , OPEN_15P_FLAG -- ODI-53
    , CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , NULL as WEEKDAY_OFFSET --ODI-2977
    , NULL as WEEK_TRANS_CNTS --ODI-2977
    , NULL as WEEK_NET_SALES --ODI-2977
    , NULL as IS_XMAS_THANKSGIVING --ODI-3039
FROM TABLE(FLASH_SUMMARY_COMP_PTD(BUSINESS_DATE, CURRENT_YEAR_BUSINESS_DATE)) PTD


UNION
   
SELECT   --ODI-2403 
   SLS.BRAND_ID
    , STORE_ID
    , COMP_DATE.CALENDAR_DT 
    , SUM(Trans_Cnt)
    , SUM(Net_Sales)
    , SUM(Trans_Cnt) as Comp_Trans
    , SUM(Net_Sales) as Comp_Sales
    , FISCAL_WEEK_START_DT AGG_START_DT
    , ''WTD'' AS Agg_Level
    , CY_Comp_Eligible_Day
    , DMA_NAME 
    , DMA_CODE
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , L1Name
    , L2Name
    , L3Name
    , L4Name
    , L5Name
    , MAX(nvl(OPEN_DATE, MAX_OPEN_DT)) <= MAX(MAX_OPEN_DT) as OPEN_15P_FLAG -- ODI-53
    , NULL as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , MAX(nvl(SLS.OPEN_DATE, COMP_DATE.MAX_HONEY_DT)) <= MAX(COMP_DATE.MAX_HONEY_DT) as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , ARRAY_AGG(SLS.BUSINESS_DT - DT.FISCAL_WEEK_START_DT) as WEEKDAY_OFFSET --ODI-2977
    , ARRAY_AGG(Trans_Cnt) as WEEK_TRANS_CNTS --ODI-2977
    , ARRAY_AGG(Net_Sales) as WEEK_NET_SALES --ODI-2977
    , max(hol.date_key is not null) as IS_XMAS_THANKSGIVING --ODI-3039
FROM 
    SLS
INNER JOIN 
    COMP_DATE
ON SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN 
    IDS_DEV.DATASTORE.DATE_DIM DT
ON  COMP_DATE.CALENDAR_DT = DT.CALENDAR_DT
LEFT JOIN
    IDH_DEV.SHARED.HOLIDAY_NAMES_DIM_V as hol
ON  SLS.BUSINESS_DT = TO_DATE(cast(hol.DATE_KEY as string), ''YYYYMMDD'')
AND hol.HOLIDAY_LIST_NM IN (''THANKSGIVING DAY'',''CHRISTMAS DAY'')
WHERE 
    SLS.BUSINESS_DT >= DT.FISCAL_WEEK_START_DT
GROUP BY    
      SLS.BRAND_ID
    , STORE_ID
    , COMP_DATE.CALENDAR_DT
    , ''WTD'' 
    , CY_Comp_Eligible_Day
    , DMA_NAME 
    , DMA_CODE
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , FISCAL_WEEK_START_DT
    , L1Name
    , L2Name
    , L3Name
    , L4Name
    , L5Name
    , FISCAL_WEEK_NBR

';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_NO_COMP_FISCAL_F("BUSINESS_DATE" DATE, "TIME_INTERVAL" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BUSINESS_DT" DATE, "TRANS_CNT" NUMBER(38,0), "NET_SALES" NUMBER(38,2), "COMP_TRANS" NUMBER(38,0), "COMP_SALES" NUMBER(38,2), "AGG_START_DT" DATE, "AGG_LEVEL" VARCHAR(16777216), "DMA_NAME" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "OWNERSHIP_TYPE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "OPEN_15P_FLAG" BOOLEAN, "CLOSED_BEFORE_PERIOD_END_FLAG" BOOLEAN, "OPEN_AFTER_HONEYMOON_FLAG" BOOLEAN, "WEEKDAY_OFFSET" ARRAY, "WEEK_TRANS_CNTS" ARRAY, "WEEK_NET_SALES" ARRAY, "IS_XMAS_THANKSGIVING" BOOLEAN, "DAY_OF_WEEK" VARCHAR(10), "END_DT" DATE, "TEMP_CLOSED_FLAG" BOOLEAN)
LANGUAGE SQL
AS '

WITH COMP_DATE AS 
(
 SELECT  
       s.calendar_dt -- comparison date
    ,  MAX_OPEN_DT -- ODI-53 maximum open date for which the store will be comp when reporting at BUSINESS_DATE
    ,  MAX_HONEY_DT -- ODI-199 maximum open date for which the store will be out of honeymoon period (3 full fiscal periods) at BUSINESS_DATE
FROM TABLE(FLASH_SUMMARY_COMP_HONEYMOON(BUSINESS_DATE,TIME_INTERVAL)) as s
),

SLS AS (
    select * from table(DAILY_FLASH_SALES_V_F(BUSINESS_DATE,TIME_INTERVAL))
),
OT AS (
    SELECT 
      BRAND_ID
    , STORE_ID
    , OWNERSHIP_TYPE
    FROM table(DAILY_FLASH_SALES_V_F(BUSINESS_DATE,TIME_INTERVAL))
    QUALIFY ROW_NUMBER() OVER (PARTITION BY STORE_ID, BRAND_ID ORDER BY BUSINESS_DT DESC) = 1
),

QTD AS (
SELECT   --ODI-2392 
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT 
    , SUM(Trans_Cnt) as Trans_Cnt
    , SUM(Net_Sales) as Net_Sales
    , SUM(CASE WHEN 
        SLS.FISCAL_WEEK_NBR = 53 
        THEN 0 ELSE 
        Trans_Cnt END) as Comp_Trans
    , SUM(CASE WHEN 
        SLS.FISCAL_WEEK_NBR = 53 
        THEN 0 ELSE 
        Net_Sales END) as Comp_Sales
    , BDT.FISCAL_QUARTER_START_DT AGG_START_DT
    , ''QTD'' AS Agg_Level
    , SLS.DMA_NAME 
    , SLS.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , MAX(nvl(OPEN_DATE, MAX_OPEN_DT)) <= MAX(MAX_OPEN_DT) as OPEN_15P_FLAG -- ODI-53
    , NULL as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , MAX(nvl(SLS.OPEN_DATE, COMP_DATE.MAX_HONEY_DT)) <= MAX(COMP_DATE.MAX_HONEY_DT) as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , max(BDT.FISCAL_QUARTER_END_DT) as END_DT
FROM 
    SLS
INNER JOIN 
    OT
ON OT.BRAND_ID = SLS.BRAND_ID
AND OT.STORE_ID = SLS.STORE_ID
INNER JOIN 
    COMP_DATE
ON  SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN IDS_DEV.INT_REF.COMP_DATES BDT
ON BDT.CALENDAR_DT = COMP_DATE.CALENDAR_DT 
AND BDT.TIME_INTERVAL = TIME_INTERVAL
AND BDT.BUSINESS_DT = BUSINESS_DATE
WHERE 
    SLS.BUSINESS_DT >= BDT.FISCAL_QUARTER_START_DT
AND SLS.BUSINESS_DT <= 
                        iff(TIME_INTERVAL <> ''CY''
                            , least(COMP_DATE.CALENDAR_DT, BDT.FISCAL_QUARTER_END_DT)
                            , COMP_DATE.CALENDAR_DT
                        )
GROUP BY    
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT
    , ''QTD'' 
    , SLS.DMA_NAME 
    , SLS.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , BDT.FISCAL_QUARTER_START_DT
    , BDT.FISCAL_WEEK_NBR
),

YTD AS (
SELECT --ODI-2480
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT 
    , SUM(Trans_Cnt) AS Trans_Cnt
    , SUM(Net_Sales) AS Net_Sales
    , SUM(CASE WHEN 
        SLS.FISCAL_WEEK_NBR = 53 
        THEN 0 ELSE 
        Trans_Cnt END) as Comp_Trans
    , SUM(CASE WHEN 
        SLS.FISCAL_WEEK_NBR = 53 
        THEN 0 ELSE 
        Net_Sales END) as Comp_Sales
    , BDT.FISCAL_YEAR_START_DT AGG_START_DT
    , ''YTD'' AS Agg_Level
    , SLS.DMA_NAME 
    , SLS.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , MAX(nvl(OPEN_DATE, MAX_OPEN_DT)) <= MAX(MAX_OPEN_DT) as OPEN_15P_FLAG -- ODI-53
    , NULL as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , MAX(nvl(SLS.OPEN_DATE, COMP_DATE.MAX_HONEY_DT)) <= MAX(COMP_DATE.MAX_HONEY_DT) as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , max(BDT.FISCAL_YEAR_END_DT) as END_DT
FROM 
    SLS
INNER JOIN 
    OT
ON OT.BRAND_ID = SLS.BRAND_ID
AND OT.STORE_ID = SLS.STORE_ID
INNER JOIN 
    COMP_DATE
ON  SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN IDS_DEV.INT_REF.COMP_DATES BDT
ON BDT.CALENDAR_DT = COMP_DATE.CALENDAR_DT 
AND BDT.TIME_INTERVAL = TIME_INTERVAL
AND BDT.BUSINESS_DT = BUSINESS_DATE
WHERE 
    SLS.BUSINESS_DT >= BDT.FISCAL_YEAR_START_DT
AND SLS.BUSINESS_DT <=
                        iff(TIME_INTERVAL <> ''CY''
                            , least(COMP_DATE.CALENDAR_DT, BDT.FISCAL_QUARTER_END_DT)
                            , COMP_DATE.CALENDAR_DT
                        )
GROUP BY    
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT
    , ''YTD'' 
    , SLS.DMA_NAME 
    , SLS.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , BDT.FISCAL_YEAR_START_DT
    , BDT.FISCAL_WEEK_NBR
)
--CDTD AS   --ODI-2289 + ODI-906

SELECT 
      BRAND_ID
    , STORE_ID
    , BUSINESS_DT
    , Trans_Cnt
    , Net_Sales
    , Comp_Trans
    , Comp_Sales
    , AGG_START_DT
    , AGG_LEVEL
    , DMA_NAME 
    , DMA_CODE
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , OPEN_15P_FLAG -- ODI-53
    , CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , WEEKDAY_OFFSET --ODI-2977
    , WEEK_TRANS_CNTS --ODI-2977
    , WEEK_NET_SALES --ODI-2977
    , IS_XMAS_THANKSGIVING --ODI-3039
    , DAY_OF_WEEK --ODI-3551
    , END_DT
    , NULL AS TEMP_CLOSED_FLAG
FROM 
    table(FLASH_SUMMARY_COMP_DAY_F(BUSINESS_DATE,TIME_INTERVAL))

UNION ALL



SELECT  --ODI-2123
      YTD.BRAND_ID
    , YTD.STORE_ID
    , YTD.CALENDAR_DT 
    , YTD.Trans_Cnt
    , YTD.Net_Sales
    , YTD.Comp_Trans  
      - SUM(CASE WHEN PTD_ALL.Comp_Sales IS NULL 
      OR PTD_ALL.Comp_Sales = 0
      OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG 
      OR PTD_ALL.TEMP_CLOSED_FLAG
      THEN nvl(PTD_ALL.Comp_Trans, 0) ELSE 0 END) AS Comp_Trans
    , YTD.Comp_Sales
      - SUM(CASE WHEN PTD_ALL.Comp_Sales IS NULL 
      OR PTD_ALL.Comp_Sales = 0
      OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG 
      OR PTD_ALL.TEMP_CLOSED_FLAG
      THEN nvl(PTD_ALL.Comp_Sales, 0) ELSE 0 END) AS Comp_Sales
    , YTD.AGG_START_DT
    , YTD.Agg_Level
    , YTD.DMA_NAME 
    , YTD.DMA_CODE
    , YTD.OWNERSHIP_TYPE
    , YTD.STATE
    , YTD.COUNTRY
    , YTD.OPEN_15P_FLAG -- ODI-53
    , YTD.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , YTD.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , NULL as WEEKDAY_OFFSET --ODI-2977
    , NULL as WEEK_TRANS_CNTS --ODI-2977
    , NULL as WEEK_NET_SALES --ODI-2977
    , NULL as IS_XMAS_THANKSGIVING --ODI-3039
    , NULL as DAY_OF_WEEK --ODI-3551
    , max(YTD.END_DT) as END_DT
    , NULL AS TEMP_CLOSED_FLAG
FROM YTD
LEFT JOIN table(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,TIME_INTERVAL)) PTD_ALL
ON YTD.BRAND_ID  = PTD_ALL.BRAND_ID
AND YTD.STORE_ID = PTD_ALL.STORE_ID
AND YTD.CALENDAR_DT = PTD_ALL.BUSINESS_DT
AND YTD.AGG_START_DT <= PTD_ALL.FISCAL_PERIOD_START_DT
AND PTD_ALL.NET_SALES IS NOT NULL
AND (PTD_ALL.COMP_SALES IS NULL or PTD_ALL.COMP_SALES = 0
OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG
OR TEMP_CLOSED_FLAG)
GROUP BY 
      YTD.BRAND_ID
    , YTD.STORE_ID
    , YTD.CALENDAR_DT 
    , YTD.Trans_Cnt
    , YTD.Net_Sales
    , YTD.AGG_START_DT
    , YTD.Agg_Level
    , YTD.DMA_NAME 
    , YTD.DMA_CODE
    , YTD.OWNERSHIP_TYPE
    , YTD.STATE
    , YTD.COUNTRY
    , YTD.OPEN_15P_FLAG -- ODI-53
    , YTD.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , YTD.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , YTD.Comp_Trans
    , YTD.Comp_Sales

UNION ALL


SELECT  --ODI-2123
      QTD.BRAND_ID
    , QTD.STORE_ID
    , QTD.CALENDAR_DT 
    , QTD.Trans_Cnt
    , QTD.Net_Sales
    , QTD.Comp_Trans 
      - SUM(CASE WHEN PTD_ALL.Comp_Sales IS NULL 
      OR PTD_ALL.Comp_Sales = 0
      OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG 
      OR PTD_ALL.TEMP_CLOSED_FLAG
      THEN nvl(PTD_ALL.Comp_Trans, 0) ELSE 0 END) AS Comp_Trans
    , QTD.Comp_Sales 
      - SUM(CASE WHEN PTD_ALL.Comp_Sales IS NULL 
      OR PTD_ALL.Comp_Sales = 0
      OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG 
      OR PTD_ALL.TEMP_CLOSED_FLAG
      THEN nvl(PTD_ALL.Comp_Sales, 0) ELSE 0 END) AS Comp_Sales
    , QTD.AGG_START_DT
    , QTD.Agg_Level
    , QTD.DMA_NAME 
    , QTD.DMA_CODE
    , QTD.OWNERSHIP_TYPE
    , QTD.STATE
    , QTD.COUNTRY
    , QTD.OPEN_15P_FLAG -- ODI-53
    , QTD.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , QTD.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , NULL as WEEKDAY_OFFSET --ODI-2977
    , NULL as WEEK_TRANS_CNTS --ODI-2977
    , NULL as WEEK_NET_SALES --ODI-2977
    , NULL as IS_XMAS_THANKSGIVING --ODI-3039
    , NULL as DAY_OF_WEEK --ODI-3551
    , max(QTD.END_DT) as END_DT
    , NULL AS TEMP_CLOSED_FLAG
FROM QTD
LEFT JOIN table(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,TIME_INTERVAL)) PTD_ALL
ON QTD.BRAND_ID  = PTD_ALL.BRAND_ID
AND QTD.STORE_ID = PTD_ALL.STORE_ID
AND QTD.CALENDAR_DT = PTD_ALL.BUSINESS_DT
AND QTD.AGG_START_DT <= PTD_ALL.FISCAL_PERIOD_START_DT
AND PTD_ALL.NET_SALES IS NOT NULL
AND (PTD_ALL.COMP_SALES IS NULL or PTD_ALL.COMP_SALES = 0
OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG
OR TEMP_CLOSED_FLAG)
GROUP BY 
      QTD.BRAND_ID
    , QTD.STORE_ID
    , QTD.CALENDAR_DT 
    , QTD.Trans_Cnt
    , QTD.Net_Sales
    , QTD.AGG_START_DT
    , QTD.Agg_Level
    , QTD.DMA_NAME 
    , QTD.DMA_CODE
    , QTD.OWNERSHIP_TYPE
    , QTD.STATE
    , QTD.COUNTRY
    , QTD.OPEN_15P_FLAG -- ODI-53
    , QTD.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , QTD.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , QTD.Comp_Trans
    , QTD.Comp_Sales


UNION ALL

SELECT  --ODI-2123
      PTD.BRAND_ID
    , PTD.STORE_ID
    , CALENDAR_DT 
    , Trans_Cnt
    , Net_Sales
    , CASE WHEN CLOSED_BEFORE_PERIOD_END_FLAG
      OR TEMP_CLOSED_FLAG 
      THEN 0 ELSE Comp_Trans END AS Comp_Trans
    , CASE WHEN CLOSED_BEFORE_PERIOD_END_FLAG
      OR TEMP_CLOSED_FLAG
      THEN 0 ELSE Comp_Sales END AS Comp_Sales
    , AGG_START_DT
    , Agg_Level
    , DMA_NAME 
    , DMA_CODE
    , OT.OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , OPEN_15P_FLAG -- ODI-53
    , CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , NULL as WEEKDAY_OFFSET --ODI-2977
    , NULL as WEEK_TRANS_CNTS --ODI-2977
    , NULL as WEEK_NET_SALES --ODI-2977
    , NULL as IS_XMAS_THANKSGIVING --ODI-3039
    , NULL as DAY_OF_WEEK --ODI-3551
    , END_DT
    , TEMP_CLOSED_FLAG
FROM TABLE(FLASH_SUMMARY_COMP_PTD_F(BUSINESS_DATE,TIME_INTERVAL)) PTD
INNER JOIN 
    OT
ON OT.BRAND_ID = PTD.BRAND_ID
AND OT.STORE_ID = PTD.STORE_ID


UNION ALL
   
SELECT   --ODI-2403 
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT 
    , SUM(Trans_Cnt)
    , SUM(Net_Sales)
    , SUM(Trans_Cnt) as Comp_Trans
    , SUM(Net_Sales) as Comp_Sales
    , BDT.FISCAL_WEEK_START_DT AGG_START_DT
    , ''WTD'' AS Agg_Level
    , SLS.DMA_NAME 
    , SLS.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , MAX(nvl(OPEN_DATE, MAX_OPEN_DT)) <= MAX(MAX_OPEN_DT) as OPEN_15P_FLAG -- ODI-53
    , NULL as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , MAX(nvl(SLS.OPEN_DATE, COMP_DATE.MAX_HONEY_DT)) <= MAX(COMP_DATE.MAX_HONEY_DT) as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , ARRAY_AGG(SLS.BUSINESS_DT - BDT.FISCAL_WEEK_START_DT) as WEEKDAY_OFFSET --ODI-2977
    , ARRAY_AGG(Trans_Cnt) as WEEK_TRANS_CNTS --ODI-2977
    , ARRAY_AGG(Net_Sales) as WEEK_NET_SALES --ODI-2977
    , max(hol.date_key is not null) as IS_XMAS_THANKSGIVING --ODI-3039
    , NULL as DAY_OF_WEEK --ODI-3551
    , max(BDT.FISCAL_WEEK_END_DT) as END_DT
    , NULL AS TEMP_CLOSED_FLAG
FROM 
    SLS
INNER JOIN 
    OT
ON OT.BRAND_ID = SLS.BRAND_ID
AND OT.STORE_ID = SLS.STORE_ID
INNER JOIN 
    COMP_DATE
ON SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN IDS_DEV.INT_REF.COMP_DATES BDT
ON BDT.CALENDAR_DT = COMP_DATE.CALENDAR_DT 
AND BDT.TIME_INTERVAL = TIME_INTERVAL
AND BDT.BUSINESS_DT = BUSINESS_DATE
LEFT JOIN
    IDH_DEV.SHARED.HOLIDAY_DIM_V as hol
ON  SLS.BUSINESS_DT = TO_DATE(cast(hol.DATE_KEY as string), ''YYYYMMDD'')
AND hol.HOLIDAY_NM IN (''THANKSGIVING DAY'',''CHRISTMAS DAY'')
WHERE 
    SLS.BUSINESS_DT >= BDT.FISCAL_WEEK_START_DT
GROUP BY    
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT
    , ''WTD'' 
    , SLS.DMA_NAME 
    , SLS.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , BDT.FISCAL_WEEK_START_DT
    , BDT.FISCAL_WEEK_NBR

';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_NO_COMP_FISCAL_F("BUSINESS_DATE" DATE, "TIME_INTERVAL" VARCHAR(16777216), "BRAND" VARCHAR(16777216), "THRESHOLD_FLG" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BUSINESS_DT" DATE, "TRANS_CNT" NUMBER(38,0), "NET_SALES" NUMBER(38,2), "COMP_TRANS" NUMBER(38,0), "COMP_SALES" NUMBER(38,2), "AGG_START_DT" DATE, "AGG_LEVEL" VARCHAR(16777216), "DMA_NAME" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "OWNERSHIP_TYPE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "OPEN_15P_FLAG" BOOLEAN, "CLOSED_BEFORE_PERIOD_END_FLAG" BOOLEAN, "OPEN_AFTER_HONEYMOON_FLAG" BOOLEAN, "WEEKDAY_OFFSET" ARRAY, "WEEK_TRANS_CNTS" ARRAY, "WEEK_NET_SALES" ARRAY, "IS_XMAS_THANKSGIVING" BOOLEAN, "DAY_OF_WEEK" VARCHAR(10), "END_DT" DATE, "TEMP_CLOSED_FLAG" BOOLEAN, "THRESHOLD_FLAG" BOOLEAN)
LANGUAGE SQL
AS '

WITH COMP_DATE AS 
(
 SELECT  
       s.calendar_dt -- comparison date
    ,  MAX_OPEN_DT -- ODI-53 maximum open date for which the store will be comp when reporting at BUSINESS_DATE
    ,  MAX_HONEY_DT -- ODI-199 maximum open date for which the store will be out of honeymoon period (3 full fiscal periods) at BUSINESS_DATE
FROM TABLE(FLASH_SUMMARY_COMP_HONEYMOON(BUSINESS_DATE,TIME_INTERVAL)) as s
),

SLS AS (
    select * from table(DAILY_FLASH_SALES_V_F(BUSINESS_DATE,TIME_INTERVAL, BRAND, THRESHOLD_FLG))
),
OT AS (
    SELECT 
      BRAND_ID
    , STORE_ID
    , OWNERSHIP_TYPE
    FROM table(DAILY_FLASH_SALES_V_F(BUSINESS_DATE,TIME_INTERVAL, BRAND, THRESHOLD_FLG))
    QUALIFY ROW_NUMBER() OVER (PARTITION BY STORE_ID, BRAND_ID ORDER BY BUSINESS_DT DESC) = 1
),

QTD AS (
SELECT   --ODI-2392 
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT 
    , SUM(nvl(Trans_Cnt,0)) as Trans_Cnt
    , SUM(nvl(Net_Sales,0)) as Net_Sales
    , SUM(CASE WHEN 
        SLS.FISCAL_WEEK_NBR = 53 
        THEN 0 ELSE 
        nvl(Trans_Cnt,0) END) as Comp_Trans
    , SUM(CASE WHEN 
        SLS.FISCAL_WEEK_NBR = 53 
        THEN 0 ELSE 
        nvl(Net_Sales,0) END) as Comp_Sales
    , BDT.FISCAL_QUARTER_START_DT AGG_START_DT
    , ''QTD'' AS Agg_Level
    , SLS.DMA_NAME 
    , SLS.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , MAX(nvl(OPEN_DATE, MAX_OPEN_DT)) <= MAX(MAX_OPEN_DT) as OPEN_15P_FLAG -- ODI-53
    , NULL as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , MAX(nvl(SLS.OPEN_DATE, COMP_DATE.MAX_HONEY_DT)) <= MAX(COMP_DATE.MAX_HONEY_DT) as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , max(BDT.FISCAL_QUARTER_END_DT) as END_DT
FROM 
    SLS
INNER JOIN 
    OT
ON OT.BRAND_ID = SLS.BRAND_ID
AND OT.STORE_ID = SLS.STORE_ID
INNER JOIN 
    COMP_DATE
ON  SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN IDS_DEV.INT_REF.COMP_DATES BDT
ON BDT.CALENDAR_DT = COMP_DATE.CALENDAR_DT 
AND BDT.TIME_INTERVAL = TIME_INTERVAL
AND BDT.BUSINESS_DT = BUSINESS_DATE
WHERE 
    SLS.BUSINESS_DT >= BDT.FISCAL_QUARTER_START_DT
AND SLS.BUSINESS_DT <= 
                        iff(TIME_INTERVAL <> ''CY''
                            , least(COMP_DATE.CALENDAR_DT, BDT.FISCAL_QUARTER_END_DT)
                            , COMP_DATE.CALENDAR_DT
                        )
GROUP BY    
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT
    , ''QTD'' 
    , SLS.DMA_NAME 
    , SLS.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , BDT.FISCAL_QUARTER_START_DT
    , BDT.FISCAL_WEEK_NBR
),

YTD AS (
SELECT --ODI-2480
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT 
    , SUM(nvl(Trans_Cnt,0)) AS Trans_Cnt
    , SUM(nvl(Net_Sales,0)) AS Net_Sales
    , SUM(CASE WHEN 
        SLS.FISCAL_WEEK_NBR = 53 
        THEN 0 ELSE 
        nvl(Trans_Cnt,0) END) as Comp_Trans
    , SUM(CASE WHEN 
        SLS.FISCAL_WEEK_NBR = 53 
        THEN 0 ELSE 
        nvl(Net_Sales,0) END) as Comp_Sales
    , BDT.FISCAL_YEAR_START_DT AGG_START_DT
    , ''YTD'' AS Agg_Level
    , SLS.DMA_NAME 
    , SLS.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , MAX(nvl(OPEN_DATE, MAX_OPEN_DT)) <= MAX(MAX_OPEN_DT) as OPEN_15P_FLAG -- ODI-53
    , NULL as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , MAX(nvl(SLS.OPEN_DATE, COMP_DATE.MAX_HONEY_DT)) <= MAX(COMP_DATE.MAX_HONEY_DT) as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , max(BDT.FISCAL_YEAR_END_DT) as END_DT
FROM 
    SLS
INNER JOIN 
    OT
ON OT.BRAND_ID = SLS.BRAND_ID
AND OT.STORE_ID = SLS.STORE_ID
INNER JOIN 
    COMP_DATE
ON  SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN IDS_DEV.INT_REF.COMP_DATES BDT
ON BDT.CALENDAR_DT = COMP_DATE.CALENDAR_DT 
AND BDT.TIME_INTERVAL = TIME_INTERVAL
AND BDT.BUSINESS_DT = BUSINESS_DATE
WHERE 
    SLS.BUSINESS_DT >= BDT.FISCAL_YEAR_START_DT
AND SLS.BUSINESS_DT <=
                        iff(TIME_INTERVAL <> ''CY''
                            , least(COMP_DATE.CALENDAR_DT, BDT.FISCAL_QUARTER_END_DT)
                            , COMP_DATE.CALENDAR_DT
                        )
GROUP BY    
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT
    , ''YTD'' 
    , SLS.DMA_NAME 
    , SLS.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , BDT.FISCAL_YEAR_START_DT
    , BDT.FISCAL_WEEK_NBR
)
--CDTD AS   --ODI-2289 + ODI-906

SELECT 
      BRAND_ID
    , STORE_ID
    , BUSINESS_DT
    , Trans_Cnt
    , Net_Sales
    , Comp_Trans
    , Comp_Sales
    , AGG_START_DT
    , AGG_LEVEL
    , DMA_NAME 
    , DMA_CODE
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , OPEN_15P_FLAG -- ODI-53
    , CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , WEEKDAY_OFFSET --ODI-2977
    , WEEK_TRANS_CNTS --ODI-2977
    , WEEK_NET_SALES --ODI-2977
    , IS_XMAS_THANKSGIVING --ODI-3039
    , DAY_OF_WEEK --ODI-3551
    , END_DT
    , NULL AS TEMP_CLOSED_FLAG
    , THRESHOLD_FLAG
FROM 
    table(FLASH_SUMMARY_COMP_DAY_F(BUSINESS_DATE,TIME_INTERVAL, BRAND, THRESHOLD_FLG))

UNION ALL



SELECT  --ODI-2123
      YTD.BRAND_ID
    , YTD.STORE_ID
    , YTD.CALENDAR_DT 
    , YTD.Trans_Cnt
    , YTD.Net_Sales
    , YTD.Comp_Trans  
      - SUM(CASE WHEN PTD_ALL.Comp_Sales IS NULL 
      OR PTD_ALL.Comp_Sales = 0
      OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG 
      OR PTD_ALL.TEMP_CLOSED_FLAG
      THEN nvl(PTD_ALL.Comp_Trans, 0) ELSE 0 END) AS Comp_Trans
    , YTD.Comp_Sales
      - SUM(CASE WHEN PTD_ALL.Comp_Sales IS NULL 
      OR PTD_ALL.Comp_Sales = 0
      OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG 
      OR PTD_ALL.TEMP_CLOSED_FLAG
      THEN nvl(PTD_ALL.Comp_Sales, 0) ELSE 0 END) AS Comp_Sales
    , YTD.AGG_START_DT
    , YTD.Agg_Level
    , YTD.DMA_NAME 
    , YTD.DMA_CODE
    , YTD.OWNERSHIP_TYPE
    , YTD.STATE
    , YTD.COUNTRY
    , YTD.OPEN_15P_FLAG -- ODI-53
    , YTD.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , YTD.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , NULL as WEEKDAY_OFFSET --ODI-2977
    , NULL as WEEK_TRANS_CNTS --ODI-2977
    , NULL as WEEK_NET_SALES --ODI-2977
    , NULL as IS_XMAS_THANKSGIVING --ODI-3039
    , NULL as DAY_OF_WEEK --ODI-3551
    , max(YTD.END_DT) as END_DT
    , NULL AS TEMP_CLOSED_FLAG
    , TRUE as THRESHOLD_FLAG
FROM YTD
LEFT JOIN table(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,TIME_INTERVAL, BRAND, THRESHOLD_FLG)) PTD_ALL
ON YTD.BRAND_ID  = PTD_ALL.BRAND_ID
AND YTD.STORE_ID = PTD_ALL.STORE_ID
AND YTD.CALENDAR_DT = PTD_ALL.BUSINESS_DT
AND YTD.AGG_START_DT <= PTD_ALL.FISCAL_PERIOD_START_DT
AND PTD_ALL.NET_SALES IS NOT NULL
AND (PTD_ALL.COMP_SALES IS NULL or PTD_ALL.COMP_SALES = 0
OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG
OR TEMP_CLOSED_FLAG)
GROUP BY 
      YTD.BRAND_ID
    , YTD.STORE_ID
    , YTD.CALENDAR_DT 
    , YTD.Trans_Cnt
    , YTD.Net_Sales
    , YTD.AGG_START_DT
    , YTD.Agg_Level
    , YTD.DMA_NAME 
    , YTD.DMA_CODE
    , YTD.OWNERSHIP_TYPE
    , YTD.STATE
    , YTD.COUNTRY
    , YTD.OPEN_15P_FLAG -- ODI-53
    , YTD.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , YTD.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , YTD.Comp_Trans
    , YTD.Comp_Sales

UNION ALL


SELECT  --ODI-2123
      QTD.BRAND_ID
    , QTD.STORE_ID
    , QTD.CALENDAR_DT 
    , QTD.Trans_Cnt
    , QTD.Net_Sales
    , QTD.Comp_Trans 
      - SUM(CASE WHEN PTD_ALL.Comp_Sales IS NULL 
      OR PTD_ALL.Comp_Sales = 0
      OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG 
      OR PTD_ALL.TEMP_CLOSED_FLAG
      THEN nvl(PTD_ALL.Comp_Trans, 0) ELSE 0 END) AS Comp_Trans
    , QTD.Comp_Sales 
      - SUM(CASE WHEN PTD_ALL.Comp_Sales IS NULL 
      OR PTD_ALL.Comp_Sales = 0
      OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG 
      OR PTD_ALL.TEMP_CLOSED_FLAG
      THEN nvl(PTD_ALL.Comp_Sales, 0) ELSE 0 END) AS Comp_Sales
    , QTD.AGG_START_DT
    , QTD.Agg_Level
    , QTD.DMA_NAME 
    , QTD.DMA_CODE
    , QTD.OWNERSHIP_TYPE
    , QTD.STATE
    , QTD.COUNTRY
    , QTD.OPEN_15P_FLAG -- ODI-53
    , QTD.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , QTD.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , NULL as WEEKDAY_OFFSET --ODI-2977
    , NULL as WEEK_TRANS_CNTS --ODI-2977
    , NULL as WEEK_NET_SALES --ODI-2977
    , NULL as IS_XMAS_THANKSGIVING --ODI-3039
    , NULL as DAY_OF_WEEK --ODI-3551
    , max(QTD.END_DT) as END_DT
    , NULL AS TEMP_CLOSED_FLAG
    , TRUE as THRESHOLD_FLAG
FROM QTD
LEFT JOIN table(FLASH_SUMMARY_COMP_PAST_WEEKS_F(BUSINESS_DATE,TIME_INTERVAL, BRAND, THRESHOLD_FLG)) PTD_ALL
ON QTD.BRAND_ID  = PTD_ALL.BRAND_ID
AND QTD.STORE_ID = PTD_ALL.STORE_ID
AND QTD.CALENDAR_DT = PTD_ALL.BUSINESS_DT
AND QTD.AGG_START_DT <= PTD_ALL.FISCAL_PERIOD_START_DT
AND PTD_ALL.NET_SALES IS NOT NULL
AND (PTD_ALL.COMP_SALES IS NULL or PTD_ALL.COMP_SALES = 0
OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG
OR TEMP_CLOSED_FLAG)
GROUP BY 
      QTD.BRAND_ID
    , QTD.STORE_ID
    , QTD.CALENDAR_DT 
    , QTD.Trans_Cnt
    , QTD.Net_Sales
    , QTD.AGG_START_DT
    , QTD.Agg_Level
    , QTD.DMA_NAME 
    , QTD.DMA_CODE
    , QTD.OWNERSHIP_TYPE
    , QTD.STATE
    , QTD.COUNTRY
    , QTD.OPEN_15P_FLAG -- ODI-53
    , QTD.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , QTD.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , QTD.Comp_Trans
    , QTD.Comp_Sales


UNION ALL

SELECT  --ODI-2123
      PTD.BRAND_ID
    , PTD.STORE_ID
    , CALENDAR_DT 
    , Trans_Cnt
    , Net_Sales
    , CASE WHEN CLOSED_BEFORE_PERIOD_END_FLAG
      OR TEMP_CLOSED_FLAG 
      THEN 0 ELSE Comp_Trans END AS Comp_Trans
    , CASE WHEN CLOSED_BEFORE_PERIOD_END_FLAG
      OR TEMP_CLOSED_FLAG
      THEN 0 ELSE Comp_Sales END AS Comp_Sales
    , AGG_START_DT
    , Agg_Level
    , DMA_NAME 
    , DMA_CODE
    , OT.OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , OPEN_15P_FLAG -- ODI-53
    , CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , NULL as WEEKDAY_OFFSET --ODI-2977
    , NULL as WEEK_TRANS_CNTS --ODI-2977
    , NULL as WEEK_NET_SALES --ODI-2977
    , NULL as IS_XMAS_THANKSGIVING --ODI-3039
    , NULL as DAY_OF_WEEK --ODI-3551
    , END_DT
    , TEMP_CLOSED_FLAG
    , TRUE as THRESHOLD_FLAG
FROM TABLE(FLASH_SUMMARY_COMP_PTD_F(BUSINESS_DATE,TIME_INTERVAL, BRAND, THRESHOLD_FLG)) PTD
INNER JOIN 
    OT
ON OT.BRAND_ID = PTD.BRAND_ID
AND OT.STORE_ID = PTD.STORE_ID


UNION ALL
   
SELECT   --ODI-2403 
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT 
    , SUM(nvl(Trans_Cnt,0)) 
    , SUM(nvl(Net_Sales,0))
    , SUM(Trans_Cnt) as Comp_Trans
    , SUM(Net_Sales) as Comp_Sales
    , BDT.FISCAL_WEEK_START_DT AGG_START_DT
    , ''WTD'' AS Agg_Level
    , SLS.DMA_NAME 
    , SLS.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , MAX(nvl(OPEN_DATE, MAX_OPEN_DT)) <= MAX(MAX_OPEN_DT) as OPEN_15P_FLAG -- ODI-53
    , NULL as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , MAX(nvl(SLS.OPEN_DATE, COMP_DATE.MAX_HONEY_DT)) <= MAX(COMP_DATE.MAX_HONEY_DT) as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , ARRAY_AGG(SLS.BUSINESS_DT - BDT.FISCAL_WEEK_START_DT) as WEEKDAY_OFFSET --ODI-2977
    , ARRAY_AGG(Trans_Cnt) as WEEK_TRANS_CNTS --ODI-2977
    , ARRAY_AGG(Net_Sales) as WEEK_NET_SALES --ODI-2977
    , max(hol.date_key is not null) as IS_XMAS_THANKSGIVING --ODI-3039
    , NULL as DAY_OF_WEEK --ODI-3551
    , max(BDT.FISCAL_WEEK_END_DT) as END_DT
    , NULL AS TEMP_CLOSED_FLAG
    , TRUE as THRESHOLD_FLAG
FROM 
    SLS
INNER JOIN 
    OT
ON OT.BRAND_ID = SLS.BRAND_ID
AND OT.STORE_ID = SLS.STORE_ID
INNER JOIN 
    COMP_DATE
ON SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN IDS_DEV.INT_REF.COMP_DATES BDT
ON BDT.CALENDAR_DT = COMP_DATE.CALENDAR_DT 
AND BDT.TIME_INTERVAL = TIME_INTERVAL
AND BDT.BUSINESS_DT = BUSINESS_DATE
LEFT JOIN
    IDH_DEV.SHARED.HOLIDAY_DIM_V as hol
ON  SLS.BUSINESS_DT = TO_DATE(cast(hol.DATE_KEY as string), ''YYYYMMDD'')
AND hol.HOLIDAY_NM IN (''THANKSGIVING DAY'',''CHRISTMAS DAY'')
WHERE 
    SLS.BUSINESS_DT >= BDT.FISCAL_WEEK_START_DT
GROUP BY    
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT
    , ''WTD'' 
    , SLS.DMA_NAME 
    , SLS.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , BDT.FISCAL_WEEK_START_DT
    , BDT.FISCAL_WEEK_NBR

';
CREATE FUNCTION IF NOT EXISTS FLASH_SUMMARY_NO_COMP_FISCAL_WITHOUT_THRESHOLD("BUSINESS_DATE" DATE, "TIME_INTERVAL" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BUSINESS_DT" DATE, "TRANS_CNT" NUMBER(38,0), "NET_SALES" NUMBER(38,2), "COMP_TRANS" NUMBER(38,0), "COMP_SALES" NUMBER(38,2), "AGG_START_DT" DATE, "AGG_LEVEL" VARCHAR(16777216), "DMA_NAME" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "OWNERSHIP_TYPE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "OPEN_15P_FLAG" BOOLEAN, "CLOSED_BEFORE_PERIOD_END_FLAG" BOOLEAN, "OPEN_AFTER_HONEYMOON_FLAG" BOOLEAN, "WEEKDAY_OFFSET" ARRAY, "WEEK_TRANS_CNTS" ARRAY, "WEEK_NET_SALES" ARRAY, "IS_XMAS_THANKSGIVING" BOOLEAN, "DAY_OF_WEEK" VARCHAR(10), "END_DT" DATE, "TEMP_CLOSED_FLAG" BOOLEAN)
LANGUAGE SQL
AS '

WITH COMP_DATE AS 
(
 SELECT  
       s.calendar_dt -- comparison date
    ,  MAX_OPEN_DT -- ODI-53 maximum open date for which the store will be comp when reporting at BUSINESS_DATE
    ,  MAX_HONEY_DT -- ODI-199 maximum open date for which the store will be out of honeymoon period (3 full fiscal periods) at BUSINESS_DATE
FROM TABLE(FLASH_SUMMARY_COMP_HONEYMOON_without_threshold(BUSINESS_DATE,TIME_INTERVAL)) as s
),

SLS AS (
    select * from IDS_DEV.DATASTORE.DAILY_FLASH_SALES_STG as STG where SESSION_NO = CURRENT_SESSION() and STG.TIME_INTERVAL = TIME_INTERVAL
),
OT AS (
    SELECT 
      BRAND_ID
    , STORE_ID
    , OWNERSHIP_TYPE
    , DMA_CODE
    , DMA_NAME
    FROM IDS_DEV.DATASTORE.DAILY_FLASH_SALES_STG as STG
    WHERE SESSION_NO = CURRENT_SESSION() and STG.TIME_INTERVAL = TIME_INTERVAL
    QUALIFY ROW_NUMBER() OVER (PARTITION BY STORE_ID, BRAND_ID ORDER BY BUSINESS_DT DESC) = 1
),

QTD AS (
SELECT   --ODI-2392 
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT 
    , SUM(Trans_Cnt) as Trans_Cnt
    , SUM(Net_Sales) as Net_Sales
    , SUM(CASE WHEN 
        SLS.FISCAL_WEEK_NBR = 53 
        THEN 0 ELSE 
        Trans_Cnt END) as Comp_Trans
    , SUM(CASE WHEN 
        SLS.FISCAL_WEEK_NBR = 53 
        THEN 0 ELSE 
        Net_Sales END) as Comp_Sales
    , BDT.FISCAL_QUARTER_START_DT AGG_START_DT
    , ''QTD'' AS Agg_Level
    , OT.DMA_NAME 
    , OT.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , MAX(nvl(OPEN_DATE, MAX_OPEN_DT)) <= MAX(MAX_OPEN_DT) as OPEN_15P_FLAG -- ODI-53
    , NULL as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , MAX(nvl(SLS.OPEN_DATE, COMP_DATE.MAX_HONEY_DT)) <= MAX(COMP_DATE.MAX_HONEY_DT) as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , max(BDT.FISCAL_QUARTER_END_DT) as END_DT
FROM 
    SLS
INNER JOIN 
    OT
ON OT.BRAND_ID = SLS.BRAND_ID
AND OT.STORE_ID = SLS.STORE_ID
INNER JOIN 
    COMP_DATE
ON  SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN IDS_DEV.INT_REF.COMP_DATES BDT
ON BDT.CALENDAR_DT = COMP_DATE.CALENDAR_DT 
AND BDT.TIME_INTERVAL = TIME_INTERVAL
AND BDT.BUSINESS_DT = BUSINESS_DATE
WHERE 
    SLS.BUSINESS_DT >= BDT.FISCAL_QUARTER_START_DT
AND SLS.BUSINESS_DT <= 
                        iff(TIME_INTERVAL <> ''CY''
                            , least(COMP_DATE.CALENDAR_DT, BDT.FISCAL_QUARTER_END_DT)
                            , COMP_DATE.CALENDAR_DT
                        )
GROUP BY    
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT
    , ''QTD'' 
    , OT.DMA_NAME 
    , OT.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , BDT.FISCAL_QUARTER_START_DT
    , BDT.FISCAL_WEEK_NBR
),

YTD AS (
SELECT --ODI-2480
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT 
    , SUM(Trans_Cnt) AS Trans_Cnt
    , SUM(Net_Sales) AS Net_Sales
    , SUM(CASE WHEN 
        SLS.FISCAL_WEEK_NBR = 53 
        THEN 0 ELSE 
        Trans_Cnt END) as Comp_Trans
    , SUM(CASE WHEN 
        SLS.FISCAL_WEEK_NBR = 53 
        THEN 0 ELSE 
        Net_Sales END) as Comp_Sales
    , BDT.FISCAL_YEAR_START_DT AGG_START_DT
    , ''YTD'' AS Agg_Level
    , OT.DMA_NAME 
    , OT.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , MAX(nvl(OPEN_DATE, MAX_OPEN_DT)) <= MAX(MAX_OPEN_DT) as OPEN_15P_FLAG -- ODI-53
    , NULL as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , MAX(nvl(SLS.OPEN_DATE, COMP_DATE.MAX_HONEY_DT)) <= MAX(COMP_DATE.MAX_HONEY_DT) as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , max(BDT.FISCAL_YEAR_END_DT) as END_DT
FROM 
    SLS
INNER JOIN 
    OT
ON OT.BRAND_ID = SLS.BRAND_ID
AND OT.STORE_ID = SLS.STORE_ID
INNER JOIN 
    COMP_DATE
ON  SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN IDS_DEV.INT_REF.COMP_DATES BDT
ON BDT.CALENDAR_DT = COMP_DATE.CALENDAR_DT 
AND BDT.TIME_INTERVAL = TIME_INTERVAL
AND BDT.BUSINESS_DT = BUSINESS_DATE
WHERE 
    SLS.BUSINESS_DT >= BDT.FISCAL_YEAR_START_DT
AND SLS.BUSINESS_DT <=
                        iff(TIME_INTERVAL <> ''CY''
                            , least(COMP_DATE.CALENDAR_DT, BDT.FISCAL_QUARTER_END_DT)
                            , COMP_DATE.CALENDAR_DT
                        )
GROUP BY    
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT
    , ''YTD'' 
    , OT.DMA_NAME 
    , OT.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , BDT.FISCAL_YEAR_START_DT
    , BDT.FISCAL_WEEK_NBR
)
--CDTD AS   --ODI-2289 + ODI-906

SELECT 
      BRAND_ID
    , STORE_ID
    , BUSINESS_DT
    , Trans_Cnt
    , Net_Sales
    , Comp_Trans
    , Comp_Sales
    , AGG_START_DT
    , AGG_LEVEL
    , DMA_NAME 
    , DMA_CODE
    , OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , OPEN_15P_FLAG -- ODI-53
    , CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , WEEKDAY_OFFSET --ODI-2977
    , WEEK_TRANS_CNTS --ODI-2977
    , WEEK_NET_SALES --ODI-2977
    , IS_XMAS_THANKSGIVING --ODI-3039
    , DAY_OF_WEEK --ODI-3551
    , END_DT
    , NULL AS TEMP_CLOSED_FLAG
FROM 
    table(FLASH_SUMMARY_COMP_DAY_without_threshold(BUSINESS_DATE,TIME_INTERVAL))

UNION ALL



SELECT  --ODI-2123
      YTD.BRAND_ID
    , YTD.STORE_ID
    , YTD.CALENDAR_DT 
    , YTD.Trans_Cnt
    , YTD.Net_Sales
    , YTD.Comp_Trans  
      - SUM(CASE WHEN PTD_ALL.Comp_Sales IS NULL 
      OR PTD_ALL.Comp_Sales = 0
      OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG 
      OR PTD_ALL.TEMP_CLOSED_FLAG
      THEN nvl(PTD_ALL.Comp_Trans, 0) ELSE 0 END) AS Comp_Trans
    , YTD.Comp_Sales
      - SUM(CASE WHEN PTD_ALL.Comp_Sales IS NULL 
      OR PTD_ALL.Comp_Sales = 0
      OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG 
      OR PTD_ALL.TEMP_CLOSED_FLAG
      THEN nvl(PTD_ALL.Comp_Sales, 0) ELSE 0 END) AS Comp_Sales
    , YTD.AGG_START_DT
    , YTD.Agg_Level
    , YTD.DMA_NAME 
    , YTD.DMA_CODE
    , YTD.OWNERSHIP_TYPE
    , YTD.STATE
    , YTD.COUNTRY
    , YTD.OPEN_15P_FLAG -- ODI-53
    , YTD.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , YTD.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , NULL as WEEKDAY_OFFSET --ODI-2977
    , NULL as WEEK_TRANS_CNTS --ODI-2977
    , NULL as WEEK_NET_SALES --ODI-2977
    , NULL as IS_XMAS_THANKSGIVING --ODI-3039
    , NULL as DAY_OF_WEEK --ODI-3551
    , max(YTD.END_DT) as END_DT
    , NULL AS TEMP_CLOSED_FLAG
FROM YTD
LEFT JOIN table(FLASH_SUMMARY_COMP_PAST_WEEKS_without_threshold(BUSINESS_DATE,TIME_INTERVAL)) PTD_ALL
ON YTD.BRAND_ID  = PTD_ALL.BRAND_ID
AND YTD.STORE_ID = PTD_ALL.STORE_ID
AND YTD.CALENDAR_DT = PTD_ALL.BUSINESS_DT
AND YTD.AGG_START_DT <= PTD_ALL.FISCAL_PERIOD_START_DT
AND PTD_ALL.NET_SALES IS NOT NULL
AND (PTD_ALL.COMP_SALES IS NULL or PTD_ALL.COMP_SALES = 0
OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG
OR TEMP_CLOSED_FLAG)
GROUP BY 
      YTD.BRAND_ID
    , YTD.STORE_ID
    , YTD.CALENDAR_DT 
    , YTD.Trans_Cnt
    , YTD.Net_Sales
    , YTD.AGG_START_DT
    , YTD.Agg_Level
    , YTD.DMA_NAME 
    , YTD.DMA_CODE
    , YTD.OWNERSHIP_TYPE
    , YTD.STATE
    , YTD.COUNTRY
    , YTD.OPEN_15P_FLAG -- ODI-53
    , YTD.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , YTD.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , YTD.Comp_Trans
    , YTD.Comp_Sales

UNION ALL


SELECT  --ODI-2123
      QTD.BRAND_ID
    , QTD.STORE_ID
    , QTD.CALENDAR_DT 
    , QTD.Trans_Cnt
    , QTD.Net_Sales
    , QTD.Comp_Trans 
      - SUM(CASE WHEN PTD_ALL.Comp_Sales IS NULL 
      OR PTD_ALL.Comp_Sales = 0
      OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG 
      OR PTD_ALL.TEMP_CLOSED_FLAG
      THEN nvl(PTD_ALL.Comp_Trans, 0) ELSE 0 END) AS Comp_Trans
    , QTD.Comp_Sales 
      - SUM(CASE WHEN PTD_ALL.Comp_Sales IS NULL 
      OR PTD_ALL.Comp_Sales = 0
      OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG 
      OR PTD_ALL.TEMP_CLOSED_FLAG
      THEN nvl(PTD_ALL.Comp_Sales, 0) ELSE 0 END) AS Comp_Sales
    , QTD.AGG_START_DT
    , QTD.Agg_Level
    , QTD.DMA_NAME 
    , QTD.DMA_CODE
    , QTD.OWNERSHIP_TYPE
    , QTD.STATE
    , QTD.COUNTRY
    , QTD.OPEN_15P_FLAG -- ODI-53
    , QTD.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , QTD.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , NULL as WEEKDAY_OFFSET --ODI-2977
    , NULL as WEEK_TRANS_CNTS --ODI-2977
    , NULL as WEEK_NET_SALES --ODI-2977
    , NULL as IS_XMAS_THANKSGIVING --ODI-3039
    , NULL as DAY_OF_WEEK --ODI-3551
    , max(QTD.END_DT) as END_DT
    , NULL AS TEMP_CLOSED_FLAG
FROM QTD
LEFT JOIN table(FLASH_SUMMARY_COMP_PAST_WEEKS_without_threshold(BUSINESS_DATE,TIME_INTERVAL)) PTD_ALL
ON QTD.BRAND_ID  = PTD_ALL.BRAND_ID
AND QTD.STORE_ID = PTD_ALL.STORE_ID
AND QTD.CALENDAR_DT = PTD_ALL.BUSINESS_DT
AND QTD.AGG_START_DT <= PTD_ALL.FISCAL_PERIOD_START_DT
AND PTD_ALL.NET_SALES IS NOT NULL
AND (PTD_ALL.COMP_SALES IS NULL or PTD_ALL.COMP_SALES = 0
OR PTD_ALL.CLOSED_BEFORE_PERIOD_END_FLAG
OR TEMP_CLOSED_FLAG)
GROUP BY 
      QTD.BRAND_ID
    , QTD.STORE_ID
    , QTD.CALENDAR_DT 
    , QTD.Trans_Cnt
    , QTD.Net_Sales
    , QTD.AGG_START_DT
    , QTD.Agg_Level
    , QTD.DMA_NAME 
    , QTD.DMA_CODE
    , QTD.OWNERSHIP_TYPE
    , QTD.STATE
    , QTD.COUNTRY
    , QTD.OPEN_15P_FLAG -- ODI-53
    , QTD.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , QTD.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , QTD.Comp_Trans
    , QTD.Comp_Sales


UNION ALL

SELECT  --ODI-2123
      PTD.BRAND_ID
    , PTD.STORE_ID
    , CALENDAR_DT 
    , Trans_Cnt
    , Net_Sales
    , CASE WHEN CLOSED_BEFORE_PERIOD_END_FLAG
      OR TEMP_CLOSED_FLAG 
      THEN 0 ELSE Comp_Trans END AS Comp_Trans
    , CASE WHEN CLOSED_BEFORE_PERIOD_END_FLAG
      OR TEMP_CLOSED_FLAG
      THEN 0 ELSE Comp_Sales END AS Comp_Sales
    , AGG_START_DT
    , Agg_Level
    , OT.DMA_NAME 
    , OT.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , STATE
    , COUNTRY
    , OPEN_15P_FLAG -- ODI-53
    , CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , NULL as WEEKDAY_OFFSET --ODI-2977
    , NULL as WEEK_TRANS_CNTS --ODI-2977
    , NULL as WEEK_NET_SALES --ODI-2977
    , NULL as IS_XMAS_THANKSGIVING --ODI-3039
    , NULL as DAY_OF_WEEK --ODI-3551
    , END_DT
    , TEMP_CLOSED_FLAG
FROM TABLE(FLASH_SUMMARY_COMP_PTD_without_threshold(BUSINESS_DATE,TIME_INTERVAL)) PTD
INNER JOIN 
    OT
ON OT.BRAND_ID = PTD.BRAND_ID
AND OT.STORE_ID = PTD.STORE_ID


UNION ALL
   
SELECT   --ODI-2403 
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT 
    , SUM(Trans_Cnt)
    , SUM(Net_Sales)
    , SUM(Trans_Cnt) as Comp_Trans
    , SUM(Net_Sales) as Comp_Sales
    , BDT.FISCAL_WEEK_START_DT AGG_START_DT
    , ''WTD'' AS Agg_Level
    , OT.DMA_NAME 
    , OT.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , MAX(nvl(OPEN_DATE, MAX_OPEN_DT)) <= MAX(MAX_OPEN_DT) as OPEN_15P_FLAG -- ODI-53
    , NULL as CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
    , MAX(nvl(SLS.OPEN_DATE, COMP_DATE.MAX_HONEY_DT)) <= MAX(COMP_DATE.MAX_HONEY_DT) as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
    , ARRAY_AGG(SLS.BUSINESS_DT - BDT.FISCAL_WEEK_START_DT) as WEEKDAY_OFFSET --ODI-2977
    , ARRAY_AGG(Trans_Cnt) as WEEK_TRANS_CNTS --ODI-2977
    , ARRAY_AGG(Net_Sales) as WEEK_NET_SALES --ODI-2977
    , max(hol.date_key is not null) as IS_XMAS_THANKSGIVING --ODI-3039
    , NULL as DAY_OF_WEEK --ODI-3551
    , max(BDT.FISCAL_WEEK_END_DT) as END_DT
    , NULL AS TEMP_CLOSED_FLAG
FROM 
    SLS
INNER JOIN 
    OT
ON OT.BRAND_ID = SLS.BRAND_ID
AND OT.STORE_ID = SLS.STORE_ID
INNER JOIN 
    COMP_DATE
ON SLS.BUSINESS_DT <= COMP_DATE.CALENDAR_DT
INNER JOIN IDS_DEV.INT_REF.COMP_DATES BDT
ON BDT.CALENDAR_DT = COMP_DATE.CALENDAR_DT 
AND BDT.TIME_INTERVAL = TIME_INTERVAL
AND BDT.BUSINESS_DT = BUSINESS_DATE
LEFT JOIN
    IDH_DEV.SHARED.HOLIDAY_DIM_V as hol
ON  SLS.BUSINESS_DT = TO_DATE(cast(hol.DATE_KEY as string), ''YYYYMMDD'')
AND hol.HOLIDAY_NM IN (''THANKSGIVING DAY'',''CHRISTMAS DAY'')
WHERE 
    SLS.BUSINESS_DT >= BDT.FISCAL_WEEK_START_DT
GROUP BY    
      SLS.BRAND_ID
    , SLS.STORE_ID
    , COMP_DATE.CALENDAR_DT
    , ''WTD'' 
    , OT.DMA_NAME 
    , OT.DMA_CODE
    , OT.OWNERSHIP_TYPE
    , SLS.STATE
    , SLS.COUNTRY
    , BDT.FISCAL_WEEK_START_DT
    , BDT.FISCAL_WEEK_NBR

';
CREATE FUNCTION IF NOT EXISTS INSPIRE_BRAND_FLASH_REPORT("BUSINESS_DATE" DATE)
RETURNS TABLE ("AGG_LEVEL" VARCHAR(16777216), "BUSINESS_DATE" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_NM" VARCHAR(16777216), "DMA_CD" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "DAY_OF_WEEK" VARCHAR(10), "START_DT_CY" DATE, "END_DT_CY" DATE, "NET_SALES_CY" NUMBER(38,2), "TRANS_CY" NUMBER(38,0), "COMP_SALES_CY" NUMBER(38,2), "COMP_TRANS_CY" NUMBER(38,0), "FISC_DATE_LY" DATE, "FISC_START_DT_LY" DATE, "FISC_END_DT_LY" DATE, "FISC_NET_SALES_LY" NUMBER(38,2), "FISC_TRANS_LY" NUMBER(38,0), "FISC_COMP_SALES_LY" NUMBER(38,2), "FISC_COMP_TRANS_LY" NUMBER(38,0), "CAL_COMP_DATE_LY" DATE, "CAL_COMP_START_DT_LY" DATE, "CAL_COMP_END_DT_LY" DATE, "CAL_NET_SALES_LY" NUMBER(38,2), "CAL_TRANS_LY" NUMBER(38,0), "CAL_COMP_SALES_LY" NUMBER(38,2), "CAL_COMP_TRANS_LY" NUMBER(38,0), "CAL_COMP_DATE_2Y" DATE, "CAL_COMP_START_DT_2Y" DATE, "CAL_COMP_END_DT_2Y" DATE, "CAL_NET_SALES_2Y" NUMBER(38,2), "CAL_TRANS_2Y" NUMBER(38,0), "CAL_COMP_SALES_2Y" NUMBER(38,2), "CAL_COMP_TRANS_2Y" NUMBER(38,0), "CAL_COMP_DATE_3Y" DATE, "CAL_COMP_START_DT_3Y" DATE, "CAL_COMP_END_DT_3Y" DATE, "CAL_NET_SALES_3Y" NUMBER(38,2), "CAL_TRANS_3Y" NUMBER(38,0), "CAL_COMP_SALES_3Y" NUMBER(38,2), "CAL_COMP_TRANS_3Y" NUMBER(38,0))
LANGUAGE SQL
AS '
  SELECT * FROM TABLE(INSPIRE_BRAND_FLASH_REPORT(BUSINESS_DATE, ''ALL'', ''Y''))
