        THEN
            calendar_three_years.Comp_Trans - EXCLUDE_FROM_ARRAY(calendar_three_years.WEEK_TRANS_CNTS, fiscal_curr_year.WEEK_TRANS_CNTS, fiscal_curr_year.WEEKDAY_OFFSET, calendar_three_years.WEEKDAY_OFFSET)
        WHEN fiscal_curr_year.AGG_LEVEL = ''PTD'' AND WP.CAL_3Y_TRANS IS NOT NULL
        THEN calendar_three_years.Comp_Trans  - WP.CAL_3Y_TRANS  --ODI-515
        WHEN fiscal_curr_year.AGG_LEVEL = ''YTD'' AND WY.CAL_3Y_TRANS IS NOT NULL
        THEN calendar_three_years.Comp_Trans  - WY.CAL_3Y_TRANS
        WHEN fiscal_curr_year.AGG_LEVEL = ''QTD'' AND WQ.CAL_3Y_TRANS IS NOT NULL
        THEN calendar_three_years.Comp_Trans  - WQ.CAL_3Y_TRANS
        ELSE calendar_three_years.Comp_Trans
    END
  END as Cal_Comp_Trans_3Y
  FROM 
  table(FLASH_SUMMARY_NO_COMP_FISCAL_F(BUSINESS_DATE, ''CY'', BRAND, THRESHOLD_FLG)) as fiscal_curr_year
  inner join IDS_DEV.INT_REF.COMP_CALENDAR dt
  on dt.CALENDAR_DT = fiscal_curr_year.business_dt
  left outer join 
  table(FLASH_SUMMARY_NO_COMP_FISCAL_F(BUSINESS_DATE,''FISC1Y'', BRAND, THRESHOLD_FLG)) as fiscal_last_year
  on dt.FISCAL_1YR_COMP_DT = fiscal_last_year.business_dt
  and fiscal_curr_year.store_id = fiscal_last_year.store_id
  and fiscal_curr_year.brand_id = fiscal_last_year.brand_id
  and fiscal_curr_year.AGG_LEVEL = fiscal_last_year.AGG_LEVEL
  left outer join 
  table(FLASH_SUMMARY_NO_COMP_FISCAL_F(BUSINESS_DATE,''CAL1Y'', BRAND, THRESHOLD_FLG)) as calendar_last_year
  on dt.CALENDAR_1YR_COMP_DT = calendar_last_year.business_dt
  and fiscal_curr_year.store_id = calendar_last_year.store_id
  and fiscal_curr_year.brand_id = calendar_last_year.brand_id
  and fiscal_curr_year.AGG_LEVEL = calendar_last_year.AGG_LEVEL
  left outer join 
  table(FLASH_SUMMARY_NO_COMP_FISCAL_F(BUSINESS_DATE,''CAL2Y'', BRAND, THRESHOLD_FLG)) as calendar_two_years
  on dt.CALENDAR_2YR_COMP_DT = calendar_two_years.business_dt
  and fiscal_curr_year.store_id = calendar_two_years.store_id
  and fiscal_curr_year.brand_id = calendar_two_years.brand_id
  and fiscal_curr_year.AGG_LEVEL = calendar_two_years.AGG_LEVEL
  left outer join 
  table(FLASH_SUMMARY_NO_COMP_FISCAL_F(BUSINESS_DATE,''CAL3Y'', BRAND, THRESHOLD_FLG)) as calendar_three_years
  on dt.CALENDAR_3YR_COMP_DT = calendar_three_years.business_dt
  and fiscal_curr_year.store_id = calendar_three_years.store_id
  and fiscal_curr_year.brand_id = calendar_three_years.brand_id
  and fiscal_curr_year.AGG_LEVEL = calendar_three_years.AGG_LEVEL
  left outer join 
  table(FLASH_SUMMARY_COMP_WEEKS_IN_PERIODS_F(BUSINESS_DATE, BRAND, THRESHOLD_FLG)) as WP
  on  fiscal_curr_year.store_id = WP.store_id
  and fiscal_curr_year.brand_id = WP.brand_id
  and fiscal_curr_year.AGG_START_DT = WP.FISCAL_PERIOD_START_DT
  AND fiscal_last_year.AGG_START_DT = WP.FISCAL_1YR_COMP_PERIOD_DT 
  AND calendar_last_year.AGG_START_DT = WP.CALENDAR_1YR_COMP_PERIOD_DT
  AND calendar_two_years.AGG_START_DT = NVL(WP.CALENDAR_2YR_COMP_PERIOD_DT,calendar_two_years.AGG_START_DT)
  AND calendar_three_years.AGG_START_DT = NVL(WP.CALENDAR_3YR_COMP_PERIOD_DT,calendar_three_years.AGG_START_DT)
  left outer join 
  table(FLASH_SUMMARY_COMP_WEEKS_IN_QUARTERS_F(BUSINESS_DATE, BRAND, THRESHOLD_FLG)) as WQ
  on   fiscal_curr_year.store_id = WQ.store_id
  and fiscal_curr_year.brand_id = WQ.brand_id
  and fiscal_curr_year.AGG_START_DT = WQ.FISCAL_QUARTER_START_DT
  AND fiscal_last_year.AGG_START_DT = WQ.FISCAL_1YR_COMP_QUARTER_DT 
  AND calendar_last_year.AGG_START_DT = WQ.CALENDAR_1YR_COMP_QUARTER_DT
  AND calendar_two_years.AGG_START_DT = NVL(WQ.CALENDAR_2YR_COMP_QUARTER_DT,calendar_two_years.AGG_START_DT)
  AND calendar_three_years.AGG_START_DT = NVL(WQ.CALENDAR_3YR_COMP_QUARTER_DT,calendar_three_years.AGG_START_DT)
  left outer join 
  table(FLASH_SUMMARY_COMP_WEEKS_IN_YEARS_F(BUSINESS_DATE, BRAND, THRESHOLD_FLG)) as WY
  on   fiscal_curr_year.store_id = WY.store_id
  and fiscal_curr_year.brand_id = WY.brand_id
  and fiscal_curr_year.AGG_START_DT = WY.FISCAL_YEAR_START_DT
  AND fiscal_last_year.AGG_START_DT = WY.FISCAL_1YR_COMP_YEAR_DT 
  AND calendar_last_year.AGG_START_DT = WY.CALENDAR_1YR_COMP_YEAR_DT
  AND calendar_two_years.AGG_START_DT = NVL(WY.CALENDAR_2YR_COMP_YEAR_DT,calendar_two_years.AGG_START_DT)
  AND calendar_three_years.AGG_START_DT = NVL(WY.CALENDAR_3YR_COMP_YEAR_DT,calendar_three_years.AGG_START_DT)
  left outer join 
  IDH_DEV.OPERATION.LOCATION_HIERARCHY_V lv 
  on  lv.LOCATION_ID = fiscal_curr_year.STORE_ID
  and lv.brand_id = fiscal_curr_year.brand_id
  order by 
  fiscal_curr_year.brand_id ASC, 
  fiscal_curr_year.store_id ASC,
  (case when fiscal_curr_year.AGG_LEVEL = ''DAY'' then 1
    when fiscal_curr_year.AGG_LEVEL = ''WTD'' then 2
    when fiscal_curr_year.AGG_LEVEL = ''PTD'' then 3
    when fiscal_curr_year.AGG_LEVEL = ''QTD'' then 4
    when fiscal_curr_year.AGG_LEVEL = ''YTD'' then 5 END) ASC,
  fiscal_curr_year.AGG_START_DT DESC
  ';
CREATE FUNCTION IF NOT EXISTS INSPIRE_BRAND_FLASH_REPORT_DEV_AG("BUSINESS_DATE" DATE)
RETURNS TABLE ("AGG_LEVEL" VARCHAR(16777216), "BUSINESS_DATE" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_NAME" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "IS_FRANCHISEE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "NET_SALES_CY" NUMBER(38,2), "TRANS_CY" NUMBER(38,0), "COMP_SALES_CY" NUMBER(38,2), "COMP_TRANS_CY" NUMBER(38,0), "FISC_DATE_LY" DATE, "FISC_NET_SALES_LY" NUMBER(38,2), "FISC_TRANS_LY" NUMBER(38,0), "FISC_COMP_SALES_LY" NUMBER(38,2), "FISC_COMP_TRANS_LY" NUMBER(38,0), "CAL_COMP_DATE_LY" DATE, "CAL_NET_SALES_LY" NUMBER(38,2), "CAL_TRANS_LY" NUMBER(38,0), "CAL_COMP_SALES_LY" NUMBER(38,2), "CAL_COMP_TRANS_LY" NUMBER(38,0), "CAL_COMP_DATE_2Y" DATE, "CAL_NET_SALES_2Y" NUMBER(38,2), "CAL_TRANS_2Y" NUMBER(38,0), "CAL_COMP_SALES_2Y" NUMBER(38,2), "CAL_COMP_TRANS_2Y" NUMBER(38,0), "CAL_COMP_DATE_3Y" DATE, "CAL_NET_SALES_3Y" NUMBER(38,2), "CAL_TRANS_3Y" NUMBER(38,0), "CAL_COMP_SALES_3Y" NUMBER(38,2), "CAL_COMP_TRANS_3Y" NUMBER(38,0))
LANGUAGE SQL
AS '

  select 
  fiscal_curr_year.AGG_LEVEL, 
  fiscal_curr_year.AGG_START_DT,
  fiscal_curr_year.BRAND_ID,
  fiscal_curr_year.STORE_ID,
  fiscal_curr_year.DMA_NAME,
  fiscal_curr_year.DMA_CODE,
  fiscal_curr_year.L1Name,
  fiscal_curr_year.L2Name,
  fiscal_curr_year.L3Name,
  fiscal_curr_year.L4Name,
  fiscal_curr_year.L5Name,
  fiscal_curr_year.OWNERSHIP_TYPE,
  fiscal_curr_year.STATE,
  fiscal_curr_year.COUNTRY,
  fiscal_curr_year.Net_Sales as Net_Sales_CY,
  fiscal_curr_year.Trans_Cnt as Trans_CY,
  CASE WHEN 
  fiscal_curr_year.Net_Sales = 0 AND NOT nvl(fiscal_curr_year.IS_XMAS_THANKSGIVING, false)
  OR fiscal_curr_year.Comp_Sales = 0
  OR NOT fiscal_curr_year.OPEN_15P_FLAG --ODI-53
  OR fiscal_curr_year.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
  THEN NULL 
  ELSE 
  fiscal_curr_year.Comp_Sales 
  END 
  as Comp_Sales_CY,
  CASE WHEN 
  fiscal_curr_year.Net_Sales = 0 AND NOT nvl(fiscal_curr_year.IS_XMAS_THANKSGIVING, false)
  OR fiscal_curr_year.Comp_Trans = 0
  OR NOT fiscal_curr_year.OPEN_15P_FLAG --ODI-53
  OR fiscal_curr_year.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
  THEN NULL 
  ELSE
  fiscal_curr_year.Comp_Trans 
  END 
  as Comp_Trans_CY,
  dates.FISCAL1YRCOMP_DATEID,
  fiscal_last_year.Net_Sales as Fc_Net_Sales_LY,
  fiscal_last_year.Trans_Cnt as Fc_Trans_LY,
  CASE WHEN 
  fiscal_curr_year.Net_Sales = 0 AND NOT nvl(fiscal_curr_year.IS_XMAS_THANKSGIVING, false)
  OR 
  fiscal_last_year.Net_Sales = 0 AND NOT nvl(fiscal_last_year.IS_XMAS_THANKSGIVING, false)
  OR 
  fiscal_curr_year.Comp_Sales IS NULL
  OR fiscal_last_year.Comp_Sales = 0
  OR NOT fiscal_curr_year.OPEN_15P_FLAG --ODI-53
  OR fiscal_curr_year.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
  THEN NULL 
  ELSE
    CASE
        WHEN --ODI-2977
            fiscal_curr_year.AGG_LEVEL = ''WTD''
            AND ARRAY_INTERSECTION(fiscal_curr_year.WEEKDAY_OFFSET, fiscal_last_year.WEEKDAY_OFFSET) IS NOT NULL
            AND fiscal_curr_year.AGG_START_DT + 6 <> BUSINESS_DATE
        THEN
            fiscal_last_year.Comp_Sales - EXCLUDE_FROM_ARRAY(fiscal_last_year.WEEK_NET_SALES, fiscal_curr_year.WEEK_NET_SALES, fiscal_curr_year.WEEKDAY_OFFSET, fiscal_last_year.WEEKDAY_OFFSET)
      
        WHEN fiscal_curr_year.AGG_LEVEL = ''YTD'' AND PY.FISC_1Y_SALES IS NOT NULL
        THEN fiscal_last_year.Comp_Sales - PY.FISC_1Y_SALES   --ODI-57
        WHEN fiscal_curr_year.AGG_LEVEL = ''QTD'' AND PQ.FISC_1Y_SALES IS NOT NULL
        THEN fiscal_last_year.Comp_Sales - PQ.FISC_1Y_SALES   --ODI-57
    ELSE
        fiscal_last_year.Comp_Sales
    END
  END 
  as Fc_Comp_Sales_LY,
  CASE WHEN 
  fiscal_curr_year.Net_Sales = 0 AND NOT nvl(fiscal_curr_year.IS_XMAS_THANKSGIVING, false)
  OR 
  fiscal_last_year.Net_Sales = 0 AND NOT nvl(fiscal_last_year.IS_XMAS_THANKSGIVING, false)
  OR 
  fiscal_curr_year.Comp_Sales IS NULL
  OR fiscal_last_year.Comp_Trans = 0
  OR NOT fiscal_curr_year.OPEN_15P_FLAG --ODI-53
  OR fiscal_curr_year.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
  THEN NULL 
  ELSE
    CASE
        WHEN --ODI-2977
            fiscal_curr_year.AGG_LEVEL = ''WTD''
            AND ARRAY_INTERSECTION(fiscal_curr_year.WEEKDAY_OFFSET, fiscal_last_year.WEEKDAY_OFFSET) IS NOT NULL
            AND fiscal_curr_year.AGG_START_DT + 6 <> BUSINESS_DATE
        THEN
            fiscal_last_year.Comp_Trans - EXCLUDE_FROM_ARRAY(fiscal_last_year.WEEK_TRANS_CNTS, fiscal_curr_year.WEEK_TRANS_CNTS, fiscal_curr_year.WEEKDAY_OFFSET, fiscal_last_year.WEEKDAY_OFFSET)
          
        WHEN fiscal_curr_year.AGG_LEVEL = ''YTD'' AND PY.FISC_1Y_TRANS IS NOT NULL
        THEN fiscal_last_year.Comp_Trans - PY.FISC_1Y_TRANS  --ODI-57
        WHEN fiscal_curr_year.AGG_LEVEL = ''QTD'' AND PQ.FISC_1Y_TRANS IS NOT NULL
        THEN fiscal_last_year.Comp_Trans - PQ.FISC_1Y_TRANS  --ODI-57
    ELSE
        fiscal_last_year.Comp_Trans
    END
  END 
  as Fc_Comp_Trans_LY,
  dates.CALENDAR1YRCOMP_DATEID,
  calendar_last_year.Net_Sales as Cal_Net_Sales_LY,
  calendar_last_year.Trans_Cnt as Cal_Trans_LY,
  CASE WHEN 
  fiscal_curr_year.Net_Sales = 0 AND NOT nvl(fiscal_curr_year.IS_XMAS_THANKSGIVING, false)
  OR 
  calendar_last_year.Net_Sales = 0 AND NOT nvl(calendar_last_year.IS_XMAS_THANKSGIVING, false)
  OR 
  fiscal_curr_year.Comp_Sales IS NULL 
  OR calendar_last_year.Comp_Sales = 0
  OR NOT fiscal_curr_year.OPEN_15P_FLAG --ODI-53
  OR fiscal_curr_year.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
  THEN NULL 
  ELSE
    CASE
        WHEN --ODI-2977
            fiscal_curr_year.AGG_LEVEL = ''WTD''
            AND ARRAY_INTERSECTION(fiscal_curr_year.WEEKDAY_OFFSET, calendar_last_year.WEEKDAY_OFFSET) IS NOT NULL
            AND fiscal_curr_year.AGG_START_DT + 6 <> BUSINESS_DATE
        THEN
            calendar_last_year.Comp_Sales - EXCLUDE_FROM_ARRAY(calendar_last_year.WEEK_NET_SALES, fiscal_curr_year.WEEK_NET_SALES, fiscal_curr_year.WEEKDAY_OFFSET, calendar_last_year.WEEKDAY_OFFSET)
        WHEN fiscal_curr_year.AGG_LEVEL = ''YTD'' AND PY.CAL_1Y_SALES IS NOT NULL
        THEN calendar_last_year.Comp_Sales - PY.CAL_1Y_SALES
        WHEN fiscal_curr_year.AGG_LEVEL = ''QTD'' AND PQ.CAL_1Y_SALES IS NOT NULL
        THEN calendar_last_year.Comp_Sales - PQ.CAL_1Y_SALES
    ELSE
        calendar_last_year.Comp_Sales
    END
  END as Cal_Comp_Sales_LY,
  CASE WHEN 
  fiscal_curr_year.Net_Sales = 0 AND NOT nvl(fiscal_curr_year.IS_XMAS_THANKSGIVING, false)
  OR 
  calendar_last_year.Net_Sales =0 AND NOT nvl(calendar_last_year.IS_XMAS_THANKSGIVING, false)
  OR 
  fiscal_curr_year.Comp_Sales IS NULL
  OR NOT fiscal_curr_year.OPEN_15P_FLAG --ODI-53
  OR fiscal_curr_year.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
  OR calendar_last_year.Comp_Trans = 0
  THEN NULL 
  ELSE
    CASE
        WHEN --ODI-2977
            fiscal_curr_year.AGG_LEVEL = ''WTD''
            AND ARRAY_INTERSECTION(fiscal_curr_year.WEEKDAY_OFFSET, calendar_last_year.WEEKDAY_OFFSET) IS NOT NULL
            AND fiscal_curr_year.AGG_START_DT + 6 <> BUSINESS_DATE
        THEN
            calendar_last_year.Comp_Trans - EXCLUDE_FROM_ARRAY(calendar_last_year.WEEK_TRANS_CNTS, fiscal_curr_year.WEEK_TRANS_CNTS, fiscal_curr_year.WEEKDAY_OFFSET, calendar_last_year.WEEKDAY_OFFSET)
    WHEN fiscal_curr_year.AGG_LEVEL = ''YTD'' AND PY.CAL_1Y_TRANS IS NOT NULL
    THEN calendar_last_year.Comp_Trans - PY.CAL_1Y_TRANS
    WHEN fiscal_curr_year.AGG_LEVEL = ''QTD'' AND PQ.CAL_1Y_TRANS IS NOT NULL
    THEN calendar_last_year.Comp_Trans - PQ.CAL_1Y_TRANS
    ELSE
        calendar_last_year.Comp_Trans 
    END
  END as Cal_Comp_Trans_LY,
  dates.CALENDAR2YRCOMP_DATEID,
  calendar_two_years.Net_Sales as Cal_Net_Sales_2Y,
  calendar_two_years.Trans_Cnt as Cal_Trans_2Y,
  CASE WHEN 
  fiscal_curr_year.Net_Sales = 0 AND NOT nvl(fiscal_curr_year.IS_XMAS_THANKSGIVING, false)
  OR   
  calendar_two_years.Net_Sales = 0 AND NOT nvl(calendar_two_years.IS_XMAS_THANKSGIVING, false)
  OR 
  fiscal_curr_year.Comp_Sales IS NULL
  OR calendar_two_years.Comp_Sales = 0
  OR NOT fiscal_curr_year.OPEN_15P_FLAG --ODI-53
  OR fiscal_curr_year.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
  OR NOT calendar_two_years.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
  THEN NULL 
  ELSE
    CASE
        WHEN --ODI-2977
            fiscal_curr_year.AGG_LEVEL = ''WTD''
            AND ARRAY_INTERSECTION(fiscal_curr_year.WEEKDAY_OFFSET, calendar_two_years.WEEKDAY_OFFSET) IS NOT NULL
            AND fiscal_curr_year.AGG_START_DT + 6 <> BUSINESS_DATE
        THEN
            calendar_two_years.Comp_Sales - EXCLUDE_FROM_ARRAY(calendar_two_years.WEEK_NET_SALES, fiscal_curr_year.WEEK_NET_SALES, fiscal_curr_year.WEEKDAY_OFFSET, calendar_two_years.WEEKDAY_OFFSET)
        WHEN fiscal_curr_year.AGG_LEVEL = ''YTD'' AND PY.CAL_2Y_SALES IS NOT NULL
        THEN calendar_two_years.Comp_Sales - PY.CAL_2Y_SALES
        WHEN fiscal_curr_year.AGG_LEVEL = ''QTD'' AND PQ.CAL_2Y_SALES IS NOT NULL
        THEN calendar_two_years.Comp_Sales - PQ.CAL_2Y_SALES
    ELSE
        calendar_two_years.Comp_Sales 
    END
  END 
  as Cal_Comp_Sales_2Y,
  CASE WHEN 
  fiscal_curr_year.Net_Sales = 0 AND NOT nvl(fiscal_curr_year.IS_XMAS_THANKSGIVING, false)
  OR
  calendar_two_years.Net_Sales = 0 AND NOT nvl(calendar_two_years.IS_XMAS_THANKSGIVING, false)
  OR 
  fiscal_curr_year.Comp_Sales IS NULL
  OR calendar_two_years.Comp_Trans = 0
  OR NOT fiscal_curr_year.OPEN_15P_FLAG --ODI-53
  OR fiscal_curr_year.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
  OR NOT calendar_two_years.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
  THEN NULL 
  ELSE
    CASE
        WHEN --ODI-2977
            fiscal_curr_year.AGG_LEVEL = ''WTD''
            AND ARRAY_INTERSECTION(fiscal_curr_year.WEEKDAY_OFFSET, calendar_two_years.WEEKDAY_OFFSET) IS NOT NULL
            AND fiscal_curr_year.AGG_START_DT + 6 <> BUSINESS_DATE
        THEN
            calendar_two_years.Comp_Trans - EXCLUDE_FROM_ARRAY(calendar_two_years.WEEK_TRANS_CNTS, fiscal_curr_year.WEEK_TRANS_CNTS, fiscal_curr_year.WEEKDAY_OFFSET, calendar_two_years.WEEKDAY_OFFSET)
        WHEN fiscal_curr_year.AGG_LEVEL = ''YTD'' AND PY.CAL_2Y_TRANS IS NOT NULL
        THEN calendar_two_years.Comp_Trans - PY.CAL_2Y_TRANS
        WHEN fiscal_curr_year.AGG_LEVEL = ''QTD'' AND PQ.CAL_2Y_TRANS IS NOT NULL
        THEN calendar_two_years.Comp_Trans - PQ.CAL_2Y_TRANS
    ELSE
        calendar_two_years.Comp_Trans 
    END
  END as Cal_Comp_Trans_2Y,
  dates.CALENDAR3YRCOMP_DATEID,
  calendar_three_years.Net_Sales as Cal_Net_Sales_3Y,
  calendar_three_years.Trans_Cnt as Cal_Trans_3Y,
  CASE WHEN 
  fiscal_curr_year.Net_Sales = 0 AND NOT nvl(fiscal_curr_year.IS_XMAS_THANKSGIVING, false)
  OR
  calendar_three_years.Net_Sales = 0 AND NOT nvl(calendar_three_years.IS_XMAS_THANKSGIVING, false)
  OR 
  fiscal_curr_year.Comp_Sales IS NULL
  OR calendar_three_years.Comp_Sales = 0
  OR NOT fiscal_curr_year.OPEN_15P_FLAG --ODI-53
  OR fiscal_curr_year.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
  OR NOT calendar_three_years.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
  THEN NULL 
  ELSE
    CASE
        WHEN --ODI-2977
            fiscal_curr_year.AGG_LEVEL = ''WTD''
            AND ARRAY_INTERSECTION(fiscal_curr_year.WEEKDAY_OFFSET, calendar_three_years.WEEKDAY_OFFSET) IS NOT NULL
            AND fiscal_curr_year.AGG_START_DT + 6 <> BUSINESS_DATE
        THEN
            calendar_three_years.Comp_Sales - EXCLUDE_FROM_ARRAY(calendar_three_years.WEEK_NET_SALES, fiscal_curr_year.WEEK_NET_SALES, fiscal_curr_year.WEEKDAY_OFFSET, calendar_three_years.WEEKDAY_OFFSET)
        WHEN fiscal_curr_year.AGG_LEVEL = ''YTD'' AND PY.CAL_3Y_SALES IS NOT NULL
        THEN calendar_three_years.Comp_Sales - PY.CAL_3Y_SALES
        WHEN fiscal_curr_year.AGG_LEVEL = ''QTD'' AND PQ.CAL_3Y_SALES IS NOT NULL
        THEN calendar_three_years.Comp_Sales - PQ.CAL_3Y_SALES
    ELSE
        calendar_three_years.Comp_Sales 
    END
  END as Cal_Comp_Sales_3Y,
  CASE WHEN 
  fiscal_curr_year.Net_Sales = 0 AND NOT nvl(fiscal_curr_year.IS_XMAS_THANKSGIVING, false)
  OR
  calendar_three_years.Net_Sales = 0 AND NOT nvl(calendar_three_years.IS_XMAS_THANKSGIVING, false)
  OR 
  fiscal_curr_year.Comp_Sales IS NULL
  OR calendar_three_years.Comp_Trans = 0
  OR NOT fiscal_curr_year.OPEN_15P_FLAG --ODI-53
  OR fiscal_curr_year.CLOSED_BEFORE_PERIOD_END_FLAG --ODI-55
  OR NOT calendar_three_years.OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
  THEN NULL 
  ELSE
    CASE
        WHEN --ODI-2977
            fiscal_curr_year.AGG_LEVEL = ''WTD''
            AND ARRAY_INTERSECTION(fiscal_curr_year.WEEKDAY_OFFSET, calendar_three_years.WEEKDAY_OFFSET) IS NOT NULL
            AND fiscal_curr_year.AGG_START_DT + 6 <> BUSINESS_DATE
        THEN
            calendar_three_years.Comp_Trans - EXCLUDE_FROM_ARRAY(calendar_three_years.WEEK_TRANS_CNTS, fiscal_curr_year.WEEK_TRANS_CNTS, fiscal_curr_year.WEEKDAY_OFFSET, calendar_three_years.WEEKDAY_OFFSET)
        WHEN fiscal_curr_year.AGG_LEVEL = ''YTD'' AND PY.CAL_3Y_TRANS IS NOT NULL
        THEN calendar_three_years.Comp_Trans  - PY.CAL_3Y_TRANS
        WHEN fiscal_curr_year.AGG_LEVEL = ''QTD'' AND PQ.CAL_3Y_TRANS IS NOT NULL
        THEN calendar_three_years.Comp_Trans  - PQ.CAL_3Y_TRANS
    ELSE
        calendar_three_years.Comp_Trans 
    END
  END as Cal_Comp_Trans_3Y
  FROM 
  table(FLASH_SUMMARY_NO_COMP_FISCAL_DEV_AG(BUSINESS_DATE, BUSINESS_DATE)) as fiscal_curr_year
  inner join IDS_DEV.DATASTORE.VW_COMP_CAL_DATE_3YR dt
  on dt.date_id = fiscal_curr_year.business_dt
  inner join IDS_DEV.DATASTORE.VW_COMP_CAL_DATE_3YR dates
  on dates.date_id = fiscal_curr_year.AGG_START_DT
  left outer join 
  table(FLASH_SUMMARY_NO_COMP_FISCAL_DEV_AG((select FISCAL1YRCOMP_DATEID from IDS_DEV.DATASTORE.VW_COMP_CAL_DATE_3YR where date_id = BUSINESS_DATE), BUSINESS_DATE)) as fiscal_last_year
  on dt.FISCAL1YRCOMP_DATEID = fiscal_last_year.business_dt
  and fiscal_curr_year.store_id = fiscal_last_year.store_id
  and fiscal_curr_year.brand_id = fiscal_last_year.brand_id
  and fiscal_curr_year.AGG_LEVEL = fiscal_last_year.AGG_LEVEL
  left outer join 
  table(FLASH_SUMMARY_NO_COMP_FISCAL_DEV_AG((select CALENDAR1YRCOMP_DATEID from IDS_DEV.DATASTORE.VW_COMP_CAL_DATE_3YR where date_id = BUSINESS_DATE), BUSINESS_DATE)) as calendar_last_year
  on dt.CALENDAR1YRCOMP_DATEID = calendar_last_year.business_dt
  and fiscal_curr_year.store_id = calendar_last_year.store_id
  and fiscal_curr_year.brand_id = calendar_last_year.brand_id
  and fiscal_curr_year.AGG_LEVEL = calendar_last_year.AGG_LEVEL
  left outer join 
  table(FLASH_SUMMARY_NO_COMP_FISCAL_DEV_AG((select CALENDAR2YRCOMP_DATEID from IDS_DEV.DATASTORE.VW_COMP_CAL_DATE_3YR where date_id = BUSINESS_DATE), BUSINESS_DATE)) as calendar_two_years
  on dt.CALENDAR2YRCOMP_DATEID = calendar_two_years.business_dt
  and fiscal_curr_year.store_id = calendar_two_years.store_id
  and fiscal_curr_year.brand_id = calendar_two_years.brand_id
  and fiscal_curr_year.AGG_LEVEL = calendar_two_years.AGG_LEVEL
  left outer join 
  table(FLASH_SUMMARY_NO_COMP_FISCAL_DEV_AG((select CALENDAR3YRCOMP_DATEID from IDS_DEV.DATASTORE.VW_COMP_CAL_DATE_3YR where date_id = BUSINESS_DATE), BUSINESS_DATE)) as calendar_three_years
  on dt.CALENDAR3YRCOMP_DATEID = calendar_three_years.business_dt
  and fiscal_curr_year.store_id = calendar_three_years.store_id
  and fiscal_curr_year.brand_id = calendar_three_years.brand_id
  and fiscal_curr_year.AGG_LEVEL = calendar_three_years.AGG_LEVEL
  left outer join 
  table(FLASH_SUMMARY_COMP_PERIODS_IN_YEARS(BUSINESS_DATE)) as PY
  on   fiscal_curr_year.store_id = PY.store_id
  and fiscal_curr_year.brand_id = PY.brand_id
  and fiscal_curr_year.AGG_START_DT = PY.FISCAL_YEAR_START_DT
  left outer join 
  table(FLASH_SUMMARY_COMP_PERIODS_IN_QUARTERS(BUSINESS_DATE)) as PQ
  on   fiscal_curr_year.store_id = PQ.store_id
  and fiscal_curr_year.brand_id = PQ.brand_id
  and fiscal_curr_year.AGG_START_DT = PQ.FISCAL_QUARTER_START_DT
  order by 
  fiscal_curr_year.brand_id ASC, 
  fiscal_curr_year.store_id ASC,
  (case when fiscal_curr_year.AGG_LEVEL = ''DY'' then 1
    when fiscal_curr_year.AGG_LEVEL = ''WTD'' then 2
    when fiscal_curr_year.AGG_LEVEL = ''PTD'' then 3
    when fiscal_curr_year.AGG_LEVEL = ''QTD'' then 4
    when fiscal_curr_year.AGG_LEVEL = ''YTD'' then 5 END) ASC,
  fiscal_last_year.business_dt DESC
  ';
CREATE FUNCTION IF NOT EXISTS INSPIRE_BRAND_FLASH_REPORT_V("BUSINESS_DATE" DATE)
RETURNS TABLE ("AGG_LEVEL" VARCHAR(16777216), "BUSINESS_DATE" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_NAME" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "IS_FRANCHISEE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "NET_SALES_CY" NUMBER(38,2), "TRANS_CY" NUMBER(38,0), "COMP_SALES_CY" NUMBER(38,2), "COMP_TRANS_CY" NUMBER(38,0), "FISC_DATE_LY" DATE, "FISC_NET_SALES_LY" NUMBER(38,2), "FISC_TRANS_LY" NUMBER(38,0), "FISC_COMP_SALES_LY" NUMBER(38,2), "FISC_COMP_TRANS_LY" NUMBER(38,0), "CAL_COMP_DATE_LY" DATE, "CAL_NET_SALES_LY" NUMBER(38,2), "CAL_TRANS_LY" NUMBER(38,0), "CAL_COMP_SALES_LY" NUMBER(38,2), "CAL_COMP_TRANS_LY" NUMBER(38,0), "CAL_COMP_DATE_2Y" DATE, "CAL_NET_SALES_2Y" NUMBER(38,2), "CAL_TRANS_2Y" NUMBER(38,0), "CAL_COMP_SALES_2Y" NUMBER(38,2), "CAL_COMP_TRANS_2Y" NUMBER(38,0), "CAL_COMP_DATE_3Y" DATE, "CAL_NET_SALES_3Y" NUMBER(38,2), "CAL_TRANS_3Y" NUMBER(38,0), "CAL_COMP_SALES_3Y" NUMBER(38,2), "CAL_COMP_TRANS_3Y" NUMBER(38,0))
LANGUAGE SQL
AS '

  select 
  fiscal_curr_year.AGG_LEVEL, 
  fiscal_curr_year.AGG_START_DT,
  fiscal_curr_year.BRAND_ID,
  fiscal_curr_year.STORE_ID,
  fiscal_curr_year.DMA_NAME,
  fiscal_curr_year.DMA_CODE,
  fiscal_curr_year.L1Name,
  fiscal_curr_year.L2Name,
  fiscal_curr_year.L3Name,
  fiscal_curr_year.L4Name,
  fiscal_curr_year.L5Name,
  fiscal_curr_year.OWNERSHIP_TYPE,
  fiscal_curr_year.STATE,
  fiscal_curr_year.COUNTRY,
  fiscal_curr_year.FY_Net_Sales_Day as Net_Sales_CY,
  fiscal_curr_year.FY_Net_Trans_Cnt_Day as Trans_CY,
  fiscal_curr_year.FY_Comp_Sales_Day as Comp_Sales_CY,
  fiscal_curr_year.FY_Comp_Trans_Cnt_Day as Comp_Trans_CY,
  fiscal_last_year.AGG_START_DT,
  fiscal_last_year.FY_Net_Sales_Day as Fc_Net_Sales_LY,
  fiscal_last_year.FY_Net_Trans_Cnt_Day as Fc_Trans_LY,
  fiscal_last_year.FY_Comp_Sales_Day as Fc_Comp_Sales_LY,
  fiscal_last_year.FY_Comp_Trans_Cnt_Day as Fc_Comp_Trans_LY,
  calendar_last_year.AGG_START_DT,
  calendar_last_year.FY_Net_Sales_Day as Cal_Net_Sales_LY,
  calendar_last_year.FY_Net_Trans_Cnt_Day as Cal_Trans_LY,
  calendar_last_year.FY_Comp_Sales_Day as Cal_Comp_Sales_LY,
  calendar_last_year.FY_Comp_Trans_Cnt_Day as Cal_Comp_Trans_LY,
  calendar_two_years.AGG_START_DT,
  calendar_two_years.FY_Net_Sales_Day as Cal_Net_Sales_2Y,
  calendar_two_years.FY_Net_Trans_Cnt_Day as Cal_Trans_2Y,
  calendar_two_years.FY_Comp_Sales_Day as Cal_Comp_Sales_2Y,
  calendar_two_years.FY_Comp_Trans_Cnt_Day as Cal_Comp_Trans_2Y,
  calendar_three_years.AGG_START_DT,
  calendar_three_years.FY_Net_Sales_Day as Cal_Net_Sales_3Y,
  calendar_three_years.FY_Net_Trans_Cnt_Day as Cal_Trans_3Y,
  calendar_three_years.FY_Comp_Sales_Day as Cal_Comp_Sales_3Y,
  calendar_three_years.FY_Comp_Trans_Cnt_Day as Cal_Comp_Trans_3Y
  FROM 
  table(FLASH_SUMMARY_NO_COMP_FISCAL(BUSINESS_DATE)) as fiscal_curr_year
  inner join IDH_DEV.SHARED.VW_COMP_CAL_DATE_3YR dt
  on dt.date_id = fiscal_curr_year.business_dt
  left outer join 
  table(FLASH_SUMMARY_NO_COMP_FISCAL(select FISCAL1YRCOMP_DATEID from IDH_DEV.SHARED.VW_COMP_CAL_DATE_3YR where date_id = BUSINESS_DATE)) as fiscal_last_year
  on dt.FISCAL1YRCOMP_DATEID = fiscal_last_year.business_dt
  and fiscal_curr_year.store_id = fiscal_last_year.store_id
  and fiscal_curr_year.brand_id = fiscal_last_year.brand_id
  and fiscal_curr_year.AGG_LEVEL = fiscal_last_year.AGG_LEVEL
  left outer join 
  table(FLASH_SUMMARY_NO_COMP_FISCAL(select CALENDAR1YRCOMP_DATEID from IDH_DEV.SHARED.VW_COMP_CAL_DATE_3YR where date_id = BUSINESS_DATE)) as calendar_last_year
  on dt.CALENDAR1YRCOMP_DATEID = calendar_last_year.business_dt
  and fiscal_curr_year.store_id = calendar_last_year.store_id
  and fiscal_curr_year.brand_id = calendar_last_year.brand_id
  and fiscal_curr_year.AGG_LEVEL = calendar_last_year.AGG_LEVEL
  left outer join 
  table(FLASH_SUMMARY_NO_COMP_FISCAL(select CALENDAR2YRCOMP_DATEID from IDH_DEV.SHARED.VW_COMP_CAL_DATE_3YR where date_id = BUSINESS_DATE)) as calendar_two_years
  on dt.CALENDAR2YRCOMP_DATEID = calendar_two_years.business_dt
  and fiscal_curr_year.store_id = calendar_two_years.store_id
  and fiscal_curr_year.brand_id = calendar_two_years.brand_id
  and fiscal_curr_year.AGG_LEVEL = calendar_two_years.AGG_LEVEL
  left outer join 
  table(FLASH_SUMMARY_NO_COMP_FISCAL(select CALENDAR3YRCOMP_DATEID from IDH_DEV.SHARED.VW_COMP_CAL_DATE_3YR where date_id = BUSINESS_DATE)) as calendar_three_years
  on dt.CALENDAR3YRCOMP_DATEID = calendar_three_years.business_dt
  and fiscal_curr_year.store_id = calendar_three_years.store_id
  and fiscal_curr_year.brand_id = calendar_three_years.brand_id
  and fiscal_curr_year.AGG_LEVEL = calendar_three_years.AGG_LEVEL
  order by 
  fiscal_curr_year.brand_id ASC, 
  fiscal_curr_year.store_id ASC,
  (case when fiscal_curr_year.AGG_LEVEL = ''DY'' then 1
    when fiscal_curr_year.AGG_LEVEL = ''WTD'' then 2
    when fiscal_curr_year.AGG_LEVEL = ''PTD'' then 3
    when fiscal_curr_year.AGG_LEVEL = ''QTD'' then 4
    when fiscal_curr_year.AGG_LEVEL = ''YTD'' then 5 END) ASC,
  fiscal_last_year.business_dt DESC
  ';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_DAYPART_FLASH("FROM_DATE" DATE, "TO_DATE" DATE)
RETURNS TABLE ("AGG_LEVEL" VARCHAR(16777216), "BUSINESS_DATE" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_CD" VARCHAR(16777216), "DMA_NM" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "ADDRESS_1" VARCHAR(16777216), "ADDRESS_2" VARCHAR(16777216), "CITY" VARCHAR(16777216), "ZIP_CODE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "DAY_OF_WEEK" VARCHAR(16777216), "HOLIDAY_IND_CY" NUMBER(38,0), "HOLIDAY_NM_CY" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "CLOSED_HOUR" TIME(9), "IRB_DAYPART" VARCHAR(16777216), "BRAND_DAYPART" VARCHAR(16777216), "NET_SALES_CY" NUMBER(38,2), "TRANS_CY" NUMBER(38,0), "AVG_CHECK_CY" NUMBER(38,2), "COMP_SALES_CY" NUMBER(38,2), "COMP_TRANS_CY" NUMBER(38,0), "COMP_AVG_CHECK_CY" NUMBER(38,2), "FISC_DATE_LY" DATE, "FISC_HOLIDAY_IND_LY" NUMBER(38,0), "FISC_HOLIDAY_NM_LY" VARCHAR(16777216), "FISC_NET_SALES_LY" NUMBER(38,2), "FISC_TRANS_LY" NUMBER(38,0), "FISC_AVG_CHECK_LY" NUMBER(38,2), "FISC_COMP_SALES_LY" NUMBER(38,2), "FISC_COMP_TRANS_LY" NUMBER(38,0), "FISC_COMP_AVG_CHECK_LY" NUMBER(38,2), "CAL_COMP_DATE_LY" DATE, "CAL_HOLIDAY_IND_LY" NUMBER(38,0), "CAL_HOLIDAY_NM_LY" VARCHAR(16777216), "CAL_NET_SALES_LY" NUMBER(38,2), "CAL_TRANS_LY" NUMBER(38,0), "CAL_AVG_CHECK_LY" NUMBER(38,2), "CAL_COMP_SALES_LY" NUMBER(38,2), "CAL_COMP_TRANS_LY" NUMBER(38,0), "CAL_COMP_AVG_CHECK_LY" NUMBER(38,2), "CAL_COMP_DATE_2Y" DATE, "CAL_HOLIDAY_IND_2Y" NUMBER(38,0), "CAL_HOLIDAY_NM_2Y" VARCHAR(16777216), "CAL_NET_SALES_2Y" NUMBER(38,2), "CAL_TRANS_2Y" NUMBER(38,0), "CAL_AVG_CHECK_2Y" NUMBER(38,2), "CAL_COMP_SALES_2Y" NUMBER(38,2), "CAL_COMP_TRANS_2Y" NUMBER(38,0), "CAL_COMP_AVG_CHECK_2Y" NUMBER(38,2), "CAL_COMP_DATE_3Y" DATE, "CAL_HOLIDAY_IND_3Y" NUMBER(38,0), "CAL_HOLIDAY_NM_3Y" VARCHAR(16777216), "CAL_NET_SALES_3Y" NUMBER(38,2), "CAL_TRANS_3Y" NUMBER(38,0), "CAL_AVG_CHECK_3Y" NUMBER(38,2), "CAL_COMP_SALES_3Y" NUMBER(38,2), "CAL_COMP_TRANS_3Y" NUMBER(38,0), "CAL_COMP_AVG_CHECK_3Y" NUMBER(38,2))
LANGUAGE SQL
AS '

SELECT
    ''DAY'' AS AGG_LEVEL
    , BUSINESS_DATE
    , BRAND
    , STORE_NBR
    , DMA_CODE AS DMA_CD
    , DMA_NAME AS DMA_NM
    , L1Name
    , L2Name
    , L3Name
    , L4Name
    , L5Name
    , OWNERSHIP_TYP
    , ADDRESS_1
    , ADDRESS_2
    , CITY
    , ZIP_CODE
    , STATE
    , COUNTRY
    , DAY_OF_WEEK
    , HOLIDAY_IND_CY
    , HOLIDAY_NM_CY

    --current year
    , FISC_YEAR_NBR
    , FISC_QUARTER_NBR
    , FISC_PERIOD_NBR
    , FISC_WEEK_NBR
    , CLOSED_HOUR
    , IRB_DAYPART
    , BRAND_DAYPART
    , NET_SALES_CY
    , TRANS_CY
    , AVG_CHECK_CY
    , COMP_SALES_CY
    , COMP_TRANS_CY
    , COMP_AVG_CHECK_CY

    --fiscal last year
    , FISC_DATE_LY
    , FISC_HOLIDAY_IND_LY
    , FISC_HOLIDAY_NM_LY
    , FISC_NET_SALES_LY
    , FISC_TRANS_LY
    , FISC_AVG_CHECK_LY
    , FISC_COMP_SALES_LY
    , FISC_COMP_TRANS_LY
    , FISC_COMP_AVG_CHECK_LY

    --calendar last year
    , CAL_COMP_DATE_LY
    , CAL_HOLIDAY_IND_LY
    , CAL_HOLIDAY_NM_LY
    , CAL_NET_SALES_LY
    , CAL_TRANS_LY
    , CAL_AVG_CHECK_LY
    , CAL_COMP_SALES_LY
    , CAL_COMP_TRANS_LY
    , CAL_COMP_AVG_CHECK_LY

    --calendar 2 years
    , CAL_COMP_DATE_2Y
    , CAL_HOLIDAY_IND_2Y
    , CAL_HOLIDAY_NM_2Y
    , CAL_NET_SALES_2Y
    , CAL_TRANS_2Y
    , CAL_AVG_CHECK_2Y
    , CAL_COMP_SALES_2Y
    , CAL_COMP_TRANS_2Y
    , CAL_COMP_AVG_CHECK_2Y

    --calendar 3 years
    , CAL_COMP_DATE_3Y
    , CAL_HOLIDAY_IND_3Y
    , CAL_HOLIDAY_NM_3Y
    , CAL_NET_SALES_3Y
    , CAL_TRANS_3Y
    , CAL_AVG_CHECK_3Y
    , CAL_COMP_SALES_3Y
    , CAL_COMP_TRANS_3Y
    , CAL_COMP_AVG_CHECK_3Y
FROM table(DAYPART_FLASH_SUMMARY(FROM_DATE, TO_DATE, ''DAY_PART''))
ORDER BY 
    BRAND ASC, 
    STORE_NBR ASC,
    BUSINESS_DATE DESC,
    CLOSED_HOUR ASC
';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_DAYPART_FLASH_SUMMARY("FROM_DATE" DATE, "TO_DATE" DATE)
RETURNS TABLE ("BUSINESS_DATE" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "BRAND_DAY_PART_NM" VARCHAR(16777216), "IRB_DAY_PART_NM" VARCHAR(16777216), "CLOSED_HR" TIME(9), "DMA_CODE" VARCHAR(16777216), "DMA_NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "ADDRESS_1" VARCHAR(16777216), "ADDRESS_2" VARCHAR(16777216), "CITY" VARCHAR(16777216), "ZIP_CODE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "DAY_OF_WEEK" VARCHAR(16777216), "HOLIDAY_IND" NUMBER(38,0), "HOLIDAY_NM" VARCHAR(16777216), "NET_SALES" NUMBER(38,2), "TRANS" NUMBER(38,0), "NET_SALES_DAY" NUMBER(38,2), "TRANS_DAY" NUMBER(38,0), "COMP_STORE_CNT" NUMBER(38,0), "RN" NUMBER(38,0))
LANGUAGE SQL
AS '

WITH SUM_DAY AS
(
SELECT 
  dpsf.BUSINESS_DT
, dpsf.BRAND_ID
, dpsf.STORE_ID
, SUM(NVL(dpsf.Net_Sales, 0))               as NET_SALES_DAY
, SUM(NVL(dpsf.Trans_Cnt, 0))               as TRANS_DAY
FROM table(INSPIRE_DAILY_DAYPART_INIT(FROM_DATE , TO_DATE)) as dpsf
GROUP BY 
  dpsf.BUSINESS_DT
, dpsf.BRAND_ID
, dpsf.STORE_ID
)

SELECT
    bdt.CALENDAR_DT                         as BUSINESS_DATE
    , dpsf.BRAND_ID                         as BRAND
    , dpsf.STORE_ID                         as STORE_NBR
    , dpsf.BRAND_DAY_PART_NM                as BRAND_DAY_PART_NM
    , dpsf.IRB_DAY_PART_NM                  as IRB_DAY_PART_NM
    , dpsf.CLOSED_HR                        as CLOSED_HR
    , dpsf.DMA_CODE                         as DMA_CODE
    , dpsf.DMA_NAME                         as DMA_NAME
    , dpsf.OWNERSHIP_TYP                    as OWNERSHIP_TYP
    , dpsf.ADDRESS_1                        as ADDRESS_1
    , dpsf.ADDRESS_2                        as ADDRESS_2
    , dpsf.CITY                             as CITY
    , dpsf.ZIP_CD                           as ZIP_CODE
    , dpsf.STATE                            as STATE
    , dpsf.COUNTRY                          as COUNTRY
    , bdt.FISCAL_YEAR_NBR                   as FISC_YEAR_NBR
    , bdt.FISCAL_QUARTER_NBR                as FISC_QUARTER_NBR
    , bdt.FISCAL_PERIOD_NBR                 as FISC_PERIOD_NBR
    , bdt.FISCAL_WEEK_NBR                   as FISC_WEEK_NBR
    , bdt.CALENDAR_DAY_NM                   as DAY_OF_WEEK
    , iff(nvl(
        hol.HOLIDAY_IND
        , FALSE), 1, 0)                     as HOLIDAY_IND
    , hol.HOLIDAY_LIST_NM                   as HOLIDAY_NM
    , nvl(dpsf.Net_Sales, 0)                as NET_SALES
    , nvl(
        CASE
            WHEN nvl(dpsf.Net_Sales, 0) = 0
            THEN 0
            ELSE dpsf.Trans_Cnt
        END, 0)                             as TRANS
    , d.NET_SALES_DAY
    , d.TRANS_DAY
    , CASE
        WHEN d.NET_SALES_DAY = 0
            AND NOT nvl(
                    (ARRAY_CONTAINS(cast(''THANKSGIVING DAY'' as variant), split(hol.HOLIDAY_LIST_NM, '', ''))
                    OR ARRAY_CONTAINS(cast(''CHRISTMAS DAY'' as variant), split(hol.HOLIDAY_LIST_NM, '', '')))
                , FALSE
            )
        THEN 0
        WHEN NOT dpsf.OPEN_AFTER_HONEYMOON_FLAG OR NOT dpsf.OPEN_15P_FLAG
        THEN 0
        ELSE 1
    END                                     as COMP_STORE_CNT,
    ROW_NUMBER() OVER (PARTITION BY dpsf.BUSINESS_DT, dpsf.BRAND_ID, dpsf.STORE_ID ORDER BY dpsf.STORE_ID) as RN
FROM table(INSPIRE_DAILY_DAYPART_INIT(FROM_DATE,TO_DATE)) as dpsf
INNER JOIN SUM_DAY d
    on  dpsf.BUSINESS_DT = d.BUSINESS_DT
    and dpsf.BRAND_ID = d.BRAND_ID
    and dpsf.STORE_ID = d.STORE_ID
INNER JOIN IDH_DEV.SHARED.DATE_DIM_V as bdt
    on bdt.CALENDAR_DT = dpsf.BUSINESS_DT
LEFT JOIN IDH_DEV.SHARED.HOLIDAY_LIST_V as hol
    ON bdt.DATE_KEY = hol.DATE_KEY
';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_DAYPART_INIT("DATE_FROM" DATE, "DATE_TO" DATE)
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BRAND_DAY_PART_NM" VARCHAR(16777216), "IRB_DAY_PART_NM" VARCHAR(16777216), "CLOSED_HR" TIME(9), "BUSINESS_DT" DATE, "FISCAL_YEAR_NBR" NUMBER(38,0), "FISCAL_QUARTER_NBR" NUMBER(38,0), "FISCAL_PERIOD_NBR" NUMBER(38,0), "FISCAL_WEEK_NBR" NUMBER(38,0), "CALENDAR_DAY_NM" VARCHAR(16777216), "NET_SALES" NUMBER(38,2), "TRANS_CNT" NUMBER(38,0), "DMA_NAME" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "ADDRESS_1" VARCHAR(16777216), "ADDRESS_2" VARCHAR(16777216), "CITY" VARCHAR(16777216), "ZIP_CD" VARCHAR(16777216), "OPEN_15P_FLAG" BOOLEAN, "OPEN_AFTER_HONEYMOON_FLAG" BOOLEAN)
LANGUAGE SQL
AS '

with a as
(  
 select
 DATE_FROM,
 DATE_TO
),
DT as (
SELECT
DT.CALENDAR_DT,
DT.FISCAL_YEAR_NBR,
DT.FISCAL_QUARTER_NBR,
DT.FISCAL_PERIOD_NBR,
DT.FISCAL_WEEK_NBR,
DT.CALENDAR_DAY_NM  
FROM a
INNER join
IDH_DEV.SHARED.DATE_DIM_V DT
on DT.CALENDAR_DT BETWEEN A.DATE_FROM AND A.DATE_TO
),
ST as (
SELECT
DT.CALENDAR_DT,
DT.FISCAL_YEAR_NBR,
DT.FISCAL_QUARTER_NBR,
DT.FISCAL_PERIOD_NBR,
DT.FISCAL_WEEK_NBR,
DT.CALENDAR_DAY_NM,  
ST.STORE_ID,
ST.BRAND_ID,
st.DMA_NM,
st.DMA_CD,
st.OWNERSHIP_TYP,
st.STATE_NM,
st.COUNTRY_NM,
st.ADDRESS_1_TXT,
st.ADDRESS_2_TXT,
st.CITY_NM,
st.ZIP_CD,
ST.OPEN_DT
FROM DT
INNER JOIN IDH_DEV.SHARED.STORE_SCD_V ST  
ON DT.CALENDAR_DT >= ST.OPEN_DT
AND IFNULL(st.COUNTRY_NM, '''') in (''US'', ''USA'')
AND ST.CURRENT_IND = 1
)
SELECT
      ST.BRAND_ID
    , ST.STORE_ID
    , dfsf.BRAND_DAY_PART_NM
    , dfsf.IRB_DAY_PART_NM
    , dfsf.CLOSED_HR
    , ST.CALENDAR_DT
    , ST.FISCAL_YEAR_NBR
    , ST.FISCAL_QUARTER_NBR
    , ST.FISCAL_PERIOD_NBR
    , ST.FISCAL_WEEK_NBR
    , ST.CALENDAR_DAY_NM
    , sum(nvl(dfsf.NET_SALES_AMT, 0)) AS Net_Sales  /*ODI - 2289*/
    , iff(sum(nvl(dfsf.NET_SALES_AMT, 0)) = 0, 0, sum(nvl(dfsf.TRX_CNT, 0))) AS Trans_Cnt  /*ODI - 2289*/
    , IFNULL(st.DMA_NM, ''UNKNOWN'') AS DMA_NAME
    , IFNULL(st.DMA_CD, ''UNKNOWN'') AS DMA_CODE
    , IFNULL(st.OWNERSHIP_TYP, ''UNKNOWN'') AS OWNERSHIP_TYP
    , IFNULL(st.STATE_NM, ''UNKNOWN'') AS STATE
    , IFNULL(st.COUNTRY_NM, ''UNKNOWN'') AS COUNTRY
    , IFNULL(st.ADDRESS_1_TXT, ''UNKNOWN'') AS ADDRESS_1
    , IFNULL(st.ADDRESS_2_TXT, ''UNKNOWN'') AS ADDRESS_2  
    , IFNULL(st.CITY_NM, ''UNKNOWN'') AS CITY
    , IFNULL(st.ZIP_CD, ''UNKNOWN'') AS ZIP_CD
    , nvl(ST.OPEN_DT, opendt.calendar_dt) <= opendt.calendar_dt as OPEN_15P_FLAG -- ODI-53
    , nvl(ST.OPEN_DT, opendthoney.calendar_dt) <= opendthoney.calendar_dt as OPEN_AFTER_HONEYMOON_FLAG -- ODI-199
FROM ST
INNER JOIN 
    IDH_DEV.SHARED.DATE_DIM_V as opendt
    on opendt.calendar_dt = opendt.FISCAL_PERIOD_START_DT
    INNER JOIN IDH_DEV.SHARED.DATE_DIM_V as busdt
    on busdt.calendar_dt = ST.CALENDAR_DT
    and
        iff (opendt.FISCAL_PERIOD_START_DT = opendt.CALENDAR_DT
            , iff((opendt.FISCAL_PERIOD_NBR+15)%12 = 0, 12, (opendt.FISCAL_PERIOD_NBR+15)%12)
            , iff((opendt.FISCAL_PERIOD_NBR+16)%12 = 0, 12, (opendt.FISCAL_PERIOD_NBR+16)%12)
        ) = busdt.FISCAL_PERIOD_NBR
    and iff (opendt.FISCAL_PERIOD_START_DT = opendt.CALENDAR_DT
            , opendt.FISCAL_YEAR_NBR + trunc((opendt.FISCAL_PERIOD_NBR+14)/12)
            , opendt.FISCAL_YEAR_NBR + trunc((opendt.FISCAL_PERIOD_NBR+15)/12)
        ) = busdt.FISCAL_YEAR_NBR  
    INNER JOIN IDH_DEV.SHARED.DATE_DIM_V as opendthoney --ODI-199
    on
        iff ((opendthoney.FISCAL_PERIOD_NBR +
                iff(opendthoney.FISCAL_PERIOD_START_DT = opendthoney.CALENDAR_DT, 3, 4)
        ) % 12 = 0, 12, (opendthoney.FISCAL_PERIOD_NBR +
                iff(opendthoney.FISCAL_PERIOD_START_DT = opendthoney.CALENDAR_DT, 3, 4)
        ) % 12
        ) = busdt.FISCAL_PERIOD_NBR
    and 
        opendthoney.FISCAL_YEAR_NBR + trunc(
            (opendthoney.FISCAL_PERIOD_NBR +
                    iff(opendthoney.FISCAL_PERIOD_START_DT = opendthoney.CALENDAR_DT, 2, 3)
            ) / 12
        ) = busdt.FISCAL_YEAR_NBR
    and opendthoney.calendar_dt = opendthoney.FISCAL_PERIOD_START_DT
LEFT OUTER JOIN  IDS_DEV.DATASTORE.DAILY_DAY_PART_FLASH_SALES_FACT dfsf
ON  ST.STORE_ID = DFSF.STORE_ID
and ST.brand_id = DFSF.brand_id
AND ST.CALENDAR_DT = DFSF.BUSINESS_DT
GROUP BY
      ST.BRAND_ID
    , ST.STORE_ID
    , dfsf.BRAND_DAY_PART_NM
    , dfsf.IRB_DAY_PART_NM
    , dfsf.CLOSED_HR
    , ST.CALENDAR_DT
    , ST.FISCAL_YEAR_NBR
    , ST.FISCAL_QUARTER_NBR
    , ST.FISCAL_PERIOD_NBR
    , ST.FISCAL_WEEK_NBR
    , ST.CALENDAR_DAY_NM
    , st.DMA_NM
    , st.DMA_CD
    , st.OWNERSHIP_TYP
    , st.STATE_NM
    , st.COUNTRY_NM
    , st.ADDRESS_1_TXT
    , st.ADDRESS_2_TXT
    , st.CITY_NM
    , st.ZIP_CD
    , ST.OPEN_DT
    , opendt.calendar_dt
    , opendthoney.calendar_dt
';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_DAY_PART_FLASH("FROM_DATE" DATE, "TO_DATE" DATE)
RETURNS TABLE ("AGG_LEVEL" VARCHAR(16777216), "BUSINESS_DATE" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "BRAND_DAY_PART_NM" VARCHAR(16777216), "IRB_DAY_PART_NM" VARCHAR(16777216), "CLOSED_HR" TIME(9), "DMA_CODE" VARCHAR(16777216), "DMA_NAME" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "ADDRESS_1" VARCHAR(16777216), "ADDRESS_2" VARCHAR(16777216), "CITY" VARCHAR(16777216), "ZIP_CODE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "DAY_OF_WEEK" VARCHAR(16777216), "HOLIDAY_IND_CY" NUMBER(38,0), "HOLIDAY_NM_CY" VARCHAR(16777216), "NET_SALES_CY" NUMBER(38,2), "TRANS_CY" NUMBER(38,0), "AVG_CHECK_CY" NUMBER(38,2), "STORE_CNT_CY" NUMBER(38,0), "COMP_SALES_CY" NUMBER(38,2), "COMP_TRANS_CY" NUMBER(38,0), "COMP_AVG_CHECK_CY" NUMBER(38,2), "COMP_STORE_CNT_CY" NUMBER(38,0), "FISC_DATE_LY" DATE, "FISC_HOLIDAY_IND_LY" NUMBER(38,0), "FISC_HOLIDAY_NM_LY" VARCHAR(16777216), "FISC_NET_SALES_LY" NUMBER(38,2), "FISC_TRANS_LY" NUMBER(38,0), "FISC_AVG_CHECK_LY" NUMBER(38,2), "FISC_STORE_CNT_LY" NUMBER(38,0), "FISC_COMP_SALES_LY" NUMBER(38,2), "FISC_COMP_TRANS_LY" NUMBER(38,0), "FISC_COMP_AVG_CHECK_LY" NUMBER(38,2), "FISC_COMP_STORE_CNT_LY" NUMBER(38,0), "CAL_COMP_DATE_LY" DATE, "CAL_HOLIDAY_IND_LY" NUMBER(38,0), "CAL_HOLIDAY_NM_LY" VARCHAR(16777216), "CAL_NET_SALES_LY" NUMBER(38,2), "CAL_TRANS_LY" NUMBER(38,0), "CAL_AVG_CHECK_LY" NUMBER(38,2), "CAL_STORE_CNT_LY" NUMBER(38,0), "CAL_COMP_SALES_LY" NUMBER(38,2), "CAL_COMP_TRANS_LY" NUMBER(38,0), "CAL_COMP_AVG_CHECK_LY" NUMBER(38,2), "CAL_COMP_STORE_CNT_LY" NUMBER(38,0), "CAL_COMP_DATE_2Y" DATE, "CAL_HOLIDAY_IND_2Y" NUMBER(38,0), "CAL_HOLIDAY_NM_2Y" VARCHAR(16777216), "CAL_NET_SALES_2Y" NUMBER(38,2), "CAL_TRANS_2Y" NUMBER(38,0), "CAL_AVG_CHECK_2Y" NUMBER(38,2), "CAL_STORE_CNT_2Y" NUMBER(38,0), "CAL_COMP_SALES_2Y" NUMBER(38,2), "CAL_COMP_TRANS_2Y" NUMBER(38,0), "CAL_COMP_AVG_CHECK_2Y" NUMBER(38,2), "CAL_COMP_STORE_CNT_2Y" NUMBER(38,0), "CAL_COMP_DATE_3Y" DATE, "CAL_HOLIDAY_IND_3Y" NUMBER(38,0), "CAL_HOLIDAY_NM_3Y" VARCHAR(16777216), "CAL_NET_SALES_3Y" NUMBER(38,2), "CAL_TRANS_3Y" NUMBER(38,0), "CAL_AVG_CHECK_3Y" NUMBER(38,2), "CAL_STORE_CNT_3Y" NUMBER(38,0), "CAL_COMP_SALES_3Y" NUMBER(38,2), "CAL_COMP_TRANS_3Y" NUMBER(38,0), "CAL_COMP_AVG_CHECK_3Y" NUMBER(38,2), "CAL_COMP_STORE_CNT_3Y" NUMBER(38,0))
LANGUAGE SQL
AS '

SELECT
    ''DAY''                                           as AGG_LEVEL
    , cy.BUSINESS_DATE                              as BUSINESS_DATE
    , CASE WHEN UPPER(cy.BRAND) IN (''ARG'',''ARBYS'') THEN ''ARB''
       WHEN UPPER(cy.BRAND) IN (''BWW'') THEN ''BWW''
       WHEN UPPER(cy.BRAND) IN (''SDI'',''SONIC'') THEN ''SON''
       WHEN UPPER(cy.BRAND) IN (''JJ'') THEN ''JJ''
       WHEN UPPER(cy.BRAND) IN (''DNKN'') THEN ''DUN''
       WHEN UPPER(cy.BRAND) IN (''BSKN'') THEN ''BR''
       WHEN UPPER(cy.BRAND) IN (''RTO'') THEN ''RT''
       ELSE ''UNKNOWN''
       END                                          as BRAND
    , cy.STORE_NBR                                  as STORE_NBR
    , cy.BRAND_DAY_PART_NM                          as BRAND_DAY_PART_NM
    , cy.IRB_DAY_PART_NM                            as IRB_DAY_PART_NM
    , cy.CLOSED_HR                                  as CLOSED_HR
    , cy.DMA_CODE                                   as DMA_CODE
    , cy.DMA_NAME                                   as DMA_NAME
    , lv.LEVEL1_NM                                  as L1Name
    , lv.LEVEL2_NM                                  as L2Name
    , lv.LEVEL3_NM                                  as L3Name
    , lv.LEVEL4_NM                                  as L4Name
    , lv.LEVEL5_NM                                  as L5Name
    , cy.OWNERSHIP_TYP                              as OWNERSHIP_TYP
    , cy.ADDRESS_1                                  as ADDRESS_1
    , cy.ADDRESS_2                                  as ADDRESS_2
    , cy.CITY                                       as CITY
    , cy.ZIP_CODE                                   as ZIP_CODE
    , cy.STATE                                      as STATE
    , cy.COUNTRY                                    as COUNTRY

    --current year
    , cy.FISC_YEAR_NBR                              as FISC_YEAR_NBR
    , cy.FISC_QUARTER_NBR                           as FISC_QUARTER_NBR
    , cy.FISC_PERIOD_NBR                            as FISCAL_PERIOD_NBR
    , cy.FISC_WEEK_NBR                              as FISCAL_WEEK_NBR
    , cy.DAY_OF_WEEK                                as DAY_OF_WEEK
    , cy.HOLIDAY_IND                                as HOLIDAY_IND_CY
    , cy.HOLIDAY_NM                                 as HOLIDAY_NM_CY
    , cy.NET_SALES                                  as NET_SALES_CY
    , cy.TRANS                                      as TRANS_CY
    , iff(cy.TRANS > 0, cy.NET_SALES/cy.TRANS, 0)   as AVG_CHECK_CY
    , iff(cy.NET_SALES > 0, 1, 0)                   as STORE_CNT_CY
    , iff(cy.COMP_STORE_CNT = 1, cy.NET_SALES, 0)   as COMP_SALES_CY
    , iff(cy.COMP_STORE_CNT = 1, cy.TRANS, 0)       as COMP_TRANS_CY
    , iff(cy.COMP_STORE_CNT = 1 AND cy.TRANS > 0
        , cy.NET_SALES/cy.TRANS, 0)                 as COMP_AVG_CHECK_CY
    , cy.COMP_STORE_CNT                             as COMP_STORE_CNT_CY

    --fiscal last year
    , fly.BUSINESS_DATE                             as FISC_DATE_LY
    , fly.HOLIDAY_IND                               as FISC_HOLIDAY_IND_LY
    , fly.HOLIDAY_NM                                as FISC_HOLIDAY_NM_LY
    , fly.NET_SALES                                 as FISC_NET_SALES_LY
    , fly.TRANS                                     as FISC_TRANS_LY
    , iff(fly.TRANS > 0, fly.NET_SALES/fly.TRANS, 0)as FISC_AVG_CHECK_LY
    , iff(fly.NET_SALES > 0, 1, 0)                  as FISC_STORE_CNT_LY
    , iff(fly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
        , fly.NET_SALES, 0)                         as FISC_COMP_SALES_LY
    , iff(fly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
        , fly.TRANS, 0)                             as FISC_COMP_TRANS_LY
    , iff(fly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1 AND fly.TRANS > 0
        , fly.NET_SALES/fly.TRANS, 0)               as FISC_COMP_AVG_CHECK_LY
    , iff(cy.COMP_STORE_CNT = 1
        , fly.COMP_STORE_CNT, 0)                    as FISC_COMP_STORE_CNT_LY

    --calendar last year
    , cly.BUSINESS_DATE                             as CAL_COMP_DATE_LY
    , cly.HOLIDAY_IND                               as CAL_HOLIDAY_IND_LY
    , cly.HOLIDAY_NM                                as CAL_HOLIDAY_NM_LY
    , cly.NET_SALES                                 as CAL_NET_SALES_LY
    , cly.TRANS                                     as CAL_TRANS_LY
    , iff(cly.TRANS > 0, cly.NET_SALES/cly.TRANS, 0)as CAL_AVG_CHECK_LY
    , iff(cly.NET_SALES > 0, 1, 0)                  as CAL_STORE_CNT_LY
    , iff(cly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
        , cly.NET_SALES, 0)                         as CAL_COMP_SALES_LY
    , iff(cly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
        , cly.TRANS, 0)                             as CAL_COMP_TRANS_LY
    , iff(cly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1 AND cly.TRANS > 0
        , cly.NET_SALES/cly.TRANS, 0)               as CAL_COMP_AVG_CHECK_LY
    , iff(cy.COMP_STORE_CNT = 1
        , cly.COMP_STORE_CNT, 0)                    as CAL_COMP_STORE_CNT_LY

    --calendar 2 years
    , c2y.BUSINESS_DATE                             as CAL_COMP_DATE_2Y
    , c2y.HOLIDAY_IND                               as CAL_HOLIDAY_IND_2Y
    , c2y.HOLIDAY_NM                                as CAL_HOLIDAY_NM_2Y
    , c2y.NET_SALES                                 as CAL_NET_SALES_2Y
    , c2y.TRANS                                     as CAL_TRANS_2Y
    , iff(c2y.TRANS > 0, c2y.NET_SALES/c2y.TRANS, 0)as CAL_AVG_CHECK_2Y
    , iff(c2y.NET_SALES > 0, 1, 0)                  as CAL_STORE_CNT_2Y
    , iff(c2y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
        , c2y.NET_SALES, 0)                         as CAL_COMP_SALES_2Y
    , iff(c2y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
        , c2y.TRANS, 0)                             as CAL_COMP_TRANS_2Y
    , iff(c2y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1 AND c2y.TRANS > 0
        , c2y.NET_SALES/c2y.TRANS, 0)               as CAL_COMP_AVG_CHECK_2Y
    , iff(cy.COMP_STORE_CNT = 1
        , c2y.COMP_STORE_CNT, 0)                    as CAL_COMP_STORE_CNT_2Y

    --calendar 3 years
    , c3y.BUSINESS_DATE                             as CAL_COMP_DATE_3Y
    , c3y.HOLIDAY_IND                               as CAL_HOLIDAY_IND_3Y
    , c3y.HOLIDAY_NM                                as CAL_HOLIDAY_NM_3Y
    , c3y.NET_SALES                                 as CAL_NET_SALES_3Y
    , c3y.TRANS                                     as CAL_TRANS_3Y
    , iff(c3y.TRANS > 0, c3y.NET_SALES/c3y.TRANS, 0)as CAL_AVG_CHECK_3Y
    , iff(c3y.NET_SALES > 0, 1, 0)                  as CAL_STORE_CNT_3Y
    , iff(c3y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
        , c3y.NET_SALES, 0)                         as CAL_COMP_SALES_3Y
    , iff(c3y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
        , c3y.TRANS, 0)                             as CAL_COMP_TRANS_3Y
    , iff(c3y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1 AND c3y.TRANS > 0
        , c3y.NET_SALES/c3y.TRANS, 0)               as CAL_COMP_AVG_CHECK_3Y
    , iff(cy.COMP_STORE_CNT = 1
        , c3y.COMP_STORE_CNT, 0)                    as CAL_COMP_STORE_CNT_3Y
FROM table(INSPIRE_DAILY_DAY_PART_FLASH_SUMMARY(FROM_DATE, TO_DATE)) as cy
INNER JOIN IDS_DEV.INT_REF_BV.COMP_CALENDAR_BV as bdt
    on bdt.CALENDAR_DT = cy.BUSINESS_DATE
LEFT JOIN table(INSPIRE_DAILY_DAY_PART_FLASH_SUMMARY(
            SELECT FISCAL_1YR_COMP_DT FROM IDS_DEV.INT_REF_BV.COMP_CALENDAR_BV where CALENDAR_DT = FROM_DATE
            , SELECT FISCAL_1YR_COMP_DT FROM IDS_DEV.INT_REF_BV.COMP_CALENDAR_BV where CALENDAR_DT = TO_DATE
        )
    ) as fly
    on fly.BRAND = cy.BRAND
    and fly.STORE_NBR = cy.STORE_NBR
    and fly.BUSINESS_DATE = bdt.FISCAL_1YR_COMP_DT
LEFT JOIN table(INSPIRE_DAILY_DAY_PART_FLASH_SUMMARY(
            SELECT CALENDAR_1YR_COMP_DT FROM IDS_DEV.INT_REF_BV.COMP_CALENDAR_BV where CALENDAR_DT = FROM_DATE
            , SELECT CALENDAR_1YR_COMP_DT FROM IDS_DEV.INT_REF_BV.COMP_CALENDAR_BV where CALENDAR_DT = TO_DATE
        )
    ) as cly
    on cly.BRAND = cy.BRAND
    and cly.STORE_NBR = cy.STORE_NBR
    and cly.BUSINESS_DATE = bdt.CALENDAR_1YR_COMP_DT
LEFT JOIN table(INSPIRE_DAILY_DAY_PART_FLASH_SUMMARY(
            SELECT CALENDAR_2YR_COMP_DT FROM IDS_DEV.INT_REF_BV.COMP_CALENDAR_BV where CALENDAR_DT = FROM_DATE
            , SELECT CALENDAR_2YR_COMP_DT FROM IDS_DEV.INT_REF_BV.COMP_CALENDAR_BV where CALENDAR_DT = TO_DATE
        )
    ) as c2y
    on c2y.BRAND = cy.BRAND
    and c2y.STORE_NBR = cy.STORE_NBR
    and c2y.BUSINESS_DATE = bdt.CALENDAR_2YR_COMP_DT
LEFT JOIN table(INSPIRE_DAILY_DAY_PART_FLASH_SUMMARY(
            SELECT CALENDAR_3YR_COMP_DT FROM IDS_DEV.INT_REF_BV.COMP_CALENDAR_BV where CALENDAR_DT = FROM_DATE
            , SELECT CALENDAR_3YR_COMP_DT FROM IDS_DEV.INT_REF_BV.COMP_CALENDAR_BV where CALENDAR_DT = TO_DATE
        )
    ) as c3y
    on c3y.BRAND = cy.BRAND
    and c3y.STORE_NBR = cy.STORE_NBR
    and c3y.BUSINESS_DATE = bdt.CALENDAR_3YR_COMP_DT
LEFT JOIN IDH_DEV.OPERATION.LOCATION_HIERARCHY_V lv 
    on lv.LOCATION_ID = cy.STORE_NBR
    and lv.brand_id = cy.BRAND
ORDER BY 
    cy.BRAND ASC, 
    cy.STORE_NBR ASC,
    cy.BUSINESS_DATE DESC
';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_DAY_PART_FLASH_SUMMARY("FROM_DATE" DATE, "TO_DATE" DATE)
RETURNS TABLE ("BUSINESS_DATE" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "BRAND_DAY_PART_NM" VARCHAR(16777216), "IRB_DAY_PART_NM" VARCHAR(16777216), "CLOSED_HR" TIME(9), "DMA_CODE" VARCHAR(16777216), "DMA_NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "ADDRESS_1" VARCHAR(16777216), "ADDRESS_2" VARCHAR(16777216), "CITY" VARCHAR(16777216), "ZIP_CODE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "DAY_OF_WEEK" VARCHAR(16777216), "HOLIDAY_IND" NUMBER(38,0), "HOLIDAY_NM" VARCHAR(16777216), "NET_SALES" NUMBER(38,2), "TRANS" NUMBER(38,0), "NET_SALES_DAY" NUMBER(38,2), "TRANS_DAY" NUMBER(38,0), "COMP_STORE_CNT" NUMBER(38,0), "RN" NUMBER(38,0))
LANGUAGE SQL
AS '

WITH SUM_DAY AS
(
SELECT 
  dpsf.BUSINESS_DT
, dpsf.BRAND_ID
, dpsf.STORE_ID
, SUM(NVL(dpsf.Net_Sales, 0))               as NET_SALES_DAY
, SUM(NVL(dpsf.Trans_Cnt, 0))               as TRANS_DAY
FROM table(INSPIRE_DAILY_DAYPART_INIT(FROM_DATE , TO_DATE)) as dpsf
GROUP BY 
  dpsf.BUSINESS_DT
, dpsf.BRAND_ID
, dpsf.STORE_ID
)

SELECT
    bdt.CALENDAR_DT                         as BUSINESS_DATE
    , dpsf.BRAND_ID                         as BRAND
    , dpsf.STORE_ID                         as STORE_NBR
    , dpsf.BRAND_DAY_PART_NM                as BRAND_DAY_PART_NM
    , dpsf.IRB_DAY_PART_NM                  as IRB_DAY_PART_NM
    , dpsf.CLOSED_HR                        as CLOSED_HR
    , dpsf.DMA_CODE                         as DMA_CODE
    , dpsf.DMA_NAME                         as DMA_NAME
    , dpsf.OWNERSHIP_TYP                    as OWNERSHIP_TYP
    , dpsf.ADDRESS_1                        as ADDRESS_1
    , dpsf.ADDRESS_2                        as ADDRESS_2
    , dpsf.CITY                             as CITY
    , dpsf.ZIP_CD                           as ZIP_CODE
    , dpsf.STATE                            as STATE
    , dpsf.COUNTRY                          as COUNTRY
    , bdt.FISCAL_YEAR_NBR                   as FISC_YEAR_NBR
    , bdt.FISCAL_QUARTER_NBR                as FISC_QUARTER_NBR
    , bdt.FISCAL_PERIOD_NBR                 as FISC_PERIOD_NBR
    , bdt.FISCAL_WEEK_NBR                   as FISC_WEEK_NBR
    , bdt.CALENDAR_DAY_NM                   as DAY_OF_WEEK
    , iff(nvl(
        hol.HOLIDAY_IND
        , FALSE), 1, 0)                     as HOLIDAY_IND
    , hol.HOLIDAY_LIST_NM                   as HOLIDAY_NM
    , nvl(dpsf.Net_Sales, 0)                as NET_SALES
    , nvl(
        CASE
            WHEN nvl(dpsf.Net_Sales, 0) = 0
            THEN 0
            ELSE dpsf.Trans_Cnt
        END, 0)                             as TRANS
    , d.NET_SALES_DAY
    , d.TRANS_DAY
    , CASE
        WHEN d.NET_SALES_DAY = 0
            AND NOT nvl(
                    (ARRAY_CONTAINS(cast(''THANKSGIVING DAY'' as variant), split(hol.HOLIDAY_LIST_NM, '', ''))
                    OR ARRAY_CONTAINS(cast(''CHRISTMAS DAY'' as variant), split(hol.HOLIDAY_LIST_NM, '', '')))
                , FALSE
            )
        THEN 0
        WHEN NOT dpsf.OPEN_AFTER_HONEYMOON_FLAG OR NOT dpsf.OPEN_15P_FLAG
        THEN 0
        ELSE 1
    END                                     as COMP_STORE_CNT,
    ROW_NUMBER() OVER (PARTITION BY dpsf.BUSINESS_DT, dpsf.BRAND_ID, dpsf.STORE_ID ORDER BY dpsf.STORE_ID) as RN
FROM table(INSPIRE_DAILY_DAYPART_INIT(FROM_DATE,TO_DATE)) as dpsf
INNER JOIN SUM_DAY d
    on  dpsf.BUSINESS_DT = d.BUSINESS_DT
    and dpsf.BRAND_ID = d.BRAND_ID
    and dpsf.STORE_ID = d.STORE_ID
INNER JOIN IDH_DEV.SHARED.DATE_DIM_V as bdt
    on bdt.CALENDAR_DT = dpsf.BUSINESS_DT
LEFT JOIN IDH_DEV.SHARED.HOLIDAY_LIST_V as hol
    ON bdt.DATE_KEY = hol.DATE_KEY
';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_FLASH("FROM_DATE" DATE, "TO_DATE" DATE)
RETURNS TABLE ("AGG_LEVEL" VARCHAR(16777216), "BUSINESS_DATE" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_CD" VARCHAR(16777216), "DMA_NM" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "ADDRESS_1" VARCHAR(16777216), "ADDRESS_2" VARCHAR(16777216), "CITY" VARCHAR(16777216), "ZIP_CODE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "DAY_OF_WEEK" VARCHAR(16777216), "HOLIDAY_IND_CY" NUMBER(38,0), "HOLIDAY_NM_CY" VARCHAR(16777216), "NET_SALES_CY" NUMBER(38,2), "TRANS_CY" NUMBER(38,0), "AVG_CHECK_CY" NUMBER(38,2), "STORE_CNT_CY" NUMBER(38,0), "COMP_SALES_CY" NUMBER(38,2), "COMP_TRANS_CY" NUMBER(38,0), "COMP_AVG_CHECK_CY" NUMBER(38,2), "COMP_STORE_CNT_CY" NUMBER(38,0), "FISC_DATE_LY" DATE, "FISC_HOLIDAY_IND_LY" NUMBER(38,0), "FISC_HOLIDAY_NM_LY" VARCHAR(16777216), "FISC_NET_SALES_LY" NUMBER(38,2), "FISC_TRANS_LY" NUMBER(38,0), "FISC_AVG_CHECK_LY" NUMBER(38,2), "FISC_STORE_CNT_LY" NUMBER(38,0), "FISC_COMP_SALES_LY" NUMBER(38,2), "FISC_COMP_TRANS_LY" NUMBER(38,0), "FISC_COMP_AVG_CHECK_LY" NUMBER(38,2), "FISC_COMP_STORE_CNT_LY" NUMBER(38,0), "CAL_COMP_DATE_LY" DATE, "CAL_HOLIDAY_IND_LY" NUMBER(38,0), "CAL_HOLIDAY_NM_LY" VARCHAR(16777216), "CAL_NET_SALES_LY" NUMBER(38,2), "CAL_TRANS_LY" NUMBER(38,0), "CAL_AVG_CHECK_LY" NUMBER(38,2), "CAL_STORE_CNT_LY" NUMBER(38,0), "CAL_COMP_SALES_LY" NUMBER(38,2), "CAL_COMP_TRANS_LY" NUMBER(38,0), "CAL_COMP_AVG_CHECK_LY" NUMBER(38,2), "CAL_COMP_STORE_CNT_LY" NUMBER(38,0), "CAL_COMP_DATE_2Y" DATE, "CAL_HOLIDAY_IND_2Y" NUMBER(38,0), "CAL_HOLIDAY_NM_2Y" VARCHAR(16777216), "CAL_NET_SALES_2Y" NUMBER(38,2), "CAL_TRANS_2Y" NUMBER(38,0), "CAL_AVG_CHECK_2Y" NUMBER(38,2), "CAL_STORE_CNT_2Y" NUMBER(38,0), "CAL_COMP_SALES_2Y" NUMBER(38,2), "CAL_COMP_TRANS_2Y" NUMBER(38,0), "CAL_COMP_AVG_CHECK_2Y" NUMBER(38,2), "CAL_COMP_STORE_CNT_2Y" NUMBER(38,0), "CAL_COMP_DATE_3Y" DATE, "CAL_HOLIDAY_IND_3Y" NUMBER(38,0), "CAL_HOLIDAY_NM_3Y" VARCHAR(16777216), "CAL_NET_SALES_3Y" NUMBER(38,2), "CAL_TRANS_3Y" NUMBER(38,0), "CAL_AVG_CHECK_3Y" NUMBER(38,2), "CAL_STORE_CNT_3Y" NUMBER(38,0), "CAL_COMP_SALES_3Y" NUMBER(38,2), "CAL_COMP_TRANS_3Y" NUMBER(38,0), "CAL_COMP_AVG_CHECK_3Y" NUMBER(38,2), "CAL_COMP_STORE_CNT_3Y" NUMBER(38,0))
LANGUAGE SQL
AS '
    SELECT * FROM table(INSPIRE_DAILY_FLASH(FROM_DATE, TO_DATE, ''ALL''))
';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_FLASH("FROM_DATE" DATE, "TO_DATE" DATE, "BRAND_INPUT" VARCHAR(16777216))
RETURNS TABLE ("AGG_LEVEL" VARCHAR(16777216), "BUSINESS_DATE" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_CD" VARCHAR(16777216), "DMA_NM" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "ADDRESS_1" VARCHAR(16777216), "ADDRESS_2" VARCHAR(16777216), "CITY" VARCHAR(16777216), "ZIP_CODE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "DAY_OF_WEEK" VARCHAR(16777216), "HOLIDAY_IND_CY" NUMBER(38,0), "HOLIDAY_NM_CY" VARCHAR(16777216), "NET_SALES_CY" NUMBER(38,2), "TRANS_CY" NUMBER(38,0), "AVG_CHECK_CY" NUMBER(38,2), "STORE_CNT_CY" NUMBER(38,0), "COMP_SALES_CY" NUMBER(38,2), "COMP_TRANS_CY" NUMBER(38,0), "COMP_AVG_CHECK_CY" NUMBER(38,2), "COMP_STORE_CNT_CY" NUMBER(38,0), "FISC_DATE_LY" DATE, "FISC_HOLIDAY_IND_LY" NUMBER(38,0), "FISC_HOLIDAY_NM_LY" VARCHAR(16777216), "FISC_NET_SALES_LY" NUMBER(38,2), "FISC_TRANS_LY" NUMBER(38,0), "FISC_AVG_CHECK_LY" NUMBER(38,2), "FISC_STORE_CNT_LY" NUMBER(38,0), "FISC_COMP_SALES_LY" NUMBER(38,2), "FISC_COMP_TRANS_LY" NUMBER(38,0), "FISC_COMP_AVG_CHECK_LY" NUMBER(38,2), "FISC_COMP_STORE_CNT_LY" NUMBER(38,0), "CAL_COMP_DATE_LY" DATE, "CAL_HOLIDAY_IND_LY" NUMBER(38,0), "CAL_HOLIDAY_NM_LY" VARCHAR(16777216), "CAL_NET_SALES_LY" NUMBER(38,2), "CAL_TRANS_LY" NUMBER(38,0), "CAL_AVG_CHECK_LY" NUMBER(38,2), "CAL_STORE_CNT_LY" NUMBER(38,0), "CAL_COMP_SALES_LY" NUMBER(38,2), "CAL_COMP_TRANS_LY" NUMBER(38,0), "CAL_COMP_AVG_CHECK_LY" NUMBER(38,2), "CAL_COMP_STORE_CNT_LY" NUMBER(38,0), "CAL_COMP_DATE_2Y" DATE, "CAL_HOLIDAY_IND_2Y" NUMBER(38,0), "CAL_HOLIDAY_NM_2Y" VARCHAR(16777216), "CAL_NET_SALES_2Y" NUMBER(38,2), "CAL_TRANS_2Y" NUMBER(38,0), "CAL_AVG_CHECK_2Y" NUMBER(38,2), "CAL_STORE_CNT_2Y" NUMBER(38,0), "CAL_COMP_SALES_2Y" NUMBER(38,2), "CAL_COMP_TRANS_2Y" NUMBER(38,0), "CAL_COMP_AVG_CHECK_2Y" NUMBER(38,2), "CAL_COMP_STORE_CNT_2Y" NUMBER(38,0), "CAL_COMP_DATE_3Y" DATE, "CAL_HOLIDAY_IND_3Y" NUMBER(38,0), "CAL_HOLIDAY_NM_3Y" VARCHAR(16777216), "CAL_NET_SALES_3Y" NUMBER(38,2), "CAL_TRANS_3Y" NUMBER(38,0), "CAL_AVG_CHECK_3Y" NUMBER(38,2), "CAL_STORE_CNT_3Y" NUMBER(38,0), "CAL_COMP_SALES_3Y" NUMBER(38,2), "CAL_COMP_TRANS_3Y" NUMBER(38,0), "CAL_COMP_AVG_CHECK_3Y" NUMBER(38,2), "CAL_COMP_STORE_CNT_3Y" NUMBER(38,0))
LANGUAGE SQL
AS '

SELECT
    AGG_LEVEL
    , BUSINESS_DATE
    , BRAND
    , STORE_NBR
    , DMA_CODE AS DMA_CD
    , DMA_NAME AS DMA_NM
    , L1Name
    , L2Name
    , L3Name
    , L4Name
    , L5Name
    , OWNERSHIP_TYP
    , ADDRESS_1
    , ADDRESS_2 
    , CITY
    , ZIP_CODE
    , STATE
    , COUNTRY
    , FISC_YEAR_NBR
    , FISC_QUARTER_NBR
    , FISC_PERIOD_NBR
    , FISC_WEEK_NBR
