    , TRANS_CY
    , AVG_CHECK_CY
    , STORE_CNT_CY
    , COMP_SALES_CY
    , COMP_TRANS_CY
    , COMP_AVG_CHECK_CY
    , COMP_STORE_CNT_CY
    , FISC_DATE_LY
    , FISC_HOLIDAY_IND_LY
    , FISC_HOLIDAY_NM_LY
    , Fisc_Net_Sales_LY
    , Fisc_Trans_LY
    , FISC_AVG_CHECK_LY
    , FISC_STORE_CNT_LY
    , Fisc_Comp_Sales_LY
    , Fisc_Comp_Trans_LY
    , FISC_COMP_AVG_CHECK_LY
    , FISC_COMP_STORE_CNT_LY
    , CAL_COMP_DATE_LY
    , CAL_HOLIDAY_IND_LY
    , CAL_HOLIDAY_NM_LY
    , CAL_Net_Sales_LY
    , CAL_Trans_LY
    , CAL_AVG_CHECK_LY
    , CAL_STORE_CNT_LY
    , CAL_Comp_Sales_LY
    , CAL_Comp_Trans_LY
    , CAL_COMP_AVG_CHECK_LY
    , CAL_COMP_STORE_CNT_LY
    , CAL_COMP_DATE_2Y
    , CAL_HOLIDAY_IND_2Y
    , CAL_HOLIDAY_NM_2Y
    , CAL_Net_Sales_2Y
    , CAL_Trans_2Y
    , CAL_AVG_CHECK_2Y
    , CAL_STORE_CNT_2Y
    , CAL_Comp_Sales_2Y
    , CAL_Comp_Trans_2Y
    , CAL_COMP_AVG_CHECK_2Y
    , CAL_COMP_STORE_CNT_2Y
    , CAL_COMP_DATE_3Y
    , CAL_HOLIDAY_IND_3Y
    , CAL_HOLIDAY_NM_3Y
    , CAL_Net_Sales_3Y
    , CAL_Trans_3Y
    , CAL_AVG_CHECK_3Y
    , CAL_STORE_CNT_3Y
    , CAL_Comp_Sales_3Y
    , CAL_Comp_Trans_3Y
    , CAL_COMP_AVG_CHECK_3Y
    , CAL_COMP_STORE_CNT_3Y
FROM TABLE(DAYPART_FLASH_SUMMARY(FROM_DATE, TO_DATE, ''DAY'', BRAND_INPUT))
ORDER BY 
    BRAND ASC, 
    STORE_NBR ASC,
    BUSINESS_DATE DESC
';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_FLASH_SUMMARY("FROM_DATE" DATE, "TO_DATE" DATE)
RETURNS TABLE ("BUSINESS_DATE" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "DMA_NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "ADDRESS_1" VARCHAR(16777216), "ADDRESS_2" VARCHAR(16777216), "CITY" VARCHAR(16777216), "ZIP_CODE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "DAY_OF_WEEK" VARCHAR(16777216), "HOLIDAY_IND" NUMBER(38,0), "HOLIDAY_NM" VARCHAR(16777216), "NET_SALES" NUMBER(38,2), "TRANS" NUMBER(38,0), "COMP_STORE_CNT" NUMBER(38,0))
LANGUAGE SQL
AS '

SELECT
    bdt.CALENDAR_DT                         as BUSINESS_DATE
    , dpsf.BRAND_ID                         as BRAND
    , dpsf.STORE_ID                         as STORE_NBR
    , dpsf.DMA_CODE                         as DMA_CODE
    , dpsf.DMA_NAME                         as DMA_NAME
    , dpsf.OWNERSHIP_TYP                    as OWNERSHIP_TYP
    , dpsf.ADDRESS_1                        as ADDRESS_1
    , dpsf.ADDRESS_2                        as ADDRESS_2
    , dpsf.CITY                             as CITY
    , dpsf.ZIP_CD                           as ZIP_CODE
    , dpsf.STATE                            as STATE
    , dpsf.COUNTRY                          as COUNTRY
    , bdt.FISCAL_YEAR_NBR                   as FISC_YEAR_NBR
    , bdt.FISCAL_QUARTER_NBR                as FISC_QUARTER_NBR
    , bdt.FISCAL_PERIOD_NBR                 as FISC_PERIOD_NBR
    , bdt.FISCAL_WEEK_NBR                   as FISC_WEEK_NBR
    , bdt.CALENDAR_DAY_NM                   as DAY_OF_WEEK
    , iff(nvl(
        hol.HOLIDAY_IND
        , FALSE), 1, 0)                     as HOLIDAY_IND
    , hol.HOLIDAY_LIST_NM                   as HOLIDAY_NM
    , nvl(dpsf.Net_Sales, 0)                as NET_SALES
    , nvl(
        CASE
            WHEN nvl(dpsf.Net_Sales, 0) = 0
            THEN 0
            ELSE dpsf.Trans_Cnt
        END, 0)                             as TRANS
    , CASE
        WHEN nvl(dpsf.Net_Sales, 0) = 0
            AND NOT nvl(
                    (ARRAY_CONTAINS(cast(''THANKSGIVING DAY'' as variant), split(hol.HOLIDAY_LIST_NM, '', ''))
                    OR ARRAY_CONTAINS(cast(''CHRISTMAS DAY'' as variant), split(hol.HOLIDAY_LIST_NM, '', '')))
                , FALSE
            )
        THEN 0
        WHEN NOT dpsf.OPEN_AFTER_HONEYMOON_FLAG OR NOT dpsf.OPEN_15P_FLAG
        THEN 0
        ELSE 1
    END                                     as COMP_STORE_CNT
FROM table(DAILY_DAY_PART_FLASH_SALES_V(
            FROM_DATE
            , TO_DATE
        )
    ) as dpsf
INNER JOIN IDH_DEV.SHARED.DATE_DIM_V as bdt
    on bdt.CALENDAR_DT = dpsf.BUSINESS_DT
LEFT JOIN IDH_DEV.SHARED.HOLIDAY_LIST_V as hol
    ON bdt.DATE_KEY = hol.DATE_KEY
';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_OFFER_SALES("STARTDATE" DATE, "ENDDATE" DATE)
RETURNS TABLE ("BUSINESS_DT" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_CD" VARCHAR(16777216), "DMA_NM" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "DAY_OF_WEEK" VARCHAR(16777216), "HOLIDAY_IND_CY" VARCHAR(16777216), "HOLIDAY_NM_CY" VARCHAR(16777216), "MDM_OFFER_ID" NUMBER(38,0), "MDM_OFFER_NM" VARCHAR(16777216), "DISCOUNT_AMT_CY" FLOAT, "OFFER_CNT_CY" NUMBER(38,0), "CHECK_SALES_CY" FLOAT, "CHECK_CNT_CY" NUMBER(38,0), "REST_SALES_CY" FLOAT, "REST_TRANS_CY" NUMBER(38,0), "FISC_DATE_LY" DATE, "FISC_HOLIDAY_IND_LY" VARCHAR(16777216), "FISC_HOLIDAY_NM_LY" VARCHAR(16777216), "FISC_DISCOUNT_AMT_LY" FLOAT, "FISC_OFFER_CNT_LY" NUMBER(38,0), "FISC_CHECK_SALES_LY" FLOAT, "FISC_CHECK_CNT_LY" NUMBER(38,0), "FISC_REST_SALES_LY" FLOAT, "FISC_REST_TRANS_LY" NUMBER(38,0), "CAL_COMP_DATE_LY" DATE, "CAL_HOLIDAY_IND_LY" VARCHAR(16777216), "CAL_HOLIDAY_NM_LY" VARCHAR(16777216), "CAL_DISCOUNT_AMT_LY" FLOAT, "CAL_OFFER_CNT_LY" NUMBER(38,0), "CAL_CHECK_SALES_LY" FLOAT, "CAL_CHECK_CNT_LY" NUMBER(38,0), "CAL_REST_SALES_LY" FLOAT, "CAL_REST_TRANS_LY" NUMBER(38,0), "OFFER_HIERARCHY_ID" VARCHAR(16777216), "LEVEL5_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL4_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL3_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL2_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL1_OFFER_HIERARCHY_NM" VARCHAR(16777216), "OFFER_MISC1" VARCHAR(16777216), "OFFER_MISC2" VARCHAR(16777216), "OFFER_MISC3" VARCHAR(16777216), "OFFER_MISC4" VARCHAR(16777216), "OFFER_MISC5" VARCHAR(16777216), "OFFER_MISC6" VARCHAR(16777216), "OFFER_MISC7" VARCHAR(16777216), "OFFER_MISC8" VARCHAR(16777216), "OFFER_MISC9" VARCHAR(16777216), "OFFER_MISC10" VARCHAR(16777216))
LANGUAGE SQL
AS '

    WITH 
    get_dates AS (
        SELECT DISTINCT  
              CALENDAR_DT
            , CALENDAR_DAY_NM  
            , FISCAL_1YR_COMP_DT
            , CALENDAR_1YR_COMP_DT
            , FISCAL_WEEK_NBR
            , FISCAL_YEAR_NBR
            , FISCAL_QUARTER_NBR
            , FISCAL_PERIOD_NBR
            , FISCAL_1YR_COMP_YEAR_DT
            , CALENDAR_1YR_COMP_YEAR_DT
            , iff(nvl(hol.HOLIDAY_IND, false), ''Y'', ''N'')         as HOLIDAY_IND_CY
            , hol.HOLIDAY_LIST_NM                                as HOLIDAY_NM_CY
            , iff(nvl(hol_fly.HOLIDAY_IND, false), ''Y'', ''N'')     as FISC_HOLIDAY_IND_LY
            , hol_fly.HOLIDAY_LIST_NM                            as FISC_HOLIDAY_NM_LY
            , iff(nvl(hol_cly.HOLIDAY_IND, false), ''Y'', ''N'')     as CAL_HOLIDAY_IND_LY
            , hol_cly.HOLIDAY_LIST_NM                            as CAL_HOLIDAY_NM_LY
        FROM 
        IDS_DEV.INT_REF.COMP_CALENDAR dt
        LEFT OUTER JOIN IDH_DEV.SHARED.HOLIDAY_LIST_V as hol
        ON dt.DATE_KEY = hol.DATE_KEY
        LEFT OUTER JOIN IDH_DEV.SHARED.HOLIDAY_LIST_V as hol_fly
        ON dt.FISCAL_1YR_DATE_KEY = hol_fly.DATE_KEY
        LEFT OUTER JOIN IDH_DEV.SHARED.HOLIDAY_LIST_V as hol_cly
        ON dt.CALENDAR_1YR_DATE_KEY = hol_cly.DATE_KEY
        where CALENDAR_DT between startDate and endDate
    )    
    , get_stores as (
        SELECT DISTINCT
              dt.CALENDAR_DT
            , dt.CALENDAR_DAY_NM  
            , dt.FISCAL_1YR_COMP_DT as FISC_DATE_LY
            , dt.CALENDAR_1YR_COMP_DT as CAL_COMP_DATE_LY  
            , dt.FISCAL_WEEK_NBR
            , dt.FISCAL_YEAR_NBR
            , dt.FISCAL_QUARTER_NBR
            , dt.FISCAL_PERIOD_NBR
            , dt.HOLIDAY_IND_CY
            , dt.HOLIDAY_NM_CY
            , dt.FISC_HOLIDAY_IND_LY
            , dt.FISC_HOLIDAY_NM_LY
            , dt.CAL_HOLIDAY_IND_LY
            , dt.CAL_HOLIDAY_NM_LY
            , st.store_id
            , st.brand_id
            , ssv.DMA_CD
            , ssv.DMA_NM
            , ssv.CLOSURE_DT
            , ssv.OWNERSHIP_TYP
            , ssv.STATE_NM as STATE
            , ssv.COUNTRY_NM as COUNTRY
            , odv.MDM_OFFER_ID
            , odv.OFFER_NM
            , lhv.LEVEL1_NM as L1NAME
            , lhv.LEVEL2_NM as L2NAME
            , lhv.LEVEL3_NM as L3NAME
            , lhv.LEVEL4_NM as L4NAME
            , lhv.LEVEL5_NM as L5NAME
            
         FROM 
            get_dates dt
            INNER JOIN IDH_QA.SHARED.STORE_SCD_PROD_V st
                ON st.CURRENT_IND = 1 
                AND nvl(st.CLOSURE_DT,''9999-01-01'') >= least(dt.FISCAL_1YR_COMP_YEAR_DT,dt.CALENDAR_1YR_COMP_YEAR_DT)
                AND st.COUNTRY_NM IN (''US'', ''USA'')
            INNER JOIN IDH_QA.SALES.ORDER_DETAIL_SUBSET_V odv
                ON st.brand_id = odv.brand_id
                AND st.STORE_ID = odv.STORE_ID
                AND odv.MDM_ITEM_TYP = ''Offer''  
                AND odv.MDM_OFFER_ID IS NOT NULL  
           LEFT OUTER JOIN IDH_QA.SHARED.STORE_SCD_PROD_V ssv    
                ON st.brand_id = ssv.brand_id
                AND st.STORE_ID = ssv.STORE_ID
                AND dt.calendar_dt BETWEEN ssv.EFFECTIVE_BEGIN_DT AND ssv.EFFECTIVE_END_DT
                AND ssv.COUNTRY_NM IN (''US'', ''USA'')
            LEFT JOIN IDH_DEV.OPERATION.LOCATION_HIERARCHY_V lhv
                ON lhv.LOCATION_ID = st.STORE_ID
                AND lhv.BRAND_ID = st.BRAND_ID

    )
    , result as (
        SELECT DISTINCT
            st.CALENDAR_DT as BUSINESS_DT
            , CASE 
                WHEN st.BRAND_ID = ''arbys'' THEN ''ARB''
                WHEN st.BRAND_ID = ''sonic'' THEN ''SON''
                WHEN st.BRAND_ID = ''bww'' THEN ''BWW''
                WHEN st.BRAND_ID = ''jj'' THEN ''JJ''
                WHEN st.BRAND_ID = ''dnkn'' THEN ''DUN''
                WHEN st.BRAND_ID = ''bskn'' THEN ''BR''
                WHEN st.BRAND_ID = ''rto'' THEN ''RT''
                ELSE ''UNKNOWN'' 
            END AS BRAND
            , st.STORE_ID as STORE_NBR
            , st.DMA_CD
            , st.DMA_NM
            , st.L1NAME
            , st.L2NAME
            , st.L3NAME
            , st.L4NAME
            , st.L5NAME
            , st.OWNERSHIP_TYP
            , st.STATE
            , st.COUNTRY
            , st.FISCAL_YEAR_NBR
            , st.FISCAL_QUARTER_NBR
            , st.FISCAL_PERIOD_NBR
            , st.FISCAL_WEEK_NBR
            , st.CALENDAR_DAY_NM as DAY_OF_WEEK
            , st.HOLIDAY_IND_CY
            , st.HOLIDAY_NM_CY
            , st.MDM_OFFER_ID
            , st.OFFER_NM as MDM_OFFER_NM

            -- current year
            , ifnull(odv.DISCOUNT_AMT, 0.00) as DISCOUNT_AMT_CY
            , ifnull(odv.OFFER_CNT,0) as OFFER_CNT_CY
            , ifnull(odv.CHECK_SALES, 0.00) as CHECK_SALES_CY
            , ifnull(odv.CHECK_CNT,0) as CHECK_CNT_CY
            , ifnull(odv.REST_SALES, 0.00) as REST_SALES_CY
            , ifnull(odv.REST_TRANS,0) as REST_TRANS_CY

            -- fiscal year
            , st.FISC_DATE_LY
            , st.FISC_HOLIDAY_IND_LY
            , st.FISC_HOLIDAY_NM_LY
            , ifnull(fisc_odv.DISCOUNT_AMT, 0.00) as FISC_DISCOUNT_AMT_LY
            , ifnull(fisc_odv.OFFER_CNT,0) as FISC_OFFER_CNT_LY
            , ifnull(fisc_odv.CHECK_SALES, 0.00) as FISC_CHECK_SALES_LY
            , ifnull(fisc_odv.CHECK_CNT,0) as FISC_CHECK_CNT_LY
            , ifnull(fisc_odv.REST_SALES, 0.00) as FISC_REST_SALES_CY
            , ifnull(fisc_odv.REST_TRANS,0) as FISC_REST_TRANS_CY

            -- calendar year
            , st.CAL_COMP_DATE_LY
            , st.CAL_HOLIDAY_IND_LY
            , st.CAL_HOLIDAY_NM_LY
            , ifnull(cal_odv.DISCOUNT_AMT, 0.00) as CAL_DISCOUNT_AMT_LY
            , ifnull(cal_odv.OFFER_CNT,0) as CAL_OFFER_CNT_LY
            , ifnull(cal_odv.CHECK_SALES, 0.00) as CAL_CHECK_SALES_LY
            , ifnull(cal_odv.CHECK_CNT,0) as CAL_CHECK_CNT_LY
            , ifnull(cal_odv.REST_SALES, 0.00) as CAL_REST_SALES_CY
            , ifnull(cal_odv.REST_TRANS,0) as CAL_REST_TRANS_CY

            , odv.OFFER_HIERARCHY_ID
            , odv.LEVEL5_OFFER_HIERARCHY_NM
            , odv.LEVEL4_OFFER_HIERARCHY_NM
            , odv.LEVEL3_OFFER_HIERARCHY_NM
            , odv.LEVEL2_OFFER_HIERARCHY_NM
            , odv.LEVEL1_OFFER_HIERARCHY_NM
            , odv.OFFER_MISC1
            , odv.OFFER_MISC2
            , odv.OFFER_MISC3
            , odv.OFFER_MISC4
            , odv.OFFER_MISC5
            , odv.OFFER_MISC6
            , odv.OFFER_MISC7
            , odv.OFFER_MISC8
            , odv.OFFER_MISC9
            , odv.OFFER_MISC10
        FROM 
            get_stores st
            LEFT OUTER JOIN TABLE(INSPIRE_DAILY_OFFER_SALES_INIT(startDate, endDate,''DAY'',''CY'')) odv
                ON st.brand_id = odv.brand_id
                AND st.STORE_ID = odv.STORE_ID
                AND st.calendar_dt = odv.BUSINESS_DT
                AND st.MDM_OFFER_ID = odv.MDM_OFFER_ID  
            LEFT OUTER JOIN TABLE(INSPIRE_DAILY_OFFER_SALES_INIT(startDate, endDate, ''DAY'',''FISC1Y'')) fisc_odv
                ON st.brand_id = fisc_odv.brand_id
                AND st.STORE_ID = fisc_odv.STORE_ID
                AND st.FISC_DATE_LY = fisc_odv.BUSINESS_DT
                AND st.MDM_OFFER_ID =fisc_odv.MDM_OFFER_ID
            LEFT OUTER JOIN TABLE(INSPIRE_DAILY_OFFER_SALES_INIT(startDate, endDate,''DAY'',''CAL1Y'')) cal_odv
                ON st.brand_id = cal_odv.brand_id
                AND st.STORE_ID = cal_odv.STORE_ID
                AND st.CAL_COMP_DATE_LY = cal_odv.BUSINESS_DT
                AND st.MDM_OFFER_ID =cal_odv.MDM_OFFER_ID
        WHERE
            st.COUNTRY IN (''US'', ''USA'')
    )
    SELECT * 
    FROM result 
    WHERE 
        OFFER_CNT_CY <> 0 
        OR FISC_OFFER_CNT_LY <> 0
        OR CAL_OFFER_CNT_LY <> 0
';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_OFFER_SALES_CAL("FROMDATE" DATE, "TODATE" DATE)
RETURNS TABLE ("ORDER_ID" VARCHAR(16777216), "CAL_DATE_LY" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "MDM_ITEM_ID" NUMBER(38,0), "CAL_DISCOUNT_AMT_LY" NUMBER(38,2), "CAL_OFFER_CNT_LY" NUMBER(38,0), "CAL_CHECK_SALES_LY" NUMBER(38,2), "CAL_CHECK_CNT_LY" NUMBER(38,0), "CAL_REST_SALES_LY" NUMBER(38,2), "CAL_REST_TRANS_LY" NUMBER(38,0))
LANGUAGE SQL
AS '

WITH date_interval AS
(
    SELECT 
        MIN(CALENDAR_COMPARABLE_DT) AS MIN_CAL_COMPARABLE_DT
        , MAX(CALENDAR_COMPARABLE_DT) AS MAX_CAL_COMPARABLE_DT 
    FROM 
        IDH_DEV.SHARED.DATE_DIM_V dd 
    WHERE 
        CALENDAR_DT BETWEEN FromDate AND ToDate
)

, src AS
(
SELECT
    od.ORDER_ID
    , od.ORDER_DT AS BUSINESS_DT
    , CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
         WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
         WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
         WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
         WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
         WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
         WHEN od.BRAND_ID = ''rto'' THEN ''RT''
         ELSE ''UNKNOWN'' END AS BRAND
    , od.STORE_ID AS STORE_NBR
    , od.MDM_ITEM_ID AS MDM_ITEM_ID
    , ROW_NUMBER() OVER(PARTITION BY od.ORDER_DT, od.BRAND_ID, od.STORE_ID, IFNULL(od.MDM_ITEM_ID, 0) ORDER BY od.ORDER_ID, od.ORDER_DT, od.BRAND_ID, od.STORE_ID, IFNULL(od.MDM_ITEM_ID, 0)) AS Rn
    
    , SUM(od.DERIVED_DISCOUNT_AMT) OVER(PARTITION BY od.BRAND_ID, od.STORE_ID, od.ORDER_DT, IFNULL(od.MDM_ITEM_ID, 0)) AS CAL_DISCOUNT_AMT_LY
    , SUM(od.DERIVED_GROSS_QTY) OVER(PARTITION BY od.BRAND_ID, od.STORE_ID, od.ORDER_DT, IFNULL(od.MDM_ITEM_ID, 0)) AS CAL_OFFER_CNT_LY
    
    , SUM(od.DERIVED_NET_AMT) OVER(PARTITION BY IFNULL(od.MDM_ITEM_ID, 0), od.BRAND_ID, od.STORE_ID, od.ORDER_DT) AS CAL_CHECK_SALES_LY
    , COUNT(DISTINCT od.ORDER_ID) OVER(PARTITION BY IFNULL(od.MDM_ITEM_ID, 0), od.BRAND_ID, od.STORE_ID, od.ORDER_DT) AS CAL_CHECK_CNT_LY
  
    , SUM(od.DERIVED_NET_AMT) OVER(PARTITION BY od.BRAND_ID, od.STORE_ID, od.ORDER_DT) AS CAL_REST_SALES_LY
    , COUNT(DISTINCT od.ORDER_ID) OVER(PARTITION BY od.BRAND_ID, od.STORE_ID, od.ORDER_DT) AS CAL_REST_TRANS_LY

FROM
    ORDER_DETAIL_V od
WHERE
    IFNULL((CASE WHEN UPPER(CAST(VOIDED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(VOIDED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND IFNULL((CASE WHEN UPPER(CAST(CLEARED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(CLEARED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND IFNULL((CASE WHEN UPPER(CAST(DELETED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(DELETED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND od.ORDER_DT BETWEEN FromDate AND ToDate
)


SELECT
    src.ORDER_ID
    , src.BUSINESS_DT
    , src.BRAND
    , src.STORE_NBR
    , src.MDM_ITEM_ID

    , src.CAL_DISCOUNT_AMT_LY
    , src.CAL_OFFER_CNT_LY
    , src.CAL_CHECK_SALES_LY
    , src.CAL_CHECK_CNT_LY
    , src.CAL_REST_SALES_LY
    , src.CAL_REST_TRANS_LY

FROM
    src
WHERE
    src.Rn = 1
    
';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_OFFER_SALES_FISC("FROMDATE" DATE, "TODATE" DATE)
RETURNS TABLE ("ORDER_ID" VARCHAR(16777216), "FISC_DATE_LY" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "MDM_ITEM_ID" NUMBER(38,0), "FISC_DISCOUNT_AMT_LY" NUMBER(38,2), "FISC_OFFER_CNT_LY" NUMBER(38,0), "FISC_CHECK_SALES_LY" NUMBER(38,2), "FISC_CHECK_CNT_LY" NUMBER(38,0), "FISC_REST_SALES_LY" NUMBER(38,2), "FISC_REST_TRANS_LY" NUMBER(38,0))
LANGUAGE SQL
AS '

WITH date_interval AS
(
    SELECT 
        MIN(FISCAL_COMPARABLE_DT) AS MIN_FISCAL_COMPARABLE_DT
        , MAX(FISCAL_COMPARABLE_DT) AS MAX_FISCAL_COMPARABLE_DT 
    FROM 
        IDH_DEV.SHARED.DATE_DIM_V dd 
    WHERE 
        CALENDAR_DT BETWEEN FromDate AND ToDate
)

, src AS
(
SELECT
    od.ORDER_ID
    , od.ORDER_DT AS BUSINESS_DT
    , CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
         WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
         WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
         WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
         WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
         WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
         WHEN od.BRAND_ID = ''rto'' THEN ''RT''
         ELSE ''UNKNOWN'' END AS BRAND
    , od.STORE_ID AS STORE_NBR
    , od.MDM_ITEM_ID AS MDM_ITEM_ID
    , ROW_NUMBER() OVER(PARTITION BY od.ORDER_DT, od.BRAND_ID, od.STORE_ID, IFNULL(od.MDM_ITEM_ID, 0) ORDER BY od.ORDER_ID, od.ORDER_DT, od.BRAND_ID, od.STORE_ID, IFNULL(od.MDM_ITEM_ID, 0)) AS Rn
    
    , SUM(od.DERIVED_DISCOUNT_AMT) OVER(PARTITION BY od.BRAND_ID, od.STORE_ID, od.ORDER_DT, IFNULL(od.MDM_ITEM_ID, 0)) AS FISC_DISCOUNT_AMT_LY
    , SUM(od.DERIVED_GROSS_QTY) OVER(PARTITION BY od.BRAND_ID, od.STORE_ID, od.ORDER_DT, IFNULL(od.MDM_ITEM_ID, 0)) AS FISC_OFFER_CNT_LY
    
    , SUM(od.DERIVED_NET_AMT) OVER(PARTITION BY IFNULL(od.MDM_ITEM_ID, 0), od.BRAND_ID, od.STORE_ID, od.ORDER_DT) AS FISC_CHECK_SALES_LY
    , COUNT(DISTINCT od.ORDER_ID) OVER(PARTITION BY IFNULL(od.MDM_ITEM_ID, 0), od.BRAND_ID, od.STORE_ID, od.ORDER_DT) AS FISC_CHECK_CNT_LY
  
    , SUM(od.DERIVED_NET_AMT) OVER(PARTITION BY od.BRAND_ID, od.STORE_ID, od.ORDER_DT) AS FISC_REST_SALES_LY
    , COUNT(DISTINCT od.ORDER_ID) OVER(PARTITION BY od.BRAND_ID, od.STORE_ID, od.ORDER_DT) AS FISC_REST_TRANS_LY

FROM
    ORDER_DETAIL_V od
WHERE
    IFNULL((CASE WHEN UPPER(CAST(VOIDED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(VOIDED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND IFNULL((CASE WHEN UPPER(CAST(CLEARED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(CLEARED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND IFNULL((CASE WHEN UPPER(CAST(DELETED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(DELETED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND od.ORDER_DT BETWEEN FromDate AND ToDate
)


SELECT
    src.ORDER_ID
    , src.BUSINESS_DT
    , src.BRAND
    , src.STORE_NBR
    , src.MDM_ITEM_ID

    , src.FISC_DISCOUNT_AMT_LY
    , src.FISC_OFFER_CNT_LY
    , src.FISC_CHECK_SALES_LY
    , src.FISC_CHECK_CNT_LY
    , src.FISC_REST_SALES_LY
    , src.FISC_REST_TRANS_LY

FROM
    src
WHERE
    src.Rn = 1
    
';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_OFFER_SALES_INIT("STARTDATE" DATE, "ENDDATE" DATE, "AGG_LEVEL" VARCHAR(16777216), "TIME_INTERVAL" VARCHAR(16777216))
RETURNS TABLE ("BUSINESS_DT" DATE, "BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "MDM_OFFER_ID" NUMBER(38,0), "MDM_OFFER_NM" VARCHAR(16777216), "DISCOUNT_AMT" FLOAT, "OFFER_CNT" NUMBER(38,0), "CHECK_SALES" FLOAT, "CHECK_CNT" NUMBER(18,0), "REST_SALES" FLOAT, "REST_TRANS" NUMBER(18,0), "OFFER_HIERARCHY_ID" VARCHAR(16777216), "LEVEL5_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL4_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL3_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL2_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL1_OFFER_HIERARCHY_NM" VARCHAR(16777216), "OFFER_MISC1" VARCHAR(16777216), "OFFER_MISC2" VARCHAR(16777216), "OFFER_MISC3" VARCHAR(16777216), "OFFER_MISC4" VARCHAR(16777216), "OFFER_MISC5" VARCHAR(16777216), "OFFER_MISC6" VARCHAR(16777216), "OFFER_MISC7" VARCHAR(16777216), "OFFER_MISC8" VARCHAR(16777216), "OFFER_MISC9" VARCHAR(16777216), "OFFER_MISC10" VARCHAR(16777216))
LANGUAGE SQL
AS '


    WITH get_dates AS (
        SELECT 
        DATE_KEY,
        CALENDAR_DT,
        FISCAL_WEEK_START_DT
        FROM IDS_DEV.INT_REF.COMP_DATES dt
        WHERE dt.TIME_INTERVAL = TIME_INTERVAL 
        AND dt.business_dt BETWEEN startDate AND endDate
    )  
    ,init as (
        SELECT
          CASE WHEN AGG_LEVEL =''DAY'' THEN CALENDAR_DT ELSE FISCAL_WEEK_START_DT END AS BUSINESS_DT,
          BRAND_ID,
          STORE_ID,
          MDM_ITEM_TYP,
          MDM_OFFER_ID,
          OFFER_NM,  
          ORDER_ID,
          DERIVED_NET_AMT,
          DERIVED_DISCOUNT_AMT,
          DERIVED_GROSS_QTY,
          OFFER_HIERARCHY_ID,
          LEVEL5_OFFER_HIERARCHY_NM,
          LEVEL4_OFFER_HIERARCHY_NM,
          LEVEL3_OFFER_HIERARCHY_NM,
          LEVEL2_OFFER_HIERARCHY_NM,
          LEVEL1_OFFER_HIERARCHY_NM,
          OFFER_MISC1,
          OFFER_MISC2,
          OFFER_MISC3,
          OFFER_MISC4,
          OFFER_MISC5,
          OFFER_MISC6,
          OFFER_MISC7,
          OFFER_MISC8,
          OFFER_MISC9,
          OFFER_MISC10,
          CALENDAR_DT,
          FISCAL_WEEK_START_DT,
          ROW_NUMBER() OVER (PARTITION BY BRAND_ID, STORE_ID, MDM_OFFER_ID, CASE WHEN AGG_LEVEL =''DAY'' THEN CALENDAR_DT ELSE FISCAL_WEEK_START_DT END ORDER BY CASE WHEN AGG_LEVEL =''DAY'' THEN CALENDAR_DT ELSE FISCAL_WEEK_START_DT END) AS RN
          FROM get_dates dt
          LEFT OUTER JOIN IDH_QA.SALES.ORDER_DETAIL_SUBSET_V odv 
          ON dt.DATE_KEY = odv.ORDER_DT_KEY 
          AND IFNULL(IFF(UPPER(odv.VOIDED_IND) = ''Y'', ''TRUE'', UPPER(odv.VOIDED_IND)), ''FALSE'') <> ''TRUE''
          AND IFNULL(IFF(UPPER(odv.CLEARED_IND) = ''Y'', ''TRUE'', UPPER(odv.CLEARED_IND)), ''FALSE'') <> ''TRUE''
          AND IFNULL(IFF(UPPER(odv.DELETED_IND) = ''Y'', ''TRUE'', UPPER(odv.DELETED_IND)), ''FALSE'') <> ''TRUE''  
       )
       ,rest_trans as (
          SELECT
              BUSINESS_DT
            , BRAND_ID
            , STORE_ID 
            , SUM(ifnull(DERIVED_NET_AMT, 0.00)) OVER(PARTITION BY BRAND_ID, STORE_ID, BUSINESS_DT) AS REST_SALES
            , COUNT(DISTINCT ORDER_ID) OVER(PARTITION BY BRAND_ID, STORE_ID, BUSINESS_DT) AS REST_TRANS
              FROM init
              QUALIFY ROW_NUMBER() OVER(PARTITION BY BRAND_ID, STORE_ID, BUSINESS_DT ORDER BY BUSINESS_DT) = 1     
       )
        , check_sales as (
          SELECT
              BUSINESS_DT
            , BRAND_ID
            , STORE_ID 
            , MDM_OFFER_ID
            , SUM(ifnull(DERIVED_NET_AMT, 0.00)) OVER(PARTITION BY BRAND_ID, STORE_ID, MDM_OFFER_ID, BUSINESS_DT) AS CHECK_SALES
            , COUNT (DISTINCT ORDER_ID) OVER(PARTITION BY BRAND_ID, STORE_ID, MDM_OFFER_ID, BUSINESS_DT) AS CHECK_CNT
              FROM init 
              WHERE MDM_ITEM_TYP = ''Offer''
              QUALIFY ROW_NUMBER() OVER(PARTITION BY BRAND_ID, STORE_ID, MDM_OFFER_ID, BUSINESS_DT ORDER BY BUSINESS_DT) = 1
        ),
          offer as (
          SELECT
              BUSINESS_DT
            , BRAND_ID
            , STORE_ID 
            , MDM_OFFER_ID
            , SUM(ifnull(DERIVED_DISCOUNT_AMT, 0.00)) OVER(PARTITION BY BRAND_ID, STORE_ID, MDM_OFFER_ID, BUSINESS_DT) AS DISCOUNT_AMT
            , SUM(ifnull(DERIVED_GROSS_QTY, 0.00)) OVER(PARTITION BY BRAND_ID, STORE_ID, MDM_OFFER_ID, BUSINESS_DT) AS OFFER_CNT
              FROM init 
              WHERE MDM_ITEM_TYP = ''Offer''
              QUALIFY ROW_NUMBER() OVER(PARTITION BY BRAND_ID, STORE_ID, MDM_OFFER_ID, BUSINESS_DT ORDER BY BUSINESS_DT) = 1  
          )
          SELECT DISTINCT
              i.BUSINESS_DT
            , i.BRAND_ID
            , i.STORE_ID 
            , i.MDM_OFFER_ID
            , i.OFFER_NM
            , o.DISCOUNT_AMT
            , o.OFFER_CNT
            , c.CHECK_SALES
            , c.CHECK_CNT
            , r.REST_SALES 
            , r.REST_TRANS
            , i.OFFER_HIERARCHY_ID
            , i.LEVEL5_OFFER_HIERARCHY_NM
            , i.LEVEL4_OFFER_HIERARCHY_NM
            , i.LEVEL3_OFFER_HIERARCHY_NM
            , i.LEVEL2_OFFER_HIERARCHY_NM
            , i.LEVEL1_OFFER_HIERARCHY_NM
            , i.OFFER_MISC1
            , i.OFFER_MISC2
            , i.OFFER_MISC3
            , i.OFFER_MISC4
            , i.OFFER_MISC5
            , i.OFFER_MISC6
            , i.OFFER_MISC7
            , i.OFFER_MISC8
            , i.OFFER_MISC9
            , i.OFFER_MISC10
          FROM init i
          INNER JOIN rest_trans r
          ON i.BRAND_ID = r.BRAND_ID
          AND i.STORE_ID = r.STORE_ID
          AND i.BUSINESS_DT = r.BUSINESS_DT
          INNER JOIN check_sales c
          ON i.BRAND_ID = c.BRAND_ID
          AND i.STORE_ID = c.STORE_ID
          AND i.MDM_OFFER_ID = c.MDM_OFFER_ID
          AND i.BUSINESS_DT = c.BUSINESS_DT
          INNER JOIN offer o
          ON i.BRAND_ID = o.BRAND_ID
          AND i.STORE_ID = o.STORE_ID
          AND i.MDM_OFFER_ID = o.MDM_OFFER_ID
          AND i.BUSINESS_DT = o.BUSINESS_DT
          WHERE i.MDM_ITEM_TYP = ''Offer''
          AND i.RN = 1
          ';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_OFFER_SALES_INIT("STARTDATE" DATE, "ENDDATE" DATE, "TIME_INTERVAL" VARCHAR(16777216))
RETURNS TABLE ("BUSINESS_DT" DATE, "BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "DAY_OF_WEEK" VARCHAR(16777216), "HOLIDAY_IND" VARCHAR(16777216), "HOLIDAY_NM" VARCHAR(16777216), "MDM_OFFER_ID" NUMBER(38,0), "MDM_OFFER_NM" VARCHAR(16777216), "DISCOUNT_AMT" NUMBER(30,2), "OFFER_CNT" NUMBER(30,2), "CHECK_SALES" NUMBER(30,2), "CHECK_CNT" NUMBER(30,2), "REST_SALES" NUMBER(30,2), "REST_TRANS" NUMBER(30,2), "OFFER_HIERARCHY_ID" VARCHAR(16777216), "LEVEL5_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL4_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL3_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL2_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL1_OFFER_HIERARCHY_NM" VARCHAR(16777216), "OFFER_MISC1" VARCHAR(16777216), "OFFER_MISC2" VARCHAR(16777216), "OFFER_MISC3" VARCHAR(16777216), "OFFER_MISC4" VARCHAR(16777216), "OFFER_MISC5" VARCHAR(16777216), "OFFER_MISC6" VARCHAR(16777216), "OFFER_MISC7" VARCHAR(16777216), "OFFER_MISC8" VARCHAR(16777216), "OFFER_MISC9" VARCHAR(16777216), "OFFER_MISC10" VARCHAR(16777216))
LANGUAGE SQL
AS '
    WITH get_dates AS (
        select distinct
        CALENDAR_DT,
        FISCAL_YEAR_NBR,
        FISCAL_QUARTER_NBR, 
        FISCAL_PERIOD_NBR, 
        FISCAL_WEEK_NBR,
        CALENDAR_DAY_NM ,
        HOLIDAY_IND, 
        HOLIDAY_LIST_NM
        from IDS_DEV.INT_REF.COMP_DATES dt
        where dt.time_interval = TIME_INTERVAL 
        and dt.business_dt between startDate and endDate
    )
            SELECT
              dt.calendar_dt as BUSINESS_DT
            , odv.BRAND_ID
            , odv.STORE_ID 
            , dt.FISCAL_YEAR_NBR
            , dt.FISCAL_QUARTER_NBR
            , dt.FISCAL_PERIOD_NBR
            , dt.FISCAL_WEEK_NBR
            , dt.CALENDAR_DAY_NM
            , dt.HOLIDAY_IND
            , dt.HOLIDAY_LIST_NM
            , odv.MDM_OFFER_ID
            , odv.OFFER_NM 
            , ROUND(SUM(ifnull(odv.DERIVED_DISCOUNT_AMT, 0.00)) OVER(PARTITION BY odv.BRAND_ID, odv.STORE_ID, odv.ORDER_DT, IFNULL(odv.MDM_OFFER_ID, 0)),2) AS DISCOUNT_AMT
            , ROUND(SUM(ifnull(odv.DERIVED_GROSS_QTY, 0.00)) OVER(PARTITION BY odv.BRAND_ID, odv.STORE_ID, odv.ORDER_DT, IFNULL(odv.MDM_OFFER_ID, 0)),2) AS OFFER_CNT
            , ROUND(SUM(ifnull(odv.DERIVED_NET_AMT, 0.00)) OVER(PARTITION BY odv.BRAND_ID, odv.STORE_ID, IFNULL(odv.MDM_OFFER_ID, 0)),2) AS CHECK_SALES
            , COUNT(DISTINCT odv.ORDER_ID) OVER(PARTITION BY odv.BRAND_ID, odv.STORE_ID, odv.ORDER_DT, IFNULL(odv.MDM_OFFER_ID, 0)) AS CHECK_CNT
            , ROUND(SUM(ifnull(odv.DERIVED_NET_AMT, 0.00)) OVER(PARTITION BY odv.BRAND_ID, odv.STORE_ID, odv.ORDER_DT),2) AS REST_SALES
            , COUNT(DISTINCT odv.ORDER_ID) OVER(PARTITION BY odv.BRAND_ID, odv.STORE_ID, odv.ORDER_DT) AS REST_TRANS
            , odv.OFFER_HIERARCHY_ID
            , odv.LEVEL5_OFFER_HIERARCHY_NM
            , odv.LEVEL4_OFFER_HIERARCHY_NM
            , odv.LEVEL3_OFFER_HIERARCHY_NM
            , odv.LEVEL2_OFFER_HIERARCHY_NM
            , odv.LEVEL1_OFFER_HIERARCHY_NM
            , odv.OFFER_MISC1
            , odv.OFFER_MISC2
            , odv.OFFER_MISC3
            , odv.OFFER_MISC4
            , odv.OFFER_MISC5
            , odv.OFFER_MISC6
            , odv.OFFER_MISC7
            , odv.OFFER_MISC8
            , odv.OFFER_MISC9
            , odv.OFFER_MISC10
              FROM get_dates dt
              LEFT OUTER JOIN IDS_DEV.datastore.ORDER_DETAIL_TEST odv 
              ON dt.calendar_dt = odv.order_dt
              AND odv.MDM_ITEM_TYP = ''Offer''
              AND IFNULL(IFF(UPPER(odv.VOIDED_IND) = ''Y'', ''TRUE'', UPPER(odv.VOIDED_IND)), ''FALSE'') <> ''TRUE''
              AND IFNULL(IFF(UPPER(odv.CLEARED_IND) = ''Y'', ''TRUE'', UPPER(odv.CLEARED_IND)), ''FALSE'') <> ''TRUE''
              AND IFNULL(IFF(UPPER(odv.DELETED_IND) = ''Y'', ''TRUE'', UPPER(odv.DELETED_IND)), ''FALSE'') <> ''TRUE''
              QUALIFY ROW_NUMBER() OVER(PARTITION BY odv.BRAND_ID, odv.STORE_ID, odv.ORDER_DT, odv.MDM_OFFER_ID ORDER BY odv.ORDER_DT) = 1


';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_ORDER_FULFILLMENT_FLASH("FROM_DATE" DATE, "TO_DATE" DATE)
RETURNS TABLE ("AGG_LEVEL" VARCHAR(16777216), "BUSINESS_DATE" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_CD" VARCHAR(16777216), "DMA_NM" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "ADDRESS_1" VARCHAR(16777216), "ADDRESS_2" VARCHAR(16777216), "CITY" VARCHAR(16777216), "ZIP_CODE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "CHANNEL_ID" VARCHAR(16777216), "ORDER_CHANNEL_L1" VARCHAR(16777216), "ORDER_CHANNEL_L2" VARCHAR(16777216), "ORDER_CHANNEL_L3" VARCHAR(16777216), "FULFILLMENT_CHANNEL_L1" VARCHAR(16777216), "FULFILLMENT_CHANNEL_L2" VARCHAR(16777216), "FULFILLMENT_CHANNEL_L3" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "DAY_OF_WEEK" VARCHAR(16777216), "HOLIDAY_IND_CY" NUMBER(38,0), "HOLIDAY_NM_CY" VARCHAR(16777216), "NET_SALES_CY" NUMBER(38,2), "TRANS_CY" NUMBER(38,0), "AVG_CHECK_CY" NUMBER(38,2), "COMP_SALES_CY" NUMBER(38,2), "COMP_TRANS_CY" NUMBER(38,0), "COMP_AVG_CHECK_CY" NUMBER(38,2), "FISC_DATE_LY" DATE, "FISC_HOLIDAY_IND_LY" NUMBER(38,0), "FISC_HOLIDAY_NM_LY" VARCHAR(16777216), "FISC_NET_SALES_LY" NUMBER(38,2), "FISC_TRANS_LY" NUMBER(38,0), "FISC_AVG_CHECK_LY" NUMBER(38,2), "FISC_COMP_SALES_LY" NUMBER(38,2), "FISC_COMP_TRANS_LY" NUMBER(38,0), "FISC_COMP_AVG_CHECK_LY" NUMBER(38,2), "CAL_COMP_DATE_LY" DATE, "CAL_HOLIDAY_IND_LY" NUMBER(38,0), "CAL_HOLIDAY_NM_LY" VARCHAR(16777216), "CAL_NET_SALES_LY" NUMBER(38,2), "CAL_TRANS_LY" NUMBER(38,0), "CAL_AVG_CHECK_LY" NUMBER(38,2), "CAL_COMP_SALES_LY" NUMBER(38,2), "CAL_COMP_TRANS_LY" NUMBER(38,0), "CAL_COMP_AVG_CHECK_LY" NUMBER(38,2), "CAL_COMP_DATE_2Y" DATE, "CAL_HOLIDAY_IND_2Y" NUMBER(38,0), "CAL_HOLIDAY_NM_2Y" VARCHAR(16777216), "CAL_NET_SALES_2Y" NUMBER(38,2), "CAL_TRANS_2Y" NUMBER(38,0), "CAL_AVG_CHECK_2Y" NUMBER(38,2), "CAL_COMP_SALES_2Y" NUMBER(38,2), "CAL_COMP_TRANS_2Y" NUMBER(38,0), "CAL_COMP_AVG_CHECK_2Y" NUMBER(38,2), "CAL_COMP_DATE_3Y" DATE, "CAL_HOLIDAY_IND_3Y" NUMBER(38,0), "CAL_HOLIDAY_NM_3Y" VARCHAR(16777216), "CAL_NET_SALES_3Y" NUMBER(38,2), "CAL_TRANS_3Y" NUMBER(38,0), "CAL_AVG_CHECK_3Y" NUMBER(38,2), "CAL_COMP_SALES_3Y" NUMBER(38,2), "CAL_COMP_TRANS_3Y" NUMBER(38,0), "CAL_COMP_AVG_CHECK_3Y" NUMBER(38,2))
LANGUAGE SQL
AS '

SELECT
    ''DAY'' AS AGG_LEVEL
    , BUSINESS_DATE
    , BRAND
    , STORE_NBR
    , DMA_CODE AS DMA_CD
    , DMA_NAME AS DMA_NM
    , L1Name AS L1NAME
    , L2Name AS L2NAME
    , L3Name AS L3NAME
    , L4Name AS L4NAME
    , L5Name AS L5NAME
    , OWNERSHIP_TYP
    , ADDRESS_1
    , ADDRESS_2
    , CITY
    , ZIP_CODE
    , STATE
    , COUNTRY


    , nvl(main.CHANNEL_ID, '''') AS CHANNEL_ID
    , nvl(o.ORDER_CHANNEL_HIERARCHY_LEVEL1_NM, '''') AS ORDER_CHANNEL_L1
    , nvl(o.ORDER_CHANNEL_HIERARCHY_LEVEL2_NM, '''') AS ORDER_CHANNEL_L2
    , nvl(o.ORDER_CHANNEL_HIERARCHY_LEVEL3_NM, '''') AS ORDER_CHANNEL_L3
    , nvl(o.FULFILLMENT_CHANNEL_HIERARCHY_L1_NM, '''') AS FULFILLMENT_CHANNEL_L1
    , nvl(o.FULFILLMENT_CHANNEL_HIERARCHY_L2_NM, '''') AS FULFILLMENT_CHANNEL_L2
    , nvl(o.FULFILLMENT_CHANNEL_HIERARCHY_L3_NM, '''') AS FULFILLMENT_CHANNEL_L3


    --current year
    , FISC_YEAR_NBR
    , FISC_QUARTER_NBR
    , FISC_PERIOD_NBR
    , FISC_WEEK_NBR
    , DAY_OF_WEEK AS DAY_OF_WEEK_CY
    , HOLIDAY_IND_CY
    , HOLIDAY_NM_CY
    , NET_SALES_CY
    , TRANS_CY
    , AVG_CHECK_CY
    , COMP_SALES_CY
    , COMP_TRANS_CY
    , COMP_AVG_CHECK_CY

    --fiscal last year
    , FISC_DATE_LY
    , FISC_HOLIDAY_IND_LY
    , FISC_HOLIDAY_NM_LY
    , FISC_NET_SALES_LY
    , FISC_TRANS_LY
    , FISC_AVG_CHECK_LY
    , FISC_COMP_SALES_LY
    , FISC_COMP_TRANS_LY
    , FISC_COMP_AVG_CHECK_LY

    --calendar last year
    , CAL_COMP_DATE_LY
    , CAL_HOLIDAY_IND_LY
    , CAL_HOLIDAY_NM_LY
    , CAL_NET_SALES_LY
    , CAL_TRANS_LY
    , CAL_AVG_CHECK_LY
    , CAL_COMP_SALES_LY
    , CAL_COMP_TRANS_LY
    , CAL_COMP_AVG_CHECK_LY

    --calendar 2 years
    , CAL_COMP_DATE_2Y
    , CAL_HOLIDAY_IND_2Y
    , CAL_HOLIDAY_NM_2Y
    , CAL_NET_SALES_2Y
    , CAL_TRANS_2Y
    , CAL_AVG_CHECK_2Y
    , CAL_COMP_SALES_2Y
    , CAL_COMP_TRANS_2Y
    , CAL_COMP_AVG_CHECK_2Y

    --calendar 3 years
    , CAL_COMP_DATE_3Y
    , CAL_HOLIDAY_IND_3Y
    , CAL_HOLIDAY_NM_3Y
    , CAL_NET_SALES_3Y
    , CAL_TRANS_3Y
    , CAL_AVG_CHECK_3Y
    , CAL_COMP_SALES_3Y
    , CAL_COMP_TRANS_3Y
    , CAL_COMP_AVG_CHECK_3Y
FROM table(DAYPART_FLASH_SUMMARY(FROM_DATE, TO_DATE, ''DAY_CHANNEL'')) main
LEFT JOIN ORDER_CHANNEL_V o
    on main.CHANNEL_ID = o.CHANNEL_ID
ORDER BY 
    BUSINESS_DATE DESC,
    BRAND ASC, 
    STORE_NBR ASC,
    main.CHANNEL_ID
';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_PRODUCT_OFFER_SALES("FROMDATE" DATE, "TODATE" DATE)
RETURNS TABLE ("BUSINESS_DT" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_CD" VARCHAR(16777216), "DMA_NM" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "DAY_OF_WEEK" VARCHAR(16777216), "HOLIDAY_IND_CY" VARCHAR(16777216), "HOLIDAY_NM_CY" VARCHAR(16777216), "MENU_ITEM_ID" NUMBER(38,0), "MDM_ITEM_TYP" VARCHAR(16777216), "MENU_ITEM_NM" VARCHAR(16777216), "MDM_PRODUCT_ID" NUMBER(38,0), "MDM_PRODUCT_NM" VARCHAR(16777216), "MDM_OFFER_ID" NUMBER(38,0), "MDM_OFFER_NM" VARCHAR(16777216), "PRODUCT_SALES_CY" NUMBER(38,2), "DISCOUNT_AMT_CY" NUMBER(38,2), "MENU_ITEM_CNT_CY" NUMBER(38,2), "CHECK_SALES_CY" NUMBER(38,2), "CHECK_CNT_CY" NUMBER(38,2), "REST_SALES_CY" NUMBER(38,2), "REST_TRANS_CY" NUMBER(38,2), "FISC_DATE_LY" DATE, "FISC_HOLIDAY_IND_LY" VARCHAR(16777216), "FISC_HOLIDAY_NM_LY" VARCHAR(16777216), "FISC_PRODUCT_SALES_LY" NUMBER(38,2), "FISC_DISCOUNT_AMT_LY" NUMBER(38,2), "FISC_MENU_ITEM_CNT_LY" NUMBER(38,2), "FISC_CHECK_SALES_LY" NUMBER(38,2), "FISC_CHECK_CNT_LY" NUMBER(38,2), "FISC_REST_SALES_LY" NUMBER(38,2), "FISC_REST_TRANS_LY" NUMBER(38,2), "CAL_COMP_DATE_LY" DATE, "CAL_HOLIDAY_IND_LY" VARCHAR(16777216), "CAL_HOLIDAY_NM_LY" VARCHAR(16777216), "CAL_PRODUCT_SALES_LY" NUMBER(38,2), "CAL_DISCOUNT_AMT_LY" NUMBER(38,2), "CAL_MENU_ITEM_CNT_LY" NUMBER(38,2), "CAL_CHECK_SALES_LY" NUMBER(38,2), "CAL_CHECK_CNT_LY" NUMBER(38,2), "CAL_REST_SALES_LY" NUMBER(38,2), "CAL_REST_TRANS_LY" NUMBER(38,2), "PRODUCT_HIERARCHY_ID" NUMBER(38,0), "LEVEL5_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL4_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL3_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL2_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL1_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "OFFER_HIERARCHY_ID" NUMBER(38,0), "LEVEL5_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL4_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL3_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL2_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL1_OFFER_HIERARCHY_NM" VARCHAR(16777216), "PRODUCT_MISC1" VARCHAR(16777216), "PRODUCT_MISC2" VARCHAR(16777216), "PRODUCT_MISC3" VARCHAR(16777216), "PRODUCT_MISC4" VARCHAR(16777216), "PRODUCT_MISC5" VARCHAR(16777216), "PRODUCT_MISC6" VARCHAR(16777216), "PRODUCT_MISC7" VARCHAR(16777216), "PRODUCT_MISC8" VARCHAR(16777216), "PRODUCT_MISC9" VARCHAR(16777216), "PRODUCT_MISC10" VARCHAR(16777216), "OFFER_MISC1" VARCHAR(16777216), "OFFER_MISC2" VARCHAR(16777216), "OFFER_MISC3" VARCHAR(16777216), "OFFER_MISC4" VARCHAR(16777216), "OFFER_MISC5" VARCHAR(16777216), "OFFER_MISC6" VARCHAR(16777216), "OFFER_MISC7" VARCHAR(16777216), "OFFER_MISC8" VARCHAR(16777216), "OFFER_MISC9" VARCHAR(16777216), "OFFER_MISC10" VARCHAR(16777216))
LANGUAGE SQL
AS '

WITH fisc_date_interval AS
(
SELECT 
    MIN(FISCAL_COMPARABLE_DT) AS MIN_FISCAL_COMPARABLE_DT
    , MAX(FISCAL_COMPARABLE_DT) AS MAX_FISCAL_COMPARABLE_DT 
FROM 
    IDH_DEV.SHARED.DATE_DIM_V dd 
WHERE 
    CALENDAR_DT BETWEEN FromDate AND ToDate
)

, cal_date_interval AS
(
SELECT 
    MIN(CALENDAR_COMPARABLE_DT) AS MIN_CAL_COMPARABLE_DT
    , MAX(CALENDAR_COMPARABLE_DT) AS MAX_CAL_COMPARABLE_DT 
FROM 
    IDH_DEV.SHARED.DATE_DIM_V dd 
WHERE 
    CALENDAR_DT BETWEEN FromDate AND ToDate
)

, src AS
(
SELECT
    od.ORDER_ID
    , od.ORDER_DT AS BUSINESS_DT
    , CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
         WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
         WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
         WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
         WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
         WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
         WHEN od.BRAND_ID = ''rto'' THEN ''RT''
         ELSE ''UNKNOWN'' END AS BRAND
    , od.STORE_ID AS STORE_NBR
    , IFNULL(st.DMA_CD, '''') AS DMA_CD
    , IFNULL(st.DMA_NM, '''') AS DMA_NM
    , IFNULL(lv.LEVEL1_NM, '''') AS L1NAME
    , IFNULL(lv.LEVEL2_NM, '''') AS L2NAME
    , IFNULL(lv.LEVEL3_NM, '''') AS L3NAME
    , IFNULL(lv.LEVEL4_NM, '''') AS L4NAME
    , IFNULL(lv.LEVEL5_NM, '''') AS L5NAME
    , IFNULL(st.OWNERSHIP_TYP, '''') AS OWNERSHIP_TYP
    , IFNULL(st.STATE_NM, '''') AS STATE
    , IFNULL(st.COUNTRY_NM, '''') AS COUNTRY
    , dd.FISCAL_YEAR_NBR AS FISC_YEAR_NBR
    , dd.FISCAL_QUARTER_NBR AS FISC_QUARTER_NBR
    , dd.FISCAL_PERIOD_NBR AS FISC_PERIOD_NBR
    , dd.FISCAL_WEEK_NBR AS FISC_WEEK_NBR
    , dd.CALENDAR_DAY_NM AS DAY_OF_WEEK

    , CASE WHEN UPPER(CAST(hlf.HOLIDAY_IND AS VARCHAR(10))) = ''TRUE'' THEN ''Y''
           WHEN UPPER(CAST(hlf.HOLIDAY_IND AS VARCHAR(10))) = ''FALSE'' THEN ''N''
           ELSE NULL END AS HOLIDAY_IND_CY
    , hlf.HOLIDAY_LIST_NM AS HOLIDAY_NM_CY

    , IFNULL(od.MDM_ITEM_ID, 0) AS MENU_ITEM_ID
    , IFNULL(od.MDM_ITEM_TYP, '''') AS MDM_ITEM_TYP
    , IFNULL(od.ITEM_NM, '''') AS MENU_ITEM_NM
    , IFNULL(od.MDM_PRODUCT_ID, 0) AS MDM_PRODUCT_ID
    , IFNULL(od.PRODUCT_NM, '''') AS MDM_PRODUCT_NM
    , IFNULL(od.MDM_OFFER_ID, 0) AS MDM_OFFER_ID
    , IFNULL(od.OFFER_NM, '''') AS MDM_OFFER_NM

    , IFNULL(od.PRODUCT_HIERARCHY_ID, 0) AS PRODUCT_HIERARCHY_ID
    , IFNULL(od.LEVEL5_PRODUCT_HIERARCHY_NM, '''') AS LEVEL5_PRODUCT_HIERARCHY_NM
    , IFNULL(od.LEVEL4_PRODUCT_HIERARCHY_NM, '''') AS LEVEL4_PRODUCT_HIERARCHY_NM
    , IFNULL(od.LEVEL3_PRODUCT_HIERARCHY_NM, '''') AS LEVEL3_PRODUCT_HIERARCHY_NM
    , IFNULL(od.LEVEL2_PRODUCT_HIERARCHY_NM, '''') AS LEVEL2_PRODUCT_HIERARCHY_NM
    , IFNULL(od.LEVEL1_PRODUCT_HIERARCHY_NM, '''') AS LEVEL1_PRODUCT_HIERARCHY_NM

    , IFNULL(od.OFFER_HIERARCHY_ID, 0) AS OFFER_HIERARCHY_ID
    , IFNULL(od.LEVEL5_OFFER_HIERARCHY_NM, '''') AS LEVEL5_OFFER_HIERARCHY_NM
    , IFNULL(od.LEVEL4_OFFER_HIERARCHY_NM, '''') AS LEVEL4_OFFER_HIERARCHY_NM
    , IFNULL(od.LEVEL3_OFFER_HIERARCHY_NM, '''') AS LEVEL3_OFFER_HIERARCHY_NM
    , IFNULL(od.LEVEL2_OFFER_HIERARCHY_NM, '''') AS LEVEL2_OFFER_HIERARCHY_NM
    , IFNULL(od.LEVEL1_OFFER_HIERARCHY_NM, '''') AS LEVEL1_OFFER_HIERARCHY_NM
    , IFNULL(od.PRODUCT_MISC1, '''') AS PRODUCT_MISC1
    , IFNULL(od.PRODUCT_MISC2, '''') AS PRODUCT_MISC2
    , IFNULL(od.PRODUCT_MISC3, '''') AS PRODUCT_MISC3
    , IFNULL(od.PRODUCT_MISC4, '''') AS PRODUCT_MISC4
    , IFNULL(od.PRODUCT_MISC5, '''') AS PRODUCT_MISC5
    , IFNULL(od.PRODUCT_MISC6, '''') AS PRODUCT_MISC6
    , IFNULL(od.PRODUCT_MISC7, '''') AS PRODUCT_MISC7
    , IFNULL(od.PRODUCT_MISC8, '''') AS PRODUCT_MISC8
    , IFNULL(od.PRODUCT_MISC9, '''') AS PRODUCT_MISC9
    , IFNULL(od.PRODUCT_MISC10, '''') AS PRODUCT_MISC10
  
    , IFNULL(od.OFFER_MISC1, '''') AS OFFER_MISC1
    , IFNULL(od.OFFER_MISC2, '''') AS OFFER_MISC2
    , IFNULL(od.OFFER_MISC3, '''') AS OFFER_MISC3
    , IFNULL(od.OFFER_MISC4, '''') AS OFFER_MISC4
    , IFNULL(od.OFFER_MISC5, '''') AS OFFER_MISC5
    , IFNULL(od.OFFER_MISC6, '''') AS OFFER_MISC6
    , IFNULL(od.OFFER_MISC7, '''') AS OFFER_MISC7
    , IFNULL(od.OFFER_MISC8, '''') AS OFFER_MISC8
    , IFNULL(od.OFFER_MISC9, '''') AS OFFER_MISC9
    , IFNULL(od.OFFER_MISC10, '''') AS OFFER_MISC10

    , od.DERIVED_NET_AMT
  
    , SUM(od.DERIVED_NET_AMT) OVER(PARTITION BY od.BRAND_ID, od.STORE_ID, od.ORDER_DT, IFNULL(od.MDM_ITEM_ID, 0)) AS PRODUCT_SALES_CY

    , SUM(od.DERIVED_DISCOUNT_AMT) OVER(PARTITION BY od.BRAND_ID, od.STORE_ID, od.ORDER_DT, IFNULL(od.MDM_ITEM_ID, 0)) AS DISCOUNT_AMT_CY
    , SUM(od.DERIVED_GROSS_QTY) OVER(PARTITION BY od.BRAND_ID, od.STORE_ID, od.ORDER_DT, IFNULL(od.MDM_ITEM_ID, 0)) AS MENU_ITEM_CNT_CY
  
    , SUM(od.DERIVED_NET_AMT) OVER(PARTITION BY od.ORDER_ID) AS CHECK_SALES_CY
    , ROW_NUMBER() OVER(PARTITION BY od.ORDER_ID, IFNULL(od.MDM_ITEM_ID, 0) ORDER BY od.ORDER_ID, IFNULL(od.MDM_ITEM_ID, 0)) AS Rn_CHECK_SALES_CY

    , SUM(od.DERIVED_NET_AMT) OVER(PARTITION BY od.BRAND_ID, od.STORE_ID, od.ORDER_DT) AS REST_SALES_CY
    , COUNT(DISTINCT od.ORDER_ID) OVER(PARTITION BY od.BRAND_ID, od.STORE_ID, od.ORDER_DT) AS REST_TRANS_CY
  
    , dd.FISCAL_COMPARABLE_DT AS FISC_DATE_LY
    , CASE WHEN UPPER(CAST(fisc_dat.HOLIDAY_IND AS VARCHAR(10))) = ''TRUE'' THEN ''Y''
           WHEN UPPER(CAST(fisc_dat.HOLIDAY_IND AS VARCHAR(10))) = ''FALSE'' THEN ''N''
           ELSE NULL END AS FISC_HOLIDAY_IND_LY
  
    , fisc_dat.HOLIDAY_LIST_NM AS FISC_HOLIDAY_NM_LY
    , dd.CALENDAR_COMPARABLE_DT AS CAL_COMP_DATE_LY
    , CASE WHEN UPPER(CAST(hl_cal.HOLIDAY_IND AS VARCHAR(10))) = ''TRUE'' THEN ''Y''
           WHEN UPPER(CAST(hl_cal.HOLIDAY_IND AS VARCHAR(10))) = ''FALSE'' THEN ''N''
           ELSE NULL END AS CAL_HOLIDAY_IND_LY
    , hl_cal.HOLIDAY_LIST_NM AS CAL_HOLIDAY_NM_LY

    , ROW_NUMBER() OVER(PARTITION BY od.ORDER_DT, od.BRAND_ID, od.STORE_ID, IFNULL(od.MDM_ITEM_ID, 0) ORDER BY od.ORDER_DT, od.BRAND_ID, od.STORE_ID, IFNULL(od.MDM_ITEM_ID, 0)) AS Rn
FROM
    ORDER_DETAIL_V od
INNER JOIN
    IDH_DEV.SHARED.DATE_DIM_V dd
ON  dd.CALENDAR_DT = od.ORDER_DT
INNER JOIN
    IDH_DEV.SHARED.STORE_SCD_V st
ON  st.STORE_ID = od.STORE_ID
AND st.BRAND_ID = od.BRAND_ID
AND od.ORDER_DT BETWEEN st.EFFECTIVE_BEGIN_DT AND st.EFFECTIVE_END_DT
AND IFNULL(st.CLOSURE_DT, ''9999-12-31'') >= (SELECT DATE_TRUNC(''YEAR'', MIN(DT)) AS Ref_Date FROM (SELECT MIN(MIN_FISCAL_COMPARABLE_DT) AS DT FROM fisc_date_interval UNION SELECT MIN(MIN_CAL_COMPARABLE_DT) AS DT FROM cal_date_interval))
AND st.COUNTRY_NM IN (''US'', ''USA'')
LEFT OUTER JOIN 
    IDH_DEV.OPERATION.LOCATION_HIERARCHY_V lv
ON  lv.LOCATION_ID = od.STORE_ID
AND lv.BRAND_ID = od.BRAND_ID
LEFT OUTER JOIN
    IDH_DEV.SHARED.HOLIDAY_LIST_V hlf
ON  TO_DATE(CAST(hlf.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = od.ORDER_DT
LEFT OUTER JOIN
    IDH_DEV.SHARED.HOLIDAY_LIST_V fisc_dat
ON  TO_DATE(CAST(fisc_dat.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = dd.FISCAL_COMPARABLE_DT
LEFT OUTER JOIN
    IDH_DEV.SHARED.HOLIDAY_LIST_V hl_cal
ON  TO_DATE(CAST(hl_cal.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = dd.CALENDAR_COMPARABLE_DT
WHERE
    IFNULL((CASE WHEN UPPER(CAST(VOIDED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(VOIDED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND IFNULL((CASE WHEN UPPER(CAST(CLEARED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(CLEARED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND IFNULL((CASE WHEN UPPER(CAST(DELETED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(DELETED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND od.ORDER_DT BETWEEN FromDate AND ToDate
)

, src_prel AS
(
SELECT
    src.BUSINESS_DT
    , src.BRAND
    , src.STORE_NBR
    , MAX(src.DMA_CD) AS DMA_CD
    , MAX(src.DMA_NM) AS DMA_NM
    , MAX(src.L1NAME) AS L1NAME
    , MAX(src.L2NAME) AS L2NAME
    , MAX(src.L3NAME) AS L3NAME
    , MAX(src.L4NAME) AS L4NAME
    , MAX(src.L5NAME) AS L5NAME
    , MAX(src.OWNERSHIP_TYP) AS OWNERSHIP_TYP
    , MAX(src.STATE) AS STATE
    , MAX(src.COUNTRY) AS COUNTRY
    , MAX(src.FISC_YEAR_NBR) AS FISC_YEAR_NBR
    , MAX(src.FISC_QUARTER_NBR) AS FISC_QUARTER_NBR
    , MAX(src.FISC_PERIOD_NBR) AS FISC_PERIOD_NBR
    , MAX(src.FISC_WEEK_NBR) AS FISC_WEEK_NBR
    , MAX(src.DAY_OF_WEEK) AS DAY_OF_WEEK
    , MAX(src.HOLIDAY_IND_CY) AS HOLIDAY_IND_CY
    , MAX(src.HOLIDAY_NM_CY) AS HOLIDAY_NM_CY
    , src.MENU_ITEM_ID
    , MAX(src.MDM_ITEM_TYP) AS MDM_ITEM_TYP
    , MAX(src.MENU_ITEM_NM) AS MENU_ITEM_NM
    , MAX(src.MDM_PRODUCT_ID) AS MDM_PRODUCT_ID
    , MAX(src.MDM_PRODUCT_NM) AS MDM_PRODUCT_NM
    , MAX(src.MDM_OFFER_ID) AS MDM_OFFER_ID
    , MAX(src.MDM_OFFER_NM) AS MDM_OFFER_NM

    , MAX(src.PRODUCT_SALES_CY) AS PRODUCT_SALES_CY
    , MAX(src.DISCOUNT_AMT_CY) AS DISCOUNT_AMT_CY
    , MAX(src.MENU_ITEM_CNT_CY) AS MENU_ITEM_CNT_CY
    , MAX(src.REST_SALES_CY) AS REST_SALES_CY
    , MAX(src.REST_TRANS_CY) AS REST_TRANS_CY
    , MAX(src.DERIVED_NET_AMT) AS DERIVED_NET_AMT

    , MAX(src.FISC_DATE_LY) AS FISC_DATE_LY
    , MAX(src.FISC_HOLIDAY_IND_LY) AS FISC_HOLIDAY_IND_LY
    , MAX(src.FISC_HOLIDAY_NM_LY) AS FISC_HOLIDAY_NM_LY
    
    , MAX(src.CAL_COMP_DATE_LY) AS CAL_COMP_DATE_LY
    , MAX(src.CAL_HOLIDAY_IND_LY) AS CAL_HOLIDAY_IND_LY
    , MAX(src.CAL_HOLIDAY_NM_LY) AS CAL_HOLIDAY_NM_LY
  
    , MAX(src.PRODUCT_HIERARCHY_ID) AS PRODUCT_HIERARCHY_ID
    , MAX(src.LEVEL5_PRODUCT_HIERARCHY_NM) AS LEVEL5_PRODUCT_HIERARCHY_NM
    , MAX(src.LEVEL4_PRODUCT_HIERARCHY_NM) AS LEVEL4_PRODUCT_HIERARCHY_NM
    , MAX(src.LEVEL3_PRODUCT_HIERARCHY_NM) AS LEVEL3_PRODUCT_HIERARCHY_NM
    , MAX(src.LEVEL2_PRODUCT_HIERARCHY_NM) AS LEVEL2_PRODUCT_HIERARCHY_NM
    , MAX(src.LEVEL1_PRODUCT_HIERARCHY_NM) AS LEVEL1_PRODUCT_HIERARCHY_NM
    
    , MAX(src.OFFER_HIERARCHY_ID) AS OFFER_HIERARCHY_ID
    , MAX(src.LEVEL5_OFFER_HIERARCHY_NM) AS LEVEL5_OFFER_HIERARCHY_NM
    , MAX(src.LEVEL4_OFFER_HIERARCHY_NM) AS LEVEL4_OFFER_HIERARCHY_NM
    , MAX(src.LEVEL3_OFFER_HIERARCHY_NM) AS LEVEL3_OFFER_HIERARCHY_NM
    , MAX(src.LEVEL2_OFFER_HIERARCHY_NM) AS LEVEL2_OFFER_HIERARCHY_NM
    , MAX(src.LEVEL1_OFFER_HIERARCHY_NM) AS LEVEL1_OFFER_HIERARCHY_NM
  
    , MAX(src.PRODUCT_MISC1) AS PRODUCT_MISC1
    , MAX(src.PRODUCT_MISC2) AS PRODUCT_MISC2
    , MAX(src.PRODUCT_MISC3) AS PRODUCT_MISC3
    , MAX(src.PRODUCT_MISC4) AS PRODUCT_MISC4
    , MAX(src.PRODUCT_MISC5) AS PRODUCT_MISC5
    , MAX(src.PRODUCT_MISC6) AS PRODUCT_MISC6
    , MAX(src.PRODUCT_MISC7) AS PRODUCT_MISC7
    , MAX(src.PRODUCT_MISC8) AS PRODUCT_MISC8
    , MAX(src.PRODUCT_MISC9) AS PRODUCT_MISC9
    , MAX(src.PRODUCT_MISC10) AS PRODUCT_MISC10
  
    , MAX(src.OFFER_MISC1) AS OFFER_MISC1
    , MAX(src.OFFER_MISC2) AS OFFER_MISC2
    , MAX(src.OFFER_MISC3) AS OFFER_MISC3
    , MAX(src.OFFER_MISC4) AS OFFER_MISC4
    , MAX(src.OFFER_MISC5) AS OFFER_MISC5
    , MAX(src.OFFER_MISC6) AS OFFER_MISC6
    , MAX(src.OFFER_MISC7) AS OFFER_MISC7
    , MAX(src.OFFER_MISC8) AS OFFER_MISC8
    , MAX(src.OFFER_MISC9) AS OFFER_MISC9
    , MAX(src.OFFER_MISC10) AS OFFER_MISC10
FROM
    src
WHERE
    Rn = 1
AND src.MDM_ITEM_TYP IN (''Product'', ''Offer'', ''Offer and Product'')
GROUP BY
    src.BUSINESS_DT
    , src.BRAND
    , src.STORE_NBR
    , src.MENU_ITEM_ID
)

, res_current_period AS
(
    SELECT
    sp.BUSINESS_DT
    , sp.BRAND
    , sp.STORE_NBR
    , sp.DMA_CD
    , sp.DMA_NM
    , sp.L1NAME
    , sp.L2NAME
    , sp.L3NAME
    , sp.L4NAME
    , sp.L5NAME
    , sp.OWNERSHIP_TYP
    , sp.STATE
    , sp.COUNTRY
    , sp.FISC_YEAR_NBR
    , sp.FISC_QUARTER_NBR
    , sp.FISC_PERIOD_NBR
    , sp.FISC_WEEK_NBR
    , sp.DAY_OF_WEEK
    , sp.HOLIDAY_IND_CY
    , sp.HOLIDAY_NM_CY
    , sp.MENU_ITEM_ID
    , sp.MDM_ITEM_TYP
    , sp.MENU_ITEM_NM
    , sp.MDM_PRODUCT_ID
    , sp.MDM_PRODUCT_NM
    , sp.MDM_OFFER_ID
    , sp.MDM_OFFER_NM

    , sp.PRODUCT_SALES_CY
    , sp.DISCOUNT_AMT_CY
    , sp.MENU_ITEM_CNT_CY
    , (
        SELECT SUM(CHECK_SALES_CY) AS CHECK_SALES_CY
        FROM
            src
        WHERE
            src.MENU_ITEM_ID = sp.MENU_ITEM_ID
        AND src.BRAND = sp.BRAND
        AND src.STORE_NBR = sp.STORE_NBR
        AND src.BUSINESS_DT = sp.BUSINESS_DT 
        AND src.Rn_CHECK_SALES_CY = 1
      ) AS CHECK_SALES_CY
    , (
        SELECT
            COUNT(DISTINCT ORDER_ID) AS CHECK_CNT_CY
        FROM
            src
        WHERE
            src.MENU_ITEM_ID = sp.MENU_ITEM_ID
        AND src.BRAND = sp.BRAND
        AND src.STORE_NBR = sp.STORE_NBR
        AND src.BUSINESS_DT = sp.BUSINESS_DT 
      ) AS CHECK_CNT_CY
    , sp.REST_SALES_CY
    , sp.REST_TRANS_CY

    , sp.FISC_DATE_LY
    , sp.FISC_HOLIDAY_IND_LY
    , sp.FISC_HOLIDAY_NM_LY
    
    , sp.CAL_COMP_DATE_LY
    , sp.CAL_HOLIDAY_IND_LY
    , sp.CAL_HOLIDAY_NM_LY
    
    , sp.PRODUCT_HIERARCHY_ID
    , sp.LEVEL5_PRODUCT_HIERARCHY_NM
    , sp.LEVEL4_PRODUCT_HIERARCHY_NM
    , sp.LEVEL3_PRODUCT_HIERARCHY_NM
    , sp.LEVEL2_PRODUCT_HIERARCHY_NM
    , sp.LEVEL1_PRODUCT_HIERARCHY_NM
  
    , sp.OFFER_HIERARCHY_ID
    , sp.LEVEL5_OFFER_HIERARCHY_NM
    , sp.LEVEL4_OFFER_HIERARCHY_NM
    , sp.LEVEL3_OFFER_HIERARCHY_NM
    , sp.LEVEL2_OFFER_HIERARCHY_NM
    , sp.LEVEL1_OFFER_HIERARCHY_NM
  
    , sp.PRODUCT_MISC1
    , sp.PRODUCT_MISC2
    , sp.PRODUCT_MISC3
    , sp.PRODUCT_MISC4
    , sp.PRODUCT_MISC5
    , sp.PRODUCT_MISC6
    , sp.PRODUCT_MISC7
    , sp.PRODUCT_MISC8
    , sp.PRODUCT_MISC9
    , sp.PRODUCT_MISC10
    
    , sp.OFFER_MISC1
    , sp.OFFER_MISC2
    , sp.OFFER_MISC3
    , sp.OFFER_MISC4
    , sp.OFFER_MISC5
    , sp.OFFER_MISC6
    , sp.OFFER_MISC7
    , sp.OFFER_MISC8
    , sp.OFFER_MISC9
    , sp.OFFER_MISC10
FROM
    src_prel sp
)

, pre_final AS
(
SELECT
    COALESCE(rcp.BUSINESS_DT, fsc.FISC_ORIG_BUSINESS_DT, cal.CAL_ORIG_BUSINESS_DT) AS BUSINESS_DT
    , COALESCE(rcp.BRAND, fsc.BRAND, cal.BRAND) AS BRAND
    , COALESCE(rcp.STORE_NBR, fsc.STORE_NBR, cal.STORE_NBR) AS STORE_NBR
    , COALESCE(rcp.DMA_CD, fsc.DMA_CD, cal.DMA_CD) AS DMA_CD
    , COALESCE(rcp.DMA_NM, fsc.DMA_NM, cal.DMA_NM) AS DMA_NM
    , NULLIF(COALESCE(rcp.L1NAME, fsc.L1NAME, cal.L1NAME), '''') AS L1NAME
    , NULLIF(COALESCE(rcp.L2NAME, fsc.L2NAME, cal.L2NAME), '''') AS L2NAME
    , NULLIF(COALESCE(rcp.L3NAME, fsc.L3NAME, cal.L3NAME), '''') AS L3NAME
    , NULLIF(COALESCE(rcp.L4NAME, fsc.L4NAME, cal.L4NAME), '''') AS L4NAME
    , NULLIF(COALESCE(rcp.L5NAME, fsc.L5NAME, cal.L5NAME), '''') AS L5NAME
    , COALESCE(rcp.OWNERSHIP_TYP, fsc.OWNERSHIP_TYP, cal.OWNERSHIP_TYP) AS OWNERSHIP_TYP
    , COALESCE(rcp.STATE, fsc.STATE, cal.STATE) AS STATE
    , COALESCE(rcp.COUNTRY, fsc.COUNTRY, cal.COUNTRY) AS COUNTRY
    
    
    
    , COALESCE(rcp.FISC_YEAR_NBR, dd_fisc_up.FISCAL_YEAR_NBR, dd_cal_up.FISCAL_YEAR_NBR) AS FISCAL_YEAR_NBR
    , COALESCE(rcp.FISC_QUARTER_NBR, dd_fisc_up.FISCAL_QUARTER_NBR, dd_cal_up.FISCAL_QUARTER_NBR) AS FISCAL_QUARTER_NBR
    , COALESCE(rcp.FISC_PERIOD_NBR, dd_fisc_up.FISCAL_PERIOD_NBR, dd_cal_up.FISCAL_PERIOD_NBR) AS FISCAL_PERIOD_NBR
    , COALESCE(rcp.FISC_WEEK_NBR, dd_fisc_up.FISCAL_WEEK_NBR, dd_cal_up.FISCAL_WEEK_NBR) AS FISCAL_WEEK_NBR
    , COALESCE(rcp.DAY_OF_WEEK, dd_fisc_up.CALENDAR_DAY_NM, dd_cal_up.CALENDAR_DAY_NM) AS CALENDAR_DAY_NM
    
    , IFNULL(CASE WHEN UPPER(CAST(dd_dat.HOLIDAY_IND AS VARCHAR(10))) = ''TRUE'' THEN ''Y''
                  WHEN UPPER(CAST(dd_dat.HOLIDAY_IND AS VARCHAR(10))) = ''FALSE'' THEN ''N''
                  ELSE NULL END, ''N'') AS HOLIDAY_IND_CY              
    , dd_dat.HOLIDAY_LIST_NM AS HOLIDAY_NM_CY
    , COALESCE(rcp.MENU_ITEM_ID, fsc.MENU_ITEM_ID, cal.MENU_ITEM_ID) AS MENU_ITEM_ID
    , COALESCE(rcp.MDM_ITEM_TYP, fsc.MDM_ITEM_TYP, cal.MDM_ITEM_TYP) AS MDM_ITEM_TYP
    , COALESCE(rcp.MENU_ITEM_NM, fsc.MENU_ITEM_NM, cal.MENU_ITEM_NM) AS MENU_ITEM_NM
    , NULLIF(COALESCE(rcp.MDM_PRODUCT_ID, fsc.MDM_PRODUCT_ID, cal.MDM_PRODUCT_ID), 0) AS MDM_PRODUCT_ID
    , NULLIF(COALESCE(rcp.MDM_PRODUCT_NM, fsc.MDM_PRODUCT_NM, cal.MDM_PRODUCT_NM), '''') AS MDM_PRODUCT_NM
    , NULLIF(COALESCE(rcp.MDM_OFFER_ID, fsc.MDM_OFFER_ID, cal.MDM_OFFER_ID), 0) AS MDM_OFFER_ID
    , NULLIF(COALESCE(rcp.MDM_OFFER_NM, fsc.MDM_OFFER_NM, cal.MDM_OFFER_NM), '''') AS MDM_OFFER_NM

    , IFNULL(rcp.PRODUCT_SALES_CY, 0.00) AS PRODUCT_SALES_CY
    , IFNULL(rcp.DISCOUNT_AMT_CY, 0.00) AS DISCOUNT_AMT_CY
    , IFNULL(rcp.MENU_ITEM_CNT_CY, 0) AS MENU_ITEM_CNT_CY
    , IFNULL(rcp.CHECK_SALES_CY, 0.00) AS CHECK_SALES_CY
    , IFNULL(rcp.CHECK_CNT_CY, 0) AS CHECK_CNT_CY
    , IFNULL(rcp.REST_SALES_CY, 0.00) AS REST_SALES_CY
    , IFNULL(rcp.REST_TRANS_CY, 0) AS REST_TRANS_CY

    , COALESCE(rcp.FISC_DATE_LY, fsc.BUSINESS_DT, dd.FISCAL_COMPARABLE_DT) AS FISC_DATE_LY

    , IFNULL(fsc.HOLIDAY_IND_CY
                , IFNULL(CASE WHEN UPPER(CAST(fisc_dat.HOLIDAY_IND AS VARCHAR(10))) = ''TRUE'' THEN ''Y''
                  WHEN UPPER(CAST(fisc_dat.HOLIDAY_IND AS VARCHAR(10))) = ''FALSE'' THEN ''N''
                  ELSE NULL END, ''N'')
            ) AS FISC_HOLIDAY_IND_LY
    , IFNULL(rcp.FISC_HOLIDAY_NM_LY, fsc.HOLIDAY_NM_CY) AS FISC_HOLIDAY_NM_LY

    , IFNULL(fsc.PRODUCT_SALES_CY, 0.00) AS FISC_PRODUCT_SALES_LY
    , IFNULL(fsc.DISCOUNT_AMT_CY, 0.00) AS FISC_DISCOUNT_AMT_LY
    , IFNULL(fsc.MENU_ITEM_CNT_CY, 0) AS FISC_MENU_ITEM_CNT_LY
    , IFNULL(fsc.CHECK_SALES_CY, 0.00) AS FISC_CHECK_SALES_LY
    , IFNULL(fsc.CHECK_CNT_CY, 0) AS FISC_CHECK_CNT_LY
    , IFNULL(fsc.REST_SALES_CY, 0.00) AS FISC_REST_SALES_LY
    , IFNULL(fsc.REST_TRANS_CY, 0) AS FISC_REST_TRANS_LY

    , COALESCE(rcp.CAL_COMP_DATE_LY, cal.BUSINESS_DT, dd.CALENDAR_COMPARABLE_DT) AS CAL_COMP_DATE_LY
    , IFNULL(cal.HOLIDAY_NM_CY 
                , IFNULL(CASE WHEN UPPER(CAST(cal_dat.HOLIDAY_IND AS VARCHAR(10))) = ''TRUE'' THEN ''Y''
                  WHEN UPPER(CAST(cal_dat.HOLIDAY_IND AS VARCHAR(10))) = ''FALSE'' THEN ''N''
                  ELSE NULL END, ''N'') 
    ) AS CAL_HOLIDAY_IND_LY
    , IFNULL(rcp.CAL_HOLIDAY_NM_LY, cal.HOLIDAY_NM_CY) AS CAL_HOLIDAY_NM_LY
    , IFNULL(cal.PRODUCT_SALES_CY, 0.00) AS CAL_PRODUCT_SALES_LY
    , IFNULL(cal.DISCOUNT_AMT_CY, 0.00) AS CAL_DISCOUNT_AMT_LY
    , IFNULL(cal.MENU_ITEM_CNT_CY, 0) AS CAL_MENU_ITEM_CNT_LY
    , IFNULL(cal.CHECK_SALES_CY, 0.00) AS CAL_CHECK_SALES_LY
    , IFNULL(cal.CHECK_CNT_CY, 0) AS CAL_CHECK_CNT_LY
    , IFNULL(cal.REST_SALES_CY, 0.00) AS CAL_REST_SALES_LY
    , IFNULL(cal.REST_TRANS_CY, 0) AS CAL_REST_TRANS_LY

    , NULLIF(COALESCE(rcp.PRODUCT_HIERARCHY_ID, fsc.PRODUCT_HIERARCHY_ID, cal.PRODUCT_HIERARCHY_ID), 0) AS PRODUCT_HIERARCHY_ID
    , NULLIF(COALESCE(rcp.LEVEL5_PRODUCT_HIERARCHY_NM, fsc.LEVEL5_PRODUCT_HIERARCHY_NM, cal.LEVEL5_PRODUCT_HIERARCHY_NM), '''') AS LEVEL5_PRODUCT_HIERARCHY_NM
    , NULLIF(COALESCE(rcp.LEVEL4_PRODUCT_HIERARCHY_NM, fsc.LEVEL4_PRODUCT_HIERARCHY_NM, cal.LEVEL4_PRODUCT_HIERARCHY_NM), '''') AS LEVEL4_PRODUCT_HIERARCHY_NM
    , NULLIF(COALESCE(rcp.LEVEL3_PRODUCT_HIERARCHY_NM, fsc.LEVEL3_PRODUCT_HIERARCHY_NM, cal.LEVEL3_PRODUCT_HIERARCHY_NM), '''') AS LEVEL3_PRODUCT_HIERARCHY_NM
    , NULLIF(COALESCE(rcp.LEVEL2_PRODUCT_HIERARCHY_NM, fsc.LEVEL2_PRODUCT_HIERARCHY_NM, cal.LEVEL2_PRODUCT_HIERARCHY_NM), '''') AS LEVEL2_PRODUCT_HIERARCHY_NM
    , NULLIF(COALESCE(rcp.LEVEL1_PRODUCT_HIERARCHY_NM, fsc.LEVEL1_PRODUCT_HIERARCHY_NM, cal.LEVEL1_PRODUCT_HIERARCHY_NM), '''') AS LEVEL1_PRODUCT_HIERARCHY_NM
    , NULLIF(COALESCE(rcp.OFFER_HIERARCHY_ID, fsc.OFFER_HIERARCHY_ID, cal.OFFER_HIERARCHY_ID), 0) AS OFFER_HIERARCHY_ID
    , NULLIF(COALESCE(rcp.LEVEL5_OFFER_HIERARCHY_NM, fsc.LEVEL5_OFFER_HIERARCHY_NM, cal.LEVEL5_OFFER_HIERARCHY_NM), '''') AS LEVEL5_OFFER_HIERARCHY_NM
    , NULLIF(COALESCE(rcp.LEVEL4_OFFER_HIERARCHY_NM, fsc.LEVEL4_OFFER_HIERARCHY_NM, cal.LEVEL4_OFFER_HIERARCHY_NM), '''') AS LEVEL4_OFFER_HIERARCHY_NM
    , NULLIF(COALESCE(rcp.LEVEL3_OFFER_HIERARCHY_NM, fsc.LEVEL3_OFFER_HIERARCHY_NM, cal.LEVEL3_OFFER_HIERARCHY_NM), '''') AS LEVEL3_OFFER_HIERARCHY_NM
    , NULLIF(COALESCE(rcp.LEVEL2_OFFER_HIERARCHY_NM, fsc.LEVEL2_OFFER_HIERARCHY_NM, cal.LEVEL2_OFFER_HIERARCHY_NM), '''') AS LEVEL2_OFFER_HIERARCHY_NM
    , NULLIF(COALESCE(rcp.LEVEL1_OFFER_HIERARCHY_NM, fsc.LEVEL1_OFFER_HIERARCHY_NM, cal.LEVEL1_OFFER_HIERARCHY_NM), '''') AS LEVEL1_OFFER_HIERARCHY_NM
    , NULLIF(COALESCE(rcp.PRODUCT_MISC1, fsc.PRODUCT_MISC1, cal.PRODUCT_MISC1), '''') AS PRODUCT_MISC1
    , NULLIF(COALESCE(rcp.PRODUCT_MISC2, fsc.PRODUCT_MISC2, cal.PRODUCT_MISC2), '''') AS PRODUCT_MISC2
    , NULLIF(COALESCE(rcp.PRODUCT_MISC3, fsc.PRODUCT_MISC3, cal.PRODUCT_MISC3), '''') AS PRODUCT_MISC3
    , NULLIF(COALESCE(rcp.PRODUCT_MISC4, fsc.PRODUCT_MISC4, cal.PRODUCT_MISC4), '''') AS PRODUCT_MISC4
    , NULLIF(COALESCE(rcp.PRODUCT_MISC5, fsc.PRODUCT_MISC5, cal.PRODUCT_MISC5), '''') AS PRODUCT_MISC5
    , NULLIF(COALESCE(rcp.PRODUCT_MISC6, fsc.PRODUCT_MISC6, cal.PRODUCT_MISC6), '''') AS PRODUCT_MISC6
    , NULLIF(COALESCE(rcp.PRODUCT_MISC7, fsc.PRODUCT_MISC7, cal.PRODUCT_MISC7), '''') AS PRODUCT_MISC7
    , NULLIF(COALESCE(rcp.PRODUCT_MISC8, fsc.PRODUCT_MISC8, cal.PRODUCT_MISC8), '''') AS PRODUCT_MISC8
    , NULLIF(COALESCE(rcp.PRODUCT_MISC9, fsc.PRODUCT_MISC9, cal.PRODUCT_MISC9), '''') AS PRODUCT_MISC9
    , NULLIF(COALESCE(rcp.PRODUCT_MISC10, fsc.PRODUCT_MISC10, cal.PRODUCT_MISC10), '''') AS PRODUCT_MISC10
    , NULLIF(COALESCE(rcp.OFFER_MISC1, fsc.OFFER_MISC1, cal.OFFER_MISC1), '''') AS OFFER_MISC1
    , NULLIF(COALESCE(rcp.OFFER_MISC2, fsc.OFFER_MISC2, cal.OFFER_MISC2), '''') AS OFFER_MISC2
    , NULLIF(COALESCE(rcp.OFFER_MISC3, fsc.OFFER_MISC3, cal.OFFER_MISC3), '''') AS OFFER_MISC3
    , NULLIF(COALESCE(rcp.OFFER_MISC4, fsc.OFFER_MISC4, cal.OFFER_MISC4), '''') AS OFFER_MISC4
    , NULLIF(COALESCE(rcp.OFFER_MISC5, fsc.OFFER_MISC5, cal.OFFER_MISC5), '''') AS OFFER_MISC5
    , NULLIF(COALESCE(rcp.OFFER_MISC6, fsc.OFFER_MISC6, cal.OFFER_MISC6), '''') AS OFFER_MISC6
    , NULLIF(COALESCE(rcp.OFFER_MISC7, fsc.OFFER_MISC7, cal.OFFER_MISC7), '''') AS OFFER_MISC7
    , NULLIF(COALESCE(rcp.OFFER_MISC8, fsc.OFFER_MISC8, cal.OFFER_MISC8), '''') AS OFFER_MISC8
    , NULLIF(COALESCE(rcp.OFFER_MISC9, fsc.OFFER_MISC9, cal.OFFER_MISC9), '''') AS OFFER_MISC9
    , NULLIF(COALESCE(rcp.OFFER_MISC10, fsc.OFFER_MISC10, cal.OFFER_MISC10), '''') AS OFFER_MISC10
FROM 
    res_current_period rcp
FULL OUTER JOIN
    TABLE(INSPIRE_DAILY_PRODUCT_OFFER_SALES_COMP((SELECT MIN(MIN_FISCAL_COMPARABLE_DT) FROM fisc_date_interval), (SELECT MIN(MAX_FISCAL_COMPARABLE_DT) FROM fisc_date_interval))) fsc
ON  rcp.MENU_ITEM_ID = fsc.MENU_ITEM_ID
AND rcp.BUSINESS_DT = fsc.FISC_ORIG_BUSINESS_DT
AND rcp.BRAND = fsc.BRAND
AND rcp.STORE_NBR = fsc.STORE_NBR

FULL OUTER JOIN
    TABLE(INSPIRE_DAILY_PRODUCT_OFFER_SALES_COMP((SELECT MIN(MIN_CAL_COMPARABLE_DT) FROM cal_date_interval), (SELECT MIN(MIN_CAL_COMPARABLE_DT) FROM cal_date_interval))) cal
ON  IFNULL(rcp.MENU_ITEM_ID, fsc.MENU_ITEM_ID) = cal.MENU_ITEM_ID
AND IFNULL(rcp.BUSINESS_DT, fsc.FISC_ORIG_BUSINESS_DT) = cal.CAL_ORIG_BUSINESS_DT
AND IFNULL(rcp.BRAND, fsc.BRAND) = cal.BRAND
AND IFNULL(rcp.STORE_NBR, fsc.STORE_NBR) = cal.STORE_NBR

LEFT OUTER JOIN
    IDH_DEV.SHARED.DATE_DIM_V dd
ON  dd.CALENDAR_DT = COALESCE(rcp.BUSINESS_DT, fsc.FISC_ORIG_BUSINESS_DT, cal.CAL_ORIG_BUSINESS_DT)
LEFT OUTER JOIN
    IDH_DEV.SHARED.HOLIDAY_LIST_V dd_dat
ON  TO_DATE(CAST(dd_dat.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = dd.CALENDAR_DT


LEFT OUTER JOIN
    IDH_DEV.SHARED.DATE_DIM_V dd_fisc_up
ON  dd_fisc_up.FISCAL_COMPARABLE_DT = COALESCE(rcp.CAL_COMP_DATE_LY, fsc.BUSINESS_DT, cal.BUSINESS_DT)
LEFT OUTER JOIN
    IDH_DEV.SHARED.HOLIDAY_LIST_V fisc_dat
ON  TO_DATE(CAST(fisc_dat.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = COALESCE(rcp.FISC_DATE_LY, fsc.BUSINESS_DT, dd.FISCAL_COMPARABLE_DT)

LEFT OUTER JOIN
    IDH_DEV.SHARED.DATE_DIM_V dd_cal_up
ON  dd_cal_up.CALENDAR_COMPARABLE_DT = COALESCE(rcp.CAL_COMP_DATE_LY, cal.BUSINESS_DT, fsc.BUSINESS_DT)
LEFT OUTER JOIN
    IDH_DEV.SHARED.HOLIDAY_LIST_V cal_dat
ON  TO_DATE(CAST(cal_dat.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = COALESCE(rcp.CAL_COMP_DATE_LY, cal.BUSINESS_DT, dd.CALENDAR_COMPARABLE_DT)

WHERE
    COALESCE(rcp.BUSINESS_DT, fsc.FISC_ORIG_BUSINESS_DT, cal.CAL_ORIG_BUSINESS_DT) BETWEEN FromDate AND ToDate
)

SELECT
    BUSINESS_DT
    , BRAND
    , STORE_NBR
    , DMA_CD
    , DMA_NM
    , L1NAME
    , L2NAME
    , L3NAME
    , L4NAME
    , L5NAME
    , OWNERSHIP_TYP
    , STATE
    , COUNTRY

    , FISCAL_YEAR_NBR
    , FISCAL_QUARTER_NBR
    , FISCAL_PERIOD_NBR
    , FISCAL_WEEK_NBR
    , CALENDAR_DAY_NM

    , HOLIDAY_IND_CY              
    , HOLIDAY_NM_CY
    , MENU_ITEM_ID
    , MDM_ITEM_TYP
    , MENU_ITEM_NM
    , MDM_PRODUCT_ID
    , MDM_PRODUCT_NM
    , MDM_OFFER_ID
    , MDM_OFFER_NM

    , CAST(PRODUCT_SALES_CY AS NUMBER(38, 2)) AS PRODUCT_SALES_CY
    , CAST(DISCOUNT_AMT_CY AS NUMBER(38, 2)) AS DISCOUNT_AMT_CY
    , MENU_ITEM_CNT_CY
    , CAST(CHECK_SALES_CY AS NUMBER(38, 2)) AS CHECK_SALES_CY
    , CHECK_CNT_CY
    , CAST(IFF(REST_SALES_CY <> 0.00, REST_SALES_CY, (FIRST_VALUE(REST_SALES_CY) OVER (PARTITION BY BUSINESS_DT, BRAND, STORE_NBR ORDER BY REST_SALES_CY DESC))) AS NUMBER(38, 2)) AS REST_SALES_CY
    , IFF(REST_TRANS_CY <> 0.00, REST_TRANS_CY, (FIRST_VALUE(REST_TRANS_CY) OVER (PARTITION BY BUSINESS_DT, BRAND, STORE_NBR ORDER BY REST_TRANS_CY DESC))) AS REST_TRANS_CY

    , FISC_DATE_LY

    , FISC_HOLIDAY_IND_LY
    , FISC_HOLIDAY_NM_LY

    , CAST(FISC_PRODUCT_SALES_LY AS NUMBER(38, 2)) AS FISC_PRODUCT_SALES_LY
    , CAST(FISC_DISCOUNT_AMT_LY AS NUMBER(38, 2)) AS FISC_DISCOUNT_AMT_LY
    , FISC_MENU_ITEM_CNT_LY
    , CAST(FISC_CHECK_SALES_LY AS NUMBER(38, 2)) AS FISC_CHECK_SALES_LY
    , FISC_CHECK_CNT_LY
    , CAST(IFF(FISC_REST_SALES_LY <> 0.00, FISC_REST_SALES_LY, (FIRST_VALUE(FISC_REST_SALES_LY) OVER (PARTITION BY FISC_DATE_LY, BRAND, STORE_NBR ORDER BY FISC_REST_SALES_LY DESC))) AS NUMBER(38, 2)) AS FISC_REST_SALES_LY
    , IFF(FISC_REST_TRANS_LY <> 0.00, FISC_REST_TRANS_LY, (FIRST_VALUE(FISC_REST_TRANS_LY) OVER (PARTITION BY FISC_DATE_LY, BRAND, STORE_NBR ORDER BY FISC_REST_TRANS_LY DESC))) AS FISC_REST_TRANS_LY

    , CAL_COMP_DATE_LY
    , CAL_HOLIDAY_IND_LY
    , CAL_HOLIDAY_NM_LY
    , CAST(CAL_PRODUCT_SALES_LY AS NUMBER(38, 2)) AS CAL_PRODUCT_SALES_LY
    , CAST(CAL_DISCOUNT_AMT_LY AS NUMBER(38, 2)) AS CAL_DISCOUNT_AMT_LY
    , CAL_MENU_ITEM_CNT_LY
    , CAST(CAL_CHECK_SALES_LY AS NUMBER(38, 2)) AS CAL_CHECK_SALES_LY
    , CAL_CHECK_CNT_LY
    , CAST(IFF(CAL_REST_SALES_LY <> 0.00, CAL_REST_SALES_LY, (FIRST_VALUE(CAL_REST_SALES_LY) OVER (PARTITION BY CAL_COMP_DATE_LY, BRAND, STORE_NBR ORDER BY CAL_REST_SALES_LY DESC))) AS NUMBER(38, 2)) AS CAL_REST_SALES_LY
    , IFF(CAL_REST_TRANS_LY <> 0.00, CAL_REST_TRANS_LY, (FIRST_VALUE(CAL_REST_TRANS_LY) OVER (PARTITION BY CAL_COMP_DATE_LY, BRAND, STORE_NBR ORDER BY CAL_REST_TRANS_LY DESC))) AS CAL_REST_TRANS_LY

    , PRODUCT_HIERARCHY_ID
    , LEVEL5_PRODUCT_HIERARCHY_NM
    , LEVEL4_PRODUCT_HIERARCHY_NM
    , LEVEL3_PRODUCT_HIERARCHY_NM
    , LEVEL2_PRODUCT_HIERARCHY_NM
    , LEVEL1_PRODUCT_HIERARCHY_NM
    , OFFER_HIERARCHY_ID
    , LEVEL5_OFFER_HIERARCHY_NM
    , LEVEL4_OFFER_HIERARCHY_NM
    , LEVEL3_OFFER_HIERARCHY_NM
    , LEVEL2_OFFER_HIERARCHY_NM
    , LEVEL1_OFFER_HIERARCHY_NM
    , PRODUCT_MISC1
    , PRODUCT_MISC2
    , PRODUCT_MISC3
    , PRODUCT_MISC4
    , PRODUCT_MISC5
    , PRODUCT_MISC6
    , PRODUCT_MISC7
    , PRODUCT_MISC8
    , PRODUCT_MISC9
    , PRODUCT_MISC10
    , OFFER_MISC1
    , OFFER_MISC2
    , OFFER_MISC3
    , OFFER_MISC4
    , OFFER_MISC5
    , OFFER_MISC6
    , OFFER_MISC7
    , OFFER_MISC8
    , OFFER_MISC9
    , OFFER_MISC10
FROM
    pre_final
      
';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_PRODUCT_OFFER_SALES_COMP("FROMDATE" DATE, "TODATE" DATE)
RETURNS TABLE ("FISC_ORIG_BUSINESS_DT" DATE, "CAL_ORIG_BUSINESS_DT" DATE, "BUSINESS_DT" VARCHAR(16777216), "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_CD" VARCHAR(16777216), "DMA_NM" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "DAY_OF_WEEK" VARCHAR(16777216), "HOLIDAY_IND_CY" VARCHAR(16777216), "HOLIDAY_NM_CY" VARCHAR(16777216), "MENU_ITEM_ID" NUMBER(38,0), "MDM_ITEM_TYP" VARCHAR(16777216), "MENU_ITEM_NM" VARCHAR(16777216), "MDM_PRODUCT_ID" NUMBER(38,0), "MDM_PRODUCT_NM" VARCHAR(16777216), "MDM_OFFER_ID" NUMBER(38,0), "MDM_OFFER_NM" VARCHAR(16777216), "PRODUCT_SALES_CY" NUMBER(38,2), "DISCOUNT_AMT_CY" NUMBER(38,2), "MENU_ITEM_CNT_CY" NUMBER(38,2), "CHECK_SALES_CY" NUMBER(38,2), "CHECK_CNT_CY" NUMBER(38,2), "REST_SALES_CY" NUMBER(38,2), "REST_TRANS_CY" NUMBER(38,2), "PRODUCT_HIERARCHY_ID" NUMBER(38,0), "LEVEL5_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL4_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL3_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL2_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL1_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "OFFER_HIERARCHY_ID" NUMBER(38,0), "LEVEL5_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL4_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL3_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL2_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL1_OFFER_HIERARCHY_NM" VARCHAR(16777216), "PRODUCT_MISC1" VARCHAR(16777216), "PRODUCT_MISC2" VARCHAR(16777216), "PRODUCT_MISC3" VARCHAR(16777216), "PRODUCT_MISC4" VARCHAR(16777216), "PRODUCT_MISC5" VARCHAR(16777216), "PRODUCT_MISC6" VARCHAR(16777216), "PRODUCT_MISC7" VARCHAR(16777216), "PRODUCT_MISC8" VARCHAR(16777216), "PRODUCT_MISC9" VARCHAR(16777216), "PRODUCT_MISC10" VARCHAR(16777216), "OFFER_MISC1" VARCHAR(16777216), "OFFER_MISC2" VARCHAR(16777216), "OFFER_MISC3" VARCHAR(16777216), "OFFER_MISC4" VARCHAR(16777216), "OFFER_MISC5" VARCHAR(16777216), "OFFER_MISC6" VARCHAR(16777216), "OFFER_MISC7" VARCHAR(16777216), "OFFER_MISC8" VARCHAR(16777216), "OFFER_MISC9" VARCHAR(16777216), "OFFER_MISC10" VARCHAR(16777216))
LANGUAGE SQL
AS '


WITH src AS
(
SELECT
    od.ORDER_ID
    , od.ORDER_DT AS BUSINESS_DT
    , orig_bt.CALENDAR_DT AS FISC_ORIG_BUSINESS_DT
    , orig_bt_cal.CALENDAR_DT AS CAL_ORIG_BUSINESS_DT
    , CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
         WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
         WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
         WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
         WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
         WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
         WHEN od.BRAND_ID = ''rto'' THEN ''RT''
         ELSE ''UNKNOWN'' END AS BRAND
    , od.STORE_ID AS STORE_NBR
    , IFNULL(st.DMA_CD, '''') AS DMA_CD
    , IFNULL(st.DMA_NM, '''') AS DMA_NM
    , IFNULL(lv.LEVEL1_NM, '''') AS L1NAME
    , IFNULL(lv.LEVEL2_NM, '''') AS L2NAME
    , IFNULL(lv.LEVEL3_NM, '''') AS L3NAME
    , IFNULL(lv.LEVEL4_NM, '''') AS L4NAME
    , IFNULL(lv.LEVEL5_NM, '''') AS L5NAME
    , IFNULL(st.OWNERSHIP_TYP, '''') AS OWNERSHIP_TYP
    , IFNULL(st.STATE_NM, '''') AS STATE
    , IFNULL(st.COUNTRY_NM, '''') AS COUNTRY
    , dd.FISCAL_YEAR_NBR AS FISC_YEAR_NBR
    , dd.FISCAL_QUARTER_NBR AS FISC_QUARTER_NBR
    , dd.FISCAL_PERIOD_NBR AS FISC_PERIOD_NBR
    , dd.FISCAL_WEEK_NBR AS FISC_WEEK_NBR
    , dd.CALENDAR_DAY_NM AS DAY_OF_WEEK

    , IFNULL(CASE WHEN UPPER(CAST(hlf.HOLIDAY_IND AS VARCHAR(10))) = ''TRUE'' THEN ''Y''
           WHEN UPPER(CAST(hlf.HOLIDAY_IND AS VARCHAR(10))) = ''FALSE'' THEN ''N''
           ELSE NULL END, ''N'') AS HOLIDAY_IND_CY
    , hlf.HOLIDAY_LIST_NM AS HOLIDAY_NM_CY

    , IFNULL(od.MDM_ITEM_ID, 0) AS MENU_ITEM_ID
    , IFNULL(od.MDM_ITEM_TYP, '''') AS MDM_ITEM_TYP
    , IFNULL(od.ITEM_NM, '''') AS MENU_ITEM_NM
    , IFNULL(od.MDM_PRODUCT_ID, 0) AS MDM_PRODUCT_ID
    , IFNULL(od.PRODUCT_NM, '''') AS MDM_PRODUCT_NM
    , IFNULL(od.MDM_OFFER_ID, 0) AS MDM_OFFER_ID
    , IFNULL(od.OFFER_NM, '''') AS MDM_OFFER_NM
  
    , SUM(od.DERIVED_NET_AMT) OVER(PARTITION BY od.BRAND_ID, od.STORE_ID, od.ORDER_DT, orig_bt.CALENDAR_DT, orig_bt_cal.CALENDAR_DT, IFNULL(od.MDM_ITEM_ID, 0)) AS PRODUCT_SALES_CY
    , SUM(od.DERIVED_DISCOUNT_AMT) OVER(PARTITION BY od.BRAND_ID, od.STORE_ID, od.ORDER_DT, orig_bt.CALENDAR_DT, orig_bt_cal.CALENDAR_DT, IFNULL(od.MDM_ITEM_ID, 0)) AS DISCOUNT_AMT_CY
    , SUM(od.DERIVED_GROSS_QTY) OVER(PARTITION BY od.BRAND_ID, od.STORE_ID, od.ORDER_DT, orig_bt.CALENDAR_DT, orig_bt_cal.CALENDAR_DT, IFNULL(od.MDM_ITEM_ID, 0)) AS MENU_ITEM_CNT_CY
    , SUM(od.DERIVED_NET_AMT) OVER(PARTITION BY od.BRAND_ID, od.STORE_ID, od.ORDER_DT, orig_bt.CALENDAR_DT, orig_bt_cal.CALENDAR_DT) AS REST_SALES_CY
    , COUNT(DISTINCT od.ORDER_ID) OVER(PARTITION BY od.BRAND_ID, od.STORE_ID, od.ORDER_DT, orig_bt.CALENDAR_DT, orig_bt_cal.CALENDAR_DT) AS REST_TRANS_CY
  
    , SUM(od.DERIVED_NET_AMT) OVER(PARTITION BY od.ORDER_ID) AS CHECK_SALES_CY
    , ROW_NUMBER() OVER(PARTITION BY od.ORDER_ID, IFNULL(od.MDM_ITEM_ID, 0) ORDER BY od.ORDER_ID, IFNULL(od.MDM_ITEM_ID, 0)) AS Rn_CHECK_SALES_CY

    , IFNULL(od.PRODUCT_HIERARCHY_ID, 0) AS PRODUCT_HIERARCHY_ID
    , IFNULL(od.LEVEL5_PRODUCT_HIERARCHY_NM, '''') AS LEVEL5_PRODUCT_HIERARCHY_NM
    , IFNULL(od.LEVEL4_PRODUCT_HIERARCHY_NM, '''') AS LEVEL4_PRODUCT_HIERARCHY_NM
    , IFNULL(od.LEVEL3_PRODUCT_HIERARCHY_NM, '''') AS LEVEL3_PRODUCT_HIERARCHY_NM
    , IFNULL(od.LEVEL2_PRODUCT_HIERARCHY_NM, '''') AS LEVEL2_PRODUCT_HIERARCHY_NM
    , IFNULL(od.LEVEL1_PRODUCT_HIERARCHY_NM, '''') AS LEVEL1_PRODUCT_HIERARCHY_NM

    , IFNULL(od.OFFER_HIERARCHY_ID, 0) AS OFFER_HIERARCHY_ID
    , IFNULL(od.LEVEL5_OFFER_HIERARCHY_NM, '''') AS LEVEL5_OFFER_HIERARCHY_NM
    , IFNULL(od.LEVEL4_OFFER_HIERARCHY_NM, '''') AS LEVEL4_OFFER_HIERARCHY_NM
    , IFNULL(od.LEVEL3_OFFER_HIERARCHY_NM, '''') AS LEVEL3_OFFER_HIERARCHY_NM
    , IFNULL(od.LEVEL2_OFFER_HIERARCHY_NM, '''') AS LEVEL2_OFFER_HIERARCHY_NM
    , IFNULL(od.LEVEL1_OFFER_HIERARCHY_NM, '''') AS LEVEL1_OFFER_HIERARCHY_NM
    , IFNULL(od.PRODUCT_MISC1, '''') AS PRODUCT_MISC1
    , IFNULL(od.PRODUCT_MISC2, '''') AS PRODUCT_MISC2
    , IFNULL(od.PRODUCT_MISC3, '''') AS PRODUCT_MISC3
    , IFNULL(od.PRODUCT_MISC4, '''') AS PRODUCT_MISC4
    , IFNULL(od.PRODUCT_MISC5, '''') AS PRODUCT_MISC5
    , IFNULL(od.PRODUCT_MISC6, '''') AS PRODUCT_MISC6
    , IFNULL(od.PRODUCT_MISC7, '''') AS PRODUCT_MISC7
    , IFNULL(od.PRODUCT_MISC8, '''') AS PRODUCT_MISC8
    , IFNULL(od.PRODUCT_MISC9, '''') AS PRODUCT_MISC9
    , IFNULL(od.PRODUCT_MISC10, '''') AS PRODUCT_MISC10
  
    , IFNULL(od.OFFER_MISC1, '''') AS OFFER_MISC1
    , IFNULL(od.OFFER_MISC2, '''') AS OFFER_MISC2
    , IFNULL(od.OFFER_MISC3, '''') AS OFFER_MISC3
    , IFNULL(od.OFFER_MISC4, '''') AS OFFER_MISC4
    , IFNULL(od.OFFER_MISC5, '''') AS OFFER_MISC5
    , IFNULL(od.OFFER_MISC6, '''') AS OFFER_MISC6
    , IFNULL(od.OFFER_MISC7, '''') AS OFFER_MISC7
    , IFNULL(od.OFFER_MISC8, '''') AS OFFER_MISC8
    , IFNULL(od.OFFER_MISC9, '''') AS OFFER_MISC9
    , IFNULL(od.OFFER_MISC10, '''') AS OFFER_MISC10

    , od.DERIVED_NET_AMT
    , ROW_NUMBER() OVER(PARTITION BY od.ORDER_DT, od.BRAND_ID, od.STORE_ID, IFNULL(od.MDM_ITEM_ID, 0) ORDER BY od.ORDER_ID, od.ORDER_DT, od.BRAND_ID, od.STORE_ID, IFNULL(od.MDM_ITEM_ID, 0)) AS Rn
FROM
    ORDER_DETAIL_V od
INNER JOIN
    IDH_DEV.SHARED.DATE_DIM_V dd
ON  dd.CALENDAR_DT = od.ORDER_DT
INNER JOIN
    IDH_DEV.SHARED.STORE_SCD_V st
ON  st.STORE_ID = od.STORE_ID
AND st.BRAND_ID = od.BRAND_ID
AND od.ORDER_DT BETWEEN st.EFFECTIVE_BEGIN_DT AND st.EFFECTIVE_END_DT
AND IFNULL(st.CLOSURE_DT, ''9999-12-31'') >= FromDate
AND st.COUNTRY_NM IN (''US'', ''USA'')
LEFT OUTER JOIN 
    IDH_DEV.OPERATION.LOCATION_HIERARCHY_V lv
ON  lv.LOCATION_ID = od.STORE_ID
AND lv.BRAND_ID = od.BRAND_ID
LEFT OUTER JOIN
    IDH_DEV.SHARED.HOLIDAY_LIST_V hlf
ON  TO_DATE(CAST(hlf.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = od.ORDER_DT
LEFT OUTER JOIN
    IDH_DEV.SHARED.HOLIDAY_LIST_V fisc_dat
ON  TO_DATE(CAST(fisc_dat.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = dd.FISCAL_COMPARABLE_DT
LEFT OUTER JOIN
    IDH_DEV.SHARED.HOLIDAY_LIST_V hl_cal
ON  TO_DATE(CAST(hl_cal.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = dd.CALENDAR_COMPARABLE_DT
INNER JOIN
    IDH_QA.SHARED.DATE_DIM_V orig_bt
ON  od.ORDER_DT = orig_bt.FISCAL_COMPARABLE_DT
INNER JOIN
    IDH_QA.SHARED.DATE_DIM_V orig_bt_cal
ON  od.ORDER_DT = orig_bt_cal.CALENDAR_COMPARABLE_DT
WHERE
    IFNULL((CASE WHEN UPPER(CAST(VOIDED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(VOIDED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND IFNULL((CASE WHEN UPPER(CAST(CLEARED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(CLEARED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND IFNULL((CASE WHEN UPPER(CAST(DELETED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(DELETED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND od.ORDER_DT BETWEEN FromDate AND ToDate
)

, src_prel AS
(
SELECT
    src.BUSINESS_DT
    , src.FISC_ORIG_BUSINESS_DT
    , src.CAL_ORIG_BUSINESS_DT
    , src.BRAND
    , src.STORE_NBR
    , MAX(src.DMA_CD) AS DMA_CD
    , MAX(src.DMA_NM) AS DMA_NM
    , MAX(src.L1NAME) AS L1NAME
    , MAX(src.L2NAME) AS L2NAME
    , MAX(src.L3NAME) AS L3NAME
    , MAX(src.L4NAME) AS L4NAME
    , MAX(src.L5NAME) AS L5NAME
    , MAX(src.OWNERSHIP_TYP) AS OWNERSHIP_TYP
    , MAX(src.STATE) AS STATE
    , MAX(src.COUNTRY) AS COUNTRY
    , MAX(src.FISC_YEAR_NBR) AS FISC_YEAR_NBR
    , MAX(src.FISC_QUARTER_NBR) AS FISC_QUARTER_NBR
    , MAX(src.FISC_PERIOD_NBR) AS FISC_PERIOD_NBR
    , MAX(src.FISC_WEEK_NBR) AS FISC_WEEK_NBR
    , MAX(src.DAY_OF_WEEK) AS DAY_OF_WEEK
    , MAX(src.HOLIDAY_IND_CY) AS HOLIDAY_IND_CY
    , MAX(src.HOLIDAY_NM_CY) AS HOLIDAY_NM_CY
    , src.MENU_ITEM_ID
    , MAX(src.MDM_ITEM_TYP) AS MDM_ITEM_TYP
    , MAX(src.MENU_ITEM_NM) AS MENU_ITEM_NM
    , MAX(src.MDM_PRODUCT_ID) AS MDM_PRODUCT_ID
    , MAX(src.MDM_PRODUCT_NM) AS MDM_PRODUCT_NM
    , MAX(src.MDM_OFFER_ID) AS MDM_OFFER_ID
    , MAX(src.MDM_OFFER_NM) AS MDM_OFFER_NM

    , MAX(src.PRODUCT_SALES_CY) AS PRODUCT_SALES_CY
    , MAX(src.DISCOUNT_AMT_CY) AS DISCOUNT_AMT_CY
    , MAX(src.MENU_ITEM_CNT_CY) AS MENU_ITEM_CNT_CY
    , MAX(src.REST_SALES_CY) AS REST_SALES_CY
    , MAX(src.REST_TRANS_CY) AS REST_TRANS_CY
    
  
    , MAX(src.PRODUCT_HIERARCHY_ID) PRODUCT_HIERARCHY_ID
    , MAX(src.LEVEL5_PRODUCT_HIERARCHY_NM) LEVEL5_PRODUCT_HIERARCHY_NM
    , MAX(src.LEVEL4_PRODUCT_HIERARCHY_NM) LEVEL4_PRODUCT_HIERARCHY_NM
    , MAX(src.LEVEL3_PRODUCT_HIERARCHY_NM) LEVEL3_PRODUCT_HIERARCHY_NM
    , MAX(src.LEVEL2_PRODUCT_HIERARCHY_NM) LEVEL2_PRODUCT_HIERARCHY_NM
    , MAX(src.LEVEL1_PRODUCT_HIERARCHY_NM) LEVEL1_PRODUCT_HIERARCHY_NM
  
    , MAX(src.OFFER_HIERARCHY_ID) AS OFFER_HIERARCHY_ID
    , MAX(src.LEVEL5_OFFER_HIERARCHY_NM) AS LEVEL5_OFFER_HIERARCHY_NM
    , MAX(src.LEVEL4_OFFER_HIERARCHY_NM) AS LEVEL4_OFFER_HIERARCHY_NM
    , MAX(src.LEVEL3_OFFER_HIERARCHY_NM) AS LEVEL3_OFFER_HIERARCHY_NM
    , MAX(src.LEVEL2_OFFER_HIERARCHY_NM) AS LEVEL2_OFFER_HIERARCHY_NM
    , MAX(src.LEVEL1_OFFER_HIERARCHY_NM) AS LEVEL1_OFFER_HIERARCHY_NM
  
    , MAX(src.PRODUCT_MISC1) AS PRODUCT_MISC1
    , MAX(src.PRODUCT_MISC2) AS PRODUCT_MISC2
    , MAX(src.PRODUCT_MISC3) AS PRODUCT_MISC3
    , MAX(src.PRODUCT_MISC4) AS PRODUCT_MISC4
    , MAX(src.PRODUCT_MISC5) AS PRODUCT_MISC5
    , MAX(src.PRODUCT_MISC6) AS PRODUCT_MISC6
    , MAX(src.PRODUCT_MISC7) AS PRODUCT_MISC7
    , MAX(src.PRODUCT_MISC8) AS PRODUCT_MISC8
    , MAX(src.PRODUCT_MISC9) AS PRODUCT_MISC9
    , MAX(src.PRODUCT_MISC10) AS PRODUCT_MISC10
  
    , MAX(src.OFFER_MISC1) AS OFFER_MISC1
    , MAX(src.OFFER_MISC2) AS OFFER_MISC2
    , MAX(src.OFFER_MISC3) AS OFFER_MISC3
    , MAX(src.OFFER_MISC4) AS OFFER_MISC4
    , MAX(src.OFFER_MISC5) AS OFFER_MISC5
    , MAX(src.OFFER_MISC6) AS OFFER_MISC6
    , MAX(src.OFFER_MISC7) AS OFFER_MISC7
    , MAX(src.OFFER_MISC8) AS OFFER_MISC8
    , MAX(src.OFFER_MISC9) AS OFFER_MISC9
    , MAX(src.OFFER_MISC10) AS OFFER_MISC10
  
FROM
    src
WHERE
    Rn = 1
AND MDM_ITEM_TYP IN (''Product'', ''Offer'', ''Offer and Product'')
GROUP BY
    src.BUSINESS_DT
    , src.FISC_ORIG_BUSINESS_DT
    , src.CAL_ORIG_BUSINESS_DT
    , src.BRAND
    , src.STORE_NBR
    , src.MENU_ITEM_ID
)

SELECT
    sp.FISC_ORIG_BUSINESS_DT
    , sp.CAL_ORIG_BUSINESS_DT
    , sp.BUSINESS_DT
    , sp.BRAND
    , sp.STORE_NBR
    , sp.DMA_CD
    , sp.DMA_NM
    , sp.L1NAME
    , sp.L2NAME
    , sp.L3NAME
    , sp.L4NAME
    , sp.L5NAME
    , sp.OWNERSHIP_TYP
    , sp.STATE
    , sp.COUNTRY
    , sp.FISC_YEAR_NBR
    , sp.FISC_QUARTER_NBR
    , sp.FISC_PERIOD_NBR
    , sp.FISC_WEEK_NBR
    , sp.DAY_OF_WEEK

    , sp.HOLIDAY_IND_CY
    , sp.HOLIDAY_NM_CY

    , sp.MENU_ITEM_ID
    , sp.MDM_ITEM_TYP
    , sp.MENU_ITEM_NM

    , sp.MDM_PRODUCT_ID
    , sp.MDM_PRODUCT_NM
    , sp.MDM_OFFER_ID
    , sp.MDM_OFFER_NM

    , CAST(sp.PRODUCT_SALES_CY AS NUMBER(38, 2)) AS PRODUCT_SALES_CY
    , CAST(sp.DISCOUNT_AMT_CY AS NUMBER(38, 2)) AS DISCOUNT_AMT_CY
    , sp.MENU_ITEM_CNT_CY
    , CAST((
        SELECT SUM(CHECK_SALES_CY) AS CHECK_SALES_CY
        FROM
            src
        WHERE
            src.MENU_ITEM_ID = sp.MENU_ITEM_ID
        AND src.BRAND = sp.BRAND
        AND src.STORE_NBR = sp.STORE_NBR
        AND src.BUSINESS_DT = sp.BUSINESS_DT 
        AND src.Rn_CHECK_SALES_CY = 1
      ) AS NUMBER(38, 2)) AS CHECK_SALES_CY
    , (
        SELECT
            COUNT(DISTINCT ORDER_ID) AS CHECK_CNT_CY
        FROM
            src
        WHERE
            src.MENU_ITEM_ID = sp.MENU_ITEM_ID
        AND src.BRAND = sp.BRAND
        AND src.STORE_NBR = sp.STORE_NBR
        AND src.BUSINESS_DT = sp.BUSINESS_DT 
      ) AS CHECK_CNT_CY
    , CAST(sp.REST_SALES_CY AS NUMBER(38, 2)) AS REST_SALES_CY
    , sp.REST_TRANS_CY

    , sp.PRODUCT_HIERARCHY_ID
    , sp.LEVEL5_PRODUCT_HIERARCHY_NM
    , sp.LEVEL4_PRODUCT_HIERARCHY_NM
    , sp.LEVEL3_PRODUCT_HIERARCHY_NM
    , sp.LEVEL2_PRODUCT_HIERARCHY_NM
    , sp.LEVEL1_PRODUCT_HIERARCHY_NM
    , sp.OFFER_HIERARCHY_ID
    , sp.LEVEL5_OFFER_HIERARCHY_NM
    , sp.LEVEL4_OFFER_HIERARCHY_NM
    , sp.LEVEL3_OFFER_HIERARCHY_NM
    , sp.LEVEL2_OFFER_HIERARCHY_NM
    , sp.LEVEL1_OFFER_HIERARCHY_NM
    , sp.PRODUCT_MISC1
    , sp.PRODUCT_MISC2
    , sp.PRODUCT_MISC3
    , sp.PRODUCT_MISC4
    , sp.PRODUCT_MISC5
    , sp.PRODUCT_MISC6
    , sp.PRODUCT_MISC7
    , sp.PRODUCT_MISC8
    , sp.PRODUCT_MISC9
    , sp.PRODUCT_MISC10
    , sp.OFFER_MISC1
    , sp.OFFER_MISC2
    , sp.OFFER_MISC3
    , sp.OFFER_MISC4
    , sp.OFFER_MISC5
    , sp.OFFER_MISC6
    , sp.OFFER_MISC7
    , sp.OFFER_MISC8
    , sp.OFFER_MISC9
    , sp.OFFER_MISC10
FROM
    src_prel sp
ORDER BY
    sp.BUSINESS_DT
    , sp.BRAND
    , sp.STORE_NBR
    , sp.MENU_ITEM_ID
';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_PRODUCT_SALES("FROMDATE" DATE, "TODATE" DATE)
RETURNS TABLE ("AGG_LEVEL" VARCHAR(16777216), "BUSINESS_DT" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_CD" VARCHAR(16777216), "DMA_NM" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "DAY_OF_WEEK" VARCHAR(16777216), "HOLIDAY_IND_CY" VARCHAR(16777216), "HOLIDAY_NM_CY" VARCHAR(16777216), "MDM_PRODUCT_ID" NUMBER(38,0), "MDM_PRODUCT_NM" VARCHAR(16777216), "PRODUCT_HIERARCHY_ID" NUMBER(38,0), "LEVEL5_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL4_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL3_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL2_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL1_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "PRODUCT_MISC1" VARCHAR(16777216), "PRODUCT_MISC2" VARCHAR(16777216), "PRODUCT_MISC3" VARCHAR(16777216), "PRODUCT_MISC4" VARCHAR(16777216), "PRODUCT_MISC5" VARCHAR(16777216), "PRODUCT_MISC6" VARCHAR(16777216), "PRODUCT_MISC7" VARCHAR(16777216), "PRODUCT_MISC8" VARCHAR(16777216), "PRODUCT_MISC9" VARCHAR(16777216), "PRODUCT_MISC10" VARCHAR(16777216), "PRODUCT_SALES_CY" FLOAT, "PRODUCT_CNT_CY" NUMBER(38,0), "CHECK_SALES_CY" FLOAT, "CHECK_CNT_CY" NUMBER(38,0), "REST_SALES_CY" FLOAT, "REST_TRANS_CY" NUMBER(38,0), "FISC_DATE_LY" DATE, "FISC_HOLIDAY_IND_LY" VARCHAR(16777216), "FISC_HOLIDAY_NM_LY" VARCHAR(16777216), "FISC_PRODUCT_SALES_LY" FLOAT, "FISC_PRODUCT_CNT_LY" NUMBER(38,0), "FISC_CHECK_SALES_LY" FLOAT, "FISC_CHECK_CNT_LY" NUMBER(38,0), "FISC_REST_SALES_LY" FLOAT, "FISC_REST_TRANS_LY" NUMBER(38,0), "CAL_COMP_DATE_LY" DATE, "CAL_HOLIDAY_IND_LY" VARCHAR(16777216), "CAL_HOLIDAY_NM_LY" VARCHAR(16777216), "CAL_PRODUCT_SALES_LY" FLOAT, "CAL_PRODUCT_CNT_LY" NUMBER(38,0), "CAL_CHECK_SALES_LY" FLOAT, "CAL_CHECK_CNT_LY" NUMBER(38,0), "CAL_REST_SALES_LY" FLOAT, "CAL_REST_TRANS_LY" NUMBER(38,0))
LANGUAGE SQL
AS '


WITH fisc_interval AS
(
SELECT
    MIN(FISCAL_COMPARABLE_DT) AS MIN_FISCAL_COMPARABLE_DT
    , MAX(FISCAL_COMPARABLE_DT) AS MAX_FISCAL_COMPARABLE_DT 
FROM 
    IDH_DEV.SHARED.DATE_DIM_V dd 
WHERE 
    CALENDAR_DT BETWEEN FromDate AND ToDate
)
, cal_interval AS
(
SELECT 
    MIN(CALENDAR_COMPARABLE_DT) AS MIN_CAL_COMPARABLE_DT
    , MAX(CALENDAR_COMPARABLE_DT) AS MAX_CAL_COMPARABLE_DT 
FROM 
    IDH_DEV.SHARED.DATE_DIM_V dd 
WHERE 
    CALENDAR_DT BETWEEN FromDate AND ToDate
)

, CY AS
(
SELECT
    AGG_LEVEL
    , BUSINESS_DT
    , BRAND
    , BRAND_ID
    , STORE_NBR
    , MDM_PRODUCT_ID
  
    , MDM_PRODUCT_NM
    , PRODUCT_HIERARCHY_ID
    , LEVEL5_PRODUCT_HIERARCHY_NM
    , LEVEL4_PRODUCT_HIERARCHY_NM
    , LEVEL3_PRODUCT_HIERARCHY_NM
    , LEVEL2_PRODUCT_HIERARCHY_NM
    , LEVEL1_PRODUCT_HIERARCHY_NM
    , PRODUCT_MISC1
    , PRODUCT_MISC2
    , PRODUCT_MISC3
    , PRODUCT_MISC4
    , PRODUCT_MISC5
    , PRODUCT_MISC6
    , PRODUCT_MISC7
    , PRODUCT_MISC8
    , PRODUCT_MISC9
    , PRODUCT_MISC10
    
    , PRODUCT_SALES_CY
    , PRODUCT_CNT_CY
    , CHECK_SALES_CY
    , CHECK_CNT_CY
    , REST_SALES_CY
    , REST_TRANS_CY
    
    , FISC_DATE_LY
    , 0.00 AS FISC_PRODUCT_SALES_CY
    , 0 AS FISC_PRODUCT_CNT_CY
    , 0.00 AS FISC_CHECK_SALES_CY
    , 0 AS FISC_CHECK_CNT_CY
    , 0.00 AS FISC_REST_SALES_CY
    , 0 AS FISC_REST_TRANS_CY
    
    , CAL_COMP_DATE_LY
    , 0.00 AS CAL_PRODUCT_SALES_CY
    , 0 AS CAL_PRODUCT_CNT_CY
    , 0.00 AS CAL_CHECK_SALES_CY
    , 0 AS CAL_CHECK_CNT_CY
    , 0.00 AS CAL_REST_SALES_CY
    , 0 AS CAL_REST_TRANS_CY
FROM
    TABLE(INSPIRE_DAILY_PRODUCT_SALES_MAIN(FromDate, ToDate))
)

, FSC AS
(
SELECT
    fsc.AGG_LEVEL
    , dd_f.CALENDAR_DT AS BUSINESS_DT
    , fsc.BRAND
    , fsc.BRAND_ID
    , fsc.STORE_NBR
    , fsc.MDM_PRODUCT_ID
  
    , fsc.MDM_PRODUCT_NM
    , fsc.PRODUCT_HIERARCHY_ID
    , fsc.LEVEL5_PRODUCT_HIERARCHY_NM
    , fsc.LEVEL4_PRODUCT_HIERARCHY_NM
    , fsc.LEVEL3_PRODUCT_HIERARCHY_NM
    , fsc.LEVEL2_PRODUCT_HIERARCHY_NM
    , fsc.LEVEL1_PRODUCT_HIERARCHY_NM
    , fsc.PRODUCT_MISC1
    , fsc.PRODUCT_MISC2
    , fsc.PRODUCT_MISC3
    , fsc.PRODUCT_MISC4
    , fsc.PRODUCT_MISC5
    , fsc.PRODUCT_MISC6
    , fsc.PRODUCT_MISC7
    , fsc.PRODUCT_MISC8
    , fsc.PRODUCT_MISC9
    , fsc.PRODUCT_MISC10
    
    , 0.00 AS PRODUCT_SALES_CY
    , 0 AS PRODUCT_CNT_CY
    , 0.00 AS CHECK_SALES_CY
    , 0 AS CHECK_CNT_CY
    , 0.00 AS REST_SALES_CY
    , 0 AS REST_TRANS_CY
    
    , fsc.BUSINESS_DT AS FISC_DATE_LY
    , fsc.PRODUCT_SALES_CY AS FISC_PRODUCT_SALES_CY
    , fsc.PRODUCT_CNT_CY AS FISC_PRODUCT_CNT_CY
    , fsc.CHECK_SALES_CY AS FISC_CHECK_SALES_CY
    , fsc.CHECK_CNT_CY AS FISC_CHECK_CNT_CY
    , fsc.REST_SALES_CY AS FISC_REST_SALES_CY
    , fsc.REST_TRANS_CY AS FISC_REST_TRANS_CY
    
    , dd_f.CALENDAR_COMPARABLE_DT AS CAL_COMP_DATE_LY
    , 0.00 AS CAL_PRODUCT_SALES_CY
    , 0 AS CAL_PRODUCT_CNT_CY
    , 0.00 AS CAL_CHECK_SALES_CY
    , 0 AS CAL_CHECK_CNT_CY
    , 0.00 AS CAL_REST_SALES_CY
    , 0 AS CAL_REST_TRANS_CY
FROM
    TABLE(INSPIRE_DAILY_PRODUCT_SALES_MAIN((SELECT MIN(MIN_FISCAL_COMPARABLE_DT) FROM fisc_interval), (SELECT MAX(MAX_FISCAL_COMPARABLE_DT) FROM fisc_interval))) fsc
LEFT OUTER JOIN
    IDH_DEV.SHARED.DATE_DIM_V dd_f
ON  dd_f.FISCAL_COMPARABLE_DT = fsc.BUSINESS_DT
)

, CAL AS
(
SELECT
    cal.AGG_LEVEL
    , dd_cal.CALENDAR_DT AS BUSINESS_DT
    , cal.BRAND
    , cal.BRAND_ID
    , cal.STORE_NBR
    , cal.MDM_PRODUCT_ID
  
    , cal.MDM_PRODUCT_NM
    , cal.PRODUCT_HIERARCHY_ID
    , cal.LEVEL5_PRODUCT_HIERARCHY_NM
    , cal.LEVEL4_PRODUCT_HIERARCHY_NM
    , cal.LEVEL3_PRODUCT_HIERARCHY_NM
    , cal.LEVEL2_PRODUCT_HIERARCHY_NM
    , cal.LEVEL1_PRODUCT_HIERARCHY_NM
    , cal.PRODUCT_MISC1
    , cal.PRODUCT_MISC2
    , cal.PRODUCT_MISC3
    , cal.PRODUCT_MISC4
    , cal.PRODUCT_MISC5
    , cal.PRODUCT_MISC6
    , cal.PRODUCT_MISC7
    , cal.PRODUCT_MISC8
    , cal.PRODUCT_MISC9
    , cal.PRODUCT_MISC10

    , 0.00 AS PRODUCT_SALES_CY
    , 0 AS PRODUCT_CNT_CY
    , 0.00 AS CHECK_SALES_CY
    , 0 AS CHECK_CNT_CY
    , 0.00 AS REST_SALES_CY
    , 0 AS REST_TRANS_CY

    , dd_cal.FISCAL_COMPARABLE_DT AS FISC_DATE_LY
    , 0.00 AS FISC_PRODUCT_SALES_CY
    , 0 AS FISC_PRODUCT_CNT_CY
    , 0.00 AS FISC_CHECK_SALES_CY
    , 0 AS FISC_CHECK_CNT_CY
    , 0.00 AS FISC_REST_SALES_CY
    , 0 AS FISC_REST_TRANS_CY

    , cal.BUSINESS_DT AS CAL_COMP_DATE_LY
    , cal.PRODUCT_SALES_CY AS CAL_PRODUCT_SALES_CY
    , cal.PRODUCT_CNT_CY AS CAL_PRODUCT_CNT_CY
    , cal.CHECK_SALES_CY AS CAL_CHECK_SALES_CY
    , cal.CHECK_CNT_CY AS CAL_CHECK_CNT_CY
    , cal.REST_SALES_CY AS CAL_REST_SALES_CY
    , cal.REST_TRANS_CY AS CAL_REST_TRANS_CY
FROM
    TABLE(INSPIRE_DAILY_PRODUCT_SALES_MAIN((SELECT MIN(MIN_CAL_COMPARABLE_DT) FROM cal_interval), (SELECT MAX(MAX_CAL_COMPARABLE_DT) FROM cal_interval))) cal
LEFT OUTER JOIN
    IDH_DEV.SHARED.DATE_DIM_V dd_cal
ON  dd_cal.CALENDAR_COMPARABLE_DT = cal.BUSINESS_DT
)

, agg AS
(
SELECT
    AGG_LEVEL
    , BUSINESS_DT
    , BRAND
    , BRAND_ID
    , STORE_NBR
    , MDM_PRODUCT_ID
  
    , MDM_PRODUCT_NM
    , PRODUCT_HIERARCHY_ID
    , LEVEL5_PRODUCT_HIERARCHY_NM
    , LEVEL4_PRODUCT_HIERARCHY_NM
    , LEVEL3_PRODUCT_HIERARCHY_NM
    , LEVEL2_PRODUCT_HIERARCHY_NM
    , LEVEL1_PRODUCT_HIERARCHY_NM
    , PRODUCT_MISC1
    , PRODUCT_MISC2
    , PRODUCT_MISC3
    , PRODUCT_MISC4
    , PRODUCT_MISC5
    , PRODUCT_MISC6
    , PRODUCT_MISC7
    , PRODUCT_MISC8
    , PRODUCT_MISC9
    , PRODUCT_MISC10
    
    , PRODUCT_SALES_CY
    , PRODUCT_CNT_CY
    , CHECK_SALES_CY
    , CHECK_CNT_CY
    , REST_SALES_CY
    , REST_TRANS_CY
    
    , FISC_DATE_LY
    , FISC_PRODUCT_SALES_CY
    , FISC_PRODUCT_CNT_CY
    , FISC_CHECK_SALES_CY
    , FISC_CHECK_CNT_CY
    , FISC_REST_SALES_CY
    , FISC_REST_TRANS_CY
    
    , CAL_COMP_DATE_LY
    , CAL_PRODUCT_SALES_CY
    , CAL_PRODUCT_CNT_CY
    , CAL_CHECK_SALES_CY
    , CAL_CHECK_CNT_CY
    , CAL_REST_SALES_CY
    , CAL_REST_TRANS_CY
FROM
    CY

UNION ALL

SELECT
    AGG_LEVEL
    , BUSINESS_DT
    , BRAND
    , BRAND_ID
    , STORE_NBR
    , MDM_PRODUCT_ID
  
    , MDM_PRODUCT_NM
    , PRODUCT_HIERARCHY_ID
    , LEVEL5_PRODUCT_HIERARCHY_NM
    , LEVEL4_PRODUCT_HIERARCHY_NM
    , LEVEL3_PRODUCT_HIERARCHY_NM
    , LEVEL2_PRODUCT_HIERARCHY_NM
    , LEVEL1_PRODUCT_HIERARCHY_NM
    , PRODUCT_MISC1
    , PRODUCT_MISC2
    , PRODUCT_MISC3
    , PRODUCT_MISC4
    , PRODUCT_MISC5
    , PRODUCT_MISC6
    , PRODUCT_MISC7
    , PRODUCT_MISC8
    , PRODUCT_MISC9
    , PRODUCT_MISC10

    , PRODUCT_SALES_CY
    , PRODUCT_CNT_CY
    , CHECK_SALES_CY
    , CHECK_CNT_CY
    , REST_SALES_CY
    , REST_TRANS_CY
    
    , FISC_DATE_LY
    , FISC_PRODUCT_SALES_CY
    , FISC_PRODUCT_CNT_CY
    , FISC_CHECK_SALES_CY
    , FISC_CHECK_CNT_CY
    , FISC_REST_SALES_CY
    , FISC_REST_TRANS_CY
    
    , CAL_COMP_DATE_LY
    , CAL_PRODUCT_SALES_CY
    , CAL_PRODUCT_CNT_CY
    , CAL_CHECK_SALES_CY
    , CAL_CHECK_CNT_CY
    , CAL_REST_SALES_CY
    , CAL_REST_TRANS_CY
FROM
    FSC

UNION ALL

SELECT
    AGG_LEVEL
    , BUSINESS_DT
    , BRAND
    , BRAND_ID
    , STORE_NBR
    , MDM_PRODUCT_ID
  
    , MDM_PRODUCT_NM
    , PRODUCT_HIERARCHY_ID
    , LEVEL5_PRODUCT_HIERARCHY_NM
    , LEVEL4_PRODUCT_HIERARCHY_NM
    , LEVEL3_PRODUCT_HIERARCHY_NM
    , LEVEL2_PRODUCT_HIERARCHY_NM
    , LEVEL1_PRODUCT_HIERARCHY_NM
    , PRODUCT_MISC1
    , PRODUCT_MISC2
    , PRODUCT_MISC3
    , PRODUCT_MISC4
    , PRODUCT_MISC5
    , PRODUCT_MISC6
    , PRODUCT_MISC7
    , PRODUCT_MISC8
    , PRODUCT_MISC9
    , PRODUCT_MISC10
    
    , PRODUCT_SALES_CY
    , PRODUCT_CNT_CY
    , CHECK_SALES_CY
    , CHECK_CNT_CY
    , REST_SALES_CY
    , REST_TRANS_CY
    
    , FISC_DATE_LY
    , FISC_PRODUCT_SALES_CY
    , FISC_PRODUCT_CNT_CY
    , FISC_CHECK_SALES_CY
    , FISC_CHECK_CNT_CY
    , FISC_REST_SALES_CY
    , FISC_REST_TRANS_CY
    
    , CAL_COMP_DATE_LY
    , CAL_PRODUCT_SALES_CY
    , CAL_PRODUCT_CNT_CY
    , CAL_CHECK_SALES_CY
    , CAL_CHECK_CNT_CY
    , CAL_REST_SALES_CY
    , CAL_REST_TRANS_CY
FROM
    CAL
)

, pre_final AS
(
SELECT
    AGG_LEVEL
    , BUSINESS_DT
    , BRAND
    , BRAND_ID
    , STORE_NBR
    , MDM_PRODUCT_ID

    , MAX(MDM_PRODUCT_NM) AS MDM_PRODUCT_NM
    , MAX(PRODUCT_HIERARCHY_ID) AS PRODUCT_HIERARCHY_ID
    , MAX(LEVEL5_PRODUCT_HIERARCHY_NM) AS LEVEL5_PRODUCT_HIERARCHY_NM
    , MAX(LEVEL4_PRODUCT_HIERARCHY_NM) AS LEVEL4_PRODUCT_HIERARCHY_NM
    , MAX(LEVEL3_PRODUCT_HIERARCHY_NM) AS LEVEL3_PRODUCT_HIERARCHY_NM
    , MAX(LEVEL2_PRODUCT_HIERARCHY_NM) AS LEVEL2_PRODUCT_HIERARCHY_NM
    , MAX(LEVEL1_PRODUCT_HIERARCHY_NM) AS LEVEL1_PRODUCT_HIERARCHY_NM
    , MAX(PRODUCT_MISC1) AS PRODUCT_MISC1
    , MAX(PRODUCT_MISC2) AS PRODUCT_MISC2
    , MAX(PRODUCT_MISC3) AS PRODUCT_MISC3
    , MAX(PRODUCT_MISC4) AS PRODUCT_MISC4
    , MAX(PRODUCT_MISC5) AS PRODUCT_MISC5
    , MAX(PRODUCT_MISC6) AS PRODUCT_MISC6
    , MAX(PRODUCT_MISC7) AS PRODUCT_MISC7
    , MAX(PRODUCT_MISC8) AS PRODUCT_MISC8
    , MAX(PRODUCT_MISC9) AS PRODUCT_MISC9
    , MAX(PRODUCT_MISC10) AS PRODUCT_MISC10

    , SUM(PRODUCT_SALES_CY) AS PRODUCT_SALES_CY
    , SUM(PRODUCT_CNT_CY) AS PRODUCT_CNT_CY
    , SUM(CHECK_SALES_CY) AS CHECK_SALES_CY
    , SUM(CHECK_CNT_CY) AS CHECK_CNT_CY
    , SUM(REST_SALES_CY) AS REST_SALES_CY
    , SUM(REST_TRANS_CY) AS REST_TRANS_CY
    
    , FISC_DATE_LY
    , SUM(FISC_PRODUCT_SALES_CY) AS FISC_PRODUCT_SALES_CY
    , SUM(FISC_PRODUCT_CNT_CY) AS FISC_PRODUCT_CNT_CY
    , SUM(FISC_CHECK_SALES_CY) AS FISC_CHECK_SALES_CY
    , SUM(FISC_CHECK_CNT_CY) AS FISC_CHECK_CNT_CY
    , SUM(FISC_REST_SALES_CY) AS FISC_REST_SALES_CY
    , SUM(FISC_REST_TRANS_CY) AS FISC_REST_TRANS_CY
    
    , CAL_COMP_DATE_LY
    , SUM(CAL_PRODUCT_SALES_CY) AS CAL_PRODUCT_SALES_CY
    , SUM(CAL_PRODUCT_CNT_CY) AS CAL_PRODUCT_CNT_CY
    , SUM(CAL_CHECK_SALES_CY) AS CAL_CHECK_SALES_CY
    , SUM(CAL_CHECK_CNT_CY) AS CAL_CHECK_CNT_CY
    , SUM(CAL_REST_SALES_CY) AS CAL_REST_SALES_CY
    , SUM(CAL_REST_TRANS_CY) AS CAL_REST_TRANS_CY
FROM
    agg
GROUP BY
    AGG_LEVEL
    , BUSINESS_DT
    , BRAND
    , BRAND_ID
    , STORE_NBR
    , MDM_PRODUCT_ID
  
    , FISC_DATE_LY
    , CAL_COMP_DATE_LY
)

SELECT
    pf.AGG_LEVEL
    , pf.BUSINESS_DT
    , pf.BRAND
    , pf.STORE_NBR

    , st.DMA_CD
    , st.DMA_CD

    , lv.LEVEL1_NM AS L1NAME
    , lv.LEVEL2_NM AS L2NAME
    , lv.LEVEL3_NM AS L3NAME
    , lv.LEVEL4_NM AS L4NAME
    , lv.LEVEL5_NM AS L5NAME

    , st.OWNERSHIP_TYP AS OWNERSHIP_TYP
    , st.STATE_NM AS STATE
    , st.COUNTRY_NM AS COUNTRY

    , dd.FISCAL_YEAR_NBR AS FISC_YEAR_NBR
    , dd.FISCAL_QUARTER_NBR AS FISC_QUARTER_NBR
    , dd.FISCAL_PERIOD_NBR AS FISC_PERIOD_NBR
    , dd.FISCAL_WEEK_NBR AS FISC_WEEK_NBR
    , dd.CALENDAR_DAY_NM AS DAY_OF_WEEK

    , CASE WHEN UPPER(CAST(hlf.HOLIDAY_IND AS VARCHAR(10))) = ''TRUE'' THEN ''Y''
           WHEN UPPER(CAST(hlf.HOLIDAY_IND AS VARCHAR(10))) = ''FALSE'' THEN ''N''
           ELSE NULL END AS HOLIDAY_IND_CY
    , hlf.HOLIDAY_LIST_NM AS HOLIDAY_NM_CY
    
    , NULLIF(pf.MDM_PRODUCT_ID, 0) AS MDM_PRODUCT_ID
    , pf.MDM_PRODUCT_NM
    , pf.PRODUCT_HIERARCHY_ID
    , pf.LEVEL5_PRODUCT_HIERARCHY_NM
    , pf.LEVEL4_PRODUCT_HIERARCHY_NM
    , pf.LEVEL3_PRODUCT_HIERARCHY_NM
    , pf.LEVEL2_PRODUCT_HIERARCHY_NM
    , pf.LEVEL1_PRODUCT_HIERARCHY_NM
    , pf.PRODUCT_MISC1
    , pf.PRODUCT_MISC2
    , pf.PRODUCT_MISC3
    , pf.PRODUCT_MISC4
    , pf.PRODUCT_MISC5
    , pf.PRODUCT_MISC6
    , pf.PRODUCT_MISC7
    , pf.PRODUCT_MISC8
    , pf.PRODUCT_MISC9
    , pf.PRODUCT_MISC10

    , pf.PRODUCT_SALES_CY
    , pf.PRODUCT_CNT_CY
    , pf.CHECK_SALES_CY
    , pf.CHECK_CNT_CY

    , IFF(pf.REST_SALES_CY <> 0.00, pf.REST_SALES_CY, (FIRST_VALUE(pf.REST_SALES_CY) OVER (PARTITION BY pf.BUSINESS_DT, pf.BRAND, pf.STORE_NBR ORDER BY pf.REST_SALES_CY DESC))) AS REST_SALES_CY
    , IFF(pf.REST_TRANS_CY <> 0.00, pf.REST_TRANS_CY, (FIRST_VALUE(pf.REST_TRANS_CY) OVER (PARTITION BY pf.BUSINESS_DT, pf.BRAND, pf.STORE_NBR ORDER BY pf.REST_TRANS_CY DESC))) AS REST_TRANS_CY
    , pf.FISC_DATE_LY
    , CASE WHEN UPPER(CAST(hlf_fisc.HOLIDAY_IND AS VARCHAR(10))) = ''TRUE'' THEN ''Y''
           WHEN UPPER(CAST(hlf_fisc.HOLIDAY_IND AS VARCHAR(10))) = ''FALSE'' THEN ''N''
           ELSE NULL END AS FISC_HOLIDAY_IND_LY
    , hlf_fisc.HOLIDAY_LIST_NM AS FISC_HOLIDAY_NM_LY
    , pf.FISC_PRODUCT_SALES_CY
    , pf.FISC_PRODUCT_CNT_CY
    , pf.FISC_CHECK_SALES_CY
    , pf.FISC_CHECK_CNT_CY

    , IFF(pf.FISC_REST_SALES_CY <> 0.00, pf.FISC_REST_SALES_CY, (FIRST_VALUE(pf.FISC_REST_SALES_CY) OVER (PARTITION BY pf.BUSINESS_DT, pf.BRAND, pf.STORE_NBR ORDER BY pf.FISC_REST_SALES_CY DESC))) AS FISC_REST_SALES_CY
    , IFF(pf.FISC_REST_TRANS_CY <> 0.00, pf.FISC_REST_TRANS_CY, (FIRST_VALUE(pf.FISC_REST_TRANS_CY) OVER (PARTITION BY pf.BUSINESS_DT, pf.BRAND, pf.STORE_NBR ORDER BY pf.FISC_REST_TRANS_CY DESC))) AS FISC_REST_TRANS_CY
    , pf.CAL_COMP_DATE_LY
    , CASE WHEN UPPER(CAST(hlf_cal.HOLIDAY_IND AS VARCHAR(10))) = ''TRUE'' THEN ''Y''
           WHEN UPPER(CAST(hlf_cal.HOLIDAY_IND AS VARCHAR(10))) = ''FALSE'' THEN ''N''
           ELSE NULL END AS FISC_HOLIDAY_IND_LY
    , hlf_cal.HOLIDAY_LIST_NM AS FISC_HOLIDAY_NM_LY
    , pf.CAL_PRODUCT_SALES_CY
    , pf.CAL_PRODUCT_CNT_CY
    , pf.CAL_CHECK_SALES_CY
    , pf.CAL_CHECK_CNT_CY

    , IFF(pf.CAL_REST_SALES_CY <> 0.00, pf.CAL_REST_SALES_CY, (FIRST_VALUE(pf.CAL_REST_SALES_CY) OVER (PARTITION BY pf.BUSINESS_DT, pf.BRAND, pf.STORE_NBR ORDER BY pf.CAL_REST_SALES_CY DESC))) AS CAL_REST_SALES_CY
    , IFF(pf.CAL_REST_TRANS_CY <> 0.00, pf.CAL_REST_TRANS_CY, (FIRST_VALUE(pf.CAL_REST_TRANS_CY) OVER (PARTITION BY pf.BUSINESS_DT, pf.BRAND, pf.STORE_NBR ORDER BY pf.CAL_REST_TRANS_CY DESC))) AS CAL_REST_TRANS_CY
FROM
    pre_final pf
INNER JOIN
    IDH_DEV.SHARED.DATE_DIM_V dd
ON  dd.CALENDAR_DT = pf.BUSINESS_DT
LEFT OUTER JOIN
    IDH_DEV.SHARED.HOLIDAY_LIST_V hlf
ON  TO_DATE(CAST(hlf.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = pf.BUSINESS_DT
LEFT OUTER JOIN
    IDH_DEV.SHARED.HOLIDAY_LIST_V hlf_fisc
ON  TO_DATE(CAST(hlf_fisc.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = pf.FISC_DATE_LY
LEFT OUTER JOIN
    IDH_DEV.SHARED.HOLIDAY_LIST_V hlf_cal
ON  TO_DATE(CAST(hlf_cal.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = pf.CAL_COMP_DATE_LY
LEFT OUTER JOIN
    IDH_DEV.OPERATION.LOCATION_HIERARCHY_V lv
ON  lv.LOCATION_ID = pf.STORE_NBR
AND lv.BRAND_ID = pf.BRAND_ID
INNER JOIN
    IDH_DEV.SHARED.STORE_SCD_V st
ON  st.STORE_ID = pf.STORE_NBR
AND st.BRAND_ID = pf.BRAND_ID
AND pf.BUSINESS_DT BETWEEN st.EFFECTIVE_BEGIN_DT AND st.EFFECTIVE_END_DT
AND IFNULL(st.CLOSURE_DT, ''9999-12-31'') >= (SELECT DATE_TRUNC(''YEAR'', MIN(DT)) AS Ref_Date FROM (SELECT MIN(MIN_FISCAL_COMPARABLE_DT) AS DT FROM fisc_interval UNION SELECT MIN(MIN_CAL_COMPARABLE_DT) AS DT FROM cal_interval))
AND st.COUNTRY_NM IN (''US'', ''USA'')
WHERE
    pf.BUSINESS_DT BETWEEN FromDate AND ToDate

';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_PRODUCT_SALES_CAL("FROMDATE" DATE, "TODATE" DATE)
RETURNS TABLE ("BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "MDM_PRODUCT_ID" NUMBER(38,0), "MDM_PRODUCT_NM" VARCHAR(16777216), "CAL_DATE_LY" DATE, "CAL_PRODUCT_SALES_LY" NUMBER(38,2), "CAL_PRODUCT_CNT_LY" NUMBER(38,0), "CAL_CHECK_SALES_LY" NUMBER(38,2), "CAL_CHECK_CNT_LY" NUMBER(38,0), "CAL_REST_SALES_LY" NUMBER(38,2), "CAL_REST_TRANS_LY" NUMBER(38,0), "PRODUCT_HIERARCHY_ID" NUMBER(38,0), "LEVEL5_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL4_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL3_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL2_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL1_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "DMA_CD" VARCHAR(16777216), "DMA_NM" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "PRODUCT_MISC1" VARCHAR(16777216), "PRODUCT_MISC2" VARCHAR(16777216), "PRODUCT_MISC3" VARCHAR(16777216), "PRODUCT_MISC4" VARCHAR(16777216), "PRODUCT_MISC5" VARCHAR(16777216), "PRODUCT_MISC6" VARCHAR(16777216), "PRODUCT_MISC7" VARCHAR(16777216), "PRODUCT_MISC8" VARCHAR(16777216), "PRODUCT_MISC9" VARCHAR(16777216), "PRODUCT_MISC10" VARCHAR(16777216))
LANGUAGE SQL
AS '

WITH date_interval AS
(
SELECT 
    MIN(CALENDAR_COMPARABLE_DT) AS MIN_CAL_COMPARABLE_DT
    , MAX(CALENDAR_COMPARABLE_DT) AS MAX_CAL_COMPARABLE_DT 
FROM 
    IDH_DEV.SHARED.DATE_DIM_V dd 
WHERE 
    CALENDAR_DT BETWEEN FromDate AND ToDate
)
, src_cal_period AS
(
    SELECT
        od.ORDER_ID
      , od.ORDERLINE_ID
      , od.ORDER_DT AS BUSINESS_DT
      , od.STORE_ID AS STORE_NBR
      , IFNULL(od.MDM_PRODUCT_ID, 0) AS MDM_PRODUCT_ID
      , IFNULL(od.PRODUCT_NM, '''') AS MDM_PRODUCT_NM
      , IFNULL(DERIVED_GROSS_QTY, 0) AS DERIVED_GROSS_QTY
      , IFNULL(DERIVED_NET_AMT, 0) AS DERIVED_NET_AMT
      , od.BRAND_ID
      , CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
           WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
           WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
           WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
           WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
           WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
           WHEN od.BRAND_ID = ''rto'' THEN ''RT''
           ELSE ''UNKNOWN'' END AS BRAND
      , od.LOAD_DT
      , od.LAST_UPDATED_DTTM
      , od.ORDER_DT AS CAL_DATE_LY
  
      , IFNULL(od.PRODUCT_HIERARCHY_ID, 0) AS PRODUCT_HIERARCHY_ID
      , IFNULL(od.LEVEL5_PRODUCT_HIERARCHY_NM, '''') AS LEVEL5_PRODUCT_HIERARCHY_NM
      , IFNULL(od.LEVEL4_PRODUCT_HIERARCHY_NM, '''') AS LEVEL4_PRODUCT_HIERARCHY_NM
      , IFNULL(od.LEVEL3_PRODUCT_HIERARCHY_NM, '''') AS LEVEL3_PRODUCT_HIERARCHY_NM
      , IFNULL(od.LEVEL2_PRODUCT_HIERARCHY_NM, '''') AS LEVEL2_PRODUCT_HIERARCHY_NM
      , IFNULL(od.LEVEL1_PRODUCT_HIERARCHY_NM, '''') AS LEVEL1_PRODUCT_HIERARCHY_NM
      , st.DMA_CD
      , st.DMA_NM
      , IFNULL(lv.LEVEL1_NM, '''') AS L1NAME
      , IFNULL(lv.LEVEL2_NM, '''') AS L2NAME
      , IFNULL(lv.LEVEL3_NM, '''') AS L3NAME
      , IFNULL(lv.LEVEL4_NM, '''') AS L4NAME
      , IFNULL(lv.LEVEL5_NM, '''') AS L5NAME
      , st.OWNERSHIP_TYP AS OWNERSHIP_TYP
      , st.STATE_NM AS STATE
      , st.COUNTRY_NM AS COUNTRY
      , IFNULL(od.PRODUCT_MISC1, '''') AS PRODUCT_MISC1
      , IFNULL(od.PRODUCT_MISC2, '''') AS PRODUCT_MISC2
      , IFNULL(od.PRODUCT_MISC3, '''') AS PRODUCT_MISC3
      , IFNULL(od.PRODUCT_MISC4, '''') AS PRODUCT_MISC4
      , IFNULL(od.PRODUCT_MISC5, '''') AS PRODUCT_MISC5
      , IFNULL(od.PRODUCT_MISC6, '''') AS PRODUCT_MISC6
      , IFNULL(od.PRODUCT_MISC7, '''') AS PRODUCT_MISC7
      , IFNULL(od.PRODUCT_MISC8, '''') AS PRODUCT_MISC8
      , IFNULL(od.PRODUCT_MISC9, '''') AS PRODUCT_MISC9
      , IFNULL(od.PRODUCT_MISC10, '''') AS PRODUCT_MISC10
    FROM
        ORDER_DETAIL_V od
    LEFT OUTER JOIN
        IDH_DEV.SHARED.STORE_SCD_V st
    ON  st.STORE_ID = od.STORE_ID
    AND st.BRAND_ID = od.BRAND_ID
    AND st.CURRENT_IND = 1
    AND IFNULL(st.CLOSURE_DT, ''9999-12-31'') >= IFNULL((SELECT MIN_CAL_COMPARABLE_DT FROM date_interval), ''9999-12-31'')
    LEFT OUTER JOIN 
        IDH_DEV.OPERATION.LOCATION_HIERARCHY_V lv
    ON  lv.LOCATION_ID = od.STORE_ID
    AND lv.BRAND_ID = od.BRAND_ID
    WHERE
        IFNULL((CASE WHEN UPPER(CAST(VOIDED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(VOIDED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND IFNULL((CASE WHEN UPPER(CAST(CLEARED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(CLEARED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND IFNULL((CASE WHEN UPPER(CAST(DELETED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(DELETED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND od.ORDER_DT BETWEEN (SELECT MIN_CAL_COMPARABLE_DT FROM date_interval) AND (SELECT MAX_CAL_COMPARABLE_DT FROM date_interval)
)
, tot AS
(
SELECT
    x.ORDER_ID
    , x.BUSINESS_DT AS CAL_DATE_LY
    , x.STORE_NBR
    , x.BRAND
    , x.MDM_PRODUCT_ID
    , ROW_NUMBER() OVER (PARTITION BY ORDER_ID ORDER BY BUSINESS_DT, STORE_NBR, BRAND, MDM_PRODUCT_ID) AS Rn
FROM
    (
        SELECT DISTINCT 
            ORDER_ID, BUSINESS_DT, STORE_NBR, BRAND, MDM_PRODUCT_ID 
        FROM 
            src_cal_period s1 
    ) x
    QUALIFY 
        Rn = 1
)

, src_cal_period_dist_chk AS
(
    SELECT
        ORDER_ID
      , BRAND
      , STORE_NBR
      , MDM_PRODUCT_ID
      , MDM_PRODUCT_NM
      , CAL_DATE_LY
      , DERIVED_GROSS_QTY
      , DERIVED_NET_AMT AS DERIVED_NET_AMT
      , SUM(DERIVED_NET_AMT) OVER(PARTITION BY ORDER_ID) AS CAL_CHECK_SALES_LY
      , COUNT(DISTINCT ORDER_ID) OVER(PARTITION BY CAL_DATE_LY, BRAND, STORE_NBR, MDM_PRODUCT_ID) AS CAL_CHECK_CNT_LY
      , COUNT(DISTINCT ORDER_ID) OVER(PARTITION BY CAL_DATE_LY, BRAND, STORE_NBR) AS CAL_REST_TRANS_LY
      , ROW_NUMBER() OVER(PARTITION BY ORDER_ID, CAL_DATE_LY, BRAND, STORE_NBR, MDM_PRODUCT_ID ORDER BY ORDER_ID) AS Rn
  
      , PRODUCT_HIERARCHY_ID
      , LEVEL5_PRODUCT_HIERARCHY_NM
      , LEVEL4_PRODUCT_HIERARCHY_NM
      , LEVEL3_PRODUCT_HIERARCHY_NM
      , LEVEL2_PRODUCT_HIERARCHY_NM
      , LEVEL1_PRODUCT_HIERARCHY_NM
      , DMA_CD
      , DMA_NM
      , L1NAME
      , L2NAME
      , L3NAME
      , L4NAME
      , L5NAME
      , OWNERSHIP_TYP
      , STATE
      , COUNTRY
      , PRODUCT_MISC1
      , PRODUCT_MISC2
      , PRODUCT_MISC3
      , PRODUCT_MISC4
      , PRODUCT_MISC5
      , PRODUCT_MISC6
      , PRODUCT_MISC7
      , PRODUCT_MISC8
      , PRODUCT_MISC9
      , PRODUCT_MISC10
    FROM
        src_cal_period
)

SELECT
    s.BRAND
    , s.STORE_NBR
    , s.MDM_PRODUCT_ID
    , s.MDM_PRODUCT_NM
    , s.CAL_DATE_LY
    , SUM(DERIVED_NET_AMT) AS CAL_PRODUCT_SALES_LY
    , SUM(s.DERIVED_GROSS_QTY) AS CAL_PRODUCT_CNT_LY
    , MAX(chk.CAL_CHECK_SALES_LY) AS CAL_CHECK_SALES_LY
    , MAX(s.CAL_CHECK_CNT_LY) AS CAL_CHECK_CNT_LY
    , SUM(s.DERIVED_NET_AMT) AS CAL_REST_SALES_LY
    , MAX(IFNULL(t.CAL_REST_TRANS_LY, 0)) AS CAL_REST_TRANS_LY
  
    , PRODUCT_HIERARCHY_ID
    , LEVEL5_PRODUCT_HIERARCHY_NM
    , LEVEL4_PRODUCT_HIERARCHY_NM
    , LEVEL3_PRODUCT_HIERARCHY_NM
    , LEVEL2_PRODUCT_HIERARCHY_NM
    , LEVEL1_PRODUCT_HIERARCHY_NM
    , DMA_CD
    , DMA_NM
    , L1NAME
    , L2NAME
    , L3NAME
    , L4NAME
    , L5NAME
    , OWNERSHIP_TYP
    , STATE
    , COUNTRY
    , PRODUCT_MISC1
    , PRODUCT_MISC2
    , PRODUCT_MISC3
    , PRODUCT_MISC4
    , PRODUCT_MISC5
    , PRODUCT_MISC6
    , PRODUCT_MISC7
    , PRODUCT_MISC8
    , PRODUCT_MISC9
    , PRODUCT_MISC10
FROM
    src_cal_period_dist_chk s
LEFT OUTER JOIN
(
    SELECT
      BRAND
      , STORE_NBR
      , MDM_PRODUCT_ID
      , CAL_DATE_LY
      , SUM(CAL_CHECK_SALES_LY) AS CAL_CHECK_SALES_LY
      , SUM(Rn) AS CAL_CHECK_CNT_LY
    FROM
        src_cal_period_dist_chk
    WHERE
        Rn = 1
    GROUP BY
        BRAND
      , STORE_NBR
      , MDM_PRODUCT_ID
      , CAL_DATE_LY
) chk
ON  s.BRAND = chk.BRAND
AND s.STORE_NBR = chk.STORE_NBR
AND s.MDM_PRODUCT_ID = chk.MDM_PRODUCT_ID
AND s.CAL_DATE_LY = chk.CAL_DATE_LY
LEFT OUTER JOIN
(
    SELECT
      BRAND
      , STORE_NBR
      , MDM_PRODUCT_ID
      , CAL_DATE_LY
      , COUNT(DISTINCT ORDER_ID) AS CAL_REST_TRANS_LY
    FROM
        tot
    GROUP BY
        BRAND
      , STORE_NBR
      , MDM_PRODUCT_ID
      , CAL_DATE_LY
) t
ON  s.BRAND = t.BRAND
AND s.STORE_NBR = t.STORE_NBR
AND s.MDM_PRODUCT_ID = t.MDM_PRODUCT_ID
AND s.CAL_DATE_LY = t.CAL_DATE_LY
GROUP BY
    s.BRAND
    , s.STORE_NBR
    , s.MDM_PRODUCT_ID
    , s.CAL_DATE_LY
    , s.CAL_REST_TRANS_LY
  
    , MDM_PRODUCT_NM
    , PRODUCT_HIERARCHY_ID
    , LEVEL5_PRODUCT_HIERARCHY_NM
    , LEVEL4_PRODUCT_HIERARCHY_NM
    , LEVEL3_PRODUCT_HIERARCHY_NM
    , LEVEL2_PRODUCT_HIERARCHY_NM
    , LEVEL1_PRODUCT_HIERARCHY_NM
    , DMA_CD
    , DMA_NM
    , L1NAME
    , L2NAME
    , L3NAME
    , L4NAME
    , L5NAME
    , OWNERSHIP_TYP
    , STATE
    , COUNTRY
    , PRODUCT_MISC1
    , PRODUCT_MISC2
    , PRODUCT_MISC3
    , PRODUCT_MISC4
    , PRODUCT_MISC5
    , PRODUCT_MISC6
    , PRODUCT_MISC7
    , PRODUCT_MISC8
    , PRODUCT_MISC9
    , PRODUCT_MISC10
ORDER BY s.CAL_DATE_LY, s.STORE_NBR, MDM_PRODUCT_ID  


';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_PRODUCT_SALES_FISC("FROMDATE" DATE, "TODATE" DATE)
RETURNS TABLE ("BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "MDM_PRODUCT_ID" NUMBER(38,0), "MDM_PRODUCT_NM" VARCHAR(16777216), "FISC_DATE_LY" DATE, "FISC_PRODUCT_SALES_LY" NUMBER(38,2), "FISC_PRODUCT_CNT_LY" NUMBER(38,0), "FISC_CHECK_SALES_LY" NUMBER(38,2), "FISC_CHECK_CNT_LY" NUMBER(38,0), "FISC_REST_SALES_LY" NUMBER(38,2), "FISC_REST_TRANS_LY" NUMBER(38,0), "PRODUCT_HIERARCHY_ID" NUMBER(38,0), "LEVEL5_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL4_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL3_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL2_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL1_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "DMA_CD" VARCHAR(16777216), "DMA_NM" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "PRODUCT_MISC1" VARCHAR(16777216), "PRODUCT_MISC2" VARCHAR(16777216), "PRODUCT_MISC3" VARCHAR(16777216), "PRODUCT_MISC4" VARCHAR(16777216), "PRODUCT_MISC5" VARCHAR(16777216), "PRODUCT_MISC6" VARCHAR(16777216), "PRODUCT_MISC7" VARCHAR(16777216), "PRODUCT_MISC8" VARCHAR(16777216), "PRODUCT_MISC9" VARCHAR(16777216), "PRODUCT_MISC10" VARCHAR(16777216))
LANGUAGE SQL
AS '

WITH date_interval AS
(
SELECT 
    MIN(FISCAL_COMPARABLE_DT) AS MIN_FISCAL_COMPARABLE_DT
    , MAX(FISCAL_COMPARABLE_DT) AS MAX_FISCAL_COMPARABLE_DT 
FROM 
    IDH_DEV.SHARED.DATE_DIM_V dd 
WHERE 
    CALENDAR_DT BETWEEN FromDate AND ToDate
)
, src_fisc_period AS
(
    SELECT
        od.ORDER_ID
      , od.ORDERLINE_ID
      , od.ORDER_DT AS BUSINESS_DT
      , od.STORE_ID AS STORE_NBR
      , IFNULL(od.MDM_PRODUCT_ID, 0) AS MDM_PRODUCT_ID
      , IFNULL(od.PRODUCT_NM, '''') AS MDM_PRODUCT_NM
      , IFNULL(DERIVED_GROSS_QTY, 0) AS DERIVED_GROSS_QTY
      , IFNULL(DERIVED_NET_AMT, 0) AS DERIVED_NET_AMT
      , od.BRAND_ID
      , CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
           WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
           WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
           WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
           WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
           WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
           WHEN od.BRAND_ID = ''rto'' THEN ''RT''
           ELSE ''UNKNOWN'' END AS BRAND
      , od.LOAD_DT
      , od.LAST_UPDATED_DTTM
      , od.ORDER_DT AS FISC_DATE_LY
  
      , IFNULL(od.PRODUCT_HIERARCHY_ID, 0) AS PRODUCT_HIERARCHY_ID
      , IFNULL(od.LEVEL5_PRODUCT_HIERARCHY_NM, '''') AS LEVEL5_PRODUCT_HIERARCHY_NM
      , IFNULL(od.LEVEL4_PRODUCT_HIERARCHY_NM, '''') AS LEVEL4_PRODUCT_HIERARCHY_NM
      , IFNULL(od.LEVEL3_PRODUCT_HIERARCHY_NM, '''') AS LEVEL3_PRODUCT_HIERARCHY_NM
      , IFNULL(od.LEVEL2_PRODUCT_HIERARCHY_NM, '''') AS LEVEL2_PRODUCT_HIERARCHY_NM
      , IFNULL(od.LEVEL1_PRODUCT_HIERARCHY_NM, '''') AS LEVEL1_PRODUCT_HIERARCHY_NM
      , st.DMA_CD
      , st.DMA_NM
      , IFNULL(lv.LEVEL1_NM, '''') AS L1NAME
      , IFNULL(lv.LEVEL2_NM, '''') AS L2NAME
      , IFNULL(lv.LEVEL3_NM, '''') AS L3NAME
      , IFNULL(lv.LEVEL4_NM, '''') AS L4NAME
      , IFNULL(lv.LEVEL5_NM, '''') AS L5NAME
      , st.OWNERSHIP_TYP AS OWNERSHIP_TYP
      , st.STATE_NM AS STATE
      , st.COUNTRY_NM AS COUNTRY
      , IFNULL(od.PRODUCT_MISC1, '''') AS PRODUCT_MISC1
      , IFNULL(od.PRODUCT_MISC2, '''') AS PRODUCT_MISC2
      , IFNULL(od.PRODUCT_MISC3, '''') AS PRODUCT_MISC3
      , IFNULL(od.PRODUCT_MISC4, '''') AS PRODUCT_MISC4
      , IFNULL(od.PRODUCT_MISC5, '''') AS PRODUCT_MISC5
      , IFNULL(od.PRODUCT_MISC6, '''') AS PRODUCT_MISC6
      , IFNULL(od.PRODUCT_MISC7, '''') AS PRODUCT_MISC7
      , IFNULL(od.PRODUCT_MISC8, '''') AS PRODUCT_MISC8
      , IFNULL(od.PRODUCT_MISC9, '''') AS PRODUCT_MISC9
      , IFNULL(od.PRODUCT_MISC10, '''') AS PRODUCT_MISC10
    FROM
        ORDER_DETAIL_V od
    LEFT OUTER JOIN
        IDH_DEV.SHARED.STORE_SCD_V st
    ON  st.STORE_ID = od.STORE_ID
    AND st.BRAND_ID = od.BRAND_ID
    AND st.CURRENT_IND = 1
    AND IFNULL(st.CLOSURE_DT, ''9999-12-31'') >= IFNULL((SELECT MIN_FISCAL_COMPARABLE_DT FROM date_interval), ''9999-12-31'')
    LEFT OUTER JOIN 
        IDH_DEV.OPERATION.LOCATION_HIERARCHY_V lv
    ON  lv.LOCATION_ID = od.STORE_ID
    AND lv.BRAND_ID = od.BRAND_ID
    WHERE
        IFNULL((CASE WHEN UPPER(CAST(VOIDED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(VOIDED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND IFNULL((CASE WHEN UPPER(CAST(CLEARED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(CLEARED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND IFNULL((CASE WHEN UPPER(CAST(DELETED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(DELETED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND od.ORDER_DT BETWEEN (SELECT MIN_FISCAL_COMPARABLE_DT FROM date_interval) AND (SELECT MAX_FISCAL_COMPARABLE_DT FROM date_interval)
)
, tot AS
(
SELECT
    x.ORDER_ID
    , x.BUSINESS_DT AS FISC_DATE_LY
    , x.STORE_NBR
    , x.BRAND
    , x.MDM_PRODUCT_ID
    , ROW_NUMBER() OVER (PARTITION BY ORDER_ID ORDER BY BUSINESS_DT, STORE_NBR, BRAND, MDM_PRODUCT_ID) AS Rn
FROM
    (
        SELECT DISTINCT 
            ORDER_ID, BUSINESS_DT, STORE_NBR, BRAND, MDM_PRODUCT_ID 
        FROM 
            src_fisc_period s1 
    ) x
    QUALIFY 
        Rn = 1
)

, src_fisc_period_dist_chk AS
(
SELECT
    ORDER_ID
  , BRAND
  , STORE_NBR
  , MDM_PRODUCT_ID
  , MDM_PRODUCT_NM
  , FISC_DATE_LY
  , DERIVED_GROSS_QTY
  , DERIVED_NET_AMT AS DERIVED_NET_AMT
  , SUM(DERIVED_NET_AMT) OVER(PARTITION BY ORDER_ID) AS FISC_CHECK_SALES_LY
  , COUNT(DISTINCT ORDER_ID) OVER(PARTITION BY FISC_DATE_LY, BRAND, STORE_NBR, MDM_PRODUCT_ID) AS FISC_CHECK_CNT_LY
  , COUNT(DISTINCT ORDER_ID) OVER(PARTITION BY FISC_DATE_LY, BRAND, STORE_NBR) AS FISC_REST_TRANS_LY
  , ROW_NUMBER() OVER(PARTITION BY ORDER_ID, FISC_DATE_LY, BRAND, STORE_NBR, MDM_PRODUCT_ID ORDER BY ORDER_ID) AS Rn

  , PRODUCT_HIERARCHY_ID
  , LEVEL5_PRODUCT_HIERARCHY_NM
  , LEVEL4_PRODUCT_HIERARCHY_NM
  , LEVEL3_PRODUCT_HIERARCHY_NM
  , LEVEL2_PRODUCT_HIERARCHY_NM
  , LEVEL1_PRODUCT_HIERARCHY_NM
  , DMA_CD
  , DMA_NM
  , L1NAME
  , L2NAME
  , L3NAME
  , L4NAME
  , L5NAME
  , OWNERSHIP_TYP
  , STATE
  , COUNTRY
  , PRODUCT_MISC1
  , PRODUCT_MISC2
  , PRODUCT_MISC3
  , PRODUCT_MISC4
  , PRODUCT_MISC5
  , PRODUCT_MISC6
  , PRODUCT_MISC7
  , PRODUCT_MISC8
  , PRODUCT_MISC9
  , PRODUCT_MISC10
FROM
    src_fisc_period
)

SELECT
    s.BRAND
    , s.STORE_NBR
    , s.MDM_PRODUCT_ID
    , s.MDM_PRODUCT_NM
    , s.FISC_DATE_LY
    , SUM(DERIVED_NET_AMT) AS FISC_PRODUCT_SALES_LY
    , SUM(s.DERIVED_GROSS_QTY) AS FISC_PRODUCT_CNT_LY
    , MAX(chk.FISC_CHECK_SALES_LY) AS FISC_CHECK_SALES_LY
    , MAX(s.FISC_CHECK_CNT_LY) AS FISC_CHECK_CNT_LY
    , SUM(s.DERIVED_NET_AMT) AS FISC_REST_SALES_LY
    , MAX(IFNULL(t.FISC_REST_TRANS_LY, 0)) AS FISC_REST_TRANS_LY
  
    , PRODUCT_HIERARCHY_ID
    , LEVEL5_PRODUCT_HIERARCHY_NM
    , LEVEL4_PRODUCT_HIERARCHY_NM
    , LEVEL3_PRODUCT_HIERARCHY_NM
    , LEVEL2_PRODUCT_HIERARCHY_NM
    , LEVEL1_PRODUCT_HIERARCHY_NM
    , DMA_CD
    , DMA_NM
    , L1NAME
    , L2NAME
    , L3NAME
    , L4NAME
    , L5NAME
    , OWNERSHIP_TYP
    , STATE
    , COUNTRY
    , PRODUCT_MISC1
    , PRODUCT_MISC2
    , PRODUCT_MISC3
    , PRODUCT_MISC4
    , PRODUCT_MISC5
    , PRODUCT_MISC6
    , PRODUCT_MISC7
    , PRODUCT_MISC8
    , PRODUCT_MISC9
    , PRODUCT_MISC10
FROM
    src_fisc_period_dist_chk s
LEFT OUTER JOIN
(
    SELECT
      BRAND
      , STORE_NBR
      , MDM_PRODUCT_ID
      , FISC_DATE_LY
      , SUM(FISC_CHECK_SALES_LY) AS FISC_CHECK_SALES_LY
      , SUM(Rn) AS FISC_CHECK_CNT_LY
    FROM
        src_fisc_period_dist_chk
    WHERE
        Rn = 1
    GROUP BY
        BRAND
      , STORE_NBR
      , MDM_PRODUCT_ID
      , FISC_DATE_LY
) chk
ON  s.BRAND = chk.BRAND
AND s.STORE_NBR = chk.STORE_NBR
AND s.MDM_PRODUCT_ID = chk.MDM_PRODUCT_ID
AND s.FISC_DATE_LY = chk.FISC_DATE_LY
LEFT OUTER JOIN
(
    SELECT
      BRAND
      , STORE_NBR
      , MDM_PRODUCT_ID
      , FISC_DATE_LY
      , COUNT(DISTINCT ORDER_ID) AS FISC_REST_TRANS_LY
    FROM
        tot
    GROUP BY
        BRAND
      , STORE_NBR
      , MDM_PRODUCT_ID
      , FISC_DATE_LY
) t
ON  s.BRAND = t.BRAND
AND s.STORE_NBR = t.STORE_NBR
AND s.MDM_PRODUCT_ID = t.MDM_PRODUCT_ID
AND s.FISC_DATE_LY = t.FISC_DATE_LY
GROUP BY
    s.BRAND
    , s.STORE_NBR
    , s.MDM_PRODUCT_ID
    , s.FISC_DATE_LY
  
    , s.MDM_PRODUCT_NM
    , PRODUCT_HIERARCHY_ID
    , LEVEL5_PRODUCT_HIERARCHY_NM
    , LEVEL4_PRODUCT_HIERARCHY_NM
    , LEVEL3_PRODUCT_HIERARCHY_NM
    , LEVEL2_PRODUCT_HIERARCHY_NM
    , LEVEL1_PRODUCT_HIERARCHY_NM
    , DMA_CD
    , DMA_NM
    , L1NAME
    , L2NAME
    , L3NAME
    , L4NAME
    , L5NAME
    , OWNERSHIP_TYP
    , STATE
    , COUNTRY
    , PRODUCT_MISC1
    , PRODUCT_MISC2
    , PRODUCT_MISC3
    , PRODUCT_MISC4
    , PRODUCT_MISC5
    , PRODUCT_MISC6
    , PRODUCT_MISC7
    , PRODUCT_MISC8
    , PRODUCT_MISC9
    , PRODUCT_MISC10
ORDER BY s.FISC_DATE_LY, s.STORE_NBR, MDM_PRODUCT_ID  

';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_PRODUCT_SALES_INIT("STARTDATE" DATE, "ENDDATE" DATE, "AGG_LEVEL" VARCHAR(16777216), "TIME_INTERVAL" VARCHAR(16777216))
RETURNS TABLE ("BUSINESS_DT" DATE, "BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "MDM_PRODUCT_ID" NUMBER(38,0), "MDM_PRODUCT_NM" VARCHAR(16777216), "DISCOUNT_AMT" FLOAT, "PRODUCT_CNT" NUMBER(38,0), "CHECK_SALES" FLOAT, "CHECK_CNT" NUMBER(18,0), "REST_SALES" FLOAT, "REST_TRANS" NUMBER(18,0), "PRODUCT_HIERARCHY_ID" NUMBER(38,0), "LEVEL5_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL4_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL3_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL2_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL1_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "PRODUCT_MISC1" VARCHAR(16777216), "PRODUCT_MISC2" VARCHAR(16777216), "PRODUCT_MISC3" VARCHAR(16777216), "PRODUCT_MISC4" VARCHAR(16777216), "PRODUCT_MISC5" VARCHAR(16777216), "PRODUCT_MISC6" VARCHAR(16777216), "PRODUCT_MISC7" VARCHAR(16777216), "PRODUCT_MISC8" VARCHAR(16777216), "PRODUCT_MISC9" VARCHAR(16777216), "PRODUCT_MISC10" VARCHAR(16777216))
LANGUAGE SQL
AS '


    WITH get_dates AS (
        SELECT 
        DATE_KEY,
        CALENDAR_DT,
        FISCAL_WEEK_START_DT
        FROM IDS_QA.INT_REF.COMP_DATES dt
        WHERE dt.TIME_INTERVAL = TIME_INTERVAL 
        AND dt.business_dt BETWEEN startDate AND endDate
    )  
    ,init as (
        SELECT
          CASE WHEN AGG_LEVEL =''DAY'' THEN CALENDAR_DT ELSE FISCAL_WEEK_START_DT END AS BUSINESS_DT,
          BRAND_ID,
          STORE_ID,
          MDM_ITEM_TYP,
          MDM_PRODUCT_ID,
          PRODUCT_NM,  
          ORDER_ID,
          DERIVED_NET_AMT,
          DERIVED_DISCOUNT_AMT,
          DERIVED_GROSS_QTY,
          PRODUCT_HIERARCHY_ID,
          LEVEL5_PRODUCT_HIERARCHY_NM,
          LEVEL4_PRODUCT_HIERARCHY_NM,
          LEVEL3_PRODUCT_HIERARCHY_NM,
          LEVEL2_PRODUCT_HIERARCHY_NM,
          LEVEL1_PRODUCT_HIERARCHY_NM,
          PRODUCT_MISC1,
          PRODUCT_MISC2,
          PRODUCT_MISC3,
          PRODUCT_MISC4,
          PRODUCT_MISC5,
          PRODUCT_MISC6,
          PRODUCT_MISC7,
          PRODUCT_MISC8,
          PRODUCT_MISC9,
          PRODUCT_MISC10,
          CALENDAR_DT,
          FISCAL_WEEK_START_DT,
          ROW_NUMBER() OVER (PARTITION BY BRAND_ID, STORE_ID, MDM_PRODUCT_ID, CASE WHEN AGG_LEVEL =''DAY'' THEN CALENDAR_DT ELSE FISCAL_WEEK_START_DT END ORDER BY CASE WHEN AGG_LEVEL =''DAY'' THEN CALENDAR_DT ELSE FISCAL_WEEK_START_DT END) AS RN
          FROM get_dates dt
          LEFT OUTER JOIN IDH_QA.SALES.ORDER_DETAIL_SUBSET_V odv 
          ON dt.DATE_KEY = odv.ORDER_DT_KEY 
          AND IFNULL((CASE WHEN UPPER(CAST(odv.VOIDED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(odv.VOIDED_IND AS VARCHAR(10))) END), '''') != ''Y''
          AND IFNULL((CASE WHEN UPPER(CAST(odv.CLEARED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(odv.CLEARED_IND AS VARCHAR(10))) END), '''') != ''Y''
          AND IFNULL((CASE WHEN UPPER(CAST(odv.DELETED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(odv.DELETED_IND AS VARCHAR(10))) END), '''') != ''Y'' 
          
       )
       ,rest_trans as (
          SELECT
              BUSINESS_DT
            , BRAND_ID
            , STORE_ID 
            , SUM(ifnull(DERIVED_NET_AMT, 0.00)) OVER(PARTITION BY BRAND_ID, STORE_ID, BUSINESS_DT) AS REST_SALES
            , COUNT(DISTINCT ORDER_ID) OVER(PARTITION BY BRAND_ID, STORE_ID, BUSINESS_DT) AS REST_TRANS
              FROM init
              QUALIFY ROW_NUMBER() OVER(PARTITION BY BRAND_ID, STORE_ID, BUSINESS_DT ORDER BY BUSINESS_DT) = 1     
       )
        , check_sales as (
          SELECT
              BUSINESS_DT
            , BRAND_ID
            , STORE_ID 
            , MDM_PRODUCT_ID
            , SUM(ifnull(DERIVED_NET_AMT, 0.00)) OVER(PARTITION BY BRAND_ID, STORE_ID, MDM_PRODUCT_ID, BUSINESS_DT) AS CHECK_SALES
            , COUNT (DISTINCT ORDER_ID) OVER(PARTITION BY BRAND_ID, STORE_ID, MDM_PRODUCT_ID, BUSINESS_DT) AS CHECK_CNT
              FROM init 
              WHERE MDM_ITEM_TYP = ''Product''
              QUALIFY ROW_NUMBER() OVER(PARTITION BY BRAND_ID, STORE_ID, MDM_PRODUCT_ID, BUSINESS_DT ORDER BY BUSINESS_DT) = 1
        ),
          product as (
          SELECT
              BUSINESS_DT
            , BRAND_ID
            , STORE_ID 
            , MDM_PRODUCT_ID
            , SUM(ifnull(DERIVED_DISCOUNT_AMT, 0.00)) OVER(PARTITION BY BRAND_ID, STORE_ID, MDM_PRODUCT_ID, BUSINESS_DT) AS DISCOUNT_AMT
            , SUM(ifnull(DERIVED_GROSS_QTY, 0.00)) OVER(PARTITION BY BRAND_ID, STORE_ID, MDM_PRODUCT_ID, BUSINESS_DT) AS PRODUCT_CNT
              FROM init 
              WHERE MDM_ITEM_TYP = ''Product''
              QUALIFY ROW_NUMBER() OVER(PARTITION BY BRAND_ID, STORE_ID, MDM_PRODUCT_ID, BUSINESS_DT ORDER BY BUSINESS_DT) = 1  
          )
          SELECT DISTINCT
              i.BUSINESS_DT
            , i.BRAND_ID
            , i.STORE_ID 
            , i.MDM_PRODUCT_ID
            , i.PRODUCT_NM
            , o.DISCOUNT_AMT
            , o.PRODUCT_CNT
            , c.CHECK_SALES
            , c.CHECK_CNT
            , r.REST_SALES 
            , r.REST_TRANS
            , i.PRODUCT_HIERARCHY_ID
            , i.LEVEL5_PRODUCT_HIERARCHY_NM
            , i.LEVEL4_PRODUCT_HIERARCHY_NM
            , i.LEVEL3_PRODUCT_HIERARCHY_NM
            , i.LEVEL2_PRODUCT_HIERARCHY_NM
            , i.LEVEL1_PRODUCT_HIERARCHY_NM
            , i.PRODUCT_MISC1
            , i.PRODUCT_MISC2
            , i.PRODUCT_MISC3
            , i.PRODUCT_MISC4
            , i.PRODUCT_MISC5
            , i.PRODUCT_MISC6
            , i.PRODUCT_MISC7
            , i.PRODUCT_MISC8
            , i.PRODUCT_MISC9
            , i.PRODUCT_MISC10
          FROM init i
          INNER JOIN rest_trans r
          ON i.BRAND_ID = r.BRAND_ID
          AND i.STORE_ID = r.STORE_ID
          AND i.BUSINESS_DT = r.BUSINESS_DT
          INNER JOIN check_sales c
          ON i.BRAND_ID = c.BRAND_ID
          AND i.STORE_ID = c.STORE_ID
          AND i.MDM_PRODUCT_ID = c.MDM_PRODUCT_ID
          AND i.BUSINESS_DT = c.BUSINESS_DT
          INNER JOIN product o
          ON i.BRAND_ID = o.BRAND_ID
          AND i.STORE_ID = o.STORE_ID
          AND i.MDM_PRODUCT_ID = o.MDM_PRODUCT_ID
          AND i.BUSINESS_DT = o.BUSINESS_DT
          WHERE i.MDM_ITEM_TYP = ''Product''
          AND i.RN = 1
          ';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_PRODUCT_SALES_MAIN("FROMDATE" DATE, "TODATE" DATE)
RETURNS TABLE ("AGG_LEVEL" VARCHAR(16777216), "BUSINESS_DT" VARCHAR(16777216), "BRAND" VARCHAR(16777216), "BRAND_ID" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "MDM_PRODUCT_ID" NUMBER(38,0), "PRODUCT_SALES_CY" FLOAT, "PRODUCT_CNT_CY" NUMBER(38,0), "CHECK_SALES_CY" FLOAT, "CHECK_CNT_CY" NUMBER(38,0), "REST_SALES_CY" FLOAT, "REST_TRANS_CY" NUMBER(38,0), "FISC_DATE_LY" DATE, "CAL_COMP_DATE_LY" DATE, "MDM_PRODUCT_NM" VARCHAR(16777216), "PRODUCT_HIERARCHY_ID" NUMBER(38,0), "LEVEL5_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL4_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL3_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL2_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL1_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "PRODUCT_MISC1" VARCHAR(16777216), "PRODUCT_MISC2" VARCHAR(16777216), "PRODUCT_MISC3" VARCHAR(16777216), "PRODUCT_MISC4" VARCHAR(16777216), "PRODUCT_MISC5" VARCHAR(16777216), "PRODUCT_MISC6" VARCHAR(16777216), "PRODUCT_MISC7" VARCHAR(16777216), "PRODUCT_MISC8" VARCHAR(16777216), "PRODUCT_MISC9" VARCHAR(16777216), "PRODUCT_MISC10" VARCHAR(16777216))
LANGUAGE SQL
AS '


WITH ORDER_DETAIL_V AS
(
SELECT
    od.*
FROM
    ORDER_DETAIL_V od /*for UAT should be replaced with ORDER_DETAIL_V*/
WHERE
    IFNULL((CASE WHEN UPPER(CAST(VOIDED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(VOIDED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND IFNULL((CASE WHEN UPPER(CAST(CLEARED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(CLEARED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND IFNULL((CASE WHEN UPPER(CAST(DELETED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(DELETED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND od.ORDER_DT BETWEEN FromDate AND ToDate
)

, CHECK_CY AS 
(
SELECT
    src.BRAND_ID
    , src.STORE_ID
    , src.MDM_PRODUCT_ID
    , src.ORDER_DT
    , SUM(src.CHECK_SALES_CY) AS CHECK_SALES_CY
    , COUNT(DISTINCT ORDER_ID) AS CHECK_CNT_CY
FROM
(
    SELECT
        od.ORDER_ID
        , od.BRAND_ID
        , od.STORE_ID
        , IFNULL(od.MDM_PRODUCT_ID, 0) AS MDM_PRODUCT_ID
        , od.ORDER_DT
        , SUM(DERIVED_NET_AMT) OVER(PARTITION BY od.ORDER_ID) AS CHECK_SALES_CY
        , ROW_NUMBER() OVER(PARTITION BY od.ORDER_ID, IFNULL(od.MDM_PRODUCT_ID, 0) ORDER BY od.ORDER_ID, IFNULL(od.MDM_PRODUCT_ID, 0)) AS Rn
    FROM
        ORDER_DETAIL_V od
    QUALIFY
        Rn = 1
) src
GROUP BY
    src.BRAND_ID
    , src.STORE_ID
    , src.MDM_PRODUCT_ID
    , src.ORDER_DT
)

, REST_CY AS
(
SELECT
    od.BRAND_ID
    , od.STORE_ID
    , od.ORDER_DT
    , SUM(DERIVED_NET_AMT) AS REST_SALES_CY
    , COUNT(DISTINCT od.ORDER_ID) AS REST_TRANS_CY
FROM
    ORDER_DETAIL_V od
GROUP BY
    od.BRAND_ID
    , od.STORE_ID
    , od.ORDER_DT
)

SELECT
    ''DAY'' AS AGG_LEVEL
    , od.ORDER_DT AS BUSINESS_DT
    , CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
         WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
         WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
         WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
         WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
         WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
         WHEN od.BRAND_ID = ''rto'' THEN ''RT''
         ELSE ''UNKNOWN'' END AS BRAND
    , od.BRAND_ID
    , od.STORE_ID AS STORE_NBR
    , od.MDM_PRODUCT_ID AS MDM_PRODUCT_ID

    , od.PRODUCT_SALES_CY
    , od.PRODUCT_CNT_CY
    , CHECK_CY.CHECK_SALES_CY
    , CHECK_CY.CHECK_CNT_CY
    , REST_CY.REST_SALES_CY
    , REST_CY.REST_TRANS_CY
  
    , dd.FISCAL_COMPARABLE_DT AS FISC_DATE_LY
    , dd.CALENDAR_COMPARABLE_DT AS CAL_COMP_DATE_LY
  
    , od.MDM_PRODUCT_NM AS MDM_PRODUCT_NM
    , od.PRODUCT_HIERARCHY_ID AS PRODUCT_HIERARCHY_ID
    , od.LEVEL5_PRODUCT_HIERARCHY_NM AS LEVEL5_PRODUCT_HIERARCHY_NM
    , od.LEVEL4_PRODUCT_HIERARCHY_NM AS LEVEL4_PRODUCT_HIERARCHY_NM
    , od.LEVEL3_PRODUCT_HIERARCHY_NM AS LEVEL3_PRODUCT_HIERARCHY_NM
    , od.LEVEL2_PRODUCT_HIERARCHY_NM AS LEVEL2_PRODUCT_HIERARCHY_NM
    , od.LEVEL1_PRODUCT_HIERARCHY_NM AS LEVEL1_PRODUCT_HIERARCHY_NM
    , od.PRODUCT_MISC1 AS PRODUCT_MISC1
    , od.PRODUCT_MISC2 AS PRODUCT_MISC2
    , od.PRODUCT_MISC3 AS PRODUCT_MISC3
    , od.PRODUCT_MISC4 AS PRODUCT_MISC4
    , od.PRODUCT_MISC5 AS PRODUCT_MISC5
    , od.PRODUCT_MISC6 AS PRODUCT_MISC6
    , od.PRODUCT_MISC7 AS PRODUCT_MISC7
    , od.PRODUCT_MISC8 AS PRODUCT_MISC8
    , od.PRODUCT_MISC9 AS PRODUCT_MISC9
    , od.PRODUCT_MISC10 AS PRODUCT_MISC10

FROM
    (
    SELECT
        odv.ORDER_DT
        , ORDER_DT_KEY
        , odv.STORE_ID
        , odv.BRAND_ID
        , IFNULL(odv.MDM_PRODUCT_ID, 0) AS MDM_PRODUCT_ID
        , odv.PRODUCT_NM AS MDM_PRODUCT_NM
        , odv.PRODUCT_HIERARCHY_ID
        , odv.LEVEL5_PRODUCT_HIERARCHY_NM
        , odv.LEVEL4_PRODUCT_HIERARCHY_NM
        , odv.LEVEL3_PRODUCT_HIERARCHY_NM
        , odv.LEVEL2_PRODUCT_HIERARCHY_NM
        , odv.LEVEL1_PRODUCT_HIERARCHY_NM
        , odv.PRODUCT_MISC1
        , odv.PRODUCT_MISC2
        , odv.PRODUCT_MISC3
        , odv.PRODUCT_MISC4
        , odv.PRODUCT_MISC5
        , odv.PRODUCT_MISC6
        , odv.PRODUCT_MISC7
        , odv.PRODUCT_MISC8
        , odv.PRODUCT_MISC9
        , odv.PRODUCT_MISC10
        
        , SUM(DERIVED_NET_AMT) AS PRODUCT_SALES_CY
        , SUM(DERIVED_GROSS_QTY) AS PRODUCT_CNT_CY
    FROM
        ORDER_DETAIL_V odv
    WHERE
        odv.MDM_ITEM_TYP = ''Product''
    GROUP BY
        odv.ORDER_DT
        , ORDER_DT_KEY
        , odv.STORE_ID
        , odv.BRAND_ID
        , IFNULL(odv.MDM_PRODUCT_ID, 0)
      
        , odv.PRODUCT_NM
        , odv.PRODUCT_HIERARCHY_ID
        , odv.LEVEL5_PRODUCT_HIERARCHY_NM
        , odv.LEVEL4_PRODUCT_HIERARCHY_NM
        , odv.LEVEL3_PRODUCT_HIERARCHY_NM
        , odv.LEVEL2_PRODUCT_HIERARCHY_NM
        , odv.LEVEL1_PRODUCT_HIERARCHY_NM
        , odv.PRODUCT_MISC1
        , odv.PRODUCT_MISC2
        , odv.PRODUCT_MISC3
        , odv.PRODUCT_MISC4
        , odv.PRODUCT_MISC5
        , odv.PRODUCT_MISC6
        , odv.PRODUCT_MISC7
        , odv.PRODUCT_MISC8
        , odv.PRODUCT_MISC9
        , odv.PRODUCT_MISC10
    ) od
INNER JOIN
    IDH_DEV.SHARED.DATE_DIM_V dd
ON  dd.CALENDAR_DT = od.ORDER_DT
LEFT OUTER JOIN
    CHECK_CY
ON  CHECK_CY.BRAND_ID = od.BRAND_ID
AND CHECK_CY.STORE_ID = od.STORE_ID
AND CHECK_CY.MDM_PRODUCT_ID = od.MDM_PRODUCT_ID
AND CHECK_CY.ORDER_DT = od.ORDER_DT
LEFT OUTER JOIN
    REST_CY
ON  REST_CY.BRAND_ID = od.BRAND_ID
AND REST_CY.STORE_ID = od.STORE_ID
AND REST_CY.ORDER_DT = od.ORDER_DT
ORDER BY
    MDM_PRODUCT_ID
    , BUSINESS_DT
    , BRAND
    , STORE_NBR


';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_PRODUCT_SALES_MAIN2("FROMDATE" DATE, "TODATE" DATE)
RETURNS TABLE ("AGG_LEVEL" VARCHAR(16777216), "BUSINESS_DT" VARCHAR(16777216), "BRAND" VARCHAR(16777216), "BRAND_ID" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "MDM_PRODUCT_ID" NUMBER(38,0), "PRODUCT_SALES_CY" FLOAT, "PRODUCT_CNT_CY" NUMBER(38,0), "CHECK_SALES_CY" FLOAT, "CHECK_CNT_CY" NUMBER(38,0), "REST_SALES_CY" FLOAT, "REST_TRANS_CY" NUMBER(38,0), "FISC_DATE_LY" DATE, "CAL_COMP_DATE_LY" DATE, "MDM_PRODUCT_NM" VARCHAR(16777216), "PRODUCT_HIERARCHY_ID" NUMBER(38,0), "LEVEL5_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL4_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL3_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL2_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL1_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "PRODUCT_MISC1" VARCHAR(16777216), "PRODUCT_MISC2" VARCHAR(16777216), "PRODUCT_MISC3" VARCHAR(16777216), "PRODUCT_MISC4" VARCHAR(16777216), "PRODUCT_MISC5" VARCHAR(16777216), "PRODUCT_MISC6" VARCHAR(16777216), "PRODUCT_MISC7" VARCHAR(16777216), "PRODUCT_MISC8" VARCHAR(16777216), "PRODUCT_MISC9" VARCHAR(16777216), "PRODUCT_MISC10" VARCHAR(16777216))
LANGUAGE SQL
AS '


WITH ORDER_DETAIL_V AS
(
SELECT
    od.*
FROM
    IDH_QA.SALES.ORDER_DETAIL_SUBSET_V /*IDS_DEV.DATASTORE.ORDER_DETAIL_SUBSET_TBL*//*ORDER_DETAIL_SUBSET_V*/ od /*for UAT should be replaced with ORDER_DETAIL_V*/
WHERE
    IFNULL((CASE WHEN UPPER(CAST(VOIDED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(VOIDED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND IFNULL((CASE WHEN UPPER(CAST(CLEARED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(CLEARED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND IFNULL((CASE WHEN UPPER(CAST(DELETED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(DELETED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND od.ORDER_DT BETWEEN FromDate AND ToDate
)

/*, CHECK_CY AS 
(
SELECT
    src.BRAND_ID
    , src.STORE_ID
    , src.MDM_PRODUCT_ID
    , src.ORDER_DT
    , SUM(src.CHECK_SALES_CY) AS CHECK_SALES_CY
    , COUNT(DISTINCT ORDER_ID) AS CHECK_CNT_CY
FROM
(
    SELECT
        od.ORDER_ID
        , od.BRAND_ID
        , od.STORE_ID
        , IFNULL(od.MDM_PRODUCT_ID, 0) AS MDM_PRODUCT_ID
        , od.ORDER_DT
        , SUM(DERIVED_NET_AMT) OVER(PARTITION BY od.ORDER_ID) AS CHECK_SALES_CY
        , ROW_NUMBER() OVER(PARTITION BY od.ORDER_ID, IFNULL(od.MDM_PRODUCT_ID, 0) ORDER BY od.ORDER_ID, IFNULL(od.MDM_PRODUCT_ID, 0)) AS Rn
    FROM
        ORDER_DETAIL_V od
    QUALIFY
        Rn = 1
) src
GROUP BY
    src.BRAND_ID
    , src.STORE_ID
    , src.MDM_PRODUCT_ID
    , src.ORDER_DT
)*/

/*, REST_CY AS
(
SELECT
    od.BRAND_ID
    , od.STORE_ID
    , od.ORDER_DT
    , SUM(DERIVED_NET_AMT) AS REST_SALES_CY
    , COUNT(DISTINCT od.ORDER_ID) AS REST_TRANS_CY
FROM
    ORDER_DETAIL_V od
GROUP BY
    od.BRAND_ID
    , od.STORE_ID
    , od.ORDER_DT
)*/

SELECT
    ''DAY'' AS AGG_LEVEL
    , od.ORDER_DT AS BUSINESS_DT
    , CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
         WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
         WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
         WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
         WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
         WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
         WHEN od.BRAND_ID = ''rto'' THEN ''RT''
         ELSE ''UNKNOWN'' END AS BRAND
    , od.BRAND_ID
    , od.STORE_ID AS STORE_NBR
    , od.MDM_PRODUCT_ID AS MDM_PRODUCT_ID

    , od.PRODUCT_SALES_CY
    , od.PRODUCT_CNT_CY
    , CHECK_CY.CHECK_SALES_CY
    , CHECK_CY.CHECK_CNT_CY
    , REST_CY.REST_SALES_CY
    , REST_CY.REST_TRANS_CY
  
    , dd.FISCAL_COMPARABLE_DT AS FISC_DATE_LY
    , dd.CALENDAR_COMPARABLE_DT AS CAL_COMP_DATE_LY
  
    , od.MDM_PRODUCT_NM AS MDM_PRODUCT_NM
    , od.PRODUCT_HIERARCHY_ID AS PRODUCT_HIERARCHY_ID
    , od.LEVEL5_PRODUCT_HIERARCHY_NM AS LEVEL5_PRODUCT_HIERARCHY_NM
    , od.LEVEL4_PRODUCT_HIERARCHY_NM AS LEVEL4_PRODUCT_HIERARCHY_NM
    , od.LEVEL3_PRODUCT_HIERARCHY_NM AS LEVEL3_PRODUCT_HIERARCHY_NM
    , od.LEVEL2_PRODUCT_HIERARCHY_NM AS LEVEL2_PRODUCT_HIERARCHY_NM
    , od.LEVEL1_PRODUCT_HIERARCHY_NM AS LEVEL1_PRODUCT_HIERARCHY_NM
    , od.PRODUCT_MISC1 AS PRODUCT_MISC1
    , od.PRODUCT_MISC2 AS PRODUCT_MISC2
    , od.PRODUCT_MISC3 AS PRODUCT_MISC3
    , od.PRODUCT_MISC4 AS PRODUCT_MISC4
    , od.PRODUCT_MISC5 AS PRODUCT_MISC5
    , od.PRODUCT_MISC6 AS PRODUCT_MISC6
    , od.PRODUCT_MISC7 AS PRODUCT_MISC7
    , od.PRODUCT_MISC8 AS PRODUCT_MISC8
    , od.PRODUCT_MISC9 AS PRODUCT_MISC9
    , od.PRODUCT_MISC10 AS PRODUCT_MISC10

FROM
    (
    SELECT
        odv.ORDER_DT
        , ORDER_DT_KEY
        , odv.STORE_ID
        , odv.BRAND_ID
        , IFNULL(odv.MDM_PRODUCT_ID, 0) AS MDM_PRODUCT_ID
        , odv.PRODUCT_NM AS MDM_PRODUCT_NM
        , odv.PRODUCT_HIERARCHY_ID
        , odv.LEVEL5_PRODUCT_HIERARCHY_NM
        , odv.LEVEL4_PRODUCT_HIERARCHY_NM
        , odv.LEVEL3_PRODUCT_HIERARCHY_NM
        , odv.LEVEL2_PRODUCT_HIERARCHY_NM
        , odv.LEVEL1_PRODUCT_HIERARCHY_NM
        , odv.PRODUCT_MISC1
        , odv.PRODUCT_MISC2
        , odv.PRODUCT_MISC3
        , odv.PRODUCT_MISC4
        , odv.PRODUCT_MISC5
        , odv.PRODUCT_MISC6
        , odv.PRODUCT_MISC7
        , odv.PRODUCT_MISC8
        , odv.PRODUCT_MISC9
        , odv.PRODUCT_MISC10
        
        , SUM(DERIVED_NET_AMT) AS PRODUCT_SALES_CY
        , SUM(DERIVED_GROSS_QTY) AS PRODUCT_CNT_CY
    FROM
        ORDER_DETAIL_V odv
    WHERE
        odv.MDM_ITEM_TYP = ''Product''
    GROUP BY
        odv.ORDER_DT
        , ORDER_DT_KEY
        , odv.STORE_ID
        , odv.BRAND_ID
        , IFNULL(odv.MDM_PRODUCT_ID, 0)
      
        , odv.PRODUCT_NM
        , odv.PRODUCT_HIERARCHY_ID
        , odv.LEVEL5_PRODUCT_HIERARCHY_NM
        , odv.LEVEL4_PRODUCT_HIERARCHY_NM
        , odv.LEVEL3_PRODUCT_HIERARCHY_NM
        , odv.LEVEL2_PRODUCT_HIERARCHY_NM
        , odv.LEVEL1_PRODUCT_HIERARCHY_NM
        , odv.PRODUCT_MISC1
        , odv.PRODUCT_MISC2
        , odv.PRODUCT_MISC3
        , odv.PRODUCT_MISC4
        , odv.PRODUCT_MISC5
        , odv.PRODUCT_MISC6
        , odv.PRODUCT_MISC7
        , odv.PRODUCT_MISC8
        , odv.PRODUCT_MISC9
        , odv.PRODUCT_MISC10
    ) od
INNER JOIN
    IDH_QA.SHARED.DATE_DIM_V dd
ON  dd.CALENDAR_DT = od.ORDER_DT
LEFT OUTER JOIN
(
SELECT
    src.BRAND_ID
    , src.STORE_ID
    , src.MDM_PRODUCT_ID
    , src.ORDER_DT
    , SUM(src.CHECK_SALES_CY) AS CHECK_SALES_CY
    , COUNT(DISTINCT ORDER_ID) AS CHECK_CNT_CY
FROM
(
    SELECT
        od.ORDER_ID
        , od.BRAND_ID
        , od.STORE_ID
        , IFNULL(od.MDM_PRODUCT_ID, 0) AS MDM_PRODUCT_ID
        , od.ORDER_DT
        , SUM(DERIVED_NET_AMT) OVER(PARTITION BY od.ORDER_ID) AS CHECK_SALES_CY
        , ROW_NUMBER() OVER(PARTITION BY od.ORDER_ID, IFNULL(od.MDM_PRODUCT_ID, 0) ORDER BY od.ORDER_ID, IFNULL(od.MDM_PRODUCT_ID, 0)) AS Rn
    FROM
        ORDER_DETAIL_V od
    QUALIFY
        Rn = 1
) src
GROUP BY
    src.BRAND_ID
    , src.STORE_ID
    , src.MDM_PRODUCT_ID
    , src.ORDER_DT
)   CHECK_CY
ON  CHECK_CY.BRAND_ID = od.BRAND_ID
AND CHECK_CY.STORE_ID = od.STORE_ID
AND CHECK_CY.MDM_PRODUCT_ID = od.MDM_PRODUCT_ID
AND CHECK_CY.ORDER_DT = od.ORDER_DT
LEFT OUTER JOIN
(
SELECT
    od.BRAND_ID
    , od.STORE_ID
    , od.ORDER_DT
    , SUM(DERIVED_NET_AMT) AS REST_SALES_CY
    , COUNT(DISTINCT od.ORDER_ID) AS REST_TRANS_CY
FROM
    ORDER_DETAIL_V od
GROUP BY
    od.BRAND_ID
    , od.STORE_ID
    , od.ORDER_DT
)   REST_CY
ON  REST_CY.BRAND_ID = od.BRAND_ID
AND REST_CY.STORE_ID = od.STORE_ID
AND REST_CY.ORDER_DT = od.ORDER_DT
ORDER BY
    MDM_PRODUCT_ID
    , BUSINESS_DT
    , BRAND
    , STORE_NBR


';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_PRODUCT_SALES_MAIN_V("FROMDATE" DATE, "TODATE" DATE)
RETURNS TABLE ("AGG_LEVEL" VARCHAR(16777216), "BUSINESS_DT" VARCHAR(16777216), "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_CD" VARCHAR(16777216), "DMA_NM" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "DAY_OF_WEEK" VARCHAR(16777216), "HOLIDAY_IND_CY" VARCHAR(16777216), "HOLIDAY_NM_CY" VARCHAR(16777216), "MDM_PRODUCT_ID" NUMBER(38,0), "MDM_PRODUCT_NM" VARCHAR(16777216), "PRODUCT_HIERARCHY_ID" NUMBER(38,0), "LEVEL5_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL4_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL3_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL2_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL1_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "PRODUCT_MISC1" VARCHAR(16777216), "PRODUCT_MISC2" VARCHAR(16777216), "PRODUCT_MISC3" VARCHAR(16777216), "PRODUCT_MISC4" VARCHAR(16777216), "PRODUCT_MISC5" VARCHAR(16777216), "PRODUCT_MISC6" VARCHAR(16777216), "PRODUCT_MISC7" VARCHAR(16777216), "PRODUCT_MISC8" VARCHAR(16777216), "PRODUCT_MISC9" VARCHAR(16777216), "PRODUCT_MISC10" VARCHAR(16777216), "PRODUCT_SALES_CY" FLOAT, "PRODUCT_CNT_CY" NUMBER(38,0), "CHECK_SALES_CY" FLOAT, "CHECK_CNT_CY" NUMBER(38,0), "REST_SALES_CY" FLOAT, "REST_TRANS_CY" NUMBER(38,0), "FISC_DATE_LY" DATE, "FISC_HOLIDAY_IND_LY" VARCHAR(16777216), "FISC_HOLIDAY_NM_LY" VARCHAR(16777216), "CAL_COMP_DATE_LY" DATE, "CAL_HOLIDAY_IND_LY" VARCHAR(16777216), "CAL_HOLIDAY_NM_LY" VARCHAR(16777216))
LANGUAGE SQL
AS '


WITH ORDER_DETAIL_V AS
(
SELECT
    od.*
FROM
    IDS_DEV.DATASTORE.ORDER_DETAIL_SUBSET_TBL/*ORDER_DETAIL_SUBSET_V*/ od /*for UAT should be replaced with ORDER_DETAIL_V*/
WHERE
    IFNULL((CASE WHEN UPPER(CAST(VOIDED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(VOIDED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND IFNULL((CASE WHEN UPPER(CAST(CLEARED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(CLEARED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND IFNULL((CASE WHEN UPPER(CAST(DELETED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(DELETED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND od.ORDER_DT BETWEEN FromDate AND ToDate
)

, CHECK_CY AS 
(
SELECT
    src.BRAND_ID
    , src.STORE_ID
    , src.MDM_PRODUCT_ID
    , src.ORDER_DT
    , SUM(src.CHECK_SALES_CY) AS CHECK_SALES_CY
    , COUNT(DISTINCT ORDER_ID) AS CHECK_CNT_CY
FROM
(
    SELECT
        od.ORDER_ID
        , od.BRAND_ID
        , od.STORE_ID
        , IFNULL(od.MDM_PRODUCT_ID, 0) AS MDM_PRODUCT_ID
        , od.ORDER_DT
        , SUM(DERIVED_NET_AMT) OVER(PARTITION BY od.ORDER_ID) AS CHECK_SALES_CY
    FROM
        ORDER_DETAIL_V od
    WHERE
        od.MDM_ITEM_TYP = ''Product''
) src
GROUP BY
    src.BRAND_ID
    , src.STORE_ID
    , src.MDM_PRODUCT_ID
    , src.ORDER_DT
)

, REST_CY AS
(
SELECT
    od.BRAND_ID
    , od.STORE_ID
    , od.ORDER_DT
    , SUM(DERIVED_NET_AMT) AS REST_SALES_CY
    , COUNT(DISTINCT od.ORDER_ID) AS REST_TRANS_CY
FROM
    ORDER_DETAIL_V od
GROUP BY
    od.BRAND_ID
    , od.STORE_ID
    , od.ORDER_DT
)

SELECT
    ''DAY'' AS AGG_LEVEL
    , od.ORDER_DT AS BUSINESS_DT
    , CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
         WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
         WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
         WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
         WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
         WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
         WHEN od.BRAND_ID = ''rto'' THEN ''RT''
         ELSE ''UNKNOWN'' END AS BRAND
    , od.STORE_ID AS STORE_NBR
    , st.DMA_CD AS DMA_CD
    , st.DMA_NM AS DMA_NM
    , lv.LEVEL1_NM AS L1NAME
    , lv.LEVEL2_NM AS L2NAME
    , lv.LEVEL3_NM AS L3NAME
    , lv.LEVEL4_NM AS L4NAME
    , lv.LEVEL5_NM AS L5NAME
    , st.OWNERSHIP_TYP AS OWNERSHIP_TYP
    , st.STATE_NM AS STATE
    , st.COUNTRY_NM AS COUNTRY
    , dd.FISCAL_YEAR_NBR AS FISC_YEAR_NBR
    , dd.FISCAL_QUARTER_NBR AS FISC_QUARTER_NBR
    , dd.FISCAL_PERIOD_NBR AS FISC_PERIOD_NBR
    , dd.FISCAL_WEEK_NBR AS FISC_WEEK_NBR
    , dd.CALENDAR_DAY_NM AS DAY_OF_WEEK

    , CASE WHEN UPPER(CAST(hlf.HOLIDAY_IND AS VARCHAR(10))) = ''TRUE'' THEN ''Y''
           WHEN UPPER(CAST(hlf.HOLIDAY_IND AS VARCHAR(10))) = ''FALSE'' THEN ''N''
           ELSE NULL END AS HOLIDAY_IND_CY
    , hlf.HOLIDAY_LIST_NM AS HOLIDAY_NM_CY

    , od.MDM_PRODUCT_ID AS MDM_PRODUCT_ID
    , od.MDM_PRODUCT_NM AS MDM_PRODUCT_NM
    , od.PRODUCT_HIERARCHY_ID AS PRODUCT_HIERARCHY_ID
    
    , od.LEVEL5_PRODUCT_HIERARCHY_NM AS LEVEL5_PRODUCT_HIERARCHY_NM
    , od.LEVEL4_PRODUCT_HIERARCHY_NM AS LEVEL4_PRODUCT_HIERARCHY_NM
    , od.LEVEL3_PRODUCT_HIERARCHY_NM AS LEVEL3_PRODUCT_HIERARCHY_NM
    , od.LEVEL2_PRODUCT_HIERARCHY_NM AS LEVEL2_PRODUCT_HIERARCHY_NM
    , od.LEVEL1_PRODUCT_HIERARCHY_NM AS LEVEL1_PRODUCT_HIERARCHY_NM

    , od.PRODUCT_MISC1 AS PRODUCT_MISC1
    , od.PRODUCT_MISC2 AS PRODUCT_MISC2
    , od.PRODUCT_MISC3 AS PRODUCT_MISC3
    , od.PRODUCT_MISC4 AS PRODUCT_MISC4
    , od.PRODUCT_MISC5 AS PRODUCT_MISC5
    , od.PRODUCT_MISC6 AS PRODUCT_MISC6
    , od.PRODUCT_MISC7 AS PRODUCT_MISC7
    , od.PRODUCT_MISC8 AS PRODUCT_MISC8
    , od.PRODUCT_MISC9 AS PRODUCT_MISC9
    , od.PRODUCT_MISC10 AS PRODUCT_MISC10
    
    , od.PRODUCT_SALES_CY
    , od.PRODUCT_CNT_CY
    , CHECK_CY.CHECK_SALES_CY
    , CHECK_CY.CHECK_CNT_CY
    , REST_CY.REST_SALES_CY
    , REST_CY.REST_TRANS_CY

    , dd.FISCAL_COMPARABLE_DT AS FISC_DATE_LY
    , CASE WHEN UPPER(CAST(fisc_dat.HOLIDAY_IND AS VARCHAR(10))) = ''TRUE'' THEN ''Y''
           WHEN UPPER(CAST(fisc_dat.HOLIDAY_IND AS VARCHAR(10))) = ''FALSE'' THEN ''N''
           ELSE NULL END AS FISC_HOLIDAY_IND_LY

    , fisc_dat.HOLIDAY_LIST_NM AS FISC_HOLIDAY_NM_LY
    , dd.CALENDAR_COMPARABLE_DT AS CAL_COMP_DATE_LY
    , CASE WHEN UPPER(CAST(hl_cal.HOLIDAY_IND AS VARCHAR(10))) = ''TRUE'' THEN ''Y''
           WHEN UPPER(CAST(hl_cal.HOLIDAY_IND AS VARCHAR(10))) = ''FALSE'' THEN ''N''
           ELSE NULL END AS CAL_HOLIDAY_IND_LY
    , hl_cal.HOLIDAY_LIST_NM AS CAL_HOLIDAY_NM_LY

FROM
    (
    SELECT
        odv.ORDER_DT
        , ORDER_DT_KEY
        , odv.STORE_ID
        , odv.BRAND_ID
        , IFNULL(odv.MDM_PRODUCT_ID, 0) AS MDM_PRODUCT_ID
        , SUM(DERIVED_NET_AMT) AS PRODUCT_SALES_CY
        , SUM(DERIVED_GROSS_QTY) AS PRODUCT_CNT_CY
  
        , MAX(odv.PRODUCT_NM) AS MDM_PRODUCT_NM
        , MAX(odv.PRODUCT_HIERARCHY_ID) AS PRODUCT_HIERARCHY_ID
        , MAX(odv.LEVEL5_PRODUCT_HIERARCHY_NM) AS LEVEL5_PRODUCT_HIERARCHY_NM
        , MAX(odv.LEVEL4_PRODUCT_HIERARCHY_NM) AS LEVEL4_PRODUCT_HIERARCHY_NM
        , MAX(odv.LEVEL3_PRODUCT_HIERARCHY_NM) AS LEVEL3_PRODUCT_HIERARCHY_NM
        , MAX(odv.LEVEL2_PRODUCT_HIERARCHY_NM) AS LEVEL2_PRODUCT_HIERARCHY_NM
        , MAX(odv.LEVEL1_PRODUCT_HIERARCHY_NM) AS LEVEL1_PRODUCT_HIERARCHY_NM
        , MAX(odv.PRODUCT_MISC1) AS PRODUCT_MISC1
        , MAX(odv.PRODUCT_MISC2) AS PRODUCT_MISC2
        , MAX(odv.PRODUCT_MISC3) AS PRODUCT_MISC3
        , MAX(odv.PRODUCT_MISC4) AS PRODUCT_MISC4
        , MAX(odv.PRODUCT_MISC5) AS PRODUCT_MISC5
        , MAX(odv.PRODUCT_MISC6) AS PRODUCT_MISC6
        , MAX(odv.PRODUCT_MISC7) AS PRODUCT_MISC7
        , MAX(odv.PRODUCT_MISC8) AS PRODUCT_MISC8
        , MAX(odv.PRODUCT_MISC9) AS PRODUCT_MISC9
        , MAX(odv.PRODUCT_MISC10) AS PRODUCT_MISC10
    FROM
        ORDER_DETAIL_V odv
    WHERE
        odv.MDM_ITEM_TYP = ''Product''
    GROUP BY
        odv.ORDER_DT
        , ORDER_DT_KEY
        , odv.STORE_ID
        , odv.BRAND_ID
        , IFNULL(odv.MDM_PRODUCT_ID, 0)
  
        , IFNULL(odv.PRODUCT_NM, '''')
        , IFNULL(odv.PRODUCT_HIERARCHY_ID, 0)
        , IFNULL(odv.LEVEL5_PRODUCT_HIERARCHY_NM, '''')
        , IFNULL(odv.LEVEL4_PRODUCT_HIERARCHY_NM, '''')
        , IFNULL(odv.LEVEL3_PRODUCT_HIERARCHY_NM, '''')
        , IFNULL(odv.LEVEL2_PRODUCT_HIERARCHY_NM, '''')
        , IFNULL(odv.LEVEL1_PRODUCT_HIERARCHY_NM, '''')
        , IFNULL(odv.PRODUCT_MISC1, '''')
        , IFNULL(odv.PRODUCT_MISC2, '''')
        , IFNULL(odv.PRODUCT_MISC3, '''')
        , IFNULL(odv.PRODUCT_MISC4, '''')
        , IFNULL(odv.PRODUCT_MISC5, '''')
        , IFNULL(odv.PRODUCT_MISC6, '''')
        , IFNULL(odv.PRODUCT_MISC7, '''')
        , IFNULL(odv.PRODUCT_MISC8, '''')
        , IFNULL(odv.PRODUCT_MISC9, '''')
        , IFNULL(odv.PRODUCT_MISC10, '''')
    ) od
INNER JOIN
    IDH_QA.SHARED.DATE_DIM_V dd
ON  dd.CALENDAR_DT = od.ORDER_DT
LEFT OUTER JOIN
    IDH_QA.SHARED.STORE_SCD_PROD_V st
ON  st.STORE_ID = od.STORE_ID
AND st.BRAND_ID = od.BRAND_ID
AND st.CURRENT_IND = 1
AND IFNULL(st.CLOSURE_DT, ''9999-12-31'') >= FromDate
LEFT OUTER JOIN 
    IDH_QA.OPERATION.LOCATION_HIERARCHY_V lv
ON  lv.LOCATION_ID = od.STORE_ID
AND lv.BRAND_ID = od.BRAND_ID
LEFT OUTER JOIN
    IDH_QA.SHARED.HOLIDAY_LIST_V hlf
ON  hlf.DATE_KEY = od.ORDER_DT_KEY
LEFT OUTER JOIN
    IDH_QA.SHARED.HOLIDAY_LIST_V fisc_dat
ON  TO_DATE(CAST(fisc_dat.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = dd.FISCAL_COMPARABLE_DT
LEFT OUTER JOIN
    IDH_QA.SHARED.HOLIDAY_LIST_V hl_cal
ON  TO_DATE(CAST(hl_cal.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = dd.CALENDAR_COMPARABLE_DT
LEFT OUTER JOIN
    CHECK_CY
ON  CHECK_CY.BRAND_ID = od.BRAND_ID
AND CHECK_CY.STORE_ID = od.STORE_ID
AND CHECK_CY.MDM_PRODUCT_ID = od.MDM_PRODUCT_ID
AND CHECK_CY.ORDER_DT = od.ORDER_DT
LEFT OUTER JOIN
    REST_CY
ON  REST_CY.BRAND_ID = od.BRAND_ID
AND REST_CY.STORE_ID = od.STORE_ID
AND REST_CY.ORDER_DT = od.ORDER_DT
ORDER BY
    MDM_PRODUCT_ID
    , BUSINESS_DT
    , BRAND
    , STORE_NBR

';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_PRODUCT_SALES_MAIN_V_X("FROMDATE" DATE, "TODATE" DATE)
RETURNS TABLE ("AGG_LEVEL" VARCHAR(16777216), "BUSINESS_DT" VARCHAR(16777216), "BRAND" VARCHAR(16777216), "BRAND_ID" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "MDM_PRODUCT_ID" NUMBER(38,0), "PRODUCT_SALES_CY" FLOAT, "PRODUCT_CNT_CY" NUMBER(38,0), "CHECK_SALES_CY" FLOAT, "CHECK_CNT_CY" NUMBER(38,0), "REST_SALES_CY" FLOAT, "REST_TRANS_CY" NUMBER(38,0), "FISC_DATE_LY" DATE, "CAL_COMP_DATE_LY" DATE, "MDM_PRODUCT_NM" VARCHAR(16777216), "PRODUCT_HIERARCHY_ID" NUMBER(38,0), "LEVEL5_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL4_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL3_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL2_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL1_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "PRODUCT_MISC1" VARCHAR(16777216), "PRODUCT_MISC2" VARCHAR(16777216), "PRODUCT_MISC3" VARCHAR(16777216), "PRODUCT_MISC4" VARCHAR(16777216), "PRODUCT_MISC5" VARCHAR(16777216), "PRODUCT_MISC6" VARCHAR(16777216), "PRODUCT_MISC7" VARCHAR(16777216), "PRODUCT_MISC8" VARCHAR(16777216), "PRODUCT_MISC9" VARCHAR(16777216), "PRODUCT_MISC10" VARCHAR(16777216))
LANGUAGE SQL
AS '


WITH ORDER_DETAIL_V AS
(
SELECT
    od.*
FROM
    IDH_QA.SALES.ORDER_DETAIL_SUBSET_V /*IDS_DEV.DATASTORE.ORDER_DETAIL_SUBSET_TBL*//*ORDER_DETAIL_SUBSET_V*/ od /*for UAT should be replaced with ORDER_DETAIL_V*/
WHERE
    IFNULL((CASE WHEN UPPER(CAST(VOIDED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(VOIDED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND IFNULL((CASE WHEN UPPER(CAST(CLEARED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(CLEARED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND IFNULL((CASE WHEN UPPER(CAST(DELETED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(DELETED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND od.ORDER_DT BETWEEN FromDate AND ToDate
)

, CHECK_CY AS 
(
SELECT
    src.BRAND_ID
    , src.STORE_ID
    , src.MDM_PRODUCT_ID
    , src.ORDER_DT
    , SUM(src.CHECK_SALES_CY) AS CHECK_SALES_CY
    , COUNT(DISTINCT ORDER_ID) AS CHECK_CNT_CY
FROM
(
    SELECT
        od.ORDER_ID
        , od.BRAND_ID
        , od.STORE_ID
        , IFNULL(od.MDM_PRODUCT_ID, 0) AS MDM_PRODUCT_ID
        , od.ORDER_DT
        , SUM(DERIVED_NET_AMT) OVER(PARTITION BY od.ORDER_ID) AS CHECK_SALES_CY
    FROM
        ORDER_DETAIL_V od
    WHERE
        od.MDM_ITEM_TYP = ''Product''
) src
GROUP BY
    src.BRAND_ID
    , src.STORE_ID
    , src.MDM_PRODUCT_ID
    , src.ORDER_DT
)

, REST_CY AS
(
SELECT
    od.BRAND_ID
    , od.STORE_ID
    , od.ORDER_DT
    , SUM(DERIVED_NET_AMT) AS REST_SALES_CY
    , COUNT(DISTINCT od.ORDER_ID) AS REST_TRANS_CY
FROM
    ORDER_DETAIL_V od
GROUP BY
    od.BRAND_ID
    , od.STORE_ID
    , od.ORDER_DT
)

SELECT
    ''DAY'' AS AGG_LEVEL
    , od.ORDER_DT AS BUSINESS_DT
    , CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
         WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
         WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
         WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
         WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
         WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
         WHEN od.BRAND_ID = ''rto'' THEN ''RT''
         ELSE ''UNKNOWN'' END AS BRAND
    , od.BRAND_ID
    , od.STORE_ID AS STORE_NBR
    , od.MDM_PRODUCT_ID AS MDM_PRODUCT_ID

    , od.PRODUCT_SALES_CY
    , od.PRODUCT_CNT_CY
    , CHECK_CY.CHECK_SALES_CY
    , CHECK_CY.CHECK_CNT_CY
    , REST_CY.REST_SALES_CY
    , REST_CY.REST_TRANS_CY
  
    , dd.FISCAL_COMPARABLE_DT AS FISC_DATE_LY
    , dd.CALENDAR_COMPARABLE_DT AS CAL_COMP_DATE_LY
  
    , od.MDM_PRODUCT_NM AS MDM_PRODUCT_NM
    , od.PRODUCT_HIERARCHY_ID AS PRODUCT_HIERARCHY_ID
    , od.LEVEL5_PRODUCT_HIERARCHY_NM AS LEVEL5_PRODUCT_HIERARCHY_NM
    , od.LEVEL4_PRODUCT_HIERARCHY_NM AS LEVEL4_PRODUCT_HIERARCHY_NM
    , od.LEVEL3_PRODUCT_HIERARCHY_NM AS LEVEL3_PRODUCT_HIERARCHY_NM
    , od.LEVEL2_PRODUCT_HIERARCHY_NM AS LEVEL2_PRODUCT_HIERARCHY_NM
    , od.LEVEL1_PRODUCT_HIERARCHY_NM AS LEVEL1_PRODUCT_HIERARCHY_NM
    , od.PRODUCT_MISC1 AS PRODUCT_MISC1
    , od.PRODUCT_MISC2 AS PRODUCT_MISC2
    , od.PRODUCT_MISC3 AS PRODUCT_MISC3
    , od.PRODUCT_MISC4 AS PRODUCT_MISC4
    , od.PRODUCT_MISC5 AS PRODUCT_MISC5
    , od.PRODUCT_MISC6 AS PRODUCT_MISC6
    , od.PRODUCT_MISC7 AS PRODUCT_MISC7
    , od.PRODUCT_MISC8 AS PRODUCT_MISC8
    , od.PRODUCT_MISC9 AS PRODUCT_MISC9
    , od.PRODUCT_MISC10 AS PRODUCT_MISC10

FROM
    (
    SELECT
        odv.ORDER_DT
        , ORDER_DT_KEY
        , odv.STORE_ID
        , odv.BRAND_ID
        , IFNULL(odv.MDM_PRODUCT_ID, 0) AS MDM_PRODUCT_ID
        , odv.PRODUCT_NM AS MDM_PRODUCT_NM
        , odv.PRODUCT_HIERARCHY_ID
        , odv.LEVEL5_PRODUCT_HIERARCHY_NM
        , odv.LEVEL4_PRODUCT_HIERARCHY_NM
        , odv.LEVEL3_PRODUCT_HIERARCHY_NM
        , odv.LEVEL2_PRODUCT_HIERARCHY_NM
        , odv.LEVEL1_PRODUCT_HIERARCHY_NM
        , odv.PRODUCT_MISC1
        , odv.PRODUCT_MISC2
        , odv.PRODUCT_MISC3
        , odv.PRODUCT_MISC4
        , odv.PRODUCT_MISC5
        , odv.PRODUCT_MISC6
        , odv.PRODUCT_MISC7
        , odv.PRODUCT_MISC8
        , odv.PRODUCT_MISC9
        , odv.PRODUCT_MISC10
        
        , SUM(DERIVED_NET_AMT) AS PRODUCT_SALES_CY
        , SUM(DERIVED_GROSS_QTY) AS PRODUCT_CNT_CY
    FROM
        ORDER_DETAIL_V odv
    WHERE
        odv.MDM_ITEM_TYP = ''Product''
    GROUP BY
        odv.ORDER_DT
        , ORDER_DT_KEY
        , odv.STORE_ID
        , odv.BRAND_ID
        , IFNULL(odv.MDM_PRODUCT_ID, 0)
      
        , odv.PRODUCT_NM
        , odv.PRODUCT_HIERARCHY_ID
        , odv.LEVEL5_PRODUCT_HIERARCHY_NM
        , odv.LEVEL4_PRODUCT_HIERARCHY_NM
        , odv.LEVEL3_PRODUCT_HIERARCHY_NM
        , odv.LEVEL2_PRODUCT_HIERARCHY_NM
        , odv.LEVEL1_PRODUCT_HIERARCHY_NM
        , odv.PRODUCT_MISC1
        , odv.PRODUCT_MISC2
        , odv.PRODUCT_MISC3
        , odv.PRODUCT_MISC4
        , odv.PRODUCT_MISC5
        , odv.PRODUCT_MISC6
        , odv.PRODUCT_MISC7
        , odv.PRODUCT_MISC8
        , odv.PRODUCT_MISC9
        , odv.PRODUCT_MISC10
    ) od
INNER JOIN
    IDH_QA.SHARED.DATE_DIM_V dd
ON  dd.CALENDAR_DT = od.ORDER_DT
LEFT OUTER JOIN
    CHECK_CY
ON  CHECK_CY.BRAND_ID = od.BRAND_ID
AND CHECK_CY.STORE_ID = od.STORE_ID
AND CHECK_CY.MDM_PRODUCT_ID = od.MDM_PRODUCT_ID
AND CHECK_CY.ORDER_DT = od.ORDER_DT
LEFT OUTER JOIN
    REST_CY
ON  REST_CY.BRAND_ID = od.BRAND_ID
AND REST_CY.STORE_ID = od.STORE_ID
AND REST_CY.ORDER_DT = od.ORDER_DT
ORDER BY
    MDM_PRODUCT_ID
    , BUSINESS_DT
    , BRAND
    , STORE_NBR

';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_PRODUCT_SALES_SS("FROMDATE" DATE, "TODATE" DATE)
RETURNS TABLE ("BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "MDM_PRODUCT_ID" NUMBER(38,0), "FISC_DATE_LY" DATE, "FISC_PRODUCT_SALES_LY" NUMBER(38,2), "FISC_PRODUCT_CNT_LY" NUMBER(38,0), "FISC_CHECK_SALES_LY" NUMBER(38,2), "FISC_CHECK_CNT_LY" NUMBER(38,0), "FISC_REST_SALES_LY" NUMBER(38,2), "FISC_REST_TRANS_LY" NUMBER(38,0))
LANGUAGE SQL
AS '

WITH date_interval AS
(
    SELECT 
        MIN(FISCAL_COMPARABLE_DT) AS MIN_FISCAL_COMPARABLE_DT
        , MAX(FISCAL_COMPARABLE_DT) AS MAX_FISCAL_COMPARABLE_DT 
FROM 
        IDH_DEV.SHARED.DATE_DIM_V dd 
WHERE 
    CALENDAR_DT BETWEEN FromDate AND ToDate
)
, src_fisc_period AS
(
    SELECT
        od.ORDER_ID
      , od.ORDERLINE_ID
      , od.ORDER_DT AS BUSINESS_DT
      , od.STORE_ID
      , od.MDM_PRODUCT_ID
      , DERIVED_GROSS_QTY
      , DERIVED_NET_AMT
      , od.BRAND_ID
      , od.LOAD_DT
      , od.LAST_UPDATED_DTTM
      , ORDER_DT AS FISCAL_COMPARABLE_DT
      , ROW_NUMBER() OVER (PARTITION BY ORDER_ID, ORDERLINE_ID, STORE_ID, ORDER_DT ORDER BY ORDER_ID, ORDERLINE_ID, STORE_ID, ORDER_DT, LAST_UPDATED_DTTM DESC, DERIVED_NET_AMT DESC, IFNULL(MDM_PARENT_ITEM_ID, 0) DESC) as Rn
    FROM
        ORDER_DETAIL_V od
    WHERE
        IFNULL((CASE WHEN UPPER(CAST(VOIDED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(VOIDED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND IFNULL((CASE WHEN UPPER(CAST(CLEARED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(CLEARED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND IFNULL((CASE WHEN UPPER(CAST(DELETED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(DELETED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND MDM_PRODUCT_ID IS NOT NULL
    AND od.ORDER_DT BETWEEN (SELECT MIN_FISCAL_COMPARABLE_DT FROM date_interval) AND (SELECT MAX_FISCAL_COMPARABLE_DT FROM date_interval)
)
, src_fisc_period_prel AS
(
    SELECT
        od.ORDER_ID
      , od.ORDERLINE_ID
      , od.BUSINESS_DT
      , od.STORE_ID AS STORE_NBR
      , od.MDM_PRODUCT_ID
      , DERIVED_GROSS_QTY
      , DERIVED_NET_AMT
      , od.FISCAL_COMPARABLE_DT AS FISC_DATE_LY
      , CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
           WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
           WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
           WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
           WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
           WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
           WHEN od.BRAND_ID = ''rto'' THEN ''RT''
           ELSE ''UNKNOWN'' END AS BRAND
      , od.LOAD_DT
      , od.LAST_UPDATED_DTTM
    FROM
        src_fisc_period od
    WHERE
        od.Rn = 1
)
, src_fisc_period_dist AS
(
    SELECT
        ORDER_ID
      , BRAND
      , STORE_NBR
      , MDM_PRODUCT_ID
      , FISC_DATE_LY
      , IFNULL(DERIVED_GROSS_QTY, 0) AS DERIVED_GROSS_QTY
      , DERIVED_NET_AMT AS DERIVED_NET_AMT
    FROM
        src_fisc_period_prel
)
, src_fisc_period_dist_chk AS
(
    SELECT
        ORDER_ID
      , BRAND
      , STORE_NBR
      , MDM_PRODUCT_ID
      , FISC_DATE_LY
      , DERIVED_GROSS_QTY
      , DERIVED_NET_AMT AS DERIVED_NET_AMT
      , SUM(DERIVED_NET_AMT) OVER(PARTITION BY ORDER_ID) AS FISC_CHECK_SALES_LY
      , ROW_NUMBER() OVER(PARTITION BY ORDER_ID, FISC_DATE_LY, BRAND, STORE_NBR, MDM_PRODUCT_ID ORDER BY ORDER_ID) AS Rn
    FROM
        src_fisc_period_prel
)

SELECT
    s.BRAND
    , s.STORE_NBR
    , s.MDM_PRODUCT_ID
    , s.FISC_DATE_LY
    , SUM(DERIVED_NET_AMT) AS FISC_PRODUCT_SALES_LY
    , MAX(tot.FISC_PRODUCT_CNT_LY) AS FISC_PRODUCT_CNT_LY
    , MAX(chk.FISC_CHECK_SALES_LY) AS FISC_CHECK_SALES_LY
    , MAX(chk.FISC_CHECK_CNT_LY) AS FISC_CHECK_CNT_LY
    , MAX(tot.FISC_REST_SALES_LY) AS FISC_REST_SALES_LY
    , MAX(tot.FISC_REST_TRANS_LY) AS FISC_REST_TRANS_LY
FROM
    src_fisc_period_dist_chk s
LEFT OUTER JOIN
(
    SELECT
      BRAND
      , STORE_NBR
      , MDM_PRODUCT_ID
      , FISC_DATE_LY
      , SUM(FISC_CHECK_SALES_LY) AS FISC_CHECK_SALES_LY
      , SUM(Rn) AS FISC_CHECK_CNT_LY
    FROM
        src_fisc_period_dist_chk
    WHERE
        Rn = 1
    GROUP BY
        BRAND
      , STORE_NBR
      , MDM_PRODUCT_ID
      , FISC_DATE_LY
) chk
ON  s.BRAND = chk.BRAND
AND s.STORE_NBR = chk.STORE_NBR
AND s.MDM_PRODUCT_ID = chk.MDM_PRODUCT_ID
AND s.FISC_DATE_LY = chk.FISC_DATE_LY
LEFT OUTER JOIN
(
    SELECT
      BRAND
      , STORE_NBR
      , FISC_DATE_LY
      , SUM(DERIVED_NET_AMT) AS FISC_REST_SALES_LY
      , COUNT(DISTINCT ORDER_ID) AS FISC_REST_TRANS_LY
      , COUNT(DISTINCT MDM_PRODUCT_ID) AS FISC_PRODUCT_CNT_LY
    FROM
        src_fisc_period_dist_chk
    GROUP BY
        BRAND
      , STORE_NBR
      , FISC_DATE_LY
) tot
ON  s.BRAND = chk.BRAND
AND s.STORE_NBR = chk.STORE_NBR
AND s.FISC_DATE_LY = chk.FISC_DATE_LY
GROUP BY
    s.BRAND
    , s.STORE_NBR
    , s.MDM_PRODUCT_ID
    , s.FISC_DATE_LY
ORDER BY s.STORE_NBR, MDM_PRODUCT_ID  

';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_PRODUCT_SALES_SS_FISC("FROMDATE" DATE, "TODATE" DATE)
RETURNS TABLE ("AGG_LEVEL" VARCHAR(16777216), "BUSINESS_DT" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_CD" VARCHAR(16777216), "DMA_NM" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "DAY_OF_WEEK" VARCHAR(16777216), "HOLIDAY_IND_CY" BOOLEAN, "HOLIDAY_NM_CY" VARCHAR(16777216), "MDM_PRODUCT_ID" NUMBER(38,0), "MDM_PRODUCT_NM" VARCHAR(16777216), "PRODUCT_HIERARCHY_ID" NUMBER(38,0), "LEVEL5_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL4_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL3_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL2_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL1_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "PRODUCT_MISC1" VARCHAR(16777216), "PRODUCT_MISC2" VARCHAR(16777216), "PRODUCT_MISC3" VARCHAR(16777216), "PRODUCT_MISC4" VARCHAR(16777216), "PRODUCT_MISC5" VARCHAR(16777216), "PRODUCT_MISC6" VARCHAR(16777216), "PRODUCT_MISC7" VARCHAR(16777216), "PRODUCT_MISC8" VARCHAR(16777216), "PRODUCT_MISC9" VARCHAR(16777216), "PRODUCT_MISC10" VARCHAR(16777216), "PRODUCT_SALES_CY" NUMBER(38,2), "PRODUCT_CNT_CY" NUMBER(38,0), "CHECK_SALES_CY" NUMBER(38,2), "CHECK_CNT_CY" NUMBER(38,0), "REST_SALES_CY" NUMBER(38,2), "REST_TRANS_CY" NUMBER(38,0), "FISC_DATE_LY" DATE, "FISC_HOLIDAY_IND_LY" BOOLEAN, "FISC_HOLIDAY_NM_LY" VARCHAR(16777216), "CAL_COMP_DATE_LY" DATE, "CAL_HOLIDAY_IND_LY" BOOLEAN, "CAL_HOLIDAY_NM_LY" VARCHAR(16777216))
LANGUAGE SQL
AS '

SELECT 
    * 
FROM 
    TABLE(INSPIRE_DAILY_PRODUCT_SALES_SS(FromDate, ToDate))
  
';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_PRODUCT_SALES_TEST("STARTDATE" DATE, "ENDDATE" DATE)
RETURNS TABLE ("BUSINESS_DT" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_CD" VARCHAR(16777216), "DMA_NM" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "DAY_OF_WEEK" VARCHAR(16777216), "HOLIDAY_IND_CY" VARCHAR(16777216), "HOLIDAY_NM_CY" VARCHAR(16777216), "MDM_PRODUCT_ID" NUMBER(38,0), "MDM_PRODUCT_NM" VARCHAR(16777216), "DISCOUNT_AMT_CY" FLOAT, "PRODUCT_CNT_CY" NUMBER(38,0), "CHECK_SALES_CY" FLOAT, "CHECK_CNT_CY" NUMBER(38,0), "REST_SALES_CY" FLOAT, "REST_TRANS_CY" NUMBER(38,0), "FISC_DATE_LY" DATE, "FISC_HOLIDAY_IND_LY" VARCHAR(16777216), "FISC_HOLIDAY_NM_LY" VARCHAR(16777216), "FISC_DISCOUNT_AMT_LY" FLOAT, "FISC_PRODUCT_CNT_LY" NUMBER(38,0), "FISC_CHECK_SALES_LY" FLOAT, "FISC_CHECK_CNT_LY" NUMBER(38,0), "FISC_REST_SALES_LY" FLOAT, "FISC_REST_TRANS_LY" NUMBER(38,0), "CAL_COMP_DATE_LY" DATE, "CAL_HOLIDAY_IND_LY" VARCHAR(16777216), "CAL_HOLIDAY_NM_LY" VARCHAR(16777216), "CAL_DISCOUNT_AMT_LY" FLOAT, "CAL_PRODUCT_CNT_LY" NUMBER(38,0), "CAL_CHECK_SALES_LY" FLOAT, "CAL_CHECK_CNT_LY" NUMBER(38,0), "CAL_REST_SALES_LY" FLOAT, "CAL_REST_TRANS_LY" NUMBER(38,0), "PRODUCT_HIERARCHY_ID" NUMBER(38,0), "LEVEL5_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL4_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL3_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL2_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL1_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "PRODUCT_MISC1" VARCHAR(16777216), "PRODUCT_MISC2" VARCHAR(16777216), "PRODUCT_MISC3" VARCHAR(16777216), "PRODUCT_MISC4" VARCHAR(16777216), "PRODUCT_MISC5" VARCHAR(16777216), "PRODUCT_MISC6" VARCHAR(16777216), "PRODUCT_MISC7" VARCHAR(16777216), "PRODUCT_MISC8" VARCHAR(16777216), "PRODUCT_MISC9" VARCHAR(16777216), "PRODUCT_MISC10" VARCHAR(16777216))
LANGUAGE SQL
AS '

    WITH 
    get_dates AS (
        SELECT DISTINCT  
              CALENDAR_DT
            , CALENDAR_DAY_NM  
            , FISCAL_1YR_COMP_DT
            , CALENDAR_1YR_COMP_DT
            , FISCAL_WEEK_NBR
            , FISCAL_YEAR_NBR
            , FISCAL_QUARTER_NBR
            , FISCAL_PERIOD_NBR
            , FISCAL_1YR_COMP_YEAR_DT
            , CALENDAR_1YR_COMP_YEAR_DT
            , iff(nvl(hol.HOLIDAY_IND, false), ''Y'', ''N'')         as HOLIDAY_IND_CY
            , hol.HOLIDAY_LIST_NM                                as HOLIDAY_NM_CY
            , iff(nvl(hol_fly.HOLIDAY_IND, false), ''Y'', ''N'')     as FISC_HOLIDAY_IND_LY
            , hol_fly.HOLIDAY_LIST_NM                            as FISC_HOLIDAY_NM_LY
            , iff(nvl(hol_cly.HOLIDAY_IND, false), ''Y'', ''N'')     as CAL_HOLIDAY_IND_LY
            , hol_cly.HOLIDAY_LIST_NM                            as CAL_HOLIDAY_NM_LY
        FROM 
        IDS_QA.INT_REF.COMP_CALENDAR dt
        LEFT OUTER JOIN IDH_QA.SHARED.HOLIDAY_LIST_V as hol
        ON dt.DATE_KEY = hol.DATE_KEY
        LEFT OUTER JOIN IDH_QA.SHARED.HOLIDAY_LIST_V as hol_fly
        ON dt.FISCAL_1YR_DATE_KEY = hol_fly.DATE_KEY
        LEFT OUTER JOIN IDH_QA.SHARED.HOLIDAY_LIST_V as hol_cly
        ON dt.CALENDAR_1YR_DATE_KEY = hol_cly.DATE_KEY
        where CALENDAR_DT between startDate and endDate
    )    
    , get_stores as (
        SELECT DISTINCT
              dt.CALENDAR_DT
            , dt.CALENDAR_DAY_NM  
            , dt.FISCAL_1YR_COMP_DT as FISC_DATE_LY
            , dt.CALENDAR_1YR_COMP_DT as CAL_COMP_DATE_LY  
            , dt.FISCAL_WEEK_NBR
            , dt.FISCAL_YEAR_NBR
            , dt.FISCAL_QUARTER_NBR
            , dt.FISCAL_PERIOD_NBR
            , dt.HOLIDAY_IND_CY
            , dt.HOLIDAY_NM_CY
            , dt.FISC_HOLIDAY_IND_LY
            , dt.FISC_HOLIDAY_NM_LY
            , dt.CAL_HOLIDAY_IND_LY
            , dt.CAL_HOLIDAY_NM_LY
            , st.store_id
            , st.brand_id
            , ssv.DMA_CD
            , ssv.DMA_NM
            , ssv.CLOSURE_DT
            , ssv.OWNERSHIP_TYP
            , ssv.STATE_NM as STATE
            , ssv.COUNTRY_NM as COUNTRY
            , odv.MDM_PRODUCT_ID
            , odv.PRODUCT_NM
            , lhv.LEVEL1_NM as L1NAME
            , lhv.LEVEL2_NM as L2NAME
            , lhv.LEVEL3_NM as L3NAME
            , lhv.LEVEL4_NM as L4NAME
            , lhv.LEVEL5_NM as L5NAME
            
         FROM 
            get_dates dt
            INNER JOIN IDH_QA.SHARED.STORE_SCD_PROD_V st
                ON st.CURRENT_IND = 1 
                AND nvl(st.CLOSURE_DT,''9999-01-01'') >= least(dt.FISCAL_1YR_COMP_YEAR_DT,dt.CALENDAR_1YR_COMP_YEAR_DT)
                AND st.COUNTRY_NM IN (''US'', ''USA'')
            INNER JOIN IDH_QA.SALES.ORDER_DETAIL_SUBSET_V odv
                ON st.brand_id = odv.brand_id
                AND st.STORE_ID = odv.STORE_ID
                AND odv.MDM_ITEM_TYP = ''Product''  
                AND odv.MDM_PRODUCT_ID IS NOT NULL  
           LEFT OUTER JOIN IDH_QA.SHARED.STORE_SCD_PROD_V ssv    
                ON st.brand_id = ssv.brand_id
                AND st.STORE_ID = ssv.STORE_ID
                AND dt.calendar_dt BETWEEN ssv.EFFECTIVE_BEGIN_DT AND ssv.EFFECTIVE_END_DT
                AND ssv.COUNTRY_NM IN (''US'', ''USA'')
            LEFT JOIN IDH_QA.OPERATION.LOCATION_HIERARCHY_V lhv
                ON lhv.LOCATION_ID = st.STORE_ID
                AND lhv.BRAND_ID = st.BRAND_ID

    )
    , result as (
        SELECT DISTINCT
            st.CALENDAR_DT as BUSINESS_DT
            , CASE 
                WHEN st.BRAND_ID = ''arbys'' THEN ''ARB''
                WHEN st.BRAND_ID = ''sonic'' THEN ''SON''
                WHEN st.BRAND_ID = ''bww'' THEN ''BWW''
                WHEN st.BRAND_ID = ''jj'' THEN ''JJ''
                WHEN st.BRAND_ID = ''dnkn'' THEN ''DUN''
                WHEN st.BRAND_ID = ''bskn'' THEN ''BR''
                WHEN st.BRAND_ID = ''rto'' THEN ''RT''
                ELSE ''UNKNOWN'' 
            END AS BRAND
            , st.STORE_ID as STORE_NBR
            , st.DMA_CD
            , st.DMA_NM
            , st.L1NAME
            , st.L2NAME
            , st.L3NAME
            , st.L4NAME
            , st.L5NAME
            , st.OWNERSHIP_TYP
            , st.STATE
            , st.COUNTRY
            , st.FISCAL_YEAR_NBR
            , st.FISCAL_QUARTER_NBR
            , st.FISCAL_PERIOD_NBR
            , st.FISCAL_WEEK_NBR
            , st.CALENDAR_DAY_NM as DAY_OF_WEEK
            , st.HOLIDAY_IND_CY
            , st.HOLIDAY_NM_CY
            , st.MDM_PRODUCT_ID
            , st.PRODUCT_NM as MDM_PRODUCT_NM

            -- current year
            , ifnull(odv.DISCOUNT_AMT, 0.00) as DISCOUNT_AMT_CY
            , ifnull(odv.PRODUCT_CNT,0) as PRODUCT_CNT_CY
            , ifnull(odv.CHECK_SALES, 0.00) as CHECK_SALES_CY
            , ifnull(odv.CHECK_CNT,0) as CHECK_CNT_CY
            , ifnull(odv.REST_SALES, 0.00) as REST_SALES_CY
            , ifnull(odv.REST_TRANS,0) as REST_TRANS_CY

            -- fiscal year
            , st.FISC_DATE_LY
            , st.FISC_HOLIDAY_IND_LY
            , st.FISC_HOLIDAY_NM_LY
            , ifnull(fisc_odv.DISCOUNT_AMT, 0.00) as FISC_DISCOUNT_AMT_LY
            , ifnull(fisc_odv.PRODUCT_CNT,0) as FISC_PRODUCT_CNT_LY
            , ifnull(fisc_odv.CHECK_SALES, 0.00) as FISC_CHECK_SALES_LY
            , ifnull(fisc_odv.CHECK_CNT,0) as FISC_CHECK_CNT_LY
            , ifnull(fisc_odv.REST_SALES, 0.00) as FISC_REST_SALES_CY
            , ifnull(fisc_odv.REST_TRANS,0) as FISC_REST_TRANS_CY

            -- calendar year
            , st.CAL_COMP_DATE_LY
            , st.CAL_HOLIDAY_IND_LY
            , st.CAL_HOLIDAY_NM_LY
            , ifnull(cal_odv.DISCOUNT_AMT, 0.00) as CAL_DISCOUNT_AMT_LY
            , ifnull(cal_odv.PRODUCT_CNT,0) as CAL_PRODUCT_CNT_LY
            , ifnull(cal_odv.CHECK_SALES, 0.00) as CAL_CHECK_SALES_LY
            , ifnull(cal_odv.CHECK_CNT,0) as CAL_CHECK_CNT_LY
            , ifnull(cal_odv.REST_SALES, 0.00) as CAL_REST_SALES_CY
            , ifnull(cal_odv.REST_TRANS,0) as CAL_REST_TRANS_CY

            , odv.PRODUCT_HIERARCHY_ID
            , odv.LEVEL5_PRODUCT_HIERARCHY_NM
            , odv.LEVEL4_PRODUCT_HIERARCHY_NM
            , odv.LEVEL3_PRODUCT_HIERARCHY_NM
            , odv.LEVEL2_PRODUCT_HIERARCHY_NM
            , odv.LEVEL1_PRODUCT_HIERARCHY_NM
            , odv.PRODUCT_MISC1
            , odv.PRODUCT_MISC2
            , odv.PRODUCT_MISC3
            , odv.PRODUCT_MISC4
            , odv.PRODUCT_MISC5
            , odv.PRODUCT_MISC6
            , odv.PRODUCT_MISC7
            , odv.PRODUCT_MISC8
            , odv.PRODUCT_MISC9
            , odv.PRODUCT_MISC10
        FROM 
            get_stores st
            LEFT OUTER JOIN TABLE(INSPIRE_DAILY_PRODUCT_SALES_INIT(startDate, endDate,''DAY'',''CY'')) odv
                ON st.brand_id = odv.brand_id
                AND st.STORE_ID = odv.STORE_ID
                AND st.calendar_dt = odv.BUSINESS_DT
                AND st.MDM_PRODUCT_ID = odv.MDM_PRODUCT_ID  
            LEFT OUTER JOIN TABLE(INSPIRE_DAILY_PRODUCT_SALES_INIT(startDate, endDate, ''DAY'',''FISC1Y'')) fisc_odv
                ON st.brand_id = fisc_odv.brand_id
                AND st.STORE_ID = fisc_odv.STORE_ID
                AND st.FISC_DATE_LY = fisc_odv.BUSINESS_DT
                AND st.MDM_PRODUCT_ID =fisc_odv.MDM_PRODUCT_ID
            LEFT OUTER JOIN TABLE(INSPIRE_DAILY_PRODUCT_SALES_INIT(startDate, endDate,''DAY'',''CAL1Y'')) cal_odv
                ON st.brand_id = cal_odv.brand_id
                AND st.STORE_ID = cal_odv.STORE_ID
                AND st.CAL_COMP_DATE_LY = cal_odv.BUSINESS_DT
                AND st.MDM_PRODUCT_ID =cal_odv.MDM_PRODUCT_ID
        WHERE
            st.COUNTRY IN (''US'', ''USA'')
    )
    SELECT * 
    FROM result 
    WHERE 
        PRODUCT_CNT_CY <> 0 
        OR FISC_PRODUCT_CNT_LY <> 0
        OR CAL_PRODUCT_CNT_LY <> 0
';
CREATE FUNCTION IF NOT EXISTS INSPIRE_DAILY_PRODUCT_SALES_TEST2("STARTDATE" DATE, "ENDDATE" DATE)
RETURNS TABLE ("BUSINESS_DT" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_CD" VARCHAR(16777216), "DMA_NM" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "DAY_OF_WEEK" VARCHAR(16777216), "HOLIDAY_IND_CY" VARCHAR(16777216), "HOLIDAY_NM_CY" VARCHAR(16777216), "MDM_PRODUCT_ID" NUMBER(38,0), "MDM_PRODUCT_NM" VARCHAR(16777216), "DISCOUNT_AMT_CY" FLOAT, "PRODUCT_CNT_CY" NUMBER(38,0), "CHECK_SALES_CY" FLOAT, "CHECK_CNT_CY" NUMBER(38,0), "REST_SALES_CY" FLOAT, "REST_TRANS_CY" NUMBER(38,0), "FISC_DATE_LY" DATE, "FISC_HOLIDAY_IND_LY" VARCHAR(16777216), "FISC_HOLIDAY_NM_LY" VARCHAR(16777216), "FISC_DISCOUNT_AMT_LY" FLOAT, "FISC_PRODUCT_CNT_LY" NUMBER(38,0), "FISC_CHECK_SALES_LY" FLOAT, "FISC_CHECK_CNT_LY" NUMBER(38,0), "FISC_REST_SALES_LY" FLOAT, "FISC_REST_TRANS_LY" NUMBER(38,0), "CAL_COMP_DATE_LY" DATE, "CAL_HOLIDAY_IND_LY" VARCHAR(16777216), "CAL_HOLIDAY_NM_LY" VARCHAR(16777216), "CAL_DISCOUNT_AMT_LY" FLOAT, "CAL_PRODUCT_CNT_LY" NUMBER(38,0), "CAL_CHECK_SALES_LY" FLOAT, "CAL_CHECK_CNT_LY" NUMBER(38,0), "CAL_REST_SALES_LY" FLOAT, "CAL_REST_TRANS_LY" NUMBER(38,0), "PRODUCT_HIERARCHY_ID" NUMBER(38,0), "LEVEL5_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL4_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL3_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL2_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL1_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "PRODUCT_MISC1" VARCHAR(16777216), "PRODUCT_MISC2" VARCHAR(16777216), "PRODUCT_MISC3" VARCHAR(16777216), "PRODUCT_MISC4" VARCHAR(16777216), "PRODUCT_MISC5" VARCHAR(16777216), "PRODUCT_MISC6" VARCHAR(16777216), "PRODUCT_MISC7" VARCHAR(16777216), "PRODUCT_MISC8" VARCHAR(16777216), "PRODUCT_MISC9" VARCHAR(16777216), "PRODUCT_MISC10" VARCHAR(16777216))
LANGUAGE SQL
AS '

    WITH 
    get_dates AS (
        SELECT DISTINCT  
              CALENDAR_DT
            , CALENDAR_DAY_NM  
            , FISCAL_1YR_COMP_DT
            , CALENDAR_1YR_COMP_DT
            , FISCAL_WEEK_NBR
            , FISCAL_YEAR_NBR
            , FISCAL_QUARTER_NBR
            , FISCAL_PERIOD_NBR
            , FISCAL_1YR_COMP_YEAR_DT
            , CALENDAR_1YR_COMP_YEAR_DT
            , iff(nvl(hol.HOLIDAY_IND, false), ''Y'', ''N'')         as HOLIDAY_IND_CY
            , hol.HOLIDAY_LIST_NM                                as HOLIDAY_NM_CY
            , iff(nvl(hol_fly.HOLIDAY_IND, false), ''Y'', ''N'')     as FISC_HOLIDAY_IND_LY
            , hol_fly.HOLIDAY_LIST_NM                            as FISC_HOLIDAY_NM_LY
            , iff(nvl(hol_cly.HOLIDAY_IND, false), ''Y'', ''N'')     as CAL_HOLIDAY_IND_LY
            , hol_cly.HOLIDAY_LIST_NM                            as CAL_HOLIDAY_NM_LY
        FROM 
        IDS_QA.INT_REF.COMP_CALENDAR dt
        LEFT OUTER JOIN IDH_QA.SHARED.HOLIDAY_LIST_V as hol
        ON dt.DATE_KEY = hol.DATE_KEY
        LEFT OUTER JOIN IDH_QA.SHARED.HOLIDAY_LIST_V as hol_fly
        ON dt.FISCAL_1YR_DATE_KEY = hol_fly.DATE_KEY
        LEFT OUTER JOIN IDH_QA.SHARED.HOLIDAY_LIST_V as hol_cly
        ON dt.CALENDAR_1YR_DATE_KEY = hol_cly.DATE_KEY
        where CALENDAR_DT between startDate and endDate
    )    
    , get_stores as (
        SELECT DISTINCT
              dt.CALENDAR_DT
            , dt.CALENDAR_DAY_NM  
            , dt.FISCAL_1YR_COMP_DT as FISC_DATE_LY
            , dt.CALENDAR_1YR_COMP_DT as CAL_COMP_DATE_LY  
            , dt.FISCAL_WEEK_NBR
            , dt.FISCAL_YEAR_NBR
            , dt.FISCAL_QUARTER_NBR
            , dt.FISCAL_PERIOD_NBR
            , dt.HOLIDAY_IND_CY
            , dt.HOLIDAY_NM_CY
            , dt.FISC_HOLIDAY_IND_LY
            , dt.FISC_HOLIDAY_NM_LY
            , dt.CAL_HOLIDAY_IND_LY
            , dt.CAL_HOLIDAY_NM_LY
            , st.store_id
            , st.brand_id
            , st.DMA_CD
            , st.DMA_NM
            , st.CLOSURE_DT
            , st.OWNERSHIP_TYP
            , st.STATE_NM as STATE
            , st.COUNTRY_NM as COUNTRY
            , odv.MDM_PRODUCT_ID
            , odv.PRODUCT_NM
            , lhv.LEVEL1_NM as L1NAME
            , lhv.LEVEL2_NM as L2NAME
            , lhv.LEVEL3_NM as L3NAME
            , lhv.LEVEL4_NM as L4NAME
            , lhv.LEVEL5_NM as L5NAME
            
         FROM 
            get_dates dt
            INNER JOIN IDH_QA.SHARED.STORE_SCD_PROD_V st
                ON dt.calendar_dt BETWEEN st.EFFECTIVE_BEGIN_DT AND st.EFFECTIVE_END_DT
                AND nvl(st.CLOSURE_DT,''9999-01-01'') >= cast(''2019-01-01'' as date)
                --least(dt.FISCAL_1YR_COMP_YEAR_DT,dt.CALENDAR_1YR_COMP_YEAR_DT)
                AND st.COUNTRY_NM IN (''US'', ''USA'')
            INNER JOIN IDH_QA.SALES.ORDER_DETAIL_SUBSET_V odv
                ON st.brand_id = odv.brand_id
                AND st.STORE_ID = odv.STORE_ID
                AND odv.MDM_ITEM_TYP = ''Product''  
                AND odv.MDM_PRODUCT_ID IS NOT NULL  
           /*LEFT OUTER JOIN IDH_QA.SHARED.STORE_SCD_PROD_V ssv    
                ON st.brand_id = ssv.brand_id
                AND st.STORE_ID = ssv.STORE_ID
                AND dt.calendar_dt BETWEEN ssv.EFFECTIVE_BEGIN_DT AND ssv.EFFECTIVE_END_DT
                AND ssv.COUNTRY_NM IN (''US'', ''USA'')*/
            LEFT JOIN IDH_QA.OPERATION.LOCATION_HIERARCHY_V lhv
                ON lhv.LOCATION_ID = st.STORE_ID
                AND lhv.BRAND_ID = st.BRAND_ID

    )
    , result as (
        SELECT DISTINCT
            st.CALENDAR_DT as BUSINESS_DT
            , CASE 
                WHEN st.BRAND_ID = ''arbys'' THEN ''ARB''
                WHEN st.BRAND_ID = ''sonic'' THEN ''SON''
                WHEN st.BRAND_ID = ''bww'' THEN ''BWW''
                WHEN st.BRAND_ID = ''jj'' THEN ''JJ''
                WHEN st.BRAND_ID = ''dnkn'' THEN ''DUN''
                WHEN st.BRAND_ID = ''bskn'' THEN ''BR''
                WHEN st.BRAND_ID = ''rto'' THEN ''RT''
                ELSE ''UNKNOWN'' 
            END AS BRAND
            , st.STORE_ID as STORE_NBR
            , st.DMA_CD
            , st.DMA_NM
            , st.L1NAME
            , st.L2NAME
            , st.L3NAME
            , st.L4NAME
            , st.L5NAME
            , st.OWNERSHIP_TYP
            , st.STATE
            , st.COUNTRY
            , st.FISCAL_YEAR_NBR
            , st.FISCAL_QUARTER_NBR
            , st.FISCAL_PERIOD_NBR
            , st.FISCAL_WEEK_NBR
            , st.CALENDAR_DAY_NM as DAY_OF_WEEK
            , st.HOLIDAY_IND_CY
            , st.HOLIDAY_NM_CY
            , st.MDM_PRODUCT_ID
            , st.PRODUCT_NM as MDM_PRODUCT_NM

            -- current year
            , ifnull(odv.DISCOUNT_AMT, 0.00) as DISCOUNT_AMT_CY
            , ifnull(odv.PRODUCT_CNT,0) as PRODUCT_CNT_CY
            , ifnull(odv.CHECK_SALES, 0.00) as CHECK_SALES_CY
            , ifnull(odv.CHECK_CNT,0) as CHECK_CNT_CY
            , ifnull(odv.REST_SALES, 0.00) as REST_SALES_CY
            , ifnull(odv.REST_TRANS,0) as REST_TRANS_CY

            -- fiscal year
            , st.FISC_DATE_LY
            , st.FISC_HOLIDAY_IND_LY
            , st.FISC_HOLIDAY_NM_LY
            , ifnull(fisc_odv.DISCOUNT_AMT, 0.00) as FISC_DISCOUNT_AMT_LY
            , ifnull(fisc_odv.PRODUCT_CNT,0) as FISC_PRODUCT_CNT_LY
            , ifnull(fisc_odv.CHECK_SALES, 0.00) as FISC_CHECK_SALES_LY
            , ifnull(fisc_odv.CHECK_CNT,0) as FISC_CHECK_CNT_LY
            , ifnull(fisc_odv.REST_SALES, 0.00) as FISC_REST_SALES_CY
            , ifnull(fisc_odv.REST_TRANS,0) as FISC_REST_TRANS_CY

            -- calendar year
            , st.CAL_COMP_DATE_LY
            , st.CAL_HOLIDAY_IND_LY
            , st.CAL_HOLIDAY_NM_LY
            , ifnull(cal_odv.DISCOUNT_AMT, 0.00) as CAL_DISCOUNT_AMT_LY
            , ifnull(cal_odv.PRODUCT_CNT,0) as CAL_PRODUCT_CNT_LY
            , ifnull(cal_odv.CHECK_SALES, 0.00) as CAL_CHECK_SALES_LY
            , ifnull(cal_odv.CHECK_CNT,0) as CAL_CHECK_CNT_LY
            , ifnull(cal_odv.REST_SALES, 0.00) as CAL_REST_SALES_CY
            , ifnull(cal_odv.REST_TRANS,0) as CAL_REST_TRANS_CY

            , odv.PRODUCT_HIERARCHY_ID
            , odv.LEVEL5_PRODUCT_HIERARCHY_NM
            , odv.LEVEL4_PRODUCT_HIERARCHY_NM
            , odv.LEVEL3_PRODUCT_HIERARCHY_NM
            , odv.LEVEL2_PRODUCT_HIERARCHY_NM
            , odv.LEVEL1_PRODUCT_HIERARCHY_NM
            , odv.PRODUCT_MISC1
            , odv.PRODUCT_MISC2
            , odv.PRODUCT_MISC3
            , odv.PRODUCT_MISC4
            , odv.PRODUCT_MISC5
            , odv.PRODUCT_MISC6
            , odv.PRODUCT_MISC7
            , odv.PRODUCT_MISC8
            , odv.PRODUCT_MISC9
            , odv.PRODUCT_MISC10
        FROM 
            get_stores st
            LEFT OUTER JOIN TABLE(INSPIRE_DAILY_PRODUCT_SALES_INIT(startDate, endDate,''DAY'',''CY'')) odv
                ON st.brand_id = odv.brand_id
                AND st.STORE_ID = odv.STORE_ID
                AND st.calendar_dt = odv.BUSINESS_DT
                AND st.MDM_PRODUCT_ID = odv.MDM_PRODUCT_ID  
            LEFT OUTER JOIN TABLE(INSPIRE_DAILY_PRODUCT_SALES_INIT(startDate, endDate, ''DAY'',''FISC1Y'')) fisc_odv
                ON st.brand_id = fisc_odv.brand_id
                AND st.STORE_ID = fisc_odv.STORE_ID
                AND st.FISC_DATE_LY = fisc_odv.BUSINESS_DT
                AND st.MDM_PRODUCT_ID =fisc_odv.MDM_PRODUCT_ID
            LEFT OUTER JOIN TABLE(INSPIRE_DAILY_PRODUCT_SALES_INIT(startDate, endDate,''DAY'',''CAL1Y'')) cal_odv
                ON st.brand_id = cal_odv.brand_id
                AND st.STORE_ID = cal_odv.STORE_ID
                AND st.CAL_COMP_DATE_LY = cal_odv.BUSINESS_DT
                AND st.MDM_PRODUCT_ID =cal_odv.MDM_PRODUCT_ID
        WHERE
            st.COUNTRY IN (''US'', ''USA'')
    )
    SELECT * 
    FROM result 
    WHERE 
        PRODUCT_CNT_CY <> 0 
        OR FISC_PRODUCT_CNT_LY <> 0
        OR CAL_PRODUCT_CNT_LY <> 0
';
CREATE FUNCTION IF NOT EXISTS INSPIRE_WEEKLY_DAYPART_ORDER_FULFILLMENT_FLASH("FISCAL_YEAR_NBR" NUMBER(38,0), "FISCAL_WEEK_FROM_NBR" NUMBER(38,0), "FISCAL_WEEK_TO_NBR" NUMBER(38,0))
RETURNS TABLE ("AGG_LEVEL" VARCHAR(16777216), "WEEK_START_DT" DATE, "WEEK_END_DT" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_CD" VARCHAR(16777216), "DMA_NM" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "ADDRESS_1" VARCHAR(16777216), "ADDRESS_2" VARCHAR(16777216), "CITY" VARCHAR(16777216), "ZIP_CODE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "CHANNEL_ID" VARCHAR(16777216), "ORDER_CHANNEL_L1" VARCHAR(16777216), "ORDER_CHANNEL_L2" VARCHAR(16777216), "ORDER_CHANNEL_L3" VARCHAR(16777216), "FULFILLMENT_CHANNEL_L1" VARCHAR(16777216), "FULFILLMENT_CHANNEL_L2" VARCHAR(16777216), "FULFILLMENT_CHANNEL_L3" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "CLOSED_HOUR" TIME(9), "IRB_DAYPART" VARCHAR(16777216), "BRAND_DAYPART" VARCHAR(16777216), "NET_SALES_CY" NUMBER(38,2), "TRANS_CY" NUMBER(38,0), "AVG_CHECK_CY" NUMBER(38,2), "COMP_SALES_CY" NUMBER(38,2), "COMP_TRANS_CY" NUMBER(38,0), "COMP_AVG_CHECK_CY" NUMBER(38,2), "FISC_WEEK_START_DT_LY" DATE, "FISC_WEEK_END_DT_LY" DATE, "FISC_NET_SALES_LY" NUMBER(38,2), "FISC_TRANS_LY" NUMBER(38,0), "FISC_AVG_CHECK_LY" NUMBER(38,2), "FISC_COMP_SALES_LY" NUMBER(38,2), "FISC_COMP_TRANS_LY" NUMBER(38,0), "FISC_COMP_AVG_CHECK_LY" NUMBER(38,2), "CAL_WEEK_START_DT_LY" DATE, "CAL_WEEK_END_DT_LY" DATE, "CAL_NET_SALES_LY" NUMBER(38,2), "CAL_TRANS_LY" NUMBER(38,0), "CAL_AVG_CHECK_LY" NUMBER(38,2), "CAL_COMP_SALES_LY" NUMBER(38,2), "CAL_COMP_TRANS_LY" NUMBER(38,0), "CAL_COMP_AVG_CHECK_LY" NUMBER(38,2), "CAL_WEEK_START_DT_2Y" DATE, "CAL_WEEK_END_DT_2Y" DATE, "CAL_NET_SALES_2Y" NUMBER(38,2), "CAL_TRANS_2Y" NUMBER(38,0), "CAL_AVG_CHECK_2Y" NUMBER(38,2), "CAL_COMP_SALES_2Y" NUMBER(38,2), "CAL_COMP_TRANS_2Y" NUMBER(38,0), "CAL_COMP_AVG_CHECK_2Y" NUMBER(38,2), "CAL_WEEK_START_DT_3Y" DATE, "CAL_WEEK_END_DT_3Y" DATE, "CAL_NET_SALES_3Y" NUMBER(38,2), "CAL_TRANS_3Y" NUMBER(38,0), "CAL_AVG_CHECK_3Y" NUMBER(38,2), "CAL_COMP_SALES_3Y" NUMBER(38,2), "CAL_COMP_TRANS_3Y" NUMBER(38,0), "CAL_COMP_AVG_CHECK_3Y" NUMBER(38,2))
LANGUAGE SQL
AS '

SELECT
    ''WEEK'' as AGG_LEVEL
    , WEEK_START_DT
    , WEEK_END_DT
    , BRAND
    , STORE_NBR
    , DMA_CODE
    , DMA_NAME
    , L1Name
    , L2Name
    , L3Name
    , L4Name
    , L5Name
    , OWNERSHIP_TYP
    , ADDRESS_1
    , ADDRESS_2
    , CITY
    , ZIP_CODE
    , STATE
    , COUNTRY
    , nvl(main.CHANNEL_ID, '''')
    , nvl(o.ORDER_CHANNEL_HIERARCHY_LEVEL1_NM, '''') as ORDER_CHANNEL_L1
    , nvl(o.ORDER_CHANNEL_HIERARCHY_LEVEL2_NM, '''') as ORDER_CHANNEL_L2
    , nvl(o.ORDER_CHANNEL_HIERARCHY_LEVEL3_NM, '''') as ORDER_CHANNEL_L3
    , nvl(o.FULFILLMENT_CHANNEL_HIERARCHY_L1_NM, '''') as FULFILLMENT_CHANNEL_L1
    , nvl(o.FULFILLMENT_CHANNEL_HIERARCHY_L2_NM, '''') as FULFILLMENT_CHANNEL_L2
    , nvl(o.FULFILLMENT_CHANNEL_HIERARCHY_L3_NM, '''') as FULFILLMENT_CHANNEL_L3
    , FISC_YEAR_NBR
    , FISC_QUARTER_NBR
    , FISC_PERIOD_NBR
    , FISC_WEEK_NBR
    , CLOSED_HOUR
    , IRB_DAYPART
    , BRAND_DAYPART

    --current year
    , NET_SALES_CY
    , TRANS_CY
    , AVG_CHECK_CY
    , COMP_SALES_CY
    , COMP_TRANS_CY
    , COMP_AVG_CHECK_CY

    --fiscal last year
    , FISC_WEEK_START_DT_LY
    , FISC_WEEK_END_DT_LY
    , FISC_NET_SALES_LY
    , FISC_TRANS_LY
    , FISC_AVG_CHECK_LY
    , FISC_COMP_SALES_LY
    , FISC_COMP_TRANS_LY
    , FISC_COMP_AVG_CHECK_LY

    --calendar last year
    , CAL_WEEK_START_DT_LY
    , CAL_WEEK_END_DT_LY
    , CAL_NET_SALES_LY
    , CAL_TRANS_LY
    , CAL_AVG_CHECK_LY
    , CAL_COMP_SALES_LY
    , CAL_COMP_TRANS_LY
    , CAL_COMP_AVG_CHECK_LY

    --calendar 2 years
    , CAL_WEEK_START_DT_2Y
    , CAL_WEEK_END_DT_2Y
    , CAL_NET_SALES_2Y
    , CAL_TRANS_2Y
    , CAL_AVG_CHECK_2Y
    , CAL_COMP_SALES_2Y
    , CAL_COMP_TRANS_2Y
    , CAL_COMP_AVG_CHECK_2Y

    --calendar 3 years
    , CAL_WEEK_START_DT_3Y
    , CAL_WEEK_END_DT_3Y
    , CAL_NET_SALES_3Y
    , CAL_TRANS_3Y
    , CAL_AVG_CHECK_3Y
    , CAL_COMP_SALES_3Y
    , CAL_COMP_TRANS_3Y
    , CAL_COMP_AVG_CHECK_3Y
FROM table(DAYPART_FLASH_SUMMARY(
            (SELECT CALENDAR_DT FROM IDH_DEV.SHARED.DATE_DIM_V dt WHERE dt.FISCAL_YEAR_NBR = FISCAL_YEAR_NBR
                and dt.FISCAL_WEEK_NBR = FISCAL_WEEK_FROM_NBR and dt.CALENDAR_DT = dt.FISCAL_WEEK_START_DT)
            , (SELECT CALENDAR_DT FROM IDH_DEV.SHARED.DATE_DIM_V dt WHERE dt.FISCAL_YEAR_NBR = FISCAL_YEAR_NBR
                and dt.FISCAL_WEEK_NBR = FISCAL_WEEK_TO_NBR and dt.CALENDAR_DT = dt.FISCAL_WEEK_END_DT)
            , ''WEEK_CHANNEL''
        )
    ) as main
LEFT JOIN ORDER_CHANNEL_V o
    on main.CHANNEL_ID = o.CHANNEL_ID
ORDER BY 
    BRAND ASC, 
    STORE_NBR ASC,
    WEEK_START_DT DESC,
    CLOSED_HOUR ASC,
    main.CHANNEL_ID
';
CREATE FUNCTION IF NOT EXISTS INSPIRE_WEEKLY_FLASH("FISCAL_YEAR_NBR" NUMBER(38,0), "FISCAL_WEEK_FROM_NBR" NUMBER(38,0), "FISCAL_WEEK_TO_NBR" NUMBER(38,0))
RETURNS TABLE ("AGG_LEVEL" VARCHAR(16777216), "WEEK_START_DT" DATE, "WEEK_END_DT" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_CD" VARCHAR(16777216), "DMA_NM" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "ADDRESS_1" VARCHAR(16777216), "ADDRESS_2" VARCHAR(16777216), "CITY" VARCHAR(16777216), "ZIP_CODE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "NET_SALES_CY" NUMBER(38,2), "TRANS_CY" NUMBER(38,0), "AVG_CHECK_CY" NUMBER(38,2), "STORE_CNT_CY" NUMBER(38,0), "COMP_SALES_CY" NUMBER(38,2), "COMP_TRANS_CY" NUMBER(38,0), "COMP_AVG_CHECK_CY" NUMBER(38,2), "COMP_STORE_CNT_CY" NUMBER(38,0), "FISC_WEEK_START_DT_LY" DATE, "FISC_WEEK_END_DT_LY" DATE, "FISC_NET_SALES_LY" NUMBER(38,2), "FISC_TRANS_LY" NUMBER(38,0), "FISC_AVG_CHECK_LY" NUMBER(38,2), "FISC_STORE_CNT_LY" NUMBER(38,0), "FISC_COMP_SALES_LY" NUMBER(38,2), "FISC_COMP_TRANS_LY" NUMBER(38,0), "FISC_COMP_AVG_CHECK_LY" NUMBER(38,2), "FISC_COMP_STORE_CNT_LY" NUMBER(38,0), "CAL_WEEK_START_DT_LY" DATE, "CAL_WEEK_END_DT_LY" DATE, "CAL_NET_SALES_LY" NUMBER(38,2), "CAL_TRANS_LY" NUMBER(38,0), "CAL_AVG_CHECK_LY" NUMBER(38,2), "CAL_STORE_CNT_LY" NUMBER(38,0), "CAL_COMP_SALES_LY" NUMBER(38,2), "CAL_COMP_TRANS_LY" NUMBER(38,0), "CAL_COMP_AVG_CHECK_LY" NUMBER(38,2), "CAL_COMP_STORE_CNT_LY" NUMBER(38,0), "CAL_WEEK_START_DT_2Y" DATE, "CAL_WEEK_END_DT_2Y" DATE, "CAL_NET_SALES_2Y" NUMBER(38,2), "CAL_TRANS_2Y" NUMBER(38,0), "CAL_AVG_CHECK_2Y" NUMBER(38,2), "CAL_STORE_CNT_2Y" NUMBER(38,0), "CAL_COMP_SALES_2Y" NUMBER(38,2), "CAL_COMP_TRANS_2Y" NUMBER(38,0), "CAL_COMP_AVG_CHECK_2Y" NUMBER(38,2), "CAL_COMP_STORE_CNT_2Y" NUMBER(38,0), "CAL_WEEK_START_DT_3Y" DATE, "CAL_WEEK_END_DT_3Y" DATE, "CAL_NET_SALES_3Y" NUMBER(38,2), "CAL_TRANS_3Y" NUMBER(38,0), "CAL_AVG_CHECK_3Y" NUMBER(38,2), "CAL_STORE_CNT_3Y" NUMBER(38,0), "CAL_COMP_SALES_3Y" NUMBER(38,2), "CAL_COMP_TRANS_3Y" NUMBER(38,0), "CAL_COMP_AVG_CHECK_3Y" NUMBER(38,2), "CAL_COMP_STORE_CNT_3Y" NUMBER(38,0))
LANGUAGE SQL
AS '

    SELECT * FROM table(INSPIRE_WEEKLY_FLASH(FISCAL_YEAR_NBR, FISCAL_WEEK_FROM_NBR, FISCAL_WEEK_TO_NBR, ''ALL''))

';
CREATE FUNCTION IF NOT EXISTS INSPIRE_WEEKLY_FLASH("FISCAL_YEAR_NBR" NUMBER(38,0), "FISCAL_WEEK_FROM_NBR" NUMBER(38,0), "FISCAL_WEEK_TO_NBR" NUMBER(38,0), "BRAND_INPUT" VARCHAR(16777216))
RETURNS TABLE ("AGG_LEVEL" VARCHAR(16777216), "WEEK_START_DT" DATE, "WEEK_END_DT" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_CD" VARCHAR(16777216), "DMA_NM" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "ADDRESS_1" VARCHAR(16777216), "ADDRESS_2" VARCHAR(16777216), "CITY" VARCHAR(16777216), "ZIP_CODE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "NET_SALES_CY" NUMBER(38,2), "TRANS_CY" NUMBER(38,0), "AVG_CHECK_CY" NUMBER(38,2), "STORE_CNT_CY" NUMBER(38,0), "COMP_SALES_CY" NUMBER(38,2), "COMP_TRANS_CY" NUMBER(38,0), "COMP_AVG_CHECK_CY" NUMBER(38,2), "COMP_STORE_CNT_CY" NUMBER(38,0), "FISC_WEEK_START_DT_LY" DATE, "FISC_WEEK_END_DT_LY" DATE, "FISC_NET_SALES_LY" NUMBER(38,2), "FISC_TRANS_LY" NUMBER(38,0), "FISC_AVG_CHECK_LY" NUMBER(38,2), "FISC_STORE_CNT_LY" NUMBER(38,0), "FISC_COMP_SALES_LY" NUMBER(38,2), "FISC_COMP_TRANS_LY" NUMBER(38,0), "FISC_COMP_AVG_CHECK_LY" NUMBER(38,2), "FISC_COMP_STORE_CNT_LY" NUMBER(38,0), "CAL_WEEK_START_DT_LY" DATE, "CAL_WEEK_END_DT_LY" DATE, "CAL_NET_SALES_LY" NUMBER(38,2), "CAL_TRANS_LY" NUMBER(38,0), "CAL_AVG_CHECK_LY" NUMBER(38,2), "CAL_STORE_CNT_LY" NUMBER(38,0), "CAL_COMP_SALES_LY" NUMBER(38,2), "CAL_COMP_TRANS_LY" NUMBER(38,0), "CAL_COMP_AVG_CHECK_LY" NUMBER(38,2), "CAL_COMP_STORE_CNT_LY" NUMBER(38,0), "CAL_WEEK_START_DT_2Y" DATE, "CAL_WEEK_END_DT_2Y" DATE, "CAL_NET_SALES_2Y" NUMBER(38,2), "CAL_TRANS_2Y" NUMBER(38,0), "CAL_AVG_CHECK_2Y" NUMBER(38,2), "CAL_STORE_CNT_2Y" NUMBER(38,0), "CAL_COMP_SALES_2Y" NUMBER(38,2), "CAL_COMP_TRANS_2Y" NUMBER(38,0), "CAL_COMP_AVG_CHECK_2Y" NUMBER(38,2), "CAL_COMP_STORE_CNT_2Y" NUMBER(38,0), "CAL_WEEK_START_DT_3Y" DATE, "CAL_WEEK_END_DT_3Y" DATE, "CAL_NET_SALES_3Y" NUMBER(38,2), "CAL_TRANS_3Y" NUMBER(38,0), "CAL_AVG_CHECK_3Y" NUMBER(38,2), "CAL_STORE_CNT_3Y" NUMBER(38,0), "CAL_COMP_SALES_3Y" NUMBER(38,2), "CAL_COMP_TRANS_3Y" NUMBER(38,0), "CAL_COMP_AVG_CHECK_3Y" NUMBER(38,2), "CAL_COMP_STORE_CNT_3Y" NUMBER(38,0))
LANGUAGE SQL
AS '

SELECT
    AGG_LEVEL
    , WEEK_START_DT
    , WEEK_END_DT
    , BRAND
    , STORE_NBR
    , DMA_CODE AS DMA_CD
    , DMA_NAME AS DMA_NM
    , L1Name
    , L2Name
    , L3Name
    , L4Name
    , L5Name
    , OWNERSHIP_TYP
    , ADDRESS_1
    , ADDRESS_2
    , CITY
    , ZIP_CODE
    , STATE
    , COUNTRY

    --current year
    , FISC_YEAR_NBR
    , FISC_QUARTER_NBR
    , FISC_PERIOD_NBR
    , FISC_WEEK_NBR
    , NET_SALES_CY
    , TRANS_CY
    , AVG_CHECK_CY
    , STORE_CNT_CY
    , COMP_SALES_CY
    , COMP_TRANS_CY
    , COMP_AVG_CHECK_CY
    , COMP_STORE_CNT_CY

    --fiscal last year
    , FISC_WEEK_START_DT_LY
    , FISC_WEEK_END_DT_LY
    , FISC_NET_SALES_LY
    , FISC_TRANS_LY
    , FISC_AVG_CHECK_LY
    , FISC_STORE_CNT_LY
    , FISC_COMP_SALES_LY
    , FISC_COMP_TRANS_LY
    , FISC_COMP_AVG_CHECK_LY
    , FISC_COMP_STORE_CNT_LY

    --calendar last year
    , CAL_WEEK_START_DT_LY
    , CAL_WEEK_END_DT_LY
    , CAL_NET_SALES_LY
    , CAL_TRANS_LY
    , CAL_AVG_CHECK_LY
    , CAL_STORE_CNT_LY
    , CAL_COMP_SALES_LY
    , CAL_COMP_TRANS_LY
    , CAL_COMP_AVG_CHECK_LY
    , CAL_COMP_STORE_CNT_LY

    --calendar 2 years
    , CAL_WEEK_START_DT_2Y
    , CAL_WEEK_END_DT_2Y
    , CAL_NET_SALES_2Y
    , CAL_TRANS_2Y
    , CAL_AVG_CHECK_2Y
    , CAL_STORE_CNT_2Y
    , CAL_COMP_SALES_2Y
    , CAL_COMP_TRANS_2Y
    , CAL_COMP_AVG_CHECK_2Y
    , CAL_COMP_STORE_CNT_2Y

    --calendar 3 years
    , CAL_WEEK_START_DT_3Y
    , CAL_WEEK_END_DT_3Y
    , CAL_NET_SALES_3Y
    , CAL_TRANS_3Y
    , CAL_AVG_CHECK_3Y
    , CAL_STORE_CNT_3Y
    , CAL_COMP_SALES_3Y
    , CAL_COMP_TRANS_3Y
    , CAL_COMP_AVG_CHECK_3Y
    , CAL_COMP_STORE_CNT_3Y
FROM table(DAYPART_FLASH_SUMMARY(
            (SELECT CALENDAR_DT FROM IDH_DEV.SHARED.DATE_DIM_V dt WHERE dt.FISCAL_YEAR_NBR = FISCAL_YEAR_NBR
                and dt.FISCAL_WEEK_NBR = FISCAL_WEEK_FROM_NBR and dt.CALENDAR_DT = dt.FISCAL_WEEK_START_DT)
            , (SELECT CALENDAR_DT FROM IDH_DEV.SHARED.DATE_DIM_V dt WHERE dt.FISCAL_YEAR_NBR = FISCAL_YEAR_NBR
                and dt.FISCAL_WEEK_NBR = FISCAL_WEEK_TO_NBR and dt.CALENDAR_DT = dt.FISCAL_WEEK_END_DT)
            , ''WEEK''
            , BRAND_INPUT
        )
    ) 
ORDER BY 
    BRAND ASC, 
    STORE_NBR ASC,
    WEEK_START_DT DESC
';
CREATE FUNCTION IF NOT EXISTS INSPIRE_WEEKLY_FLASH_SUMMARY("FROM_DATE" DATE, "TO_DATE" DATE)
RETURNS TABLE ("WEEK_START_DT" DATE, "WEEK_END_DT" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "DMA_NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "ADDRESS_1" VARCHAR(16777216), "ADDRESS_2" VARCHAR(16777216), "CITY" VARCHAR(16777216), "ZIP_CODE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "NET_SALES" NUMBER(38,2), "TRANS" NUMBER(38,0), "COMP_STORE_CNT" NUMBER(38,0), "WEEKDAY_OFFSET" ARRAY, "WEEK_TRANS_CNTS" ARRAY, "WEEK_NET_SALES" ARRAY, "IS_XMAS_THANKSGIVING" BOOLEAN)
LANGUAGE SQL
AS '

SELECT
    bdt.FISCAL_WEEK_START_DT                as WEEK_START_DT
    , bdt.FISCAL_WEEK_END_DT                as WEEK_END_DT
    , dpsf.BRAND_ID                         as BRAND
    , dpsf.STORE_ID                         as STORE_NBR
    , dpsf.DMA_CODE                         as DMA_CODE
    , dpsf.DMA_NAME                         as DMA_NAME
    , dpsf.OWNERSHIP_TYP                    as OWNERSHIP_TYP
    , dpsf.ADDRESS_1                        as ADDRESS_1
    , dpsf.ADDRESS_2                        as ADDRESS_2
    , dpsf.CITY                             as CITY
    , dpsf.ZIP_CD                           as ZIP_CODE
    , dpsf.STATE                            as STATE
    , dpsf.COUNTRY                          as COUNTRY
    , bdt.FISCAL_YEAR_NBR                   as FISC_YEAR_NBR
    , bdt.FISCAL_QUARTER_NBR                as FISC_QUARTER_NBR
    , bdt.FISCAL_PERIOD_NBR                 as FISC_PERIOD_NBR
    , bdt.FISCAL_WEEK_NBR                   as FISC_WEEK_NBR
    , nvl(sum(dpsf.Net_Sales), 0)           as NET_SALES
    , nvl(sum(
        CASE
            WHEN nvl(dpsf.Net_Sales, 0) = 0
            THEN 0
            ELSE dpsf.Trans_Cnt
        END), 0)                            as TRANS
    , CASE
        WHEN nvl(sum(dpsf.Net_Sales), 0) = 0
            and max(hol.DATE_KEY) is null
        THEN 0
        WHEN NOT max(dpsf.OPEN_AFTER_HONEYMOON_FLAG) OR NOT max(dpsf.OPEN_15P_FLAG)
        THEN 0
        ELSE 1
    END                                     as COMP_STORE_CNT
    , ARRAY_AGG(dpsf.BUSINESS_DT - bdt.FISCAL_WEEK_START_DT)
                                            as WEEKDAY_OFFSET --ODI-2977
    , ARRAY_AGG(dpsf.Trans_Cnt)             as WEEK_TRANS_CNTS --ODI-2977
    , ARRAY_AGG(dpsf.Net_Sales)             as WEEK_NET_SALES --ODI-2977
    , max(hol.DATE_KEY) is not null         as IS_XMAS_THANKSGIVING
FROM table(DAILY_DAY_PART_FLASH_SALES_V(
            FROM_DATE
            , TO_DATE
        )
    ) as dpsf
INNER JOIN IDH_DEV.SHARED.DATE_DIM_V as bdt
    on bdt.CALENDAR_DT = dpsf.BUSINESS_DT
LEFT JOIN IDH_DEV.SHARED.HOLIDAY_LIST_V as hol
    ON bdt.DATE_KEY = hol.DATE_KEY
    AND (ARRAY_CONTAINS(cast(''THANKSGIVING DAY'' as variant), split(hol.HOLIDAY_LIST_NM, '', ''))
         OR ARRAY_CONTAINS(cast(''CHRISTMAS DAY'' as variant), split(hol.HOLIDAY_LIST_NM, '', '')))
GROUP BY
    bdt.FISCAL_WEEK_START_DT
    , bdt.FISCAL_WEEK_END_DT
    , dpsf.BRAND_ID
    , dpsf.STORE_ID
    , bdt.FISCAL_YEAR_NBR
    , bdt.FISCAL_QUARTER_NBR
    , bdt.FISCAL_PERIOD_NBR
    , bdt.FISCAL_WEEK_NBR
    , dpsf.DMA_CODE
    , dpsf.DMA_NAME
    , dpsf.OWNERSHIP_TYP
    , dpsf.ADDRESS_1
    , dpsf.ADDRESS_2
    , dpsf.CITY
    , dpsf.ZIP_CD
    , dpsf.STATE
    , dpsf.COUNTRY
';
CREATE FUNCTION IF NOT EXISTS INSPIRE_WEEKLY_OFFER_SALES("FISCAL_YEAR" NUMBER(38,0), "FROM_WEEK" NUMBER(38,0), "TO_WEEK" NUMBER(38,0))
RETURNS TABLE ("FISC_WEEK_NBR" NUMBER(38,0), "WEEK_START_DT" DATE, "WEEK_END_DT" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_CD" VARCHAR(16777216), "DMA_NM" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "MDM_OFFER_ID" NUMBER(38,0), "MDM_OFFER_NM" VARCHAR(16777216), "DISCOUNT_AMT_CY" FLOAT, "OFFER_CNT_CY" NUMBER(38,0), "CHECK_SALES_CY" FLOAT, "CHECK_CNT_CY" NUMBER(38,0), "REST_SALES_CY" FLOAT, "REST_TRANS_CY" NUMBER(38,0), "FISC_WEEK_START_DT_LY" DATE, "FISC_WEEK_END_DT_LY" DATE, "FISC_DISCOUNT_AMT_LY" FLOAT, "FISC_OFFER_CNT_LY" NUMBER(38,0), "FISC_CHECK_SALES_LY" FLOAT, "FISC_CHECK_CNT_LY" NUMBER(38,0), "FISC_REST_SALES_LY" FLOAT, "FISC_REST_TRANS_LY" NUMBER(38,0), "CAL_WEEK_START_DT_LY" DATE, "CAL_WEEK_END_DT_LY" DATE, "CAL_DISCOUNT_AMT_LY" FLOAT, "CAL_OFFER_CNT_LY" NUMBER(38,0), "CAL_CHECK_SALES_LY" FLOAT, "CAL_CHECK_CNT_LY" NUMBER(38,0), "CAL_REST_SALES_LY" FLOAT, "CAL_REST_TRANS_LY" NUMBER(38,0), "OFFER_HIERARCHY_ID" VARCHAR(16777216), "LEVEL5_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL4_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL3_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL2_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL1_OFFER_HIERARCHY_NM" VARCHAR(16777216), "OFFER_MISC1" VARCHAR(16777216), "OFFER_MISC2" VARCHAR(16777216), "OFFER_MISC3" VARCHAR(16777216), "OFFER_MISC4" VARCHAR(16777216), "OFFER_MISC5" VARCHAR(16777216), "OFFER_MISC6" VARCHAR(16777216), "OFFER_MISC7" VARCHAR(16777216), "OFFER_MISC8" VARCHAR(16777216), "OFFER_MISC9" VARCHAR(16777216), "OFFER_MISC10" VARCHAR(16777216))
LANGUAGE SQL
AS '

    WITH 
    get_weeks as (
        SELECT 
              MIN(FISCAL_WEEK_START_DT) AS MIN_FISCAL_WEEK_START_DT
            , MAX(FISCAL_WEEK_END_DT) AS MAX_FISCAL_WEEK_END_DT
        FROM 
        IDH_DEV.SHARED.DATE_DIM_V dd 
        WHERE
        FISCAL_YEAR_NBR = FISCAL_YEAR
        AND FISCAL_WEEK_NBR BETWEEN FROM_WEEK AND TO_WEEK
    )
   ,get_dates AS (
        SELECT DISTINCT  
              CALENDAR_DT
            , FISCAL_WEEK_START_DT  
            , FISCAL_WEEK_END_DT
            , FISCAL_WEEK_NBR
            , FISCAL_YEAR_NBR
            , FISCAL_QUARTER_NBR
            , FISCAL_PERIOD_NBR
            , FISCAL_1YR_COMP_DT
            , FISCAL_1YR_COMP_WEEK_DT
            , FISCAL_1YR_COMP_WEEK_END_DT
            , CALENDAR_1YR_COMP_DT
            , CALENDAR_1YR_COMP_WEEK_DT
            , CALENDAR_1YR_COMP_WEEK_END_DT
            , FISCAL_1YR_COMP_YEAR_DT
            , CALENDAR_1YR_COMP_YEAR_DT
        FROM 
        IDS_DEV.INT_REF.COMP_CALENDAR 
        INNER JOIN get_weeks
        ON CALENDAR_DT between MIN_FISCAL_WEEK_START_DT and MAX_FISCAL_WEEK_END_DT
     )   
    ,ssv AS ( 
       SELECT
         STORE_ID
       , BRAND_ID
       , DMA_CD
       , DMA_NM
       , CLOSURE_DT
       , OWNERSHIP_TYP
       , STATE_NM 
       , COUNTRY_NM 
       , FISCAL_WEEK_START_DT
       , CALENDAR_DT
       FROM get_dates dt
       LEFT OUTER JOIN 
       IDH_QA.SHARED.STORE_SCD_PROD_V ssv    
       ON dt.CALENDAR_DT BETWEEN ssv.EFFECTIVE_BEGIN_DT AND ssv.EFFECTIVE_END_DT
       QUALIFY ROW_NUMBER() OVER (PARTITION BY STORE_ID, BRAND_ID, FISCAL_WEEK_START_DT  ORDER BY CALENDAR_DT DESC) = 1   
     )
    , get_stores as (
        SELECT DISTINCT
              dt.FISCAL_WEEK_START_DT  
            , dt.FISCAL_WEEK_END_DT
            , dt.FISCAL_WEEK_NBR
            , dt.FISCAL_YEAR_NBR
            , dt.FISCAL_QUARTER_NBR
            , dt.FISCAL_PERIOD_NBR
            , dt.FISCAL_1YR_COMP_WEEK_DT
            , dt.FISCAL_1YR_COMP_WEEK_END_DT
            , dt.CALENDAR_1YR_COMP_WEEK_DT
            , dt.CALENDAR_1YR_COMP_WEEK_END_DT  
            , st.store_id
            , st.brand_id
            , ssv.DMA_CD
            , ssv.DMA_NM
            , ssv.CLOSURE_DT
            , ssv.OWNERSHIP_TYP
            , ssv.STATE_NM as STATE
            , ssv.COUNTRY_NM as COUNTRY
            , odv.MDM_OFFER_ID
            , odv.OFFER_NM
            , lhv.LEVEL1_NM as L1NAME
            , lhv.LEVEL2_NM as L2NAME
            , lhv.LEVEL3_NM as L3NAME
            , lhv.LEVEL4_NM as L4NAME
            , lhv.LEVEL5_NM as L5NAME
            
         FROM 
            get_dates dt
            INNER JOIN IDH_QA.SHARED.STORE_SCD_PROD_V st
                ON st.CURRENT_IND = 1 
                AND nvl(st.CLOSURE_DT,''9999-01-01'') >= least(dt.FISCAL_1YR_COMP_YEAR_DT,dt.CALENDAR_1YR_COMP_YEAR_DT)
                AND st.COUNTRY_NM IN (''US'', ''USA'')
            INNER JOIN IDH_QA.SALES.ORDER_DETAIL_SUBSET_V odv
                ON st.brand_id = odv.brand_id
                AND st.STORE_ID = odv.STORE_ID
                AND odv.MDM_ITEM_TYP = ''Offer''  
                AND odv.MDM_OFFER_ID IS NOT NULL  
           LEFT OUTER JOIN ssv
                ON st.brand_id = ssv.brand_id
                AND st.STORE_ID = ssv.STORE_ID
                AND dt.FISCAL_WEEK_START_DT = ssv.FISCAL_WEEK_START_DT
                AND ssv.COUNTRY_NM IN (''US'', ''USA'')
            LEFT JOIN IDH_DEV.OPERATION.LOCATION_HIERARCHY_V lhv
                ON lhv.LOCATION_ID = st.STORE_ID
                AND lhv.BRAND_ID = st.BRAND_ID

    )
    , result as (
        SELECT DISTINCT
              st.FISCAL_WEEK_NBR
            , st.FISCAL_WEEK_START_DT
            , st.FISCAL_WEEK_END_DT 
            , CASE 
                WHEN st.BRAND_ID = ''arbys'' THEN ''ARB''
                WHEN st.BRAND_ID = ''sonic'' THEN ''SON''
                WHEN st.BRAND_ID = ''bww'' THEN ''BWW''
                WHEN st.BRAND_ID = ''jj'' THEN ''JJ''
                WHEN st.BRAND_ID = ''dnkn'' THEN ''DUN''
                WHEN st.BRAND_ID = ''bskn'' THEN ''BR''
                WHEN st.BRAND_ID = ''rto'' THEN ''RT''
                ELSE ''UNKNOWN'' 
            END AS BRAND
            , st.STORE_ID as STORE_NBR
            , st.DMA_CD
            , st.DMA_NM
            , st.L1NAME
            , st.L2NAME
            , st.L3NAME
            , st.L4NAME
            , st.L5NAME
            , st.OWNERSHIP_TYP
            , st.STATE
            , st.COUNTRY
            , st.FISCAL_YEAR_NBR
            , st.FISCAL_QUARTER_NBR
            , st.FISCAL_PERIOD_NBR
            , st.MDM_OFFER_ID
            , st.OFFER_NM as MDM_OFFER_NM

            -- current year
            , ifnull(odv.DISCOUNT_AMT, 0.00) as DISCOUNT_AMT_CY
            , ifnull(odv.OFFER_CNT,0) as OFFER_CNT_CY
            , ifnull(odv.CHECK_SALES, 0.00) as CHECK_SALES_CY
            , ifnull(odv.CHECK_CNT,0) as CHECK_CNT_CY
            , ifnull(odv.REST_SALES, 0.00) as REST_SALES_CY
            , ifnull(odv.REST_TRANS,0) as REST_TRANS_CY

            -- fiscal year
            , st.FISCAL_1YR_COMP_WEEK_DT
            , st.FISCAL_1YR_COMP_WEEK_END_DT as FISC_WEEK_END_DT_LY
            , ifnull(fisc_odv.DISCOUNT_AMT, 0.00) as FISC_DISCOUNT_AMT_LY
            , ifnull(fisc_odv.OFFER_CNT,0) as FISC_OFFER_CNT_LY
            , ifnull(fisc_odv.CHECK_SALES, 0.00) as FISC_CHECK_SALES_LY
            , ifnull(fisc_odv.CHECK_CNT,0) as FISC_CHECK_CNT_LY
            , ifnull(fisc_odv.REST_SALES, 0.00) as FISC_REST_SALES_CY
            , ifnull(fisc_odv.REST_TRANS,0) as FISC_REST_TRANS_CY

            -- calendar year
            , st.CALENDAR_1YR_COMP_WEEK_DT
            , st.CALENDAR_1YR_COMP_WEEK_END_DT as CAL_WEEK_END_DT_LY
            , ifnull(cal_odv.DISCOUNT_AMT, 0.00) as CAL_DISCOUNT_AMT_LY
            , ifnull(cal_odv.OFFER_CNT,0) as CAL_OFFER_CNT_LY
            , ifnull(cal_odv.CHECK_SALES, 0.00) as CAL_CHECK_SALES_LY
            , ifnull(cal_odv.CHECK_CNT,0) as CAL_CHECK_CNT_LY
            , ifnull(cal_odv.REST_SALES, 0.00) as CAL_REST_SALES_CY
            , ifnull(cal_odv.REST_TRANS,0) as CAL_REST_TRANS_CY

            , odv.OFFER_HIERARCHY_ID
            , odv.LEVEL5_OFFER_HIERARCHY_NM
            , odv.LEVEL4_OFFER_HIERARCHY_NM
            , odv.LEVEL3_OFFER_HIERARCHY_NM
            , odv.LEVEL2_OFFER_HIERARCHY_NM
            , odv.LEVEL1_OFFER_HIERARCHY_NM
            , odv.OFFER_MISC1
            , odv.OFFER_MISC2
            , odv.OFFER_MISC3
            , odv.OFFER_MISC4
            , odv.OFFER_MISC5
            , odv.OFFER_MISC6
            , odv.OFFER_MISC7
            , odv.OFFER_MISC8
            , odv.OFFER_MISC9
            , odv.OFFER_MISC10
        FROM 
            get_stores st
            LEFT OUTER JOIN TABLE(INSPIRE_DAILY_OFFER_SALES_INIT((select MIN_FISCAL_WEEK_START_DT from get_weeks), (select MAX_FISCAL_WEEK_END_DT from get_weeks),''WEEK'',''CY'')) odv
                ON st.brand_id = odv.brand_id
                AND st.STORE_ID = odv.STORE_ID
                AND st.FISCAL_WEEK_START_DT = odv.BUSINESS_DT
                AND st.MDM_OFFER_ID = odv.MDM_OFFER_ID  
            LEFT OUTER JOIN TABLE(INSPIRE_DAILY_OFFER_SALES_INIT((select MIN_FISCAL_WEEK_START_DT from get_weeks), (select MAX_FISCAL_WEEK_END_DT from get_weeks), ''WEEK'',''FISC1Y'')) fisc_odv
                ON st.brand_id = fisc_odv.brand_id
                AND st.STORE_ID = fisc_odv.STORE_ID
                AND st.FISCAL_1YR_COMP_WEEK_DT = fisc_odv.BUSINESS_DT
                AND st.MDM_OFFER_ID =fisc_odv.MDM_OFFER_ID
            LEFT OUTER JOIN TABLE(INSPIRE_DAILY_OFFER_SALES_INIT((select MIN_FISCAL_WEEK_START_DT from get_weeks), (select MAX_FISCAL_WEEK_END_DT from get_weeks),''WEEK'',''CAL1Y'')) cal_odv
                ON st.brand_id = cal_odv.brand_id
                AND st.STORE_ID = cal_odv.STORE_ID
                AND st.CALENDAR_1YR_COMP_WEEK_DT = cal_odv.BUSINESS_DT
                AND st.MDM_OFFER_ID =cal_odv.MDM_OFFER_ID
        WHERE
            st.COUNTRY IN (''US'', ''USA'')
    )
    SELECT * 
    FROM result 
    WHERE 
        OFFER_CNT_CY <> 0 
        OR FISC_OFFER_CNT_LY <> 0
        OR CAL_OFFER_CNT_LY <> 0
';
CREATE FUNCTION IF NOT EXISTS INSPIRE_WEEKLY_PRODUCT_OFFER_SALES("FISCAL_YEAR" NUMBER(38,0), "FROM_WEEK" NUMBER(38,0), "TO_WEEK" NUMBER(38,0))
RETURNS TABLE ("FISC_WEEK_NBR" NUMBER(38,0), "WEEK_START_DT" DATE, "WEEK_END_DT" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_CD" VARCHAR(16777216), "DMA_NM" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "MDM_ITEM_ID" NUMBER(38,0), "MDM_ITEM_TYP" VARCHAR(16777216), "MDM_ITEM_NM" VARCHAR(16777216), "MDM_PRODUCT_ID" NUMBER(38,0), "MDM_PRODUCT_NM" VARCHAR(16777216), "MDM_OFFER_ID" NUMBER(38,0), "MDM_OFFER_NM" VARCHAR(16777216), "PRODUCT_HIERARCHY_ID" NUMBER(38,0), "LEVEL5_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL4_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL3_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL2_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL1_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "OFFER_HIERARCHY_ID" NUMBER(38,0), "LEVEL5_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL4_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL3_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL2_OFFER_HIERARCHY_NM" VARCHAR(16777216), "LEVEL1_OFFER_HIERARCHY_NM" VARCHAR(16777216), "PRODUCT_MISC1" VARCHAR(16777216), "PRODUCT_MISC2" VARCHAR(16777216), "PRODUCT_MISC3" VARCHAR(16777216), "PRODUCT_MISC4" VARCHAR(16777216), "PRODUCT_MISC5" VARCHAR(16777216), "PRODUCT_MISC6" VARCHAR(16777216), "PRODUCT_MISC7" VARCHAR(16777216), "PRODUCT_MISC8" VARCHAR(16777216), "PRODUCT_MISC9" VARCHAR(16777216), "PRODUCT_MISC10" VARCHAR(16777216), "OFFER_MISC1" VARCHAR(16777216), "OFFER_MISC2" VARCHAR(16777216), "OFFER_MISC3" VARCHAR(16777216), "OFFER_MISC4" VARCHAR(16777216), "OFFER_MISC5" VARCHAR(16777216), "OFFER_MISC6" VARCHAR(16777216), "OFFER_MISC7" VARCHAR(16777216), "OFFER_MISC8" VARCHAR(16777216), "OFFER_MISC9" VARCHAR(16777216), "OFFER_MISC10" VARCHAR(16777216), "PRODUCT_SALES_CY" NUMBER(38,2), "DISCOUNT_AMT_CY" NUMBER(38,2), "MENU_ITEM_CNT_CY" NUMBER(38,0), "CHECK_SALES_CY" NUMBER(38,2), "CHECK_CNT_CY" NUMBER(38,0), "REST_SALES_CY" NUMBER(38,2), "REST_TRANS_CY" NUMBER(38,0), "FISC_WEEK_START_DT_LY" DATE, "FISC_WEEK_END_DT_LY" DATE, "FISC_PRODUCT_SALES_LY" NUMBER(38,2), "FISC_DISCOUNT_AMT_LY" NUMBER(38,2), "FISC_MENU_ITEM_CNT_LY" NUMBER(38,0), "FISC_CHECK_SALES_LY" NUMBER(38,2), "FISC_CHECK_CNT_LY" NUMBER(38,0), "FISC_REST_SALES_LY" NUMBER(38,2), "FISC_REST_TRANS_LY" NUMBER(38,0), "CAL_WEEK_START_DT_LY" DATE, "CAL_WEEK_END_DT_LY" DATE, "CAL_PRODUCT_SALES_LY" NUMBER(38,2), "CAL_DISCOUNT_AMT_LY" NUMBER(38,2), "CAL_MENU_ITEM_CNT_LY" NUMBER(38,0), "CAL_CHECK_SALES_LY" NUMBER(38,2), "CAL_CHECK_CNT_LY" NUMBER(38,0), "CAL_REST_SALES_LY" NUMBER(38,2), "CAL_REST_TRANS_LY" NUMBER(38,0))
LANGUAGE SQL
AS '

WITH date_interval AS
(
SELECT 
    MIN(FISCAL_WEEK_START_DT) AS MIN_FISCAL_WEEK_START_DT
    , MAX(FISCAL_WEEK_END_DT) AS MAX_FISCAL_WEEK_END_DT
FROM 
    IDH_DEV.SHARED.DATE_DIM_V dd 
WHERE
    FISCAL_YEAR_NBR = FISCAL_YEAR
    AND FISCAL_WEEK_NBR BETWEEN FROM_WEEK AND TO_WEEK
GROUP BY
    FISCAL_WEEK_NBR
)
, fisc_date_interval AS
(
SELECT 
    MIN(FISCAL_COMPARABLE_DT) AS MIN_FISCAL_COMPARABLE_DT
    , MAX(FISCAL_COMPARABLE_DT) AS MAX_FISCAL_COMPARABLE_DT 
FROM 
    IDH_DEV.SHARED.DATE_DIM_V dd 
WHERE 
    CALENDAR_DT BETWEEN (SELECT MIN(MIN_FISCAL_WEEK_START_DT) FROM date_interval) AND (SELECT MAX(MAX_FISCAL_WEEK_END_DT) FROM date_interval)
)
, cal_date_interval AS
(
SELECT 
    MIN(CALENDAR_COMPARABLE_DT) AS MIN_CAL_COMPARABLE_DT
    , MAX(CALENDAR_COMPARABLE_DT) AS MAX_CAL_COMPARABLE_DT 
FROM 
    IDH_DEV.SHARED.DATE_DIM_V dd 
WHERE 
    CALENDAR_DT BETWEEN (SELECT MIN(MIN_FISCAL_WEEK_START_DT) FROM date_interval) AND (SELECT MAX(MAX_FISCAL_WEEK_END_DT) FROM date_interval)
)

, CY_trans AS 
(
SELECT
    od.STORE_ID AS STORE_NBR
    , CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
         WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
         WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
         WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
         WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
         WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
         WHEN od.BRAND_ID = ''rto'' THEN ''RT''
         ELSE ''UNKNOWN'' END AS BRAND
    , dd.FISCAL_WEEK_NBR AS FISC_WEEK_NBR
    , dd.FISCAL_WEEK_START_DT AS FISC_WEEK_START_DT
    , dd.FISCAL_WEEK_END_DT AS FISC_WEEK_END_DT
    , SUM(od.DERIVED_NET_AMT) AS REST_SALES_CY
    , COUNT(DISTINCT od.ORDER_ID) AS REST_TRANS_CY
FROM
    ORDER_DETAIL_V od
INNER JOIN
    IDH_DEV.SHARED.DATE_DIM_V dd
ON  od.ORDER_DT = dd.CALENDAR_DT
INNER JOIN
    IDH_DEV.SHARED.STORE_SCD_V st
ON  st.STORE_ID = od.STORE_ID
AND st.BRAND_ID = od.BRAND_ID
AND od.ORDER_DT BETWEEN st.EFFECTIVE_BEGIN_DT AND st.EFFECTIVE_END_DT
AND IFNULL(st.CLOSURE_DT, ''9999-12-31'') >= (SELECT MIN(MIN_FISCAL_WEEK_START_DT) FROM date_interval)
AND st.COUNTRY_NM IN (''US'', ''USA'')
WHERE
    IFNULL((CASE WHEN UPPER(CAST(VOIDED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(VOIDED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND IFNULL((CASE WHEN UPPER(CAST(CLEARED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(CLEARED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND IFNULL((CASE WHEN UPPER(CAST(DELETED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(DELETED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND od.ORDER_DT BETWEEN (SELECT MIN(MIN_FISCAL_WEEK_START_DT) FROM date_interval) AND (SELECT MAX(MAX_FISCAL_WEEK_END_DT) FROM date_interval)
GROUP BY
    STORE_NBR
    , BRAND
    , dd.FISCAL_WEEK_NBR
    , dd.FISCAL_WEEK_START_DT
    , dd.FISCAL_WEEK_END_DT
)

, LY_fisc_trans AS 
(
SELECT
    od.STORE_ID AS STORE_NBR
    , CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
         WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
         WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
         WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
         WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
         WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
         WHEN od.BRAND_ID = ''rto'' THEN ''RT''
         ELSE ''UNKNOWN'' END AS BRAND
    , dd.FISCAL_WEEK_START_DT AS FISC_WEEK_START_DT
    , dd.FISCAL_WEEK_END_DT AS FISC_WEEK_END_DT
    , SUM(od.DERIVED_NET_AMT) AS FISC_REST_SALES_LY
    , COUNT(DISTINCT od.ORDER_ID) AS FISC_REST_TRANS_LY
FROM
    ORDER_DETAIL_V od
INNER JOIN
    IDH_DEV.SHARED.DATE_DIM_V dd
ON  od.ORDER_DT = dd.CALENDAR_DT
INNER JOIN
    IDH_DEV.SHARED.STORE_SCD_V st
ON  st.STORE_ID = od.STORE_ID
AND st.BRAND_ID = od.BRAND_ID
AND od.ORDER_DT BETWEEN st.EFFECTIVE_BEGIN_DT AND st.EFFECTIVE_END_DT
AND IFNULL(st.CLOSURE_DT, ''9999-12-31'') >= (SELECT DATE_TRUNC(''YEAR'', MIN(DT)) AS Ref_Date FROM (SELECT MIN(MIN_FISCAL_COMPARABLE_DT) AS DT FROM fisc_date_interval UNION SELECT MIN(MIN_CAL_COMPARABLE_DT) AS DT FROM cal_date_interval))
AND st.COUNTRY_NM IN (''US'', ''USA'')
WHERE
    IFNULL((CASE WHEN UPPER(CAST(VOIDED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(VOIDED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND IFNULL((CASE WHEN UPPER(CAST(CLEARED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(CLEARED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND IFNULL((CASE WHEN UPPER(CAST(DELETED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(DELETED_IND AS VARCHAR(10))) END), '''') != ''Y''
--AND od.MDM_ITEM_TYP IN (''Product'', ''Offer'', ''Offer and Product'')
AND od.ORDER_DT BETWEEN (SELECT MIN(MIN_FISCAL_COMPARABLE_DT) FROM fisc_date_interval) AND (SELECT MAX(MAX_FISCAL_COMPARABLE_DT) FROM fisc_date_interval)
GROUP BY
    STORE_NBR
    , BRAND
    , dd.FISCAL_WEEK_START_DT
    , dd.FISCAL_WEEK_END_DT
)

, LY_cal_trans AS 
(
SELECT
    od.STORE_ID AS STORE_NBR
    , CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
         WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
         WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
         WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
         WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
         WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
         WHEN od.BRAND_ID = ''rto'' THEN ''RT''
         ELSE ''UNKNOWN'' END AS BRAND
    , dd.CALENDAR_WEEK_START_DT AS CAL_WEEK_START_DT
    , dd.CALENDAR_WEEK_END_DT AS CAL_WEEK_END_DT
    , SUM(od.DERIVED_NET_AMT) AS CAL_REST_SALES_LY
    , COUNT(DISTINCT od.ORDER_ID) AS CAL_REST_TRANS_LY
FROM
    ORDER_DETAIL_V od
INNER JOIN
    IDH_DEV.SHARED.DATE_DIM_V dd
ON  od.ORDER_DT = dd.CALENDAR_DT
INNER JOIN
    IDH_DEV.SHARED.STORE_SCD_V st
ON  st.STORE_ID = od.STORE_ID
AND st.BRAND_ID = od.BRAND_ID
AND od.ORDER_DT BETWEEN st.EFFECTIVE_BEGIN_DT AND st.EFFECTIVE_END_DT
AND IFNULL(st.CLOSURE_DT, ''9999-12-31'') >= (SELECT DATE_TRUNC(''YEAR'', MIN(DT)) AS Ref_Date FROM (SELECT MIN(MIN_FISCAL_COMPARABLE_DT) AS DT FROM fisc_date_interval UNION SELECT MIN(MIN_CAL_COMPARABLE_DT) AS DT FROM cal_date_interval))
AND st.COUNTRY_NM IN (''US'', ''USA'')
WHERE
    IFNULL((CASE WHEN UPPER(CAST(VOIDED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(VOIDED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND IFNULL((CASE WHEN UPPER(CAST(CLEARED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(CLEARED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND IFNULL((CASE WHEN UPPER(CAST(DELETED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(DELETED_IND AS VARCHAR(10))) END), '''') != ''Y''
AND od.ORDER_DT BETWEEN (SELECT MIN(MIN_CAL_COMPARABLE_DT) FROM cal_date_interval) AND (SELECT MAX(MAX_CAL_COMPARABLE_DT) FROM cal_date_interval)
GROUP BY
    STORE_NBR
    , BRAND
    , dd.CALENDAR_WEEK_START_DT
    , dd.CALENDAR_WEEK_END_DT
)


, pre_res AS 
(
SELECT
    dd_f.FISCAL_WEEK_NBR AS FISC_WEEK_NBR
    , dd_f.FISCAL_WEEK_START_DT AS WEEK_START_DT
    , dd_f.FISCAL_WEEK_END_DT AS WEEK_END_DT
    , pos.BRAND
    , pos.STORE_NBR
    , NULLIF(pos.DMA_CD, '''') AS DMA_CD
    , NULLIF(pos.DMA_NM, '''') AS DMA_NM
    , pos.L1NAME
    , pos.L2NAME
    , pos.L3NAME
    , pos.L4NAME
    , pos.L5NAME
    , pos.OWNERSHIP_TYP
    , NULLIF(pos.STATE, '''') AS STATE
    , NULLIF(pos.COUNTRY, '''') AS COUNTRY
    , pos.FISC_YEAR_NBR
    , pos.FISC_QUARTER_NBR
    , pos.FISC_PERIOD_NBR
    , pos.MENU_ITEM_ID
    , pos.MDM_ITEM_TYP
    , pos.MENU_ITEM_NM
    , pos.MDM_PRODUCT_ID
    , pos.MDM_PRODUCT_NM
    , pos.MDM_OFFER_ID
    , pos.MDM_OFFER_NM
    , pos.PRODUCT_HIERARCHY_ID
    , pos.LEVEL5_PRODUCT_HIERARCHY_NM
    , pos.LEVEL4_PRODUCT_HIERARCHY_NM
    , pos.LEVEL3_PRODUCT_HIERARCHY_NM
    , pos.LEVEL2_PRODUCT_HIERARCHY_NM
    , pos.LEVEL1_PRODUCT_HIERARCHY_NM
    
    , pos.OFFER_HIERARCHY_ID
    , pos.LEVEL5_OFFER_HIERARCHY_NM
    , pos.LEVEL4_OFFER_HIERARCHY_NM
    , pos.LEVEL3_OFFER_HIERARCHY_NM
    , pos.LEVEL2_OFFER_HIERARCHY_NM
    , pos.LEVEL1_OFFER_HIERARCHY_NM
    
    , pos.PRODUCT_MISC1
    , pos.PRODUCT_MISC2
    , pos.PRODUCT_MISC3
    , pos.PRODUCT_MISC4
    , pos.PRODUCT_MISC5
    , pos.PRODUCT_MISC6
    , pos.PRODUCT_MISC7
    , pos.PRODUCT_MISC8
    , pos.PRODUCT_MISC9
    , pos.PRODUCT_MISC10
    
    , pos.OFFER_MISC1
    , pos.OFFER_MISC2
    , pos.OFFER_MISC3
    , pos.OFFER_MISC4
    , pos.OFFER_MISC5
    , pos.OFFER_MISC6
    , pos.OFFER_MISC7
    , pos.OFFER_MISC8
    , pos.OFFER_MISC9
    , pos.OFFER_MISC10
    
    , SUM(pos.PRODUCT_SALES_CY) AS PRODUCT_SALES_CY
    , SUM(pos.DISCOUNT_AMT_CY) AS DISCOUNT_AMT_CY
    , SUM(pos.MENU_ITEM_CNT_CY) AS MENU_ITEM_CNT_CY
    , SUM(pos.CHECK_SALES_CY) AS CHECK_SALES_CY
    , SUM(pos.CHECK_CNT_CY) AS CHECK_CNT_CY
    , dd_f_ly.FISCAL_WEEK_START_DT AS FISC_WEEK_START_DT_LY
    , dd_f_ly.FISCAL_WEEK_END_DT AS FISC_WEEK_END_DT_LY
    , SUM(pos.FISC_PRODUCT_SALES_LY) AS FISC_PRODUCT_SALES_LY
    , SUM(pos.FISC_DISCOUNT_AMT_LY) AS FISC_DISCOUNT_AMT_LY
    , SUM(pos.FISC_MENU_ITEM_CNT_LY) AS FISC_MENU_ITEM_CNT_LY
    , SUM(pos.FISC_CHECK_SALES_LY) AS FISC_CHECK_SALES_LY
    , SUM(pos.FISC_CHECK_CNT_LY) AS FISC_CHECK_CNT_LY
    , dd_cal_ly.CALENDAR_WEEK_START_DT AS CAL_WEEK_START_DT_LY
    , dd_cal_ly.CALENDAR_WEEK_END_DT AS CAL_WEEK_END_DT_LY
    , SUM(pos.CAL_PRODUCT_SALES_LY) AS CAL_PRODUCT_SALES_LY
    , SUM(pos.CAL_DISCOUNT_AMT_LY) AS CAL_DISCOUNT_AMT_LY
    , SUM(pos.CAL_MENU_ITEM_CNT_LY) AS CAL_MENU_ITEM_CNT_LY
    , SUM(pos.CAL_CHECK_SALES_LY) AS CAL_CHECK_SALES_LY
    , SUM(pos.CAL_CHECK_CNT_LY) AS CAL_CHECK_CNT_LY
FROM
    TABLE(INSPIRE_DAILY_PRODUCT_OFFER_SALES(    (SELECT MIN(MIN_FISCAL_WEEK_START_DT) FROM date_interval), (SELECT MAX(MAX_FISCAL_WEEK_END_DT) FROM date_interval)          )) pos
INNER JOIN
    IDH_DEV.SHARED.DATE_DIM_V dd_f
ON  dd_f.CALENDAR_DT = pos.BUSINESS_DT
INNER JOIN
    IDH_DEV.SHARED.DATE_DIM_V dd_f_ly
ON  dd_f_ly.CALENDAR_DT = pos.FISC_DATE_LY
INNER JOIN
    IDH_DEV.SHARED.DATE_DIM_V dd_cal_ly
ON  dd_cal_ly.CALENDAR_DT = pos.CAL_COMP_DATE_LY
GROUP BY
    dd_f.FISCAL_WEEK_NBR
    , dd_f.FISCAL_WEEK_START_DT
    , dd_f.FISCAL_WEEK_END_DT
    , pos.BRAND
    , pos.STORE_NBR
    , pos.DMA_CD
    , pos.DMA_NM
    , pos.L1NAME
    , pos.L2NAME
    , pos.L3NAME
    , pos.L4NAME
    , pos.L5NAME
    , pos.OWNERSHIP_TYP
    , pos.STATE
    , pos.COUNTRY
    , pos.FISC_YEAR_NBR
    , pos.FISC_QUARTER_NBR
    , pos.FISC_PERIOD_NBR
    , pos.MENU_ITEM_ID
    , pos.MDM_ITEM_TYP
    , pos.MENU_ITEM_NM
    , pos.MDM_PRODUCT_ID
    , pos.MDM_PRODUCT_NM
    , pos.MDM_OFFER_ID
    , pos.MDM_OFFER_NM
    , pos.PRODUCT_HIERARCHY_ID
    , pos.LEVEL5_PRODUCT_HIERARCHY_NM
    , pos.LEVEL4_PRODUCT_HIERARCHY_NM
    , pos.LEVEL3_PRODUCT_HIERARCHY_NM
    , pos.LEVEL2_PRODUCT_HIERARCHY_NM
    , pos.LEVEL1_PRODUCT_HIERARCHY_NM
    
    , pos.OFFER_HIERARCHY_ID
    , pos.LEVEL5_OFFER_HIERARCHY_NM
    , pos.LEVEL4_OFFER_HIERARCHY_NM
    , pos.LEVEL3_OFFER_HIERARCHY_NM
    , pos.LEVEL2_OFFER_HIERARCHY_NM
    , pos.LEVEL1_OFFER_HIERARCHY_NM
    
    , pos.PRODUCT_MISC1
    , pos.PRODUCT_MISC2
    , pos.PRODUCT_MISC3
    , pos.PRODUCT_MISC4
    , pos.PRODUCT_MISC5
    , pos.PRODUCT_MISC6
    , pos.PRODUCT_MISC7
    , pos.PRODUCT_MISC8
    , pos.PRODUCT_MISC9
    , pos.PRODUCT_MISC10
    
    , pos.OFFER_MISC1
    , pos.OFFER_MISC2
    , pos.OFFER_MISC3
    , pos.OFFER_MISC4
    , pos.OFFER_MISC5
    , pos.OFFER_MISC6
    , pos.OFFER_MISC7
    , pos.OFFER_MISC8
    , pos.OFFER_MISC9
    , pos.OFFER_MISC10
    
    , dd_f_ly.FISCAL_WEEK_START_DT
    , dd_f_ly.FISCAL_WEEK_END_DT

    , dd_cal_ly.CALENDAR_WEEK_START_DT
    , dd_cal_ly.CALENDAR_WEEK_END_DT
)  
  
SELECT
    pr.FISC_WEEK_NBR
    , pr.WEEK_START_DT
    , pr.WEEK_END_DT
    , pr.BRAND
    , pr.STORE_NBR
    , pr.DMA_CD
    , pr.DMA_NM
    , pr.L1NAME
    , pr.L2NAME
    , pr.L3NAME
    , pr.L4NAME
    , pr.L5NAME
    , pr.OWNERSHIP_TYP
    , pr.STATE
    , pr.COUNTRY
    , pr.FISC_YEAR_NBR
    , pr.FISC_QUARTER_NBR
    , pr.FISC_PERIOD_NBR
    , pr.MENU_ITEM_ID
    , pr.MDM_ITEM_TYP
    , pr.MENU_ITEM_NM
    , pr.MDM_PRODUCT_ID
    , pr.MDM_PRODUCT_NM
    , pr.MDM_OFFER_ID
    , pr.MDM_OFFER_NM
    , pr.PRODUCT_HIERARCHY_ID
    , pr.LEVEL5_PRODUCT_HIERARCHY_NM
    , pr.LEVEL4_PRODUCT_HIERARCHY_NM
    , pr.LEVEL3_PRODUCT_HIERARCHY_NM
    , pr.LEVEL2_PRODUCT_HIERARCHY_NM
    , pr.LEVEL1_PRODUCT_HIERARCHY_NM

    , pr.OFFER_HIERARCHY_ID
    , pr.LEVEL5_OFFER_HIERARCHY_NM
    , pr.LEVEL4_OFFER_HIERARCHY_NM
    , pr.LEVEL3_OFFER_HIERARCHY_NM
    , pr.LEVEL2_OFFER_HIERARCHY_NM
    , pr.LEVEL1_OFFER_HIERARCHY_NM

    , pr.PRODUCT_MISC1
    , pr.PRODUCT_MISC2
    , pr.PRODUCT_MISC3
    , pr.PRODUCT_MISC4
    , pr.PRODUCT_MISC5
    , pr.PRODUCT_MISC6
    , pr.PRODUCT_MISC7
    , pr.PRODUCT_MISC8
    , pr.PRODUCT_MISC9
    , pr.PRODUCT_MISC10

    , pr.OFFER_MISC1
    , pr.OFFER_MISC2
    , pr.OFFER_MISC3
    , pr.OFFER_MISC4
    , pr.OFFER_MISC5
    , pr.OFFER_MISC6
    , pr.OFFER_MISC7
    , pr.OFFER_MISC8
    , pr.OFFER_MISC9
    , pr.OFFER_MISC10

    , CAST(pr.PRODUCT_SALES_CY AS NUMBER(38, 2)) AS PRODUCT_SALES_CY
    , CAST(pr.DISCOUNT_AMT_CY AS NUMBER(38, 2)) AS DISCOUNT_AMT_CY
    , pr.MENU_ITEM_CNT_CY
    , CAST(pr.CHECK_SALES_CY AS NUMBER(38, 2)) AS CHECK_SALES_CY
    , pr.CHECK_CNT_CY
    , CAST(IFNULL(cy.REST_SALES_CY, 0.00) AS NUMBER(38, 2)) AS REST_SALES_CY
    , CAST(IFNULL(cy.REST_TRANS_CY, 0) AS NUMBER(38, 2)) AS REST_TRANS_CY
    , pr.FISC_WEEK_START_DT_LY
    , pr.FISC_WEEK_END_DT_LY
    , CAST(pr.FISC_PRODUCT_SALES_LY AS NUMBER(38, 2)) AS FISC_PRODUCT_SALES_LY
    , CAST(pr.FISC_DISCOUNT_AMT_LY AS NUMBER(38, 2)) AS FISC_DISCOUNT_AMT_LY
    , pr.FISC_MENU_ITEM_CNT_LY
    , CAST(pr.FISC_CHECK_SALES_LY AS NUMBER(38, 2)) AS FISC_CHECK_SALES_LY
    , pr.FISC_CHECK_CNT_LY
    , CAST(IFNULL(ly_f.FISC_REST_SALES_LY, 0.00) AS NUMBER(38, 2)) AS FISC_REST_SALES_LY
    , CAST(IFNULL(ly_f.FISC_REST_TRANS_LY, 0) AS NUMBER(38, 0)) AS FISC_REST_TRANS_LY
    , pr.CAL_WEEK_START_DT_LY
    , pr.CAL_WEEK_END_DT_LY
    , CAST(pr.CAL_PRODUCT_SALES_LY AS NUMBER(38, 2)) AS CAL_PRODUCT_SALES_LY
    , CAST(pr.CAL_DISCOUNT_AMT_LY AS NUMBER(38, 2)) AS CAL_DISCOUNT_AMT_LY
    , pr.CAL_MENU_ITEM_CNT_LY
    , CAST(pr.CAL_CHECK_SALES_LY AS NUMBER(38, 2)) AS CAL_CHECK_SALES_LY
    , pr.CAL_CHECK_CNT_LY
    , CAST(IFNULL(ly_c.CAL_REST_SALES_LY, 0.00) AS NUMBER(38, 2)) AS CAL_REST_SALES_LY
    , CAST(IFNULL(ly_c.CAL_REST_TRANS_LY, 0) AS NUMBER(38, 2)) AS CAL_REST_TRANS_LY
FROM 
    pre_res pr
LEFT OUTER JOIN
    CY_trans cy
ON  pr.BRAND = cy.BRAND
AND pr.STORE_NBR = cy.STORE_NBR
AND pr.FISC_WEEK_NBR = cy.FISC_WEEK_NBR
AND pr.WEEK_START_DT = cy.FISC_WEEK_START_DT
AND pr.WEEK_END_DT = cy.FISC_WEEK_END_DT
LEFT OUTER JOIN
    LY_fisc_trans ly_f
ON  ly_f.BRAND = pr.BRAND
AND ly_f.STORE_NBR = pr.STORE_NBR
AND ly_f.FISC_WEEK_START_DT = pr.FISC_WEEK_START_DT_LY
AND ly_f.FISC_WEEK_END_DT = pr.FISC_WEEK_END_DT_LY
LEFT OUTER JOIN
    LY_cal_trans ly_c
ON  ly_c.BRAND = pr.BRAND
AND ly_c.STORE_NBR = pr.STORE_NBR
AND ly_c.CAL_WEEK_START_DT = pr.CAL_WEEK_START_DT_LY
AND ly_c.CAL_WEEK_END_DT = pr.CAL_WEEK_END_DT_LY
  
  
';
CREATE FUNCTION IF NOT EXISTS INSPIRE_WEEKLY_PRODUCT_SALES("FISCAL_YEAR" NUMBER(38,0), "FROM_WEEK" NUMBER(38,0), "TO_WEEK" NUMBER(38,0))
RETURNS TABLE ("FISC_WEEK_NBR" NUMBER(38,0), "WEEK_START_DT" DATE, "WEEK_END_DT" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_CD" VARCHAR(16777216), "DMA_NM" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "MDM_PRODUCT_ID" NUMBER(38,0), "MDM_PRODUCT_NM" VARCHAR(16777216), "PRODUCT_HIERARCHY_ID" NUMBER(38,0), "LEVEL5_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL4_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL3_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL2_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL1_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "PRODUCT_MISC1" VARCHAR(16777216), "PRODUCT_MISC2" VARCHAR(16777216), "PRODUCT_MISC3" VARCHAR(16777216), "PRODUCT_MISC4" VARCHAR(16777216), "PRODUCT_MISC5" VARCHAR(16777216), "PRODUCT_MISC6" VARCHAR(16777216), "PRODUCT_MISC7" VARCHAR(16777216), "PRODUCT_MISC8" VARCHAR(16777216), "PRODUCT_MISC9" VARCHAR(16777216), "PRODUCT_MISC10" VARCHAR(16777216), "PRODUCT_SALES_CY" NUMBER(38,2), "PRODUCT_CNT_CY" NUMBER(38,0), "CHECK_SALES_CY" NUMBER(38,2), "CHECK_CNT_CY" NUMBER(38,0), "REST_SALES_CY" NUMBER(38,2), "REST_TRANS_CY" NUMBER(38,0), "FISC_WEEK_START_DT_LY" DATE, "FISC_WEEK_END_DT_LY" DATE, "FISC_PRODUCT_SALES_LY" NUMBER(38,2), "FISC_PRODUCT_CNT_LY" NUMBER(38,0), "FISC_CHECK_SALES_LY" NUMBER(38,2), "FISC_CHECK_CNT_LY" NUMBER(38,0), "FISC_REST_SALES_LY" NUMBER(38,2), "FISC_REST_TRANS_LY" NUMBER(38,0), "CAL_WEEK_START_DT_LY" DATE, "CAL_WEEK_END_DT_LY" DATE, "CAL_PRODUCT_SALES_LY" NUMBER(38,2), "CAL_PRODUCT_CNT_LY" NUMBER(38,0), "CAL_CHECK_SALES_LY" NUMBER(38,2), "CAL_CHECK_CNT_LY" NUMBER(38,0), "CAL_REST_SALES_LY" NUMBER(38,2), "CAL_REST_TRANS_LY" NUMBER(38,0))
LANGUAGE SQL
AS '


WITH CY_interval AS 
(
SELECT 
    MIN(FISCAL_WEEK_START_DT) AS MIN_FISCAL_WEEK_START_DT
    , MAX(FISCAL_WEEK_END_DT) AS MAX_FISCAL_WEEK_END_DT
FROM 
    IDH_DEV.SHARED.DATE_DIM_V dd 
WHERE
    FISCAL_YEAR_NBR = FISCAL_YEAR
    AND FISCAL_WEEK_NBR BETWEEN FROM_WEEK AND TO_WEEK
GROUP BY
    FISCAL_WEEK_NBR
)

, fisc_interval AS
(
SELECT
    MIN(FISCAL_COMPARABLE_DT) AS MIN_FISCAL_COMPARABLE_DT
    , MAX(FISCAL_COMPARABLE_DT) AS MAX_FISCAL_COMPARABLE_DT 
FROM 
    IDH_DEV.SHARED.DATE_DIM_V dd 
WHERE 
    CALENDAR_DT BETWEEN (SELECT MIN(MIN_FISCAL_WEEK_START_DT) FROM CY_interval) AND (SELECT MAX(MAX_FISCAL_WEEK_END_DT) FROM CY_interval)
)

, cal_interval AS
(
SELECT 
    MIN(CALENDAR_COMPARABLE_DT) AS MIN_CAL_COMPARABLE_DT
    , MAX(CALENDAR_COMPARABLE_DT) AS MAX_CAL_COMPARABLE_DT 
FROM 
    IDH_DEV.SHARED.DATE_DIM_V dd 
WHERE 
    CALENDAR_DT BETWEEN (SELECT MIN(MIN_FISCAL_WEEK_START_DT) FROM CY_interval) AND (SELECT MAX(MAX_FISCAL_WEEK_END_DT) FROM CY_interval)
)

, CY AS
(
SELECT
    AGG_LEVEL
    , BUSINESS_DT
    , BRAND
    , BRAND_ID
    , STORE_NBR
    , MDM_PRODUCT_ID
  
    , MDM_PRODUCT_NM
    , PRODUCT_HIERARCHY_ID
    , LEVEL5_PRODUCT_HIERARCHY_NM
    , LEVEL4_PRODUCT_HIERARCHY_NM
    , LEVEL3_PRODUCT_HIERARCHY_NM
    , LEVEL2_PRODUCT_HIERARCHY_NM
    , LEVEL1_PRODUCT_HIERARCHY_NM
    , PRODUCT_MISC1
    , PRODUCT_MISC2
    , PRODUCT_MISC3
    , PRODUCT_MISC4
    , PRODUCT_MISC5
    , PRODUCT_MISC6
    , PRODUCT_MISC7
    , PRODUCT_MISC8
    , PRODUCT_MISC9
    , PRODUCT_MISC10
    
    , PRODUCT_SALES_CY
    , PRODUCT_CNT_CY
    , CHECK_SALES_CY
    , CHECK_CNT_CY
    , REST_SALES_CY
    , REST_TRANS_CY
    
    , FISC_DATE_LY
    , 0.00 AS FISC_PRODUCT_SALES_CY
    , 0 AS FISC_PRODUCT_CNT_CY
    , 0.00 AS FISC_CHECK_SALES_CY
    , 0 AS FISC_CHECK_CNT_CY
    , 0.00 AS FISC_REST_SALES_CY
    , 0 AS FISC_REST_TRANS_CY
    
    , CAL_COMP_DATE_LY
    , 0.00 AS CAL_PRODUCT_SALES_CY
    , 0 AS CAL_PRODUCT_CNT_CY
    , 0.00 AS CAL_CHECK_SALES_CY
    , 0 AS CAL_CHECK_CNT_CY
    , 0.00 AS CAL_REST_SALES_CY
    , 0 AS CAL_REST_TRANS_CY
FROM
    TABLE(INSPIRE_DAILY_PRODUCT_SALES_MAIN((SELECT MIN(MIN_FISCAL_WEEK_START_DT) FROM CY_interval), (SELECT MAX(MAX_FISCAL_WEEK_END_DT) FROM CY_interval)))
)

, FSC AS
(
SELECT
    fsc.AGG_LEVEL
    , dd_f.CALENDAR_DT AS BUSINESS_DT
    , fsc.BRAND
    , fsc.BRAND_ID
    , fsc.STORE_NBR
    , fsc.MDM_PRODUCT_ID
  
    , fsc.MDM_PRODUCT_NM
    , fsc.PRODUCT_HIERARCHY_ID
    , fsc.LEVEL5_PRODUCT_HIERARCHY_NM
    , fsc.LEVEL4_PRODUCT_HIERARCHY_NM
    , fsc.LEVEL3_PRODUCT_HIERARCHY_NM
    , fsc.LEVEL2_PRODUCT_HIERARCHY_NM
    , fsc.LEVEL1_PRODUCT_HIERARCHY_NM
    , fsc.PRODUCT_MISC1
    , fsc.PRODUCT_MISC2
    , fsc.PRODUCT_MISC3
    , fsc.PRODUCT_MISC4
    , fsc.PRODUCT_MISC5
    , fsc.PRODUCT_MISC6
    , fsc.PRODUCT_MISC7
    , fsc.PRODUCT_MISC8
    , fsc.PRODUCT_MISC9
    , fsc.PRODUCT_MISC10
    
    , 0.00 AS PRODUCT_SALES_CY
    , 0 AS PRODUCT_CNT_CY
    , 0.00 AS CHECK_SALES_CY
    , 0 AS CHECK_CNT_CY
    , 0.00 AS REST_SALES_CY
    , 0 AS REST_TRANS_CY
    
    , fsc.BUSINESS_DT AS FISC_DATE_LY
    , fsc.PRODUCT_SALES_CY AS FISC_PRODUCT_SALES_CY
    , fsc.PRODUCT_CNT_CY AS FISC_PRODUCT_CNT_CY
    , fsc.CHECK_SALES_CY AS FISC_CHECK_SALES_CY
    , fsc.CHECK_CNT_CY AS FISC_CHECK_CNT_CY
    , fsc.REST_SALES_CY AS FISC_REST_SALES_CY
    , fsc.REST_TRANS_CY AS FISC_REST_TRANS_CY
    
    , dd_f.CALENDAR_COMPARABLE_DT AS CAL_COMP_DATE_LY
    , 0.00 AS CAL_PRODUCT_SALES_CY
    , 0 AS CAL_PRODUCT_CNT_CY
    , 0.00 AS CAL_CHECK_SALES_CY
    , 0 AS CAL_CHECK_CNT_CY
    , 0.00 AS CAL_REST_SALES_CY
    , 0 AS CAL_REST_TRANS_CY
FROM
    TABLE(INSPIRE_DAILY_PRODUCT_SALES_MAIN((SELECT MIN(MIN_FISCAL_COMPARABLE_DT) FROM fisc_interval), (SELECT MAX(MAX_FISCAL_COMPARABLE_DT) FROM fisc_interval))) fsc
LEFT OUTER JOIN
    IDH_DEV.SHARED.DATE_DIM_V dd_f
ON  dd_f.FISCAL_COMPARABLE_DT = fsc.BUSINESS_DT
)

, CAL AS
(
SELECT
    cal.AGG_LEVEL
    , dd_cal.CALENDAR_DT AS BUSINESS_DT
    , cal.BRAND
    , cal.BRAND_ID
    , cal.STORE_NBR
    , cal.MDM_PRODUCT_ID
  
    , cal.MDM_PRODUCT_NM
    , cal.PRODUCT_HIERARCHY_ID
    , cal.LEVEL5_PRODUCT_HIERARCHY_NM
    , cal.LEVEL4_PRODUCT_HIERARCHY_NM
    , cal.LEVEL3_PRODUCT_HIERARCHY_NM
    , cal.LEVEL2_PRODUCT_HIERARCHY_NM
    , cal.LEVEL1_PRODUCT_HIERARCHY_NM
    , cal.PRODUCT_MISC1
    , cal.PRODUCT_MISC2
    , cal.PRODUCT_MISC3
    , cal.PRODUCT_MISC4
    , cal.PRODUCT_MISC5
    , cal.PRODUCT_MISC6
    , cal.PRODUCT_MISC7
    , cal.PRODUCT_MISC8
    , cal.PRODUCT_MISC9
    , cal.PRODUCT_MISC10

    , 0.00 AS PRODUCT_SALES_CY
    , 0 AS PRODUCT_CNT_CY
    , 0.00 AS CHECK_SALES_CY
    , 0 AS CHECK_CNT_CY
    , 0.00 AS REST_SALES_CY
    , 0 AS REST_TRANS_CY

    , dd_cal.FISCAL_COMPARABLE_DT AS FISC_DATE_LY
    , 0.00 AS FISC_PRODUCT_SALES_CY
    , 0 AS FISC_PRODUCT_CNT_CY
    , 0.00 AS FISC_CHECK_SALES_CY
    , 0 AS FISC_CHECK_CNT_CY
    , 0.00 AS FISC_REST_SALES_CY
    , 0 AS FISC_REST_TRANS_CY

    , cal.BUSINESS_DT AS CAL_COMP_DATE_LY
    , cal.PRODUCT_SALES_CY AS CAL_PRODUCT_SALES_CY
    , cal.PRODUCT_CNT_CY AS CAL_PRODUCT_CNT_CY
    , cal.CHECK_SALES_CY AS CAL_CHECK_SALES_CY
    , cal.CHECK_CNT_CY AS CAL_CHECK_CNT_CY
    , cal.REST_SALES_CY AS CAL_REST_SALES_CY
    , cal.REST_TRANS_CY AS CAL_REST_TRANS_CY
FROM
    TABLE(INSPIRE_DAILY_PRODUCT_SALES_MAIN((SELECT MIN(MIN_CAL_COMPARABLE_DT) FROM cal_interval), (SELECT MAX(MAX_CAL_COMPARABLE_DT) FROM cal_interval))) cal
LEFT OUTER JOIN
    IDH_DEV.SHARED.DATE_DIM_V dd_cal
ON  dd_cal.CALENDAR_COMPARABLE_DT = cal.BUSINESS_DT
)

, agg AS
(
SELECT
    AGG_LEVEL
    , BUSINESS_DT
    , BRAND
    , BRAND_ID
    , STORE_NBR
    , MDM_PRODUCT_ID
  
    , MDM_PRODUCT_NM
    , PRODUCT_HIERARCHY_ID
    , LEVEL5_PRODUCT_HIERARCHY_NM
    , LEVEL4_PRODUCT_HIERARCHY_NM
    , LEVEL3_PRODUCT_HIERARCHY_NM
    , LEVEL2_PRODUCT_HIERARCHY_NM
    , LEVEL1_PRODUCT_HIERARCHY_NM
    , PRODUCT_MISC1
    , PRODUCT_MISC2
    , PRODUCT_MISC3
    , PRODUCT_MISC4
    , PRODUCT_MISC5
    , PRODUCT_MISC6
    , PRODUCT_MISC7
    , PRODUCT_MISC8
    , PRODUCT_MISC9
    , PRODUCT_MISC10
    
    , PRODUCT_SALES_CY
    , PRODUCT_CNT_CY
    , CHECK_SALES_CY
    , CHECK_CNT_CY
    , REST_SALES_CY
    , REST_TRANS_CY
    
    , FISC_DATE_LY
    , FISC_PRODUCT_SALES_CY
    , FISC_PRODUCT_CNT_CY
    , FISC_CHECK_SALES_CY
    , FISC_CHECK_CNT_CY
    , FISC_REST_SALES_CY
    , FISC_REST_TRANS_CY
    
    , CAL_COMP_DATE_LY
    , CAL_PRODUCT_SALES_CY
    , CAL_PRODUCT_CNT_CY
    , CAL_CHECK_SALES_CY
    , CAL_CHECK_CNT_CY
    , CAL_REST_SALES_CY
    , CAL_REST_TRANS_CY
FROM
    CY

UNION ALL

SELECT
    AGG_LEVEL
    , BUSINESS_DT
    , BRAND
    , BRAND_ID
    , STORE_NBR
    , MDM_PRODUCT_ID
  
    , MDM_PRODUCT_NM
    , PRODUCT_HIERARCHY_ID
    , LEVEL5_PRODUCT_HIERARCHY_NM
    , LEVEL4_PRODUCT_HIERARCHY_NM
    , LEVEL3_PRODUCT_HIERARCHY_NM
    , LEVEL2_PRODUCT_HIERARCHY_NM
    , LEVEL1_PRODUCT_HIERARCHY_NM
    , PRODUCT_MISC1
    , PRODUCT_MISC2
    , PRODUCT_MISC3
    , PRODUCT_MISC4
    , PRODUCT_MISC5
    , PRODUCT_MISC6
    , PRODUCT_MISC7
    , PRODUCT_MISC8
    , PRODUCT_MISC9
    , PRODUCT_MISC10

    , PRODUCT_SALES_CY
    , PRODUCT_CNT_CY
    , CHECK_SALES_CY
    , CHECK_CNT_CY
    , REST_SALES_CY
    , REST_TRANS_CY
    
    , FISC_DATE_LY
    , FISC_PRODUCT_SALES_CY
    , FISC_PRODUCT_CNT_CY
    , FISC_CHECK_SALES_CY
    , FISC_CHECK_CNT_CY
    , FISC_REST_SALES_CY
    , FISC_REST_TRANS_CY
    
    , CAL_COMP_DATE_LY
    , CAL_PRODUCT_SALES_CY
    , CAL_PRODUCT_CNT_CY
    , CAL_CHECK_SALES_CY
    , CAL_CHECK_CNT_CY
    , CAL_REST_SALES_CY
    , CAL_REST_TRANS_CY
FROM
    FSC

UNION ALL

SELECT
    AGG_LEVEL
    , BUSINESS_DT
    , BRAND
    , BRAND_ID
    , STORE_NBR
    , MDM_PRODUCT_ID
  
    , MDM_PRODUCT_NM
    , PRODUCT_HIERARCHY_ID
    , LEVEL5_PRODUCT_HIERARCHY_NM
    , LEVEL4_PRODUCT_HIERARCHY_NM
    , LEVEL3_PRODUCT_HIERARCHY_NM
    , LEVEL2_PRODUCT_HIERARCHY_NM
    , LEVEL1_PRODUCT_HIERARCHY_NM
    , PRODUCT_MISC1
    , PRODUCT_MISC2
    , PRODUCT_MISC3
    , PRODUCT_MISC4
    , PRODUCT_MISC5
    , PRODUCT_MISC6
    , PRODUCT_MISC7
    , PRODUCT_MISC8
    , PRODUCT_MISC9
    , PRODUCT_MISC10
    
    , PRODUCT_SALES_CY
    , PRODUCT_CNT_CY
    , CHECK_SALES_CY
    , CHECK_CNT_CY
    , REST_SALES_CY
    , REST_TRANS_CY
    
    , FISC_DATE_LY
    , FISC_PRODUCT_SALES_CY
    , FISC_PRODUCT_CNT_CY
    , FISC_CHECK_SALES_CY
    , FISC_CHECK_CNT_CY
    , FISC_REST_SALES_CY
    , FISC_REST_TRANS_CY
    
    , CAL_COMP_DATE_LY
    , CAL_PRODUCT_SALES_CY
    , CAL_PRODUCT_CNT_CY
    , CAL_CHECK_SALES_CY
    , CAL_CHECK_CNT_CY
    , CAL_REST_SALES_CY
    , CAL_REST_TRANS_CY
FROM
    CAL
)

, pre_final AS
(
SELECT
    AGG_LEVEL
    , BUSINESS_DT
    , BRAND
    , BRAND_ID
    , STORE_NBR
    , MDM_PRODUCT_ID

    , MAX(MDM_PRODUCT_NM) AS MDM_PRODUCT_NM
    , MAX(PRODUCT_HIERARCHY_ID) AS PRODUCT_HIERARCHY_ID
    , MAX(LEVEL5_PRODUCT_HIERARCHY_NM) AS LEVEL5_PRODUCT_HIERARCHY_NM
    , MAX(LEVEL4_PRODUCT_HIERARCHY_NM) AS LEVEL4_PRODUCT_HIERARCHY_NM
    , MAX(LEVEL3_PRODUCT_HIERARCHY_NM) AS LEVEL3_PRODUCT_HIERARCHY_NM
    , MAX(LEVEL2_PRODUCT_HIERARCHY_NM) AS LEVEL2_PRODUCT_HIERARCHY_NM
    , MAX(LEVEL1_PRODUCT_HIERARCHY_NM) AS LEVEL1_PRODUCT_HIERARCHY_NM
    , MAX(PRODUCT_MISC1) AS PRODUCT_MISC1
    , MAX(PRODUCT_MISC2) AS PRODUCT_MISC2
    , MAX(PRODUCT_MISC3) AS PRODUCT_MISC3
    , MAX(PRODUCT_MISC4) AS PRODUCT_MISC4
    , MAX(PRODUCT_MISC5) AS PRODUCT_MISC5
    , MAX(PRODUCT_MISC6) AS PRODUCT_MISC6
    , MAX(PRODUCT_MISC7) AS PRODUCT_MISC7
    , MAX(PRODUCT_MISC8) AS PRODUCT_MISC8
    , MAX(PRODUCT_MISC9) AS PRODUCT_MISC9
    , MAX(PRODUCT_MISC10) AS PRODUCT_MISC10

    , SUM(PRODUCT_SALES_CY) AS PRODUCT_SALES_CY
    , SUM(PRODUCT_CNT_CY) AS PRODUCT_CNT_CY
    , SUM(CHECK_SALES_CY) AS CHECK_SALES_CY
    , SUM(CHECK_CNT_CY) AS CHECK_CNT_CY
    , SUM(REST_SALES_CY) AS REST_SALES_CY
    , SUM(REST_TRANS_CY) AS REST_TRANS_CY
    
    , FISC_DATE_LY
    , SUM(FISC_PRODUCT_SALES_CY) AS FISC_PRODUCT_SALES_CY
    , SUM(FISC_PRODUCT_CNT_CY) AS FISC_PRODUCT_CNT_CY
    , SUM(FISC_CHECK_SALES_CY) AS FISC_CHECK_SALES_CY
    , SUM(FISC_CHECK_CNT_CY) AS FISC_CHECK_CNT_CY
    , SUM(FISC_REST_SALES_CY) AS FISC_REST_SALES_CY
    , SUM(FISC_REST_TRANS_CY) AS FISC_REST_TRANS_CY
    
    , CAL_COMP_DATE_LY
    , SUM(CAL_PRODUCT_SALES_CY) AS CAL_PRODUCT_SALES_CY
    , SUM(CAL_PRODUCT_CNT_CY) AS CAL_PRODUCT_CNT_CY
    , SUM(CAL_CHECK_SALES_CY) AS CAL_CHECK_SALES_CY
    , SUM(CAL_CHECK_CNT_CY) AS CAL_CHECK_CNT_CY
    , SUM(CAL_REST_SALES_CY) AS CAL_REST_SALES_CY
    , SUM(CAL_REST_TRANS_CY) AS CAL_REST_TRANS_CY
FROM
    agg
GROUP BY
    AGG_LEVEL
    , BUSINESS_DT
    , BRAND
    , BRAND_ID
    , STORE_NBR
    , MDM_PRODUCT_ID
  
    , FISC_DATE_LY
    , CAL_COMP_DATE_LY
)

, pre_final_week AS
(
SELECT
    pf.AGG_LEVEL
    , pf.BUSINESS_DT
    , pf.BRAND
    , pf.STORE_NBR
    , ROW_NUMBER() OVER(PARTITION BY  pf.BUSINESS_DT, pf.BRAND, pf.STORE_NBR ORDER BY pf.BUSINESS_DT, pf.BRAND, pf.STORE_NBR, NULLIF(pf.MDM_PRODUCT_ID, 0)) AS Rn

    , st.DMA_CD
    , st.DMA_NM

    , lv.LEVEL1_NM AS L1NAME
    , lv.LEVEL2_NM AS L2NAME
    , lv.LEVEL3_NM AS L3NAME
    , lv.LEVEL4_NM AS L4NAME
    , lv.LEVEL5_NM AS L5NAME

    , st.OWNERSHIP_TYP AS OWNERSHIP_TYP
    , st.STATE_NM AS STATE
    , st.COUNTRY_NM AS COUNTRY

    , dd.FISCAL_YEAR_NBR AS FISC_YEAR_NBR
    , dd.FISCAL_QUARTER_NBR AS FISC_QUARTER_NBR
    , dd.FISCAL_PERIOD_NBR AS FISC_PERIOD_NBR
    
    , NULLIF(pf.MDM_PRODUCT_ID, 0) AS MDM_PRODUCT_ID
    , pf.MDM_PRODUCT_NM
    , pf.PRODUCT_HIERARCHY_ID
    , pf.LEVEL5_PRODUCT_HIERARCHY_NM
    , pf.LEVEL4_PRODUCT_HIERARCHY_NM
    , pf.LEVEL3_PRODUCT_HIERARCHY_NM
    , pf.LEVEL2_PRODUCT_HIERARCHY_NM
    , pf.LEVEL1_PRODUCT_HIERARCHY_NM
    , pf.PRODUCT_MISC1
    , pf.PRODUCT_MISC2
    , pf.PRODUCT_MISC3
    , pf.PRODUCT_MISC4
    , pf.PRODUCT_MISC5
    , pf.PRODUCT_MISC6
    , pf.PRODUCT_MISC7
    , pf.PRODUCT_MISC8
    , pf.PRODUCT_MISC9
    , pf.PRODUCT_MISC10

    , pf.PRODUCT_SALES_CY
    , pf.PRODUCT_CNT_CY
    , pf.CHECK_SALES_CY
    , pf.CHECK_CNT_CY

    , IFF(pf.REST_SALES_CY <> 0.00, pf.REST_SALES_CY, (FIRST_VALUE(pf.REST_SALES_CY) OVER (PARTITION BY pf.BUSINESS_DT, pf.BRAND, pf.STORE_NBR ORDER BY pf.REST_SALES_CY DESC))) AS REST_SALES_CY
    , IFF(pf.REST_TRANS_CY <> 0.00, pf.REST_TRANS_CY, (FIRST_VALUE(pf.REST_TRANS_CY) OVER (PARTITION BY pf.BUSINESS_DT, pf.BRAND, pf.STORE_NBR ORDER BY pf.REST_TRANS_CY DESC))) AS REST_TRANS_CY
    , pf.FISC_DATE_LY
    , pf.FISC_PRODUCT_SALES_CY
    , pf.FISC_PRODUCT_CNT_CY
    , pf.FISC_CHECK_SALES_CY
    , pf.FISC_CHECK_CNT_CY
    , IFF(pf.FISC_REST_SALES_CY <> 0.00, pf.FISC_REST_SALES_CY, (FIRST_VALUE(pf.FISC_REST_SALES_CY) OVER (PARTITION BY pf.BUSINESS_DT, pf.BRAND, pf.STORE_NBR ORDER BY pf.FISC_REST_SALES_CY DESC))) AS FISC_REST_SALES_CY
    , IFF(pf.FISC_REST_TRANS_CY <> 0.00, pf.FISC_REST_TRANS_CY, (FIRST_VALUE(pf.FISC_REST_TRANS_CY) OVER (PARTITION BY pf.BUSINESS_DT, pf.BRAND, pf.STORE_NBR ORDER BY pf.FISC_REST_TRANS_CY DESC))) AS FISC_REST_TRANS_CY
    
    , pf.CAL_COMP_DATE_LY
    , pf.CAL_PRODUCT_SALES_CY
    , pf.CAL_PRODUCT_CNT_CY
    , pf.CAL_CHECK_SALES_CY
    , pf.CAL_CHECK_CNT_CY
    , IFF(pf.CAL_REST_SALES_CY <> 0.00, pf.CAL_REST_SALES_CY, (FIRST_VALUE(pf.CAL_REST_SALES_CY) OVER (PARTITION BY pf.BUSINESS_DT, pf.BRAND, pf.STORE_NBR ORDER BY pf.CAL_REST_SALES_CY DESC))) AS CAL_REST_SALES_CY
    , IFF(pf.CAL_REST_TRANS_CY <> 0.00, pf.CAL_REST_TRANS_CY, (FIRST_VALUE(pf.CAL_REST_TRANS_CY) OVER (PARTITION BY pf.BUSINESS_DT, pf.BRAND, pf.STORE_NBR ORDER BY pf.CAL_REST_TRANS_CY DESC))) AS CAL_REST_TRANS_CY
FROM
    pre_final pf
INNER JOIN
    IDH_DEV.SHARED.DATE_DIM_V dd
ON  dd.CALENDAR_DT = pf.BUSINESS_DT
LEFT OUTER JOIN
    IDH_DEV.OPERATION.LOCATION_HIERARCHY_V lv
ON  lv.LOCATION_ID = pf.STORE_NBR
AND lv.BRAND_ID = pf.BRAND_ID
INNER JOIN
    IDH_DEV.SHARED.STORE_SCD_V st
ON  st.STORE_ID = pf.STORE_NBR
AND st.BRAND_ID = pf.BRAND_ID
AND pf.BUSINESS_DT BETWEEN st.EFFECTIVE_BEGIN_DT AND st.EFFECTIVE_END_DT
AND IFNULL(st.CLOSURE_DT, ''9999-12-31'') >= (SELECT DATE_TRUNC(''YEAR'', MIN(DT)) AS Ref_Date FROM (SELECT MIN(MIN_FISCAL_COMPARABLE_DT) AS DT FROM fisc_interval UNION SELECT MIN(MIN_CAL_COMPARABLE_DT) AS DT FROM cal_interval))
AND st.COUNTRY_NM IN (''US'', ''USA'')
WHERE
    pf.BUSINESS_DT BETWEEN (SELECT MIN(MIN_FISCAL_WEEK_START_DT) FROM CY_interval) AND (SELECT MAX(MAX_FISCAL_WEEK_END_DT) FROM CY_interval)
)

SELECT
    fsc_CY.FISCAL_WEEK_NBR AS FISC_WEEK_NBR
    , fsc_CY.FISCAL_WEEK_START_DT AS WEEK_START_DT
    , fsc_CY.FISCAL_WEEK_END_DT AS WEEK_END_DT
    , pfw.BRAND
    , pfw.STORE_NBR

    , MAX(pfw.DMA_CD) AS DMA_CD
    , MAX(pfw.DMA_NM) AS DMA_NM

    , MAX(pfw.L1NAME) AS L1NAME
    , MAX(pfw.L2NAME) AS L2NAME
    , MAX(pfw.L3NAME) AS L3NAME
    , MAX(pfw.L4NAME) AS L4NAME
    , MAX(pfw.L5NAME) AS L5NAME

    , MAX(pfw.OWNERSHIP_TYP) AS OWNERSHIP_TYP
    , MAX(pfw.STATE) AS STATE
    , MAX(pfw.COUNTRY) AS COUNTRY

    , pfw.FISC_YEAR_NBR
    , pfw.FISC_QUARTER_NBR
    , pfw.FISC_PERIOD_NBR
    
    , pfw.MDM_PRODUCT_ID
    , MAX(pfw.MDM_PRODUCT_NM) AS MDM_PRODUCT_NM
    , MAX(pfw.PRODUCT_HIERARCHY_ID) AS PRODUCT_HIERARCHY_ID
    , MAX(pfw.LEVEL5_PRODUCT_HIERARCHY_NM) AS LEVEL5_PRODUCT_HIERARCHY_NM
    , MAX(pfw.LEVEL4_PRODUCT_HIERARCHY_NM) AS LEVEL4_PRODUCT_HIERARCHY_NM
    , MAX(pfw.LEVEL3_PRODUCT_HIERARCHY_NM) AS LEVEL3_PRODUCT_HIERARCHY_NM
    , MAX(pfw.LEVEL2_PRODUCT_HIERARCHY_NM) AS LEVEL2_PRODUCT_HIERARCHY_NM
    , MAX(pfw.LEVEL1_PRODUCT_HIERARCHY_NM) AS LEVEL1_PRODUCT_HIERARCHY_NM
    , MAX(pfw.PRODUCT_MISC1) AS PRODUCT_MISC1
    , MAX(pfw.PRODUCT_MISC2) AS PRODUCT_MISC2
    , MAX(pfw.PRODUCT_MISC3) AS PRODUCT_MISC3
    , MAX(pfw.PRODUCT_MISC4) AS PRODUCT_MISC4
    , MAX(pfw.PRODUCT_MISC5) AS PRODUCT_MISC5
    , MAX(pfw.PRODUCT_MISC6) AS PRODUCT_MISC6
    , MAX(pfw.PRODUCT_MISC7) AS PRODUCT_MISC7
    , MAX(pfw.PRODUCT_MISC8) AS PRODUCT_MISC8
    , MAX(pfw.PRODUCT_MISC9) AS PRODUCT_MISC9
    , MAX(pfw.PRODUCT_MISC10) AS PRODUCT_MISC10

    , CAST(SUM(pfw.PRODUCT_SALES_CY) AS NUMBER(38, 2)) AS PRODUCT_SALES_CY
    , SUM(pfw.PRODUCT_CNT_CY) AS PRODUCT_CNT_CY
    , CAST(SUM(pfw.CHECK_SALES_CY) AS NUMBER(38, 2)) AS CHECK_SALES_CY
    , SUM(pfw.CHECK_CNT_CY) AS CHECK_CNT_CY
    , CAST(MAX(cy.REST_SALES_CY) AS NUMBER(38, 2)) AS REST_SALES_CY
    , MAX(cy.REST_TRANS_CY) AS REST_TRANS_CY
    
    , fsc_LY.FISCAL_WEEK_START_DT AS FISC_WEEK_START_DT_LY
    , fsc_LY.FISCAL_WEEK_END_DT AS FISC_WEEK_END_DT_LY
    , CAST(SUM(pfw.FISC_PRODUCT_SALES_CY) AS NUMBER(38, 2)) AS FISC_PRODUCT_SALES_LY
    , SUM(pfw.FISC_PRODUCT_CNT_CY) AS FISC_PRODUCT_CNT_LY
    , CAST(SUM(FISC_CHECK_SALES_CY) AS NUMBER(38, 2)) AS FISC_CHECK_SALES_LY
    , SUM(FISC_CHECK_CNT_CY) FISC_CHECK_CNT_LY
    , CAST(MAX(f_ly.FISC_REST_SALES_CY) AS NUMBER(38, 2)) AS FISC_REST_SALES_LY
    , MAX(f_ly.FISC_REST_TRANS_CY) AS FISC_REST_TRANS_LY
    
    , cal_LY.CALENDAR_WEEK_START_DT AS CAL_WEEK_START_DT_LY
    , cal_LY.CALENDAR_WEEK_END_DT AS CAL_WEEK_END_DT_LY
    , CAST(SUM(pfw.CAL_PRODUCT_SALES_CY) AS NUMBER(38, 2)) AS CAL_PRODUCT_SALES_LY
    , SUM(pfw.CAL_PRODUCT_CNT_CY) AS CAL_PRODUCT_CNT_LY
    , CAST(SUM(pfw.CAL_CHECK_SALES_CY) AS NUMBER(38, 2)) AS CAL_CHECK_SALES_LY
    , SUM(pfw.CAL_CHECK_CNT_CY) AS CAL_CHECK_CNT_LY
    , CAST(MAX(c_ly.CAL_REST_SALES_CY) AS NUMBER(38, 2)) AS CAL_REST_SALES_LY
    , MAX(c_ly.CAL_REST_TRANS_CY) AS CAL_REST_TRANS_LY
    
FROM
    pre_final_week pfw
INNER JOIN
    IDH_DEV.SHARED.DATE_DIM_V fsc_CY
ON  fsc_CY.CALENDAR_DT = pfw.BUSINESS_DT
INNER JOIN
    IDH_DEV.SHARED.DATE_DIM_V fsc_LY
ON  fsc_LY.CALENDAR_DT = pfw.FISC_DATE_LY
INNER JOIN
    IDH_DEV.SHARED.DATE_DIM_V cal_LY
ON  cal_LY.CALENDAR_DT = pfw.CAL_COMP_DATE_LY

LEFT OUTER JOIN
(
  SELECT 
    pf.BRAND
    , pf.STORE_NBR
    , fsc_CY.FISCAL_WEEK_START_DT
    , fsc_CY.FISCAL_WEEK_END_DT
    , SUM(REST_SALES_CY) AS REST_SALES_CY
    , SUM(REST_TRANS_CY) AS REST_TRANS_CY
FROM 
    pre_final_week pf 
INNER JOIN
    IDH_DEV.SHARED.DATE_DIM_V fsc_CY
ON  fsc_CY.CALENDAR_DT = pf.BUSINESS_DT
WHERE
    Rn = 1
GROUP BY
    pf.BRAND
    , pf.STORE_NBR
    , fsc_CY.FISCAL_WEEK_START_DT
    , fsc_CY.FISCAL_WEEK_END_DT
) cy 
ON  cy.BRAND = pfw.BRAND 
AND cy.STORE_NBR = pfw.STORE_NBR 
AND cy.FISCAL_WEEK_START_DT = fsc_CY.FISCAL_WEEK_START_DT
AND cy.FISCAL_WEEK_END_DT = fsc_CY.FISCAL_WEEK_END_DT

LEFT OUTER JOIN
(
  SELECT 
    pf.BRAND
    , pf.STORE_NBR
    , fsc_LY.FISCAL_WEEK_START_DT
    , fsc_LY.FISCAL_WEEK_END_DT
    , SUM(FISC_REST_SALES_CY) AS FISC_REST_SALES_CY
    , SUM(FISC_REST_TRANS_CY) AS FISC_REST_TRANS_CY
FROM 
    pre_final_week pf
INNER JOIN
    IDH_DEV.SHARED.DATE_DIM_V fsc_LY
ON  fsc_LY.CALENDAR_DT = pf.FISC_DATE_LY
WHERE
    Rn = 1
GROUP BY
    pf.BRAND
    , pf.STORE_NBR
    , fsc_LY.FISCAL_WEEK_START_DT
    , fsc_LY.FISCAL_WEEK_END_DT
) f_ly
ON  f_ly.BRAND = pfw.BRAND 
AND f_ly.STORE_NBR = pfw.STORE_NBR 
AND f_ly.FISCAL_WEEK_START_DT = fsc_LY.FISCAL_WEEK_START_DT
AND f_ly.FISCAL_WEEK_END_DT = fsc_LY.FISCAL_WEEK_END_DT

LEFT OUTER JOIN
(
  SELECT 
    pf.BRAND
    , pf.STORE_NBR
    , cal_LY.CALENDAR_WEEK_START_DT
    , cal_LY.CALENDAR_WEEK_END_DT
    , SUM(CAL_REST_SALES_CY) AS CAL_REST_SALES_CY
    , SUM(CAL_REST_TRANS_CY) AS CAL_REST_TRANS_CY
FROM 
    pre_final_week pf
INNER JOIN
    IDH_DEV.SHARED.DATE_DIM_V cal_LY
ON  cal_LY.CALENDAR_DT = pf.CAL_COMP_DATE_LY
WHERE
    Rn = 1
GROUP BY
    pf.BRAND
    , pf.STORE_NBR
    , cal_LY.CALENDAR_WEEK_START_DT
    , cal_LY.CALENDAR_WEEK_END_DT
) c_ly
ON  c_ly.BRAND = pfw.BRAND 
AND c_ly.STORE_NBR = pfw.STORE_NBR 
AND c_ly.CALENDAR_WEEK_START_DT = cal_LY.CALENDAR_WEEK_START_DT
AND c_ly.CALENDAR_WEEK_END_DT = cal_LY.CALENDAR_WEEK_END_DT

GROUP BY
    fsc_CY.FISCAL_WEEK_NBR
    , fsc_CY.FISCAL_WEEK_START_DT
    , fsc_CY.FISCAL_WEEK_END_DT
    , pfw.BRAND
    , pfw.STORE_NBR
    , pfw.FISC_YEAR_NBR
    , pfw.FISC_QUARTER_NBR
    , pfw.FISC_PERIOD_NBR
    , pfw.MDM_PRODUCT_ID
    , fsc_LY.FISCAL_WEEK_START_DT
    , fsc_LY.FISCAL_WEEK_END_DT
    , cal_LY.CALENDAR_WEEK_START_DT
    , cal_LY.CALENDAR_WEEK_END_DT

  ';
CREATE FUNCTION IF NOT EXISTS INSPIRE_WEEKLY_PRODUCT_SALES("FROMDATE" DATE, "TODATE" DATE)
RETURNS TABLE ("AGG_LEVEL" VARCHAR(16777216), "FISCAL_WEEK_START_DT" DATE, "FISCAL_WEEK_END_DT" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_CD" VARCHAR(16777216), "DMA_NM" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "MDM_PRODUCT_ID" NUMBER(38,0), "MDM_PRODUCT_NM" VARCHAR(16777216), "PRODUCT_HIERARCHY_ID" NUMBER(38,0), "LEVEL5_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL4_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL3_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL2_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL1_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "PRODUCT_MISC1" VARCHAR(16777216), "PRODUCT_MISC2" VARCHAR(16777216), "PRODUCT_MISC3" VARCHAR(16777216), "PRODUCT_MISC4" VARCHAR(16777216), "PRODUCT_MISC5" VARCHAR(16777216), "PRODUCT_MISC6" VARCHAR(16777216), "PRODUCT_MISC7" VARCHAR(16777216), "PRODUCT_MISC8" VARCHAR(16777216), "PRODUCT_MISC9" VARCHAR(16777216), "PRODUCT_MISC10" VARCHAR(16777216), "PRODUCT_SALES_CY" NUMBER(38,2), "PRODUCT_CNT_CY" NUMBER(38,0), "CHECK_SALES_CY" NUMBER(38,2), "CHECK_CNT_CY" NUMBER(38,0), "REST_SALES_CY" NUMBER(38,2), "REST_TRANS_CY" NUMBER(38,0), "FISC_DATE_LY" DATE, "FISC_PRODUCT_SALES_LY" NUMBER(38,2), "FISC_PRODUCT_CNT_LY" NUMBER(38,0), "FISC_CHECK_SALES_LY" NUMBER(38,2), "FISC_CHECK_CNT_LY" NUMBER(38,0), "FISC_REST_SALES_LY" NUMBER(38,2), "FISC_REST_TRANS_LY" NUMBER(38,0), "CAL_COMP_DATE_LY" DATE, "CAL_PRODUCT_SALES_LY" NUMBER(38,2), "CAL_PRODUCT_CNT_LY" NUMBER(38,0), "CAL_CHECK_SALES_LY" NUMBER(38,2), "CAL_CHECK_CNT_LY" NUMBER(38,0), "CAL_REST_SALES_LY" NUMBER(38,2), "CAL_REST_TRANS_LY" NUMBER(38,0))
LANGUAGE SQL
AS '

WITH date_interval AS
(
    SELECT 
        MIN(FISCAL_WEEK_START_DT) AS MIN_FISCAL_WEEK_START_DT
        , MAX(FISCAL_WEEK_END_DT) AS MAX_FISCAL_WEEK_END_DT
FROM 
        IDH_DEV.SHARED.DATE_DIM_V dd 
WHERE 
    CALENDAR_DT BETWEEN FromDate AND ToDate
GROUP BY
    FISCAL_WEEK_NBR
)
, src_current_period AS
(
    SELECT
        od.ORDER_ID
      , od.ORDERLINE_ID
      , od.ORDER_DT AS BUSINESS_DT
      , od.STORE_ID AS STORE_NBR
      , MAX(IFNULL(od.MDM_PRODUCT_ID, 0)) OVER(PARTITION BY MDM_PRODUCT_ID) AS MDM_PRODUCT_ID
      , MAX(IFNULL(od.PRODUCT_NM, '''')) OVER(PARTITION BY MDM_PRODUCT_ID) AS MDM_PRODUCT_NM
      , IFNULL(od.PRODUCT_HIERARCHY_ID, 0) AS PRODUCT_HIERARCHY_ID
      , IFNULL(od.LEVEL5_PRODUCT_HIERARCHY_NM, '''') AS LEVEL5_PRODUCT_HIERARCHY_NM
      , IFNULL(od.LEVEL4_PRODUCT_HIERARCHY_NM, '''') AS LEVEL4_PRODUCT_HIERARCHY_NM
      , IFNULL(od.LEVEL3_PRODUCT_HIERARCHY_NM, '''') AS LEVEL3_PRODUCT_HIERARCHY_NM
      , IFNULL(od.LEVEL2_PRODUCT_HIERARCHY_NM, '''') AS LEVEL2_PRODUCT_HIERARCHY_NM
      , IFNULL(od.LEVEL1_PRODUCT_HIERARCHY_NM, '''') AS LEVEL1_PRODUCT_HIERARCHY_NM
      , IFNULL(od.PRODUCT_MISC1, '''') AS PRODUCT_MISC1
      , IFNULL(od.PRODUCT_MISC2, '''') AS PRODUCT_MISC2
      , IFNULL(od.PRODUCT_MISC3, '''') AS PRODUCT_MISC3
      , IFNULL(od.PRODUCT_MISC4, '''') AS PRODUCT_MISC4
      , IFNULL(od.PRODUCT_MISC5, '''') AS PRODUCT_MISC5
      , IFNULL(od.PRODUCT_MISC6, '''') AS PRODUCT_MISC6
      , IFNULL(od.PRODUCT_MISC7, '''') AS PRODUCT_MISC7
      , IFNULL(od.PRODUCT_MISC8, '''') AS PRODUCT_MISC8
      , IFNULL(od.PRODUCT_MISC9, '''') AS PRODUCT_MISC9
      , IFNULL(od.PRODUCT_MISC10, '''') AS PRODUCT_MISC10
      , DERIVED_GROSS_QTY
      , DERIVED_NET_AMT
      , SUM(DERIVED_NET_AMT) OVER(PARTITION BY ORDER_ID) AS ORDER_MDM_PRODUCT_ID
      , ROW_NUMBER() OVER (PARTITION BY ORDER_ID ORDER BY ORDER_ID) AS SELECTED_ORDER_ID
      , od.BRAND_ID
      , CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
           WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
           WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
           WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
           WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
           WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
           WHEN od.BRAND_ID = ''rto'' THEN ''RT''
           ELSE ''UNKNOWN'' END AS BRAND
      , od.LOAD_DT
      , od.LAST_UPDATED_DTTM
    FROM
        ORDER_DETAIL_V od
    WHERE
        IFNULL((CASE WHEN UPPER(CAST(VOIDED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(VOIDED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND IFNULL((CASE WHEN UPPER(CAST(CLEARED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(CLEARED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND IFNULL((CASE WHEN UPPER(CAST(DELETED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(DELETED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND od.ORDER_DT BETWEEN (SELECT MIN(MIN_FISCAL_WEEK_START_DT) FROM date_interval) AND (SELECT MAX(MAX_FISCAL_WEEK_END_DT) FROM date_interval)
)
, src_current_period_dist_chk AS
(
    SELECT
        BRAND
      , BRAND_ID
      , STORE_NBR
      , MDM_PRODUCT_ID
      , MDM_PRODUCT_NM
      , PRODUCT_HIERARCHY_ID
      , LEVEL5_PRODUCT_HIERARCHY_NM
      , LEVEL4_PRODUCT_HIERARCHY_NM
      , LEVEL3_PRODUCT_HIERARCHY_NM
      , LEVEL2_PRODUCT_HIERARCHY_NM
      , LEVEL1_PRODUCT_HIERARCHY_NM
      , PRODUCT_MISC1
      , PRODUCT_MISC2
      , PRODUCT_MISC3
      , PRODUCT_MISC4
      , PRODUCT_MISC5
      , PRODUCT_MISC6
      , PRODUCT_MISC7
      , PRODUCT_MISC8
      , PRODUCT_MISC9
      , PRODUCT_MISC10
      , di.MIN_FISCAL_WEEK_START_DT AS WEEK_START_DT
      , di.MAX_FISCAL_WEEK_END_DT AS WEEK_END_DT
      , SUM(DERIVED_GROSS_QTY) AS DERIVED_GROSS_QTY
      , SUM(DERIVED_NET_AMT) AS DERIVED_NET_AMT
      , COUNT(DISTINCT ORDER_ID) AS ORDER_ID
    FROM
        src_current_period scp
    INNER JOIN
        date_interval di
    ON  scp.BUSINESS_DT BETWEEN di.MIN_FISCAL_WEEK_START_DT AND MAX_FISCAL_WEEK_END_DT
    GROUP BY
        BRAND
      , BRAND_ID
      , STORE_NBR
      , MDM_PRODUCT_ID
      , MDM_PRODUCT_NM
      , PRODUCT_HIERARCHY_ID
      , LEVEL5_PRODUCT_HIERARCHY_NM
      , LEVEL4_PRODUCT_HIERARCHY_NM
      , LEVEL3_PRODUCT_HIERARCHY_NM
      , LEVEL2_PRODUCT_HIERARCHY_NM
      , LEVEL1_PRODUCT_HIERARCHY_NM
      , PRODUCT_MISC1
      , PRODUCT_MISC2
      , PRODUCT_MISC3
      , PRODUCT_MISC4
      , PRODUCT_MISC5
      , PRODUCT_MISC6
      , PRODUCT_MISC7
      , PRODUCT_MISC8
      , PRODUCT_MISC9
      , PRODUCT_MISC10
      , di.MIN_FISCAL_WEEK_START_DT
      , di.MAX_FISCAL_WEEK_END_DT
)
, chk AS
(
SELECT DISTINCT
    ORDER_ID
    , BRAND
    , BRAND_ID
    , STORE_NBR
    , BUSINESS_DT
    , MDM_PRODUCT_ID
    , ORDER_MDM_PRODUCT_ID 
FROM 
    src_current_period
)
, tot AS
(
SELECT
    BUSINESS_DT
    , BRAND
    , BRAND_ID
    , STORE_NBR
    , SUM(DERIVED_NET_AMT) AS CHECK_SALES_CY
    , COUNT(DISTINCT ORDER_ID) AS CHECK_CNT_CY
FROM
    src_current_period
GROUP BY
    BUSINESS_DT
    , BRAND
    , BRAND_ID
    , STORE_NBR
)
, results AS
(
SELECT
    s.BRAND
    , s.BRAND_ID
    , s.STORE_NBR
    , s.MDM_PRODUCT_ID
    , s.MDM_PRODUCT_NM AS MDM_PRODUCT_NM
    , s.PRODUCT_HIERARCHY_ID AS PRODUCT_HIERARCHY_ID
    , s.LEVEL5_PRODUCT_HIERARCHY_NM AS LEVEL5_PRODUCT_HIERARCHY_NM
    , s.LEVEL4_PRODUCT_HIERARCHY_NM AS LEVEL4_PRODUCT_HIERARCHY_NM
    , s.LEVEL3_PRODUCT_HIERARCHY_NM AS LEVEL3_PRODUCT_HIERARCHY_NM
    , s.LEVEL2_PRODUCT_HIERARCHY_NM AS LEVEL2_PRODUCT_HIERARCHY_NM
    , s.LEVEL1_PRODUCT_HIERARCHY_NM AS LEVEL1_PRODUCT_HIERARCHY_NM
    , s.PRODUCT_MISC1 AS PRODUCT_MISC1
    , s.PRODUCT_MISC2 AS PRODUCT_MISC2
    , s.PRODUCT_MISC3 AS PRODUCT_MISC3
    , s.PRODUCT_MISC4 AS PRODUCT_MISC4
    , s.PRODUCT_MISC5 AS PRODUCT_MISC5
    , s.PRODUCT_MISC6 AS PRODUCT_MISC6
    , s.PRODUCT_MISC7 AS PRODUCT_MISC7
    , s.PRODUCT_MISC8 AS PRODUCT_MISC8
    , s.PRODUCT_MISC9 AS PRODUCT_MISC9
    , s.PRODUCT_MISC10 AS PRODUCT_MISC10
    , s.WEEK_START_DT AS WEEK_START_DT
    , s.WEEK_END_DT AS WEEK_END_DT
    , dd.FISCAL_COMPARABLE_DT AS FISC_DATE_LY
    , dd.CALENDAR_COMPARABLE_DT AS CAL_COMP_DATE_LY
    , s.DERIVED_NET_AMT AS PRODUCT_SALES_CY
    , s.DERIVED_GROSS_QTY AS PRODUCT_CNT_CY
    , (SELECT SUM(ch.ORDER_MDM_PRODUCT_ID) FROM chk ch WHERE ch.BRAND = s.BRAND AND ch.BRAND_ID = s.BRAND_ID AND ch.STORE_NBR = s.STORE_NBR AND ch.MDM_PRODUCT_ID = s.MDM_PRODUCT_ID AND ch.BUSINESS_DT BETWEEN s.WEEK_START_DT AND s.WEEK_END_DT)  AS CHECK_SALES_CY
    , (SELECT COUNT(DISTINCT ORDER_ID) FROM chk ch WHERE ch.BRAND = s.BRAND AND ch.BRAND_ID = s.BRAND_ID AND ch.STORE_NBR = s.STORE_NBR AND ch.MDM_PRODUCT_ID = s.MDM_PRODUCT_ID AND ch.BUSINESS_DT BETWEEN s.WEEK_START_DT AND s.WEEK_END_DT)  AS CHECK_CNT_CY
    , (SELECT SUM(t.CHECK_SALES_CY) FROM tot t WHERE t.BRAND = s.BRAND AND t.BRAND_ID = s.BRAND_ID AND t.STORE_NBR = s.STORE_NBR AND t.BUSINESS_DT BETWEEN s.WEEK_START_DT AND s.WEEK_END_DT)  AS REST_SALES_CY
    , (SELECT SUM(t.CHECK_CNT_CY) FROM tot t WHERE t.BRAND = s.BRAND AND t.BRAND_ID = s.BRAND_ID AND t.STORE_NBR = s.STORE_NBR AND t.BUSINESS_DT BETWEEN s.WEEK_START_DT AND s.WEEK_END_DT)  AS REST_TRANS_CY
    , dd.FISCAL_YEAR_NBR AS FISC_YEAR_NBR
    , dd.FISCAL_QUARTER_NBR AS FISC_QUARTER_NBR
    , dd.FISCAL_PERIOD_NBR AS FISC_PERIOD_NBR
    , dd.FISCAL_WEEK_NBR AS FISC_WEEK_NBR
FROM
    src_current_period_dist_chk s
INNER JOIN
    IDH_DEV.SHARED.DATE_DIM_V dd
ON  dd.CALENDAR_DT = s.WEEK_START_DT
)

SELECT
    ''WEEK'' AS AGG_LEVEL
    , r.WEEK_START_DT AS WEEK_START_DT
    , r.WEEK_END_DT AS WEEK_END_DT
    , r.BRAND
    , r.STORE_NBR
    , st.DMA_CD
    , st.DMA_NM
    , IFNULL(lv.LEVEL1_NM, '''') AS L1NAME
    , IFNULL(lv.LEVEL2_NM, '''') AS L2NAME
    , IFNULL(lv.LEVEL3_NM, '''') AS L3NAME
    , IFNULL(lv.LEVEL4_NM, '''') AS L4NAME
    , IFNULL(lv.LEVEL5_NM, '''') AS L5NAME
    , st.OWNERSHIP_TYP AS OWNERSHIP_TYP
    , st.STATE_NM AS STATE
    , st.COUNTRY_NM AS COUNTRY
    , r.FISC_YEAR_NBR AS FISC_YEAR_NBR
    , r.FISC_QUARTER_NBR AS FISC_QUARTER_NBR
    , r.FISC_PERIOD_NBR AS FISC_PERIOD_NBR
    , r.FISC_WEEK_NBR AS FISC_WEEK_NBR
    , r.MDM_PRODUCT_ID
    , r.MDM_PRODUCT_NM
    , r.PRODUCT_HIERARCHY_ID
    , r.LEVEL5_PRODUCT_HIERARCHY_NM
    , r.LEVEL4_PRODUCT_HIERARCHY_NM
    , r.LEVEL3_PRODUCT_HIERARCHY_NM
    , r.LEVEL2_PRODUCT_HIERARCHY_NM
    , r.LEVEL1_PRODUCT_HIERARCHY_NM
    , r.PRODUCT_MISC1
    , r.PRODUCT_MISC2
    , r.PRODUCT_MISC3
    , r.PRODUCT_MISC4
    , r.PRODUCT_MISC5
    , r.PRODUCT_MISC6
    , r.PRODUCT_MISC7
    , r.PRODUCT_MISC8
    , r.PRODUCT_MISC9
    , r.PRODUCT_MISC10
    , r.PRODUCT_SALES_CY
    , r.PRODUCT_CNT_CY
    , r.CHECK_SALES_CY
    , r.CHECK_CNT_CY
    , r.REST_SALES_CY
    , r.REST_TRANS_CY
    , r.FISC_DATE_LY
    , IFNULL(fsc.FISC_PRODUCT_SALES_LY, 0.00) AS FISC_PRODUCT_SALES_LY
    , IFNULL(fsc.FISC_PRODUCT_CNT_LY, 0) AS FISC_PRODUCT_CNT_LY
    , IFNULL(fsc.FISC_CHECK_SALES_LY, 0.00) AS FISC_CHECK_SALES_LY
    , IFNULL(fsc.FISC_CHECK_CNT_LY, 0) AS FISC_CHECK_CNT_LY
    , IFNULL(fsc.FISC_REST_SALES_LY, 0.00) AS FISC_REST_SALES_LY
    , IFNULL(fsc.FISC_REST_TRANS_LY, 0.00) AS FISC_REST_TRANS_LY
    , r.CAL_COMP_DATE_LY
    , IFNULL(cln.CAL_PRODUCT_SALES_LY, 0.00) AS CAL_PRODUCT_SALES_LY
    , IFNULL(cln.CAL_PRODUCT_CNT_LY, 0) AS CAL_PRODUCT_CNT_LY
    , IFNULL(cln.CAL_CHECK_SALES_LY, 0.00) AS CAL_CHECK_SALES_LY
    , IFNULL(cln.CAL_CHECK_CNT_LY, 0) AS CAL_CHECK_CNT_LY
    , IFNULL(cln.CAL_REST_SALES_LY, 0.00) AS CAL_REST_SALES_LY
    , IFNULL(cln.CAL_REST_TRANS_LY, 0.00) AS CAL_REST_TRANS_LY
FROM
    results r
LEFT OUTER JOIN
    IDH_DEV.SHARED.STORE_SCD_V st
ON  st.STORE_ID = r.STORE_NBR
AND st.BRAND_ID = r.BRAND_ID
AND st.CURRENT_IND = 1
LEFT OUTER JOIN 
    IDH_DEV.OPERATION.LOCATION_HIERARCHY_V lv
ON  lv.LOCATION_ID = r.STORE_NBR
AND lv.BRAND_ID = r.BRAND_ID
LEFT OUTER JOIN
    TABLE(INSPIRE_DAILY_PRODUCT_SALES_FISC(TO_DATE(FromDate), TO_DATE(ToDate))) fsc
ON  fsc.BRAND = r.BRAND
AND fsc.STORE_NBR = r.STORE_NBR
AND fsc.MDM_PRODUCT_ID = r.MDM_PRODUCT_ID
AND fsc.FISC_DATE_LY = r.FISC_DATE_LY
LEFT OUTER JOIN
    TABLE(INSPIRE_DAILY_PRODUCT_SALES_CAL(TO_DATE(FromDate), TO_DATE(ToDate))) cln
ON  cln.BRAND = r.BRAND
AND cln.STORE_NBR = r.STORE_NBR
AND cln.MDM_PRODUCT_ID = r.MDM_PRODUCT_ID
AND cln.CAL_DATE_LY = r.CAL_COMP_DATE_LY

';
CREATE FUNCTION IF NOT EXISTS INSPIRE_WEEKLY_PRODUCT_SALES_NUMBER("FISCAL_YEAR_NUMBER" NUMBER(38,0), "FROM_FISCAL_WEEK_NUMBER" NUMBER(38,0), "TO_FISCAL_WEEK_NUMBER" NUMBER(38,0))
RETURNS TABLE ("AGG_LEVEL" VARCHAR(16777216), "FISCAL_WEEK_START_DT" DATE, "FISCAL_WEEK_END_DT" DATE, "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_CD" VARCHAR(16777216), "DMA_NM" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "DAY_OF_WEEK" VARCHAR(16777216), "HOLIDAY_IND_CY" BOOLEAN, "HOLIDAY_NM_CY" VARCHAR(16777216), "MDM_PRODUCT_ID" NUMBER(38,0), "MDM_PRODUCT_NM" VARCHAR(16777216), "PARENT_PRODUCT_ID" NUMBER(38,0), "PARENT_PRODUCT_NM" VARCHAR(16777216), "PRODUCT_HIERARCHY_ID" NUMBER(38,0), "LEVEL5_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL4_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL3_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL2_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "LEVEL1_PRODUCT_HIERARCHY_NM" VARCHAR(16777216), "PRODUCT_MISC1" VARCHAR(16777216), "PRODUCT_MISC2" VARCHAR(16777216), "PRODUCT_MISC3" VARCHAR(16777216), "PRODUCT_MISC4" VARCHAR(16777216), "PRODUCT_MISC5" VARCHAR(16777216), "PRODUCT_MISC6" VARCHAR(16777216), "PRODUCT_MISC7" VARCHAR(16777216), "PRODUCT_MISC8" VARCHAR(16777216), "PRODUCT_MISC9" VARCHAR(16777216), "PRODUCT_MISC10" VARCHAR(16777216), "PRODUCT_SALES_CY" NUMBER(38,2), "PRODUCT_CNT_CY" NUMBER(38,0), "CHECK_SALES_CY" NUMBER(38,2), "CHECK_CNT_CY" NUMBER(38,0), "REST_SALES_CY" NUMBER(38,2), "REST_TRANS_CY" NUMBER(38,0), "FISC_DATE_LY" DATE, "FISC_HOLIDAY_IND_LY" BOOLEAN, "FISC_HOLIDAY_NM_LY" VARCHAR(16777216), "FISC_PRODUCT_SALES_LY" NUMBER(38,2), "FISC_PRODUCT_CNT_LY" NUMBER(38,0), "FISC_CHECK_SALES_LY" NUMBER(38,2), "FISC_CHECK_CNT_LY" NUMBER(38,0), "FISC_REST_SALES_LY" NUMBER(38,2), "FISC_REST_TRANS_LY" NUMBER(38,0), "CAL_COMP_DATE_LY" DATE, "CAL_HOLIDAY_IND_LY" BOOLEAN, "CAL_HOLIDAY_NM_LY" VARCHAR(16777216), "CAL_PRODUCT_SALES_LY" NUMBER(38,2), "CAL_PRODUCT_CNT_LY" NUMBER(38,0), "CAL_CHECK_SALES_LY" NUMBER(38,2), "CAL_CHECK_CNT_LY" NUMBER(38,0), "CAL_REST_SALES_LY" NUMBER(38,2), "CAL_REST_TRANS_LY" NUMBER(38,0))
LANGUAGE SQL
AS '

WITH date_interval AS
(
    SELECT 
        MIN(FISCAL_WEEK_START_DT) AS MIN_FISCAL_WEEK_START_DT
        , MAX(FISCAL_WEEK_END_DT) AS MAX_FISCAL_WEEK_END_DT
    FROM 
        IDH_DEV.SHARED.DATE_DIM_V dd 
    WHERE
        FISCAL_YEAR_NBR = FISCAL_YEAR_Number
    AND FISCAL_WEEK_NBR BETWEEN FROM_FISCAL_WEEK_Number AND TO_FISCAL_WEEK_Number
    
)
, src_current_period AS
(
    SELECT
        od.ORDER_ID
      , od.ORDERLINE_ID
      , od.ORDER_DT AS BUSINESS_DT
      , od.STORE_ID AS STORE_NBR
      , IFNULL(od.MDM_PRODUCT_ID, 0) AS MDM_PRODUCT_ID
      , IFNULL(od.PRODUCT_NM, '''') AS MDM_PRODUCT_NM
      , IFNULL(od.MDM_PARENT_ITEM_ID, 0) AS PARENT_PRODUCT_ID
      , IFNULL(od.PARENT_ITEM_NM, '''') AS PARENT_PRODUCT_NM
      , IFNULL(od.PRODUCT_HIERARCHY_ID, 0) AS PRODUCT_HIERARCHY_ID
      , IFNULL(od.LEVEL5_PRODUCT_HIERARCHY_NM, '''') AS LEVEL5_PRODUCT_HIERARCHY_NM
      , IFNULL(od.LEVEL4_PRODUCT_HIERARCHY_NM, '''') AS LEVEL4_PRODUCT_HIERARCHY_NM
      , IFNULL(od.LEVEL3_PRODUCT_HIERARCHY_NM, '''') AS LEVEL3_PRODUCT_HIERARCHY_NM
      , IFNULL(od.LEVEL2_PRODUCT_HIERARCHY_NM, '''') AS LEVEL2_PRODUCT_HIERARCHY_NM
      , IFNULL(od.LEVEL1_PRODUCT_HIERARCHY_NM, '''') AS LEVEL1_PRODUCT_HIERARCHY_NM
      , IFNULL(od.PRODUCT_MISC1, '''') AS PRODUCT_MISC1
      , IFNULL(od.PRODUCT_MISC2, '''') AS PRODUCT_MISC2
      , IFNULL(od.PRODUCT_MISC3, '''') AS PRODUCT_MISC3
      , IFNULL(od.PRODUCT_MISC4, '''') AS PRODUCT_MISC4
      , IFNULL(od.PRODUCT_MISC5, '''') AS PRODUCT_MISC5
      , IFNULL(od.PRODUCT_MISC6, '''') AS PRODUCT_MISC6
      , IFNULL(od.PRODUCT_MISC7, '''') AS PRODUCT_MISC7
      , IFNULL(od.PRODUCT_MISC8, '''') AS PRODUCT_MISC8
      , IFNULL(od.PRODUCT_MISC9, '''') AS PRODUCT_MISC9
      , IFNULL(od.PRODUCT_MISC10, '''') AS PRODUCT_MISC10
      , DERIVED_GROSS_QTY
      , DERIVED_NET_AMT
      , od.BRAND_ID
      , CASE WHEN od.BRAND_ID = ''arbys'' THEN ''ARB''
           WHEN od.BRAND_ID = ''sonic'' THEN ''SON''
           WHEN od.BRAND_ID = ''bww'' THEN ''BWW''
           WHEN od.BRAND_ID = ''jj'' THEN ''JJ''
           WHEN od.BRAND_ID = ''dnkn'' THEN ''DUN''
           WHEN od.BRAND_ID = ''bskn'' THEN ''BR''
           WHEN od.BRAND_ID = ''rto'' THEN ''RT''
           ELSE ''UNKNOWN'' END AS BRAND
      , od.LOAD_DT
      , od.LAST_UPDATED_DTTM
    FROM
        ORDER_DETAIL_V od
    WHERE
        IFNULL((CASE WHEN UPPER(CAST(VOIDED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(VOIDED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND IFNULL((CASE WHEN UPPER(CAST(CLEARED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(CLEARED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND IFNULL((CASE WHEN UPPER(CAST(DELETED_IND AS VARCHAR(10))) =  ''TRUE'' THEN ''Y'' ELSE UPPER(CAST(DELETED_IND AS VARCHAR(10))) END), '''') != ''Y''
    AND od.ORDER_DT BETWEEN (SELECT MIN_FISCAL_WEEK_START_DT FROM date_interval) AND (SELECT MAX_FISCAL_WEEK_END_DT FROM date_interval)
)
, src_current_period_dist_chk AS
(
    SELECT
        ORDER_ID
      , BRAND
      , BRAND_ID
      , STORE_NBR
      , MDM_PRODUCT_ID
      , MDM_PRODUCT_NM
      , PRODUCT_HIERARCHY_ID
      , LEVEL5_PRODUCT_HIERARCHY_NM
      , LEVEL4_PRODUCT_HIERARCHY_NM
      , LEVEL3_PRODUCT_HIERARCHY_NM
      , LEVEL2_PRODUCT_HIERARCHY_NM
      , LEVEL1_PRODUCT_HIERARCHY_NM
      , PRODUCT_MISC1
      , PRODUCT_MISC2
      , PRODUCT_MISC3
      , PRODUCT_MISC4
      , PRODUCT_MISC5
      , PRODUCT_MISC6
      , PRODUCT_MISC7
      , PRODUCT_MISC8
      , PRODUCT_MISC9
      , PRODUCT_MISC10
      , BUSINESS_DT
      , DERIVED_GROSS_QTY
      , DERIVED_NET_AMT AS DERIVED_NET_AMT
      , MAX(IFNULL(PARENT_PRODUCT_ID, 0)) OVER(PARTITION BY MDM_PRODUCT_ID) AS PARENT_PRODUCT_ID
      , MAX(IFNULL(PARENT_PRODUCT_NM, '''')) OVER(PARTITION BY MDM_PRODUCT_ID) AS PARENT_PRODUCT_NM
      , SUM(DERIVED_NET_AMT) OVER(PARTITION BY ORDER_ID) AS CHECK_SALES_CY
      , ROW_NUMBER() OVER(PARTITION BY ORDER_ID, BUSINESS_DT, BRAND, STORE_NBR, MDM_PRODUCT_ID ORDER BY ORDER_ID) AS Rn
    FROM
        src_current_period
)
, results AS
(
    SELECT
      s.BRAND
      , s.BRAND_ID
      , s.STORE_NBR
      , s.MDM_PRODUCT_ID
      , IFNULL(s.MDM_PRODUCT_NM, '''') AS MDM_PRODUCT_NM
      , MAX(s.PRODUCT_HIERARCHY_ID) AS PRODUCT_HIERARCHY_ID
      , MAX(s.LEVEL5_PRODUCT_HIERARCHY_NM) AS LEVEL5_PRODUCT_HIERARCHY_NM
      , MAX(s.LEVEL4_PRODUCT_HIERARCHY_NM) AS LEVEL4_PRODUCT_HIERARCHY_NM
      , MAX(s.LEVEL3_PRODUCT_HIERARCHY_NM) AS LEVEL3_PRODUCT_HIERARCHY_NM
      , MAX(s.LEVEL2_PRODUCT_HIERARCHY_NM) AS LEVEL2_PRODUCT_HIERARCHY_NM
      , MAX(s.LEVEL1_PRODUCT_HIERARCHY_NM) AS LEVEL1_PRODUCT_HIERARCHY_NM
      , MAX(s.PRODUCT_MISC1) AS PRODUCT_MISC1
      , MAX(s.PRODUCT_MISC2) AS PRODUCT_MISC2
      , MAX(s.PRODUCT_MISC3) AS PRODUCT_MISC3
      , MAX(s.PRODUCT_MISC4) AS PRODUCT_MISC4
      , MAX(s.PRODUCT_MISC5) AS PRODUCT_MISC5
      , MAX(s.PRODUCT_MISC6) AS PRODUCT_MISC6
      , MAX(s.PRODUCT_MISC7) AS PRODUCT_MISC7
      , MAX(s.PRODUCT_MISC8) AS PRODUCT_MISC8
      , MAX(s.PRODUCT_MISC9) AS PRODUCT_MISC9
      , MAX(s.PRODUCT_MISC10) AS PRODUCT_MISC10
      , MAX(s.BUSINESS_DT) AS BUSINESS_DT
      , dd.FISCAL_WEEK_START_DT AS WEEK_START_DT
      , dd.FISCAL_WEEK_END_DT AS WEEK_END_DT
      , MAX(dd.FISCAL_COMPARABLE_DT) AS FISC_DATE_LY
      , MAX(dd.CALENDAR_COMPARABLE_DT) AS CAL_COMP_DATE_LY
      , SUM(DERIVED_NET_AMT) AS PRODUCT_SALES_CY
      , SUM(DERIVED_GROSS_QTY) AS PRODUCT_CNT_CY
      , MAX(chk.CHECK_SALES_CY) AS CHECK_SALES_CY
      , MAX(chk.CHECK_CNT_CY) AS CHECK_CNT_CY
      , MAX(tot.REST_SALES_CY) AS REST_SALES_CY
      , MAX(tot.REST_TRANS_CY) AS REST_TRANS_CY
      , MAX(dd.FISCAL_YEAR_NBR) AS FISC_YEAR_NBR
      , MAX(dd.FISCAL_QUARTER_NBR) AS FISC_QUARTER_NBR
      , MAX(dd.FISCAL_PERIOD_NBR) AS FISC_PERIOD_NBR
      , MAX(dd.FISCAL_WEEK_NBR) AS FISC_WEEK_NBR
      , MAX(dd.CALENDAR_DAY_NM) AS DAY_OF_WEEK
      , MAX(IFNULL(hlf.HOLIDAY_IND, ''N'')) AS HOLIDAY_IND_CY
      , MAX(IFNULL(hlf.HOLIDAY_LIST_NM, ''N'')) AS HOLIDAY_NM_CY
      , MAX(s.PARENT_PRODUCT_ID) AS PARENT_PRODUCT_ID
      , MAX(s.PARENT_PRODUCT_NM) AS PARENT_PRODUCT_NM
      , MAX(IFNULL(hl_cal.HOLIDAY_IND, ''N'')) AS CAL_HOLIDAY_IND_LY
      , MAX(IFNULL(hl_cal.HOLIDAY_LIST_NM, ''N'')) AS CAL_HOLIDAY_NM_LY
  FROM
      src_current_period_dist_chk s
  INNER JOIN
      IDH_DEV.SHARED.DATE_DIM_V dd
  ON  dd.CALENDAR_DT = s.BUSINESS_DT
  LEFT OUTER JOIN
      IDH_DEV.SHARED.HOLIDAY_LIST_V hlf
  ON  TO_DATE(CAST(hlf.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = dd.CALENDAR_DT
  LEFT OUTER JOIN
      IDH_DEV.SHARED.HOLIDAY_LIST_V hl_cal
  ON  TO_DATE(CAST(hl_cal.DATE_KEY AS VARCHAR(10)), ''YYYYMMDD'') = dd.CALENDAR_COMPARABLE_DT
  LEFT OUTER JOIN
  (
      SELECT
        BRAND
        , BRAND_ID
        , STORE_NBR
        , MDM_PRODUCT_ID
        , BUSINESS_DT
        , SUM(CHECK_SALES_CY) AS CHECK_SALES_CY
        , SUM(Rn) AS CHECK_CNT_CY
      FROM
          src_current_period_dist_chk
      WHERE
          Rn = 1
      GROUP BY
          BRAND
        , BRAND_ID
        , STORE_NBR
        , MDM_PRODUCT_ID
        , BUSINESS_DT
  ) chk
  ON  s.BRAND = chk.BRAND
  AND s.BRAND_ID = chk.BRAND_ID
  AND s.STORE_NBR = chk.STORE_NBR
  AND s.MDM_PRODUCT_ID = chk.MDM_PRODUCT_ID
  AND s.BUSINESS_DT = chk.BUSINESS_DT
  LEFT OUTER JOIN
  (
      SELECT
        BRAND
        , BRAND_ID
        , STORE_NBR
        , SUM(DERIVED_NET_AMT) AS REST_SALES_CY
        , COUNT(DISTINCT ORDER_ID) AS REST_TRANS_CY
      FROM
          src_current_period_dist_chk
      GROUP BY
          BRAND
        , BRAND_ID
        , STORE_NBR
  ) tot
  ON  s.BRAND = tot.BRAND
  AND s.BRAND_ID = tot.BRAND_ID
  AND s.STORE_NBR = tot.STORE_NBR
  GROUP BY
      s.BRAND
      , s.BRAND_ID
      , s.STORE_NBR
      , s.MDM_PRODUCT_ID
      , IFNULL(s.MDM_PRODUCT_NM, '''')
      , dd.FISCAL_WEEK_START_DT
      , dd.FISCAL_WEEK_END_DT
)

SELECT
    ''WEEK'' AS AGG_LEVEL
    , r.WEEK_START_DT AS WEEK_START_DT
    , r.WEEK_END_DT AS WEEK_END_DT
    , r.BRAND
    , r.STORE_NBR
    , st.DMA_CD
    , st.DMA_NM
    , IFNULL(lv.LEVEL1_NM, '''') AS L1NAME
    , IFNULL(lv.LEVEL2_NM, '''') AS L2NAME
    , IFNULL(lv.LEVEL3_NM, '''') AS L3NAME
    , IFNULL(lv.LEVEL4_NM, '''') AS L4NAME
    , IFNULL(lv.LEVEL5_NM, '''') AS L5NAME
    , st.OWNERSHIP_TYP AS OWNERSHIP_TYP
    , st.STATE_NM AS STATE
    , st.COUNTRY_NM AS COUNTRY
    , r.FISC_YEAR_NBR AS FISC_YEAR_NBR
    , r.FISC_QUARTER_NBR AS FISC_QUARTER_NBR
    , r.FISC_PERIOD_NBR AS FISC_PERIOD_NBR
    , r.FISC_WEEK_NBR AS FISC_WEEK_NBR
    , r.DAY_OF_WEEK AS DAY_OF_WEEK
    , r.HOLIDAY_IND_CY
    , r.HOLIDAY_NM_CY
    , r.MDM_PRODUCT_ID
    , r.MDM_PRODUCT_NM
    , r.PARENT_PRODUCT_ID
    , r.PARENT_PRODUCT_NM
    , r.PRODUCT_HIERARCHY_ID
    , r.LEVEL5_PRODUCT_HIERARCHY_NM
    , r.LEVEL4_PRODUCT_HIERARCHY_NM
    , r.LEVEL3_PRODUCT_HIERARCHY_NM
    , r.LEVEL2_PRODUCT_HIERARCHY_NM
    , r.LEVEL1_PRODUCT_HIERARCHY_NM
    , r.PRODUCT_MISC1
    , r.PRODUCT_MISC2
    , r.PRODUCT_MISC3
    , r.PRODUCT_MISC4
    , r.PRODUCT_MISC5
    , r.PRODUCT_MISC6
    , r.PRODUCT_MISC7
    , r.PRODUCT_MISC8
    , r.PRODUCT_MISC9
    , r.PRODUCT_MISC10
    , r.PRODUCT_SALES_CY
    , r.PRODUCT_CNT_CY
    , r.CHECK_SALES_CY
    , r.CHECK_CNT_CY
    , r.REST_SALES_CY
    , r.REST_TRANS_CY
    , r.FISC_DATE_LY
    , r.HOLIDAY_IND_CY
    , r.HOLIDAY_NM_CY
    
    , IFNULL(fsc.FISC_PRODUCT_SALES_LY, 0.00) AS FISC_PRODUCT_SALES_LY
    , IFNULL(fsc.FISC_PRODUCT_CNT_LY, 0) AS FISC_PRODUCT_CNT_LY
    , IFNULL(fsc.FISC_CHECK_SALES_LY, 0.00) AS FISC_CHECK_SALES_LY
    , IFNULL(fsc.FISC_CHECK_CNT_LY, 0) AS FISC_CHECK_CNT_LY
    , IFNULL(fsc.FISC_REST_SALES_LY, 0.00) AS FISC_REST_SALES_LY
    , IFNULL(fsc.FISC_REST_TRANS_LY, 0.00) AS FISC_REST_TRANS_LY
    , r.CAL_COMP_DATE_LY
    , r.CAL_HOLIDAY_IND_LY
    , r.CAL_HOLIDAY_NM_LY
    , IFNULL(cln.CAL_PRODUCT_SALES_LY, 0.00) AS CAL_PRODUCT_SALES_LY
    , IFNULL(cln.CAL_PRODUCT_CNT_LY, 0) AS CAL_PRODUCT_CNT_LY
    , IFNULL(cln.CAL_CHECK_SALES_LY, 0.00) AS CAL_CHECK_SALES_LY
    , IFNULL(cln.CAL_CHECK_CNT_LY, 0) AS CAL_CHECK_CNT_LY
    , IFNULL(cln.CAL_REST_SALES_LY, 0.00) AS CAL_REST_SALES_LY
    , IFNULL(cln.CAL_REST_TRANS_LY, 0.00) AS CAL_REST_TRANS_LY
FROM
    results r
LEFT OUTER JOIN
    IDH_DEV.SHARED.STORE_SCD_V st
ON  st.STORE_ID = r.STORE_NBR
AND st.BRAND_ID = r.BRAND_ID
AND r.BUSINESS_DT BETWEEN st.EFFECTIVE_BEGIN_DT AND st.EFFECTIVE_END_DT    
LEFT OUTER JOIN 
    IDH_DEV.OPERATION.LOCATION_HIERARCHY_V lv
ON  lv.LOCATION_ID = r.STORE_NBR
AND lv.BRAND_ID = r.BRAND_ID
LEFT OUTER JOIN
    TABLE(INSPIRE_DAILY_PRODUCT_SALES_FISC((SELECT MIN_FISCAL_WEEK_START_DT FROM date_interval), (SELECT MAX_FISCAL_WEEK_END_DT FROM date_interval))) fsc
ON  fsc.BRAND = r.BRAND
AND fsc.STORE_NBR = r.STORE_NBR
AND fsc.MDM_PRODUCT_ID = r.MDM_PRODUCT_ID
AND fsc.FISC_DATE_LY = r.FISC_DATE_LY
LEFT OUTER JOIN
    TABLE(INSPIRE_DAILY_PRODUCT_SALES_CAL((SELECT MIN_FISCAL_WEEK_START_DT FROM date_interval), (SELECT MAX_FISCAL_WEEK_END_DT FROM date_interval))) cln
ON  cln.BRAND = r.BRAND
AND cln.STORE_NBR = r.STORE_NBR
AND cln.MDM_PRODUCT_ID = r.MDM_PRODUCT_ID
AND cln.CAL_DATE_LY = r.CAL_COMP_DATE_LY
    
';
CREATE FUNCTION IF NOT EXISTS IS_XMAS_THANKSGIVING("BUSINESS_DATE" DATE, "AGG_LEVEL" VARCHAR(16777216))
RETURNS BOOLEAN
LANGUAGE SQL
AS '

select 
    iff (
        AGG_LEVEL = ''WTD''
             , max(nvl(hol.HOLIDAY_LIST_NM IN (''THANKSGIVING DAY'',''CHRISTMAS DAY''), FALSE))
        , max(nvl(hol.HOLIDAY_LIST_NM IN (''THANKSGIVING DAY'',''CHRISTMAS DAY''), FALSE) AND DT.CALENDAR_DT = BUSINESS_DATE)
    )
from IDS_DEV.DATASTORE.DATE_DIM DT
left join IDH_DEV.SHARED.HOLIDAY_NAMES_DIM_V as hol
on DT.DATE_KEY = hol.DATE_KEY
where BUSINESS_DATE between DT.FISCAL_WEEK_START_DT and DT.FISCAL_WEEK_END_DT
and DT.CALENDAR_DT <= BUSINESS_DATE

';
CREATE FUNCTION IF NOT EXISTS PERIOD_FLASH_INIT("DATE_FROM" DATE, "DATE_TO" DATE, "TIME_INTERVAL" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "FISCAL_YEAR_NBR" NUMBER(38,0), "FISCAL_QUARTER_NBR" NUMBER(38,0), "FISCAL_PERIOD_NBR" NUMBER(38,0), "NET_SALES" NUMBER(38,2), "TRANS_CNT" NUMBER(38,0), "COMP_SALES" NUMBER(38,2), "COMP_TRANS_CNT" NUMBER(38,0), "CHANNEL_ID" VARCHAR(16777216), "OPEN_15P_FLAG" BOOLEAN, "OPEN_AFTER_HONEYMOON_FLAG" BOOLEAN, "CLOSED_BEFORE_PERIOD_END_FLAG1" BOOLEAN, "TEMP_CLOSED_FLAG1" BOOLEAN, "FISCAL_PERIOD_START_DT" DATE, "STORE_CNT" NUMBER(38,0), "COMP_STORE_CNT" NUMBER(38,0))
LANGUAGE SQL
AS '

with a as
(  
    select
        DATE_FROM,
        DATE_TO,
        TIME_INTERVAL,
        CALENDAR_DT,
        MAX_OPEN_DT,
        MAX_HONEY_DT
    FROM table(FLASH_SUMMARY_COMP_HONEYMOON(DATE_FROM, DATE_TO, TIME_INTERVAL)) as honeymoon
), chs as (
    SELECT DISTINCT CHANNEL_ID, STORE_ID, BRAND_ID
    FROM IDS_DEV.DATASTORE.DAILY_DAY_PART_FLASH_SALES_FACT as dfsf
    WHERE TIME_INTERVAL = ''CY''
),
DT as (
    SELECT
        DT.CALENDAR_DT,
        DT.DATE_KEY,
        DT.FISCAL_YEAR_NBR,
        DT.FISCAL_QUARTER_NBR,
        DT.FISCAL_PERIOD_NBR,
        DT.FISCAL_WEEK_NBR,
        DT.CALENDAR_DAY_NM,
        DT.FISCAL_WEEK_START_DT,
        MAX_OPEN_DT,
        MAX_HONEY_DT,
        DT.FISCAL_PERIOD_START_DT,
        DT.FISCAL_PERIOD_END_DT
    FROM a
    INNER join IDS_DEV.INT_REF.COMP_DATES DT
        on DT.CALENDAR_DT = a.CALENDAR_DT
        and DT.TIME_INTERVAL = TIME_INTERVAL
),
ST as (
    SELECT distinct
        DT.CALENDAR_DT,
        DT.FISCAL_YEAR_NBR,
        DT.FISCAL_QUARTER_NBR,
        DT.FISCAL_PERIOD_NBR,
        DT.FISCAL_WEEK_NBR,
        DT.CALENDAR_DAY_NM,
        DT.FISCAL_WEEK_START_DT,
        DT.DATE_KEY,
        ST.STORE_ID,
        ST.BRAND_ID,
        nvl(ST.OPEN_DT, DT.MAX_OPEN_DT) <= DT.MAX_OPEN_DT as OPEN_15P_FLAG, -- ODI-53
        nvl(ST.OPEN_DT, DT.MAX_HONEY_DT) <= DT.MAX_HONEY_DT as OPEN_AFTER_HONEYMOON_FLAG, -- ODI-199,
        chs.CHANNEL_ID,
        NVL(ST.CLOSURE_DT, DT.FISCAL_PERIOD_END_DT) < DT.FISCAL_PERIOD_END_DT as CLOSED_BEFORE_PERIOD_END_FLAG,
        (least(nvl(ST.REOPEN_DT -1,DT.FISCAL_PERIOD_END_DT), DT.FISCAL_PERIOD_END_DT)
       - greatest(nvl(ST.TEMP_CLOSED_DT,DT.FISCAL_PERIOD_START_DT), DT.FISCAL_PERIOD_START_DT) >= 6 
        and ST.TEMP_CLOSED_DT is not null) AS TEMP_CLOSED_FLAG,
        DT.FISCAL_PERIOD_START_DT
    FROM DT
    INNER JOIN IDH_DEV.SHARED.STORE_SCD_V ST  
        ON CURRENT_IND = 1 AND IFNULL(st.COUNTRY_NM, '''') in (''US'', ''USA'')
    INNER JOIN (
        select BDT.FISCAL_YEAR_START_DT
        from IDS_DEV.INT_REF.COMP_DATES BDT
        where BDT.TIME_INTERVAL = ''CAL3Y''
        and BDT.BUSINESS_DT = DATE_FROM
    ) as c3y_dt
        ON nvl(ST.CLOSURE_DT, c3y_dt.FISCAL_YEAR_START_DT) >= c3y_dt.FISCAL_YEAR_START_DT
    INNER JOIN (select distinct STORE_ID, BRAND_ID from IDS_DEV.DATASTORE.DAILY_DAY_PART_FLASH_SALES_FACT as f) as dpsf
        on ST.store_ID = dpsf.STORE_ID and ST.BRAND_ID = dpsf.BRAND_ID
    LEFT JOIN chs
        ON  chs.STORE_ID = ST.STORE_ID
        AND chs.BRAND_ID = ST.BRAND_ID
),
FINAL AS (
    SELECT
    ST.BRAND_ID
    , ST.STORE_ID
    , ST.FISCAL_YEAR_NBR as FISCAL_YEAR_NBR
    , ST.FISCAL_QUARTER_NBR as FISCAL_QUARTER_NBR
    , ST.FISCAL_PERIOD_NBR as FISCAL_PERIOD_NBR
    , sum(nvl(dpsf.NET_SALES_AMT, 0)) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,ST.FISCAL_PERIOD_NBR,
        CASE
        WHEN TIME_INTERVAL = ''CY'' THEN ST.CHANNEL_ID
        WHEN  TIME_INTERVAL <> ''CY'' THEN dpsf.CHANNEL_ID
        ELSE null END) as Net_Sales
    , sum(iff(nvl(dpsf.NET_SALES_AMT,0) = 0,0, nvl(dpsf.TRX_CNT,0))) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,
        ST.FISCAL_PERIOD_NBR,
        CASE
        WHEN TIME_INTERVAL = ''CY'' THEN ST.CHANNEL_ID
        WHEN TIME_INTERVAL <> ''CY'' THEN dpsf.CHANNEL_ID
        ELSE null END ) as Trans_Cnt
    , sum(CASE WHEN ST.FISCAL_WEEK_NBR = 53  then 0 else nvl(dpsf.NET_SALES_AMT, 0) end) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,ST.FISCAL_PERIOD_NBR,
        CASE
        WHEN TIME_INTERVAL = ''CY'' THEN ST.CHANNEL_ID
        WHEN  TIME_INTERVAL <> ''CY'' THEN dpsf.CHANNEL_ID
        ELSE null END) as Comp_Sales
    , sum(iff(nvl(dpsf.NET_SALES_AMT,0) = 0,0, CASE WHEN ST.FISCAL_WEEK_NBR = 53  then 0 else nvl(dpsf.TRX_CNT,0)end)) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,
        ST.FISCAL_PERIOD_NBR,
        CASE
        WHEN TIME_INTERVAL = ''CY'' THEN ST.CHANNEL_ID
        WHEN TIME_INTERVAL <> ''CY'' THEN dpsf.CHANNEL_ID
        ELSE null END ) as Comp_Trans_Cnt
    , CASE
        WHEN TIME_INTERVAL = ''CY'' THEN ST.CHANNEL_ID
        WHEN TIME_INTERVAL <> ''CY'' THEN dpsf.CHANNEL_ID
    ELSE null
    END AS CHANNEL_ID
    , ST.OPEN_15P_FLAG as OPEN_15P_FLAG1
    , ST.OPEN_AFTER_HONEYMOON_FLAG as OPEN_AFTER_HONEYMOON_FLAG1
    , ST.CLOSED_BEFORE_PERIOD_END_FLAG as CLOSED_BEFORE_PERIOD_END_FLAG1
    , ST.TEMP_CLOSED_FLAG as TEMP_CLOSED_FLAG1
    , ST.FISCAL_PERIOD_START_DT
    , CASE
        WHEN sum(nvl(dpsf.NET_SALES_AMT, 0)) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,ST.FISCAL_PERIOD_NBR) = 0
        THEN 0 ELSE 1 END as STORE_CNT
    , CASE
        WHEN sum(nvl(dpsf.NET_SALES_AMT, 0)) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,ST.FISCAL_PERIOD_NBR) = 0 THEN 0
        WHEN CLOSED_BEFORE_PERIOD_END_FLAG1 OR TEMP_CLOSED_FLAG1
        THEN 0
        WHEN TIME_INTERVAL = ''CY'' AND (NOT OPEN_AFTER_HONEYMOON_FLAG1 OR NOT OPEN_15P_FLAG1)
        THEN 0
        WHEN TIME_INTERVAL <> ''CY'' AND NOT OPEN_AFTER_HONEYMOON_FLAG1
        THEN 0
        ELSE 1
    END                                     as COMP_STORE_CNT
FROM
    IDS_DEV.DATASTORE.DAILY_DAY_PART_FLASH_SALES_FACT as dpsf
RIGHT JOIN ST
    ON  ST.STORE_ID = dpsf.STORE_ID
    and ST.brand_id = dpsf.brand_id
    AND ST.CALENDAR_DT = dpsf.BUSINESS_DT
AND CASE
        WHEN TIME_INTERVAL = ''CY''
        THEN nvl(dpsf.CHANNEL_ID, ST.CHANNEL_ID) = ST.CHANNEL_ID
        WHEN TIME_INTERVAL <> ''CY''
        THEN dpsf.CHANNEL_ID is not null
    ELSE true END
)
SELECT * FROM FINAL
QUALIFY ROW_NUMBER() OVER (PARTITION BY STORE_ID, BRAND_ID, FISCAL_PERIOD_NBR, CHANNEL_ID order by FISCAL_PERIOD_NBR) = 1
';
CREATE FUNCTION IF NOT EXISTS PERIOD_FLASH_INIT_OLD("DATE_FROM" DATE, "DATE_TO" DATE, "TIME_INTERVAL" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "FISCAL_YEAR_NBR" NUMBER(38,0), "FISCAL_QUARTER_NBR" NUMBER(38,0), "FISCAL_PERIOD_NBR" NUMBER(38,0), "NET_SALES" NUMBER(38,2), "TRANS_CNT" NUMBER(38,0), "COMP_SALES" NUMBER(38,2), "COMP_TRANS_CNT" NUMBER(38,0), "CHANNEL_ID" VARCHAR(16777216), "OPEN_15P_FLAG" BOOLEAN, "OPEN_AFTER_HONEYMOON_FLAG" BOOLEAN, "CLOSED_BEFORE_PERIOD_END_FLAG1" BOOLEAN, "TEMP_CLOSED_FLAG1" BOOLEAN, "FISCAL_PERIOD_START_DT" DATE, "STORE_CNT" NUMBER(38,0), "COMP_STORE_CNT" NUMBER(38,0))
LANGUAGE SQL
AS '

with a as
(  
    select
        DATE_FROM,
        DATE_TO,
        TIME_INTERVAL,
        CALENDAR_DT,
        MAX_OPEN_DT,
        MAX_HONEY_DT
    FROM table(FLASH_SUMMARY_COMP_HONEYMOON(DATE_FROM, DATE_TO, TIME_INTERVAL)) as honeymoon
), chs as (
    SELECT DISTINCT CHANNEL_ID, STORE_ID, BRAND_ID
    FROM IDS_DEV.DATASTORE.DAILY_DAY_PART_FLASH_SALES_FACT as dfsf
    WHERE TIME_INTERVAL = ''CY''
),
DT as (
    SELECT
        DT.CALENDAR_DT,
        DT.DATE_KEY,
        DT.FISCAL_YEAR_NBR,
        DT.FISCAL_QUARTER_NBR,
        DT.FISCAL_PERIOD_NBR,
        DT.FISCAL_WEEK_NBR,
        DT.CALENDAR_DAY_NM,
        DT.FISCAL_WEEK_START_DT,
        MAX_OPEN_DT,
        MAX_HONEY_DT,
        DT.FISCAL_PERIOD_START_DT,
        DT.FISCAL_PERIOD_END_DT
    FROM a
    INNER join IDS_DEV.INT_REF.COMP_DATES DT
        on DT.CALENDAR_DT = a.CALENDAR_DT
),
ST as (
    SELECT distinct
        DT.CALENDAR_DT,
        DT.FISCAL_YEAR_NBR,
        DT.FISCAL_QUARTER_NBR,
        DT.FISCAL_PERIOD_NBR,
        DT.FISCAL_WEEK_NBR,
        DT.CALENDAR_DAY_NM,
        DT.FISCAL_WEEK_START_DT,
        DT.DATE_KEY,
        ST.STORE_ID,
        ST.BRAND_ID,
        nvl(ST.OPEN_DT, DT.MAX_OPEN_DT) <= DT.MAX_OPEN_DT as OPEN_15P_FLAG, -- ODI-53
        nvl(ST.OPEN_DT, DT.MAX_HONEY_DT) <= DT.MAX_HONEY_DT as OPEN_AFTER_HONEYMOON_FLAG, -- ODI-199,
        chs.CHANNEL_ID,
        NVL(ST.CLOSURE_DT, DT.FISCAL_PERIOD_END_DT) < DT.FISCAL_PERIOD_END_DT as CLOSED_BEFORE_PERIOD_END_FLAG,
        (least(nvl(ST.REOPEN_DT -1,DT.FISCAL_PERIOD_END_DT), DT.FISCAL_PERIOD_END_DT)
       - greatest(nvl(ST.TEMP_CLOSED_DT,DT.FISCAL_PERIOD_START_DT), DT.FISCAL_PERIOD_START_DT) >= 6 
        and ST.TEMP_CLOSED_DT is not null) AS TEMP_CLOSED_FLAG,
        DT.FISCAL_PERIOD_START_DT
    FROM DT
    INNER JOIN IDH_DEV.SHARED.STORE_SCD_V ST  
        ON CURRENT_IND = 1 AND IFNULL(st.COUNTRY_NM, '''') in (''US'', ''USA'')
    INNER JOIN (
        select BDT.FISCAL_YEAR_START_DT
        from IDS_DEV.INT_REF.COMP_DATES BDT
        where BDT.TIME_INTERVAL = ''CAL3Y''
        and BDT.BUSINESS_DT = DATE_FROM
    ) as c3y_dt
        ON nvl(ST.CLOSURE_DT, c3y_dt.FISCAL_YEAR_START_DT) >= c3y_dt.FISCAL_YEAR_START_DT
    INNER JOIN (select distinct STORE_ID, BRAND_ID from IDS_DEV.DATASTORE.DAILY_DAY_PART_FLASH_SALES_FACT as f) as dpsf
        on ST.store_ID = dpsf.STORE_ID and ST.BRAND_ID = dpsf.BRAND_ID
    LEFT JOIN chs
        ON  chs.STORE_ID = ST.STORE_ID
        AND chs.BRAND_ID = ST.BRAND_ID
),
FINAL AS (
    SELECT
    ST.BRAND_ID
    , ST.STORE_ID
    , ST.FISCAL_YEAR_NBR as FISCAL_YEAR_NBR
    , ST.FISCAL_QUARTER_NBR as FISCAL_QUARTER_NBR
    , ST.FISCAL_PERIOD_NBR as FISCAL_PERIOD_NBR
    , sum(nvl(dpsf.NET_SALES_AMT, 0)) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,ST.FISCAL_PERIOD_NBR,
        CASE
        WHEN TIME_INTERVAL = ''CY'' THEN ST.CHANNEL_ID
        WHEN  TIME_INTERVAL <> ''CY'' THEN dpsf.CHANNEL_ID
        ELSE null END) as Net_Sales
    , sum(iff(nvl(dpsf.NET_SALES_AMT,0) = 0,0, nvl(dpsf.TRX_CNT,0))) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,
        ST.FISCAL_PERIOD_NBR,
        CASE
        WHEN TIME_INTERVAL = ''CY'' THEN ST.CHANNEL_ID
        WHEN TIME_INTERVAL <> ''CY'' THEN dpsf.CHANNEL_ID
        ELSE null END ) as Trans_Cnt
    , sum(CASE WHEN ST.FISCAL_WEEK_NBR = 53  then 0 else nvl(dpsf.NET_SALES_AMT, 0) end) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,ST.FISCAL_PERIOD_NBR,
        CASE
        WHEN TIME_INTERVAL = ''CY'' THEN ST.CHANNEL_ID
        WHEN  TIME_INTERVAL <> ''CY'' THEN dpsf.CHANNEL_ID
        ELSE null END) as Comp_Sales
    , sum(iff(nvl(dpsf.NET_SALES_AMT,0) = 0,0, CASE WHEN ST.FISCAL_WEEK_NBR = 53  then 0 else nvl(dpsf.TRX_CNT,0)end)) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,
        ST.FISCAL_PERIOD_NBR,
        CASE
        WHEN TIME_INTERVAL = ''CY'' THEN ST.CHANNEL_ID
        WHEN TIME_INTERVAL <> ''CY'' THEN dpsf.CHANNEL_ID
        ELSE null END ) as Comp_Trans_Cnt
    , CASE
        WHEN TIME_INTERVAL = ''CY'' THEN ST.CHANNEL_ID
        WHEN TIME_INTERVAL <> ''CY'' THEN dpsf.CHANNEL_ID
    ELSE null
    END AS CHANNEL_ID
    , ST.OPEN_15P_FLAG as OPEN_15P_FLAG1
    , ST.OPEN_AFTER_HONEYMOON_FLAG as OPEN_AFTER_HONEYMOON_FLAG1
    , ST.CLOSED_BEFORE_PERIOD_END_FLAG as CLOSED_BEFORE_PERIOD_END_FLAG1
    , ST.TEMP_CLOSED_FLAG as TEMP_CLOSED_FLAG1
    , ST.FISCAL_PERIOD_START_DT
    , CASE
        WHEN sum(nvl(dpsf.NET_SALES_AMT, 0)) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,ST.FISCAL_PERIOD_NBR) = 0
        THEN 0 ELSE 1 END as STORE_CNT
    , CASE
        WHEN sum(nvl(dpsf.NET_SALES_AMT, 0)) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,ST.FISCAL_PERIOD_NBR) = 0 THEN 0
        WHEN CLOSED_BEFORE_PERIOD_END_FLAG1 OR TEMP_CLOSED_FLAG1
        THEN 0
        WHEN TIME_INTERVAL = ''CY'' AND (NOT OPEN_AFTER_HONEYMOON_FLAG1 OR NOT OPEN_15P_FLAG1)
        THEN 0
        WHEN TIME_INTERVAL <> ''CY'' AND NOT OPEN_AFTER_HONEYMOON_FLAG1
        THEN 0
        ELSE 1
    END                                     as COMP_STORE_CNT
FROM
    IDS_DEV.DATASTORE.DAILY_DAY_PART_FLASH_SALES_FACT as dpsf
RIGHT JOIN ST
    ON  ST.STORE_ID = dpsf.STORE_ID
    and ST.brand_id = dpsf.brand_id
    AND ST.CALENDAR_DT = dpsf.BUSINESS_DT
AND CASE
        WHEN TIME_INTERVAL = ''CY''
        THEN nvl(dpsf.CHANNEL_ID, ST.CHANNEL_ID) = ST.CHANNEL_ID
        WHEN TIME_INTERVAL <> ''CY''
        THEN dpsf.CHANNEL_ID is not null
    ELSE true END
)
SELECT * FROM FINAL
QUALIFY ROW_NUMBER() OVER (PARTITION BY STORE_ID, BRAND_ID, FISCAL_PERIOD_NBR, CHANNEL_ID order by FISCAL_PERIOD_NBR) = 1
';
CREATE FUNCTION IF NOT EXISTS PERIOD_FLASH_SUMMARY("FROM_DATE" DATE, "TO_DATE" DATE)
RETURNS TABLE ("BRAND" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "STORE_NBR" VARCHAR(16777216), "STORE_STATUS_TYPE" VARCHAR(16777216), "CURRENT_OWN" VARCHAR(16777216), "OWNER_AT_SALES_TIME" VARCHAR(16777216), "ORDER_CHANNEL" VARCHAR(16777216), "NET_SALES" NUMBER(38,2), "COMP_SALES_TY_CY" NUMBER(38,2), "COMP_SALES_LY_CY" NUMBER(38,2), "COMP_SALES_TY_PY" NUMBER(38,2), "COMP_SALES_LY_PY" NUMBER(38,2), "COMP_SALES_TY_PPY" NUMBER(38,2), "COMP_SALES_LY_PPY" NUMBER(38,2), "COMP_TRANS_TY_CY" NUMBER(38,0), "COMP_TRANS_LY_CY" NUMBER(38,0), "COMP_TRANS_TY_PY" NUMBER(38,0), "COMP_TRANS_LY_PY" NUMBER(38,0), "COMP_TRANS_TY_PPY" NUMBER(38,0), "COMP_TRANS_LY_PPY" NUMBER(38,0))
LANGUAGE SQL
AS '
with comps_channel_id as (
SELECT 
    coalesce(cy.BRAND_ID, cly.BRAND_ID, c2y.BRAND_ID, c3y.BRAND_ID) as BRAND_ID
    , coalesce(cy.STORE_ID, cly.STORE_ID, c2y.STORE_ID, c3y.STORE_ID)
                                                    as STORE_NBR
    , coalesce(cy.CHANNEL_ID, cly.CHANNEL_ID, c2y.CHANNEL_ID, c3y.CHANNEL_ID)
                                                    as CHANNEL_ID
    , coalesce(cy.FISCAL_YEAR_NBR, cly.FISCAL_YEAR_NBR + 1, c2y.FISCAL_YEAR_NBR + 2, c3y.FISCAL_YEAR_NBR + 3)
                                                    as FISC_YEAR_NBR
    , coalesce(cy.FISCAL_QUARTER_NBR, cly.FISCAL_QUARTER_NBR, c2y.FISCAL_QUARTER_NBR, c3y.FISCAL_QUARTER_NBR)
                                                    as FISC_QUARTER_NBR
    , coalesce(cy.FISCAL_PERIOD_NBR, cly.FISCAL_PERIOD_NBR, c2y.FISCAL_PERIOD_NBR, c3y.FISCAL_PERIOD_NBR)
                                                    as FISCAL_PERIOD_NBR

    , cy.NET_SALES                                  as NET_SALES
    , nvl(iff(cy.COMP_STORE_CNT = 1, cy.Comp_Sales, 0),0)   as COMP_SALES_TY_CY
    , nvl(iff(cy.COMP_STORE_CNT = 1, cly.Comp_Sales, 0),0)  as  COMP_SALES_LY_CY
    , nvl(iff(cly.COMP_STORE_CNT = 1, cly.Comp_Sales, 0),0)  as  COMP_SALES_TY_PY
    , nvl(iff(cly.COMP_STORE_CNT = 1, c2y.Comp_Sales, 0),0)  as  COMP_SALES_LY_PY
    , nvl(iff(c2y.COMP_STORE_CNT = 1, c2y.Comp_Sales, 0),0)  as  COMP_SALES_TY_PPY
    , nvl(iff(c2y.COMP_STORE_CNT = 1, c3y.Comp_Sales, 0),0)  as  COMP_SALES_LY_PPY

    , nvl(iff(cy.COMP_STORE_CNT = 1, cy.Comp_Trans_Cnt, 0),0)   as COMP_TRANS_TY_CY
    , nvl(iff(cy.COMP_STORE_CNT = 1, cly.Comp_Trans_Cnt, 0),0)  as  COMP_TRANS_LY_CY
    , nvl(iff(cly.COMP_STORE_CNT = 1, cly.Comp_Trans_Cnt, 0),0)  as  COMP_TRANS_TY_PY
    , nvl(iff(cly.COMP_STORE_CNT = 1, c2y.Comp_Trans_Cnt, 0),0)  as  COMP_TRANS_LY_PY
    , nvl(iff(c2y.COMP_STORE_CNT = 1, c2y.Comp_Trans_Cnt, 0),0)  as  COMP_TRANS_TY_PPY
    , nvl(iff(c2y.COMP_STORE_CNT = 1, c3y.Comp_Trans_Cnt, 0),0)  as  COMP_TRANS_LY_PPY

FROM IDS_DEV.INT_REF.COMP_CALENDAR dt
INNER JOIN table(PERIOD_FLASH_INIT(FROM_DATE, TO_DATE,''CY'')) as cy
    on dt.CALENDAR_DT = cy.FISCAL_PERIOD_START_DT
LEFT JOIN table(PERIOD_FLASH_INIT(FROM_DATE, TO_DATE, ''CAL1Y'')) as cly
    on cly.BRAND_ID = cy.BRAND_ID
    and cly.STORE_ID = cy.STORE_ID
    and dt.CALENDAR_1YR_COMP_PERIOD_DT = cly.FISCAL_PERIOD_START_DT
    and cly.CHANNEL_ID = cy.CHANNEL_ID
LEFT JOIN table(PERIOD_FLASH_INIT(FROM_DATE, TO_DATE, ''CAL2Y'')) as c2y
    on c2y.BRAND_ID = cy.BRAND_ID
    and c2y.STORE_ID = cy.STORE_ID
    and dt.CALENDAR_2YR_COMP_PERIOD_DT = c2y.FISCAL_PERIOD_START_DT
    and c2y.CHANNEL_ID = cy.CHANNEL_ID
LEFT JOIN table(PERIOD_FLASH_INIT(FROM_DATE, TO_DATE, ''CAL3Y'')) as c3y
    on c3y.BRAND_ID = cy.BRAND_ID
    and c3y.STORE_ID = cy.STORE_ID
    and dt.CALENDAR_3YR_COMP_PERIOD_DT = c3y.FISCAL_PERIOD_START_DT
    and c3y.CHANNEL_ID = cy.CHANNEL_ID
-- TO CHECK
-- where cy.CHANNEL_ID  is not null OR cy.ADD_NULL_WEEK
--     and (
--         dt.CALENDAR_DT = cy.FISCAL_WEEK_START_DT
--         or dt.FISCAL_1YR_COMP_WEEK_DT = fly.FISCAL_WEEK_START_DT
--         or dt.CALENDAR_1YR_COMP_WEEK_DT = cly.FISCAL_WEEK_START_DT
--         or dt.CALENDAR_2YR_COMP_WEEK_DT = c2y.FISCAL_WEEK_START_DT 
--         or dt.CALENDAR_3YR_COMP_WEEK_DT = c3y.FISCAL_WEEK_START_DT
--     )
),
ch_grouped as (
select
        cci.BRAND_ID,
        cci.STORE_NBR,
        cci.FISC_YEAR_NBR,
        cci.FISC_QUARTER_NBR,
        cci.FISCAL_PERIOD_NBR,
        c_V.ORDER_CHANNEL_HIERARCHY_LEVEL3_NM as order_channel,
        sum(cci.NET_SALES) as NET_SALES,
        sum(cci.COMP_SALES_TY_CY) as COMP_SALES_TY_CY,
        sum(cci.COMP_SALES_LY_CY) as COMP_SALES_LY_CY,
        sum(cci.COMP_SALES_TY_PY) as COMP_SALES_TY_PY,
        sum(cci.COMP_SALES_LY_PY) as COMP_SALES_LY_PY,
        sum(cci.COMP_SALES_TY_PPY) as COMP_SALES_TY_PPY,
        sum(cci.COMP_SALES_LY_PPY) as COMP_SALES_LY_PPY,
        sum(cci.COMP_TRANS_TY_CY) as COMP_TRANS_TY_CY,
        sum(cci.COMP_TRANS_LY_CY) as COMP_TRANS_LY_CY,
        sum(cci.COMP_TRANS_TY_PY) as COMP_TRANS_TY_PY,
        sum(cci.COMP_TRANS_LY_PY) as COMP_TRANS_LY_PY,
        sum(cci.COMP_TRANS_TY_PPY) as COMP_TRANS_TY_PPY,
        sum(cci.COMP_TRANS_LY_PPY) as COMP_TRANS_LY_PPY

    from comps_channel_id cci
    left join (select * from ORDER_CHANNEL_V chan_V where chan_V.CHANNEL_ID is not null) c_V
    on cci.CHANNEL_ID = c_V.CHANNEL_ID
    group by 
        cci.BRAND_ID,
        cci.STORE_NBR,
        cci.FISC_YEAR_NBR,
        cci.FISC_QUARTER_NBR,
        cci.FISCAL_PERIOD_NBR,
        c_V.ORDER_CHANNEL_HIERARCHY_LEVEL3_NM
)
select 
      CASE WHEN UPPER(cg.BRAND_ID) IN (''ARG'',''ARBYS'') THEN ''ARB''
       WHEN UPPER(cg.BRAND_ID) IN (''BWW'') THEN ''BWW''
       WHEN UPPER(cg.BRAND_ID) IN (''SDI'',''SONIC'') THEN ''SON''
       WHEN UPPER(cg.BRAND_ID) IN (''JJ'') THEN ''JJ''
       WHEN UPPER(cg.BRAND_ID) IN (''DNKN'') THEN ''DUN''
       WHEN UPPER(cg.BRAND_ID) IN (''BSKN'') THEN ''BR''
       WHEN UPPER(cg.BRAND_ID) IN (''RTO'') THEN ''RT''
       ELSE ''UNKNOWN''
       END as BRAND,
       cg.FISC_YEAR_NBR,
       cg.FISC_QUARTER_NBR,
       cg.FISCAL_PERIOD_NBR,
       cg.STORE_NBR,
       re.store_status_typ,
       re.FRANCHISEE_NM AS current_owner,
       old_re.FRANCHISEE_NM as owner_at_sales_time,
       cg.order_channel,
       cg.NET_SALES,
       cg.COMP_SALES_TY_CY,
       cg.COMP_SALES_LY_CY,
       cg.COMP_SALES_TY_PY,
       cg.COMP_SALES_LY_PY,
       cg.COMP_SALES_TY_PPY,
       cg.COMP_SALES_LY_PPY,
       cg.COMP_TRANS_TY_CY,
       cg.COMP_TRANS_LY_CY,
       cg.COMP_TRANS_TY_PY,
       cg.COMP_TRANS_LY_PY,
       cg.COMP_TRANS_TY_PPY,
       cg.COMP_TRANS_LY_PPY

from ch_grouped cg
left join IDM_DEV.COREDIM.RESTAURANT_SCD_DIM re 
    on cg.brand_id = re.brand_id 
    and cg.store_nbr = re.store_id
    and re.current_ind = TRUE
left join IDM_DEV.COREDIM.RESTAURANT_SCD_DIM old_re
    on cg.brand_ID = old_re.brand_id
    and cg.store_nbr = old_re.store_id
    and TO_DATE BETWEEN old_re.EFFECTIVE_BEGIN_DT and old_re.EFFECTIVE_END_DT
';
CREATE FUNCTION IF NOT EXISTS WEEK_FLASH_INIT("DATE_FROM" DATE, "DATE_TO" DATE, "AGG_LEVEL" VARCHAR(16777216), "TIME_INTERVAL" VARCHAR(16777216))
RETURNS TABLE ("BRAND_ID" VARCHAR(16777216), "STORE_ID" VARCHAR(16777216), "BRAND_DAY_PART_NM" VARCHAR(16777216), "IRB_DAY_PART_NM" VARCHAR(16777216), "CLOSED_HR" TIME(9), "BUSINESS_DT" DATE, "FISCAL_WEEK_START_DT" DATE, "FISCAL_YEAR_NBR" NUMBER(38,0), "FISCAL_QUARTER_NBR" NUMBER(38,0), "FISCAL_PERIOD_NBR" NUMBER(38,0), "FISCAL_WEEK_NBR" NUMBER(38,0), "CALENDAR_DAY_NM" VARCHAR(16777216), "HOLIDAY_IND" NUMBER(38,0), "HOLIDAY_NM" VARCHAR(16777216), "NET_SALES" NUMBER(38,2), "TRANS_CNT" NUMBER(38,0), "DMA_NAME" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "ADDRESS_1" VARCHAR(16777216), "ADDRESS_2" VARCHAR(16777216), "CITY" VARCHAR(16777216), "ZIP_CD" VARCHAR(16777216), "WEEKDAY_OFFSET" ARRAY, "WEEK_TRANS_CNTS" ARRAY, "WEEK_NET_SALES" ARRAY, "CHANNEL_ID" VARCHAR(16777216), "OPEN_15P_FLAG" BOOLEAN, "OPEN_AFTER_HONEYMOON_FLAG" BOOLEAN, "IS_XMAS_THANKSGIVING" BOOLEAN, "STORE_CNT" NUMBER(38,0), "COMP_STORE_CNT" NUMBER(38,0), "ADD_NULL_WEEK" BOOLEAN)
LANGUAGE SQL
AS '

with a as
(  
    select
        DATE_FROM,
        DATE_TO,
        AGG_LEVEL,
        TIME_INTERVAL,
        CALENDAR_DT,
        MAX_OPEN_DT,
        MAX_HONEY_DT
    FROM table(FLASH_SUMMARY_COMP_HONEYMOON(DATE_FROM, DATE_TO, TIME_INTERVAL)) as honeymoon
), chs as (
    SELECT DISTINCT CHANNEL_ID, STORE_ID, BRAND_ID
    FROM IDS_DEV.DATASTORE.DAILY_DAY_PART_FLASH_SALES_FACT as dfsf
    WHERE TIME_INTERVAL = ''CY''
),
DT as (
    SELECT
        DT.CALENDAR_DT,
        DT.DATE_KEY,
        DT.FISCAL_YEAR_NBR,
        DT.FISCAL_QUARTER_NBR,
        DT.FISCAL_PERIOD_NBR,
        DT.FISCAL_WEEK_NBR,
        DT.CALENDAR_DAY_NM,
        DT.FISCAL_WEEK_START_DT,
        MAX_OPEN_DT,
        MAX_HONEY_DT
    FROM a
    INNER join IDH_DEV.SHARED.DATE_DIM_V DT
        on DT.CALENDAR_DT = a.CALENDAR_DT
),
OT as (
    SELECT 
        BRAND_ID,
        STORE_ID,
        OWNERSHIP_TYP,
        ST.DMA_NM,
        ST.DMA_CD,
        FISCAL_WEEK_START_DT
    FROM DT
    INNER JOIN IDH_DEV.SHARED.STORE_SCD_V ST  
        ON DT.CALENDAR_DT BETWEEN ST.EFFECTIVE_BEGIN_DT AND ST.EFFECTIVE_END_DT
        AND IFNULL(st.COUNTRY_NM, '''') in (''US'', ''USA'')
    QUALIFY ROW_NUMBER() OVER (PARTITION BY STORE_ID, BRAND_ID, FISCAL_WEEK_START_DT ORDER BY CALENDAR_DT DESC) = 1
),
ST as (
    SELECT distinct
        DT.CALENDAR_DT,
        DT.FISCAL_YEAR_NBR,
        DT.FISCAL_QUARTER_NBR,
        DT.FISCAL_PERIOD_NBR,
        DT.FISCAL_WEEK_NBR,
        DT.CALENDAR_DAY_NM,
        DT.FISCAL_WEEK_START_DT,
        DT.DATE_KEY,
        ST.STORE_ID,
        ST.BRAND_ID,
        ot.DMA_NM AS DMA_NM,
        ot.DMA_CD AS DMA_CD,
        ot.OWNERSHIP_TYP AS OWNERSHIP_TYP,
        st.STATE_NM,
        st.COUNTRY_NM,
        st.ADDRESS_1_TXT,
        st.ADDRESS_2_TXT,
        st.CITY_NM,
        st.ZIP_CD,
        nvl(ST.OPEN_DT, DT.MAX_OPEN_DT) <= DT.MAX_OPEN_DT as OPEN_15P_FLAG, -- ODI-53
        nvl(ST.OPEN_DT, DT.MAX_HONEY_DT) <= DT.MAX_HONEY_DT as OPEN_AFTER_HONEYMOON_FLAG, -- ODI-199
        null as CLOSED_HOUR,
        chs.CHANNEL_ID,
        iff(nvl(hol.HOLIDAY_IND, false), 1, 0) as HOLIDAY_IND,
        nvl(hol.HOLIDAY_LIST_NM, '''') as HOLIDAY_NM,
        nvl(
                (ARRAY_CONTAINS(cast(''THANKSGIVING DAY'' as variant), split(hol.HOLIDAY_LIST_NM, '', ''))
                 OR ARRAY_CONTAINS(cast(''CHRISTMAS DAY'' as variant), split(hol.HOLIDAY_LIST_NM, '', '')))
                , FALSE) as IS_XMAS_THANKSGIVING
    FROM DT
    INNER JOIN IDH_DEV.SHARED.STORE_SCD_V ST  
        ON CURRENT_IND = 1 AND IFNULL(st.COUNTRY_NM, '''') in (''US'', ''USA'')
    LEFT JOIN OT
        ON OT.BRAND_ID = ST.BRAND_ID
        AND OT.STORE_ID = ST.STORE_ID
        AND OT.FISCAL_WEEK_START_DT = DT.FISCAL_WEEK_START_DT
    LEFT JOIN IDH_DEV.SHARED.STORE_SCD_V STDAY  
        ON DT.CALENDAR_DT BETWEEN STDAY.EFFECTIVE_BEGIN_DT AND STDAY.EFFECTIVE_END_DT
        AND STDAY.BRAND_ID = ST.BRAND_ID
        AND STDAY.STORE_ID = ST.STORE_ID
        AND IFNULL(STDAY.COUNTRY_NM, '''') in (''US'', ''USA'')
    INNER JOIN (
        select BDT.FISCAL_YEAR_START_DT
        from IDS_DEV.INT_REF.COMP_DATES BDT
        where BDT.TIME_INTERVAL = ''CAL3Y''
        and BDT.BUSINESS_DT = DATE_FROM
    ) as c3y_dt
        ON nvl(ST.CLOSURE_DT, c3y_dt.FISCAL_YEAR_START_DT) >= c3y_dt.FISCAL_YEAR_START_DT
    INNER JOIN (select distinct STORE_ID, BRAND_ID from IDS_DEV.DATASTORE.DAILY_DAY_PART_FLASH_SALES_FACT as f) as dpsf
        on ST.store_ID = dpsf.STORE_ID and ST.BRAND_ID = dpsf.BRAND_ID
    LEFT JOIN chs
        ON  chs.STORE_ID = ST.STORE_ID
        AND chs.BRAND_ID = ST.BRAND_ID
    LEFT JOIN IDH_DEV.SHARED.HOLIDAY_LIST_V as hol
        ON DT.DATE_KEY = hol.DATE_KEY
),
FINAL AS (
    SELECT
    ST.BRAND_ID
    , ST.STORE_ID
    , dpsf.BRAND_DAY_PART_NM as BRAND_DAY_PART_NM
    , dpsf.IRB_DAY_PART_NM as IRB_DAY_PART_NM
    , null AS CLOSED_HR
    , null AS BUSINESS_DT
    , ST.FISCAL_WEEK_START_DT AS FISCAL_WEEK_START_DT
    , ST.FISCAL_YEAR_NBR as FISCAL_YEAR_NBR
    , ST.FISCAL_QUARTER_NBR as FISCAL_QUARTER_NBR
    , ST.FISCAL_PERIOD_NBR as FISCAL_PERIOD_NBR
    , ST.FISCAL_WEEK_NBR as FISCAL_WEEK_NBR
    , ST.CALENDAR_DAY_NM as CALENDAR_DAY_NM
    , NULL AS HOLIDAY_IND
    , NULL AS HOLIDAY_NM
    , sum(nvl(dpsf.NET_SALES_AMT, 0)) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,ST.FISCAL_WEEK_START_DT,
        CASE
        WHEN TIME_INTERVAL = ''CY'' THEN ST.CHANNEL_ID
        WHEN  TIME_INTERVAL <> ''CY'' THEN dpsf.CHANNEL_ID
        ELSE null END) as Net_Sales
    , sum(iff(nvl(dpsf.NET_SALES_AMT,0) = 0,0, nvl(dpsf.TRX_CNT,0))) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,
        ST.FISCAL_WEEK_START_DT,
        CASE
        WHEN TIME_INTERVAL = ''CY'' THEN ST.CHANNEL_ID
        WHEN TIME_INTERVAL <> ''CY'' THEN dpsf.CHANNEL_ID
        ELSE null END ) as Trans_Cnt
    , IFNULL(st.DMA_NM, ''UNKNOWN'') AS DMA_NAME
    , IFNULL(st.DMA_CD, ''UNKNOWN'') AS DMA_CODE
    , IFNULL(st.OWNERSHIP_TYP, ''UNKNOWN'') AS OWNERSHIP_TYP
    , IFNULL(st.STATE_NM, ''UNKNOWN'') AS STATE
    , IFNULL(st.COUNTRY_NM, ''UNKNOWN'') AS COUNTRY
    , IFNULL(st.ADDRESS_1_TXT, ''UNKNOWN'') AS ADDRESS_1
    , IFNULL(st.ADDRESS_2_TXT, ''UNKNOWN'') AS ADDRESS_2  
    , IFNULL(st.CITY_NM, ''UNKNOWN'') AS CITY
    , IFNULL(st.ZIP_CD, ''UNKNOWN'') AS ZIP_CD
    , ARRAY_AGG(ST.CALENDAR_DT - ST.FISCAL_WEEK_START_DT) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,ST.FISCAL_WEEK_START_DT) AS WEEKDAY_OFFSET --ODI-2977
    , ARRAY_AGG(dpsf.TRX_CNT) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,ST.FISCAL_WEEK_START_DT) AS WEEK_TRANS_CNTS --ODI-2977
    , ARRAY_AGG(dpsf.NET_SALES_AMT) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,ST.FISCAL_WEEK_START_DT) AS WEEK_NET_SALES --ODI-2977
    , CASE
        WHEN TIME_INTERVAL = ''CY'' THEN ST.CHANNEL_ID
        WHEN TIME_INTERVAL <> ''CY'' THEN dpsf.CHANNEL_ID
    ELSE null
    END AS CHANNEL_ID
    , ST.OPEN_15P_FLAG as OPEN_15P_FLAG1
    , ST.OPEN_AFTER_HONEYMOON_FLAG as OPEN_AFTER_HONEYMOON_FLAG1
    , MAX(ST.IS_XMAS_THANKSGIVING) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,ST.FISCAL_WEEK_START_DT) AS IS_XMAS_THANKSGIVING1
    , CASE
        WHEN sum(nvl(dpsf.NET_SALES_AMT, 0)) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,ST.FISCAL_WEEK_START_DT) = 0
        THEN 0 ELSE 1 END as STORE_CNT
    , CASE
        WHEN sum(nvl(dpsf.NET_SALES_AMT, 0)) OVER (PARTITION BY ST.BRAND_ID, ST.STORE_ID,ST.FISCAL_WEEK_START_DT) = 0 THEN 0
        WHEN TIME_INTERVAL = ''CY'' AND (NOT OPEN_AFTER_HONEYMOON_FLAG1 OR NOT OPEN_15P_FLAG1)
        THEN 0
        WHEN TIME_INTERVAL <> ''CY'' AND NOT OPEN_AFTER_HONEYMOON_FLAG1
        THEN 0
        ELSE 1
    END                                     as COMP_STORE_CNT
    , TIME_INTERVAL = ''CY''
        AND sum(1) over (PARTITION BY ST.BRAND_ID, ST.STORE_ID,ST.FISCAL_WEEK_START_DT)
                * CASE WHEN dpsf.CHANNEL_ID is null
                        THEN -1 ELSE 1 END
                = -1
    as ADD_NULL_WEEK
FROM
    (select distinct AGG_LEVEL from a) as agg
    , IDS_DEV.DATASTORE.DAILY_DAY_PART_FLASH_SALES_FACT as dpsf
RIGHT JOIN ST
    ON  ST.STORE_ID = dpsf.STORE_ID
    and ST.brand_id = dpsf.brand_id
    AND ST.CALENDAR_DT = dpsf.BUSINESS_DT
AND CASE
        WHEN TIME_INTERVAL = ''CY''
        THEN nvl(dpsf.CHANNEL_ID, ST.CHANNEL_ID) = ST.CHANNEL_ID
        WHEN TIME_INTERVAL <> ''CY''
        THEN dpsf.CHANNEL_ID is not null
    ELSE true END
)
SELECT * FROM FINAL
QUALIFY ROW_NUMBER() OVER (PARTITION BY STORE_ID, BRAND_ID, FISCAL_WEEK_START_DT, CHANNEL_ID, CLOSED_HR ORDER BY FISCAL_WEEK_START_DT) = 1
';
CREATE FUNCTION IF NOT EXISTS WEEK_FLASH_SUMMARY("FROM_DATE" DATE, "TO_DATE" DATE, "AGG_LEVEL" VARCHAR(16777216))
RETURNS TABLE ("AGG_LEVEL" VARCHAR(16777216), "BUSINESS_DATE" DATE, "WEEK_START_DT" DATE, "WEEK_END_DT" DATE, "BRAND_DAYPART" VARCHAR(16777216), "IRB_DAYPART" VARCHAR(16777216), "CLOSED_HOUR" TIME(9), "BRAND" VARCHAR(16777216), "STORE_NBR" VARCHAR(16777216), "DMA_CODE" VARCHAR(16777216), "DMA_NAME" VARCHAR(16777216), "L1NAME" VARCHAR(16777216), "L2NAME" VARCHAR(16777216), "L3NAME" VARCHAR(16777216), "L4NAME" VARCHAR(16777216), "L5NAME" VARCHAR(16777216), "OWNERSHIP_TYP" VARCHAR(16777216), "ADDRESS_1" VARCHAR(16777216), "ADDRESS_2" VARCHAR(16777216), "CITY" VARCHAR(16777216), "ZIP_CODE" VARCHAR(16777216), "STATE" VARCHAR(16777216), "COUNTRY" VARCHAR(16777216), "CHANNEL_ID" VARCHAR(16777216), "FISC_YEAR_NBR" NUMBER(38,0), "FISC_QUARTER_NBR" NUMBER(38,0), "FISC_PERIOD_NBR" NUMBER(38,0), "FISC_WEEK_NBR" NUMBER(38,0), "DAY_OF_WEEK" VARCHAR(16777216), "HOLIDAY_IND_CY" NUMBER(38,0), "HOLIDAY_NM_CY" VARCHAR(16777216), "NET_SALES_CY" NUMBER(38,2), "TRANS_CY" NUMBER(38,0), "AVG_CHECK_CY" NUMBER(38,2), "STORE_CNT_CY" NUMBER(38,0), "COMP_SALES_CY" NUMBER(38,2), "COMP_TRANS_CY" NUMBER(38,0), "COMP_AVG_CHECK_CY" NUMBER(38,2), "COMP_STORE_CNT_CY" NUMBER(38,0), "FISC_DATE_LY" DATE, "FISC_WEEK_START_DT_LY" DATE, "FISC_WEEK_END_DT_LY" DATE, "FISC_HOLIDAY_IND_LY" NUMBER(38,0), "FISC_HOLIDAY_NM_LY" VARCHAR(16777216), "FISC_NET_SALES_LY" NUMBER(38,2), "FISC_TRANS_LY" NUMBER(38,0), "FISC_AVG_CHECK_LY" NUMBER(38,2), "FISC_STORE_CNT_LY" NUMBER(38,0), "FISC_COMP_SALES_LY" NUMBER(38,2), "FISC_COMP_TRANS_LY" NUMBER(38,0), "FISC_COMP_AVG_CHECK_LY" NUMBER(38,2), "FISC_COMP_STORE_CNT_LY" NUMBER(38,0), "CAL_COMP_DATE_LY" DATE, "CAL_WEEK_START_DT_LY" DATE, "CAL_WEEK_END_DT_LY" DATE, "CAL_HOLIDAY_IND_LY" NUMBER(38,0), "CAL_HOLIDAY_NM_LY" VARCHAR(16777216), "CAL_NET_SALES_LY" NUMBER(38,2), "CAL_TRANS_LY" NUMBER(38,0), "CAL_AVG_CHECK_LY" NUMBER(38,2), "CAL_STORE_CNT_LY" NUMBER(38,0), "CAL_COMP_SALES_LY" NUMBER(38,2), "CAL_COMP_TRANS_LY" NUMBER(38,0), "CAL_COMP_AVG_CHECK_LY" NUMBER(38,2), "CAL_COMP_STORE_CNT_LY" NUMBER(38,0), "CAL_COMP_DATE_2Y" DATE, "CAL_WEEK_START_DT_2Y" DATE, "CAL_WEEK_END_DT_2Y" DATE, "CAL_HOLIDAY_IND_2Y" NUMBER(38,0), "CAL_HOLIDAY_NM_2Y" VARCHAR(16777216), "CAL_NET_SALES_2Y" NUMBER(38,2), "CAL_TRANS_2Y" NUMBER(38,0), "CAL_AVG_CHECK_2Y" NUMBER(38,2), "CAL_STORE_CNT_2Y" NUMBER(38,0), "CAL_COMP_SALES_2Y" NUMBER(38,2), "CAL_COMP_TRANS_2Y" NUMBER(38,0), "CAL_COMP_AVG_CHECK_2Y" NUMBER(38,2), "CAL_COMP_STORE_CNT_2Y" NUMBER(38,0), "CAL_COMP_DATE_3Y" DATE, "CAL_WEEK_START_DT_3Y" DATE, "CAL_WEEK_END_DT_3Y" DATE, "CAL_HOLIDAY_IND_3Y" NUMBER(38,0), "CAL_HOLIDAY_NM_3Y" VARCHAR(16777216), "CAL_NET_SALES_3Y" NUMBER(38,2), "CAL_TRANS_3Y" NUMBER(38,0), "CAL_AVG_CHECK_3Y" NUMBER(38,2), "CAL_STORE_CNT_3Y" NUMBER(38,0), "CAL_COMP_SALES_3Y" NUMBER(38,2), "CAL_COMP_TRANS_3Y" NUMBER(38,0), "CAL_COMP_AVG_CHECK_3Y" NUMBER(38,2), "CAL_COMP_STORE_CNT_3Y" NUMBER(38,0))
LANGUAGE SQL
AS '

SELECT 
    AGG_LEVEL                                       as AGG_LEVEL
    , dt.CALENDAR_DT                                as BUSINESS_DATE
    , dt.FISCAL_WEEK_START_DT                       as WEEK_START_DT
    , dt.FISCAL_WEEK_START_DT + 6                   as WEEK_END_DT
    , NULL as BRAND_DAY_PART_NM
    , NULL as IRB_DAY_PART_NM
    , NULL as CLOSED_HR
    , CASE WHEN UPPER(coalesce(cy.BRAND_ID, fly.BRAND_ID, cly.BRAND_ID, c2y.BRAND_ID, c3y.BRAND_ID)) IN (''ARG'',''ARBYS'') THEN ''ARB''
       WHEN UPPER(coalesce(cy.BRAND_ID, fly.BRAND_ID, cly.BRAND_ID, c2y.BRAND_ID, c3y.BRAND_ID)) IN (''BWW'') THEN ''BWW''
       WHEN UPPER(coalesce(cy.BRAND_ID, fly.BRAND_ID, cly.BRAND_ID, c2y.BRAND_ID, c3y.BRAND_ID)) IN (''SDI'',''SONIC'') THEN ''SON''
       WHEN UPPER(coalesce(cy.BRAND_ID, fly.BRAND_ID, cly.BRAND_ID, c2y.BRAND_ID, c3y.BRAND_ID)) IN (''JJ'') THEN ''JJ''
       WHEN UPPER(coalesce(cy.BRAND_ID, fly.BRAND_ID, cly.BRAND_ID, c2y.BRAND_ID, c3y.BRAND_ID)) IN (''DNKN'') THEN ''DUN''
       WHEN UPPER(coalesce(cy.BRAND_ID, fly.BRAND_ID, cly.BRAND_ID, c2y.BRAND_ID, c3y.BRAND_ID)) IN (''BSKN'') THEN ''BR''
       WHEN UPPER(coalesce(cy.BRAND_ID, fly.BRAND_ID, cly.BRAND_ID, c2y.BRAND_ID, c3y.BRAND_ID)) IN (''RTO'') THEN ''RT''
       ELSE ''UNKNOWN''
       END                                          as BRAND
    , coalesce(cy.STORE_ID, fly.STORE_ID, cly.STORE_ID, c2y.STORE_ID, c3y.STORE_ID)
                                                    as STORE_NBR
    , coalesce(cy.DMA_CODE, fly.DMA_CODE, cly.DMA_CODE, c2y.DMA_CODE, c3y.DMA_CODE, '''')
                                                    as DMA_CODE
    , coalesce(cy.DMA_NAME, fly.DMA_NAME, cly.DMA_NAME, c2y.DMA_NAME, c3y.DMA_NAME, '''')
                                                    as DMA_NAME
    , nvl(lv.LEVEL1_NM, '''')                         as L1Name
    , nvl(lv.LEVEL2_NM, '''')                         as L2Name
    , nvl(lv.LEVEL3_NM, '''')                         as L3Name
    , nvl(lv.LEVEL4_NM, '''')                         as L4Name
    , nvl(lv.LEVEL5_NM, '''')                         as L5Name
    , coalesce(cy.OWNERSHIP_TYP, fly.OWNERSHIP_TYP, cly.OWNERSHIP_TYP, c2y.OWNERSHIP_TYP, c3y.OWNERSHIP_TYP, '''')
                                                    as OWNERSHIP_TYP
    , coalesce(cy.ADDRESS_1, fly.ADDRESS_1, cly.ADDRESS_1, c2y.ADDRESS_1, c3y.ADDRESS_1, '''')
                                                    as ADDRESS_1
    , coalesce(cy.ADDRESS_2, fly.ADDRESS_2, cly.ADDRESS_2, c2y.ADDRESS_2, c3y.ADDRESS_2, '''')
                                                    as ADDRESS_2
    , coalesce(cy.CITY, fly.CITY, cly.CITY, c2y.CITY, c3y.CITY, '''')
                                                    as CITY
    , coalesce(cy.ZIP_CD, fly.ZIP_CD, cly.ZIP_CD, c2y.ZIP_CD, c3y.ZIP_CD, '''')
                                                    as ZIP_CODE
    , coalesce(cy.STATE, fly.STATE, cly.STATE, c2y.STATE, c3y.STATE, '''')
                                                    as STATE
    , coalesce(cy.COUNTRY, fly.COUNTRY, cly.COUNTRY, c2y.COUNTRY, c3y.COUNTRY, '''')
                                                    as COUNTRY
    , coalesce(cy.CHANNEL_ID, fly.CHANNEL_ID, cly.CHANNEL_ID, c2y.CHANNEL_ID, c3y.CHANNEL_ID)
                                                    as CHANNEL_ID

    --current year
    , coalesce(cy.FISCAL_YEAR_NBR, fly.FISCAL_YEAR_NBR + 1, cly.FISCAL_YEAR_NBR + 1, c2y.FISCAL_YEAR_NBR + 2, c3y.FISCAL_YEAR_NBR + 3)
                                                    as FISC_YEAR_NBR
    , coalesce(cy.FISCAL_QUARTER_NBR, fly.FISCAL_QUARTER_NBR, cly.FISCAL_QUARTER_NBR, c2y.FISCAL_QUARTER_NBR, c3y.FISCAL_QUARTER_NBR)
                                                    as FISC_QUARTER_NBR
    , coalesce(cy.FISCAL_PERIOD_NBR, fly.FISCAL_PERIOD_NBR, cly.FISCAL_PERIOD_NBR, c2y.FISCAL_PERIOD_NBR, c3y.FISCAL_PERIOD_NBR)
                                                    as FISCAL_PERIOD_NBR
    , coalesce(cy.FISCAL_WEEK_NBR, fly.FISCAL_WEEK_NBR, cly.FISCAL_WEEK_NBR, c2y.FISCAL_WEEK_NBR, c3y.FISCAL_WEEK_NBR)
                                                    as FISCAL_WEEK_NBR
    , coalesce(cy.CALENDAR_DAY_NM, fly.CALENDAR_DAY_NM, cly.CALENDAR_DAY_NM, c2y.CALENDAR_DAY_NM, c3y.CALENDAR_DAY_NM)
                                                    as DAY_OF_WEEK
    , nvl(cy.HOLIDAY_IND, iff(nvl(hol_cy.HOLIDAY_IND, false), 1, 0))                        as HOLIDAY_IND_CY
    , coalesce(hol_cy.HOLIDAY_LIST_NM, cy.HOLIDAY_NM, '''')                        as HOLIDAY_NM_CY
    , cy.NET_SALES                                  as NET_SALES_CY
    , cy.TRANS_CNT                                      as TRANS_CY
    , iff(cy.TRANS_CNT > 0, cy.NET_SALES/cy.TRANS_CNT, 0)   as AVG_CHECK_CY
    , cy.STORE_CNT                                  as STORE_CNT_CY
    , iff(cy.COMP_STORE_CNT = 1, cy.NET_SALES, 0)   as COMP_SALES_CY
    , iff(cy.COMP_STORE_CNT = 1, cy.TRANS_CNT, 0)   as COMP_TRANS_CY
    , iff(cy.COMP_STORE_CNT = 1 AND COMP_TRANS_CY > 0
        , COMP_SALES_CY/COMP_TRANS_CY, 0)           as COMP_AVG_CHECK_CY
    , iff(STORE_CNT_CY = 0, 0, cy.COMP_STORE_CNT)   as COMP_STORE_CNT_CY

    --fiscal last year
    , dt.FISCAL_1YR_COMP_DT                         as FISC_DATE_LY
    , dt.FISCAL_1YR_COMP_WEEK_DT                    as FISC_WEEK_START_DT_LY
    , dt.FISCAL_1YR_COMP_WEEK_DT + 6                as FISC_WEEK_END_DT_LY
    , nvl(fly.HOLIDAY_IND, iff(nvl(hol_fly.HOLIDAY_IND, false), 1, 0))                       as FISC_HOLIDAY_IND_LY
    , coalesce(hol_fly.HOLIDAY_LIST_NM, fly.HOLIDAY_NM, '''')                       as FISC_HOLIDAY_NM_LY
    , nvl(fly.NET_SALES, 0)                         as FISC_NET_SALES_LY
    , nvl(fly.TRANS_CNT, 0)                         as FISC_TRANS_LY
    , iff(fly.TRANS_CNT > 0, fly.NET_SALES/fly.TRANS_CNT, 0)
                                                    as FISC_AVG_CHECK_LY
    , fly.STORE_CNT                                 as FISC_STORE_CNT_LY
    -- Partial week is not expected case since this is going to be used only when fiscal period ends
    -- , CASE
    --     WHEN --ODI-2977
    --         TO_DATE > CURRENT_DATE
    --         AND NOT nvl(cy.IS_XMAS_THANKSGIVING, false)
    --         AND ARRAY_INTERSECTION(cy.WEEKDAY_OFFSET, fly.WEEKDAY_OFFSET) IS NOT NULL
    --         AND fly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
    --     THEN
    --         fly.NET_SALES - EXCLUDE_FROM_ARRAY(fly.WEEK_NET_SALES, cy.WEEK_NET_SALES, cy.WEEKDAY_OFFSET, fly.WEEKDAY_OFFSET)
    --     ELSE        
    --         iff(fly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
    --         , fly.NET_SALES, 0)
    --     END                                         as FISC_COMP_SALES_LY
    -- Only this is needed if we only do full periods
    ,iff(fly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
            , fly.NET_SALES, 0)
    as FISC_COMP_SALES_LY
    -- Partial week is not expected case since this is going to be used only when fiscal period ends
    -- CASE
    --     WHEN --ODI-2977
    --         AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'')
    --         AND TO_DATE > CURRENT_DATE
    --         AND NOT nvl(cy.IS_XMAS_THANKSGIVING, false)
    --         AND ARRAY_INTERSECTION(cy.WEEKDAY_OFFSET, fly.WEEKDAY_OFFSET) IS NOT NULL
    --         AND fly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
    --     THEN
    --         fly.TRANS_CNT - EXCLUDE_FROM_ARRAY(fly.WEEK_TRANS_CNTS, cy.WEEK_TRANS_CNTS, cy.WEEKDAY_OFFSET, fly.WEEKDAY_OFFSET)
    --     ELSE        
    --         iff(fly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
    --         , fly.TRANS_CNT, 0)
    --     END                                         as FISC_COMP_TRANS_LY
    -- Only this is needed if we only do full periods
    ,iff(fly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
            , fly.TRANS_CNT, 0) as FISC_COMP_TRANS_LY
    , iff(fly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1 AND FISC_COMP_TRANS_LY > 0
        , FISC_COMP_SALES_LY/FISC_COMP_TRANS_LY, 0)               as FISC_COMP_AVG_CHECK_LY
    , iff(cy.COMP_STORE_CNT = 1 and FISC_STORE_CNT_LY = 1
        , fly.COMP_STORE_CNT, 0)                    as FISC_COMP_STORE_CNT_LY

    --calendar last year
    , dt.CALENDAR_1YR_COMP_DT                       as CAL_COMP_DATE_LY
    , dt.CALENDAR_1YR_COMP_WEEK_DT                  as CAL_WEEK_START_DT_LY
    , dt.CALENDAR_1YR_COMP_WEEK_DT + 6              as CAL_WEEK_END_DT_LY
    , nvl(cly.HOLIDAY_IND, iff(nvl(hol_cly.HOLIDAY_IND, false), 1, 0))                       as CAL_HOLIDAY_IND_LY
    , coalesce(hol_cly.HOLIDAY_LIST_NM, cly.HOLIDAY_NM, '''')                       as CAL_HOLIDAY_NM_LY
    , nvl(cly.NET_SALES, 0)                         as CAL_NET_SALES_LY
    , nvl(cly.TRANS_CNT, 0)                         as CAL_TRANS_LY
    , iff(cly.TRANS_CNT > 0, cly.NET_SALES/cly.TRANS_CNT, 0)
                                                    as CAL_AVG_CHECK_LY
    , cly.STORE_CNT                                 as CAL_STORE_CNT_LY
    -- Partial week is not expected case since this is going to be used only when fiscal period ends
    -- , CASE
    --     WHEN --ODI-2977
    --         AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'')
    --         AND TO_DATE > CURRENT_DATE
    --         AND NOT nvl(cy.IS_XMAS_THANKSGIVING, false)
    --         AND ARRAY_INTERSECTION(cy.WEEKDAY_OFFSET, cly.WEEKDAY_OFFSET) IS NOT NULL
    --         AND cly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
    --     THEN
    --         cly.NET_SALES - EXCLUDE_FROM_ARRAY(cly.WEEK_NET_SALES, cy.WEEK_NET_SALES, cy.WEEKDAY_OFFSET, cly.WEEKDAY_OFFSET)
    --     ELSE        
    --         iff(cly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
    --         , cly.NET_SALES, 0)
    --     END                                         as CAL_COMP_SALES_LY
    -- Only this is needed if we only do full periods
    ,iff(cly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
            , cly.NET_SALES, 0)
     as CAL_COMP_SALES_LY
    -- Partial week is not expected case since this is going to be used only when fiscal period ends
    -- , CASE
    --     WHEN --ODI-2977
    --         AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'')
    --         AND TO_DATE > CURRENT_DATE
    --         AND NOT nvl(cy.IS_XMAS_THANKSGIVING, false)
    --         AND ARRAY_INTERSECTION(cy.WEEKDAY_OFFSET, cly.WEEKDAY_OFFSET) IS NOT NULL
    --         AND cly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
    --     THEN
    --         cly.TRANS_CNT - EXCLUDE_FROM_ARRAY(cly.WEEK_TRANS_CNTS, cy.WEEK_TRANS_CNTS, cy.WEEKDAY_OFFSET, cly.WEEKDAY_OFFSET)
    --     ELSE        
    --         iff(cly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
    --         , cly.TRANS_CNT, 0)
    --     END                                         as CAL_COMP_TRANS_LY
    -- Only this is needed if we only do full periods
    ,iff(cly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1, cly.TRANS_CNT, 0) as CAL_COMP_TRANS_LY
    , iff(cly.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1 AND CAL_COMP_TRANS_LY > 0
        , CAL_COMP_SALES_LY/CAL_COMP_TRANS_LY, 0)   as CAL_COMP_AVG_CHECK_LY
    , iff(cy.COMP_STORE_CNT = 1 and CAL_STORE_CNT_LY = 1
        , cly.COMP_STORE_CNT, 0)                    as CAL_COMP_STORE_CNT_LY

    --calendar 2 years
    , dt.CALENDAR_2YR_COMP_DT                       as CAL_COMP_DATE_2Y
    , dt.CALENDAR_2YR_COMP_WEEK_DT                  as CAL_WEEK_START_DT_2Y
    , dt.CALENDAR_2YR_COMP_WEEK_DT + 6              as CAL_WEEK_END_DT_2Y
    , nvl(c2y.HOLIDAY_IND, iff(nvl(hol_c2y.HOLIDAY_IND, false), 1, 0))                       as CAL_HOLIDAY_IND_2Y
    , coalesce(hol_c2y.HOLIDAY_LIST_NM, c2y.HOLIDAY_NM, '''')                       as CAL_HOLIDAY_NM_2Y
    , nvl(c2y.NET_SALES, 0)                         as CAL_NET_SALES_DAY_2Y
    , nvl(c2y.TRANS_CNT, 0)                         as CAL_TRANS_2Y
    , iff(c2y.TRANS_CNT > 0, c2y.NET_SALES/c2y.TRANS_CNT, 0)
                                                    as CAL_AVG_CHECK_2Y
    , c2y.STORE_CNT                                 as CAL_STORE_CNT_2Y
    -- Partial week is not expected case since this is going to be used only when fiscal period ends
    -- , CASE
    --     WHEN --ODI-2977
    --         AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'')
    --         AND TO_DATE > CURRENT_DATE
    --         AND NOT nvl(cy.IS_XMAS_THANKSGIVING, false)
    --         AND ARRAY_INTERSECTION(cy.WEEKDAY_OFFSET, c2y.WEEKDAY_OFFSET) IS NOT NULL
    --         AND c2y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
    --     THEN
    --         c2y.NET_SALES - EXCLUDE_FROM_ARRAY(c2y.WEEK_NET_SALES, cy.WEEK_NET_SALES, cy.WEEKDAY_OFFSET, c2y.WEEKDAY_OFFSET)
    --     ELSE        
    --         iff(c2y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
    --     , c2y.NET_SALES, 0)
    --     END                                         as CAL_COMP_SALES_2Y
    -- Only this is needed if we only do full periods
    , iff(c2y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1, c2y.NET_SALES, 0) as CAL_COMP_SALES_2Y
    
    -- Partial week is not expected case since this is going to be used only when fiscal period ends
    -- , CASE
    --     WHEN --ODI-2977
    --         AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'')
    --         AND TO_DATE > CURRENT_DATE
    --         AND NOT nvl(cy.IS_XMAS_THANKSGIVING, false)
    --         AND ARRAY_INTERSECTION(cy.WEEKDAY_OFFSET, c2y.WEEKDAY_OFFSET) IS NOT NULL
    --         AND c2y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
    --     THEN
    --         c2y.TRANS_CNT - EXCLUDE_FROM_ARRAY(c2y.WEEK_TRANS_CNTS, cy.WEEK_TRANS_CNTS, cy.WEEKDAY_OFFSET, c2y.WEEKDAY_OFFSET)
    --     ELSE        
    --         iff(c2y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
    --         , c2y.TRANS_CNT, 0)
    --     END                                         as CAL_COMP_TRANS_2Y
    -- Only this is needed if we only do full periods
    , iff(c2y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1, c2y.TRANS_CNT, 0) as CAL_COMP_TRANS_2Y

    , iff(c2y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1 AND CAL_COMP_TRANS_2Y > 0
        , CAL_COMP_SALES_2Y/CAL_COMP_TRANS_2Y, 0)   as CAL_COMP_AVG_CHECK_2Y
    , iff(cy.COMP_STORE_CNT = 1 and CAL_STORE_CNT_2Y = 1
        , c2y.COMP_STORE_CNT, 0)                    as CAL_COMP_STORE_CNT_2Y

    --calendar 3 years
    , dt.CALENDAR_3YR_COMP_DT                       as CAL_COMP_DATE_3Y
    , dt.CALENDAR_3YR_COMP_WEEK_DT                  as CAL_WEEK_START_DT_3Y
    , dt.CALENDAR_3YR_COMP_WEEK_DT + 6              as CAL_WEEK_END_DT_3Y
    , nvl(c3y.HOLIDAY_IND, iff(nvl(hol_c3y.HOLIDAY_IND, false), 1, 0))                       as CAL_HOLIDAY_IND_3Y
    , coalesce(hol_c3y.HOLIDAY_LIST_NM, c3y.HOLIDAY_NM, '''')                       as CAL_HOLIDAY_NM_3Y
    , nvl(c3y.NET_SALES, 0)                         as CAL_NET_SALES_DAY_3Y
    , nvl(c3y.TRANS_CNT, 0)                         as CAL_TRANS_3Y
    , iff(c3y.TRANS_CNT > 0, c3y.NET_SALES/c3y.TRANS_CNT, 0)
                                                    as CAL_AVG_CHECK_3Y
    , c3y.STORE_CNT                                 as CAL_STORE_CNT_3Y
    -- Partial week is not expected case since this is going to be used only when fiscal period ends
    -- , CASE
    --     WHEN --ODI-2977
    --         AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'')
    --         AND TO_DATE > CURRENT_DATE
    --         AND NOT nvl(cy.IS_XMAS_THANKSGIVING, false)
    --         AND ARRAY_INTERSECTION(cy.WEEKDAY_OFFSET, c3y.WEEKDAY_OFFSET) IS NOT NULL
    --         AND c3y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
    --     THEN
    --         c3y.NET_SALES - EXCLUDE_FROM_ARRAY(c3y.WEEK_NET_SALES, cy.WEEK_NET_SALES, cy.WEEKDAY_OFFSET, c3y.WEEKDAY_OFFSET)
    --     ELSE        
    --         iff(c3y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
    --         , c3y.NET_SALES, 0)
    --     END                                         as CAL_COMP_SALES_3Y
    -- Only this is needed if we only do full periods
    ,iff(c3y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1, c3y.NET_SALES, 0) as CAL_COMP_SALES_3Y
    -- Partial week is not expected case since this is going to be used only when fiscal period ends
    -- , CASE
    --     WHEN --ODI-2977
    --         AGG_LEVEL in (''WEEK'', ''WEEK_CHANNEL'')
    --         AND TO_DATE > CURRENT_DATE
    --         AND NOT nvl(cy.IS_XMAS_THANKSGIVING, false)
    --         AND ARRAY_INTERSECTION(cy.WEEKDAY_OFFSET, c3y.WEEKDAY_OFFSET) IS NOT NULL
    --         AND c3y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
    --     THEN
    --         c3y.TRANS_CNT - EXCLUDE_FROM_ARRAY(c3y.WEEK_TRANS_CNTS, cy.WEEK_TRANS_CNTS, cy.WEEKDAY_OFFSET, c3y.WEEKDAY_OFFSET)
    --     ELSE        
    --         iff(c3y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1
    --         , c3y.TRANS_CNT, 0)
    --     END                                         as CAL_COMP_TRANS_3Y
    -- Only this is needed if we only do full periods
    , iff(c3y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1, c3y.TRANS_CNT, 0) as CAL_COMP_TRANS_3Y
    , iff(c3y.COMP_STORE_CNT = 1 AND cy.COMP_STORE_CNT = 1 AND CAL_COMP_TRANS_3Y > 0
        , CAL_COMP_SALES_3Y/CAL_COMP_TRANS_3Y, 0)   as CAL_COMP_AVG_CHECK_3Y
    , iff(cy.COMP_STORE_CNT = 1 and CAL_STORE_CNT_3Y = 1
        , c3y.COMP_STORE_CNT, 0)                    as CAL_COMP_STORE_CNT_3Y
FROM IDS_DEV.INT_REF.COMP_CALENDAR dt
INNER JOIN table(WEEK_FLASH_INIT(FROM_DATE, TO_DATE, AGG_LEVEL, ''CY'')) as cy
    on dt.CALENDAR_DT = cy.FISCAL_WEEK_START_DT
LEFT JOIN table(WEEK_FLASH_INIT(FROM_DATE, TO_DATE, AGG_LEVEL, ''FISC1Y'')) as fly
    on fly.BRAND_ID = cy.BRAND_ID
    and fly.STORE_ID = cy.STORE_ID
    and dt.FISCAL_1YR_COMP_WEEK_DT = fly.FISCAL_WEEK_START_DT
    and fly.CHANNEL_ID = cy.CHANNEL_ID
LEFT JOIN table(WEEK_FLASH_INIT(FROM_DATE, TO_DATE, AGG_LEVEL, ''CAL1Y'')) as cly
    on cly.BRAND_ID = cy.BRAND_ID
    and cly.STORE_ID = cy.STORE_ID
    and dt.CALENDAR_1YR_COMP_WEEK_DT = cly.FISCAL_WEEK_START_DT
    and cly.CHANNEL_ID = cy.CHANNEL_ID
LEFT JOIN table(WEEK_FLASH_INIT(FROM_DATE, TO_DATE, AGG_LEVEL, ''CAL2Y'')) as c2y
    on c2y.BRAND_ID = cy.BRAND_ID
    and c2y.STORE_ID = cy.STORE_ID
    and dt.CALENDAR_2YR_COMP_WEEK_DT = c2y.FISCAL_WEEK_START_DT
    and c2y.CHANNEL_ID = cy.CHANNEL_ID
LEFT JOIN table(WEEK_FLASH_INIT(FROM_DATE, TO_DATE, AGG_LEVEL, ''CAL3Y'')) as c3y
    on c3y.BRAND_ID = cy.BRAND_ID
    and c3y.STORE_ID = cy.STORE_ID
    and dt.CALENDAR_3YR_COMP_WEEK_DT = c3y.FISCAL_WEEK_START_DT
    and c3y.CHANNEL_ID = cy.CHANNEL_ID
LEFT JOIN IDH_DEV.OPERATION.LOCATION_HIERARCHY_V lv 
    on lv.LOCATION_ID = coalesce(cy.STORE_ID, fly.STORE_ID, cly.STORE_ID, c2y.STORE_ID, c3y.STORE_ID)
    and lv.brand_id = coalesce(cy.BRAND_ID, fly.BRAND_ID, cly.BRAND_ID, c2y.BRAND_ID, c3y.BRAND_ID)
-- TO BE REMOVED
LEFT JOIN IDH_DEV.SHARED.HOLIDAY_LIST_V as hol_cy
    ON AGG_LEVEL IN (''DAY_PART'', ''DAY_CHANNEL'')
    AND hol_cy.DATE_KEY = replace(dt.CALENDAR_DT, ''-'', '''')
LEFT JOIN IDH_DEV.SHARED.HOLIDAY_LIST_V as hol_fly
    ON AGG_LEVEL IN (''DAY_PART'', ''DAY_CHANNEL'')
    AND hol_fly.DATE_KEY = replace(dt.FISCAL_1YR_COMP_DT, ''-'', '''')
LEFT JOIN IDH_DEV.SHARED.HOLIDAY_LIST_V as hol_cly
    ON AGG_LEVEL IN (''DAY_PART'', ''DAY_CHANNEL'')
    AND hol_cly.DATE_KEY = replace(dt.CALENDAR_1YR_COMP_DT, ''-'', '''')
LEFT JOIN IDH_DEV.SHARED.HOLIDAY_LIST_V as hol_c2y
    ON AGG_LEVEL IN (''DAY_PART'', ''DAY_CHANNEL'')
    AND hol_c2y.DATE_KEY = replace(dt.CALENDAR_2YR_COMP_DT, ''-'', '''')
LEFT JOIN IDH_DEV.SHARED.HOLIDAY_LIST_V as hol_c3y
    ON AGG_LEVEL IN (''DAY_PART'', ''DAY_CHANNEL'')
    AND hol_c3y.DATE_KEY = replace(dt.CALENDAR_3YR_COMP_DT, ''-'', '''')
-- TO BE REMOVED 
where cy.CHANNEL_ID  is not null OR cy.ADD_NULL_WEEK
    and (
        dt.CALENDAR_DT = cy.FISCAL_WEEK_START_DT
        or dt.FISCAL_1YR_COMP_WEEK_DT = fly.FISCAL_WEEK_START_DT
        or dt.CALENDAR_1YR_COMP_WEEK_DT = cly.FISCAL_WEEK_START_DT
        or dt.CALENDAR_2YR_COMP_WEEK_DT = c2y.FISCAL_WEEK_START_DT 
        or dt.CALENDAR_3YR_COMP_WEEK_DT = c3y.FISCAL_WEEK_START_DT
    )
';